	"allowed" boolean,
	"reason_code" "text",
	"reason" "text",
	"has_open_entry" boolean,
	"has_open_meal" boolean,
	"open_entry_id" "uuid",
	"open_entry_at" timestamp with time zone,
	"open_meal_id" "uuid",
	"next_expected_mark" "text",
	"labor_date" "date",
	"classification" "text",
	"approval_status" "text"
);


ALTER TYPE "public"."attendance_mark_permission" OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."checklist_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "template_id" "uuid",
    "run_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "area" "text",
    "assigned_profile_id" "uuid",
    "assigned_role" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "completed_by" "uuid",
    "total_points" integer DEFAULT 0 NOT NULL,
    "earned_points" integer DEFAULT 0 NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "supervisor_profile_id" "uuid",
    "reminder_time" time without time zone,
    "due_time" time without time zone,
    "assignment_source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "submitted_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "overdue_notified_at" timestamp with time zone,
    "original_assigned_profile_id" "uuid",
    "replacement_reason" "text",
    "replacement_notes" "text",
    "replaced_at" timestamp with time zone,
    "replaced_by" "uuid",
    "completion_timing" "text",
    "coverage_alert_notified_at" timestamp with time zone,
    "coverage_auto_applied_at" timestamp with time zone,
    "last_coverage_availability_state" "text",
    "coverage_escalated_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancelled_at" timestamp with time zone,
    "cancel_reason" "text",
    CONSTRAINT "checklist_runs_assignment_source_check" CHECK (("assignment_source" = ANY (ARRAY['manual'::"text", 'recurrence'::"text"]))),
    CONSTRAINT "checklist_runs_completion_timing_check" CHECK ((("completion_timing" IS NULL) OR ("completion_timing" = ANY (ARRAY['on_time'::"text", 'late'::"text"])))),
    CONSTRAINT "checklist_runs_replacement_reason_check" CHECK ((("replacement_reason" IS NULL) OR ("replacement_reason" = ANY (ARRAY['descanso'::"text", 'vacaciones'::"text", 'permiso'::"text", 'ausencia'::"text", 'ausencia_no_marcaje'::"text", 'emergencia'::"text", 'otro'::"text"])))),
    CONSTRAINT "checklist_runs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text", 'pending_review'::"text", 'completed'::"text", 'overdue'::"text", 'cancelled'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."checklist_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_apply_checklist_auto_coverage"("p_run_id" "uuid", "p_reference_at" timestamp with time zone DEFAULT "now"()) RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  template_row public.checklist_templates;
  coverage jsonb;
  availability_state text;
  suggested_id uuid;
  suggested_reason text;
  auto_wait integer;
  shift_start time;
  grace_minutes integer;
  auto_ready_at timestamptz;
  replacement_name text;
begin
  select * into run_row
  from public.checklist_runs
  where id = p_run_id
  for update;

  if run_row.id is null then
    return null;
  end if;

  if run_row.status in ('completed', 'cancelled') then
    return null;
  end if;

  if run_row.coverage_auto_applied_at is not null then
    return null;
  end if;

  if run_row.replaced_at is not null
    and run_row.original_assigned_profile_id is not null
    and run_row.original_assigned_profile_id <> run_row.assigned_profile_id then
    return null;
  end if;

  select * into template_row from public.checklist_templates where id = run_row.template_id;
  if coalesce(template_row.auto_coverage_enabled, false) is not true then
    return null;
  end if;

  coverage := public.get_checklist_run_coverage_context(p_run_id, p_reference_at);
  availability_state := coalesce(coverage -> 'responsible_availability' ->> 'availability_state', 'unknown');
  suggested_id := nullif(coverage ->> 'suggested_replacement_profile_id', '')::uuid;
  suggested_reason := coalesce(coverage ->> 'suggested_replacement_reason', 'ausencia');

  if suggested_id is null then
    update public.checklist_runs
    set coverage_escalated_at = coalesce(coverage_escalated_at, now()),
        last_coverage_availability_state = availability_state,
        updated_at = now()
    where id = p_run_id;
    return null;
  end if;

  if availability_state in ('approved_leave', 'official_day_off') then
    null;
  elsif availability_state = 'scheduled_not_checked_in' then
    auto_wait := coalesce(template_row.auto_coverage_wait_minutes, 20);
    grace_minutes := public.get_attendance_late_grace_minutes();
    shift_start := public._profile_earliest_shift_start(
      coalesce(run_row.original_assigned_profile_id, run_row.assigned_profile_id),
      run_row.run_date
    );
    if shift_start is not null then
      auto_ready_at := ((run_row.run_date + shift_start) at time zone 'America/Guatemala')
        + make_interval(mins => grace_minutes + auto_wait);
      if p_reference_at < auto_ready_at then
        return null;
      end if;
    end if;
  else
    return null;
  end if;

  update public.checklist_runs
  set
    original_assigned_profile_id = coalesce(original_assigned_profile_id, assigned_profile_id),
    assigned_profile_id = suggested_id,
    replacement_reason = suggested_reason,
    replacement_notes = 'Asignacion automatica por motor de cobertura',
    replaced_at = now(),
    replaced_by = null,
    coverage_auto_applied_at = now(),
    last_coverage_availability_state = availability_state,
    updated_at = now()
  where id = p_run_id
  returning * into run_row;

  insert into public.checklist_session_audit (profile_id, checklist_run_id, event_type, details)
  values (
    null,
    run_row.id,
    'run_replacement_auto',
    jsonb_build_object(
      'replacement_profile_id', suggested_id,
      'replacement_reason', suggested_reason,
      'availability_state', availability_state,
      'coverage', coverage
    )
  );

  select coalesce(full_name, username, 'Colaborador') into replacement_name
  from public.profiles where id = suggested_id;

  insert into public.notifications (
    user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
  )
  values (
    suggested_id,
    null,
    'checklist_replacement',
    'Checklist asignada automaticamente',
    coalesce(
      (select title from public.checklist_templates where id = run_row.template_id limit 1),
      'Checklist'
    ) || ' fue reasignada automaticamente. Motivo: ' || suggested_reason || '.',
    'checklist_run',
    run_row.id::text,
    '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
    null
  );

  if run_row.supervisor_profile_id is not null then
    insert into public.notifications (
      user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
    )
    values (
      run_row.supervisor_profile_id,
      null,
      'checklist_coverage',
      'Cobertura automatica aplicada',
      'Se reasigno automaticamente una checklist a ' || replacement_name || '.',
      'checklist_run',
      run_row.id::text,
      '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
      null
    );
  end if;

  return run_row;
end;
$$;


ALTER FUNCTION "public"."_apply_checklist_auto_coverage"("p_run_id" "uuid", "p_reference_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_pick_available_checklist_replacement"("p_candidate_ids" "uuid"[], "p_reference_at" timestamp with time zone DEFAULT "now"(), "p_operational_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  candidate_id uuid;
  availability jsonb;
begin
  foreach candidate_id in array coalesce(p_candidate_ids, array[]::uuid[])
  loop
    if candidate_id is null then
      continue;
    end if;
    availability := public.classify_checklist_responsible_availability(
      candidate_id,
      p_reference_at,
      p_operational_date
    );
    if coalesce(availability ->> 'availability_state', '') = 'available_present' then
      return jsonb_build_object(
        'profile_id', candidate_id,
        'availability', availability
      );
    end if;
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "public"."_pick_available_checklist_replacement"("p_candidate_ids" "uuid"[], "p_reference_at" timestamp with time zone, "p_operational_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_profile_earliest_shift_start"("p_profile_id" "uuid", "p_date" "date") RETURNS time without time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select min(s.start_time)
  from public.employee_schedules s
  left join public.shift_types st on st.id = s.shift_type_id
  where s.employee_id = p_profile_id
    and s.shift_date = p_date
    and s.status = 'published'
    and s.is_work_day = true
    and coalesce(st.is_rest_day, false) = false
    and coalesce(st.is_holiday, false) = false
    and coalesce(s.shift_type, '') not in ('rest', 'asueto')
    and s.start_time is not null;
$$;


ALTER FUNCTION "public"."_profile_earliest_shift_start"("p_profile_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_profile_has_work_schedule"("p_profile_id" "uuid", "p_date" "date") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.employee_schedules s
    left join public.shift_types st on st.id = s.shift_type_id
    where s.employee_id = p_profile_id
      and s.shift_date = p_date
      and s.status = 'published'
      and s.is_work_day = true
      and coalesce(st.is_rest_day, false) = false
      and coalesce(st.is_holiday, false) = false
      and coalesce(s.shift_type, '') not in ('rest', 'asueto')
  );
$$;


ALTER FUNCTION "public"."_profile_has_work_schedule"("p_profile_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_profile_is_checked_in"("p_profile_id" "uuid", "p_labor_date" "date", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx jsonb;
begin
  ctx := public.resolve_attendance_context(p_profile_id, 'entrada', p_at);
  if coalesce((ctx ->> 'has_open_entry')::boolean, false) then
    return true;
  end if;

  return exists (
    select 1
    from public.attendance_marks m
    where m.employee_id = p_profile_id
      and m.mark_type = 'entrada'
      and (m.marked_at at time zone 'America/Guatemala')::date = p_labor_date
  );
end;
$$;


ALTER FUNCTION "public"."_profile_is_checked_in"("p_profile_id" "uuid", "p_labor_date" "date", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_profile_schedule_unavailability"("p_profile_id" "uuid", "p_date" "date") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  weekday_int integer;
  schedule_row record;
  custom_row record;
begin
  weekday_int := extract(dow from coalesce(p_date, current_date))::integer;

  for schedule_row in
    select
      es.is_work_day,
      es.shift_type,
      coalesce(st.is_rest_day, false) as is_rest_day,
      coalesce(st.is_holiday, false) as is_holiday,
      st.name as shift_type_name
    from public.employee_schedules es
    left join public.shift_types st on st.id = es.shift_type_id
    where es.employee_id = p_profile_id
      and es.shift_date = coalesce(p_date, current_date)
      and es.status = 'published'
  loop
    if schedule_row.is_holiday
      or lower(coalesce(schedule_row.shift_type_name, '')) like '%vacac%' then
      return 'Vacaciones';
    end if;
    if not schedule_row.is_work_day
      or lower(coalesce(schedule_row.shift_type, '')) in ('rest', 'asueto')
      or schedule_row.is_rest_day then
      return 'Dia de descanso';
    end if;
  end loop;

  for custom_row in
    select
      coalesce(st.is_rest_day, false) as is_rest_day,
      coalesce(st.is_holiday, false) as is_holiday,
      st.name as shift_type_name
    from public.employee_custom_schedules ecs
    left join public.shift_types st on st.id = ecs.shift_type_id
    where ecs.profile_id = p_profile_id
      and ecs.status = 'active'
      and (
        ecs.specific_date = coalesce(p_date, current_date)
        or (
          ecs.weekday = weekday_int
          and ecs.specific_date is null
          and (ecs.start_date is null or ecs.start_date <= coalesce(p_date, current_date))
          and (ecs.end_date is null or ecs.end_date >= coalesce(p_date, current_date))
        )
        or (
          ecs.start_date is not null
          and ecs.end_date is not null
          and coalesce(p_date, current_date) between ecs.start_date and ecs.end_date
        )
      )
  loop
    if custom_row.is_holiday
      or lower(coalesce(custom_row.shift_type_name, '')) like '%vacac%' then
      return 'Vacaciones';
    end if;
    if custom_row.is_rest_day then
      return 'Dia de descanso';
    end if;
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "public"."_profile_schedule_unavailability"("p_profile_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_requisition_line_specs_from_source"("p_requisition_id" "uuid", "p_quantity_mode" "text" DEFAULT 'source_requested'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  detail public.requisition_items;
  quantity_mode text := lower(nullif(trim(p_quantity_mode), ''));
  specs jsonb := '[]'::jsonb;
  requested_qty numeric;
begin
  if p_requisition_id is null then
    raise exception 'Requisicion invalida.';
  end if;

  if quantity_mode not in ('source_requested', 'pending_only') then
    raise exception 'Modo de cantidad invalido.';
  end if;

  for detail in
    select *
    from public.requisition_items
    where requisition_id = p_requisition_id
    order by created_at asc
  loop
    if quantity_mode = 'pending_only' then
      requested_qty := greatest(
        coalesce(detail.requested_quantity, 0) - coalesce(detail.delivered_quantity, 0),
        0
      );
    else
      requested_qty := coalesce(detail.requested_quantity, 0);
    end if;

    if requested_qty <= 0 then
      continue;
    end if;

    specs := specs || jsonb_build_array(jsonb_build_object(
      'item_id', detail.item_id,
      'item_name', detail.item_name,
      'requested_quantity', requested_qty,
      'notes', detail.notes
    ));
  end loop;

  return specs;
end;
$$;


ALTER FUNCTION "public"."_requisition_line_specs_from_source"("p_requisition_id" "uuid", "p_quantity_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_low_stock_items_to_today_purchase_order"("p_requisition_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  draft_order public.purchase_orders;
  incoming_items jsonb := '[]'::jsonb;
  line jsonb;
  merged_items jsonb;
  updated_payload jsonb;
  item_id uuid;
  qty numeric;
begin
  if not public.can_operate_purchase_orders() then
    raise exception 'No tienes permiso para agregar productos a ordenes de compra.';
  end if;

  if p_requisition_id is null then
    raise exception 'Requisicion invalida.';
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Debes seleccionar al menos un producto.';
  end if;

  draft_order := public.get_or_create_today_purchase_order_draft();

  for line in select * from jsonb_array_elements(p_items)
  loop
    item_id := nullif(line ->> 'item_id', '')::uuid;
    qty := coalesce((line ->> 'suggested_quantity')::numeric, (line ->> 'quantity')::numeric);
    if item_id is null or qty is null or qty <= 0 then
      raise exception 'Cada producto debe incluir item_id y cantidad valida.';
    end if;
    incoming_items := incoming_items || jsonb_build_array(
      public.build_purchase_order_line(item_id, qty)
    );
  end loop;

  merged_items := public.merge_purchase_order_items(draft_order.data -> 'items', incoming_items);
  updated_payload := jsonb_set(draft_order.data, '{items}', merged_items, true);

  update public.purchase_orders
  set
    data = updated_payload,
    updated_at = now()
  where id = draft_order.id
  returning * into draft_order;

  for line in select * from jsonb_array_elements(p_items)
  loop
    insert into public.requisition_low_stock_suggestion_logs (
      requisition_id,
      requisition_item_id,
      item_id,
      pending_quantity,
      stock_after,
      minimum_stock,
      suggested_quantity,
      user_id,
      action,
      purchase_order_id,
      source
    ) values (
      p_requisition_id,
      nullif(line ->> 'requisition_item_id', '')::uuid,
      nullif(line ->> 'item_id', '')::uuid,
      nullif(line ->> 'pending_quantity', '')::numeric,
      nullif(line ->> 'stock_after', '')::numeric,
      nullif(line ->> 'minimum_stock', '')::numeric,
      coalesce((line ->> 'suggested_quantity')::numeric, (line ->> 'quantity')::numeric),
      auth.uid(),
      'added_to_po',
      draft_order.id,
      coalesce(nullif(line ->> 'source', ''), 'low_stock')
    );
  end loop;

  return jsonb_build_object(
    'purchase_order_id', draft_order.id,
    'order_number', draft_order.order_number,
    'status', draft_order.status,
    'items_count', jsonb_array_length(merged_items)
  );
end;
$$;


ALTER FUNCTION "public"."add_low_stock_items_to_today_purchase_order"("p_requisition_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_station_pos_order_item"("p_operator_session_token" "text", "p_order_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_notes" "text", "p_variant_id" "uuid", "p_modifier_ids" "jsonb", "p_option_selections" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_order public.pos_orders;
  v_qty numeric;
  v_pricing jsonb;
  v_item public.pos_order_items;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_qty := coalesce(p_quantity, 1);
  if v_qty <= 0 then
    raise exception 'Cantidad invalida.';
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'add_order_item',
    jsonb_build_object(
      'order_id', p_order_id,
      'product_id', p_product_id,
      'quantity', v_qty,
      'notes', coalesce(p_notes, ''),
      'variant_id', p_variant_id,
      'modifier_ids', coalesce(p_modifier_ids, '[]'::jsonb),
      'option_selections', coalesce(p_option_selections, '{}'::jsonb)
    )
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'add_order_item', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'add_order_item', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);
  v_order := public.station_pos_assert_order_open_for_drafts(p_order_id, v_operator_id);

  v_pricing := public.station_pos_compute_line_item_pricing(
    p_product_id, p_variant_id, p_modifier_ids, p_option_selections
  );

  insert into public.pos_order_items (
    order_id, product_id, product_name, quantity, unit_price, total_price,
    recipe_id, production_area_id, production_ready, is_test_item,
    notes, modifiers, selected_options,
    product_variant_id, product_variant_name, selected_size, status
  ) values (
    p_order_id,
    p_product_id,
    v_pricing ->> 'product_name',
    v_qty,
    (v_pricing ->> 'unit_price')::numeric,
    (v_pricing ->> 'unit_price')::numeric * v_qty,
    nullif(v_pricing ->> 'recipe_id', '')::uuid,
    nullif(v_pricing ->> 'production_area_id', ''),
    coalesce((v_pricing ->> 'production_ready')::boolean, false),
    coalesce((v_pricing ->> 'is_test_item')::boolean, false),
    nullif(trim(coalesce(p_notes, '')), ''),
    coalesce(v_pricing -> 'modifiers', '[]'::jsonb),
    coalesce(v_pricing -> 'selected_options', '[]'::jsonb),
    p_variant_id,
    v_pricing ->> 'product_variant_name',
    v_pricing ->> 'selected_size',
    'draft'
  )
  returning * into v_item;

  v_result := jsonb_build_object(
    'item_id', v_item.id,
    'order_id', p_order_id,
    'quantity', v_item.quantity,
    'unit_price', v_item.unit_price,
    'total_price', v_item.total_price
  );

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'add_order_item', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm in ('STATION_POS_PRICING_GAP', 'Producto no disponible.', 'Variante no disponible.',
      'Modificador invalido.', 'Opcion invalida.', 'Seleccion de opciones incompleta.',
      'Seleccion de opciones invalida.', 'Modificadores invalidos.', 'Cantidad invalida.',
      'La orden POS no existe.') then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."add_station_pos_order_item"("p_operator_session_token" "text", "p_order_id" "uuid", "p_product_id" "uuid", "p_quantity" numeric, "p_notes" "text", "p_variant_id" "uuid", "p_modifier_ids" "jsonb", "p_option_selections" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."area_inventory" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "item_id" "uuid" NOT NULL,
    "area_id" "text" NOT NULL,
    "quantity" numeric DEFAULT 0 NOT NULL,
    "minimum_quantity" numeric DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "area_inventory_minimum_quantity_check" CHECK (("minimum_quantity" >= (0)::numeric)),
    CONSTRAINT "area_inventory_quantity_check" CHECK (("quantity" >= (0)::numeric))
);


ALTER TABLE "public"."area_inventory" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_area_inventory"("p_item_id" "uuid", "p_area_id" "text", "p_quantity" numeric, "p_minimum_quantity" numeric, "p_unit" "text", "p_notes" "text") RETURNS "public"."area_inventory"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  previous_value numeric;
  adjusted public.area_inventory;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para ajustar inventario.';
  end if;
  if p_quantity < 0 or p_minimum_quantity < 0 then
    raise exception 'Las cantidades no pueden ser negativas.';
  end if;

  insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
  values (p_item_id, p_area_id, 0, 0)
  on conflict (item_id, area_id) do nothing;

  select quantity into previous_value
  from public.area_inventory
  where item_id = p_item_id and area_id = p_area_id
  for update;

  if previous_value is distinct from p_quantity and nullif(trim(p_notes), '') is null then
    raise exception 'El motivo es obligatorio para ajustar existencias.';
  end if;

  update public.area_inventory
  set quantity = p_quantity, minimum_quantity = p_minimum_quantity
  where item_id = p_item_id and area_id = p_area_id
  returning * into adjusted;

  if previous_value is distinct from p_quantity then
    insert into public.inventory_movements (
      item_id, movement_type, to_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, notes, performed_by
    )
    values (
      p_item_id, 'adjustment', p_area_id, abs(p_quantity - previous_value),
      p_unit, previous_value, p_quantity, 'manual_adjustment', p_notes, auth.uid()
    );
  end if;

  return adjusted;
end;
$$;


ALTER FUNCTION "public"."adjust_area_inventory"("p_item_id" "uuid", "p_area_id" "text", "p_quantity" numeric, "p_minimum_quantity" numeric, "p_unit" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assign_operational_station"("p_profile_id" "uuid", "p_station_id" "uuid", "p_active" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.is_operational_access_admin() then
    raise exception 'No autorizado.';
  end if;
  insert into public.operational_station_assignments (
    profile_id, station_id, active, assigned_by
  )
  values (p_profile_id, p_station_id, coalesce(p_active, true), auth.uid())
  on conflict (profile_id, station_id) do update
  set active = excluded.active,
      assigned_by = auth.uid(),
      updated_at = now();

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_assign_operational_station"("p_profile_id" "uuid", "p_station_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_operational_access_summary"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_cred public.operational_credentials;
  v_assignments jsonb;
begin
  if not public.is_operational_access_admin() then
    raise exception 'No autorizado.';
  end if;
  select * into v_cred from public.operational_credentials where profile_id = p_profile_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'station_id', a.station_id,
    'station_name', s.name,
    'station_type', s.station_type,
    'active', a.active
  )), '[]'::jsonb)
  into v_assignments
  from public.operational_station_assignments a
  join public.operational_stations s on s.id = a.station_id
  where a.profile_id = p_profile_id;

  return jsonb_build_object(
    'has_pin', v_cred.profile_id is not null and v_cred.status = 'active',
    'pin_status', coalesce(v_cred.status, 'none'),
    'assignments', v_assignments
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_operational_access_summary"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_operational_pin"("p_profile_id" "uuid", "p_pin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_pin text := trim(p_pin);
  v_lookup text;
begin
  if not public.is_operational_access_admin() then
    raise exception 'No autorizado.';
  end if;
  if v_pin !~ '^\d{4}$' then
    raise exception 'El PIN operativo debe ser exactamente 4 digitos.';
  end if;
  v_lookup := public.operational_pin_lookup(v_pin);
  if exists (
    select 1 from public.operational_credentials c
    where c.pin_lookup = v_lookup and c.profile_id <> p_profile_id
  ) then
    raise exception 'PIN operativo no disponible.';
  end if;

  insert into public.operational_credentials (
    profile_id, pin_hash, pin_lookup, status, failed_attempt_count, locked_until, updated_by
  )
  values (
    p_profile_id,
    extensions.crypt(v_pin, extensions.gen_salt('bf')),
    v_lookup,
    'active',
    0,
    null,
    auth.uid()
  )
  on conflict (profile_id) do update
  set pin_hash = excluded.pin_hash,
      pin_lookup = excluded.pin_lookup,
      status = 'active',
      failed_attempt_count = 0,
      locked_until = null,
      updated_by = auth.uid(),
      updated_at = now();

  perform public.log_operational_station_event(
    null, null, 'operational_pin_reset', auth.uid(),
    jsonb_build_object('profile_id', p_profile_id), null
  );

  return jsonb_build_object('ok', true);
end;
$_$;


ALTER FUNCTION "public"."admin_set_operational_pin"("p_profile_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."checklist_template_change_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "template_id" "uuid",
    "request_type" "text" DEFAULT 'update'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "area" "text",
    "assigned_role" "text",
    "assigned_profile_id" "uuid",
    "frequency" "text",
    "shift_context" "text",
    "status_after_approval" "text" DEFAULT 'active'::"text" NOT NULL,
    "items_snapshot" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "submitted_by" "uuid" DEFAULT "auth"."uid"(),
    "submitted_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "supervisor_profile_id" "uuid",
    "backup_profile_id" "uuid",
    "reminder_time" time without time zone,
    "due_time" time without time zone,
    "recurrence_days" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "recurrence_month_day" integer,
    "recurrence_rule" "text",
    "skip_non_work_days" boolean DEFAULT true NOT NULL,
    "auto_generate" boolean DEFAULT false NOT NULL,
    "requires_approval" boolean DEFAULT true NOT NULL,
    "primary_replacement_profile_id" "uuid",
    "secondary_replacement_profile_id" "uuid",
    "coverage_escalation_profile_id" "uuid",
    "auto_coverage_enabled" boolean DEFAULT false NOT NULL,
    "auto_coverage_wait_minutes" integer DEFAULT 20 NOT NULL,
    CONSTRAINT "checklist_template_change_requ_auto_coverage_wait_minutes_check" CHECK ((("auto_coverage_wait_minutes" >= 0) AND ("auto_coverage_wait_minutes" <= 240))),
    CONSTRAINT "checklist_template_change_requests_recurrence_month_day_check" CHECK ((("recurrence_month_day" >= 1) AND ("recurrence_month_day" <= 31))),
    CONSTRAINT "checklist_template_change_requests_request_type_check" CHECK (("request_type" = ANY (ARRAY['create'::"text", 'update'::"text", 'archive'::"text", 'delete'::"text"]))),
    CONSTRAINT "checklist_template_change_requests_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."checklist_template_change_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_checklist_change_request"("p_request_id" "uuid", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "public"."checklist_template_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request_row public.checklist_template_change_requests;
  v_template_id uuid;
begin
  if not public.is_checklist_change_approver() then
    raise exception 'No tienes permiso para aprobar cambios de checklist.';
  end if;

  select * into request_row
  from public.checklist_template_change_requests
  where id = p_request_id
  for update;

  if request_row.id is null then
    raise exception 'Solicitud no encontrada.';
  end if;
  if request_row.status <> 'pending_review' then
    raise exception 'Solo se pueden aprobar solicitudes pendientes.';
  end if;

  if request_row.request_type = 'create' then
    insert into public.checklist_templates (
      title, description, area, assigned_role, assigned_profile_id, frequency, shift_context,
      status, created_by, supervisor_profile_id, backup_profile_id,
      primary_replacement_profile_id, secondary_replacement_profile_id, coverage_escalation_profile_id,
      auto_coverage_enabled, auto_coverage_wait_minutes,
      reminder_time, due_time, recurrence_days, recurrence_month_day, recurrence_rule,
      skip_non_work_days, auto_generate, requires_approval
    )
    values (
      request_row.title, request_row.description, request_row.area, request_row.assigned_role,
      request_row.assigned_profile_id, coalesce(request_row.frequency, 'manual'),
      coalesce(request_row.shift_context, 'general'), coalesce(request_row.status_after_approval, 'active'),
      request_row.submitted_by, request_row.supervisor_profile_id, request_row.backup_profile_id,
      request_row.primary_replacement_profile_id, request_row.secondary_replacement_profile_id,
      request_row.coverage_escalation_profile_id,
      coalesce(request_row.auto_coverage_enabled, false), coalesce(request_row.auto_coverage_wait_minutes, 20),
      request_row.reminder_time, request_row.due_time, coalesce(request_row.recurrence_days, '{}'::integer[]),
      request_row.recurrence_month_day, request_row.recurrence_rule,
      coalesce(request_row.skip_non_work_days, true), coalesce(request_row.auto_generate, false),
      coalesce(request_row.requires_approval, true)
    )
    returning id into v_template_id;
  elsif request_row.request_type = 'update' then
    v_template_id := request_row.template_id;
    update public.checklist_templates
    set title = request_row.title,
        description = request_row.description,
        area = request_row.area,
        assigned_role = request_row.assigned_role,
        assigned_profile_id = request_row.assigned_profile_id,
        frequency = coalesce(request_row.frequency, 'manual'),
        shift_context = coalesce(request_row.shift_context, 'general'),
        status = coalesce(request_row.status_after_approval, 'active'),
        supervisor_profile_id = request_row.supervisor_profile_id,
        backup_profile_id = request_row.backup_profile_id,
        primary_replacement_profile_id = request_row.primary_replacement_profile_id,
        secondary_replacement_profile_id = request_row.secondary_replacement_profile_id,
        coverage_escalation_profile_id = request_row.coverage_escalation_profile_id,
        auto_coverage_enabled = coalesce(request_row.auto_coverage_enabled, false),
        auto_coverage_wait_minutes = coalesce(request_row.auto_coverage_wait_minutes, 20),
        reminder_time = request_row.reminder_time,
        due_time = request_row.due_time,
        recurrence_days = coalesce(request_row.recurrence_days, '{}'::integer[]),
        recurrence_month_day = request_row.recurrence_month_day,
        recurrence_rule = request_row.recurrence_rule,
        skip_non_work_days = coalesce(request_row.skip_non_work_days, true),
        auto_generate = coalesce(request_row.auto_generate, false),
        requires_approval = coalesce(request_row.requires_approval, true)
    where id = v_template_id;
    update public.checklist_template_items
    set is_active = false
    where template_id = v_template_id
      and is_active = true;
  elsif request_row.request_type = 'archive' then
    v_template_id := request_row.template_id;
    update public.checklist_templates set status = 'inactive' where id = v_template_id;
  elsif request_row.request_type = 'delete' then
    v_template_id := request_row.template_id;
    if exists (select 1 from public.checklist_runs where template_id = request_row.template_id) then
      update public.checklist_templates set status = 'inactive' where id = request_row.template_id;
    else
      delete from public.checklist_templates where id = request_row.template_id;
      v_template_id := null;
    end if;
  end if;

  if request_row.request_type in ('create', 'update') then
    insert into public.checklist_template_items (
      template_id, item_order, title, description, response_type, is_required,
      requires_photo, requires_comment, score_points, options, require_comment_on_no,
      require_photo_on_no, generate_incident_on_no, rule_config, is_active
    )
    select
      v_template_id,
      coalesce((item.value ->> 'item_order')::integer, item.ordinality::integer - 1),
      item.value ->> 'title',
      nullif(item.value ->> 'description', ''),
      coalesce(nullif(item.value ->> 'response_type', ''), 'yes_no'),
      coalesce((item.value ->> 'is_required')::boolean, true),
      coalesce((item.value ->> 'requires_photo')::boolean, false),
      coalesce((item.value ->> 'requires_comment')::boolean, false),
      greatest(0, coalesce((item.value ->> 'score_points')::integer, 1)),
      coalesce(item.value -> 'options', '[]'::jsonb),
      coalesce((item.value ->> 'require_comment_on_no')::boolean, false),
      coalesce((item.value ->> 'require_photo_on_no')::boolean, false),
      coalesce((item.value ->> 'generate_incident_on_no')::boolean, false),
      coalesce(item.value -> 'rule_config', '{}'::jsonb),
      true
    from jsonb_array_elements(request_row.items_snapshot) with ordinality as item(value, ordinality)
    where nullif(trim(item.value ->> 'title'), '') is not null;
  end if;

  update public.checklist_template_change_requests
  set status = 'approved',
      template_id = v_template_id,
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = nullif(trim(coalesce(p_review_notes, '')), '')
  where id = p_request_id
  returning * into request_row;

  if v_template_id is not null and request_row.request_type in ('create', 'update') then
    perform public.sync_checklist_runs_from_template(v_template_id);
  end if;

  insert into public.notifications (
    user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
  )
  values (
    request_row.submitted_by,
    null,
    'checklist_approval_result',
    'Checklist aprobada',
    'Tu checklist "' || request_row.title || '" fue aprobada. Ya puedes asignarla y utilizarla.',
    'checklist_template_change_request',
    request_row.id::text,
    '/tasks?tab=checklists&view=templates',
    auth.uid()
  );

  return request_row;
end;
$$;


ALTER FUNCTION "public"."approve_checklist_change_request"("p_request_id" "uuid", "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_checklist_run"("p_run_id" "uuid", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
begin
  select * into run_row from public.checklist_runs where id = p_run_id for update;
  if run_row.id is null then raise exception 'Checklist no encontrada.'; end if;
  if not public.is_checklist_change_approver() and coalesce(run_row.supervisor_profile_id <> auth.uid(), true) then
    raise exception 'No tienes permiso para aprobar esta checklist.';
  end if;
  if run_row.status <> 'pending_review' then raise exception 'Solo se pueden aprobar checklists en revision.'; end if;

  update public.checklist_runs
  set status = 'completed',
      completed_at = now(),
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = nullif(trim(coalesce(p_review_notes, '')), '')
  where id = p_run_id
  returning * into run_row;

  return run_row;
end;
$$;


ALTER FUNCTION "public"."approve_checklist_run"("p_run_id" "uuid", "p_review_notes" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."requisitions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "requisition_number" "text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "approved_by" "uuid",
    "completed_by" "uuid",
    "from_area_id" "text" NOT NULL,
    "to_area_id" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "notes" "text",
    "rejection_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "is_test" boolean DEFAULT false NOT NULL,
    "requested_by_profile_id" "uuid",
    "requested_by_name" "text",
    "requested_by_role" "text",
    "duplicated_from_requisition_id" "uuid",
    "template_source_requisition_id" "uuid",
    "duplication_mode" "text",
    "duplicated_at" timestamp with time zone,
    "duplicated_by" "uuid",
    "creation_source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "source_requisition_id" "uuid",
    "source_template_id" "uuid",
    "source_rule_id" "uuid",
    "generation_mode" "text",
    "generated_at" timestamp with time zone,
    "generated_by" "uuid",
    CONSTRAINT "requisitions_creation_source_check" CHECK (("creation_source" = ANY (ARRAY['manual'::"text", 'duplicate_full'::"text", 'duplicate_pending'::"text", 'template_requisition'::"text"]))),
    CONSTRAINT "requisitions_distinct_areas" CHECK (("from_area_id" <> "to_area_id")),
    CONSTRAINT "requisitions_duplication_mode_check" CHECK ((("duplication_mode" IS NULL) OR ("duplication_mode" = ANY (ARRAY['full_duplicate'::"text", 'pending_only'::"text", 'template'::"text"])))),
    CONSTRAINT "requisitions_generation_mode_check" CHECK ((("generation_mode" IS NULL) OR ("generation_mode" = ANY (ARRAY['full_duplicate'::"text", 'pending_only'::"text", 'template'::"text", 'scheduled'::"text", 'low_stock'::"text", 'ai_suggested'::"text"])))),
    CONSTRAINT "requisitions_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "requisitions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending'::"text", 'approved'::"text", 'rejected'::"text", 'completed'::"text", 'partially_fulfilled'::"text", 'pending_fulfillment'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."requisitions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."requisitions"."source_template_id" IS 'Future FK to requisition_templates.id when the catalog template module ships.';



COMMENT ON COLUMN "public"."requisitions"."source_rule_id" IS 'Future FK to requisition_recurrence_rules.id for scheduled generation.';



CREATE OR REPLACE FUNCTION "public"."approve_requisition"("p_requisition_id" "uuid", "p_items" "jsonb") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  row_data jsonb;
  approved public.requisitions;
  item_row public.requisition_items;
  approved_qty numeric;
  pending_qty numeric;
  v_shortage_reason text;
begin
  if not (public.is_profile_manager() or public.is_inventory_manager()) then
    raise exception 'No tienes permiso para aprobar requisiciones.';
  end if;

  if not exists (
    select 1 from public.requisitions
    where id = p_requisition_id and status = 'pending'
  ) then
    raise exception 'Solo se pueden aprobar requisiciones pendientes.';
  end if;

  for row_data in select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    approved_qty := coalesce((row_data ->> 'approved_quantity')::numeric, 0);
    if approved_qty < 0 then
      raise exception 'La cantidad aprobada no puede ser negativa.';
    end if;

    select * into item_row
    from public.requisition_items
    where id = (row_data ->> 'id')::uuid
      and requisition_id = p_requisition_id;

    if item_row.id is null then
      continue;
    end if;

    if approved_qty > item_row.requested_quantity then
      raise exception
        'La cantidad aprobada para % no puede superar lo solicitado (%).',
        item_row.item_name,
        item_row.requested_quantity;
    end if;

    v_shortage_reason := nullif(trim(row_data ->> 'shortage_reason'), '');
    if public.requisition_shortage_reason_required(item_row.requested_quantity, approved_qty)
       and v_shortage_reason is null then
      raise exception
        'Debes indicar el motivo del faltante para %.',
        item_row.item_name;
    end if;

    pending_qty := greatest(item_row.requested_quantity - approved_qty, 0);

    update public.requisition_items ri
    set
      approved_quantity = approved_qty,
      converted_approved_quantity = approved_qty * coalesce(ri.conversion_factor, 1),
      pending_quantity = pending_qty,
      shortage_reason = case
        when public.requisition_shortage_reason_required(ri.requested_quantity, approved_qty)
          then v_shortage_reason
        else null
      end,
      shortage_notes = nullif(trim(row_data ->> 'shortage_notes'), '')
    where ri.id = item_row.id;
  end loop;

  update public.requisition_items
  set
    approved_quantity = requested_quantity,
    converted_approved_quantity = coalesce(converted_requested_quantity, requested_quantity),
    pending_quantity = 0
  where requisition_id = p_requisition_id
    and approved_quantity is null;

  update public.requisitions
  set status = 'approved', approved_by = auth.uid(), approved_at = now()
  where id = p_requisition_id
  returning * into approved;

  return approved;
end;
$$;


ALTER FUNCTION "public"."approve_requisition"("p_requisition_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_operational_task"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
  for update;

  if not found then raise exception 'Tarea no encontrada o ya archivada.'; end if;
  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para archivar esta tarea.';
  end if;

  update public.assigned_tasks
  set archived_at = now(),
      archived_by = auth.uid(),
      updated_at = now()
  where id = p_task_id
  returning * into v_task;

  perform public.log_task_activity(
    p_task_id, 'archived', 'archived_at', null, to_jsonb(now()), '{}'::jsonb
  );

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."archive_operational_task"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_attendance_device_can_mark"("p_device_id" "text", "p_employee_id" "uuid" DEFAULT NULL::"uuid", "p_client_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  status jsonb;
begin
  status := public.get_attendance_security_status(p_device_id, p_client_ip, p_user_agent);

  if coalesce((status->>'can_mark')::boolean, false) then
    return;
  end if;

  perform public.log_attendance_security_event(
    p_device_id,
    p_employee_id,
    case
      when coalesce((status->>'require_authorized_network')::boolean, false)
        and coalesce((status->>'network_allowed')::boolean, false) = false
      then 'unauthorized_network_attempt'
      else 'unauthorized_device_attempt'
    end,
    p_client_ip,
    p_user_agent,
    status
  );

  raise exception '%', coalesce(status->>'message', 'Este dispositivo no esta autorizado para registrar asistencia.');
end;
$$;


ALTER FUNCTION "public"."assert_attendance_device_can_mark"("p_device_id" "text", "p_employee_id" "uuid", "p_client_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


