    CONSTRAINT "catering_requests_conversion_status_check" CHECK (("conversion_status" = ANY (ARRAY['lead'::"text", 'contacted'::"text", 'quoted'::"text", 'negotiating'::"text", 'approved'::"text", 'lost'::"text", 'converted'::"text"]))),
    CONSTRAINT "catering_requests_estimated_value_check" CHECK ((("estimated_value" IS NULL) OR ("estimated_value" >= (0)::numeric))),
    CONSTRAINT "catering_requests_guest_count_check" CHECK ((("guest_count" IS NULL) OR ("guest_count" >= 0))),
