COMMENT ON TABLE "public"."catering_requests" IS 'Inbound catering quote requests. Source of truth before catering_quotes / catering_events.';



COMMENT ON COLUMN "public"."catering_requests"."status" IS 'Internal operational status. Synced to conversion_status via map_catering_status_to_conversion().';



COMMENT ON COLUMN "public"."catering_requests"."source" IS 'Origin channel, e.g. wix_form, erp_manual, phone, email.';



COMMENT ON COLUMN "public"."catering_requests"."lead_source" IS 'Commercial attribution: website, phone, email, referral, manual, social, etc.';



COMMENT ON COLUMN "public"."catering_requests"."conversion_status" IS 'Commercial pipeline stage: lead -> contacted -> quoted -> negotiating -> approved|lost -> converted';



COMMENT ON COLUMN "public"."catering_requests"."win_probability" IS 'Close probability 0-100 for weighted pipeline value.';



CREATE OR REPLACE FUNCTION "public"."assign_catering_lead"("p_request_id" "uuid", "p_assigned_to" "uuid") RETURNS "public"."catering_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.catering_requests;
  v_assignee_name text;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para asignar leads de catering.';
  end if;

  if p_request_id is null or p_assigned_to is null then
    raise exception 'p_request_id y p_assigned_to son obligatorios.';
  end if;

  if not exists (
    select 1 from public.profiles profile
    where profile.id = p_assigned_to and profile.status = 'active'
  ) then
    raise exception 'El responsable asignado no existe o no esta activo.';
  end if;

  select coalesce(nullif(trim(profile.full_name), ''), profile.username, 'Colaborador')
  into v_assignee_name
  from public.profiles profile
  where profile.id = p_assigned_to;

  update public.catering_requests request
  set
    assigned_to = p_assigned_to,
    updated_by = auth.uid()
  where request.id = p_request_id
  returning * into v_row;

  if not found then
    raise exception 'Solicitud de catering no encontrada.';
  end if;

  perform public.log_catering_activity(
    v_row.id,
    'lead_assigned',
    'Asignado a ' || v_assignee_name,
    jsonb_build_object('assigned_to', p_assigned_to, 'assignee_name', v_assignee_name)
  );
  perform public.notify_catering_lead_assigned(v_row.id, p_assigned_to);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."assign_catering_lead"("p_request_id" "uuid", "p_assigned_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_checklist_run_replacement"("p_run_id" "uuid", "p_replacement_profile_id" "uuid", "p_reason" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  replacement_row public.profiles;
  original_id uuid;
  reason_value text := lower(trim(coalesce(p_reason, '')));
  notes_value text := nullif(trim(coalesce(p_notes, '')), '');
  replacement_name text;
  actor_name text;
  role_value text;
begin
  if not public.can_assign_checklist_run_replacement() then
    raise exception 'No tienes permiso para asignar reemplazos de checklist.';
  end if;

  if p_replacement_profile_id is null then
    raise exception 'Selecciona un colaborador de reemplazo.';
  end if;

  if reason_value not in (
    'descanso', 'vacaciones', 'permiso', 'ausencia', 'ausencia_no_marcaje', 'emergencia', 'otro'
  ) then
    raise exception 'Motivo de reemplazo invalido.';
  end if;

  select * into run_row
  from public.checklist_runs
  where id = p_run_id
  for update;

  if run_row.id is null then
    raise exception 'Checklist no encontrada.';
  end if;

  if run_row.status in ('completed', 'cancelled') then
    raise exception 'No se puede reasignar una checklist completada o cancelada.';
  end if;

  select * into replacement_row
  from public.profiles
  where id = p_replacement_profile_id
    and status = 'active';

  if replacement_row.id is null then
    raise exception 'Colaborador de reemplazo no encontrado o inactivo.';
  end if;

  original_id := coalesce(run_row.original_assigned_profile_id, run_row.assigned_profile_id);

  if original_id = p_replacement_profile_id then
    raise exception 'El reemplazo debe ser un colaborador distinto al responsable original.';
  end if;

  update public.checklist_runs
  set
    original_assigned_profile_id = original_id,
    assigned_profile_id = p_replacement_profile_id,
    replacement_reason = reason_value,
    replacement_notes = notes_value,
    replaced_at = now(),
    replaced_by = auth.uid(),
    updated_at = now()
  where id = p_run_id
  returning * into run_row;

  insert into public.checklist_session_audit (profile_id, checklist_run_id, event_type, details)
  values (
    auth.uid(),
    run_row.id,
    'run_replacement',
    jsonb_build_object(
      'original_assigned_profile_id', original_id,
      'replacement_profile_id', p_replacement_profile_id,
      'replacement_reason', reason_value,
      'replacement_notes', notes_value
    )
  );

  select coalesce(full_name, username, 'Colaborador') into replacement_name
  from public.profiles where id = p_replacement_profile_id;

  select coalesce(full_name, username, 'Supervisor') into actor_name
  from public.profiles where id = auth.uid();

  insert into public.notifications (
    user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
  )
  values (
    p_replacement_profile_id,
    null,
    'checklist_replacement',
    'Checklist asignada por reemplazo',
    coalesce(
      (select title from public.checklist_templates where id = run_row.template_id limit 1),
      'Checklist'
    ) || ' fue reasignada a ti. Motivo: ' || reason_value || '.',
    'checklist_run',
    run_row.id::text,
    '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
    auth.uid()
  );

  if run_row.supervisor_profile_id is not null then
    insert into public.notifications (
      user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
    )
    values (
      run_row.supervisor_profile_id,
      null,
      'checklist_replacement',
      'Reemplazo de checklist registrado',
      actor_name || ' reasigno una checklist a ' || replacement_name || ' (' || reason_value || ').',
      'checklist_run',
      run_row.id::text,
      '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
      auth.uid()
    );
  end if;

  foreach role_value in array array['admin', 'gerente_general']
  loop
    insert into public.notifications (
      user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
    )
    values (
      null,
      role_value,
      'checklist_replacement',
      'Reemplazo de checklist registrado',
      actor_name || ' reasigno una checklist a ' || replacement_name || ' (' || reason_value || ').',
      'checklist_run',
      run_row.id::text,
      '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
      auth.uid()
    );
  end loop;

  return run_row;
end;
$$;


ALTER FUNCTION "public"."assign_checklist_run_replacement"("p_run_id" "uuid", "p_replacement_profile_id" "uuid", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_late_arrivals_setup_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  has_grace_fn boolean;
  has_late_fn boolean;
  has_details_fn boolean;
begin
  select exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'get_attendance_late_grace_minutes'
  ) into has_grace_fn;

  select exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'get_attendance_daily_late_arrivals'
  ) into has_late_fn;

  select exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'get_schedule_attendance_details'
      and pg_get_function_result(p.oid) like '%attendance_status%'
  ) into has_details_fn;

  return jsonb_build_object(
    'migration_071_applied', has_grace_fn and has_late_fn,
    'get_attendance_late_grace_minutes', has_grace_fn,
    'get_attendance_daily_late_arrivals', has_late_fn,
    'get_schedule_attendance_details', has_details_fn,
    'grace_minutes', case when has_grace_fn then public.get_attendance_late_grace_minutes() else null end,
    'viewer_uid', auth.uid(),
    'viewer_can_view_reports', public.can_view_attendance_reports()
  );
end;
$$;


ALTER FUNCTION "public"."attendance_late_arrivals_setup_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_pos_catalog_schema"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'image_storage_model', 'pos_products.image_url text + storage bucket pos-product-images (no pos_product_images table)',
    'pos_products_table_exists', exists (
      select 1 from information_schema.tables
      where table_schema = 'public' and table_name = 'pos_products'
    ),
    'pos_product_images_table_exists', exists (
      select 1 from information_schema.tables
      where table_schema = 'public' and table_name = 'pos_product_images'
    ),
    'pos_products_has_image_url_column', exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'pos_products' and column_name = 'image_url'
    ),
    'storage_bucket_pos_product_images', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', b.id,
        'name', b.name,
        'public', b.public,
        'file_size_limit', b.file_size_limit
      )), '[]'::jsonb)
      from storage.buckets b
      where b.id = 'pos-product-images'
    ),
    'list_rpc_exists', exists (
      select 1 from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = 'list_pos_catalog_page'
    ),
    'get_image_rpc_exists', exists (
      select 1 from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = 'get_pos_product_image_url'
    )
  );
$$;


ALTER FUNCTION "public"."audit_pos_catalog_schema"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_pos_order_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid;
begin
  if tg_table_name = 'pos_orders' then
    if tg_op = 'INSERT' then
      v_actor := public.pos_order_event_actor_profile(
        new.id, new.owner_profile_id, new.waiter_id
      );
      insert into public.pos_order_events (order_id, event_type, description, created_by)
      values (
        new.id,
        'order_created',
        'Orden creada para ' || coalesce(new.table_name, 'mesa'),
        v_actor
      );
    elsif tg_op = 'UPDATE' and new.status is distinct from old.status then
      v_actor := public.pos_order_event_actor_profile(
        new.id, new.owner_profile_id, new.waiter_id
      );
      insert into public.pos_order_events (order_id, event_type, description, created_by)
      values (
        new.id,
        'order_' || new.status,
        'Estado de la orden actualizado a ' || new.status || '.',
        v_actor
      );
    end if;
    return new;
  end if;

  if tg_table_name = 'pos_order_items' then
    if tg_op = 'INSERT' then
      v_actor := public.pos_order_event_actor_profile(new.order_id, null, null);
      insert into public.pos_order_events (order_id, event_type, description, created_by)
      values (
        new.order_id,
        'item_added',
        new.product_name || ' agregado a la orden.',
        v_actor
      );
      return new;
    elsif tg_op = 'UPDATE' then
      v_actor := public.pos_order_event_actor_profile(new.order_id, null, null);
      if new.quantity is distinct from old.quantity then
        insert into public.pos_order_events (order_id, event_type, description, created_by)
        values (
          new.order_id,
          'item_updated',
          new.product_name || ': cantidad actualizada a ' || new.quantity::text || '.',
          v_actor
        );
      elsif new.notes is distinct from old.notes then
        insert into public.pos_order_events (order_id, event_type, description, created_by)
        values (
          new.order_id,
          'item_updated',
          new.product_name || ': notas actualizadas.',
          v_actor
        );
      end if;
      return new;
    elsif tg_op = 'DELETE' then
      v_actor := public.pos_order_event_actor_profile(old.order_id, null, null);
      insert into public.pos_order_events (order_id, event_type, description, created_by)
      values (
        old.order_id,
        'item_removed',
        old.product_name || ' eliminado de productos nuevos.',
        v_actor
      );
      return old;
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."audit_pos_order_change"() OWNER TO "postgres";


