CREATE OR REPLACE FUNCTION "public"."bakery_slugify"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select upper(
    left(
      regexp_replace(
        regexp_replace(
          translate(lower(coalesce(nullif(trim(p_text), ''), 'producto')), 'áéíóúñ ', 'aeioun_'),
          '[^a-z0-9]', '', 'g'
        ),
        '^$', 'producto'
      ),
      24
    )
  );
$_$;


