CREATE OR REPLACE FUNCTION "public"."build_purchase_order_line"("p_item_id" "uuid", "p_quantity" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item public.inventory_items;
  qty numeric;
  factor numeric;
  unit_cost numeric;
begin
  select * into item from public.inventory_items where id = p_item_id;
  if item.id is null then
    raise exception 'Producto no encontrado.';
  end if;

  qty := greatest(coalesce(p_quantity, 0), 0.001);
  factor := greatest(coalesce(nullif(item.conversion_factor, 0), 1), 0.0001);
  unit_cost := coalesce(item.purchase_price, item.cost_per_base_unit, 0);

  return jsonb_build_object(
    'id', item.id::text,
    'producto_id', item.id::text,
    'inventory_item_id', item.id::text,
    'nombre', item.name,
    'item_name', item.name,
    'sku', item.sku,
    'codigo', item.sku,
    'barcode', coalesce(item.barcode, ''),
    'cantidad_compra', qty,
    'cantidadComprar', qty,
    'unidad_compra', coalesce(nullif(trim(item.purchase_unit), ''), item.base_unit),
    'unidadCompra', coalesce(nullif(trim(item.purchase_unit), ''), item.base_unit),
    'unit', coalesce(nullif(trim(item.purchase_unit), ''), item.base_unit),
    'precio_unitario_compra', unit_cost,
    'costoUnitario', unit_cost,
    'estimated_cost', unit_cost,
    'subtotal', qty * unit_cost,
    'factor_conversion', factor,
    'unidad_base', item.base_unit,
    'cantidad_base_total', qty * factor,
    'proveedor', coalesce(item.supplier, ''),
    'image_url', coalesce(item.image_url, ''),
    'source', 'requisition_low_stock'
  );
end;
$$;


ALTER FUNCTION "public"."build_purchase_order_line"("p_item_id" "uuid", "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_cash_expected"("p_cash_session_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (
    coalesce(max(s.opening_amount), 0)
    + coalesce(sum(case when m.movement_type = 'sale_cash' then m.amount else 0 end), 0)
    + coalesce(sum(case when m.movement_type = 'deposit' then m.amount else 0 end), 0)
    - coalesce(sum(case when m.movement_type = 'withdrawal' then m.amount else 0 end), 0)
    - coalesce(sum(case when m.movement_type = 'refund' then m.amount else 0 end), 0)
    + coalesce(sum(case when m.movement_type = 'adjustment' then m.amount else 0 end), 0)
  )::numeric(12,2)
  from public.cash_sessions s
  left join public.cash_movements m on m.cash_session_id = s.id
    and m.movement_type not in ('shift_open', 'shift_close', 'manual_open')
  where s.id = p_cash_session_id;
$$;


ALTER FUNCTION "public"."calculate_cash_expected"("p_cash_session_id" "uuid") OWNER TO "postgres";


