CREATE OR REPLACE FUNCTION "public"."can_access_operational_process_run"("p_run" "public"."operational_process_runs") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    public.is_operational_process_manager()
    or (
      public.can_view_operational_process_groups()
      and exists (
        select 1
        from public.operational_process_templates t
        where t.id = p_run.process_template_id
          and (
            t.supervisor_profile_id = auth.uid()
            or public.operational_process_areas_match(
              coalesce(nullif(trim(p_run.area), ''), t.area),
              (select pr.area_name from public.profiles pr where pr.id = auth.uid())
            )
            or (
              public.normalize_profile_role(public.current_profile_role()) = 'supervisor'
              and nullif(trim(coalesce(coalesce(nullif(trim(p_run.area), ''), t.area), '')), '') is null
            )
          )
      )
    );
$$;


ALTER FUNCTION "public"."can_access_operational_process_run"("p_run" "public"."operational_process_runs") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_operational_task"("p_task" "public"."assigned_tasks", "p_intent" "text" DEFAULT 'view'::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_role text := public.normalize_profile_role(public.current_profile_role());
  actor_area text;
  task_area text;
begin
  if auth.uid() is null or p_task.id is null then
    return false;
  end if;

  if not public.is_current_profile_active() then
    return false;
  end if;

  if p_task.task_source = 'employee_expediente' then
    return auth.uid() = any (p_task.assigned_profile_ids)
      or public.is_assigned_task_manager();
  end if;

  if p_task.deleted_at is not null and actor_role <> 'admin' then
    return false;
  end if;

  if exists (
    select 1
    from public.task_assignees ta
    where ta.task_id = p_task.id
      and ta.profile_id = auth.uid()
      and ta.status = 'active'
  ) then
    return true;
  end if;

  if p_task.created_by = auth.uid() then
    return true;
  end if;

  if public.is_operational_task_executive_reader() then
    return true;
  end if;

  if public.is_assigned_task_manager() then
    if actor_role = 'supervisor' then
      return exists (
        select 1
        from public.task_assignees ta
        join public.profiles p on p.id = ta.profile_id
        where ta.task_id = p_task.id
          and ta.status = 'active'
          and p.supervisor_profile_id = auth.uid()
      ) or p_task.created_by = auth.uid();
    end if;

    if actor_role in ('recursos_humanos', 'encargado_area') then
      select coalesce(p.area_id, '') into actor_area
      from public.profiles p
      where p.id = auth.uid();
      task_area := coalesce(p_task.area_id, '');
      if actor_role = 'recursos_humanos' then
        return task_area = 'administracion'
          or coalesce(p_task.category, '') in ('Recursos Humanos', 'Capacitación');
      end if;
      return actor_area = '' or task_area = '' or actor_area = task_area;
    end if;

    return true;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."can_access_operational_task"("p_task" "public"."assigned_tasks", "p_intent" "text") OWNER TO "postgres";


