    "supervisor_profile_id" "uuid",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "frequency_type" "text" DEFAULT 'manual'::"text" NOT NULL,
    "recurrence_days" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "recurrence_month_day" integer,
    CONSTRAINT "operational_process_templates_completion_mode_check" CHECK (("completion_mode" = ANY (ARRAY['all_required'::"text", 'sequential'::"text"]))),
    CONSTRAINT "operational_process_templates_frequency_type_check" CHECK (("frequency_type" = ANY (ARRAY['manual'::"text", 'daily'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "operational_process_templates_process_type_check" CHECK (("process_type" = 'checklist_bundle'::"text")),
    CONSTRAINT "operational_process_templates_recurrence_month_day_check" CHECK ((("recurrence_month_day" IS NULL) OR (("recurrence_month_day" >= 1) AND ("recurrence_month_day" <= 31)))),
