CREATE OR REPLACE FUNCTION "public"."cancel_checklist_run_for_today"("p_run_id" "uuid", "p_cancel_reason" "text", "p_force_completed" boolean DEFAULT false) RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  previous_status text;
  actor_role text;
  template_title text;
begin
  if not public.is_checklist_library_admin() then
    raise exception 'No tienes permiso para cancelar checklists de hoy.';
  end if;

  if nullif(trim(coalesce(p_cancel_reason, '')), '') is null then
    raise exception 'El motivo de cancelacion es obligatorio.';
  end if;

  select public.normalize_profile_role(role) into actor_role
  from public.profiles
  where id = auth.uid();

  select * into run_row
  from public.checklist_runs
  where id = p_run_id
  for update;

  if run_row.id is null then
    raise exception 'Corrida no encontrada.';
  end if;

  if run_row.status = 'cancelled' then
    return run_row;
  end if;

  previous_status := run_row.status;

  if previous_status = 'completed' then
    if actor_role <> 'admin' or not coalesce(p_force_completed, false) then
      raise exception 'No se puede cancelar una checklist completada.';
    end if;
  end if;

  select title into template_title
  from public.checklist_templates
  where id = run_row.template_id;

  update public.checklist_runs
  set status = 'cancelled',
      cancelled_by = auth.uid(),
      cancelled_at = now(),
      cancel_reason = trim(p_cancel_reason),
      updated_at = now()
  where id = p_run_id
  returning * into run_row;

  insert into public.checklist_session_audit (profile_id, checklist_run_id, event_type, details)
  values (
    auth.uid(),
    run_row.id,
    'today_run_cancelled_by_admin',
    jsonb_build_object(
      'run_id', run_row.id,
      'template_id', run_row.template_id,
      'template_name', coalesce(template_title, ''),
      'cancelled_by', auth.uid(),
      'previous_status', previous_status,
      'cancel_reason', trim(p_cancel_reason),
      'timestamp', now()
    )
  );

  return run_row;
end;
$$;


ALTER FUNCTION "public"."cancel_checklist_run_for_today"("p_run_id" "uuid", "p_cancel_reason" "text", "p_force_completed" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."production_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_number" "text",
    "production_area_id" "text",
    "production_area_name" "text",
    "recipe_id" "uuid",
    "output_inventory_item_id" "uuid",
    "output_name" "text" NOT NULL,
    "output_quantity" numeric NOT NULL,
    "output_unit" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "produced_by" "uuid",
    "approved_by" "uuid",
    "notes" "text",
    "total_cost" numeric DEFAULT 0 NOT NULL,
    "unit_cost" numeric DEFAULT 0 NOT NULL,
    "expected_quantity" numeric,
    "waste_quantity" numeric DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "batch_multiplier" numeric DEFAULT 1 NOT NULL,
    "expected_output_quantity" numeric,
    "actual_output_quantity" numeric,
    "yield_quantity" numeric,
    "yield_unit" "text",
    "cost_per_batch" numeric DEFAULT 0 NOT NULL,
    "total_batch_cost" numeric DEFAULT 0 NOT NULL,
    "actual_unit_cost" numeric DEFAULT 0 NOT NULL,
    CONSTRAINT "production_batches_actual_unit_cost_check" CHECK (("actual_unit_cost" >= (0)::numeric)),
    CONSTRAINT "production_batches_batch_multiplier_check" CHECK (("batch_multiplier" > (0)::numeric)),
    CONSTRAINT "production_batches_cost_per_batch_check" CHECK (("cost_per_batch" >= (0)::numeric)),
    CONSTRAINT "production_batches_output_quantity_check" CHECK (("output_quantity" > (0)::numeric)),
    CONSTRAINT "production_batches_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'in_progress'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "production_batches_total_batch_cost_check" CHECK (("total_batch_cost" >= (0)::numeric)),
    CONSTRAINT "production_batches_total_cost_check" CHECK (("total_cost" >= (0)::numeric)),
    CONSTRAINT "production_batches_unit_cost_check" CHECK (("unit_cost" >= (0)::numeric)),
    CONSTRAINT "production_batches_waste_quantity_check" CHECK (("waste_quantity" >= (0)::numeric))
);


ALTER TABLE "public"."production_batches" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_internal_production_batch"("p_batch_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."production_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  batch public.production_batches;
begin
  select * into batch from public.production_batches where id = p_batch_id for update;
  if batch.id is null then raise exception 'La produccion no existe.'; end if;
  if batch.status = 'completed' then raise exception 'No se puede cancelar una produccion completada.'; end if;
  if not public.can_manage_internal_production() then raise exception 'No tienes permiso para cancelar producciones.'; end if;

  update public.production_batches
  set status = 'cancelled',
      notes = coalesce(nullif(trim(p_notes), ''), notes),
      updated_at = now()
  where id = p_batch_id
  returning * into batch;
  return batch;
end;
$$;


ALTER FUNCTION "public"."cancel_internal_production_batch"("p_batch_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_pos_order_draft_item"("p_item_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  cancelled public.pos_order_items;
begin
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para cancelar productos.';
  end if;
  update public.pos_order_items
  set status = 'cancelled'
  where id = p_item_id and status = 'draft'
  returning * into cancelled;
  if cancelled.id is null then
    raise exception 'Solo pueden cancelarse directamente productos nuevos.';
  end if;
  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (cancelled.order_id, 'item_cancelled', cancelled.product_name || ' cancelado.', auth.uid());
end;
$$;


ALTER FUNCTION "public"."cancel_pos_order_draft_item"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_requisition"("p_requisition_id" "uuid", "p_reason" "text") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  cancelled public.requisitions;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception 'El motivo de cancelación es obligatorio.';
  end if;
  update public.requisitions
    set status = 'cancelled', rejection_reason = trim(p_reason), cancelled_at = now()
    where id = p_requisition_id
      and status in ('draft', 'pending', 'approved')
      and (requested_by = auth.uid() or public.is_profile_manager())
    returning * into cancelled;
  if cancelled.id is null then raise exception 'No se puede cancelar esta requisición.'; end if;
  return cancelled;
end;
$$;


