CREATE OR REPLACE FUNCTION "public"."catering_quote_totals"("p_items" "jsonb", "p_discount_amount" numeric DEFAULT 0, "p_tax_rate" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_subtotal numeric(12, 2) := 0;
  v_discount numeric(12, 2) := coalesce(p_discount_amount, 0);
  v_total numeric(12, 2) := 0;
  v_item jsonb;
  v_qty numeric(12, 2);
  v_unit numeric(12, 2);
  v_line_kind text;
  v_selected boolean;
begin
  if p_items is not null and jsonb_typeof(p_items) = 'array' then
    for v_item in select value from jsonb_array_elements(p_items) as value loop
      v_line_kind := coalesce(nullif(trim(v_item ->> 'line_kind'), ''), 'normal');
      v_selected := coalesce((v_item ->> 'is_selected_option')::boolean, false);

      if v_line_kind = 'option' and not v_selected then
        continue;
      end if;

      v_qty := coalesce(nullif(v_item ->> 'quantity', '')::numeric, 0);
      v_unit := coalesce(nullif(v_item ->> 'unit_price', '')::numeric, 0);
      v_subtotal := v_subtotal + round(v_qty * v_unit, 2);
    end loop;
  end if;

  v_discount := greatest(coalesce(v_discount, 0), 0);
  v_total := round(greatest(v_subtotal - v_discount, 0), 2);

  return jsonb_build_object(
    'subtotal', v_subtotal,
    'discount_amount', v_discount,
    'tax_amount', 0,
    'tax_included', true,
    'total', v_total
  );
end;
$$;


ALTER FUNCTION "public"."catering_quote_totals"("p_items" "jsonb", "p_discount_amount" numeric, "p_tax_rate" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."catering_quote_totals"("p_items" "jsonb", "p_discount_amount" numeric, "p_tax_rate" numeric) IS 'IVA incluido en precios unitarios. total = subtotal - descuento. tax_amount siempre 0.';



