CREATE OR REPLACE FUNCTION "public"."check_login_security"("p_email" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text := lower(trim(coalesce(p_email, '')));
  v_ip text := nullif(trim(coalesce(p_ip, '')), '');
  v_email_failures integer := 0;
  v_ip_failures integer := 0;
  v_blocked boolean := false;
  v_captcha_required boolean := false;
begin
  if v_email = '' then
    return jsonb_build_object(
      'allowed', false,
      'blocked', true,
      'captcha_required', false,
      'message', 'Ingresa un correo valido.',
      'email_failures', 0,
      'ip_failures', 0
    );
  end if;

  select count(*)::integer
  into v_email_failures
  from public.security_login_attempts attempt
  where attempt.success = false
    and lower(attempt.email_attempted) = v_email
    and attempt.created_at >= now() - make_interval(mins => public.login_security_window_minutes());

  if v_ip is not null then
    select count(*)::integer
    into v_ip_failures
    from public.security_login_attempts attempt
    where attempt.success = false
      and attempt.ip_address = v_ip
      and attempt.created_at >= now() - make_interval(mins => public.login_security_window_minutes());
  end if;

  v_blocked := v_email_failures >= 5 or v_ip_failures >= 10;
  v_captcha_required := not v_blocked and v_email_failures >= 3 and v_email_failures < 5;

  return jsonb_build_object(
    'allowed', not v_blocked,
    'blocked', v_blocked,
    'captcha_required', v_captcha_required,
    'message', case
      when v_blocked then 'Demasiados intentos. Intenta de nuevo en 15 minutos.'
      when v_captcha_required then 'Completa la verificacion de seguridad para continuar.'
      else null
    end,
    'email_failures', v_email_failures,
    'ip_failures', v_ip_failures
  );
end;
$$;


ALTER FUNCTION "public"."check_login_security"("p_email" "text", "p_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_areas_match"("p_left" "text", "p_right" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select
    nullif(trim(coalesce(p_left, '')), '') is not null
    and nullif(trim(coalesce(p_right, '')), '') is not null
    and (
      lower(trim(p_left)) = lower(trim(p_right))
      or (
        lower(trim(p_left)) = 'cocina'
        and lower(trim(p_right)) like '%cocina%'
      )
      or (
        lower(trim(p_right)) = 'cocina'
        and lower(trim(p_left)) like '%cocina%'
      )
    );
$$;


ALTER FUNCTION "public"."checklist_areas_match"("p_left" "text", "p_right" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_item_failed"("p_response_type" "text", "p_expected_response" "text", "p_is_required" boolean, "p_checked" boolean, "p_response_text" "text", "p_response_number" numeric) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  expected text := lower(trim(coalesce(p_expected_response, '')));
  given text := lower(trim(coalesce(p_response_text, '')));
begin
  if p_response_type in ('checkbox', 'acknowledgement') then
    if expected in ('', 'true', 'checked', 'si', 'sí', 'yes', '1') then
      return coalesce(p_checked, false) = false;
    end if;
    if expected in ('false', 'unchecked', 'no', '0') then
      return coalesce(p_checked, false) = true;
    end if;
  end if;

  if p_response_type = 'yes_no' then
    if expected = '' then expected := 'si'; end if;
    return given <> expected;
  end if;

  if p_response_type = 'select' then
    return expected <> '' and given <> expected;
  end if;

  if p_response_type in ('number', 'temperature') then
    return coalesce(p_is_required, false) and p_response_number is null;
  end if;

  if expected <> '' then
    return given <> expected;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."checklist_item_failed"("p_response_type" "text", "p_expected_response" "text", "p_is_required" boolean, "p_checked" boolean, "p_response_text" "text", "p_response_number" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_run_answered_item_count"("p_run_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select count(*)::integer
  from public.checklist_run_items ri
  where ri.run_id = p_run_id
    and public.checklist_run_item_has_answer(ri);
$$;


