    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.checklist_run_items ri
    where ri.run_id = p_run_id
      and ri.is_required = true
      and not public.checklist_run_item_has_answer(ri)
  );
$$;


ALTER FUNCTION "public"."checklist_run_has_pending_required"("p_run_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."checklist_run_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "template_item_id" "uuid",
    "item_order" integer DEFAULT 0 NOT NULL,
    "title" "text" NOT NULL,
    "response_type" "text" DEFAULT 'checkbox'::"text" NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "requires_photo" boolean DEFAULT false NOT NULL,
    "requires_comment" boolean DEFAULT false NOT NULL,
    "checked" boolean DEFAULT false NOT NULL,
    "response_text" "text",
    "response_number" numeric,
    "photo_url" "text",
    "comment" "text",
    "score_points" integer DEFAULT 1 NOT NULL,
    "earned_points" integer DEFAULT 0 NOT NULL,
    "completed_at" timestamp with time zone,
    "completed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "options" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "response_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "response_date" "date",
    "response_time" time without time zone,
    "require_comment_on_no" boolean DEFAULT false NOT NULL,
    "require_photo_on_no" boolean DEFAULT false NOT NULL,
    "generate_incident_on_no" boolean DEFAULT false NOT NULL,
    "rule_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "expected_response" "text",
    "triggers_incident" boolean DEFAULT false NOT NULL,
    "incident_severity" "text" DEFAULT 'medium'::"text" NOT NULL,
    "notify_roles" "text"[] DEFAULT ARRAY['admin'::"text", 'gerente_general'::"text", 'gerente'::"text"] NOT NULL,
    "create_task_on_fail" boolean DEFAULT false NOT NULL,
    CONSTRAINT "checklist_run_items_incident_severity_check" CHECK (("incident_severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "checklist_run_items_response_type_check" CHECK (("response_type" = ANY (ARRAY['yes_no'::"text", 'checkbox'::"text", 'short_text'::"text", 'long_text'::"text", 'text'::"text", 'number'::"text", 'date'::"text", 'time'::"text", 'photo'::"text", 'rating'::"text", 'multi_select'::"text", 'select'::"text", 'signature'::"text", 'acknowledgement'::"text", 'temperature'::"text"]))),
    CONSTRAINT "checklist_run_items_score_points_check" CHECK (("score_points" >= 0))
);


ALTER TABLE "public"."checklist_run_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_run_item_has_answer"("p_item" "public"."checklist_run_items") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    p_item.checked
    or nullif(trim(coalesce(p_item.response_text, '')), '') is not null
    or p_item.response_number is not null
    or p_item.response_date is not null
    or p_item.response_time is not null
    or nullif(trim(coalesce(p_item.photo_url, '')), '') is not null
    or p_item.completed_at is not null
    or (p_item.response_json is not null and p_item.response_json <> '{}'::jsonb),
    false
  );
$$;


ALTER FUNCTION "public"."checklist_run_item_has_answer"("p_item" "public"."checklist_run_items") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_run_template_date_lock"("p_template_id" "uuid", "p_run_date" "date") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select pg_advisory_xact_lock(
    hashtext('checklist_run:' || p_template_id::text || '|' || p_run_date::text)
  );
$$;


ALTER FUNCTION "public"."checklist_run_template_date_lock"("p_template_id" "uuid", "p_run_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_template_due_on_date"("p_template" "public"."checklist_templates", "p_date" "date") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_template.status <> 'active' then false
    when not public.checklist_template_should_auto_generate(p_template) then false
    when coalesce(p_template.frequency, 'manual') = 'manual' then coalesce(p_template.auto_generate, false)
    when p_template.frequency = 'diaria' then true
    when p_template.frequency = 'semanal' then
      coalesce(array_length(p_template.recurrence_days, 1), 0) > 0
      and extract(isodow from p_date)::integer = any(p_template.recurrence_days)
    when p_template.frequency = 'mensual' then
      coalesce(p_template.recurrence_month_day, 1) = extract(day from p_date)::integer
    when p_template.frequency in ('apertura', 'cierre', 'por_turno') then true
    else false
  end;
$$;


ALTER FUNCTION "public"."checklist_template_due_on_date"("p_template" "public"."checklist_templates", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_template_should_auto_generate"("p_template" "public"."checklist_templates") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select
    coalesce(p_template.auto_generate, false)
    or coalesce(p_template.frequency, 'manual') in (
      'diaria', 'semanal', 'mensual', 'apertura', 'cierre', 'por_turno'
    );
$$;


ALTER FUNCTION "public"."checklist_template_should_auto_generate"("p_template" "public"."checklist_templates") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_station_enrollment"("p_token" "text", "p_claim_secret_hash" "text", "p_client_fingerprint" "text", "p_user_agent" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO '', 'extensions'
    AS $_$
declare
  v_hash text;
  v_secret_hash text;
  v_tok public.operational_station_enrollment_tokens;
  v_device public.operational_station_devices;
  v_blocked boolean;
begin
  v_secret_hash := lower(trim(p_claim_secret_hash));
  if nullif(trim(p_token), '') is null
    or v_secret_hash is null
    or length(v_secret_hash) <> 64
    or v_secret_hash !~ '^[0-9a-f]{64}$'
    or nullif(trim(p_client_fingerprint), '') is null then
    raise exception 'Solicitud invalida.';
  end if;
  v_hash := encode(extensions.digest(trim(p_token), 'sha256'), 'hex');
  select * into v_tok
  from public.operational_station_enrollment_tokens
  where token_hash = v_hash
  for update;
  if v_tok.id is null or v_tok.status in ('revoked', 'expired', 'failed', 'blocked') then
    raise exception 'Solicitud invalida.';
  end if;
  if v_tok.device_claim_locked_until is not null and v_tok.device_claim_locked_until > now() then
    raise exception 'Solicitud invalida.';
  end if;
  if v_tok.expires_at < now() then
    update public.operational_station_enrollment_tokens set status = 'expired', updated_at = now()
    where id = v_tok.id;
    raise exception 'Solicitud invalida.';
  end if;
  select exists (
    select 1 from public.operational_station_devices d
    where d.client_fingerprint = trim(p_client_fingerprint)
      and d.status = 'blocked'
  ) into v_blocked;
  if v_blocked then
    raise exception 'Solicitud invalida.';
  end if;
  if v_tok.status = 'claimed' and v_tok.claimed_fingerprint = trim(p_client_fingerprint) then
    select * into v_device from public.operational_station_devices
    where enrollment_id = v_tok.id limit 1;
    return jsonb_build_object(
      'enrollment_id', v_tok.id,
      'device_id', v_device.id,
      'confirmation_code', v_tok.confirmation_code,
      'status', 'claimed',
      'idempotent', true,
      'claim_secret_issued', false
    );
  end if;
  if v_tok.status <> 'pending' then
    raise exception 'Solicitud invalida.';
  end if;
  insert into public.operational_station_devices (
    station_id, status, enrollment_id, client_fingerprint, user_agent_summary, confirmation_code,
    claim_secret_hash, claim_secret_expires_at
  )
  values (
    v_tok.station_id, 'pending', v_tok.id, trim(p_client_fingerprint),
    left(coalesce(trim(p_user_agent), ''), 200), v_tok.confirmation_code,
    v_secret_hash, v_tok.expires_at
  )
  returning * into v_device;
  update public.operational_station_enrollment_tokens
  set status = 'claimed', claimed_at = now(), claimed_fingerprint = trim(p_client_fingerprint),
      claimed_user_agent = left(coalesce(trim(p_user_agent), ''), 500),
      device_claim_attempt_count = 0, device_claim_locked_until = null, updated_at = now()
  where id = v_tok.id;
  perform public.log_operational_station_event(
    v_tok.station_id, v_device.id, 'enrollment_claimed', null,
    jsonb_build_object('fingerprint', left(trim(p_client_fingerprint), 8)), p_idempotency_key
  );
  return jsonb_build_object(
    'enrollment_id', v_tok.id,
    'device_id', v_device.id,
    'confirmation_code', v_tok.confirmation_code,
    'status', 'claimed',
    'claim_secret_issued', true
  );
exception
  when others then
    raise exception 'Solicitud invalida.';
end;
$_$;


ALTER FUNCTION "public"."claim_station_enrollment"("p_token" "text", "p_claim_secret_hash" "text", "p_client_fingerprint" "text", "p_user_agent" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_attendance_mark"("p_employee_id" "uuid", "p_labor_date" "date", "p_mark_type" "text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'America/Guatemala';
  v_mark_type text := lower(trim(coalesce(p_mark_type, 'entrada')));
  v_work record;
  v_any_schedule boolean;
  v_rest_only boolean;
  v_exception_id uuid;
  v_grace integer;
  v_shift_start_ts timestamptz;
  v_shift_end_ts timestamptz;
  v_early_minutes integer;
  v_late_minutes integer;
  v_open_entry public.attendance_marks;
begin
  if v_mark_type = 'salida' then v_mark_type := 'salida_final'; end if;

  if v_mark_type <> 'entrada' then
    select m.* into v_open_entry
    from public.attendance_marks m
    where m.employee_id = p_employee_id
      and m.mark_type = 'entrada'
      and not exists (
        select 1
        from public.attendance_marks out_mark
        where out_mark.employee_id = m.employee_id
          and out_mark.mark_type in ('salida_final', 'salida')
          and out_mark.marked_at > m.marked_at
      )
    order by m.marked_at desc
    limit 1;

    if v_open_entry.id is not null then
      return jsonb_build_object(
        'classification', coalesce(v_open_entry.classification, 'normal'),
        'approval_status', coalesce(v_open_entry.approval_status, 'not_required'),
        'schedule_exception_id', v_open_entry.schedule_exception_id,
        'system_reason', coalesce(v_open_entry.system_reason, 'Marcación de cierre vinculada a la entrada activa.'),
        'schedule_id', null,
        'schedule_status', null,
        'reason_code', coalesce(v_open_entry.classification, 'normal')
      );
    end if;
  end if;

  v_exception_id := public.find_attendance_schedule_exception(p_employee_id, p_labor_date, p_at);
  if v_exception_id is not null then
    return jsonb_build_object(
      'classification', 'authorized_overtime',
      'approval_status', 'approved',
      'schedule_exception_id', v_exception_id,
      'system_reason', 'Excepción de horario / tiempo extraordinario autorizado.',
      'schedule_id', null,
      'schedule_status', null,
      'reason_code', 'authorized_overtime'
    );
  end if;

  select exists (
    select 1
    from public.employee_schedules s
    where s.employee_id = p_employee_id
      and s.shift_date = p_labor_date
      and s.status in ('draft', 'published')
  ) into v_any_schedule;

  if not v_any_schedule then
    return jsonb_build_object(
      'classification', 'no_schedule',
      'approval_status', 'pending',
      'schedule_exception_id', null,
      'system_reason', 'Sin horario asignado para esta fecha.',
      'schedule_id', null,
      'schedule_status', null,
      'reason_code', 'no_schedule'
    );
  end if;

  select
    s.id,
    s.status,
    s.is_work_day,
    s.start_time,
    s.end_time
  into v_work
  from public.employee_schedules s
  left join public.shift_types st on st.id = s.shift_type_id
  where s.employee_id = p_employee_id
    and s.shift_date = p_labor_date
    and s.status in ('draft', 'published')
    and s.is_work_day = true
    and coalesce(st.is_rest_day, false) = false
    and coalesce(st.is_holiday, false) = false
    and coalesce(s.shift_type, '') not in ('rest', 'asueto')
  order by case s.status when 'published' then 0 else 1 end, s.block_order, s.start_time
  limit 1;

  if v_work.id is null then
    select not exists (
      select 1
      from public.employee_schedules s
      left join public.shift_types st on st.id = s.shift_type_id
      where s.employee_id = p_employee_id
        and s.shift_date = p_labor_date
        and s.status in ('draft', 'published')
        and s.is_work_day = true
        and coalesce(st.is_rest_day, false) = false
        and coalesce(st.is_holiday, false) = false
        and coalesce(s.shift_type, '') not in ('rest', 'asueto')
    ) into v_rest_only;

    if v_rest_only then
      return jsonb_build_object(
        'classification', 'rest_day_worked',
        'approval_status', 'pending',
        'schedule_exception_id', null,
        'system_reason', 'Día de descanso programado.',
        'schedule_id', null,
        'schedule_status', null,
        'reason_code', 'rest_day'
      );
    end if;

    return jsonb_build_object(
      'classification', 'no_schedule',
      'approval_status', 'pending',
      'schedule_exception_id', null,
      'system_reason', 'Sin bloque laboral válido para esta fecha.',
      'schedule_id', null,
      'schedule_status', null,
      'reason_code', 'no_schedule'
    );
  end if;

  v_grace := public.get_attendance_late_grace_minutes();
  v_shift_start_ts := ((p_labor_date + v_work.start_time) at time zone v_tz);
  v_shift_end_ts := (
    (p_labor_date + case when v_work.end_time <= v_work.start_time then 1 else 0 end) + v_work.end_time
  ) at time zone v_tz;

  if p_at < v_shift_start_ts - interval '2 hours' then
    return jsonb_build_object(
      'classification', 'out_of_schedule',
      'approval_status', 'pending',
      'schedule_exception_id', null,
      'system_reason', 'Marcación antes del horario permitido.',
      'schedule_id', v_work.id,
      'schedule_status', v_work.status,
      'reason_code', 'out_of_schedule'
    );
  end if;

  if p_at > v_shift_end_ts + interval '2 hours' then
    return jsonb_build_object(
      'classification', 'pending_overtime',
      'approval_status', 'pending',
      'schedule_exception_id', null,
      'system_reason', 'Marcación después del horario programado.',
      'schedule_id', v_work.id,
      'schedule_status', v_work.status,
      'reason_code', 'out_of_schedule'
    );
  end if;

  v_early_minutes := greatest(0, floor(extract(epoch from (v_shift_start_ts - p_at)) / 60)::integer);
  if v_early_minutes > 15 then
    return jsonb_build_object(
      'classification', 'early',
      'approval_status', 'not_required',
      'schedule_exception_id', null,
      'system_reason', 'Entrada anticipada dentro de ventana operativa.',
      'schedule_id', v_work.id,
      'schedule_status', v_work.status,
      'reason_code', 'allowed'
    );
  end if;

  v_late_minutes := greatest(0, floor(extract(epoch from (p_at - v_shift_start_ts)) / 60)::integer);
  if v_late_minutes > v_grace then
    return jsonb_build_object(
      'classification', 'late',
      'approval_status', 'not_required',
      'schedule_exception_id', null,
      'system_reason', format('Entrada tarde (%s min después del horario).', v_late_minutes),
      'schedule_id', v_work.id,
      'schedule_status', v_work.status,
      'reason_code', 'allowed'
    );
  end if;

  return jsonb_build_object(
    'classification', 'normal',
    'approval_status', 'not_required',
    'schedule_exception_id', null,
    'system_reason', 'Marcación dentro del horario asignado.',
    'schedule_id', v_work.id,
    'schedule_status', v_work.status,
    'reason_code', 'allowed'
  );
end;
$$;


ALTER FUNCTION "public"."classify_attendance_mark"("p_employee_id" "uuid", "p_labor_date" "date", "p_mark_type" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_checklist_responsible_availability"("p_profile_id" "uuid", "p_reference_at" timestamp with time zone DEFAULT "now"(), "p_operational_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  profile_row public.profiles;
  op_date date := coalesce(p_operational_date, public.get_checklist_operational_date(p_reference_at));
  labor_date date;
  ctx jsonb;
  schedule_gate jsonb;
  unavailability text;
  shift_start time;
  grace_minutes integer;
  shift_start_ts timestamptz;
  tolerance_ts timestamptz;
  availability_state text := 'unknown';
  availability_label text := 'No determinado';
  replacement_reason_suggestion text := null;
  checked_in boolean := false;
  has_work boolean := false;
begin
  if p_profile_id is null then
    return jsonb_build_object(
      'profile_id', null,
      'operational_date', op_date,
      'availability_state', 'unknown',
      'availability_label', 'No determinado'
    );
  end if;

  if not (
    public.can_access_checklists()
    or p_profile_id = auth.uid()
    or public.can_assign_checklist_run_replacement()
  ) then
    raise exception 'No tienes permiso para consultar disponibilidad de checklist.';
  end if;

  select * into profile_row from public.profiles where id = p_profile_id;
  if profile_row.id is null then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'unknown',
      'availability_label', 'Perfil no encontrado'
    );
  end if;

  if profile_row.status in ('inactive', 'suspended') then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'unknown',
      'availability_label', 'Colaborador inactivo o suspendido',
      'profile_status', profile_row.status
    );
  end if;

  unavailability := public._profile_schedule_unavailability(p_profile_id, op_date);
  if unavailability = 'Vacaciones' then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'approved_leave',
      'availability_label', 'Vacaciones o permiso aprobado',
      'replacement_reason_suggestion', 'vacaciones',
      'schedule_unavailability', unavailability
    );
  end if;

  if unavailability = 'Dia de descanso' then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'official_day_off',
      'availability_label', 'Dia de descanso o asueto',
      'replacement_reason_suggestion', 'descanso',
      'schedule_unavailability', unavailability
    );
  end if;

  schedule_gate := public.can_employee_mark_attendance(p_profile_id, op_date);
  has_work := public._profile_has_work_schedule(p_profile_id, op_date);

  if coalesce(schedule_gate ->> 'reason_code', '') = 'no_schedule' and not has_work then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'no_schedule',
      'availability_label', 'Sin horario asignado',
      'schedule_reason_code', schedule_gate ->> 'reason_code'
    );
  end if;

  if coalesce(schedule_gate ->> 'reason_code', '') = 'rest_day' and not has_work then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'official_day_off',
      'availability_label', 'Dia de descanso o asueto',
      'replacement_reason_suggestion', 'descanso',
      'schedule_reason_code', schedule_gate ->> 'reason_code'
    );
  end if;

  ctx := public.resolve_attendance_context(p_profile_id, 'entrada', p_reference_at);
  labor_date := coalesce((ctx ->> 'labor_date')::date, op_date);
  checked_in := public._profile_is_checked_in(p_profile_id, labor_date, p_reference_at);

  if checked_in then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'labor_date', labor_date,
      'availability_state', 'available_present',
      'availability_label', 'Presente o con entrada registrada',
      'checked_in', true,
      'has_open_entry', coalesce((ctx ->> 'has_open_entry')::boolean, false)
    );
  end if;

  if not has_work then
    return jsonb_build_object(
      'profile_id', p_profile_id,
      'operational_date', op_date,
      'availability_state', 'unknown',
      'availability_label', 'No determinado',
      'schedule_reason_code', schedule_gate ->> 'reason_code'
    );
  end if;

  shift_start := public._profile_earliest_shift_start(p_profile_id, op_date);
  grace_minutes := public.get_attendance_late_grace_minutes();

  if shift_start is null then
    availability_state := 'scheduled_not_checked_in';
    availability_label := 'Turno programado sin marcaje de entrada';
    replacement_reason_suggestion := 'ausencia_no_marcaje';
  else
    shift_start_ts := (op_date + shift_start) at time zone 'America/Guatemala';
    tolerance_ts := shift_start_ts + make_interval(mins => grace_minutes);
    if p_reference_at >= tolerance_ts then
      availability_state := 'scheduled_not_checked_in';
      availability_label := 'Turno programado sin marcaje de entrada';
      replacement_reason_suggestion := 'ausencia_no_marcaje';
    else
      availability_state := 'unknown';
      availability_label := 'Esperando marcaje de entrada';
    end if;
  end if;

  return jsonb_build_object(
    'profile_id', p_profile_id,
    'operational_date', op_date,
    'labor_date', labor_date,
    'availability_state', availability_state,
    'availability_label', availability_label,
    'replacement_reason_suggestion', replacement_reason_suggestion,
    'checked_in', false,
    'shift_start', shift_start,
    'grace_minutes', grace_minutes
  );
end;
$$;


ALTER FUNCTION "public"."classify_checklist_responsible_availability"("p_profile_id" "uuid", "p_reference_at" timestamp with time zone, "p_operational_date" "date") OWNER TO "postgres";


