CREATE OR REPLACE FUNCTION "public"."clear_pos_order_draft_items"("p_order_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  removed_count integer;
begin
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para limpiar esta orden.';
  end if;

  delete from public.pos_order_items
  where order_id = p_order_id
    and status = 'draft';

  get diagnostics removed_count = row_count;

  if removed_count > 0 then
    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (p_order_id, 'draft_cleared', 'Se limpiaron los productos nuevos de la orden.', auth.uid());
  end if;

  return removed_count;
end;
$$;


ALTER FUNCTION "public"."clear_pos_order_draft_items"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_station_pos_draft_items"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_removed integer;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'clear_draft_items',
    jsonb_build_object('order_id', p_order_id)
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'clear_draft_items', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'clear_draft_items', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);
  perform public.station_pos_assert_order_open_for_drafts(p_order_id, v_operator_id);

  v_removed := public.station_pos_clear_draft_items_impl(p_order_id, v_operator_id);
  v_result := jsonb_build_object('removed', v_removed, 'order_id', p_order_id);

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'clear_draft_items', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."clear_station_pos_draft_items"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."cash_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "cash_register_id" "uuid" NOT NULL,
    "opened_by" "uuid" NOT NULL,
    "closed_by" "uuid",
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "opening_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "expected_cash" numeric(12,2) DEFAULT 0 NOT NULL,
    "counted_cash" numeric(12,2),
    "difference" numeric(12,2),
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cash_sessions_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."cash_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_cash_session"("p_cash_session_id" "uuid", "p_counted_cash" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."cash_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.cash_sessions;
  expected numeric(12,2);
  saved public.cash_sessions;
begin
  if not public.is_cash_operator() then
    raise exception 'No tienes permiso para cerrar caja.';
  end if;

  select * into session_row
  from public.cash_sessions
  where id = p_cash_session_id
  for update;
  if session_row.id is null or session_row.status <> 'open' then
    raise exception 'No hay caja abierta.';
  end if;
  if not public.is_cash_supervisor() and session_row.opened_by <> auth.uid() then
    raise exception 'Solo puedes cerrar tu propia caja.';
  end if;

  expected := public.calculate_cash_expected(session_row.id);

  update public.cash_sessions
  set expected_cash = expected,
      counted_cash = coalesce(p_counted_cash, 0)::numeric(12,2),
      difference = (coalesce(p_counted_cash, 0)::numeric(12,2) - expected)::numeric(12,2),
      status = 'closed',
      closed_by = auth.uid(),
      closed_at = now(),
      notes = nullif(trim(coalesce(p_notes, notes, '')), ''),
      updated_at = now()
  where id = session_row.id
  returning * into saved;

  insert into public.cash_movements (
    cash_session_id, cash_register_id, created_by, movement_type, amount, reason
  ) values (
    saved.id, saved.cash_register_id, auth.uid(), 'shift_close', 0, 'Cierre de caja'
  );

  return saved;
end;
$$;


ALTER FUNCTION "public"."close_cash_session"("p_cash_session_id" "uuid", "p_counted_cash" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_employee_incident"("p_incident_id" "uuid", "p_closure_summary" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_incident public.employee_incidents;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para cerrar incidentes.';
  end if;

  select * into v_incident
  from public.employee_incidents
  where id = p_incident_id
  for update;

  if not found then
    raise exception 'Incidente no encontrado.';
  end if;

  if v_incident.status = 'closed' then
    return to_jsonb(v_incident);
  end if;

  update public.employee_incidents
  set
    status = 'closed',
    closed_at = now(),
    closed_by = auth.uid(),
    closure_summary = nullif(trim(coalesce(p_closure_summary, '')), ''),
    updated_at = now()
  where id = p_incident_id
  returning * into v_incident;

  return to_jsonb(v_incident);
end;
$$;


ALTER FUNCTION "public"."close_employee_incident"("p_incident_id" "uuid", "p_closure_summary" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_finance_reconciliation"("p_reconciliation_id" "uuid", "p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rec public.finance_reconciliations;
begin
  if not public.can_reconcile_finance() then
    raise exception 'No tienes permiso para cerrar conciliaciones.';
  end if;

  select * into v_rec from public.finance_reconciliations where id = p_reconciliation_id for update;
  if not found then raise exception 'Conciliación no encontrada.'; end if;
  if v_rec.status = 'closed' then raise exception 'La conciliación ya está cerrada.'; end if;

  if v_rec.difference <> 0 and not (p_force and public.can_manage_finance()) then
    raise exception 'La diferencia debe ser cero para cerrar la conciliación.';
  end if;

  update public.finance_reconciliations
  set status = 'closed', closed_at = now(), closed_by = auth.uid()
  where id = p_reconciliation_id
  returning * into v_rec;

  update public.finance_bank_transactions t
  set reconciliation_status = 'reconciled', reconciled_at = now()
  from public.finance_reconciliation_items i
  where i.reconciliation_id = p_reconciliation_id
    and i.bank_transaction_id = t.id
    and i.is_checked;

  return to_jsonb(v_rec);
end;
$$;


ALTER FUNCTION "public"."close_finance_reconciliation"("p_reconciliation_id" "uuid", "p_force" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."attendance_marks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "employee_name" "text" NOT NULL,
    "mark_type" "text" NOT NULL,
    "marked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "photo_path" "text" NOT NULL,
    "device_id" "text" NOT NULL,
    "device_name" "text" NOT NULL,
    "device_alert" boolean DEFAULT false NOT NULL,
    "related_mark_id" "uuid",
    "duration_minutes" integer,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "observation" "text",
    "labor_date" "date",
    "classification" "text",
    "approval_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "approval_notes" "text",
    "schedule_exception_id" "uuid",
    "system_reason" "text",
    CONSTRAINT "attendance_marks_approval_status_check" CHECK (("approval_status" = ANY (ARRAY['not_required'::"text", 'pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "attendance_marks_classification_check" CHECK ((("classification" IS NULL) OR ("classification" = ANY (ARRAY['normal'::"text", 'late'::"text", 'early'::"text", 'out_of_schedule'::"text", 'no_schedule'::"text", 'rest_day_worked'::"text", 'authorized_overtime'::"text", 'pending_overtime'::"text", 'manual_adjustment'::"text"])))),
    CONSTRAINT "attendance_marks_mark_type_check" CHECK (("mark_type" = ANY (ARRAY['entrada'::"text", 'salida_comida'::"text", 'regreso_comida'::"text", 'salida_final'::"text", 'salida'::"text", 'bano_inicio'::"text", 'bano_regreso'::"text"])))
);


ALTER TABLE "public"."attendance_marks" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_open_attendance_shift"("p_employee_id" "uuid", "p_closed_at" timestamp with time zone DEFAULT "now"(), "p_observation" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_marks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO '', 'extensions', 'public'
    AS $$
declare
  v_open_entry public.attendance_marks;
  v_open_meal public.attendance_marks;
  v_mark public.attendance_marks;
  v_observation text := nullif(trim(coalesce(p_observation, '')), '');
  v_labor_date date;
begin
  if not public.is_schedule_publisher() then
    raise exception 'PERMISSION_DENIED: se requiere rol de RRHH para cerrar turnos manualmente.';
  end if;

  select m.* into v_open_entry
  from public.attendance_marks m
  where m.employee_id = p_employee_id
    and m.mark_type = 'entrada'
    and not exists (
      select 1
      from public.attendance_marks out_mark
      where out_mark.employee_id = m.employee_id
        and out_mark.mark_type in ('salida_final', 'salida')
        and out_mark.marked_at > m.marked_at
    )
  order by m.marked_at desc
  limit 1;

  if v_open_entry.id is null then
    raise exception 'No hay turno abierto para este colaborador.';
  end if;

  select m.* into v_open_meal
  from public.attendance_marks m
  where m.employee_id = p_employee_id
    and m.mark_type in ('salida_comida', 'bano_inicio')
    and m.marked_at > v_open_entry.marked_at
    and not exists (
      select 1
      from public.attendance_marks back_mark
      where back_mark.employee_id = m.employee_id
        and back_mark.mark_type in ('regreso_comida', 'bano_regreso')
        and back_mark.marked_at > m.marked_at
    )
  order by m.marked_at desc
  limit 1;

  if v_open_meal.id is not null then
    raise exception 'El colaborador tiene salida a comida sin regreso. Cierra la comida antes de cerrar el turno.';
  end if;

  v_labor_date := coalesce(
    v_open_entry.labor_date,
    (v_open_entry.marked_at at time zone 'America/Guatemala')::date
  );

  insert into public.attendance_marks (
    employee_id,
    employee_name,
    mark_type,
    photo_path,
    device_id,
    device_name,
    device_alert,
    related_mark_id,
    duration_minutes,
    observation,
    marked_at,
    labor_date,
    classification,
    approval_status,
    schedule_exception_id,
    system_reason
  )
  values (
    v_open_entry.employee_id,
    v_open_entry.employee_name,
    'salida_final',
    format('manual/hr-close/%s', gen_random_uuid()),
    'rrhh-manual',
    'Cierre manual RRHH',
    false,
    v_open_entry.id,
    greatest(0, floor(extract(epoch from (p_closed_at - v_open_entry.marked_at)) / 60)::integer),
    coalesce(v_observation, 'Cierre manual de turno por RRHH.'),
    p_closed_at,
    v_labor_date,
    coalesce(v_open_entry.classification, 'normal'),
    coalesce(v_open_entry.approval_status, 'not_required'),
    v_open_entry.schedule_exception_id,
    'Salida final registrada manualmente por RRHH.'
  )
  returning * into v_mark;

  return v_mark;
end;
$$;


ALTER FUNCTION "public"."close_open_attendance_shift"("p_employee_id" "uuid", "p_closed_at" timestamp with time zone, "p_observation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_station_cash_session"("p_operator_session_token" "text", "p_counted_cash" numeric, "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_register_id uuid;
  v_op_session_id uuid;
  v_session_row public.cash_sessions;
  v_expected numeric(12,2);
  v_saved public.cash_sessions;
  v_cached jsonb;
  v_fingerprint text;
  v_generic constant text := 'No se pudo cerrar caja.';
begin
  v_fingerprint := public.station_cash_request_fingerprint(
    'close',
    jsonb_build_object(
      'counted_cash', round(coalesce(p_counted_cash, 0)::numeric, 2),
      'notes', coalesce(nullif(trim(coalesce(p_notes, '')), ''), '')
    )
  );

  v_cached := public.station_cash_idempotency_replay_if_completed(
    p_operator_session_token, 'close', p_idempotency_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_cash_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_register_id := (v_ctx ->> 'cash_register_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;

  v_cached := public.station_cash_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, p_idempotency_key, 'close', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_cash_extend_operator_idle(v_op_session_id);

  select * into v_session_row
  from public.cash_sessions
  where cash_register_id = v_register_id and status = 'open'
  order by opened_at desc
  limit 1
  for update;

  if v_session_row.id is null then
    raise exception 'No hay caja abierta.';
  end if;

  if not public.station_cash_is_supervisor(v_operator_id)
    and v_session_row.opened_by <> v_operator_id then
    raise exception 'Solo puedes cerrar tu propia caja.';
  end if;

  v_expected := public.calculate_cash_expected(v_session_row.id);

  update public.cash_sessions
  set expected_cash = v_expected,
      counted_cash = coalesce(p_counted_cash, 0)::numeric(12,2),
      difference = (coalesce(p_counted_cash, 0)::numeric(12,2) - v_expected)::numeric(12,2),
      status = 'closed',
      closed_by = v_operator_id,
      closed_at = now(),
      notes = nullif(trim(coalesce(p_notes, v_session_row.notes, '')), ''),
      updated_at = now()
  where id = v_session_row.id
  returning * into v_saved;

  insert into public.cash_movements (
    cash_session_id, cash_register_id, created_by, movement_type, amount, reason, metadata
  ) values (
    v_saved.id, v_saved.cash_register_id, v_operator_id, 'shift_close', 0, 'Cierre de caja',
    jsonb_build_object(
      'operational_station_id', v_station_id,
      'operational_station_device_id', v_device_id,
      'operator_profile_id', v_operator_id
    )
  );

  update public.operational_operator_sessions
  set revoked_at = now(), revoke_reason = 'shift_close'
  where id = v_op_session_id and revoked_at is null;

  perform public.log_operational_station_event(
    v_station_id, v_device_id, 'operator_session_locked', v_operator_id,
    jsonb_build_object('reason', 'shift_close', 'cash_session_id', v_saved.id),
    nullif(trim(p_idempotency_key), '')
  );

  v_cached := jsonb_build_object('ok', true, 'session', to_jsonb(v_saved), 'operator_locked', true);
  perform public.station_cash_idempotency_complete(v_device_id, p_idempotency_key, v_cached);
  return v_cached;
exception
  when others then
    if sqlerrm in ('No hay caja abierta.', 'Solo puedes cerrar tu propia caja.') then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."close_station_cash_session"("p_operator_session_token" "text", "p_counted_cash" numeric, "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_internal_production_batch"("p_batch_id" "uuid") RETURNS "public"."production_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  batch public.production_batches;
  input_row public.production_batch_inputs;
  output_row public.production_batch_outputs;
  stock_before numeric;
  stock_after numeric;
  batch_total numeric := 0;
  output_total numeric := 0;
  unit_cost_value numeric := 0;
begin
  select * into batch
  from public.production_batches
  where id = p_batch_id
  for update;

  if batch.id is null then raise exception 'La produccion no existe.'; end if;
  if batch.status not in ('draft', 'in_progress') then raise exception 'Solo se puede completar una produccion abierta.'; end if;
  if not public.can_create_internal_production(batch.production_area_id) then raise exception 'No tienes permiso para completar esta produccion.'; end if;
  if batch.output_inventory_item_id is null then raise exception 'La receta seleccionada no tiene producto terminado configurado.'; end if;
  if coalesce(batch.actual_output_quantity, batch.output_quantity, 0) <= 0 then raise exception 'La produccion real debe ser mayor que cero.'; end if;
  if batch.recipe_id is not null and not exists (
    select 1
    from public.standard_recipes recipe
    where recipe.id = batch.recipe_id
      and recipe.output_inventory_item_id = batch.output_inventory_item_id
  ) then
    raise exception 'La receta seleccionada no tiene producto terminado configurado.';
  end if;

  for input_row in select * from public.production_batch_inputs where batch_id = batch.id
  loop
    insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
    values (input_row.inventory_item_id, batch.production_area_id, 0, 0)
    on conflict (item_id, area_id) do nothing;

    select quantity into stock_before
    from public.area_inventory
    where item_id = input_row.inventory_item_id and area_id = batch.production_area_id
    for update;
    stock_before := coalesce(stock_before, 0);
    stock_after := stock_before - input_row.quantity;
    if stock_after < 0 then
      raise exception 'Stock insuficiente de %. Disponible: %, requerido: %.',
        input_row.item_name, stock_before, input_row.quantity;
    end if;

    update public.area_inventory
    set quantity = stock_after
    where item_id = input_row.inventory_item_id and area_id = batch.production_area_id;

    update public.production_batch_inputs
    set area_stock_before = stock_before,
        area_stock_after = stock_after,
        total_cost = input_row.quantity * input_row.cost_unit
    where id = input_row.id;

    insert into public.inventory_movements (
      item_id, movement_type, from_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, source_id, notes, performed_by
    )
    values (
      input_row.inventory_item_id, 'production_input', batch.production_area_id,
      input_row.quantity, input_row.unit, stock_before, stock_after,
      'internal_production', batch.id::text,
      'Insumo usado en produccion ' || batch.batch_number, auth.uid()
    );

    batch_total := batch_total + (input_row.quantity * input_row.cost_unit);
  end loop;

  select coalesce(sum(quantity), 0) into output_total
  from public.production_batch_outputs
  where batch_id = batch.id;

  if output_total <= 0 then raise exception 'La produccion debe tener una salida mayor que cero.'; end if;
  unit_cost_value := batch_total / output_total;

  for output_row in select * from public.production_batch_outputs where batch_id = batch.id
  loop
    insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
    values (output_row.inventory_item_id, batch.production_area_id, 0, 0)
    on conflict (item_id, area_id) do nothing;

    select quantity into stock_before
    from public.area_inventory
    where item_id = output_row.inventory_item_id and area_id = batch.production_area_id
    for update;
    stock_before := coalesce(stock_before, 0);
    stock_after := stock_before + output_row.quantity;

    update public.area_inventory
    set quantity = stock_after
    where item_id = output_row.inventory_item_id and area_id = batch.production_area_id;

    update public.production_batch_outputs
    set unit_cost = unit_cost_value,
        total_cost = output_row.quantity * unit_cost_value,
        area_stock_before = stock_before,
        area_stock_after = stock_after
    where id = output_row.id;

    update public.inventory_items
    set cost_per_base_unit = unit_cost_value
    where id = output_row.inventory_item_id;

    insert into public.inventory_movements (
      item_id, movement_type, to_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, source_id, notes, performed_by
    )
    values (
      output_row.inventory_item_id, 'production_output', batch.production_area_id,
      output_row.quantity, output_row.unit, stock_before, stock_after,
      'internal_production', batch.id::text,
      'Salida de produccion ' || batch.batch_number, auth.uid()
    );
  end loop;

  update public.production_batches
  set status = 'completed',
      completed_at = now(),
      approved_by = auth.uid(),
      total_cost = batch_total,
      total_batch_cost = batch_total,
      unit_cost = unit_cost_value,
      actual_unit_cost = unit_cost_value,
      output_quantity = output_total,
      actual_output_quantity = output_total,
      waste_quantity = greatest(0, coalesce(expected_output_quantity, expected_quantity, output_total) - output_total),
      updated_at = now()
  where id = batch.id
  returning * into batch;

  return batch;
end;
$$;


ALTER FUNCTION "public"."complete_internal_production_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_requisition"("p_requisition_id" "uuid") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requisition public.requisitions;
  detail public.requisition_items;
  moved_quantity numeric;
  source_before numeric;
  destination_before numeric;
  movement_unit text;
  completed public.requisitions;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para completar traslados.';
  end if;

  select * into requisition from public.requisitions where id = p_requisition_id for update;
  if requisition.id is null or requisition.status <> 'approved' then
    raise exception 'La requisición debe estar aprobada antes del traslado.';
  end if;
  if not exists (select 1 from public.requisition_items where requisition_id = p_requisition_id) then
    raise exception 'La requisición no tiene productos.';
  end if;

  for detail in select * from public.requisition_items where requisition_id = p_requisition_id
  loop
    moved_quantity := coalesce(
      detail.converted_approved_quantity,
      detail.converted_requested_quantity,
      detail.approved_quantity,
      detail.requested_quantity
    );
    if moved_quantity <= 0 then
      raise exception 'La cantidad para % no es valida.', detail.item_name;
    end if;
    select base_unit into movement_unit from public.inventory_items where id = detail.item_id;
    movement_unit := coalesce(movement_unit, detail.unit);

    if coalesce(requisition.is_test, false) then
      insert into public.inventory_movements (
        item_id, movement_type, from_area_id, to_area_id, quantity, unit,
        previous_quantity, new_quantity, source_type, source_id, notes, performed_by, is_test
      ) values (
        detail.item_id, 'transfer', requisition.from_area_id, requisition.to_area_id,
        moved_quantity, movement_unit, null, null,
        'requisition_test', requisition.id::text,
        'PRUEBA: traslado simulado ' || requisition.requisition_number ||
          '. Solicitado: ' || detail.requested_quantity || ' ' || coalesce(detail.requested_unit, detail.unit),
        auth.uid(),
        true
      );
      continue;
    end if;

    select quantity into source_before from public.area_inventory
      where item_id = detail.item_id and area_id = requisition.from_area_id for update;
    insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
      values (detail.item_id, requisition.to_area_id, 0, 0)
      on conflict (item_id, area_id) do nothing;
    select quantity into destination_before from public.area_inventory
      where item_id = detail.item_id and area_id = requisition.to_area_id for update;

    source_before := coalesce(source_before, 0);
    destination_before := coalesce(destination_before, 0);

    update public.area_inventory set quantity = source_before - moved_quantity
      where item_id = detail.item_id and area_id = requisition.from_area_id;
    update public.area_inventory set quantity = destination_before + moved_quantity
      where item_id = detail.item_id and area_id = requisition.to_area_id;
    insert into public.inventory_movements (
      item_id, movement_type, from_area_id, to_area_id, quantity, unit,
      previous_quantity, new_quantity, source_type, source_id, notes, performed_by, is_test
    ) values (
      detail.item_id, 'transfer', requisition.from_area_id, requisition.to_area_id,
      moved_quantity, movement_unit, source_before, source_before - moved_quantity,
      'requisition', requisition.id::text,
      'Traslado requisicion ' || requisition.requisition_number ||
        '. Solicitado: ' || detail.requested_quantity || ' ' || coalesce(detail.requested_unit, detail.unit) ||
        '. Destino antes: ' || destination_before || ', despues: ' || (destination_before + moved_quantity),
      auth.uid(),
      false
    );
  end loop;

  update public.requisitions
    set status = 'completed', completed_by = auth.uid(), completed_at = now()
    where id = p_requisition_id
    returning * into completed;

  return completed;
end;
$$;


ALTER FUNCTION "public"."complete_requisition"("p_requisition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_requisition"("p_requisition_id" "uuid", "p_items" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requisition public.requisitions;
  detail public.requisition_items;
  row_data jsonb;
  delivered_qty numeric;
  delivered_base numeric;
  moved_quantity numeric;
  source_before numeric;
  destination_before numeric;
  movement_unit text;
  completed public.requisitions;
  line_shortage_reason text;
  line_shortage_notes text;
  pending_qty numeric;
  line_status text;
  all_fulfilled boolean := true;
  any_delivered boolean := false;
  any_pending boolean := false;
  new_status text;
  snapshot_base_unit text;
  current_base_unit text;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para completar traslados.';
  end if;

  select * into requisition
  from public.requisitions
  where id = p_requisition_id
  for update;

  if requisition.id is null or requisition.status <> 'approved' then
    raise exception 'La requisición debe estar aprobada antes del traslado.';
  end if;

  if not exists (
    select 1 from public.requisition_items where requisition_id = p_requisition_id
  ) then
    raise exception 'La requisición no tiene productos.';
  end if;

  for detail in select * from public.requisition_items where requisition_id = p_requisition_id
  loop
    delivered_qty := null;
    line_shortage_reason := null;
    line_shortage_notes := null;

    if p_items is not null and jsonb_typeof(p_items) = 'array' then
      for row_data in select value from jsonb_array_elements(p_items)
      loop
        if (row_data ->> 'id')::uuid = detail.id then
          delivered_qty := coalesce(
            nullif(row_data ->> 'delivered_quantity', '')::numeric,
            nullif(row_data ->> 'approved_quantity', '')::numeric
          );
          line_shortage_reason := nullif(trim(row_data ->> 'shortage_reason'), '');
          line_shortage_notes := nullif(trim(row_data ->> 'shortage_notes'), '');
          exit;
        end if;
      end loop;
    end if;

    if delivered_qty is null then
      delivered_qty := coalesce(detail.approved_quantity, detail.requested_quantity, 0);
    end if;

    if delivered_qty < 0 then
      raise exception 'La cantidad entregada para % no puede ser negativa.', detail.item_name;
    end if;

    if delivered_qty > detail.requested_quantity then
      raise exception
        'La cantidad entregada para % no puede superar lo solicitado (%).',
        detail.item_name,
        detail.requested_quantity;
    end if;

    if public.requisition_shortage_reason_required(detail.requested_quantity, delivered_qty)
       and coalesce(line_shortage_reason, detail.shortage_reason) is null then
      raise exception
        'Debes indicar el motivo del faltante para %.',
        detail.item_name;
    end if;

    snapshot_base_unit := coalesce(nullif(trim(detail.inventory_base_unit_at_request), ''), detail.unit);
    select ii.base_unit into current_base_unit
    from public.inventory_items ii
    where ii.id = detail.item_id;

    if current_base_unit is null then
      raise exception 'El producto % ya no existe en el inventario.', detail.item_name;
    end if;

    if public.normalize_inventory_unit(snapshot_base_unit)
       <> public.normalize_inventory_unit(current_base_unit) then
      raise exception
        'La requisicion fue creada con una configuracion anterior del producto %. Unidad de inventario al crear: %. Unidad actual: %. Cancele la requisicion y vuelva a crearla con la configuracion actual.',
        detail.item_name,
        snapshot_base_unit,
        current_base_unit;
    end if;

    pending_qty := greatest(detail.requested_quantity - delivered_qty, 0);
    line_status := public.requisition_line_fulfillment_status(detail.requested_quantity, delivered_qty);

    if line_status <> 'fulfilled' then
      all_fulfilled := false;
    end if;
    if delivered_qty > 0 then
      any_delivered := true;
    end if;
    if pending_qty > 0 then
      any_pending := true;
    end if;

    delivered_base := delivered_qty * coalesce(detail.conversion_factor, 1);
    moved_quantity := delivered_base;
    movement_unit := current_base_unit;

    if delivered_qty > 0 and not coalesce(requisition.is_test, false) then
      insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
      values (detail.item_id, requisition.to_area_id, 0, 0)
      on conflict (item_id, area_id) do nothing;

      select quantity into source_before
      from public.area_inventory
      where item_id = detail.item_id and area_id = requisition.from_area_id
      for update;

      select quantity into destination_before
      from public.area_inventory
      where item_id = detail.item_id and area_id = requisition.to_area_id
      for update;

      source_before := coalesce(source_before, 0);
      destination_before := coalesce(destination_before, 0);

      if source_before < moved_quantity then
        raise exception
          E'No hay suficiente inventario para surtir este producto.\nProducto:\n%\nDisponible:\n% %\nIntentas entregar:\n% %',
          detail.item_name,
          source_before,
          current_base_unit,
          moved_quantity,
          current_base_unit;
      end if;

      update public.area_inventory
      set quantity = source_before - moved_quantity
      where item_id = detail.item_id and area_id = requisition.from_area_id;

      update public.area_inventory
      set quantity = destination_before + moved_quantity
      where item_id = detail.item_id and area_id = requisition.to_area_id;

      insert into public.inventory_movements (
        item_id, movement_type, from_area_id, to_area_id, quantity, unit,
        previous_quantity, new_quantity, source_type, source_id, notes, performed_by, is_test
      ) values (
        detail.item_id,
        'transfer',
        requisition.from_area_id,
        requisition.to_area_id,
        moved_quantity,
        movement_unit,
        source_before,
        source_before - moved_quantity,
        'requisition',
        requisition.id::text,
        'Traslado requisicion ' || requisition.requisition_number ||
          '. Solicitado: ' || detail.requested_quantity || ' ' || coalesce(detail.requested_unit, detail.unit) ||
          '. Entregado: ' || delivered_qty || ' ' || coalesce(detail.requested_unit, detail.unit) ||
          '. Pendiente: ' || pending_qty || ' ' || coalesce(detail.requested_unit, detail.unit) ||
          case
            when coalesce(line_shortage_reason, detail.shortage_reason) is not null
              then '. Motivo: ' || coalesce(line_shortage_reason, detail.shortage_reason)
            else ''
          end,
        auth.uid(),
        false
      );
    elsif delivered_qty > 0 and coalesce(requisition.is_test, false) then
      insert into public.inventory_movements (
        item_id, movement_type, from_area_id, to_area_id, quantity, unit,
        previous_quantity, new_quantity, source_type, source_id, notes, performed_by, is_test
      ) values (
        detail.item_id,
        'transfer',
        requisition.from_area_id,
        requisition.to_area_id,
        moved_quantity,
        movement_unit,
        null,
        null,
        'requisition_test',
        requisition.id::text,
        'PRUEBA: traslado simulado ' || requisition.requisition_number ||
          '. Solicitado: ' || detail.requested_quantity || ' ' || coalesce(detail.requested_unit, detail.unit) ||
          '. Entregado: ' || delivered_qty || ' ' || coalesce(detail.requested_unit, detail.unit) ||
          '. Pendiente: ' || pending_qty,
        auth.uid(),
        true
      );
    end if;

    update public.requisition_items ri
    set
      delivered_quantity = delivered_qty,
      converted_delivered_quantity = delivered_base,
      pending_quantity = pending_qty,
      fulfillment_status = line_status,
      shortage_reason = case
        when public.requisition_shortage_reason_required(ri.requested_quantity, delivered_qty)
          then coalesce(line_shortage_reason, detail.shortage_reason)
        else null
      end,
      shortage_notes = case
        when public.requisition_shortage_reason_required(ri.requested_quantity, delivered_qty)
          then line_shortage_notes
        else null
      end,
      fulfilled_at = now(),
      fulfilled_by = auth.uid()
    where ri.id = detail.id;
  end loop;

  new_status := public.requisition_header_fulfillment_status(all_fulfilled, any_delivered, any_pending);

  update public.requisitions
  set
    status = new_status,
    completed_by = auth.uid(),
    completed_at = now()
  where id = p_requisition_id
  returning * into completed;

  return completed;
end;
$$;


ALTER FUNCTION "public"."complete_requisition"("p_requisition_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_inventory_weighted_average_cost"("p_item_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with stock as (
    select coalesce(sum(ai.quantity), 0) as total_qty
    from public.area_inventory ai
    where ai.item_id = p_item_id
  ),
  purchase_weighted as (
    select
      case
        when sum(im.quantity) > 0 then sum(im.quantity * i.cost_per_base_unit) / sum(im.quantity)
        else null
      end as cpp
    from public.inventory_movements im
    join public.inventory_items i on i.id = im.item_id
    where im.item_id = p_item_id
      and im.movement_type = 'purchase'
      and im.quantity > 0
  )
  select coalesce(
    (select cpp from purchase_weighted where cpp is not null),
    (select i.cost_per_base_unit from public.inventory_items i where i.id = p_item_id),
    0
  )
  from public.inventory_items base
  where base.id = p_item_id;
$$;


ALTER FUNCTION "public"."compute_inventory_weighted_average_cost"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_pos_product_recipe_status"("p_product_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product public.pos_products;
  v_recipe public.standard_recipes;
  v_ingredient_count integer := 0;
  v_valid_variants integer := 0;
begin
  select * into v_product from public.pos_products where id = p_product_id;
  if v_product.id is null then
    return 'missing';
  end if;

  if v_product.is_test_item then
    return 'missing';
  end if;

  if v_product.product_type = 'pizza' then
    if not coalesce(v_product.inventory_tracking_enabled, false) then
      return 'missing';
    end if;

    select count(*) into v_valid_variants
    from public.pos_product_variants variant
    join public.standard_recipes recipe on recipe.id = variant.recipe_id
    where variant.product_id = v_product.id
      and variant.is_active = true
      and recipe.recipe_type = 'final_product';

    if v_valid_variants = 0 then
      return 'missing';
    end if;

    select count(*) into v_valid_variants
    from public.pos_product_variants variant
    join public.standard_recipes recipe on recipe.id = variant.recipe_id
    join public.recipe_ingredients ingredient on ingredient.recipe_id = recipe.id
    where variant.product_id = v_product.id
      and variant.is_active = true
      and recipe.active = true
      and recipe.recipe_type = 'final_product';

    if v_valid_variants = 0 then
      return case
        when exists (
          select 1
          from public.pos_product_variants variant
          join public.standard_recipes recipe on recipe.id = variant.recipe_id
          where variant.product_id = v_product.id
            and variant.is_active = true
            and recipe.active = false
        ) then 'paused'
        else 'draft'
      end;
    end if;

    return 'active';
  end if;

  if v_product.recipe_id is null then
    return 'missing';
  end if;

  select * into v_recipe
  from public.standard_recipes
  where id = v_product.recipe_id
    and recipe_type = 'final_product';

  if v_recipe.id is null then
    return 'missing';
  end if;

  if not v_recipe.active then
    return 'paused';
  end if;

  select count(*) into v_ingredient_count
  from public.recipe_ingredients
  where recipe_id = v_recipe.id;

  if v_ingredient_count = 0 then
    return 'draft';
  end if;

  return 'active';
end;
$$;


ALTER FUNCTION "public"."compute_pos_product_recipe_status"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_recipe_inventory"("p_order_item_id" "text", "p_pos_product_id" "text", "p_quantity" numeric DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  product public.pos_products;
  recipe public.standard_recipes;
  ingredient public.recipe_ingredients;
  prior_consumption public.pos_recipe_consumptions;
  required_quantity numeric;
  stock_before numeric;
  v_eval jsonb;
  v_order_item public.pos_order_items;
begin
  select * into v_order_item
  from public.pos_order_items
  where id::text = trim(p_order_item_id);

  select * into product
  from public.pos_products
  where id::text = trim(p_pos_product_id)
    and active = true;

  if product.id is null then
    raise exception 'Este producto POS no está activo.';
  end if;

  if v_order_item.id is not null then
    v_eval := public.evaluate_pos_inventory_deduction(product, v_order_item);
  elsif public.get_inventory_deduction_mode() = 'disabled'
    or public.is_inventory_migration_mode_active() then
    v_eval := jsonb_build_object('deduct', false, 'reason', 'inventory_disabled');
  elsif not coalesce(product.inventory_tracking_enabled, false) then
    v_eval := jsonb_build_object('deduct', false, 'reason', 'tracking_disabled');
  elsif coalesce(product.recipe_status, 'missing') <> 'active' then
    v_eval := jsonb_build_object('deduct', false, 'reason', 'missing_recipe');
  else
    v_eval := jsonb_build_object('deduct', true, 'reason', null);
  end if;

  if not coalesce((v_eval ->> 'deduct')::boolean, false) then
    return jsonb_build_object(
      'consumed', false,
      'skipped', true,
      'reason', coalesce(v_eval ->> 'reason', 'inventory_disabled'),
      'order_item_id', trim(p_order_item_id)
    );
  end if;

  if not exists (
    select 1 from public.profiles
    where id = auth.uid()
      and status = 'active'
      and role in ('admin', 'gerente_general', 'supervisor', 'mesero')
  ) then
    raise exception 'Usuario no autorizado para enviar comandas.';
  end if;
  if nullif(trim(p_order_item_id), '') is null or nullif(trim(p_pos_product_id), '') is null or p_quantity <= 0 then
    raise exception 'La línea de comanda o cantidad no es válida.';
  end if;

  select * into prior_consumption
  from public.pos_recipe_consumptions
  where order_item_id = trim(p_order_item_id);
  if prior_consumption.id is not null then
    return jsonb_build_object(
      'consumed', false,
      'already_consumed', true,
      'order_item_id', trim(p_order_item_id),
      'recipe_id', prior_consumption.recipe_id,
      'production_area_id', prior_consumption.production_area_id
    );
  end if;

  select * into recipe
  from public.standard_recipes
  where id = product.recipe_id
    and active = true
    and recipe_type = 'final_product';
  if recipe.id is null then
    raise exception 'Este producto no tiene receta estandarizada conectada.';
  end if;
  if product.production_area_id is null or product.production_area_id is distinct from recipe.production_area_id then
    raise exception 'El producto POS no tiene área de producción válida.';
  end if;
  if not exists (select 1 from public.recipe_ingredients where recipe_id = recipe.id) then
    raise exception 'La receta conectada no tiene ingredientes.';
  end if;

  for ingredient in select * from public.recipe_ingredients where recipe_id = recipe.id
  loop
    required_quantity := (ingredient.quantity / recipe.yield_quantity) * p_quantity;
    select quantity into stock_before from public.area_inventory
      where item_id = ingredient.inventory_item_id and area_id = product.production_area_id
      for update;
    stock_before := coalesce(stock_before, 0);
    if stock_before < required_quantity then
      raise exception 'Stock insuficiente para %. Disponible: % %, requerido: % %.',
        ingredient.ingredient_name, stock_before, ingredient.unit, required_quantity, ingredient.unit;
    end if;
  end loop;

  for ingredient in select * from public.recipe_ingredients where recipe_id = recipe.id
  loop
    required_quantity := (ingredient.quantity / recipe.yield_quantity) * p_quantity;
    select quantity into stock_before from public.area_inventory
      where item_id = ingredient.inventory_item_id and area_id = product.production_area_id
      for update;
    update public.area_inventory set quantity = stock_before - required_quantity
      where item_id = ingredient.inventory_item_id and area_id = product.production_area_id;
    insert into public.inventory_movements (
      item_id, movement_type, from_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, source_id, notes, performed_by
    ) values (
      ingredient.inventory_item_id, 'consumption', product.production_area_id,
      required_quantity, ingredient.unit, stock_before, stock_before - required_quantity,
      'pos_order', trim(p_order_item_id),
      'Consumo receta POS: ' || recipe.name, auth.uid()
    );
  end loop;

  insert into public.pos_recipe_consumptions (
    order_item_id, pos_product_id, recipe_id, production_area_id, quantity_sold, consumed_by
  ) values (
    trim(p_order_item_id), product.id::text, recipe.id, product.production_area_id, p_quantity, auth.uid()
  );

  return jsonb_build_object(
    'consumed', true,
    'already_consumed', false,
    'recipe_id', recipe.id,
    'recipe_name', recipe.name,
    'production_area_id', product.production_area_id,
    'pos_product_id', product.id
  );
end;
$$;


ALTER FUNCTION "public"."consume_recipe_inventory"("p_order_item_id" "text", "p_pos_product_id" "text", "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_recruitment_candidate_to_employee"("p_candidate_id" "uuid", "p_profile_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate public.recruitment_candidates;
  v_vacancy public.recruitment_vacancies;
  v_profile public.profiles;
  v_onboarding public.recruitment_onboarding_checklists;
  v_checklist_run public.checklist_runs;
  v_hire_date date;
  v_create_expediente boolean := coalesce((p_payload ->> 'create_expediente')::boolean, true);
  v_create_onboarding boolean := coalesce((p_payload ->> 'create_onboarding')::boolean, true);
  v_template_id uuid;
  v_eval jsonb;
  v_interviews jsonb := '[]'::jsonb;
  v_expediente_notes text;
  v_onboarding_status text := 'employee_created';
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para convertir candidatos.';
  end if;

  if p_profile_id is null then
    raise exception 'profile_id es obligatorio.';
  end if;

  select * into v_candidate from public.recruitment_candidates where id = p_candidate_id for update;
  if v_candidate.id is null then
    raise exception 'Candidato no encontrado.';
  end if;

  if v_candidate.profile_id is not null and v_candidate.profile_id <> p_profile_id then
    raise exception 'Este candidato ya está vinculado a otro colaborador.';
  end if;

  if exists (
    select 1 from public.recruitment_candidates c
    where c.profile_id = p_profile_id and c.id <> p_candidate_id
  ) then
    raise exception 'Este colaborador ya está vinculado a otro candidato.';
  end if;

  if v_candidate.pipeline_status not in ('offer', 'hired') then
    raise exception 'El candidato debe estar en oferta o contratado antes de convertir.';
  end if;

  select * into v_profile from public.profiles where id = p_profile_id;
  if v_profile.id is null then
    raise exception 'Colaborador no encontrado.';
  end if;

  select * into v_vacancy from public.recruitment_vacancies where id = v_candidate.vacancy_id;

  v_hire_date := coalesce(
    nullif(trim(coalesce(p_payload ->> 'hire_date', '')), '')::date,
    v_candidate.hire_date,
    (now() at time zone 'America/Guatemala')::date
  );

  update public.profiles
  set
    role = coalesce(nullif(trim(p_payload ->> 'erp_role'), ''), role),
    area_id = coalesce(nullif(trim(p_payload ->> 'area_id'), ''), area_id),
    area_name = coalesce(nullif(trim(p_payload ->> 'area'), ''), area_name, v_vacancy.area),
    phone = coalesce(nullif(trim(v_candidate.phone), ''), phone),
    employee_id = coalesce(nullif(trim(p_payload ->> 'employee_id'), ''), employee_id),
    status = coalesce(nullif(trim(p_payload ->> 'profile_status'), ''), status),
    updated_at = now()
  where id = p_profile_id;

  if v_candidate.pipeline_status <> 'hired' then
    perform public.hire_recruitment_candidate(p_candidate_id);
    select * into v_candidate from public.recruitment_candidates where id = p_candidate_id;
  end if;

  select coalesce(jsonb_agg(to_jsonb(ev)), '[]'::jsonb)
  into v_eval
  from public.recruitment_interview_evaluations ev
  join public.recruitment_interviews i on i.id = ev.interview_id
  where i.candidate_id = p_candidate_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'scheduled_date', i.scheduled_date,
    'scheduled_time', i.scheduled_time,
    'result', i.result,
    'notes', i.notes
  ) order by i.scheduled_date desc), '[]'::jsonb)
  into v_interviews
  from public.recruitment_interviews i
  where i.candidate_id = p_candidate_id;

  v_expediente_notes := trim(both E'\n' from concat_ws(E'\n',
    nullif(v_candidate.notes, ''),
    nullif(v_candidate.internal_notes, ''),
    'Fuente: ' || coalesce(v_candidate.source, ''),
    'Salario acordado: ' || coalesce(nullif(trim(p_payload ->> 'agreed_salary'), ''), v_candidate.salary_expectation, 'N/D')
  ));

  if v_create_expediente and public.can_write_employee_expedientes() then
    perform public.upsert_employee_expediente_profile(p_profile_id, jsonb_build_object(
      'address', v_candidate.address,
      'personal_email', v_profile.email,
      'job_title', coalesce(nullif(trim(p_payload ->> 'final_position'), ''), v_candidate.position_applied, v_vacancy.position_title),
      'hire_date', v_hire_date,
      'labor_status', 'active',
      'notes', v_expediente_notes
    ));
    v_onboarding_status := 'expediente_created';
  end if;

  insert into public.recruitment_employee_origins (
    profile_id, candidate_id, vacancy_id, source, vacancy_title,
    hire_reason, evaluation_summary, interview_summary, recruitment_notes, created_by
  )
  values (
    p_profile_id,
    p_candidate_id,
    v_vacancy.id,
    v_candidate.source,
    v_vacancy.position_title,
    coalesce(nullif(trim(p_payload ->> 'hire_reason'), ''), v_vacancy.reason),
    coalesce(v_eval, '[]'::jsonb),
    coalesce(v_interviews, '[]'::jsonb),
    v_expediente_notes,
    auth.uid()
  )
  on conflict (profile_id) do update set
    candidate_id = excluded.candidate_id,
    vacancy_id = excluded.vacancy_id,
    source = excluded.source,
    vacancy_title = excluded.vacancy_title,
    hire_reason = excluded.hire_reason,
    evaluation_summary = excluded.evaluation_summary,
    interview_summary = excluded.interview_summary,
    recruitment_notes = excluded.recruitment_notes;

  v_template_id := nullif(trim(coalesce(p_payload ->> 'checklist_template_id', '')), '')::uuid;
  if v_template_id is not null then
    begin
      v_checklist_run := public.create_checklist_run_from_template(
        v_template_id,
        v_hire_date,
        'manual',
        p_profile_id,
        'Onboarding reclutamiento',
        coalesce(nullif(trim(p_payload ->> 'area'), ''), v_vacancy.area),
        coalesce(nullif(trim(p_payload ->> 'erp_role'), ''), v_profile.role)
      );
    exception when others then
      v_checklist_run := null;
    end;
  end if;

  if v_create_onboarding then
    insert into public.recruitment_onboarding_checklists (
      candidate_id, profile_id, status, due_date, created_by
    )
    values (
      p_candidate_id,
      p_profile_id,
      'active',
      v_hire_date + 30,
      auth.uid()
    )
    on conflict (candidate_id) do update set
      profile_id = excluded.profile_id,
      updated_at = now()
    returning * into v_onboarding;

    perform public.recruitment_default_onboarding_tasks(
      v_onboarding.id,
      auth.uid(),
      nullif(trim(coalesce(p_payload ->> 'supervisor_profile_id', '')), '')::uuid,
      v_hire_date
    );

    perform public.recruitment_seed_retention_reviews(p_candidate_id, p_profile_id, v_hire_date);
    v_onboarding_status := 'onboarding_active';

    perform public.recruitment_notify(
      nullif(trim(coalesce(p_payload ->> 'supervisor_profile_id', '')), '')::uuid,
      null,
      'recruitment',
      'Onboarding pendiente',
      'Nuevo colaborador ' || v_candidate.full_name || ' requiere onboarding.',
      'recruitment_onboarding', v_onboarding.id::text,
      '/hr?section=reclutamiento&tab=onboarding'
    );
  end if;

  update public.recruitment_candidates
  set
    profile_id = p_profile_id,
    converted_at = coalesce(converted_at, now()),
    converted_by = auth.uid(),
    onboarding_status = v_onboarding_status,
    hire_date = v_hire_date,
    final_area = coalesce(nullif(trim(p_payload ->> 'area'), ''), v_vacancy.area),
    final_position = coalesce(nullif(trim(p_payload ->> 'final_position'), ''), v_candidate.position_applied, v_vacancy.position_title),
    erp_role = coalesce(nullif(trim(p_payload ->> 'erp_role'), ''), v_profile.role),
    contract_type = nullif(trim(coalesce(p_payload ->> 'contract_type', '')), ''),
    agreed_salary = nullif(trim(coalesce(p_payload ->> 'agreed_salary', '')), ''),
    initial_schedule = nullif(trim(coalesce(p_payload ->> 'initial_schedule'), ''), v_candidate.schedule_availability),
    supervisor_profile_id = nullif(trim(coalesce(p_payload ->> 'supervisor_profile_id', '')), '')::uuid,
    checklist_run_id = coalesce(v_checklist_run.id, checklist_run_id),
    updated_by = auth.uid()
  where id = p_candidate_id
  returning * into v_candidate;

  perform public.recruitment_notify(
    p_profile_id,
    null,
    'recruitment',
    'Bienvenido al equipo',
    'Tu proceso de incorporación ha iniciado.',
    'recruitment_onboarding', coalesce(v_onboarding.id, p_candidate_id)::text,
    '/hr?section=expedientes&profileId=' || p_profile_id::text
  );

  return jsonb_build_object(
    'candidate_id', v_candidate.id,
    'profile_id', p_profile_id,
    'onboarding_status', v_candidate.onboarding_status,
    'onboarding_id', v_onboarding.id,
    'checklist_run_id', v_checklist_run.id,
    'expediente_created', v_create_expediente,
    'retention_seeded', v_create_onboarding
  );
end;
$$;


ALTER FUNCTION "public"."convert_recruitment_candidate_to_employee"("p_candidate_id" "uuid", "p_profile_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_task_step_to_task"("p_step_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_step public.task_steps;
  v_task public.assigned_tasks;
  v_new_id text;
  v_primary uuid;
begin
  select * into v_step
  from public.task_steps s
  where s.id = p_step_id and s.deleted_at is null
  for update;

  if not found then raise exception 'Paso no encontrado.'; end if;
  v_task := public.assert_operational_task_mutable(v_step.task_id);

  select ta.profile_id into v_primary
  from public.task_assignees ta
  where ta.task_id = v_step.task_id
    and ta.status = 'active'
    and ta.assignment_role = 'primary'
  limit 1;

  v_new_id := 'opt-' || replace(gen_random_uuid()::text, '-', '');

  insert into public.assigned_tasks (
    id, title, objective, task_source, status, priority, area_id, created_by, assigned_by
  ) values (
    v_new_id,
    v_step.text,
    v_step.text,
    'operational',
    'pending',
    v_task.priority,
    v_task.area_id,
    auth.uid(),
    auth.uid()
  );

  if v_primary is not null then
    insert into public.task_assignees (task_id, profile_id, assignment_role, assigned_by)
    values (v_new_id, v_primary, 'primary', auth.uid());
    perform public.sync_assigned_tasks_profile_ids(v_new_id);
  end if;

  update public.task_steps
  set converted_task_id = v_new_id, updated_at = now()
  where id = p_step_id;

  perform public.log_task_activity(
    v_step.task_id, 'step_converted', 'work_plan', to_jsonb(v_step.text),
    to_jsonb(v_new_id), jsonb_build_object('step_id', p_step_id)
  );

  return jsonb_build_object(
    'source_task', public.get_operational_task_detail(v_step.task_id),
    'new_task_id', v_new_id
  );
end;
$$;


ALTER FUNCTION "public"."convert_task_step_to_task"("p_step_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_fixed_costs_from_previous_month"("p_target_month" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_target date := public.normalize_fixed_cost_month(coalesce(p_target_month, current_date));
  v_source date := (v_target - interval '1 month')::date;
  v_inserted integer := 0;
begin
  if not public.can_manage_fixed_costs() then
    raise exception 'No tienes permiso para gestionar costos fijos.';
  end if;

  insert into public.fixed_costs (
    name, category, amount, frequency, cost_month, due_day,
    payment_status, notes, is_active, created_by, updated_by
  )
  select
    src.name,
    src.category,
    src.amount,
    src.frequency,
    v_target,
    src.due_day,
    'pending',
    src.notes,
    true,
    auth.uid(),
    auth.uid()
  from public.fixed_costs src
  where src.cost_month = v_source
    and src.is_active = true
    and not exists (
      select 1
      from public.fixed_costs existing
      where existing.cost_month = v_target
        and existing.is_active = true
        and lower(existing.name) = lower(src.name)
        and existing.category = src.category
    );

  get diagnostics v_inserted = row_count;

  return jsonb_build_object(
    'target_month', v_target,
    'source_month', v_source,
    'copied_count', v_inserted
  );
end;
$$;


ALTER FUNCTION "public"."copy_fixed_costs_from_previous_month"("p_target_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_failed_login_attempts"("p_email" "text" DEFAULT NULL::"text", "p_ip" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*)::integer
  from public.security_login_attempts attempt
  where attempt.success = false
    and attempt.created_at >= now() - make_interval(mins => public.login_security_window_minutes())
    and (
      (p_email is not null and lower(attempt.email_attempted) = lower(trim(p_email)))
      or (p_ip is not null and nullif(trim(p_ip), '') is not null and attempt.ip_address = nullif(trim(p_ip), ''))
    );
$$;


ALTER FUNCTION "public"."count_failed_login_attempts"("p_email" "text", "p_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_profiles_with_role"("p_role_key" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*)::integer
  from public.profiles
  where role = p_role_key
    and status <> 'inactive';
$$;


ALTER FUNCTION "public"."count_profiles_with_role"("p_role_key" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bakery_dough_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_code" "text" NOT NULL,
    "dough_type" "text" NOT NULL,
    "recipe_id" "uuid",
    "quantity_units" numeric NOT NULL,
    "unit_weight" numeric,
    "total_weight" numeric,
    "mixed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cold_room_started_at" timestamp with time zone,
    "status" "text" DEFAULT 'mixed'::"text" NOT NULL,
    "responsible_user_id" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bakery_dough_batches_quantity_units_check" CHECK (("quantity_units" > (0)::numeric)),
    CONSTRAINT "bakery_dough_batches_status_check" CHECK (("status" = ANY (ARRAY['mixed'::"text", 'resting'::"text", 'balled'::"text", 'cold_room'::"text", 'ready'::"text", 'used'::"text", 'discarded'::"text"]))),
    CONSTRAINT "bakery_dough_batches_total_weight_check" CHECK ((("total_weight" IS NULL) OR ("total_weight" >= (0)::numeric))),
    CONSTRAINT "bakery_dough_batches_unit_weight_check" CHECK ((("unit_weight" IS NULL) OR ("unit_weight" > (0)::numeric)))
);


ALTER TABLE "public"."bakery_dough_batches" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_bakery_dough_batch"("p_payload" "jsonb") RETURNS "public"."bakery_dough_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.bakery_dough_batches;
  v_dough_type text := nullif(trim(p_payload ->> 'dough_type'), '');
  v_units numeric := nullif(p_payload ->> 'quantity_units', '')::numeric;
begin
  if not public.can_operate_bakery_production() then
    raise exception 'PERMISSION_DENIED';
  end if;
  if v_dough_type is null then
    raise exception 'Indica el tipo de masa.';
  end if;
  if coalesce(v_units, 0) <= 0 then
    raise exception 'La cantidad de unidades debe ser mayor que cero.';
  end if;

  insert into public.bakery_dough_batches (
    batch_code, dough_type, recipe_id, quantity_units, unit_weight, total_weight,
    mixed_at, status, responsible_user_id, notes
  )
  values (
    public.next_bakery_dough_batch_code(v_dough_type),
    v_dough_type,
    nullif(p_payload ->> 'recipe_id', '')::uuid,
    v_units,
    nullif(p_payload ->> 'unit_weight', '')::numeric,
    nullif(p_payload ->> 'total_weight', '')::numeric,
    coalesce(nullif(p_payload ->> 'mixed_at', '')::timestamptz, now()),
    coalesce(nullif(trim(p_payload ->> 'status'), ''), 'mixed'),
    coalesce(nullif(p_payload ->> 'responsible_user_id', '')::uuid, auth.uid()),
    nullif(trim(p_payload ->> 'notes'), '')
  )
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."create_bakery_dough_batch"("p_payload" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."cash_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "cash_session_id" "uuid" NOT NULL,
    "cash_register_id" "uuid" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "authorized_by" "uuid",
    "movement_type" "text" NOT NULL,
    "amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "reason" "text",
    "order_id" "uuid",
    "reference" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cash_movements_movement_type_check" CHECK (("movement_type" = ANY (ARRAY['sale_cash'::"text", 'withdrawal'::"text", 'deposit'::"text", 'refund'::"text", 'adjustment'::"text", 'manual_open'::"text", 'shift_open'::"text", 'shift_close'::"text"])))
);


ALTER TABLE "public"."cash_movements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_cash_movement"("p_cash_session_id" "uuid", "p_movement_type" "text", "p_amount" numeric, "p_reason" "text", "p_reference" "text" DEFAULT NULL::"text", "p_order_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."cash_movements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.cash_sessions;
  actor_role text;
  saved public.cash_movements;
  allowed_for_cashier text[] := array['deposit', 'sale_cash', 'refund'];
begin
  if not public.is_cash_operator() then
    raise exception 'No tienes permiso para operar caja.';
  end if;

  select * into session_row
  from public.cash_sessions
  where id = p_cash_session_id
  for update;
  if session_row.id is null or session_row.status <> 'open' then
    raise exception 'No hay caja abierta.';
  end if;
  if p_movement_type not in ('sale_cash', 'withdrawal', 'deposit', 'refund', 'adjustment', 'manual_open') then
    raise exception 'Tipo de movimiento invalido.';
  end if;

  select public.normalize_profile_role(role) into actor_role
  from public.profiles
  where id = auth.uid();

  if actor_role in ('cajero', 'caja') and not (p_movement_type = any(allowed_for_cashier)) then
    raise exception 'Este movimiento requiere supervisor, Admin o Gerente General.';
  end if;
  if p_movement_type in ('withdrawal', 'manual_open', 'adjustment') and not public.is_cash_supervisor() then
    raise exception 'Este movimiento requiere supervisor, Admin o Gerente General.';
  end if;
  if p_movement_type in ('withdrawal', 'deposit', 'refund', 'adjustment', 'manual_open')
    and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'El motivo es obligatorio.';
  end if;

  insert into public.cash_movements (
    cash_session_id, cash_register_id, created_by, authorized_by, movement_type,
    amount, reason, reference, order_id
  ) values (
    session_row.id, session_row.cash_register_id, auth.uid(),
    case when public.is_cash_supervisor() then auth.uid() else null end,
    p_movement_type,
    coalesce(p_amount, 0)::numeric(12,2),
    nullif(trim(coalesce(p_reason, '')), ''),
    nullif(trim(coalesce(p_reference, '')), ''),
    p_order_id
  ) returning * into saved;

  update public.cash_sessions
  set expected_cash = public.calculate_cash_expected(session_row.id),
      updated_at = now()
  where id = session_row.id;

  return saved;
end;
$$;


ALTER FUNCTION "public"."create_cash_movement"("p_cash_session_id" "uuid", "p_movement_type" "text", "p_amount" numeric, "p_reason" "text", "p_reference" "text", "p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_catering_quote"("p_request_id" "uuid", "p_items" "jsonb", "p_discount_amount" numeric DEFAULT 0, "p_valid_until" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text", "p_terms" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.catering_requests;
  v_quote public.catering_quotes;
  v_totals jsonb;
  v_item jsonb;
  v_sort integer := 0;
  v_quote_number text;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para crear cotizaciones de catering.';
  end if;

  if p_request_id is null then
    raise exception 'p_request_id es obligatorio.';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Debes incluir al menos una linea en la cotizacion.';
  end if;

  select * into v_request from public.catering_requests where id = p_request_id;
  if not found then
    raise exception 'Solicitud de catering no encontrada.';
  end if;

  v_totals := public.catering_quote_totals(p_items, p_discount_amount);
  v_quote_number := public.next_catering_quote_number();

  insert into public.catering_quotes (
    request_id, quote_number, status, subtotal, discount_amount, tax_amount, total,
    valid_until, notes, terms, created_by
  )
  values (
    p_request_id, v_quote_number, 'draft',
    (v_totals ->> 'subtotal')::numeric,
    (v_totals ->> 'discount_amount')::numeric,
    0,
    (v_totals ->> 'total')::numeric,
    p_valid_until,
    nullif(trim(coalesce(p_notes, '')), ''),
    nullif(trim(coalesce(p_terms, '')), ''),
    auth.uid()
  )
  returning * into v_quote;

  for v_item in select value from jsonb_array_elements(p_items) as value loop
    v_sort := v_sort + 1;
    insert into public.catering_quote_items (
      quote_id, item_type, description, quantity, quantity_unit, unit_price, total_price, sort_order,
      line_kind, option_group_name, option_label, is_selected_option
    )
    values (
      v_quote.id,
      coalesce(nullif(trim(v_item ->> 'item_type'), ''), 'other'),
      trim(v_item ->> 'description'),
      coalesce(nullif(v_item ->> 'quantity', '')::numeric, 1),
      coalesce(nullif(trim(v_item ->> 'quantity_unit'), ''), 'unidades'),
      coalesce(nullif(v_item ->> 'unit_price', '')::numeric, 0),
      round(coalesce(nullif(v_item ->> 'quantity', '')::numeric, 1) * coalesce(nullif(v_item ->> 'unit_price', '')::numeric, 0), 2),
      coalesce(nullif(v_item ->> 'sort_order', '')::integer, v_sort),
      coalesce(nullif(trim(v_item ->> 'line_kind'), ''), 'normal'),
      nullif(trim(coalesce(v_item ->> 'option_group_name', '')), ''),
      nullif(trim(coalesce(v_item ->> 'option_label', '')), ''),
      coalesce((v_item ->> 'is_selected_option')::boolean, false)
    );
  end loop;

  perform public.log_catering_activity(
    v_quote.request_id, 'quote_created',
    'Cotizacion ' || v_quote.quote_number || ' creada',
    jsonb_build_object('quote_id', v_quote.id, 'quote_number', v_quote.quote_number, 'total', v_quote.total)
  );

  return public.get_catering_quote_detail(v_quote.id);
end;
$$;


ALTER FUNCTION "public"."create_catering_quote"("p_request_id" "uuid", "p_items" "jsonb", "p_discount_amount" numeric, "p_valid_until" "date", "p_notes" "text", "p_terms" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_catering_request"("p_data" "jsonb") RETURNS "public"."catering_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_customer_name text := nullif(trim(coalesce(p_data ->> 'customer_name', '')), '');
  v_phone text := nullif(trim(coalesce(p_data ->> 'customer_phone', '')), '');
  v_email text := nullif(trim(coalesce(p_data ->> 'customer_email', '')), '');
  v_source text := coalesce(nullif(trim(coalesce(p_data ->> 'source', '')), ''), 'wix_form');
  v_lead_source text;
  v_guest_count integer;
  v_is_manual boolean := v_source = 'manual';
  v_row public.catering_requests;
  v_activity_type text;
  v_activity_description text;
begin
  if auth.uid() is not null and not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para crear solicitudes de catering.';
  end if;

  if v_customer_name is null then
    raise exception 'customer_name es obligatorio.';
  end if;

  v_lead_source := public.normalize_catering_lead_source(
    coalesce(p_data ->> 'lead_source', ''),
    v_source
  );

  if v_is_manual then
    if v_phone is null and v_email is null then
      raise exception 'Debes indicar telefono o correo del cliente.';
    end if;

    if nullif(p_data ->> 'guest_count', '') is not null then
      v_guest_count := nullif(p_data ->> 'guest_count', '')::integer;
      if v_guest_count is not null and v_guest_count <= 0 then
        raise exception 'guest_count debe ser mayor a 0.';
      end if;
    end if;
  end if;

  insert into public.catering_requests (
    customer_name,
    customer_phone,
    customer_email,
    event_date,
    event_time,
    event_location,
    event_type,
    guest_count,
    products_requested,
    notes,
    status,
    source,
    lead_source,
    assigned_to,
    follow_up_date,
    estimated_value,
    win_probability,
    conversion_status,
    created_by,
    updated_by
  )
  values (
    v_customer_name,
    v_phone,
    v_email,
    nullif(p_data ->> 'event_date', '')::date,
    nullif(p_data ->> 'event_time', '')::time,
    nullif(trim(coalesce(p_data ->> 'event_location', '')), ''),
    nullif(trim(coalesce(p_data ->> 'event_type', '')), ''),
    coalesce(
      v_guest_count,
      nullif(p_data ->> 'guest_count', '')::integer
    ),
    coalesce(
      (
        select array_agg(value)
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(p_data -> 'products_requested') = 'array' then p_data -> 'products_requested'
            else '[]'::jsonb
          end
        ) as value
        where nullif(trim(value), '') is not null
      ),
      '{}'::text[]
    ),
    nullif(trim(coalesce(p_data ->> 'notes', '')), ''),
    'new',
    v_source,
    v_lead_source,
    nullif(p_data ->> 'assigned_to', '')::uuid,
    nullif(p_data ->> 'follow_up_date', '')::date,
    nullif(p_data ->> 'estimated_value', '')::numeric(12, 2),
    nullif(p_data ->> 'win_probability', '')::integer,
    'lead',
    auth.uid(),
    auth.uid()
  )
  returning * into v_row;

  if v_is_manual then
    v_activity_type := 'lead_created_manual';
    v_activity_description := 'Lead creado manualmente';
  else
    v_activity_type := 'lead_received';
    v_activity_description := 'Lead recibido';
  end if;

  perform public.log_catering_activity(
    v_row.id,
    v_activity_type,
    v_activity_description,
    jsonb_build_object(
      'source', v_row.source,
      'lead_source', v_row.lead_source,
      'manual', v_is_manual
    ),
    v_row.created_by,
    v_row.created_at
  );
  perform public.notify_new_catering_request(v_row.id);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."create_catering_request"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_checklist_management_alert"("p_checklist_run_id" "uuid", "p_priority" "text", "p_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_record public.checklist_runs;
  template_record public.checklist_templates;
  sender_record public.profiles;
  alert_record public.checklist_management_alerts;
  trimmed_message text;
  normalized_priority text;
  sender_name text;
  template_title text;
  notification_warning text := null;
  role_value text;
begin
  if auth.uid() is null then
    raise exception 'Debes iniciar sesion para enviar un aviso.';
  end if;

  trimmed_message := trim(coalesce(p_message, ''));
  if char_length(trimmed_message) < 10 then
    raise exception 'El aviso debe tener al menos 10 caracteres.';
  end if;
  if char_length(trimmed_message) > 1000 then
    raise exception 'El aviso no puede superar 1000 caracteres.';
  end if;

  normalized_priority := lower(trim(coalesce(p_priority, 'informativo')));
  if normalized_priority not in ('informativo', 'atencion', 'critico') then
    raise exception 'Prioridad de aviso no valida.';
  end if;

  select * into run_record
  from public.checklist_runs
  where id = p_checklist_run_id;

  if run_record.id is null then
    raise exception 'La checklist asignada no existe.';
  end if;

  if not public.can_access_checklist_run(run_record) then
    raise exception 'No tienes permiso para enviar avisos en esta checklist.';
  end if;

  if run_record.status = 'cancelled' then
    raise exception 'No se pueden enviar avisos en checklists canceladas.';
  end if;

  select * into template_record
  from public.checklist_templates
  where id = run_record.template_id;

  select * into sender_record
  from public.profiles
  where id = auth.uid()
    and status = 'active';

  if sender_record.id is null then
    raise exception 'Perfil de usuario no valido.';
  end if;

  insert into public.checklist_management_alerts (
    checklist_run_id,
    checklist_template_id,
    sender_profile_id,
    priority,
    message,
    status
  )
  values (
    run_record.id,
    run_record.template_id,
    auth.uid(),
    normalized_priority,
    trimmed_message,
    'open'
  )
  returning * into alert_record;

  sender_name := coalesce(nullif(trim(sender_record.full_name), ''), nullif(trim(sender_record.username), ''), 'Colaborador');
  template_title := coalesce(nullif(trim(template_record.title), ''), 'Checklist');

  begin
    foreach role_value in array array['admin', 'gerente_general']
    loop
      insert into public.notifications (
        user_id,
        target_role,
        type,
        title,
        message,
        entity_type,
        entity_id,
        action_url,
        created_by
      )
      values (
        null,
        role_value,
        'checklist_management_alert',
        'Aviso desde checklist',
        sender_name || ' reporto un aviso en ' || template_title || '.',
        'checklist_management_alert',
        alert_record.id::text,
        '/tasks?tab=checklists&view=run&id=' || run_record.id::text,
        auth.uid()
      );
    end loop;
  exception
    when others then
      notification_warning := 'El aviso se guardo, pero no se pudieron crear todas las notificaciones.';
  end;

  return jsonb_build_object(
    'alert', to_jsonb(alert_record),
    'notification_warning', notification_warning
  );
end;
$$;


ALTER FUNCTION "public"."create_checklist_management_alert"("p_checklist_run_id" "uuid", "p_priority" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_checklist_run_from_template"("p_template_id" "uuid", "p_run_date" "date", "p_assignment_source" "text", "p_assigned_profile_id" "uuid", "p_notes" "text") RETURNS "public"."checklist_runs"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.create_checklist_run_from_template(
    p_template_id,
    p_run_date,
    p_assignment_source,
    p_assigned_profile_id,
    p_notes,
    null,
    null
  );
$$;


ALTER FUNCTION "public"."create_checklist_run_from_template"("p_template_id" "uuid", "p_run_date" "date", "p_assignment_source" "text", "p_assigned_profile_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_checklist_run_from_template"("p_template_id" "uuid", "p_run_date" "date" DEFAULT "public"."get_checklist_operational_date"(), "p_assignment_source" "text" DEFAULT 'manual'::"text", "p_assigned_profile_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_area" "text" DEFAULT NULL::"text", "p_assigned_role" "text" DEFAULT NULL::"text") RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  template_row public.checklist_templates;
  existing_run public.checklist_runs;
  created_run public.checklist_runs;
  effective_profile_id uuid;
  original_profile_id uuid;
  effective_area text;
  effective_role text;
begin
  select * into template_row
  from public.checklist_templates
  where id = p_template_id
    and status = 'active';

  if template_row.id is null then
    raise exception 'La plantilla no existe o esta inactiva.';
  end if;

  if not public.can_access_checklists() then
    raise exception 'No tienes permiso para crear checklists.';
  end if;

  perform public.checklist_run_template_date_lock(template_row.id, p_run_date);

  select * into existing_run
  from public.checklist_runs
  where template_id = template_row.id
    and run_date = p_run_date
    and status <> 'cancelled'
  order by created_at asc
  limit 1
  for update;

  if existing_run.id is not null then
    return existing_run;
  end if;

  original_profile_id := coalesce(p_assigned_profile_id, template_row.assigned_profile_id);
  effective_profile_id := original_profile_id;
  effective_area := nullif(trim(coalesce(p_area, template_row.area, '')), '');
  effective_role := nullif(trim(coalesce(p_assigned_role, template_row.assigned_role, '')), '');

  if template_row.skip_non_work_days
    and effective_profile_id is not null
    and not public.is_profile_scheduled_to_work(effective_profile_id, p_run_date)
  then
    if template_row.backup_profile_id is not null
      and template_row.backup_profile_id <> effective_profile_id
      and public.is_profile_scheduled_to_work(template_row.backup_profile_id, p_run_date)
    then
      effective_profile_id := template_row.backup_profile_id;
    end if;
  end if;

  insert into public.checklist_runs (
    template_id, run_date, area, assigned_profile_id, assigned_role, status,
    total_points, earned_points, notes, supervisor_profile_id, reminder_time,
    due_time, assignment_source, original_assigned_profile_id
  )
  values (
    template_row.id, p_run_date, effective_area, effective_profile_id,
    effective_role, 'pending',
    coalesce((
      select sum(score_points)::integer
      from public.checklist_template_items
      where template_id = template_row.id
        and is_active = true
    ), 0),
    0, nullif(trim(coalesce(p_notes, '')), ''), template_row.supervisor_profile_id,
    template_row.reminder_time, template_row.due_time, coalesce(p_assignment_source, 'manual'),
    original_profile_id
  )
  on conflict (template_id, run_date) where (status <> 'cancelled')
  do nothing
  returning * into created_run;

  if created_run.id is null then
    select * into existing_run
    from public.checklist_runs
    where template_id = template_row.id
      and run_date = p_run_date
      and status <> 'cancelled'
    order by created_at asc
    limit 1;

    if existing_run.id is not null then
      return existing_run;
    end if;

    raise exception 'No se pudo crear ni recuperar la corrida de checklist.';
  end if;

  insert into public.checklist_run_items (
    run_id, template_item_id, item_order, title, response_type, is_required,
    requires_photo, requires_comment, score_points, options,
    require_comment_on_no, require_photo_on_no, generate_incident_on_no, rule_config,
    expected_response, triggers_incident, incident_severity, notify_roles, create_task_on_fail
  )
  select
    created_run.id, item.id, item.item_order, item.title, item.response_type,
    item.is_required, item.requires_photo, item.requires_comment, item.score_points,
    item.options, item.require_comment_on_no, item.require_photo_on_no,
    item.generate_incident_on_no, item.rule_config, item.expected_response,
    item.triggers_incident, item.incident_severity, item.notify_roles, item.create_task_on_fail
  from public.checklist_template_items item
  where item.template_id = template_row.id
    and item.is_active = true
  order by item.item_order;

  if coalesce(p_assignment_source, 'manual') <> 'recurrence' then
    begin
      perform public.create_checklist_run_notifications(created_run.id);
    exception
      when others then
        raise warning 'create_checklist_run_notifications failed for run %: %', created_run.id, sqlerrm;
    end;
  end if;

  return created_run;
end;
$$;


ALTER FUNCTION "public"."create_checklist_run_from_template"("p_template_id" "uuid", "p_run_date" "date", "p_assignment_source" "text", "p_assigned_profile_id" "uuid", "p_notes" "text", "p_area" "text", "p_assigned_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_checklist_run_notifications"("p_run_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_role text := public.current_profile_role();
  run_record public.checklist_runs;
  template_title text;
  inserted_count integer := 0;
begin
  if public.normalize_profile_role(actor_role) not in ('admin', 'gerente_general', 'gerente', 'supervisor') then
    raise exception 'No tienes permiso para generar notificaciones de checklist.';
  end if;

  select * into run_record
  from public.checklist_runs
  where id = p_run_id;

  if run_record.id is null then
    raise exception 'Checklist no encontrada.';
  end if;

  select title into template_title
  from public.checklist_templates
  where id = run_record.template_id;

  with recipients as (
    select distinct p.id
    from public.profiles p
    where p.status = 'active'
      and (
        (run_record.assigned_profile_id is not null and p.id = run_record.assigned_profile_id)
        or (
          run_record.assigned_profile_id is null
          and nullif(trim(coalesce(run_record.assigned_role, '')), '') is not null
          and public.normalize_profile_role(p.role) = public.normalize_profile_role(run_record.assigned_role)
        )
        or (
          run_record.assigned_profile_id is null
          and nullif(trim(coalesce(run_record.assigned_role, '')), '') is null
          and nullif(trim(coalesce(run_record.area, '')), '') is not null
          and (
            nullif(trim(coalesce(p.area_name, '')), '') = nullif(trim(coalesce(run_record.area, '')), '')
            or nullif(trim(coalesce(p.area_id, '')), '') = nullif(trim(coalesce(run_record.area, '')), '')
          )
        )
      )
  ),
  inserted as (
    insert into public.notifications (
      user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
    )
    select
      recipients.id,
      null,
      'checklist',
      'Checklist asignada',
      'Se te asigno la checklist: ' || coalesce(template_title, 'Checklist'),
      'checklist_run',
      run_record.id::text,
      '/tasks?tab=checklists&view=run&id=' || run_record.id::text,
      auth.uid()
    from recipients
    where not exists (
      select 1
      from public.notifications n
      where n.user_id = recipients.id
        and n.type = 'checklist'
        and n.entity_type = 'checklist_run'
        and n.entity_id = run_record.id::text
    )
    returning 1
  )
  select count(*) into inserted_count from inserted;

  return inserted_count;
end;
$$;


ALTER FUNCTION "public"."create_checklist_run_notifications"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_draft_requisition_with_current_config"("p_header" "jsonb", "p_items" "jsonb", "p_provenance" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requester public.profiles;
  requester_id uuid := coalesce(
    nullif(p_header ->> 'requested_by_profile_id', '')::uuid,
    auth.uid()
  );
  from_id text := nullif(trim(p_header ->> 'from_area_id'), '');
  to_id text := nullif(trim(p_header ->> 'to_area_id'), '');
  priority text := coalesce(nullif(trim(p_header ->> 'priority'), ''), 'normal');
  header_notes text := nullif(trim(p_header ->> 'notes'), '');
  trace_message text := nullif(trim(p_provenance ->> 'trace_message'), '');
  is_test_flow boolean := coalesce((p_header ->> 'is_test')::boolean, false);
  creation_source text := coalesce(nullif(trim(p_provenance ->> 'creation_source'), ''), 'manual');
  generation_mode text := nullif(trim(p_provenance ->> 'generation_mode'), '');
  source_requisition_id uuid := nullif(p_provenance ->> 'source_requisition_id', '')::uuid;
  source_template_id uuid := nullif(p_provenance ->> 'source_template_id', '')::uuid;
  source_rule_id uuid := nullif(p_provenance ->> 'source_rule_id', '')::uuid;
  combined_notes text := header_notes;
  created public.requisitions;
  row_data jsonb;
  catalog_item public.inventory_items;
  requested_qty numeric;
  requested_unit text;
  conversion_factor numeric;
  converted_qty numeric;
  source_stock numeric;
  source_minimum numeric;
  availability text;
  items_copied integer := 0;
  items_skipped integer := 0;
  warnings jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(p_items) is distinct from 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'Debes indicar al menos un producto para generar la requisicion.';
  end if;

  if is_test_flow and not public.can_create_test_flow() then
    raise exception 'Solo Administracion puede crear pruebas de flujo.';
  end if;

  perform public.assert_requisition_request_permissions(from_id, to_id, requester_id);

  select * into requester
  from public.profiles
  where id = requester_id
    and status = 'active';

  if requester.id is null then
    raise exception 'Selecciona quien esta haciendo la requisicion.';
  end if;

  if trace_message is not null then
    combined_notes := case
      when combined_notes is null then trace_message
      else combined_notes || E'\n\n' || trace_message
    end;
  end if;

  insert into public.requisitions (
    requisition_number,
    requested_by,
    requested_by_profile_id,
    requested_by_name,
    requested_by_role,
    from_area_id,
    to_area_id,
    priority,
    notes,
    status,
    is_test,
    creation_source,
    source_requisition_id,
    source_template_id,
    source_rule_id,
    generation_mode,
    generated_at,
    generated_by
  )
  values (
    public.next_requisition_number(),
    auth.uid(),
    requester.id,
    coalesce(requester.full_name, requester.username),
    requester.role,
    from_id,
    to_id,
    priority,
    combined_notes,
    'draft',
    is_test_flow,
    creation_source,
    source_requisition_id,
    source_template_id,
    source_rule_id,
    generation_mode,
    now(),
    auth.uid()
  )
  returning * into created;

  for row_data in select value from jsonb_array_elements(p_items)
  loop
    select * into catalog_item
    from public.inventory_items
    where id = nullif(row_data ->> 'item_id', '')::uuid;

    if catalog_item.id is null or coalesce(catalog_item.active, false) = false then
      items_skipped := items_skipped + 1;
      warnings := warnings || jsonb_build_array(jsonb_build_object(
        'item_id', nullif(row_data ->> 'item_id', '')::uuid,
        'item_name', coalesce(row_data ->> 'item_name', catalog_item.name, 'Producto'),
        'reason', 'producto_inactivo',
        'message', coalesce(row_data ->> 'item_name', catalog_item.name, 'Producto') || ' esta inactivo o ya no existe.'
      ));
      continue;
    end if;

    requested_qty := coalesce(nullif(row_data ->> 'requested_quantity', '')::numeric, 0);

    if requested_qty <= 0 then
      items_skipped := items_skipped + 1;
      warnings := warnings || jsonb_build_array(jsonb_build_object(
        'item_id', catalog_item.id,
        'item_name', catalog_item.name,
        'reason', 'sin_cantidad_pendiente',
        'message', catalog_item.name || ' no tiene cantidad valida para copiar.'
      ));
      continue;
    end if;

    requested_unit := coalesce(
      nullif(trim(row_data ->> 'requested_unit'), ''),
      nullif(trim(catalog_item.default_requisition_unit), ''),
      catalog_item.base_unit
    );

    if not public.has_item_requisition_unit_conversion(catalog_item.id, requested_unit) then
      items_skipped := items_skipped + 1;
      warnings := warnings || jsonb_build_array(jsonb_build_object(
        'item_id', catalog_item.id,
        'item_name', catalog_item.name,
        'reason', 'sin_conversion',
        'message', 'No existe conversion configurada para ' || catalog_item.name || ' en la unidad ' || requested_unit || '.'
      ));
      continue;
    end if;

    conversion_factor := public.resolve_item_requisition_unit_factor(catalog_item.id, requested_unit);
    converted_qty := requested_qty * conversion_factor;

    select quantity, minimum_quantity
    into source_stock, source_minimum
    from public.area_inventory
    where item_id = catalog_item.id
      and area_id = from_id;

    source_stock := coalesce(source_stock, 0);
    source_minimum := coalesce(source_minimum, 0);
    availability := case
      when source_stock <= 0 then 'Sin stock'
      when source_stock < converted_qty then 'Parcial'
      else 'Disponible'
    end;

    insert into public.requisition_items (
      requisition_id,
      item_id,
      item_name,
      unit,
      requested_quantity,
      approved_quantity,
      requested_unit,
      conversion_factor,
      converted_requested_quantity,
      availability_status,
      stock_available_at_request,
      stock_minimum_at_request,
      conversion_warning,
      notes,
      is_test,
      inventory_base_unit_at_request
    ) values (
      created.id,
      catalog_item.id,
      catalog_item.name,
      requested_unit,
      requested_qty,
      null,
      requested_unit,
      conversion_factor,
      converted_qty,
      availability,
      source_stock,
      source_minimum,
      false,
      nullif(trim(row_data ->> 'notes'), ''),
      is_test_flow,
      catalog_item.base_unit
    );

    items_copied := items_copied + 1;
  end loop;

  if items_copied = 0 then
    delete from public.requisitions where id = created.id;
    raise exception 'No se pudo copiar ningun producto. Revisa los productos inactivos o sin conversion valida.';
  end if;

  return jsonb_build_object(
    'new_requisition_id', created.id,
    'requisition_number', created.requisition_number,
    'items_copied', items_copied,
    'items_skipped', items_skipped,
    'warnings', warnings,
    'creation_source', creation_source,
    'generation_mode', generation_mode,
    'source_requisition_id', source_requisition_id,
    'source_template_id', source_template_id,
    'source_rule_id', source_rule_id
  );
end;
$$;


ALTER FUNCTION "public"."create_draft_requisition_with_current_config"("p_header" "jsonb", "p_items" "jsonb", "p_provenance" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_finance_bank_account"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.finance_bank_accounts;
  v_opening numeric := coalesce((p_data ->> 'opening_balance')::numeric, 0);
begin
  if not public.can_manage_finance() then
    raise exception 'No tienes permiso para configurar cuentas bancarias.';
  end if;

  insert into public.finance_bank_accounts (
    name, bank_name, account_number, currency, opening_balance, current_balance, created_by
  )
  values (
    trim(p_data ->> 'name'),
    coalesce(trim(p_data ->> 'bank_name'), ''),
    coalesce(trim(p_data ->> 'account_number'), ''),
    coalesce(nullif(trim(p_data ->> 'currency'), ''), 'GTQ'),
    v_opening,
    v_opening,
    auth.uid()
  )
  returning * into v_row;

  return to_jsonb(v_row);
end;
$$;


