CREATE OR REPLACE FUNCTION "public"."create_login_security_notification"("p_type" "text", "p_title" "text", "p_message" "text", "p_entity_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_role text;
begin
  foreach target_role in array array['admin', 'gerente_general']
  loop
    insert into public.notifications (
      user_id,
      target_role,
      type,
      title,
      message,
      entity_type,
      entity_id,
      action_url
    )
    select
      null,
      target_role,
      p_type,
      p_title,
      p_message,
      'security_login',
      p_entity_id,
      '/settings?tab=login-security'
    where not exists (
      select 1
      from public.notifications notification
      where notification.type = p_type
        and notification.entity_type = 'security_login'
        and coalesce(notification.entity_id, '') = coalesce(p_entity_id, '')
        and notification.created_at >= now() - make_interval(mins => public.login_security_window_minutes())
    );
  end loop;
end;
$$;


