CREATE OR REPLACE FUNCTION "public"."create_operational_task"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_title text := trim(coalesce(p_data ->> 'title', ''));
  v_description text := coalesce(p_data ->> 'description', '');
  v_area_id text := nullif(trim(coalesce(p_data ->> 'area_id', '')), '');
  v_category text := nullif(trim(coalesce(p_data ->> 'category', '')), '');
  v_priority text := coalesce(nullif(trim(p_data ->> 'priority'), ''), 'medium');
  v_difficulty text := nullif(trim(coalesce(p_data ->> 'difficulty', '')), '');
  v_due_at timestamptz := nullif(p_data ->> 'due_at', '')::timestamptz;
  v_evidence_required boolean := coalesce((p_data ->> 'evidence_required')::boolean, false);
  v_simple_steps jsonb := coalesce(p_data -> 'simple_steps', '[]'::jsonb);
  v_assignee_ids uuid[];
  v_assignee uuid;
  v_task_id text;
  v_task public.assigned_tasks;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if v_title = '' then
    raise exception 'El título es obligatorio.';
  end if;

  if v_priority not in ('low', 'medium', 'high', 'critical') then
    raise exception 'Prioridad inválida.';
  end if;

  select coalesce(array_agg(distinct value::uuid), '{}'::uuid[])
  into v_assignee_ids
  from jsonb_array_elements_text(coalesce(p_data -> 'assignee_ids', '[]'::jsonb)) as value
  where nullif(trim(value), '') is not null;

  if coalesce(array_length(v_assignee_ids, 1), 0) = 0 then
    v_assignee_ids := array[auth.uid()];
  end if;

  foreach v_assignee in array v_assignee_ids loop
    if not public.can_assign_profile_to_operational_task(v_assignee) then
      raise exception 'No tienes permiso para asignar a uno de los colaboradores.';
    end if;
  end loop;

  v_task_id := 'opt-' || gen_random_uuid()::text;

  insert into public.assigned_tasks (
    id, title, description, status, task_source, area_id, category,
    priority, difficulty, due_at, due_date, evidence_required, simple_steps,
    created_by, assigned_by
  )
  values (
    v_task_id,
    v_title,
    v_description,
    'pending',
    'operational',
    v_area_id,
    v_category,
    v_priority,
    v_difficulty,
    v_due_at,
    case when v_due_at is null then null else v_due_at::date end,
    v_evidence_required,
    v_simple_steps,
    auth.uid(),
    auth.uid()
  )
  returning * into v_task;

  foreach v_assignee in array v_assignee_ids loop
    insert into public.task_assignees (
      task_id, profile_id, assignment_role, assigned_by
    )
    values (
      v_task_id,
      v_assignee,
      case when v_assignee = v_assignee_ids[1] then 'primary' else 'participant' end,
      auth.uid()
    );
  end loop;

  perform public.log_task_activity(
    v_task_id,
    'created',
    null,
    null,
    jsonb_build_object('title', v_title, 'status', 'pending'),
    jsonb_build_object('mode', 'full')
  );

  return public.operational_task_row(v_task);
end;
$$;


ALTER FUNCTION "public"."create_operational_task"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_operational_task_quick"("p_title" "text", "p_assignee_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "text" DEFAULT NULL::"text", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_title text := trim(coalesce(p_title, ''));
  v_assignee uuid := coalesce(p_assignee_id, auth.uid());
  v_task_id text;
  v_task public.assigned_tasks;
  v_sort numeric;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;
  if v_title = '' then raise exception 'El título es obligatorio.'; end if;

  if p_assignee_id is not null and p_assignee_id <> auth.uid() then
    if not public.can_assign_profile_to_operational_task(v_assignee) then
      raise exception 'No tienes permiso para asignar esta tarea.';
    end if;
  end if;

  v_task_id := 'opt-' || gen_random_uuid()::text;
  v_sort := extract(epoch from now()) * 1000;

  insert into public.assigned_tasks (
    id, title, status, task_source, priority, area_id, due_at, due_date,
    created_by, assigned_by, sort_position
  )
  values (
    v_task_id, v_title, 'pending', 'operational', 'medium', p_area_id, p_due_at,
    case when p_due_at is null then null else p_due_at::date end,
    auth.uid(), auth.uid(), v_sort
  )
  returning * into v_task;

  insert into public.task_assignees (task_id, profile_id, assignment_role, assigned_by)
  values (v_task_id, v_assignee, 'primary', auth.uid());

  perform public.sync_assigned_tasks_profile_ids(v_task_id);
  perform public.ensure_operational_task_assignee_watchers(v_task_id);
  perform public.log_task_activity(v_task_id, 'created', null, null, jsonb_build_object('title', v_title), '{}'::jsonb);

  if v_assignee <> auth.uid() then
    perform public.notify_operational_task_event(
      v_assignee,
      'task_assigned',
      'Nueva tarea asignada: ' || v_title,
      coalesce((select full_name from public.profiles where id = auth.uid()), 'Sistema')
        || ' te asignó la tarea «' || v_title || '».',
      v_task_id
    );
  end if;

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."create_operational_task_quick"("p_title" "text", "p_assignee_id" "uuid", "p_area_id" "text", "p_due_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_or_get_finance_reconciliation"("p_bank_account_id" "uuid", "p_month" integer, "p_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.finance_reconciliations;
  v_start date;
  v_end date;
  v_system_balance numeric;
begin
  if not public.can_reconcile_finance() then
    raise exception 'No tienes permiso para conciliar.';
  end if;

  v_start := make_date(p_year, p_month, 1);
  v_end := (v_start + interval '1 month - 1 day')::date;

  select * into v_row
  from public.finance_reconciliations
  where bank_account_id = p_bank_account_id
    and period_month = p_month
    and period_year = p_year;

  if not found then
    select coalesce(current_balance, 0) into v_system_balance
    from public.finance_bank_accounts where id = p_bank_account_id;

    insert into public.finance_reconciliations (
      bank_account_id, period_month, period_year,
      statement_start_balance, statement_end_balance, system_end_balance,
      difference, created_by
    )
    values (
      p_bank_account_id, p_month, p_year,
      0, 0, v_system_balance, 0, auth.uid()
    )
    returning * into v_row;

    insert into public.finance_reconciliation_items (reconciliation_id, bank_transaction_id)
    select v_row.id, t.id
    from public.finance_bank_transactions t
    where t.bank_account_id = p_bank_account_id
      and t.transaction_date between v_start and v_end
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'reconciliation', to_jsonb(v_row),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item', to_jsonb(i),
        'transaction', to_jsonb(t)
      ) order by t.transaction_date, t.created_at)
      from public.finance_reconciliation_items i
      join public.finance_bank_transactions t on t.id = i.bank_transaction_id
      where i.reconciliation_id = v_row.id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."create_or_get_finance_reconciliation"("p_bank_account_id" "uuid", "p_month" integer, "p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_pos_split_payment"("p_order_id" "uuid", "p_items" "jsonb", "p_methods" "jsonb", "p_paid_by_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  order_row public.pos_orders;
  item_row public.pos_order_items;
  line jsonb;
  qty numeric(12,2);
  unit_price numeric(12,2);
  line_total numeric(12,2);
  subtotal numeric(12,2) := 0;
  paid_total numeric(12,2) := 0;
  cash_total numeric(12,2) := 0;
  payment_row public.pos_order_payments;
  payment_number integer;
  method_row jsonb;
  method_label text;
  session_row public.cash_sessions;
  amount_paid_so_far numeric(12,2);
  balance_after numeric(12,2);
begin
  if not public.is_cash_operator() then
    raise exception 'No tienes permiso para registrar pagos POS.';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Debes seleccionar al menos un producto para cobrar.';
  end if;

  if p_methods is null or jsonb_typeof(p_methods) <> 'array' or jsonb_array_length(p_methods) = 0 then
    raise exception 'Debes indicar al menos un metodo de pago.';
  end if;

  select * into order_row
  from public.pos_orders
  where id = p_order_id
  for update;

  if order_row.id is null then
    raise exception 'Orden no encontrada.';
  end if;

  if order_row.status not in ('awaiting_bill', 'sent_to_cashier', 'partially_paid') then
    raise exception 'La orden no esta disponible para cobro parcial.';
  end if;

  for line in select * from jsonb_array_elements(p_items)
  loop
    select * into item_row
    from public.pos_order_items
    where id = (line ->> 'order_item_id')::uuid
      and order_id = p_order_id
      and status <> 'cancelled'
    for update;

    if item_row.id is null then
      raise exception 'Item de orden invalido.';
    end if;

    qty := coalesce((line ->> 'quantity_paid')::numeric, 0);
    if qty <= 0 then
      raise exception 'Cantidad invalida para %.', item_row.product_name;
    end if;

    if qty > greatest(0, item_row.quantity - item_row.quantity_paid) then
      raise exception 'No puedes cobrar mas unidades de las pendientes para %.', item_row.product_name;
    end if;

    unit_price := item_row.unit_price;
    line_total := round(qty * unit_price, 2);
    subtotal := subtotal + line_total;
  end loop;

  if subtotal <= 0 then
    raise exception 'El subtotal de la subcuenta debe ser mayor a cero.';
  end if;

  for method_row in select * from jsonb_array_elements(p_methods)
  loop
    paid_total := paid_total + coalesce((method_row ->> 'amount')::numeric, 0);
    if coalesce(method_row ->> 'method', '') = 'cash' then
      cash_total := cash_total + coalesce((method_row ->> 'amount')::numeric, 0);
    end if;
  end loop;

  if round(paid_total, 2) < round(subtotal, 2) then
    raise exception 'El pago esta incompleto para esta subcuenta.';
  end if;

  select coalesce(max(p.payment_number), 0) + 1 into payment_number
  from public.pos_order_payments p
  where p.order_id = p_order_id;

  method_label := coalesce(
    nullif(trim(p_paid_by_label), ''),
    (
      select string_agg(
        case coalesce(m ->> 'method', 'cash')
          when 'cash' then 'Efectivo'
          when 'card' then 'Tarjeta'
          when 'transfer' then 'Transferencia'
          when 'qr' then 'QR'
          else coalesce(m ->> 'method', 'Pago')
        end,
        ' + '
      )
      from jsonb_array_elements(p_methods) m
    )
  );

  insert into public.pos_order_payments (
    order_id, payment_number, payment_method, amount, paid_by_label, methods, created_by
  ) values (
    p_order_id,
    payment_number,
    case when jsonb_array_length(p_methods) > 1 then 'mixed' else coalesce(p_methods -> 0 ->> 'method', 'cash') end,
    subtotal,
    method_label,
    p_methods,
    auth.uid()
  ) returning * into payment_row;

  for line in select * from jsonb_array_elements(p_items)
  loop
    select * into item_row
    from public.pos_order_items
    where id = (line ->> 'order_item_id')::uuid
      and order_id = p_order_id
    for update;

    qty := coalesce((line ->> 'quantity_paid')::numeric, 0);
    unit_price := item_row.unit_price;
    line_total := round(qty * unit_price, 2);

    insert into public.pos_order_payment_items (
      payment_id, order_item_id, quantity_paid, unit_price, line_total
    ) values (
      payment_row.id, item_row.id, qty, unit_price, line_total
    );

    update public.pos_order_items
    set quantity_paid = quantity_paid + qty,
        updated_at = now()
    where id = item_row.id;
  end loop;

  select coalesce(sum(p.amount), 0) into amount_paid_so_far
  from public.pos_order_payments p
  where p.order_id = p_order_id and p.status = 'paid';

  balance_after := greatest(0, order_row.total - amount_paid_so_far);

  update public.pos_orders
  set status = case when balance_after <= 0 then 'paid' else 'partially_paid' end,
      paid_at = case when balance_after <= 0 then now() else paid_at end,
      updated_at = now()
  where id = p_order_id;

  if cash_total > 0 then
    select * into session_row
    from public.cash_sessions
    where status = 'open'
    order by opened_at desc
    limit 1;

    if session_row.id is not null then
      perform public.create_cash_movement(
        session_row.id,
        'sale_cash',
        cash_total,
        'Subcuenta POS #' || payment_number::text,
        payment_row.id::text,
        p_order_id
      );
    end if;
  end if;

  perform public.record_pos_order_event(
    p_order_id,
    case when balance_after <= 0 then 'order_paid' else 'partial_payment' end,
    'Pago parcial Q' || subtotal::text || '. Saldo restante Q' || balance_after::text
  );

  return jsonb_build_object(
    'payment_id', payment_row.id,
    'payment_number', payment_number,
    'subtotal', subtotal,
    'amount_paid_total', amount_paid_so_far,
    'balance_due', balance_after,
    'order_status', case when balance_after <= 0 then 'paid' else 'partially_paid' end,
    'paid_by_label', method_label
  );
end;
$$;


ALTER FUNCTION "public"."create_pos_split_payment"("p_order_id" "uuid", "p_items" "jsonb", "p_methods" "jsonb", "p_paid_by_label" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."print_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "printer_id" "uuid" NOT NULL,
    "job_type" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "error_message" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "printed_at" timestamp with time zone,
    CONSTRAINT "print_jobs_job_type_check" CHECK (("job_type" = ANY (ARRAY['prebill'::"text", 'receipt'::"text", 'delivery_order'::"text", 'test'::"text"]))),
    CONSTRAINT "print_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'printing'::"text", 'printed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."print_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_print_job"("p_printer_id" "uuid", "p_job_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."print_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  printer_row public.pos_printers;
  created_job public.print_jobs;
  actor_role text := coalesce(public.normalize_profile_role(public.current_profile_role()), '');
  normalized_job_type text := lower(trim(coalesce(p_job_type, '')));
begin
  if actor_role not in ('admin', 'gerente_general', 'gerente', 'supervisor', 'mesero', 'caja', 'cajero') then
    raise exception 'No tienes permiso para crear trabajos de impresion.';
  end if;

  if normalized_job_type = '' then
    raise exception 'Tipo de impresion invalido.';
  end if;

  select * into printer_row
  from public.pos_printers
  where id = p_printer_id
    and is_active = true;

  if printer_row.id is null then
    raise exception 'Impresora no encontrada o inactiva.';
  end if;

  if not (normalized_job_type = any(printer_row.supported_job_types)) then
    raise exception 'La impresora no soporta este tipo de impresion.';
  end if;

  insert into public.print_jobs (printer_id, job_type, payload, created_by)
  values (printer_row.id, normalized_job_type, coalesce(p_payload, '{}'::jsonb), auth.uid())
  returning * into created_job;

  insert into public.print_job_logs (print_job_id, status, message)
  values (created_job.id, 'pending', 'Trabajo de impresion creado.');

  return created_job;
end;
$$;


ALTER FUNCTION "public"."create_print_job"("p_printer_id" "uuid", "p_job_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_production_tickets_from_order"("p_order" "jsonb", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item_data jsonb;
  product public.pos_products;
  production_area public.areas;
  area_row record;
  ticket public.production_tickets;
  ticket_ids uuid[] := '{}'::uuid[];
  product_id_text text;
  item_area_id text;
  item_quantity numeric;
begin
  if not public.can_operate_production_tickets() then
    raise exception 'No tienes permiso para enviar comandas.';
  end if;
  if nullif(trim(p_order ->> 'order_id'), '') is null then
    raise exception 'La orden no tiene identificador.';
  end if;
  if jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'No hay productos nuevos para enviar.';
  end if;

  for item_data in select value from jsonb_array_elements(p_items)
  loop
    product_id_text := nullif(trim(item_data ->> 'product_id'), '');
    item_area_id := nullif(trim(item_data ->> 'production_area_id'), '');
    item_quantity := coalesce((item_data ->> 'quantity')::numeric, 0);
    if product_id_text is null or item_area_id is null or item_quantity <= 0 then
      raise exception 'Una linea de la orden no tiene producto, area o cantidad valida.';
    end if;
    select * into product
    from public.pos_products
    where id::text = product_id_text
      and active = true
      and production_ready = true;
    if product.id is null then
      raise exception 'Producto POS no listo para produccion: %.', coalesce(item_data ->> 'product_name', product_id_text);
    end if;
    if product.recipe_id is null or product.production_area_id is distinct from item_area_id then
      raise exception 'Producto % no tiene receta o area de produccion valida.', product.name;
    end if;
  end loop;

  for area_row in
    select distinct trim(value ->> 'production_area_id') as area_id
    from jsonb_array_elements(p_items)
  loop
    select * into production_area
    from public.areas
    where id = area_row.area_id
      and active = true
      and is_production_area = true;
    if production_area.id is null then
      raise exception 'El area de produccion % no esta activa.', area_row.area_id;
    end if;

    insert into public.production_tickets (
      order_id, table_id, table_name, area_id, area_name, waiter_id,
      waiter_name, status, priority, notes
    ) values (
      trim(p_order ->> 'order_id'),
      nullif(trim(p_order ->> 'table_id'), ''),
      coalesce(nullif(trim(p_order ->> 'table_name'), ''), 'Orden POS'),
      production_area.id,
      production_area.name,
      auth.uid(),
      nullif(trim(p_order ->> 'waiter_name'), ''),
      'pending',
      coalesce(nullif(trim(p_order ->> 'priority'), ''), 'normal'),
      nullif(trim(p_order ->> 'notes'), '')
    ) returning * into ticket;
    ticket_ids := array_append(ticket_ids, ticket.id);

    for item_data in
      select value from jsonb_array_elements(p_items)
      where trim(value ->> 'production_area_id') = area_row.area_id
    loop
      select * into product
      from public.pos_products
      where id::text = trim(item_data ->> 'product_id');
      insert into public.production_ticket_items (
        ticket_id, order_item_id, product_id, product_name, quantity,
        notes, modifiers, status
      ) values (
        ticket.id,
        trim(item_data ->> 'order_item_id'),
        product.id,
        product.name,
        (item_data ->> 'quantity')::numeric,
        nullif(trim(item_data ->> 'notes'), ''),
        coalesce(item_data -> 'modifiers', '[]'::jsonb),
        'pending'
      );
    end loop;
  end loop;

  return jsonb_build_object('ticket_ids', to_jsonb(ticket_ids));
end;
$$;


ALTER FUNCTION "public"."create_production_tickets_from_order"("p_order" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recruitment_application_from_website"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_first_name text := nullif(trim(coalesce(p_data ->> 'first_name', '')), '');
  v_last_name text := nullif(trim(coalesce(p_data ->> 'last_name', '')), '');
  v_full_name text := nullif(trim(coalesce(p_data ->> 'full_name', '')), '');
  v_phone_raw text := nullif(trim(coalesce(p_data ->> 'phone', '')), '');
  v_phone text := public.recruitment_normalize_phone(v_phone_raw);
  v_email text := nullif(lower(trim(coalesce(p_data ->> 'email', ''))), '');
  v_applied_position text := nullif(trim(coalesce(
    p_data ->> 'applied_position',
    p_data ->> 'position_applied',
    ''
  )), '');
  v_data_consent boolean := public.recruitment_parse_data_consent(p_data ->> 'data_consent');
  v_age integer;
  v_submitted_at date;
  v_vacancy_id uuid;
  v_existing public.recruitment_candidates;
  v_row public.recruitment_candidates;
  v_payload jsonb;
  v_prior_experience text;
  v_motivation text;
  v_attachment_url text;
  v_is_duplicate boolean := false;
begin
  if auth.uid() is not null then
    raise exception 'Solo disponible para integraciones del sistema.';
  end if;

  if v_full_name is null then
    v_full_name := nullif(trim(concat_ws(' ', v_first_name, v_last_name)), '');
  end if;

  if v_full_name is null then
    raise exception 'first_name/last_name o full_name es obligatorio.';
  end if;

  if v_phone is null then
    raise exception 'phone es obligatorio.';
  end if;

  if v_applied_position is null then
    raise exception 'applied_position es obligatorio.';
  end if;

  if not v_data_consent then
    raise exception 'data_consent es obligatorio.';
  end if;

  if nullif(trim(coalesce(p_data ->> 'age', '')), '') is not null then
    v_age := nullif(trim(p_data ->> 'age'), '')::integer;
    if v_age is not null and (v_age < 16 or v_age > 99) then
      raise exception 'age debe estar entre 16 y 99.';
    end if;
  end if;

  if nullif(trim(coalesce(p_data ->> 'submitted_at', '')), '') is not null then
    begin
      v_submitted_at := nullif(trim(p_data ->> 'submitted_at'), '')::date;
    exception when others then
      v_submitted_at := (now() at time zone 'America/Guatemala')::date;
    end;
  else
    v_submitted_at := (now() at time zone 'America/Guatemala')::date;
  end if;

  v_attachment_url := nullif(trim(coalesce(
    p_data ->> 'attachment_url',
    p_data ->> 'document_url',
    ''
  )), '');

  v_prior_experience := nullif(trim(coalesce(
    p_data ->> 'prior_experience',
    p_data ->> 'has_experience',
    ''
  )), '');

  v_motivation := nullif(trim(coalesce(p_data ->> 'motivation', '')), '');

  v_payload := coalesce(p_data, '{}'::jsonb)
    || jsonb_build_object(
      'first_name', v_first_name,
      'last_name', v_last_name,
      'municipality', nullif(trim(coalesce(p_data ->> 'municipality', '')), ''),
      'education_level', nullif(trim(coalesce(p_data ->> 'education_level', '')), ''),
      'availability', nullif(trim(coalesce(p_data ->> 'availability', '')), ''),
      'available_start_date', nullif(trim(coalesce(p_data ->> 'available_start_date', '')), ''),
      'has_experience', nullif(trim(coalesce(p_data ->> 'has_experience', '')), ''),
      'motivation', v_motivation,
      'data_consent', v_data_consent,
      'source', 'website',
      'submitted_at', coalesce(p_data ->> 'submitted_at', v_submitted_at::text)
    );

  select c.*
  into v_existing
  from public.recruitment_candidates c
  where c.applied_at >= ((now() at time zone 'America/Guatemala')::date - 30)
    and (
      (v_email is not null and lower(trim(c.email)) = v_email)
      or (
        public.recruitment_normalize_phone(c.phone) = v_phone
        or public.recruitment_normalize_phone(c.whatsapp) = v_phone
      )
    )
  order by c.created_at desc
  limit 1;

  if v_existing.id is not null then
    v_is_duplicate := true;

    update public.recruitment_candidates
    set
      full_name = v_full_name,
      phone = v_phone_raw,
      email = coalesce(v_email, email),
      age = coalesce(v_age, age),
      address = coalesce(nullif(trim(coalesce(p_data ->> 'municipality', '')), ''), address),
      position_applied = v_applied_position,
      source = 'website',
      prior_experience = coalesce(v_prior_experience, prior_experience),
      schedule_availability = coalesce(nullif(trim(coalesce(p_data ->> 'availability', '')), ''), schedule_availability),
      salary_expectation = coalesce(nullif(trim(coalesce(p_data ->> 'salary_expectation', '')), ''), salary_expectation),
      attachment_url = coalesce(v_attachment_url, attachment_url),
      application_payload = coalesce(application_payload, '{}'::jsonb) || v_payload,
      notes = coalesce(v_motivation, notes),
      updated_at = now()
    where id = v_existing.id
    returning * into v_row;

    insert into public.recruitment_candidate_status_history (
      candidate_id, from_status, to_status, reason, notes, changed_by
    )
    values (
      v_row.id,
      v_row.pipeline_status,
      v_row.pipeline_status,
      'website_reapplication',
      'Nueva aplicación desde sitio web (' || v_submitted_at::text || ').',
      null
    );

    return jsonb_build_object(
      'id', v_row.id,
      'duplicate', true,
      'pipeline_status', v_row.pipeline_status,
      'vacancy_id', v_row.vacancy_id,
      'notification_count', 0
    );
  end if;

  v_vacancy_id := public.recruitment_resolve_vacancy_for_application(v_applied_position);
  if v_vacancy_id is null then
    raise exception 'No hay vacante disponible para registrar la aplicación.';
  end if;

  insert into public.recruitment_candidates (
    vacancy_id,
    full_name,
    phone,
    email,
    age,
    address,
    position_applied,
    source,
    prior_experience,
    schedule_availability,
    salary_expectation,
    pipeline_status,
    applied_at,
    notes,
    attachment_url,
    application_payload,
    created_by,
    updated_by
  )
  values (
    v_vacancy_id,
    v_full_name,
    v_phone_raw,
    v_email,
    v_age,
    nullif(trim(coalesce(p_data ->> 'municipality', '')), ''),
    v_applied_position,
    'website',
    v_prior_experience,
    nullif(trim(coalesce(p_data ->> 'availability', '')), ''),
    nullif(trim(coalesce(p_data ->> 'salary_expectation', '')), ''),
    'applied',
    v_submitted_at,
    v_motivation,
    v_attachment_url,
    v_payload,
    null,
    null
  )
  returning * into v_row;

  return jsonb_build_object(
    'id', v_row.id,
    'duplicate', false,
    'pipeline_status', v_row.pipeline_status,
    'vacancy_id', v_row.vacancy_id,
    'notification_count', public.notify_new_recruitment_application(v_row.id)
  );
end;
$$;


ALTER FUNCTION "public"."create_recruitment_application_from_website"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_requisition"("p_data" "jsonb", "p_items" "jsonb", "p_submit" boolean DEFAULT false) RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  created public.requisitions;
  row_data jsonb;
  catalog_item public.inventory_items;
  requester public.profiles;
  from_id text := nullif(trim(p_data ->> 'from_area_id'), '');
  to_id text := nullif(trim(p_data ->> 'to_area_id'), '');
  requester_id uuid := nullif(p_data ->> 'requested_by_profile_id', '')::uuid;
  requested_qty numeric;
  requested_unit text;
  conversion_factor numeric;
  converted_qty numeric;
  source_stock numeric;
  source_minimum numeric;
  availability text;
  is_test_flow boolean := coalesce((p_data ->> 'is_test')::boolean, false);
begin
  if is_test_flow and not public.can_create_test_flow() then
    raise exception 'Solo Administracion puede crear pruebas de flujo.';
  end if;

  perform public.assert_requisition_request_permissions(from_id, to_id, requester_id);

  select * into requester from public.profiles where id = requester_id and status = 'active';
  if requester.id is null then
    raise exception 'Selecciona quien esta haciendo la requisicion.';
  end if;

  if jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'Agrega al menos un producto a la requisicion.';
  end if;

  insert into public.requisitions (
    requisition_number, requested_by, requested_by_profile_id, requested_by_name, requested_by_role,
    from_area_id, to_area_id, priority, notes, status, submitted_at, is_test
  )
  values (
    public.next_requisition_number(), auth.uid(), requester.id,
    coalesce(requester.full_name, requester.username), requester.role, from_id, to_id,
    coalesce(nullif(trim(p_data ->> 'priority'), ''), 'normal'),
    nullif(trim(p_data ->> 'notes'), ''),
    case when p_submit then 'pending' else 'draft' end,
    case when p_submit then now() else null end,
    is_test_flow
  )
  returning * into created;

  for row_data in select value from jsonb_array_elements(p_items)
  loop
    select * into catalog_item from public.inventory_items where id = (row_data ->> 'item_id')::uuid and active = true;
    if catalog_item.id is null then raise exception 'La requisicion contiene un producto inactivo o inexistente.'; end if;
    requested_qty := coalesce((row_data ->> 'requested_quantity')::numeric, 0);
    if requested_qty <= 0 then raise exception 'Las cantidades solicitadas deben ser mayores que cero.'; end if;

    requested_unit := coalesce(
      nullif(trim(row_data ->> 'requested_unit'), ''),
      nullif(trim(catalog_item.default_requisition_unit), ''),
      catalog_item.base_unit
    );
    conversion_factor := public.resolve_item_requisition_unit_factor(catalog_item.id, requested_unit);
    converted_qty := requested_qty * conversion_factor;

    select quantity, minimum_quantity into source_stock, source_minimum
    from public.area_inventory
    where item_id = catalog_item.id and area_id = from_id;
    source_stock := coalesce(source_stock, 0);
    source_minimum := coalesce(source_minimum, 0);
    availability := case when source_stock <= 0 then 'Sin stock' when source_stock < converted_qty then 'Parcial' else 'Disponible' end;

    insert into public.requisition_items (
      requisition_id, item_id, item_name, unit, requested_quantity, approved_quantity,
      requested_unit, conversion_factor, converted_requested_quantity, availability_status,
      stock_available_at_request, stock_minimum_at_request, conversion_warning, notes, is_test,
      inventory_base_unit_at_request
    ) values (
      created.id, catalog_item.id, catalog_item.name, requested_unit, requested_qty, null,
      requested_unit, conversion_factor, converted_qty, availability,
      source_stock, source_minimum, false, nullif(trim(row_data ->> 'notes'), ''),
      is_test_flow, catalog_item.base_unit
    );
  end loop;

  return created;
end;
$$;


ALTER FUNCTION "public"."create_requisition"("p_data" "jsonb", "p_items" "jsonb", "p_submit" boolean) OWNER TO "postgres";


