CREATE OR REPLACE FUNCTION "public"."create_station_enrollment_token"("p_station_id" "uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO '', 'extensions'
    AS $$
declare
  v_station public.operational_stations;
  v_token text;
  v_hash text;
  v_row public.operational_station_enrollment_tokens;
  v_code text;
begin
  if not public.is_operational_stations_admin() then
    raise exception 'No autorizado.';
  end if;
  select * into v_station from public.operational_stations where id = p_station_id;
  if v_station.id is null then
    raise exception 'Estacion no encontrada.';
  end if;
  if v_station.status not in ('active', 'draft') then
    raise exception 'Estacion no disponible para enrollment.';
  end if;
  if nullif(trim(p_idempotency_key), '') is not null then
    select * into v_row
    from public.operational_station_enrollment_tokens
    where idempotency_key = trim(p_idempotency_key);
    if v_row.id is not null then
      return jsonb_build_object(
        'enrollment_id', v_row.id,
        'expires_at', v_row.expires_at,
        'status', v_row.status,
        'idempotent', true
      );
    end if;
  end if;
  v_token := encode(extensions.gen_random_bytes(16), 'hex');
  v_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');
  v_code := lpad((floor(random() * 1000000)::int)::text, 6, '0');
  insert into public.operational_station_enrollment_tokens (
    station_id, token_hash, status, expires_at, confirmation_code,
    idempotency_key, created_by
  )
  values (
    p_station_id, v_hash, 'pending', now() + interval '15 minutes', v_code,
    nullif(trim(p_idempotency_key), ''), auth.uid()
  )
  returning * into v_row;
  perform public.log_operational_station_event(
    p_station_id, null, 'enrollment_created', auth.uid(),
    jsonb_build_object('enrollment_id', v_row.id), p_idempotency_key
  );
  return jsonb_build_object(
    'enrollment_id', v_row.id,
    'enrollment_token', v_token,
    'confirmation_code', v_code,
    'expires_at', v_row.expires_at,
    'station_id', p_station_id,
    'station_name', v_station.name
  );
end;
$$;


ALTER FUNCTION "public"."create_station_enrollment_token"("p_station_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task_comment"("p_task_id" "text", "p_body" "text", "p_step_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_body text := trim(coalesce(p_body, ''));
  v_mentions uuid[];
  v_comment_id uuid;
  v_mention uuid;
begin
  if v_body = '' then raise exception 'El comentario no puede estar vacío.'; end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id and t.task_source = 'operational'
    and t.deleted_at is null;

  if not found then raise exception 'Tarea no encontrada.'; end if;
  if not public.can_comment_on_task(v_task) then
    raise exception 'No tienes permiso para comentar.';
  end if;

  v_mentions := public.parse_task_comment_mentions(p_task_id, v_body);

  insert into public.task_comments (
    task_id, step_id, body_markdown, mention_profile_ids, created_by
  ) values (
    p_task_id, p_step_id, v_body, coalesce(v_mentions, '{}'::uuid[]), auth.uid()
  ) returning id into v_comment_id;

  perform public.log_task_activity(
    p_task_id, 'comment_added', 'comments',
    null, to_jsonb(left(v_body, 120)),
    jsonb_build_object('comment_id', v_comment_id, 'step_id', p_step_id)
  );

  foreach v_mention in array coalesce(v_mentions, '{}'::uuid[]) loop
    perform public.notify_operational_task_event(
      v_mention,
      'task_mention',
      'Te mencionaron en una tarea',
      left(v_body, 200),
      p_task_id
    );
  end loop;

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."create_task_comment"("p_task_id" "text", "p_body" "text", "p_step_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task_label"("p_name" "text", "p_color_key" "text" DEFAULT 'teal'::"text", "p_description" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'global'::"text", "p_area_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_name text;
  v_scope text;
  v_row public.task_labels;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if not public.can_administer_task_labels() then
    raise exception 'No tienes permiso para crear etiquetas.';
  end if;

  v_name := nullif(trim(p_name), '');
  if v_name is null then
    raise exception 'El nombre de la etiqueta es obligatorio.';
  end if;

  if p_color_key is null
    or p_color_key not in ('teal', 'blue', 'green', 'yellow', 'orange', 'red', 'purple', 'pink', 'slate') then
    raise exception 'Color de etiqueta inválido.';
  end if;

  v_scope := coalesce(nullif(trim(p_scope), ''), 'global');
  if v_scope not in ('global', 'area') then
    raise exception 'Alcance de etiqueta inválido.';
  end if;

  if v_scope = 'area' and nullif(trim(p_area_id), '') is null then
    raise exception 'Las etiquetas de área requieren area_id.';
  end if;

  if exists (
    select 1
    from public.task_labels l
    where l.deleted_at is null
      and lower(l.name) = lower(v_name)
      and l.scope = v_scope
      and coalesce(l.area_id, '') = coalesce(nullif(trim(p_area_id), ''), '')
  ) then
    raise exception 'Ya existe una etiqueta con ese nombre.';
  end if;

  insert into public.task_labels (
    name,
    color_key,
    description,
    scope,
    area_id,
    created_by
  )
  values (
    v_name,
    p_color_key,
    nullif(trim(p_description), ''),
    v_scope,
    case when v_scope = 'area' then nullif(trim(p_area_id), '') else null end,
    auth.uid()
  )
  returning * into v_row;

  return jsonb_build_object(
    'label',
    jsonb_build_object(
      'id', v_row.id,
      'name', v_row.name,
      'color_key', v_row.color_key,
      'description', v_row.description,
      'scope', v_row.scope,
      'area_id', v_row.area_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."create_task_label"("p_name" "text", "p_color_key" "text", "p_description" "text", "p_scope" "text", "p_area_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task_step"("p_list_id" "uuid", "p_text" "text", "p_sort_position" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_list public.task_step_lists;
  v_pos numeric;
  v_step_id uuid;
begin
  if coalesce(trim(p_text), '') = '' then raise exception 'El paso no puede estar vacío.'; end if;

  select * into v_list
  from public.task_step_lists sl
  where sl.id = p_list_id and sl.deleted_at is null
  for update;

  if not found then raise exception 'Lista no encontrada.'; end if;
  perform public.assert_operational_task_mutable(v_list.task_id);

  if p_sort_position is not null then
    v_pos := p_sort_position;
  else
    select coalesce(max(s.sort_position), -1024) + 1024 into v_pos
    from public.task_steps s
    where s.step_list_id = p_list_id and s.deleted_at is null;
  end if;

  insert into public.task_steps (step_list_id, task_id, text, sort_position, created_by)
  values (p_list_id, v_list.task_id, trim(p_text), v_pos, auth.uid())
  returning id into v_step_id;

  return public.get_operational_task_detail(v_list.task_id);
end;
$$;


ALTER FUNCTION "public"."create_task_step"("p_list_id" "uuid", "p_text" "text", "p_sort_position" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task_step_list"("p_task_id" "text", "p_title" "text" DEFAULT 'Plan de trabajo'::"text", "p_copy_from_list_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_list_id uuid;
  v_pos numeric;
  v_src record;
  v_step record;
  v_idx int := 0;
begin
  v_task := public.assert_operational_task_mutable(p_task_id);

  select coalesce(max(sl.sort_position), -1024) + 1024 into v_pos
  from public.task_step_lists sl
  where sl.task_id = p_task_id and sl.deleted_at is null;

  insert into public.task_step_lists (task_id, title, sort_position, created_by)
  values (p_task_id, coalesce(nullif(trim(p_title), ''), 'Plan de trabajo'), v_pos, auth.uid())
  returning id into v_list_id;

  if p_copy_from_list_id is not null then
    for v_step in
      select s.*
      from public.task_steps s
      join public.task_step_lists sl on sl.id = s.step_list_id
      where s.step_list_id = p_copy_from_list_id
        and s.deleted_at is null
        and sl.deleted_at is null
        and public.can_access_operational_task(
          (select t from public.assigned_tasks t where t.id = sl.task_id), 'view'
        )
      order by s.sort_position asc
    loop
      insert into public.task_steps (
        step_list_id, task_id, text, sort_position, created_by
      ) values (
        v_list_id, p_task_id, v_step.text, v_idx::numeric * 1024, auth.uid()
      );
      v_idx := v_idx + 1;
    end loop;
  end if;

  perform public.log_task_activity(
    p_task_id, 'step_list_created', 'work_plan', null,
    to_jsonb(coalesce(nullif(trim(p_title), ''), 'Plan de trabajo')),
    jsonb_build_object('list_id', v_list_id)
  );

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."create_task_step_list"("p_task_id" "text", "p_title" "text", "p_copy_from_list_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_roles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "role_key" "text" NOT NULL,
    "role_name" "text" NOT NULL,
    "description" "text",
    "category" "text",
    "is_system" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_deprecated" boolean DEFAULT false NOT NULL,
    "hr_assignable" boolean DEFAULT false NOT NULL
);


ALTER TABLE "public"."user_roles" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_role"("p_role_name" "text", "p_description" "text" DEFAULT ''::"text", "p_is_active" boolean DEFAULT true, "p_hr_assignable" boolean DEFAULT false) RETURNS "public"."user_roles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_name text;
  normalized_key text;
  inserted_role public.user_roles;
begin
  if not public.is_profile_manager() then
    raise exception 'Solo Administración puede crear roles personalizados.';
  end if;

  normalized_name := trim(coalesce(p_role_name, ''));
  if normalized_name = '' then
    raise exception 'El nombre del rol es obligatorio.';
  end if;

  normalized_key := public.normalize_role_name(normalized_name);
  if normalized_key = '' then
    raise exception 'No se pudo generar una clave válida para el rol.';
  end if;

  if public.is_protected_role_key(normalized_key) then
    raise exception 'No se pueden crear roles reservados como admin o gerente_general.';
  end if;

  if exists (select 1 from public.user_roles where role_key = normalized_key) then
    raise exception 'El rol con clave "%" ya existe.', normalized_key;
  end if;

  insert into public.user_roles (
    role_key,
    role_name,
    description,
    category,
    is_system,
    is_active,
    is_deprecated,
    hr_assignable,
    created_by
  )
  values (
    normalized_key,
    normalized_name,
    coalesce(trim(p_description), ''),
    'Personalizado',
    false,
    coalesce(p_is_active, true),
    false,
    coalesce(p_hr_assignable, false),
    auth.uid()
  )
  returning * into inserted_role;

  return inserted_role;
end;
$$;


ALTER FUNCTION "public"."create_user_role"("p_role_name" "text", "p_description" "text", "p_is_active" boolean, "p_hr_assignable" boolean) OWNER TO "postgres";


