    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "category" "text" NOT NULL,
    "amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "frequency" "text" DEFAULT 'monthly'::"text" NOT NULL,
    "cost_month" "date" NOT NULL,
    "due_day" integer,
    "payment_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "notes" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fixed_costs_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "fixed_costs_category_check" CHECK (("category" = ANY (ARRAY['renta'::"text", 'servicios_basicos'::"text", 'internet_telefono'::"text", 'planilla_administrativa'::"text", 'software_suscripciones'::"text", 'mantenimiento'::"text", 'seguros'::"text", 'impuestos'::"text", 'financiamiento'::"text", 'otros'::"text"]))),
    CONSTRAINT "fixed_costs_cost_month_check" CHECK (("cost_month" = ("date_trunc"('month'::"text", ("cost_month")::timestamp with time zone))::"date")),
    CONSTRAINT "fixed_costs_due_day_check" CHECK ((("due_day" IS NULL) OR (("due_day" >= 1) AND ("due_day" <= 31)))),
    CONSTRAINT "fixed_costs_frequency_check" CHECK (("frequency" = ANY (ARRAY['monthly'::"text", 'quarterly'::"text", 'annual'::"text"]))),
    CONSTRAINT "fixed_costs_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'overdue'::"text", 'cancelled'::"text"])))
);


