    CONSTRAINT "standard_recipes_estimated_cost_check" CHECK (("estimated_cost" >= (0)::numeric)),
    CONSTRAINT "standard_recipes_recipe_current_cost_check" CHECK (("recipe_current_cost" >= (0)::numeric)),
    CONSTRAINT "standard_recipes_recipe_food_cost_percent_check" CHECK (("recipe_food_cost_percent" >= (0)::numeric)),
    CONSTRAINT "standard_recipes_recipe_type_check" CHECK (("recipe_type" = ANY (ARRAY['subrecipe'::"text", 'final_product'::"text"]))),
    CONSTRAINT "standard_recipes_target_food_cost_percent_check" CHECK ((("target_food_cost_percent" >= (0)::numeric) AND ("target_food_cost_percent" <= (100)::numeric))),
    CONSTRAINT "standard_recipes_yield_quantity_check" CHECK (("yield_quantity" > (0)::numeric))
);


ALTER TABLE "public"."standard_recipes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_standard_recipe"("p_recipe_id" "uuid") RETURNS "public"."standard_recipes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recipe public.standard_recipes;
begin
  select * into recipe from public.standard_recipes where id = p_recipe_id;
  if recipe.id is null or not public.can_manage_recipe_area(recipe.production_area_id) then
    raise exception 'No tienes permiso para desactivar esta receta.';
  end if;
  update public.standard_recipes set active = false where id = p_recipe_id returning * into recipe;
  return recipe;
end;
$$;


ALTER FUNCTION "public"."deactivate_standard_recipe"("p_recipe_id" "uuid") OWNER TO "postgres";


