CREATE OR REPLACE FUNCTION "public"."delete_employee_schedule"("p_schedule_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing public.employee_schedules;
begin
  select * into existing from public.employee_schedules where id = p_schedule_id;
  if existing.id is null then return; end if;
  if not public.is_schedule_editor()
    or (existing.status = 'published' and not public.is_schedule_publisher()) then
    raise exception 'No tienes permiso para eliminar este turno.';
  end if;
  insert into public.schedule_change_logs (schedule_id, changed_by, change_type, old_value)
  values (existing.id, auth.uid(), 'deleted', to_jsonb(existing));
  if existing.status = 'published' then
    insert into public.notifications (user_id, type, title, message, entity_type, entity_id)
    values (existing.employee_id, 'schedule_changed', 'Cambio en tu horario', 'Se elimino un turno de tu horario publicado.', 'employee_schedule', existing.id::text);
  end if;
  delete from public.employee_schedules where id = existing.id;
end;
$$;


ALTER FUNCTION "public"."delete_employee_schedule"("p_schedule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_pos_floor_table"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_manage_pos_floor_plan() then
    raise exception 'No tienes permiso para editar el plano del restaurante.';
  end if;

  if coalesce(trim(p_id), '') = '' then
    raise exception 'La mesa es obligatoria.';
  end if;

  if public.pos_floor_has_open_orders(trim(p_id), null) then
    raise exception 'No puedes eliminar esta mesa porque tiene una orden abierta.';
  end if;

  update public.pos_floor_tables
  set active = false, updated_by = auth.uid(), updated_at = now()
  where id = trim(p_id) and active = true;

  if not found then
    raise exception 'Mesa no encontrada.';
  end if;

  return jsonb_build_object('id', trim(p_id), 'deleted', true);
end;
$$;


ALTER FUNCTION "public"."delete_pos_floor_table"("p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_pos_floor_zone"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_manage_pos_floor_plan() then
    raise exception 'No tienes permiso para editar el plano del restaurante.';
  end if;

  if coalesce(trim(p_id), '') = '' then
    raise exception 'La zona es obligatoria.';
  end if;

  if public.pos_floor_has_open_orders(null, trim(p_id)) then
    raise exception 'No puedes eliminar esta zona porque tiene ordenes abiertas.';
  end if;

  update public.pos_floor_tables
  set active = false, updated_by = auth.uid(), updated_at = now()
  where zone_id = trim(p_id) and active = true;

  update public.pos_floor_zones
  set active = false, updated_by = auth.uid(), updated_at = now()
  where id = trim(p_id);

  if not found then
    raise exception 'Zona no encontrada.';
  end if;

  return jsonb_build_object('id', trim(p_id), 'deleted', true);
end;
$$;


ALTER FUNCTION "public"."delete_pos_floor_zone"("p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_recruitment_candidate"("p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate public.recruitment_candidates;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para eliminar candidatos.';
  end if;

  if p_candidate_id is null then
    raise exception 'Candidato no especificado.';
  end if;

  select *
  into v_candidate
  from public.recruitment_candidates
  where id = p_candidate_id;

  if v_candidate.id is null then
    raise exception 'Candidato no encontrado.';
  end if;

  if exists (
    select 1
    from public.recruitment_employee_origins o
    where o.candidate_id = p_candidate_id
  ) then
    raise exception 'No se puede eliminar un candidato convertido en colaborador.';
  end if;

  delete from public.recruitment_candidates
  where id = p_candidate_id;

  return jsonb_build_object(
    'id', v_candidate.id,
    'full_name', v_candidate.full_name,
    'deleted', true
  );
end;
$$;


ALTER FUNCTION "public"."delete_recruitment_candidate"("p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_shift_type"("p_shift_type_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.is_shift_type_manager() then
    raise exception 'No tienes permiso para gestionar tipos de turno.';
  end if;
  if exists (select 1 from public.employee_schedules where shift_type_id = p_shift_type_id)
    or exists (select 1 from public.employee_custom_schedules where shift_type_id = p_shift_type_id) then
    raise exception 'Este tipo de turno ya fue usado. Desactivalo en lugar de eliminarlo.';
  end if;
  delete from public.shift_types where id = p_shift_type_id;
end;
$$;


ALTER FUNCTION "public"."delete_shift_type"("p_shift_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_task_attachment"("p_attachment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_att public.task_attachments;
begin
  select * into v_att
  from public.task_attachments a
  where a.id = p_attachment_id and a.deleted_at is null
  for update;

  if not found then raise exception 'Adjunto no encontrado.'; end if;
  perform public.assert_operational_task_mutable(v_att.task_id);

  update public.task_attachments
  set deleted_at = now(), deleted_by = auth.uid()
  where id = p_attachment_id;

  perform public.log_task_activity(
    v_att.task_id, 'attachment_removed', 'attachments',
    to_jsonb(v_att.display_name), null,
    jsonb_build_object('attachment_id', p_attachment_id)
  );

  return public.get_operational_task_detail(v_att.task_id);
end;
$$;


ALTER FUNCTION "public"."delete_task_attachment"("p_attachment_id" "uuid") OWNER TO "postgres";


