    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_comment public.task_comments;
begin
  select * into v_comment
  from public.task_comments c
  where c.id = p_comment_id and c.deleted_at is null
