CREATE OR REPLACE FUNCTION "public"."delete_task_label"("p_label_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.task_labels;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if not public.can_administer_task_labels() then
    raise exception 'No tienes permiso para eliminar etiquetas.';
  end if;

  select * into v_row
  from public.task_labels l
  where l.id = p_label_id
    and l.deleted_at is null
  for update;

  if not found then
    raise exception 'Etiqueta no encontrada.';
  end if;

  delete from public.task_label_assignments tla
  where tla.label_id = p_label_id;

  update public.task_labels l
  set
    deleted_at = now(),
    updated_at = now()
  where l.id = p_label_id;

  return jsonb_build_object(
    'deleted_id', p_label_id,
    'name', v_row.name
  );
end;
$$;


ALTER FUNCTION "public"."delete_task_label"("p_label_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_task_step"("p_step_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_step public.task_steps;
begin
  select * into v_step
  from public.task_steps s
  where s.id = p_step_id and s.deleted_at is null
  for update;

  if not found then raise exception 'Paso no encontrado.'; end if;
  perform public.assert_operational_task_mutable(v_step.task_id);

  update public.task_steps
  set deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
  where id = p_step_id;

  return public.get_operational_task_detail(v_step.task_id);
end;
$$;


ALTER FUNCTION "public"."delete_task_step"("p_step_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_task_step_list"("p_list_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_list public.task_step_lists;
begin
  select * into v_list
  from public.task_step_lists sl
  where sl.id = p_list_id and sl.deleted_at is null
  for update;

  if not found then raise exception 'Lista no encontrada.'; end if;
  perform public.assert_operational_task_mutable(v_list.task_id);

  update public.task_step_lists
  set deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
  where id = p_list_id;

  update public.task_steps
  set deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
  where step_list_id = p_list_id and deleted_at is null;

  perform public.log_task_activity(
    v_list.task_id, 'step_list_deleted', 'work_plan', to_jsonb(v_list.title), null,
    jsonb_build_object('list_id', p_list_id)
  );

  return public.get_operational_task_detail(v_list.task_id);
end;
$$;


ALTER FUNCTION "public"."delete_task_step_list"("p_list_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bakery_production_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_code" "text" NOT NULL,
    "plan_item_id" "uuid",
    "inventory_item_id" "uuid",
    "product_name" "text" NOT NULL,
    "planned_quantity" numeric NOT NULL,
    "actual_quantity" numeric,
    "unit" "text" DEFAULT 'Unidad'::"text" NOT NULL,
    "responsible_user_id" "uuid",
    "destination_area_id" "text",
    "recipe_id" "uuid",
    "status" "text" DEFAULT 'created'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bakery_production_batches_actual_quantity_check" CHECK ((("actual_quantity" IS NULL) OR ("actual_quantity" >= (0)::numeric))),
    CONSTRAINT "bakery_production_batches_planned_quantity_check" CHECK (("planned_quantity" > (0)::numeric)),
    CONSTRAINT "bakery_production_batches_status_check" CHECK (("status" = ANY (ARRAY['created'::"text", 'in_progress'::"text", 'delivered'::"text", 'partial'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."bakery_production_batches" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deliver_bakery_production_batch"("p_batch_id" "uuid", "p_delivered_quantity" numeric, "p_quality_result" "text", "p_photo_url" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."bakery_production_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_batch public.bakery_production_batches;
  v_plan public.bakery_production_plan_items;
  v_diary public.bakery_production_diary_entries;
  v_quality text := lower(trim(coalesce(p_quality_result, '')));
  v_qty numeric := coalesce(p_delivered_quantity, 0);
  v_new_status text;
  v_plan_status text;
begin
  if not public.can_operate_bakery_production() then
    raise exception 'PERMISSION_DENIED';
  end if;
  if nullif(trim(coalesce(p_photo_url, '')), '') is null then
    raise exception 'Se requiere foto de entrega para cerrar el lote.';
  end if;
  if v_qty <= 0 then
    raise exception 'La cantidad entregada debe ser mayor que cero.';
  end if;
  if v_quality not in ('good', 'acceptable', 'failed') then
    raise exception 'Indica un resultado de calidad válido.';
  end if;

  select * into v_batch
  from public.bakery_production_batches
  where id = p_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'Lote no encontrado.';
  end if;
  if v_batch.status not in ('created', 'in_progress') then
    raise exception 'El lote ya fue entregado o cancelado.';
  end if;

  select * into v_diary
  from public.bakery_production_diary_entries
  where batch_id = v_batch.id;

  if v_diary.id is null or v_diary.actual_quantity is null then
    raise exception 'Completa el diario del panadero con cantidad real antes de entregar.';
  end if;

  insert into public.bakery_production_batch_photos (
    batch_id, photo_url, photo_type, uploaded_by
  )
  values (v_batch.id, trim(p_photo_url), 'delivery', auth.uid());

  v_new_status := case
    when v_qty >= v_batch.planned_quantity then 'delivered'
    else 'partial'
  end;

  update public.bakery_production_batches
  set
    actual_quantity = v_qty,
    status = v_new_status,
    delivered_at = now(),
    notes = coalesce(nullif(trim(p_notes), ''), notes),
    updated_at = now()
  where id = v_batch.id
  returning * into v_batch;

  if v_batch.plan_item_id is not null then
    select * into v_plan from public.bakery_production_plan_items where id = v_batch.plan_item_id;
    v_plan_status := case
      when v_new_status = 'delivered' then 'delivered'
      else 'partial'
    end;
    update public.bakery_production_plan_items
    set status = v_plan_status, updated_at = now()
    where id = v_batch.plan_item_id;
  end if;

  -- TODO(inventory): optional inventory_movements production_output here
  -- when v_batch.inventory_item_id and v_batch.destination_area_id are present.

  return v_batch;
end;
$$;


ALTER FUNCTION "public"."deliver_bakery_production_batch"("p_batch_id" "uuid", "p_delivered_quantity" numeric, "p_quality_result" "text", "p_photo_url" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diagnose_attendance_employee_state"("p_employee_name" "text", "p_start_date" "date" DEFAULT ((("now"() AT TIME ZONE 'America/Guatemala'::"text"))::"date" - 7), "p_end_date" "date" DEFAULT (("now"() AT TIME ZONE 'America/Guatemala'::"text"))::"date") RETURNS TABLE("section" "text", "employee_id" "uuid", "employee_name" "text", "labor_date" "date", "calendar_date" "date", "mark_id" "uuid", "marked_at" timestamp with time zone, "mark_type" "text", "classification" "text", "approval_status" "text", "device_id" "text", "device_name" "text", "observation" "text", "related_mark_id" "uuid", "has_open_entry" boolean, "has_open_meal" boolean, "overnight_shift" boolean, "open_entry_id" "uuid", "open_entry_at" timestamp with time zone, "open_meal_id" "uuid", "open_meal_at" timestamp with time zone, "next_expected_mark" "text", "block_reason" "text", "detail" "text", "marking_state" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'America/Guatemala';
  v_employee_id uuid;
  v_employee_name text;
  v_calendar_date date := (now() at time zone v_tz)::date;
  v_open_entry public.attendance_marks;
  v_open_meal public.attendance_marks;
  v_ctx jsonb;
  v_state_entrada jsonb;
  v_state_comida jsonb;
  v_state_regreso jsonb;
  v_state_salida jsonb;
  v_sched record;
  v_next text;
  v_block text;
  v_age_days integer;
  v_sched_overnight boolean := false;
  v_err_msg text;
  v_err_detail text;
  v_err_hint text;
  v_err_context text;
  v_err_state text;
  v_allow_diagnostic boolean;
begin
  v_open_entry.id := null;
  v_open_meal.id := null;

  v_allow_diagnostic := auth.uid() is null
    or public.is_schedule_publisher()
    or public.can_view_attendance_reports();

  if not v_allow_diagnostic then
    return query select
      'error'::text,
      null::uuid,
      coalesce(p_employee_name, 'Colaborador')::text,
      null::date,
      v_calendar_date,
      null::uuid, null::timestamptz, null::text, null::text, null::text,
      null::text, null::text,
      format(
        'PERMISSION_DENIED: auth.uid=%s. Requiere is_schedule_publisher() o can_view_attendance_reports().',
        coalesce(auth.uid()::text, 'null')
      )::text,
      null::uuid,
      null::boolean, null::boolean, null::boolean,
      null::uuid, null::timestamptz, null::uuid, null::timestamptz,
      null::text,
      'PERMISSION_DENIED'::text,
      format(
        'publisher=%s viewer=%s',
        public.is_schedule_publisher(),
        public.can_view_attendance_reports()
      )::text,
      jsonb_build_object(
        'error_message', 'PERMISSION_DENIED',
        'error_detail', format('auth.uid=%s', coalesce(auth.uid()::text, 'null')),
        'error_hint', 'Ejecuta autenticado como RRHH/admin o usa el SQL Editor con rol postgres.',
        'error_context', 'diagnose_attendance_employee_state: permission gate',
        'sqlstate', '42501'
      );
    return;
  end if;

  select p.id, coalesce(p.full_name, p.username, 'Colaborador')
  into v_employee_id, v_employee_name
  from public.profiles p
  where lower(coalesce(p.full_name, p.username, '')) like '%' || lower(trim(p_employee_name)) || '%'
  order by
    case when lower(coalesce(p.full_name, p.username, '')) = lower(trim(p_employee_name)) then 0 else 1 end,
    p.full_name
  limit 1;

  if v_employee_id is null then
    return query select
      'error'::text,
      null::uuid,
      coalesce(p_employee_name, 'Colaborador')::text,
      null::date,
      v_calendar_date,
      null::uuid, null::timestamptz, null::text, null::text, null::text,
      null::text, null::text,
      format('Sin colaborador que coincida con "%s".', p_employee_name)::text,
      null::uuid,
      null::boolean, null::boolean, null::boolean,
      null::uuid, null::timestamptz, null::uuid, null::timestamptz,
      null::text,
      format('EMPLOYEE_NOT_FOUND: "%s"', p_employee_name)::text,
      'Verifica nombre en profiles.full_name / profiles.username.'::text,
      jsonb_build_object(
        'error_message', format('Sin colaborador que coincida con "%s".', p_employee_name),
        'error_detail', format('search=%s range=%s..%s', p_employee_name, p_start_date, p_end_date),
        'error_hint', 'Prueba con un fragmento del nombre: Osman, Mois, Mazáriegos.',
        'error_context', 'diagnose_attendance_employee_state: employee lookup',
        'sqlstate', 'P0002'
      );
    return;
  end if;

  return query select
    'profile'::text,
    v_employee_id,
    v_employee_name,
    null::date,
    v_calendar_date,
    null::uuid, null::timestamptz, null::text, null::text, null::text,
    null::text, null::text, null::text, null::uuid,
    null::boolean, null::boolean, null::boolean,
    null::uuid, null::timestamptz, null::uuid, null::timestamptz,
    null::text, null::text,
    format('Rango diagnóstico: %s a %s. Hoy GT: %s.%s',
      p_start_date,
      p_end_date,
      v_calendar_date,
      case when auth.uid() is null then ' Modo SQL Editor (sin JWT).' else '' end
    )::text,
    null::jsonb;

  -- Open entry (global, not limited to date range)
  select m.* into v_open_entry
  from public.attendance_marks m
  where m.employee_id = v_employee_id
    and m.mark_type = 'entrada'
    and not exists (
      select 1
      from public.attendance_marks out_mark
      where out_mark.employee_id = m.employee_id
        and out_mark.mark_type in ('salida_final', 'salida')
        and out_mark.marked_at > m.marked_at
    )
  order by m.marked_at desc
  limit 1;

  if v_open_entry.id is not null then
    select m.* into v_open_meal
    from public.attendance_marks m
    where m.employee_id = v_employee_id
      and m.mark_type in ('salida_comida', 'bano_inicio')
      and m.marked_at > v_open_entry.marked_at
      and not exists (
        select 1
        from public.attendance_marks back_mark
        where back_mark.employee_id = m.employee_id
          and back_mark.mark_type in ('regreso_comida', 'bano_regreso')
          and back_mark.marked_at > m.marked_at
      )
    order by m.marked_at desc
    limit 1;

    v_age_days := v_calendar_date - coalesce(
      v_open_entry.labor_date,
      (v_open_entry.marked_at at time zone v_tz)::date
    );

    select exists (
      select 1
      from public.employee_schedules s
      where s.employee_id = v_employee_id
        and s.shift_date = coalesce(v_open_entry.labor_date, (v_open_entry.marked_at at time zone v_tz)::date)
        and s.status in ('draft', 'published')
        and s.is_work_day = true
        and s.start_time is not null
        and s.end_time is not null
        and s.end_time <= s.start_time
    ) into v_sched_overnight;

    return query select
      'open_entry'::text,
      v_employee_id,
      v_employee_name,
      coalesce(v_open_entry.labor_date, (v_open_entry.marked_at at time zone v_tz)::date),
      v_calendar_date,
      v_open_entry.id,
      v_open_entry.marked_at,
      v_open_entry.mark_type,
      v_open_entry.classification,
      v_open_entry.approval_status,
      v_open_entry.device_id,
      v_open_entry.device_name,
      v_open_entry.observation,
      v_open_entry.related_mark_id,
      true,
      v_open_meal.id is not null,
      coalesce(v_open_entry.labor_date, (v_open_entry.marked_at at time zone v_tz)::date) < v_calendar_date,
      v_open_entry.id,
      v_open_entry.marked_at,
      v_open_meal.id,
      v_open_meal.marked_at,
      case
        when v_open_meal.id is not null then 'regreso_comida'
        else 'salida_comida o salida_final'
      end,
      case
        when v_open_meal.id is not null then 'Comida abierta: debe regresar antes de salida final.'
        else 'Entrada abierta bloquea nueva entrada hasta salida_final.'
      end,
      format(
        'Entrada abierta hace %s día(s). labor_date=%s. ¿Horario publicado cruza medianoche ese día? %s. ¿Huérfano probable? %s (entrada sin salida_final, edad=%s d). Cierre RRHH: close_open_attendance_shift(%s).',
        v_age_days,
        coalesce(v_open_entry.labor_date::text, '-'),
        case when v_sched_overnight then 'SÍ' else 'NO' end,
        case when v_age_days >= 1 and not v_sched_overnight then 'SÍ' else 'REVISAR' end,
        v_age_days,
        v_employee_id
      ),
      null::jsonb;

    if v_open_meal.id is not null then
      return query select
        'open_meal'::text,
        v_employee_id,
        v_employee_name,
        coalesce(v_open_meal.labor_date, (v_open_meal.marked_at at time zone v_tz)::date),
        v_calendar_date,
        v_open_meal.id,
        v_open_meal.marked_at,
        v_open_meal.mark_type,
        v_open_meal.classification,
        v_open_meal.approval_status,
        v_open_meal.device_id,
        v_open_meal.device_name,
        v_open_meal.observation,
        v_open_meal.related_mark_id,
        true,
        true,
        coalesce(v_open_entry.labor_date, (v_open_entry.marked_at at time zone v_tz)::date) < v_calendar_date,
        v_open_entry.id,
        v_open_entry.marked_at,
        v_open_meal.id,
        v_open_meal.marked_at,
        'regreso_comida'::text,
        'Bloquea segunda salida_comida y salida_final hasta regreso_comida.'::text,
        format('Comida abierta desde %s. Vinculada a entrada %s.',
          to_char(v_open_meal.marked_at at time zone v_tz, 'DD/MM/YYYY HH24:MI'),
          v_open_entry.id),
        null::jsonb;
    end if;
  else
    return query select
      'open_entry'::text,
      v_employee_id,
      v_employee_name,
      null::date,
      v_calendar_date,
      null::uuid, null::timestamptz, null::text, null::text, null::text,
      null::text, null::text, null::text, null::uuid,
      false, false, false,
      null::uuid, null::timestamptz, null::uuid, null::timestamptz,
      'entrada'::text,
      null::text,
      'Sin entrada abierta global.'::text,
      null::jsonb;
  end if;

  -- Marks in range
  return query
  select
    'mark'::text,
    v_employee_id,
    v_employee_name,
    coalesce(m.labor_date, (m.marked_at at time zone v_tz)::date),
    (m.marked_at at time zone v_tz)::date,
    m.id,
    m.marked_at,
    m.mark_type,
    m.classification,
    m.approval_status,
    m.device_id,
    m.device_name,
    m.observation,
    m.related_mark_id,
    v_open_entry.id is not null,
    v_open_meal.id is not null,
    coalesce(v_open_entry.labor_date, (v_open_entry.marked_at at time zone v_tz)::date) < v_calendar_date,
    v_open_entry.id,
    v_open_entry.marked_at,
    v_open_meal.id,
    v_open_meal.marked_at,
    null::text,
    null::text,
    format('marked_at GT=%s', to_char(m.marked_at at time zone v_tz, 'DD/MM/YYYY HH24:MI:SS')),
    null::jsonb
  from public.attendance_marks m
  where m.employee_id = v_employee_id
    and coalesce(m.labor_date, (m.marked_at at time zone v_tz)::date)
      between p_start_date and p_end_date
  order by m.marked_at;

  -- Schedules in range
  for v_sched in
    select
      s.shift_date,
      s.status,
      s.is_work_day,
      s.start_time,
      s.end_time,
      s.shift_type,
      coalesce(st.name, s.shift_type) as shift_type_name
    from public.employee_schedules s
    left join public.shift_types st on st.id = s.shift_type_id
    where s.employee_id = v_employee_id
      and s.shift_date between p_start_date and p_end_date
    order by s.shift_date, s.block_order, s.start_time
  loop
    return query select
      'schedule'::text,
      v_employee_id,
      v_employee_name,
      v_sched.shift_date,
      v_calendar_date,
      null::uuid, null::timestamptz, null::text, null::text, null::text,
      null::text, null::text, null::text, null::uuid,
      v_open_entry.id is not null,
      v_open_meal.id is not null,
      false,
      v_open_entry.id,
      v_open_entry.marked_at,
      v_open_meal.id,
      v_open_meal.marked_at,
      null::text,
      null::text,
      format('%s %s-%s work=%s type=%s',
        v_sched.status,
        coalesce(v_sched.start_time::text, '-'),
        coalesce(v_sched.end_time::text, '-'),
        v_sched.is_work_day,
        v_sched.shift_type_name),
      null::jsonb;
  end loop;

  -- Custom schedule exceptions in range
  return query
  select
    'custom_schedule'::text,
    v_employee_id,
    v_employee_name,
    coalesce(ecs.specific_date, p_start_date),
    v_calendar_date,
    ecs.id,
    null::timestamptz,
    'exception'::text,
    null::text,
    ecs.status,
    null::text,
    null::text,
    ecs.notes,
    null::uuid,
    v_open_entry.id is not null,
    v_open_meal.id is not null,
    false,
    v_open_entry.id,
    v_open_entry.marked_at,
    v_open_meal.id,
    v_open_meal.marked_at,
    null::text,
    null::text,
    format('specific=%s weekday=%s %s-%s active=%s',
      coalesce(ecs.specific_date::text, '-'),
      coalesce(ecs.weekday::text, '-'),
      coalesce(ecs.start_time::text, 'null'),
      coalesce(ecs.end_time::text, 'null'),
      ecs.status),
    null::jsonb
  from public.employee_custom_schedules ecs
  where ecs.profile_id = v_employee_id
    and ecs.status = 'active'
    and (
      (ecs.specific_date between p_start_date and p_end_date)
      or (ecs.start_date <= p_end_date and coalesce(ecs.end_date, p_end_date) >= p_start_date)
    );

  v_ctx := public.resolve_attendance_context(v_employee_id, 'entrada', now());
  v_state_entrada := public.get_attendance_marking_state(v_employee_id, 'entrada');
  v_state_comida := public.get_attendance_marking_state(v_employee_id, 'salida_comida');
  v_state_regreso := public.get_attendance_marking_state(v_employee_id, 'regreso_comida');
  v_state_salida := public.get_attendance_marking_state(v_employee_id, 'salida_final');

  return query select
    'context'::text,
    v_employee_id,
    v_employee_name,
    (v_ctx ->> 'labor_date')::date,
    (v_ctx ->> 'calendar_date')::date,
    null::uuid, null::timestamptz, null::text, null::text, null::text,
    null::text, null::text, null::text, null::uuid,
    coalesce((v_ctx ->> 'has_open_entry')::boolean, false),
    coalesce((v_ctx ->> 'has_open_meal')::boolean, false),
    coalesce((v_ctx ->> 'overnight_shift')::boolean, false),
    nullif(v_ctx ->> 'open_entry_id', '')::uuid,
    nullif(v_ctx ->> 'open_entry_marked_at', '')::timestamptz,
    nullif(v_ctx ->> 'open_meal_id', '')::uuid,
    null::timestamptz,
    null::text,
    null::text,
    'resolve_attendance_context(entrada)'::text,
    v_ctx;

  return query select
    'marking_state'::text,
    v_employee_id,
    v_employee_name,
    (v_state_entrada ->> 'labor_date')::date,
    v_calendar_date,
    null::uuid, null::timestamptz,
    'entrada'::text,
    v_state_entrada ->> 'classification',
    v_state_entrada ->> 'approval_status',
    null::text, null::text, null::text, null::uuid,
    coalesce((v_state_entrada ->> 'has_open_entry')::boolean, false),
    coalesce((v_state_entrada ->> 'has_open_meal')::boolean, false),
    coalesce((v_state_entrada ->> 'overnight_shift')::boolean, false),
    null::uuid, null::timestamptz, null::uuid, null::timestamptz,
    case when coalesce((v_state_entrada ->> 'allowed_for_entrada')::boolean, false) then 'entrada' else null end,
    v_state_entrada ->> 'reason',
    format('reason_code=%s allowed=%s allowed_for_entrada=%s allowed_for_completion=%s',
      v_state_entrada ->> 'reason_code',
      v_state_entrada ->> 'allowed',
      v_state_entrada ->> 'allowed_for_entrada',
      v_state_entrada ->> 'allowed_for_completion'),
    v_state_entrada;

  return query select
    'marking_state'::text,
    v_employee_id,
    v_employee_name,
    (v_state_comida ->> 'labor_date')::date,
    v_calendar_date,
    null::uuid, null::timestamptz,
    'salida_comida'::text,
    v_state_comida ->> 'classification',
    v_state_comida ->> 'approval_status',
    null::text, null::text, null::text, null::uuid,
    coalesce((v_state_comida ->> 'has_open_entry')::boolean, false),
    coalesce((v_state_comida ->> 'has_open_meal')::boolean, false),
    coalesce((v_state_comida ->> 'overnight_shift')::boolean, false),
    null::uuid, null::timestamptz, null::uuid, null::timestamptz,
    case when coalesce((v_state_comida ->> 'allowed')::boolean, false) then 'salida_comida' else null end,
    v_state_comida ->> 'reason',
    format('reason_code=%s allowed=%s allowed_for_completion=%s RPC=get_attendance_marking_state',
      v_state_comida ->> 'reason_code',
      v_state_comida ->> 'allowed',
      v_state_comida ->> 'allowed_for_completion'),
    v_state_comida;

  return query select
    'marking_state'::text,
    v_employee_id,
    v_employee_name,
    (v_state_regreso ->> 'labor_date')::date,
    v_calendar_date,
    null::uuid, null::timestamptz,
    'regreso_comida'::text,
    v_state_regreso ->> 'classification',
    v_state_regreso ->> 'approval_status',
    null::text, null::text, null::text, null::uuid,
    coalesce((v_state_regreso ->> 'has_open_entry')::boolean, false),
    coalesce((v_state_regreso ->> 'has_open_meal')::boolean, false),
    coalesce((v_state_regreso ->> 'overnight_shift')::boolean, false),
    null::uuid, null::timestamptz, null::uuid, null::timestamptz,
    case when coalesce((v_state_regreso ->> 'allowed')::boolean, false) then 'regreso_comida' else null end,
    v_state_regreso ->> 'reason',
    format('reason_code=%s allowed=%s', v_state_regreso ->> 'reason_code', v_state_regreso ->> 'allowed'),
    v_state_regreso;

  return query select
    'marking_state'::text,
    v_employee_id,
    v_employee_name,
    (v_state_salida ->> 'labor_date')::date,
    v_calendar_date,
    null::uuid, null::timestamptz,
    'salida_final'::text,
    v_state_salida ->> 'classification',
    v_state_salida ->> 'approval_status',
    null::text, null::text, null::text, null::uuid,
    coalesce((v_state_salida ->> 'has_open_entry')::boolean, false),
    coalesce((v_state_salida ->> 'has_open_meal')::boolean, false),
    coalesce((v_state_salida ->> 'overnight_shift')::boolean, false),
    null::uuid, null::timestamptz, null::uuid, null::timestamptz,
    case when coalesce((v_state_salida ->> 'allowed')::boolean, false) then 'salida_final' else null end,
    v_state_salida ->> 'reason',
    format('reason_code=%s allowed=%s. HR close: close_open_attendance_shift(%s)',
      v_state_salida ->> 'reason_code',
      v_state_salida ->> 'allowed',
      v_employee_id),
    v_state_salida;

  -- Terminal UI simulation (matches AttendanceTerminal.jsx disabled rules)
  v_next := case
    when v_open_entry.id is null then 'entrada'
    when v_open_meal.id is not null then 'regreso_comida'
    else 'salida_comida o salida_final'
  end;

  v_block := case
    when v_open_entry.id is not null and v_open_meal.id is null then
      'salida_comida: backend allowed=' || coalesce(v_state_comida ->> 'allowed', '?')
        || '. UI también exige isCheckedIn/has_open_entry y activeMeal=false.'
    when v_open_entry.id is null then
      'salida_comida: sin entrada activa en backend.'
    else
      'salida_comida bloqueada: comida abierta.'
  end;

  return query select
    'terminal_ui'::text,
    v_employee_id,
    v_employee_name,
    (v_ctx ->> 'labor_date')::date,
    v_calendar_date,
    null::uuid, null::timestamptz, null::text, null::text, null::text,
    null::text, null::text, null::text, null::uuid,
    v_open_entry.id is not null,
    v_open_meal.id is not null,
    coalesce((v_ctx ->> 'overnight_shift')::boolean, false),
    v_open_entry.id,
    v_open_entry.marked_at,
    v_open_meal.id,
    v_open_meal.marked_at,
    v_next,
    v_block,
    'Ver filas marking_state y open_* para causa. Mensaje kiosk viene de get_attendance_marking_state → reason.'::text,
    jsonb_build_object(
      'entrada', v_state_entrada,
      'salida_comida', v_state_comida,
      'regreso_comida', v_state_regreso,
      'salida_final', v_state_salida
    );

exception
  when others then
    get stacked diagnostics
      v_err_msg = message_text,
      v_err_detail = pg_exception_detail,
      v_err_hint = pg_exception_hint,
      v_err_context = pg_exception_context;

    v_err_state := SQLSTATE;

    return query select
      'error'::text,
      v_employee_id,
      coalesce(v_employee_name, p_employee_name, 'Colaborador')::text,
      null::date,
      v_calendar_date,
      null::uuid, null::timestamptz, null::text, null::text, null::text,
      null::text, null::text,
      coalesce(v_err_msg, 'Error desconocido en diagnose_attendance_employee_state')::text,
      null::uuid,
      null::boolean, null::boolean, null::boolean,
      null::uuid, null::timestamptz, null::uuid, null::timestamptz,
      null::text,
      coalesce(v_err_msg, 'Error desconocido')::text,
      coalesce(v_err_detail, '-')::text,
      jsonb_build_object(
        'error_message', v_err_msg,
        'error_detail', v_err_detail,
        'error_hint', v_err_hint,
        'error_context', v_err_context,
        'sqlstate', v_err_state,
        'employee_name_search', p_employee_name,
        'start_date', p_start_date,
        'end_date', p_end_date
      );
end;
$$;


ALTER FUNCTION "public"."diagnose_attendance_employee_state"("p_employee_name" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."diagnose_attendance_employee_state"("p_employee_name" "text", "p_start_date" "date", "p_end_date" "date") IS 'Diagnóstico de marcajes, turno abierto, marking_state por tipo y simulación UI terminal.';



CREATE OR REPLACE FUNCTION "public"."diagnose_attendance_mark_permission"("p_employee_id" "uuid") RETURNS TABLE("mark_type" "text", "permission_allowed" boolean, "permission_reason_code" "text", "permission_reason" "text", "marking_state_allowed" boolean, "marking_state_reason_code" "text", "aligned" boolean, "has_open_entry" boolean, "has_open_meal" boolean, "next_expected_mark" "text", "labor_date" "date", "classification" "text", "approval_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_type text;
  v_perm public.attendance_mark_permission;
  v_state jsonb;
begin
  foreach v_type in array array['entrada', 'salida_comida', 'regreso_comida', 'salida_final']
  loop
    v_perm := public.resolve_attendance_mark_permission(p_employee_id, v_type, now());
    v_state := public.get_attendance_marking_state(p_employee_id, v_type);

    mark_type := v_type;
    permission_allowed := v_perm.allowed;
    permission_reason_code := v_perm.reason_code;
    permission_reason := v_perm.reason;
    marking_state_allowed := coalesce((v_state ->> 'allowed')::boolean, false);
    marking_state_reason_code := v_state ->> 'reason_code';
    aligned := v_perm.allowed = coalesce((v_state ->> 'allowed')::boolean, false);
    has_open_entry := v_perm.has_open_entry;
    has_open_meal := v_perm.has_open_meal;
    next_expected_mark := v_perm.next_expected_mark;
    labor_date := v_perm.labor_date;
    classification := v_perm.classification;
    approval_status := v_perm.approval_status;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."diagnose_attendance_mark_permission"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diagnose_pos_catalog_health"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'total_products', (select count(*)::int from public.pos_products),
    'active_products', (select count(*)::int from public.pos_products where active = true),
    'products_with_image', (
      select count(*)::int from public.pos_products
      where image_url is not null and btrim(image_url) <> ''
    ),
    'products_with_inline_image', (
      select count(*)::int from public.pos_products where image_url like 'data:%'
    ),
    'products_with_data_image', (
      select count(*)::int from public.pos_products where image_url like 'data:image%'
    ),
    'products_with_http_image', (
      select count(*)::int from public.pos_products
      where image_url like 'http://%' or image_url like 'https://%'
    ),
    'products_with_storage_image', (
      select count(*)::int from public.pos_products
      where image_url like '%/storage/v1/object/public/pos-product-images/%'
    ),
    'max_image_url_bytes', (
      select coalesce(max(length(coalesce(image_url, ''))), 0)::int from public.pos_products
    ),
    'avg_image_url_bytes', (
      select coalesce(avg(length(image_url)), 0)::int
      from public.pos_products
      where image_url is not null and btrim(image_url) <> ''
    ),
    'avg_heavy_column_bytes', (
      select coalesce(avg(
        length(coalesce(name, ''))
        + length(coalesce(description, ''))
        + length(coalesce(image_url, ''))
      ), 0)::int
      from public.pos_products
    ),
    'heaviest_images', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', h.id,
        'name', h.name,
        'active', h.active,
        'image_url_bytes', h.image_bytes,
        'is_base64', h.is_base64,
        'is_storage_url', h.is_storage_url,
        'is_http_url', h.is_http_url,
        'preview', left(coalesce(h.image_url, ''), 80)
      ) order by h.image_bytes desc), '[]'::jsonb)
      from (
        select
          id,
          name,
          active,
          image_url,
          length(coalesce(image_url, '')) as image_bytes,
          image_url like 'data:%' as is_base64,
          image_url like '%/storage/v1/object/public/pos-product-images/%' as is_storage_url,
          image_url like 'http://%' or image_url like 'https://%' as is_http_url
        from public.pos_products
        where image_url is not null and btrim(image_url) <> ''
        order by length(coalesce(image_url, '')) desc
        limit 20
      ) h
    ),
    'recent_products', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', r.id,
        'name', r.name,
        'active', r.active,
        'product_type', r.product_type,
        'created_at', r.created_at,
        'image_url_bytes', length(coalesce(r.image_url, '')),
        'has_base64_image', r.image_url like 'data:%',
        'has_storage_image', r.image_url like '%/storage/v1/object/public/pos-product-images/%'
      ) order by r.created_at desc), '[]'::jsonb)
      from (
        select id, name, active, product_type, created_at, image_url
        from public.pos_products
        order by created_at desc
        limit 20
      ) r
    ),
    'indexes', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'name', indexname,
        'definition', indexdef
      ) order by indexname), '[]'::jsonb)
      from pg_indexes
      where schemaname = 'public' and tablename = 'pos_products'
    ),
    'rls_policies', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'name', policyname,
        'cmd', cmd,
        'roles', roles
      ) order by policyname), '[]'::jsonb)
      from pg_policies
      where schemaname = 'public' and tablename = 'pos_products'
    ),
    'triggers', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'name', trigger_name,
        'timing', action_timing,
        'event', event_manipulation
      ) order by trigger_name), '[]'::jsonb)
      from information_schema.triggers
      where event_object_schema = 'public' and event_object_table = 'pos_products'
    )
  );
$$;


ALTER FUNCTION "public"."diagnose_pos_catalog_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diagnose_pos_order_owner_integrity"() RETURNS TABLE("check_code" "text", "metric_value" bigint, "notes" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO '', 'public'
    AS $$
  select 'total_orders'::text, count(*)::bigint, null::text
  from public.pos_orders
  union all
  select 'waiter_id_null', count(*)::bigint, null
  from public.pos_orders where waiter_id is null
  union all
  select 'owner_profile_id_null', count(*)::bigint, null
  from public.pos_orders where owner_profile_id is null
  union all
  select 'waiter_id_orphan_no_profile', count(*)::bigint,
    'waiter_id sin fila en profiles'::text
  from public.pos_orders o
  where o.waiter_id is not null
    and not exists (select 1 from public.profiles p where p.id = o.waiter_id)
  union all
  select 'owner_profile_id_orphan_no_profile', count(*)::bigint,
    'owner_profile_id sin fila en profiles'::text
  from public.pos_orders o
  where o.owner_profile_id is not null
    and not exists (select 1 from public.profiles p where p.id = o.owner_profile_id)
  union all
  select 'waiter_name_empty', count(*)::bigint, null
  from public.pos_orders
  where nullif(trim(coalesce(waiter_name, '')), '') is null
  union all
  select 'owner_waiter_mismatch', count(*)::bigint,
    'ambos presentes pero distintos'::text
  from public.pos_orders
  where owner_profile_id is not null
    and waiter_id is not null
    and owner_profile_id <> waiter_id
  union all
  select 'open_orders_owner_null', count(*)::bigint, null
  from public.pos_orders
  where owner_profile_id is null
    and status in ('open', 'sent', 'awaiting_bill', 'sent_to_cashier', 'partially_paid')
  union all
  select 'historical_inactive_owner', count(*)::bigint,
    'owner con profile status != active'::text
  from public.pos_orders o
  join public.profiles p on p.id = o.owner_profile_id
  where p.status is distinct from 'active';
$$;


ALTER FUNCTION "public"."diagnose_pos_order_owner_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diagnose_pos_order_owner_orphans"() RETURNS TABLE("order_id" "uuid", "orphan_waiter_id" "uuid", "order_status" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO '', 'public'
    AS $$
  select
    o.id,
    o.waiter_id,
    o.status,
    o.created_at
  from public.pos_orders o
  where o.waiter_id is not null
    and not exists (select 1 from public.profiles p where p.id = o.waiter_id)
  order by o.created_at desc
  limit 500;
$$;


ALTER FUNCTION "public"."diagnose_pos_order_owner_orphans"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_recruitment_candidate"("p_candidate_id" "uuid", "p_reason" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.recruitment_candidates;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para descartar candidatos.';
  end if;

  update public.recruitment_candidates
  set
    pipeline_status = 'discarded',
    discard_reason = p_reason,
    discard_notes = nullif(trim(coalesce(p_notes, '')), ''),
    updated_by = auth.uid()
  where id = p_candidate_id
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'pipeline_status', v_row.pipeline_status);
end;
$$;


ALTER FUNCTION "public"."discard_recruitment_candidate"("p_candidate_id" "uuid", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_catering_quote_template"("p_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_source public.catering_quote_templates;
  v_items jsonb := '[]'::jsonb;
begin
  select * into v_source from public.catering_quote_templates where id = p_template_id;
  if not found then
    raise exception 'Plantilla no encontrada.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'item_type', item.item_type,
    'description', item.description,
    'quantity', item.quantity,
    'quantity_unit', item.quantity_unit,
    'unit_price', item.unit_price,
    'sort_order', item.sort_order
  ) order by item.sort_order asc), '[]'::jsonb)
  into v_items
  from public.catering_quote_template_items item
  where item.template_id = p_template_id;

  return public.upsert_catering_quote_template(
    null,
    v_source.name || ' (copia)',
    v_source.description,
    v_source.category,
    true,
    v_items
  );
end;
$$;


ALTER FUNCTION "public"."duplicate_catering_quote_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_requisition_with_current_units"("p_requisition_id" "uuid", "p_mode" "text" DEFAULT 'full_duplicate'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source public.requisitions;
  detail public.requisition_items;
  mode text := lower(nullif(trim(p_mode), ''));
  quantity_mode text;
  creation_source text;
  generation_mode text;
  trace_message text;
  line_specs jsonb;
  result jsonb;
  pre_warnings jsonb := '[]'::jsonb;
  pre_skipped integer := 0;
  pending_qty numeric;
begin
  if p_requisition_id is null then
    raise exception 'Requisicion invalida.';
  end if;

  if mode not in ('full_duplicate', 'pending_only', 'template') then
    raise exception 'Modo de duplicacion invalido.';
  end if;

  select * into source
  from public.requisitions
  where id = p_requisition_id;

  if source.id is null then
    raise exception 'Requisicion no encontrada.';
  end if;

  if coalesce(source.is_test, false) and not public.can_create_test_flow() then
    raise exception 'Solo Administracion puede duplicar pruebas de flujo.';
  end if;

  if mode = 'full_duplicate'
     and source.status not in ('draft', 'pending', 'approved', 'partially_fulfilled', 'pending_fulfillment') then
    raise exception 'Esta requisicion no puede duplicarse completa en su estado actual.';
  end if;

  if mode = 'pending_only'
     and source.status not in ('partially_fulfilled', 'pending_fulfillment') then
    raise exception 'Solo requisiciones parcialmente surtidas pueden duplicarse con cantidades pendientes.';
  end if;

  if mode = 'template'
     and source.status not in ('completed', 'partially_fulfilled', 'pending_fulfillment', 'cancelled') then
    raise exception 'Esta requisicion no puede usarse como plantilla en su estado actual.';
  end if;

  quantity_mode := case when mode = 'pending_only' then 'pending_only' else 'source_requested' end;

  if mode = 'pending_only' then
    for detail in
      select *
      from public.requisition_items
      where requisition_id = source.id
      order by created_at asc
    loop
      pending_qty := greatest(
        coalesce(detail.requested_quantity, 0) - coalesce(detail.delivered_quantity, 0),
        0
      );
      if pending_qty <= 0 then
        pre_skipped := pre_skipped + 1;
        pre_warnings := pre_warnings || jsonb_build_array(jsonb_build_object(
          'item_id', detail.item_id,
          'item_name', detail.item_name,
          'reason', 'sin_cantidad_pendiente',
          'message', coalesce(detail.item_name, 'Producto') || ' no tiene cantidad pendiente para copiar.'
        ));
      end if;
    end loop;
  end if;

  line_specs := public._requisition_line_specs_from_source(source.id, quantity_mode);

  if jsonb_array_length(coalesce(line_specs, '[]'::jsonb)) = 0 then
    raise exception 'No hay productos con cantidad valida para generar la nueva requisicion.';
  end if;

  if mode = 'template' then
    creation_source := 'template_requisition';
    generation_mode := 'template';
    trace_message := 'Nueva requisicion creada usando ' || source.requisition_number || ' como plantilla.';
  elsif mode = 'pending_only' then
    creation_source := 'duplicate_pending';
    generation_mode := 'pending_only';
    trace_message := 'Duplicada desde ' || source.requisition_number || ' con cantidades pendientes y configuracion actual del inventario.';
  else
    creation_source := 'duplicate_full';
    generation_mode := 'full_duplicate';
    trace_message := 'Duplicada desde ' || source.requisition_number || ' con configuracion actual del inventario.';
  end if;

  result := public.create_draft_requisition_with_current_config(
    jsonb_build_object(
      'from_area_id', source.from_area_id,
      'to_area_id', source.to_area_id,
      'priority', source.priority,
      'notes', source.notes,
      'is_test', coalesce(source.is_test, false)
    ),
    line_specs,
    jsonb_build_object(
      'creation_source', creation_source,
      'generation_mode', generation_mode,
      'source_requisition_id', source.id,
      'trace_message', trace_message
    )
  );

  return result
    || jsonb_build_object(
      'duplication_mode', generation_mode,
      'source_requisition_number', source.requisition_number,
      'items_skipped', coalesce((result ->> 'items_skipped')::integer, 0) + pre_skipped,
      'warnings', coalesce(result -> 'warnings', '[]'::jsonb) || pre_warnings
    );
end;
$$;


ALTER FUNCTION "public"."duplicate_requisition_with_current_units"("p_requisition_id" "uuid", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_schedule_week"("p_source_week_start" "date", "p_target_week_start" "date", "p_options" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_source_start date := p_source_week_start;
  v_target_start date := p_target_week_start;
  v_source_end date;
  v_target_end date;
  v_day_offset integer;
  v_destination_mode text := coalesce(nullif(trim(p_options ->> 'destination_mode'), ''), 'replace_drafts');
  v_dry_run boolean := coalesce((p_options ->> 'dry_run')::boolean, false);
  v_skip_inactive boolean := coalesce((p_options ->> 'skip_inactive_employees')::boolean, false);
  v_copy_statuses text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_options -> 'copy_statuses', '["draft","published"]'::jsonb))),
    array['draft', 'published']
  );
  v_row public.employee_schedules;
  v_profile public.profiles;
  v_shift_type public.shift_types;
  v_normalized jsonb;
  v_errors jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_source_by_day jsonb := '{}'::jsonb;
  v_copied_by_day jsonb := '{}'::jsonb;
  v_target_existing jsonb;
  v_target_draft_count integer := 0;
  v_target_published_count integer := 0;
  v_total_source integer := 0;
  v_copied_count integer := 0;
  v_skipped_count integer := 0;
  v_deleted_draft_count integer := 0;
  v_distinct_source_days integer := 0;
  v_day_key text;
  v_day_count integer;
  v_error jsonb;
  v_label text;
begin
  if not public.is_schedule_editor() then
    return jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array(jsonb_build_object(
        'code', 'permission_denied',
        'severity', 'blocking',
        'message', 'No tienes permiso para duplicar horarios.'
      ))
    );
  end if;

  if not public.is_schedule_week_monday(v_source_start) or not public.is_schedule_week_monday(v_target_start) then
    return jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array(jsonb_build_object(
        'code', 'invalid_week_start',
        'severity', 'blocking',
        'message', 'La semana origen y destino deben iniciar en lunes.'
      ))
    );
  end if;

  if v_source_start = v_target_start then
    return jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array(jsonb_build_object(
        'code', 'same_week',
        'severity', 'blocking',
        'message', 'La semana destino debe ser distinta a la semana origen.'
      ))
    );
  end if;

  v_source_end := v_source_start + 6;
  v_target_end := v_target_start + 6;
  v_day_offset := v_target_start - v_source_start;

  perform pg_advisory_xact_lock(hashtext('duplicate_schedule_week:' || v_target_start::text));

  select
    count(*) filter (where status = 'draft'),
    count(*) filter (where status = 'published'),
    count(*)
  into v_target_draft_count, v_target_published_count, v_day_count
  from public.employee_schedules
  where shift_date between v_target_start and v_target_end;

  v_target_existing := jsonb_build_object(
    'draft', v_target_draft_count,
    'published', v_target_published_count,
    'total', v_target_draft_count + v_target_published_count
  );

  if v_target_published_count > 0 then
    return jsonb_build_object(
      'ok', false,
      'dry_run', v_dry_run,
      'source_week_start', v_source_start,
      'target_week_start', v_target_start,
      'destination_mode', v_destination_mode,
      'total_source', 0,
      'copied_count', 0,
      'skipped_count', 0,
      'target_existing_before', v_target_existing,
      'errors', jsonb_build_array(jsonb_build_object(
        'code', 'target_has_published',
        'severity', 'blocking',
        'message', 'La semana destino ya tiene horarios publicados. Desbloquea la edicion o elige otra semana.'
      ))
    );
  end if;

  if v_destination_mode = 'block' and (v_target_draft_count + v_target_published_count) > 0 then
    return jsonb_build_object(
      'ok', false,
      'dry_run', v_dry_run,
      'source_week_start', v_source_start,
      'target_week_start', v_target_start,
      'destination_mode', v_destination_mode,
      'total_source', 0,
      'copied_count', 0,
      'skipped_count', 0,
      'target_existing_before', v_target_existing,
      'errors', jsonb_build_array(jsonb_build_object(
        'code', 'destination_blocked',
        'severity', 'blocking',
        'message', 'La semana destino ya tiene horarios. Usa reemplazar borradores o vacia la semana.'
      ))
    );
  end if;

  for v_row in
    select s.*
    from public.employee_schedules s
    where s.shift_date between v_source_start and v_source_end
      and s.status = any (v_copy_statuses)
    order by s.shift_date, s.employee_id, s.block_order, s.start_time nulls last
  loop
    v_total_source := v_total_source + 1;
    v_day_key := v_row.shift_date::text;
    v_source_by_day := v_source_by_day || jsonb_build_object(
      v_day_key,
      coalesce((v_source_by_day ->> v_day_key)::integer, 0) + 1
    );

    select * into v_profile from public.profiles where id = v_row.employee_id;
    v_label := coalesce(v_profile.full_name, v_profile.username, 'Colaborador');

    if v_profile.id is null or v_profile.status <> 'active' then
      if v_skip_inactive then
        v_skipped_count := v_skipped_count + 1;
        v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
          'code', 'inactive_employee_skipped',
          'message', format('Se omitio un bloque de %s el %s.', v_label, to_char(v_row.shift_date, 'DD Mon')),
          'employee_id', v_row.employee_id,
          'shift_date', v_row.shift_date,
          'schedule_id', v_row.id
        ));
        continue;
      end if;
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'code', 'inactive_employee',
        'severity', 'blocking',
        'message', format('%s esta inactivo pero tiene turnos en la semana origen (%s).', v_label, to_char(v_row.shift_date, 'DD Mon')),
        'employee_id', v_row.employee_id,
        'shift_date', v_row.shift_date,
        'schedule_id', v_row.id
      ));
      continue;
    end if;

    if v_row.shift_type_id is not null then
      select * into v_shift_type from public.shift_types where id = v_row.shift_type_id;
      if v_shift_type.id is null or v_shift_type.status <> 'active' then
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'code', 'inactive_shift_type',
          'severity', 'blocking',
          'message', format('%s tiene un tipo de turno inactivo el %s.', v_label, to_char(v_row.shift_date, 'DD Mon')),
          'employee_id', v_row.employee_id,
          'shift_date', v_row.shift_date,
          'schedule_id', v_row.id,
          'shift_type_id', v_row.shift_type_id
        ));
        continue;
      end if;
    elsif coalesce(v_row.is_work_day, true) and v_row.shift_type not in ('rest', 'asueto') then
      if nullif(trim(v_row.area), '') is null or v_row.start_time is null or v_row.end_time is null then
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'code', 'invalid_work_shift',
          'severity', 'blocking',
          'message', format('%s tiene un turno laboral incompleto el %s.', v_label, to_char(v_row.shift_date, 'DD Mon')),
          'employee_id', v_row.employee_id,
          'shift_date', v_row.shift_date,
          'schedule_id', v_row.id
        ));
        continue;
      end if;
    end if;

    begin
      v_normalized := public.normalize_employee_schedule_fields(
        v_row.shift_type_id,
        v_row.shift_type,
        v_row.is_work_day,
        v_row.area,
        v_row.start_time,
        v_row.end_time,
        v_row.break_minutes,
        v_row.position
      );
    exception when others then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'code', 'normalize_failed',
        'severity', 'blocking',
        'message', format('%s el %s: %s', v_label, to_char(v_row.shift_date, 'DD Mon'), sqlerrm),
        'employee_id', v_row.employee_id,
        'shift_date', v_row.shift_date,
        'schedule_id', v_row.id
      ));
      continue;
    end;

    v_copied_count := v_copied_count + 1;
    v_day_key := (v_row.shift_date + v_day_offset)::text;
    v_copied_by_day := v_copied_by_day || jsonb_build_object(
      v_day_key,
      coalesce((v_copied_by_day ->> v_day_key)::integer, 0) + 1
    );
  end loop;

  select count(distinct shift_date) into v_distinct_source_days
  from public.employee_schedules
  where shift_date between v_source_start and v_source_end
    and status = any (v_copy_statuses);

  if v_total_source = 0 then
    return jsonb_build_object(
      'ok', false,
      'dry_run', v_dry_run,
      'source_week_start', v_source_start,
      'target_week_start', v_target_start,
      'destination_mode', v_destination_mode,
      'total_source', 0,
      'copied_count', 0,
      'skipped_count', 0,
      'target_existing_before', v_target_existing,
      'errors', jsonb_build_array(jsonb_build_object(
        'code', 'source_empty',
        'severity', 'blocking',
        'message', 'La semana origen no tiene horarios para copiar.'
      ))
    );
  end if;

  if jsonb_array_length(v_errors) > 0 then
    return jsonb_build_object(
      'ok', false,
      'dry_run', v_dry_run,
      'source_week_start', v_source_start,
      'target_week_start', v_target_start,
      'destination_mode', v_destination_mode,
      'total_source', v_total_source,
      'copied_count', 0,
      'skipped_count', v_skipped_count,
      'deleted_draft_count', 0,
      'target_existing_before', v_target_existing,
      'source_by_day', v_source_by_day,
      'copied_by_day', '{}'::jsonb,
      'errors', v_errors,
      'warnings', v_warnings
    );
  end if;

  if v_distinct_source_days > 0 and v_distinct_source_days < 7 then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'source_partial_week',
      'message', format('La semana origen solo tiene planificacion en %s dias distintos.', v_distinct_source_days)
    ));
  end if;

  if v_dry_run then
    return jsonb_build_object(
      'ok', true,
      'dry_run', true,
      'source_week_start', v_source_start,
      'target_week_start', v_target_start,
      'destination_mode', v_destination_mode,
      'total_source', v_total_source,
      'copied_count', v_copied_count,
      'skipped_count', v_skipped_count,
      'deleted_draft_count', case when v_destination_mode = 'replace_drafts' then v_target_draft_count else 0 end,
      'target_existing_before', v_target_existing,
      'source_by_day', v_source_by_day,
      'copied_by_day', v_copied_by_day,
      'errors', '[]'::jsonb,
      'warnings', v_warnings
    );
  end if;

  if v_destination_mode = 'replace_drafts' and v_target_draft_count > 0 then
    delete from public.employee_schedules
    where shift_date between v_target_start and v_target_end
      and status = 'draft';
    get diagnostics v_deleted_draft_count = row_count;
  end if;

  for v_row in
    select s.*
    from public.employee_schedules s
    join public.profiles p on p.id = s.employee_id and p.status = 'active'
    where s.shift_date between v_source_start and v_source_end
      and s.status = any (v_copy_statuses)
    order by s.shift_date, s.employee_id, s.block_order, s.start_time nulls last
  loop
    if v_skip_inactive then
      -- inactive already filtered by join
      null;
    end if;

    v_normalized := public.normalize_employee_schedule_fields(
      v_row.shift_type_id,
      v_row.shift_type,
      v_row.is_work_day,
      v_row.area,
      v_row.start_time,
      v_row.end_time,
      v_row.break_minutes,
      v_row.position
    );

    insert into public.employee_schedules (
      employee_id, area, position, shift_date, start_time, end_time, break_minutes, notes,
      status, created_by, updated_by, is_work_day, shift_type, shift_type_id, block_order, day_notes
    ) values (
      v_row.employee_id,
      v_normalized ->> 'area',
      nullif(v_normalized ->> 'position', ''),
      v_row.shift_date + v_day_offset,
      nullif(v_normalized ->> 'start_time', '')::time,
      nullif(v_normalized ->> 'end_time', '')::time,
      (v_normalized ->> 'break_minutes')::integer,
      v_row.notes,
      'draft', auth.uid(), auth.uid(),
      (v_normalized ->> 'is_work_day')::boolean,
      v_normalized ->> 'shift_type',
      nullif(v_normalized ->> 'shift_type_id', '')::uuid,
      greatest(1, coalesce(v_row.block_order, 1)),
      v_row.day_notes
    );
  end loop;

  insert into public.schedule_change_logs (schedule_id, changed_by, change_type, new_value)
  values (
    null,
    auth.uid(),
    'week_duplicated',
    jsonb_build_object(
      'source_week_start', v_source_start,
      'target_week_start', v_target_start,
      'destination_mode', v_destination_mode,
      'total_source', v_total_source,
      'copied_count', v_copied_count,
      'skipped_count', v_skipped_count,
      'deleted_draft_count', v_deleted_draft_count,
      'source_by_day', v_source_by_day,
      'copied_by_day', v_copied_by_day
    )
  );

  return jsonb_build_object(
    'ok', true,
    'dry_run', false,
    'source_week_start', v_source_start,
    'target_week_start', v_target_start,
    'destination_mode', v_destination_mode,
    'total_source', v_total_source,
    'copied_count', v_copied_count,
    'skipped_count', v_skipped_count,
    'deleted_draft_count', v_deleted_draft_count,
    'target_existing_before', v_target_existing,
    'source_by_day', v_source_by_day,
    'copied_by_day', v_copied_by_day,
    'errors', '[]'::jsonb,
    'warnings', v_warnings
  );
end;
$$;


ALTER FUNCTION "public"."duplicate_schedule_week"("p_source_week_start" "date", "p_target_week_start" "date", "p_options" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_discipline_global_kpis"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'verbal_warnings', (
      select count(*)
      from public.employee_disciplinary_actions a
      join public.profiles p on p.id = a.profile_id and p.status = 'active'
      where a.action_type = 'verbal_warning'
        and a.status <> 'revoked'
    ),
    'memorandums', (
      select count(*)
      from public.employee_disciplinary_actions a
      join public.profiles p on p.id = a.profile_id and p.status = 'active'
      where a.action_type = 'memorandum'
        and a.status <> 'revoked'
    ),
    'suspensions', (
      select count(*)
      from public.employee_disciplinary_actions a
      join public.profiles p on p.id = a.profile_id and p.status = 'active'
      where a.action_type = 'suspension'
        and a.status <> 'revoked'
    ),
    'recurrences', (
      select count(*)
      from public.employee_incidents i
      join public.profiles p on p.id = i.profile_id and p.status = 'active'
      where i.is_recurrence = true
    ),
    'open_incidents', (
      select count(*)
      from public.employee_incidents i
      join public.profiles p on p.id = i.profile_id and p.status = 'active'
      where i.status in ('open', 'under_review')
    )
  );
$$;


ALTER FUNCTION "public"."employee_discipline_global_kpis"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_discipline_profile_kpis"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'verbal_warnings', (
      select count(*)
      from public.employee_disciplinary_actions a
      where a.profile_id = p_profile_id
        and a.action_type = 'verbal_warning'
        and a.status <> 'revoked'
    ),
    'memorandums', (
      select count(*)
      from public.employee_disciplinary_actions a
      where a.profile_id = p_profile_id
        and a.action_type = 'memorandum'
        and a.status <> 'revoked'
    ),
    'suspensions', (
      select count(*)
      from public.employee_disciplinary_actions a
      where a.profile_id = p_profile_id
        and a.action_type = 'suspension'
        and a.status <> 'revoked'
    ),
    'recurrences', (
      select count(*)
      from public.employee_incidents i
      where i.profile_id = p_profile_id
        and i.is_recurrence = true
    ),
    'open_incidents', (
      select count(*)
      from public.employee_incidents i
      where i.profile_id = p_profile_id
        and i.status in ('open', 'under_review')
    )
  );
$$;


ALTER FUNCTION "public"."employee_discipline_profile_kpis"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_expediente_completeness"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_required text[];
  v_filled text[];
  v_missing text[];
  v_required_count integer;
  v_filled_count integer;
begin
  v_required := public.employee_expediente_required_slots(p_profile_id);
  v_filled := public.employee_expediente_filled_slots(p_profile_id);
  select coalesce(array_agg(r order by r), '{}'::text[])
  into v_missing
  from unnest(v_required) r
  where not (r = any(v_filled));
  v_required_count := coalesce(array_length(v_required, 1), 0);
  v_filled_count := v_required_count - coalesce(array_length(v_missing, 1), 0);
  return jsonb_build_object(
    'required_count', v_required_count,
    'filled_count', greatest(v_filled_count, 0),
    'missing_count', coalesce(array_length(v_missing, 1), 0),
    'percent', case
      when v_required_count = 0 then 100
      else round((greatest(v_filled_count, 0)::numeric / v_required_count) * 100)
    end,
    'missing_slots', to_jsonb(v_missing)
  );
end;
$$;


ALTER FUNCTION "public"."employee_expediente_completeness"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_expediente_filled_slots"("p_profile_id" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(distinct slot order by slot), '{}'::text[])
  from (
    select ft.completeness_slot as slot
    from public.employee_file_versions v
    join public.employee_file_types ft on ft.code = v.file_type_code
    where v.profile_id = p_profile_id
      and v.is_current = true
      and (
        not ft.requires_signature
        or exists (
          select 1
          from public.employee_files f
          where f.id = v.employee_file_id
            and f.signature_status = 'signed'
        )
      )
    union
    select 'dpi' as slot
    where exists (
      select 1 from public.employee_file_versions v
      join public.employee_file_types ft on ft.code = v.file_type_code
      where v.profile_id = p_profile_id and v.is_current and ft.code = 'dpi_front'
    )
    and exists (
      select 1 from public.employee_file_versions v
      join public.employee_file_types ft on ft.code = v.file_type_code
      where v.profile_id = p_profile_id and v.is_current and ft.code = 'dpi_back'
    )
  ) filled;
$$;


ALTER FUNCTION "public"."employee_expediente_filled_slots"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_expediente_required_slots"("p_profile_id" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with profile_ctx as (
    select p.id, p.area_name, p.area_id
    from public.profiles p
    where p.id = p_profile_id
  )
  select coalesce(array_agg(distinct ft.completeness_slot order by ft.completeness_slot), '{}'::text[])
  from public.employee_file_types ft
  cross join profile_ctx ctx
  where ft.is_required = true
     or (
       ft.is_conditional = true
       and ft.completeness_slot = 'food_handling'
       and public.is_food_handling_area(ctx.area_name, ctx.area_id)
     );
$$;


ALTER FUNCTION "public"."employee_expediente_required_slots"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_expediente_status"("p_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_has_expired boolean;
  v_complete jsonb;
begin
  select exists (
    select 1
    from public.employee_file_versions v
    where v.profile_id = p_profile_id
      and v.is_current = true
      and not coalesce(v.no_expires, false)
      and v.expires_at is not null
      and v.expires_at < current_date
  ) into v_has_expired;

  if v_has_expired then
    return 'expired';
  end if;

  v_complete := public.employee_expediente_completeness(p_profile_id);
  if coalesce((v_complete ->> 'percent')::integer, 0) >= 100 then
    return 'complete';
  end if;
  return 'incomplete';
end;
$$;


ALTER FUNCTION "public"."employee_expediente_status"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_file_expiry_status"("p_expires_at" "date") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select public.employee_file_expiry_status(p_expires_at, false);
$$;


ALTER FUNCTION "public"."employee_file_expiry_status"("p_expires_at" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_file_expiry_status"("p_expires_at" "date", "p_no_expires" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when coalesce(p_no_expires, false) then 'none'
    when p_expires_at is null then 'none'
    when p_expires_at < current_date then 'expired'
    when p_expires_at <= current_date + 15 then 'orange'
    when p_expires_at <= current_date + 30 then 'warning'
    else 'valid'
  end;
$$;


ALTER FUNCTION "public"."employee_file_expiry_status"("p_expires_at" "date", "p_no_expires" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_operational_process_run"("p_process_template_id" "uuid", "p_run_date" "date" DEFAULT "public"."get_checklist_operational_date"(), "p_area" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_assignment_source" "text" DEFAULT 'recurrence'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_template public.operational_process_templates;
  v_existing public.operational_process_runs;
  v_process_run public.operational_process_runs;
  v_step public.operational_process_template_steps;
  v_child_run public.checklist_runs;
  v_run_step public.operational_process_run_steps;
  v_dep_run_step_id uuid;
  v_step_map jsonb := '{}'::jsonb;
  v_source text := coalesce(nullif(trim(p_assignment_source), ''), 'recurrence');
begin
  if v_source not in ('manual', 'recurrence') then
    raise exception 'assignment_source invalido.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('operational_process_run:' || p_process_template_id::text || '|' || p_run_date::text)
  );

  select * into v_template
  from public.operational_process_templates
  where id = p_process_template_id and status = 'active';

  if v_template.id is null then
    raise exception 'Proceso operativo no encontrado o inactivo.';
  end if;

  select * into v_existing
  from public.operational_process_runs
  where process_template_id = p_process_template_id
    and run_date = p_run_date
    and status <> 'cancelled'
  order by created_at asc
  limit 1
  for update;

  if v_existing.id is not null then
    return public.get_operational_process_run_detail(v_existing.id);
  end if;

  insert into public.operational_process_runs (
    process_template_id, run_date, status, area, notes, created_by
  )
  values (
    p_process_template_id,
    p_run_date,
    'pending',
    nullif(trim(coalesce(p_area, v_template.area, '')), ''),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  )
  returning * into v_process_run;

  for v_step in
    select * from public.operational_process_template_steps
    where process_template_id = p_process_template_id
    order by step_order asc, id asc
  loop
    v_child_run := public.create_checklist_run_from_template(
      v_step.child_template_id,
      p_run_date,
      v_source,
      v_step.assigned_profile_id,
      null,
      coalesce(v_step.area, v_process_run.area),
      v_step.assigned_role
    );

    v_dep_run_step_id := null;
    if v_step.depends_on_step_id is not null then
      v_dep_run_step_id := nullif(v_step_map ->> v_step.depends_on_step_id::text, '')::uuid;
    end if;

    insert into public.operational_process_run_steps (
      process_run_id, template_step_id, checklist_run_id, child_template_id,
      step_order, step_label, is_required, depends_on_run_step_id
    )
    values (
      v_process_run.id,
      v_step.id,
      v_child_run.id,
      v_step.child_template_id,
      v_step.step_order,
      v_step.step_label,
      v_step.is_required,
      v_dep_run_step_id
    )
    on conflict (process_run_id, checklist_run_id) do nothing
    returning * into v_run_step;

    if v_run_step.id is null then
      select * into v_run_step
      from public.operational_process_run_steps
      where process_run_id = v_process_run.id
        and checklist_run_id = v_child_run.id
      limit 1;
    end if;

    v_step_map := v_step_map || jsonb_build_object(v_step.id::text, v_run_step.id);
  end loop;

  perform public.recalculate_operational_process_run_status(v_process_run.id);

  return public.get_operational_process_run_detail(v_process_run.id);
end;
$$;


ALTER FUNCTION "public"."ensure_operational_process_run"("p_process_template_id" "uuid", "p_run_date" "date", "p_area" "text", "p_notes" "text", "p_assignment_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_operational_task_assignee_watchers"("p_task_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.task_watchers (task_id, profile_id, created_by)
  select p_task_id, ta.profile_id, auth.uid()
  from public.task_assignees ta
  where ta.task_id = p_task_id
    and ta.status = 'active'
  on conflict (task_id, profile_id) do nothing;
end;
$$;


ALTER FUNCTION "public"."ensure_operational_task_assignee_watchers"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_attendance_mark_chain"("p_mark_type" "text", "p_has_open_entry" boolean, "p_has_open_meal" boolean) RETURNS TABLE("allowed" boolean, "reason_code" "text", "reason" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_mark_type text := public.normalize_attendance_mark_type(p_mark_type);
begin
  case v_mark_type
    when 'entrada' then
      if coalesce(p_has_open_entry, false) then
        return query select
          false,
          'open_entry'::text,
          'Ya existe una entrada activa para este colaborador.'::text;
      else
        return query select true, 'allowed'::text, null::text;
      end if;

    when 'salida_comida' then
      if not coalesce(p_has_open_entry, false) then
        return query select
          false,
          'no_open_entry'::text,
          'No existe entrada activa para registrar salida a comida.'::text;
      elsif coalesce(p_has_open_meal, false) then
        return query select
          false,
          'open_meal'::text,
          'Ya existe una salida a comida pendiente de regreso.'::text;
      else
        return query select true, 'open_shift'::text, null::text;
      end if;

    when 'regreso_comida' then
      if not coalesce(p_has_open_meal, false) then
        return query select
          false,
          'no_open_meal'::text,
          'No existe salida a comida pendiente.'::text;
      else
        return query select true, 'open_shift'::text, null::text;
      end if;

    when 'salida_final' then
      if not coalesce(p_has_open_entry, false) then
        return query select
          false,
          'no_open_entry'::text,
          'No existe entrada activa para registrar salida final.'::text;
      elsif coalesce(p_has_open_meal, false) then
        return query select
          false,
          'open_meal'::text,
          'Registra el regreso de comida antes de la salida final.'::text;
      else
        return query select true, 'open_shift'::text, null::text;
      end if;

    else
      return query select
        false,
        'invalid_mark_type'::text,
        'Tipo de marcaje no valido.'::text;
  end case;
end;
$$;


ALTER FUNCTION "public"."evaluate_attendance_mark_chain"("p_mark_type" "text", "p_has_open_entry" boolean, "p_has_open_meal" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_checklist_run_item_incident"("run_item_id" "uuid") RETURNS "public"."checklist_incidents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_item public.checklist_run_items;
  template_item public.checklist_template_items;
  run_record public.checklist_runs;
  template_record public.checklist_templates;
  incident_record public.checklist_incidents;
  should_trigger boolean;
  should_fail boolean;
  expected text;
  severity_value text;
  roles text[];
  incident_title text;
  incident_description text;
  role_value text;
begin
  select * into run_item
  from public.checklist_run_items
  where id = run_item_id;

  if run_item.id is null then
    return null;
  end if;

  select * into template_item
  from public.checklist_template_items
  where id = run_item.template_item_id;

  select * into run_record
  from public.checklist_runs
  where id = run_item.run_id;

  select * into template_record
  from public.checklist_templates
  where id = coalesce(run_record.template_id, template_item.template_id);

  should_trigger := coalesce(run_item.triggers_incident, template_item.triggers_incident, false)
    or coalesce(run_item.generate_incident_on_no, template_item.generate_incident_on_no, false);

  if not should_trigger then
    return null;
  end if;

  expected := coalesce(
    nullif(trim(run_item.expected_response), ''),
    nullif(trim(template_item.expected_response), ''),
    case when coalesce(run_item.generate_incident_on_no, template_item.generate_incident_on_no, false) then 'si' else null end
  );

  should_fail := public.checklist_item_failed(
    run_item.response_type,
    expected,
    run_item.is_required,
    run_item.checked,
    run_item.response_text,
    run_item.response_number
  );

  if not should_fail then
    return null;
  end if;

  severity_value := coalesce(nullif(trim(run_item.incident_severity), ''), nullif(trim(template_item.incident_severity), ''), 'medium');
  roles := coalesce(nullif(run_item.notify_roles, '{}'::text[]), nullif(template_item.notify_roles, '{}'::text[]), array['admin','gerente_general','gerente']);
  incident_title := coalesce(template_record.title, 'Checklist') || ': ' || run_item.title;
  incident_description := concat_ws(E'\n',
    'Respuesta: ' || coalesce(nullif(run_item.response_text, ''), case when run_item.checked then 'checked' else 'unchecked' end),
    case when run_item.response_number is not null then 'Numero: ' || run_item.response_number::text else null end,
    case when nullif(trim(coalesce(run_item.comment, '')), '') is not null then 'Comentario: ' || run_item.comment else null end,
    case when nullif(trim(coalesce(run_item.photo_url, '')), '') is not null then 'Foto: ' || run_item.photo_url else null end
  );

  select * into incident_record
  from public.checklist_incidents
  where checklist_incidents.run_item_id = run_item.id
    and checklist_incidents.status in ('open', 'acknowledged', 'in_progress')
  limit 1;

  if incident_record.id is null then
    insert into public.checklist_incidents (
      run_id, run_item_id, template_id, template_item_id, title, description,
      area, severity, status, reported_by
    )
    values (
      run_record.id, run_item.id, template_record.id, template_item.id, incident_title,
      incident_description, coalesce(run_record.area, template_record.area), severity_value,
      'open', coalesce(run_item.completed_by, auth.uid())
    )
    returning * into incident_record;

    foreach role_value in array roles
    loop
      insert into public.notifications (
        user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
      )
      values (
        null,
        public.normalize_profile_role(role_value),
        'checklist_incident',
        'Incidencia en checklist',
        coalesce(template_record.title, 'Checklist') || ': ' || run_item.title || ' requiere atencion',
        'checklist_incident',
        incident_record.id::text,
        '/tasks?tab=checklists&view=incidents&id=' || incident_record.id::text,
        coalesce(run_item.completed_by, auth.uid())
      );
    end loop;
  else
    update public.checklist_incidents
    set
      title = incident_title,
      description = incident_description,
      severity = severity_value,
      area = coalesce(run_record.area, template_record.area),
      updated_at = now()
    where id = incident_record.id
    returning * into incident_record;
  end if;

  return incident_record;
end;
$$;


ALTER FUNCTION "public"."evaluate_checklist_run_item_incident"("run_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_checklist_run_item_incident_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.recalculate_checklist_run_points(new.run_id);
  perform public.evaluate_checklist_run_item_incident(new.id);
  return new;
end;
$$;


ALTER FUNCTION "public"."evaluate_checklist_run_item_incident_trigger"() OWNER TO "postgres";


