CREATE OR REPLACE FUNCTION "public"."evaluate_pos_inventory_deduction"("p_product" "public"."pos_products", "p_order_item" "public"."pos_order_items") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_mode text := public.get_inventory_deduction_mode();
  v_recipe public.standard_recipes;
  v_ingredient_count integer := 0;
begin
  if coalesce(p_order_item.is_test_item, false) then
    return jsonb_build_object('deduct', false, 'reason', 'test_item');
  end if;

  if public.is_inventory_migration_mode_active() and v_mode = 'active_recipes_only' then
    v_mode := 'disabled';
  end if;

  if v_mode = 'disabled' then
    return jsonb_build_object('deduct', false, 'reason', 'inventory_disabled');
  end if;

  if v_mode = 'strict' then
    if p_order_item.recipe_id is null then
      return jsonb_build_object('deduct', false, 'reason', 'missing_recipe');
    end if;
    return jsonb_build_object('deduct', true, 'reason', null);
  end if;

  if not coalesce(p_product.inventory_tracking_enabled, false) then
    return jsonb_build_object('deduct', false, 'reason', 'tracking_disabled');
  end if;

  if coalesce(p_product.recipe_status, 'missing') <> 'active' then
    return jsonb_build_object(
      'deduct', false,
      'reason', case coalesce(p_product.recipe_status, 'missing')
        when 'missing' then 'missing_recipe'
        else 'recipe_not_active'
      end
    );
  end if;

  if p_order_item.recipe_id is null then
    return jsonb_build_object('deduct', false, 'reason', 'missing_recipe');
  end if;

  select * into v_recipe
  from public.standard_recipes
  where id = p_order_item.recipe_id
    and active = true
    and recipe_type = 'final_product';

  if v_recipe.id is null then
    return jsonb_build_object('deduct', false, 'reason', 'recipe_not_active');
  end if;

  select count(*) into v_ingredient_count
  from public.recipe_ingredients
  where recipe_id = v_recipe.id;

  if v_ingredient_count = 0 then
    return jsonb_build_object('deduct', false, 'reason', 'recipe_incomplete');
  end if;

  return jsonb_build_object('deduct', true, 'reason', null);
end;
$$;


ALTER FUNCTION "public"."evaluate_pos_inventory_deduction"("p_product" "public"."pos_products", "p_order_item" "public"."pos_order_items") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."executive_gt_local_ts"("p_at" timestamp with time zone) RETURNS timestamp without time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (coalesce(p_at, now()) at time zone 'America/Guatemala');
$$;


ALTER FUNCTION "public"."executive_gt_local_ts"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."executive_operational_day_start"("p_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with local_ts as (
    select public.executive_gt_local_ts(p_at) as ts
  ),
  op_date as (
    select case
      when ts::time >= time '04:00:00' then ts::date
      else ts::date - 1
    end as d
    from local_ts
  )
  select ((select d from op_date) + time '04:00:00') at time zone 'America/Guatemala';
$$;


ALTER FUNCTION "public"."executive_operational_day_start"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."executive_partial_open_snapshot"("p_reference_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ref timestamptz := coalesce(p_reference_at, now());
begin
  if auth.uid() is null then
    raise exception 'Authentication required for executive partial-open snapshot.';
  end if;

  if not public.is_executive_dashboard_reader() then
    raise exception 'No tienes permiso para consultar metricas ejecutivas.';
  end if;

  return (
    select jsonb_build_object(
      'orders', count(*)::bigint,
      'collected', round(coalesce(sum(pay.paid_sum), 0)::numeric, 2),
      'outstanding', round(coalesce(sum(greatest(o.total - pay.paid_sum, 0)), 0)::numeric, 2),
      'as_of', to_jsonb(v_ref)
    )
    from public.pos_orders o
    cross join lateral (
      select coalesce(sum(p.amount), 0)::numeric(14, 2) as paid_sum
      from public.pos_order_payments p
      where p.order_id = o.id
        and p.status = 'paid'
    ) pay
    where o.status = 'partially_paid'
  );
end;
$$;


ALTER FUNCTION "public"."executive_partial_open_snapshot"("p_reference_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."executive_partial_open_snapshot"("p_reference_at" timestamp with time zone) IS 'Operational snapshot of partially_paid orders; aggregates only. Not sumable with settled.sales.';



CREATE OR REPLACE FUNCTION "public"."executive_period_bounds"("p_reference_at" timestamp with time zone, "p_grain" "text", "p_segment" "text") RETURNS TABLE("start_at" timestamp with time zone, "end_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_ref timestamptz := coalesce(p_reference_at, now());
  v_local timestamp := public.executive_gt_local_ts(v_ref);
  v_cur_start_local timestamp;
  v_cur_start timestamptz;
  v_prev_start_local timestamp;
  v_elapsed interval;
begin
  v_cur_start_local := public.executive_period_start_local(v_local, p_grain);
  v_cur_start := v_cur_start_local at time zone 'America/Guatemala';

  if p_segment = 'current' then
    start_at := v_cur_start;
    end_at := v_ref;
    return next;
    return;
  end if;

  if p_segment <> 'previous' then
    raise exception 'Unsupported executive period segment: %', p_segment;
  end if;

  v_elapsed := v_ref - v_cur_start;

  case p_grain
    when 'day' then
      v_prev_start_local := v_cur_start_local - interval '1 day';
    when 'week' then
      v_prev_start_local := v_cur_start_local - interval '7 days';
    when 'month' then
      v_prev_start_local := (date_trunc('month', v_cur_start_local - interval '1 day')::date + time '04:00:00');
    when 'year' then
      v_prev_start_local := make_date(extract(year from v_cur_start_local)::int - 1, 1, 1) + time '04:00:00';
    else
      raise exception 'Unsupported executive period grain: %', p_grain;
  end case;

  start_at := v_prev_start_local at time zone 'America/Guatemala';
  end_at := least(start_at + v_elapsed, v_cur_start);
  return next;
end;
$$;


ALTER FUNCTION "public"."executive_period_bounds"("p_reference_at" timestamp with time zone, "p_grain" "text", "p_segment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."executive_period_start_local"("p_local" timestamp without time zone, "p_grain" "text") RETURNS timestamp without time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_monday date;
  v_candidate timestamp;
begin
  case p_grain
    when 'day' then
      return public.executive_gt_local_ts(
        public.executive_operational_day_start((p_local at time zone 'America/Guatemala'))
      );
    when 'week' then
      v_monday := date_trunc('week', p_local)::date;
      v_candidate := v_monday + time '04:00:00';
      if p_local >= v_candidate then
        return v_candidate;
      end if;
      return v_candidate - interval '7 days';
    when 'month' then
      v_candidate := date_trunc('month', p_local)::date + time '04:00:00';
      if p_local >= v_candidate then
        return v_candidate;
      end if;
      return (date_trunc('month', p_local - interval '1 month')::date + time '04:00:00');
    when 'year' then
      v_candidate := make_date(extract(year from p_local)::int, 1, 1) + time '04:00:00';
      if p_local >= v_candidate then
        return v_candidate;
      end if;
      return make_date(extract(year from p_local)::int - 1, 1, 1) + time '04:00:00';
    else
      raise exception 'Unsupported executive period grain: %', p_grain;
  end case;
end;
$$;


ALTER FUNCTION "public"."executive_period_start_local"("p_local" timestamp without time zone, "p_grain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_station_device_enrollment"("p_device_id" "uuid", "p_enrollment_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
begin
  select * into v_device from public.operational_station_devices
  where id = p_device_id and enrollment_id = p_enrollment_id for update;
  if v_device.id is null then
    return;
  end if;
  update public.operational_station_devices
  set status = 'blocked', blocked_reason = coalesce(nullif(trim(p_reason), ''), 'enrollment_failed'),
      blocked_at = now(), updated_at = now()
  where id = p_device_id;
  update public.operational_station_enrollment_tokens
  set status = 'failed', updated_at = now()
  where id = p_enrollment_id and status <> 'completed';
  perform public.log_operational_station_event(
    v_device.station_id, v_device.id, 'device_enrollment_failed', null,
    jsonb_build_object('reason', nullif(trim(p_reason), '')), null
  );
end;
$$;


ALTER FUNCTION "public"."fail_station_device_enrollment"("p_device_id" "uuid", "p_enrollment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_station_device_enrollment"("p_device_id" "uuid", "p_enrollment_id" "uuid", "p_auth_user_id" "uuid", "p_claim_secret_hash" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_tok public.operational_station_enrollment_tokens;
  v_station public.operational_stations;
  v_active_count int;
begin
  if nullif(trim(p_idempotency_key), '') is null or p_auth_user_id is null then
    raise exception 'Solicitud invalida.';
  end if;
  v_device := public.verify_operational_device_claim_secret(
    p_device_id, p_enrollment_id, p_claim_secret_hash, true
  );
  select * into v_tok from public.operational_station_enrollment_tokens where id = p_enrollment_id for update;
  if v_tok.status = 'completed' then
    raise exception 'Solicitud invalida.';
  end if;
  if v_tok.status <> 'authorized' or v_tok.expires_at < now() then
    raise exception 'Solicitud invalida.';
  end if;
  if v_device.status <> 'pending' then
    raise exception 'Solicitud invalida.';
  end if;
  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.status not in ('active', 'draft') then
    raise exception 'Solicitud invalida.';
  end if;
  select count(*) into v_active_count from public.operational_station_devices
  where station_id = v_device.station_id and status = 'active';
  if v_active_count > 0 then
    raise exception 'Solicitud invalida.';
  end if;
  update public.operational_station_devices
  set status = 'active', auth_user_id = p_auth_user_id, activated_at = now(),
      claim_secret_consumed_at = now(), claim_secret_hash = null, updated_at = now()
  where id = p_device_id
  returning * into v_device;
  update public.operational_station_enrollment_tokens
  set status = 'completed', completed_device_id = v_device.id,
      complete_idempotency_key = trim(p_idempotency_key), updated_at = now()
  where id = v_tok.id;
  update public.operational_stations set status = 'active', updated_at = now()
  where id = v_device.station_id and status = 'draft';
  perform public.log_operational_station_event(
    v_device.station_id, v_device.id, 'device_enrollment_completed', null,
    '{}'::jsonb, trim(p_idempotency_key)
  );
  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."finalize_station_device_enrollment"("p_device_id" "uuid", "p_enrollment_id" "uuid", "p_auth_user_id" "uuid", "p_claim_secret_hash" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_apply_bank_transaction"("p_bank_account_id" "uuid", "p_amount" numeric, "p_direction" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'El monto debe ser mayor a cero.';
  end if;

  if p_direction = 'in' then
    update public.finance_bank_accounts
    set current_balance = current_balance + p_amount, updated_by = auth.uid()
    where id = p_bank_account_id;
  elsif p_direction = 'out' then
    update public.finance_bank_accounts
    set current_balance = current_balance - p_amount, updated_by = auth.uid()
    where id = p_bank_account_id;
  else
    raise exception 'Dirección inválida.';
  end if;
end;
$$;


ALTER FUNCTION "public"."finance_apply_bank_transaction"("p_bank_account_id" "uuid", "p_amount" numeric, "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_integration_status_label"("p_kind" "text", "p_status" "text", "p_linked" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when not p_linked then case p_kind
      when 'payable' then 'Sin cuenta por pagar'
      when 'receivable' then 'Sin cuenta por cobrar'
      else 'Sin depósito bancario'
    end
    when p_kind = 'payable' and p_status = 'partial' then 'Parcialmente pagada'
    when p_kind = 'payable' and p_status = 'paid' then 'Pagada'
    when p_kind = 'receivable' and p_status = 'partial' then 'Parcialmente cobrada'
    when p_kind = 'receivable' and p_status = 'collected' then 'Cobrada'
    when p_kind = 'deposit' then 'Ya enviado a Finanzas'
    when p_kind = 'payable' then 'Cuenta por pagar creada'
    when p_kind = 'receivable' then 'Cuenta por cobrar creada'
    else 'Vinculado'
  end;
$$;


ALTER FUNCTION "public"."finance_integration_status_label"("p_kind" "text", "p_status" "text", "p_linked" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_purchase_order_amounts"("p_data" "jsonb") RETURNS TABLE("subtotal" numeric, "tax_amount" numeric, "total_amount" numeric)
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with items as (
    select coalesce(sum(
      coalesce(
        nullif(item ->> 'subtotal', '')::numeric,
        coalesce(nullif(item ->> 'costoUnitario', '')::numeric, 0)
          * coalesce(
            nullif(item ->> 'cantidadComprar', '')::numeric,
            nullif(item ->> 'cantidad_compra', '')::numeric,
            0
          )
      )
    ), 0) as subtotal
    from jsonb_array_elements(coalesce(p_data -> 'items', '[]'::jsonb)) as item
  )
  select
    i.subtotal,
    coalesce(
      nullif(p_data ->> 'tax_amount', '')::numeric,
      nullif(p_data ->> 'iva', '')::numeric,
      round(i.subtotal * 0.12, 2)
    ) as tax_amount,
    coalesce(
      nullif(p_data ->> 'total', '')::numeric,
      nullif(p_data ->> 'totalOrden', '')::numeric,
      i.subtotal
        + coalesce(
          nullif(p_data ->> 'tax_amount', '')::numeric,
          nullif(p_data ->> 'iva', '')::numeric,
          round(i.subtotal * 0.12, 2)
        )
    ) as total_amount
  from items i;
$$;


ALTER FUNCTION "public"."finance_purchase_order_amounts"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_refresh_payable_status"("p_payable_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.finance_payables;
  v_status text;
begin
  select * into v_row from public.finance_payables where id = p_payable_id;
  if not found then return; end if;

  if v_row.status = 'cancelled' then return; end if;

  if v_row.balance <= 0 then
    v_status := 'paid';
  elsif v_row.paid_amount > 0 then
    v_status := 'partial';
  elsif v_row.due_date < (now() at time zone 'America/Guatemala')::date then
    v_status := 'overdue';
  else
    v_status := 'pending';
  end if;

  update public.finance_payables set status = v_status where id = p_payable_id;
end;
$$;


ALTER FUNCTION "public"."finance_refresh_payable_status"("p_payable_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_refresh_receivable_status"("p_receivable_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.finance_receivables;
  v_status text;
begin
  select * into v_row from public.finance_receivables where id = p_receivable_id;
  if not found then return; end if;

  if v_row.status = 'cancelled' then return; end if;

  if v_row.balance <= 0 then
    v_status := 'collected';
  elsif v_row.collected_amount > 0 then
    v_status := 'partial';
  elsif v_row.due_date is not null and v_row.due_date < (now() at time zone 'America/Guatemala')::date then
    v_status := 'overdue';
  else
    v_status := 'pending';
  end if;

  update public.finance_receivables set status = v_status where id = p_receivable_id;
end;
$$;


ALTER FUNCTION "public"."finance_refresh_receivable_status"("p_receivable_id" "uuid") OWNER TO "postgres";


