  order by i.active desc, i.updated_at desc
  limit 1;
$$;


ALTER FUNCTION "public"."find_inventory_item_by_barcode"("p_barcode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_pending_requisition_items_for_inventory_item"("p_item_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb := '[]'::jsonb;
begin
  if p_item_id is null then
    return result;
  end if;

  select coalesce(jsonb_agg(row_to_json(q)::jsonb order by q.created_at desc), '[]'::jsonb)
  into result
  from (
    select
      ri.id as requisition_item_id,
      ri.requisition_id,
      r.requisition_number,
      r.status as requisition_status,
      r.from_area_id,
      r.to_area_id,
      ri.item_id,
      ri.item_name,
      ri.requested_quantity,
      coalesce(ri.delivered_quantity, 0) as delivered_quantity,
      coalesce(ri.pending_quantity, 0) as pending_quantity,
      ri.fulfillment_status,
      ri.shortage_reason,
      r.created_at
    from public.requisition_items ri
    join public.requisitions r on r.id = ri.requisition_id
    where ri.item_id = p_item_id
      and coalesce(ri.pending_quantity, 0) > 0
      and r.status in ('partially_fulfilled', 'pending_fulfillment', 'approved')
      and coalesce(r.is_test, false) = false
    order by r.created_at desc
    limit greatest(coalesce(p_limit, 20), 1)
  ) q;

  return coalesce(result, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."find_pending_requisition_items_for_inventory_item"("p_item_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."force_delete_checklist_template"("p_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  template_row public.checklist_templates;
  deleted_runs integer := 0;
  deleted_incidents integer := 0;
begin
  if not public.is_checklist_template_deleter() then
    raise exception 'No tienes permiso para eliminar checklists definitivamente.';
  end if;

  select * into template_row
  from public.checklist_templates
  where id = p_template_id;

  if template_row.id is null then
    raise exception 'Checklist no encontrada.';
  end if;

  delete from public.notifications
  where entity_type = 'checklist_run'
    and entity_id in (
      select run.id::text
      from public.checklist_runs run
      where run.template_id = p_template_id
    );

  delete from public.notifications
  where entity_type = 'checklist_template_change_request'
    and entity_id in (
      select request.id::text
      from public.checklist_template_change_requests request
      where request.template_id = p_template_id
    );

  delete from public.checklist_management_alerts alert
  using public.checklist_runs run
  where alert.checklist_run_id = run.id
    and run.template_id = p_template_id;

  with removed_incidents as (
    delete from public.checklist_incidents incident
    where incident.template_id = p_template_id
       or incident.run_id in (
         select run.id
         from public.checklist_runs run
         where run.template_id = p_template_id
       )
    returning incident.id
  )
  select count(*) into deleted_incidents from removed_incidents;

  with removed_runs as (
    delete from public.checklist_runs run
    where run.template_id = p_template_id
    returning run.id
  )
  select count(*) into deleted_runs from removed_runs;

  delete from public.checklist_template_change_requests
  where template_id = p_template_id;

  delete from public.checklist_template_suggestions
  where template_id = p_template_id;

  delete from public.checklist_template_items
  where template_id = p_template_id;

  delete from public.checklist_templates
  where id = p_template_id;

  return jsonb_build_object(
    'template_id', p_template_id,
    'deleted_runs', deleted_runs,
    'deleted_incidents', deleted_incidents
  );
end;
$$;


ALTER FUNCTION "public"."force_delete_checklist_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_due_checklist_runs"("p_target_date" "date" DEFAULT "public"."get_checklist_operational_date"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  template_row public.checklist_templates;
  generated_count integer := 0;
begin
  if not public.can_access_checklists() then
    raise exception 'No tienes permiso para generar checklists recurrentes.';
  end if;

  for template_row in
    select * from public.checklist_templates
    where status = 'active'
      and public.checklist_template_should_auto_generate(checklist_templates)
      and public.checklist_template_due_on_date(checklist_templates, p_target_date)
  loop
    begin
      perform public.create_checklist_run_from_template(
        template_row.id,
        p_target_date,
        'recurrence',
        null,
        'Generada automaticamente',
        template_row.area,
        template_row.assigned_role
      );
      generated_count := generated_count + 1;
    exception when others then
      raise warning 'generate_due_checklist_runs template % failed: %', template_row.id, sqlerrm;
    end;
  end loop;

  return generated_count;
end;
$$;


ALTER FUNCTION "public"."generate_due_checklist_runs"("p_target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_due_operational_process_runs"("p_target_date" "date" DEFAULT "public"."get_checklist_operational_date"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_template public.operational_process_templates;
  v_generated integer := 0;
begin
  if not public.can_access_checklists() then
    raise exception 'No tienes permiso para generar procesos operativos programados.';
  end if;

  for v_template in
    select * from public.operational_process_templates
    where status = 'active'
      and public.operational_process_template_should_auto_generate(operational_process_templates)
      and public.operational_process_template_due_on_date(operational_process_templates, p_target_date)
  loop
    begin
      perform public.ensure_operational_process_run(
        v_template.id,
        p_target_date,
        v_template.area,
        'Generada automaticamente',
        'recurrence'
      );
      v_generated := v_generated + 1;
    exception when others then
      raise warning 'generate_due_operational_process_runs template % failed: %', v_template.id, sqlerrm;
    end;
  end loop;

  return v_generated;
end;
$$;


ALTER FUNCTION "public"."generate_due_operational_process_runs"("p_target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_internal_barcode"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  next_num bigint;
  candidate text;
  attempts int := 0;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para generar códigos internos.';
  end if;

  loop
    next_num := nextval('public.inventory_internal_barcode_seq');
    candidate := 'EGA-INV-' || lpad(next_num::text, 6, '0');

    exit when not exists (
      select 1
      from public.inventory_items
      where lower(trim(barcode)) = lower(candidate)
    );

    attempts := attempts + 1;
    if attempts >= 20 then
      raise exception 'No se pudo generar un código interno único.';
    end if;
  end loop;

  return jsonb_build_object(
    'barcode', candidate,
    'barcode_type', 'CODE128',
    'barcode_source', 'internal'
  );
end;
$$;


ALTER FUNCTION "public"."generate_internal_barcode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_monthly_fixed_cost_review_notifications"("p_month" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_month date := public.normalize_fixed_cost_month(coalesce(p_month, current_date));
  v_month_label text := to_char(v_month, 'TMMonth YYYY');
  v_roles text[] := array['admin', 'gerente_general'];
  v_role text;
  v_created integer := 0;
begin
  if not public.can_manage_fixed_costs() then
    raise exception 'No tienes permiso para generar notificaciones de costos fijos.';
  end if;

  foreach v_role in array v_roles loop
    if not exists (
      select 1
      from public.notifications n
      where n.type = 'fixed_costs_monthly_review'
        and n.target_role = v_role
        and n.entity_type = 'fixed_costs_month'
        and n.entity_id = to_char(v_month, 'YYYY-MM')
    ) then
      insert into public.notifications (
        target_role, type, title, message, entity_type, entity_id, action_url
      )
      values (
        v_role,
        'fixed_costs_monthly_review',
        'Revisar costos fijos del mes',
        'Confirma si hay cambios en renta, servicios, prestamos, software o costos administrativos para ' || v_month_label || '.',
        'fixed_costs_month',
        to_char(v_month, 'YYYY-MM'),
        '/reports?tab=fixedCosts'
      );
      v_created := v_created + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'month', v_month,
    'notifications_created', v_created
  );
end;
$$;


ALTER FUNCTION "public"."generate_monthly_fixed_cost_review_notifications"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_archived_operational_tasks"("p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := nullif(trim(lower(coalesce(p_search, ''))), '');
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if not public.can_manage_task_labels() then
    raise exception 'No tienes permiso para ver tareas archivadas.';
  end if;

  select coalesce(jsonb_agg(
    public.operational_task_card_summary(t)
    order by t.archived_at desc nulls last
  ), '[]'::jsonb)
  into v_rows
  from (
    select t.*
    from public.assigned_tasks t
    where t.task_source = 'operational'
      and t.deleted_at is null
      and t.archived_at is not null
      and public.can_access_operational_task(t, 'view')
      and (
        v_search is null
        or lower(t.title) like '%' || v_search || '%'
        or lower(coalesce(t.objective, '')) like '%' || v_search || '%'
      )
    order by t.archived_at desc
    limit v_limit
  ) t;

  return jsonb_build_object('tasks', v_rows);
end;
$$;


ALTER FUNCTION "public"."get_archived_operational_tasks"("p_search" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_daily_late_arrivals"("p_date" "date", "p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "shift_date" "date", "area" "text", "scheduled_start" time without time zone, "check_in_at" timestamp with time zone, "check_in_local" time without time zone, "late_minutes" integer, "grace_minutes" integer, "is_late" boolean, "schedule_status" "text", "has_checkout" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_view_attendance_reports() then
    raise exception 'PERMISSION_DENIED: se requiere rol admin, gerente_general o recursos_humanos (auth.uid=%).', auth.uid();
  end if;

  return query
  with schedule_rows as (
    select distinct on (s.employee_id, s.shift_date, s.block_order)
      s.id,
      s.employee_id,
      s.shift_date,
      s.area,
      s.start_time,
      s.end_time,
      s.is_work_day,
      s.shift_type,
      s.status,
      coalesce(p.full_name, p.username, 'Colaborador') as employee_name
    from public.employee_schedules s
    join public.profiles p on p.id = s.employee_id
    left join public.shift_types st on st.id = s.shift_type_id
    where s.shift_date = p_date
      and s.status in ('published', 'draft')
      and s.is_work_day
      and s.start_time is not null
      and (p_employee_id is null or s.employee_id = p_employee_id)
      and coalesce(st.is_rest_day, false) = false
      and coalesce(st.is_holiday, false) = false
      and coalesce(s.shift_type, '') not in ('rest', 'asueto')
    order by s.employee_id, s.shift_date, s.block_order, case s.status when 'published' then 0 else 1 end
  ),
  with_marks as (
    select
      s.*,
      entrance.marked_at as check_in_at,
      exit_mark.marked_at as check_out_at,
      public.get_attendance_late_grace_minutes() as grace_minutes,
      greatest(0, coalesce(extract(epoch from (
        entrance.marked_at at time zone 'America/Guatemala' - (s.shift_date + s.start_time)
      )) / 60, 0))::integer as raw_late_minutes
    from schedule_rows s
    left join lateral (
      select m.marked_at
      from public.attendance_marks m
      where m.employee_id = s.employee_id
        and m.mark_type = 'entrada'
        and (m.marked_at at time zone 'America/Guatemala')::date = s.shift_date
      order by m.marked_at asc
      limit 1
    ) entrance on true
    left join lateral (
      select m.marked_at
      from public.attendance_marks m
      where m.employee_id = s.employee_id
        and m.mark_type in ('salida_final', 'salida')
        and (m.marked_at at time zone 'America/Guatemala')::date = s.shift_date
        and (entrance.marked_at is null or m.marked_at > entrance.marked_at)
      order by m.marked_at desc
      limit 1
    ) exit_mark on true
  )
  select
    w.employee_id,
    w.employee_name,
    w.shift_date,
    w.area,
    w.start_time,
    w.check_in_at,
    (w.check_in_at at time zone 'America/Guatemala')::time as check_in_local,
    case when w.raw_late_minutes > w.grace_minutes then w.raw_late_minutes else 0 end as late_minutes,
    w.grace_minutes,
    (w.check_in_at is not null and w.raw_late_minutes > w.grace_minutes) as is_late,
    w.status as schedule_status,
    (w.check_out_at is not null) as has_checkout
  from with_marks w
  where w.check_in_at is not null
    and w.raw_late_minutes > w.grace_minutes
  order by w.employee_name, w.start_time;
end;
$$;


ALTER FUNCTION "public"."get_attendance_daily_late_arrivals"("p_date" "date", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_devices"() RETURNS SETOF "public"."attendance_devices"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_view_attendance_security() then
    raise exception 'No tienes permiso para ver dispositivos de marcaje.';
  end if;

  return query
  select *
  from public.attendance_devices
  order by last_seen_at desc nulls last, created_at desc;
end;
$$;


