CREATE OR REPLACE FUNCTION "public"."get_attendance_security_settings_value"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select value
      from public.attendance_security_settings
      where key = 'attendance_security'
      limit 1
    ),
    jsonb_build_object(
      'require_authorized_device', true,
      'require_authorized_network', false,
      'allowed_ips', '[]'::jsonb,
      'allow_hr_manual_override', false
    )
  );
