ALTER FUNCTION "public"."get_attendance_security_settings_value"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_security_status"("p_device_id" "text", "p_client_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  settings jsonb := public.get_attendance_security_settings_value();
  require_device boolean := coalesce((settings->>'require_authorized_device')::boolean, false);
  require_network boolean := coalesce((settings->>'require_authorized_network')::boolean, false);
  device_row public.attendance_devices;
  normalized_id text := nullif(trim(p_device_id), '');
  network_allowed boolean;
  can_mark boolean := true;
  message text := 'Dispositivo autorizado para marcaje.';
  device_status text := 'unknown';
begin
  if normalized_id is not null then
    select * into device_row
    from public.attendance_devices
    where device_id = normalized_id;
  end if;

  device_status := coalesce(device_row.status, 'unknown');
  network_allowed := public.is_attendance_network_allowed(p_client_ip, settings);

  if not require_device then
    can_mark := true;
    message := 'Marcaje permitido sin restriccion de dispositivo.';
  elsif normalized_id is null then
    can_mark := false;
    message := 'Este dispositivo no esta registrado para marcaje.';
  elsif device_row.id is null then
    can_mark := false;
    message := 'Este dispositivo aun no esta autorizado para registrar asistencia.';
    device_status := 'pending';
  elsif device_row.status = 'blocked' then
    can_mark := false;
    message := 'Este dispositivo esta bloqueado para marcaje.';
  elsif device_row.status <> 'authorized' then
    can_mark := false;
    message := 'Este dispositivo aun no esta autorizado para registrar asistencia.';
  end if;

  if can_mark and require_network and not network_allowed then
    can_mark := false;
    message := 'Esta red no esta autorizada para marcaje de asistencia.';
    perform public.log_attendance_security_event(
      normalized_id,
      null,
      'unauthorized_network_attempt',
      p_client_ip,
      p_user_agent,
      jsonb_build_object('allowed_ips', settings->'allowed_ips')
    );
  end if;

  return jsonb_build_object(
    'device_status', device_status,
    'require_authorized_device', require_device,
    'require_authorized_network', require_network,
    'network_allowed', network_allowed,
    'can_mark', can_mark,
    'message', message,
    'device_name', coalesce(device_row.device_name, null),
    'device_id', normalized_id
  );
end;
$$;


ALTER FUNCTION "public"."get_attendance_security_status"("p_device_id" "text", "p_client_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_terminal_marks"() RETURNS TABLE("id" "uuid", "employee_id" "uuid", "employee_name" "text", "mark_type" "text", "marked_at" timestamp with time zone, "device_name" "text", "device_alert" boolean, "related_mark_id" "uuid", "duration_minutes" integer, "labor_date" "date", "classification" "text", "approval_status" "text", "system_reason" "text", "schedule_exception_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with open_overnight as (
    select distinct e.employee_id
    from public.attendance_marks e
    where e.mark_type = 'entrada'
      and not exists (
        select 1
        from public.attendance_marks out_mark
        where out_mark.employee_id = e.employee_id
          and out_mark.mark_type in ('salida_final', 'salida')
          and out_mark.marked_at > e.marked_at
      )
      and (e.marked_at at time zone 'America/Guatemala')::date
        < (now() at time zone 'America/Guatemala')::date
  ),
  window_start as (
    select case
      when exists (select 1 from open_overnight) then
        date_trunc(
          'day',
          (now() at time zone 'America/Guatemala')::date - 1
        ) at time zone 'America/Guatemala'
      else
        date_trunc('day', now() at time zone 'America/Guatemala') at time zone 'America/Guatemala'
    end as ts
  )
  select
    m.id,
    m.employee_id,
    m.employee_name,
    m.mark_type,
    m.marked_at,
    m.device_name,
    m.device_alert,
    m.related_mark_id,
    m.duration_minutes,
    m.labor_date,
    m.classification,
    m.approval_status,
    m.system_reason,
    m.schedule_exception_id
  from public.attendance_marks m
  cross join window_start w
  where m.marked_at >= date_trunc('day', now() at time zone 'America/Guatemala') at time zone 'America/Guatemala'
     or (
       m.employee_id in (select employee_id from open_overnight)
       and m.marked_at >= w.ts
     )
  order by m.marked_at desc;
$$;


ALTER FUNCTION "public"."get_attendance_terminal_marks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_attendance_terminal_profiles"() RETURNS TABLE("id" "uuid", "employee_code" "text", "full_name" "text", "avatar_url" "text", "area_name" "text", "pin_configured" boolean, "area_id" "text", "role" "text", "position" "text", "department" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    p.id,
    p.employee_id,
    p.full_name,
    p.avatar_url,
    p.area_name,
    c.employee_id is not null,
    p.area_id,
    p.role,
    null::text as "position",
    p.area_name as department
  from public.profiles p
  left join public.attendance_credentials c on c.employee_id = p.id
  where p.status = 'active'
  order by p.full_name nulls last, p.username;
$$;


ALTER FUNCTION "public"."get_attendance_terminal_profiles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bakery_supervisor_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_today date := (now() at time zone 'America/Guatemala')::date;
  v_week_start date := v_today - extract(dow from v_today)::integer;
begin
  if not public.can_access_bakery_module() then
    raise exception 'PERMISSION_DENIED';
  end if;

  return jsonb_build_object(
    'today_plan', (
      select coalesce(jsonb_agg(to_jsonb(p) order by p.priority desc, p.required_date), '[]'::jsonb)
      from public.bakery_production_plan_items p
      where p.required_date = v_today
        and p.status in ('planned', 'in_progress', 'partial')
    ),
    'overdue_plan', (
      select coalesce(jsonb_agg(to_jsonb(p) order by p.required_date), '[]'::jsonb)
      from public.bakery_production_plan_items p
      where p.required_date < v_today
        and p.status in ('planned', 'in_progress', 'partial')
    ),
    'batches_in_progress', (
      select coalesce(jsonb_agg(to_jsonb(b) order by b.started_at desc nulls last), '[]'::jsonb)
      from public.bakery_production_batches b
      where b.status in ('created', 'in_progress')
    ),
    'batches_pending_delivery', (
      select coalesce(jsonb_agg(to_jsonb(b) order by b.started_at desc nulls last), '[]'::jsonb)
      from public.bakery_production_batches b
      where b.status = 'in_progress'
        and exists (
          select 1 from public.bakery_production_diary_entries d
          where d.batch_id = b.id and d.actual_quantity is not null
        )
    ),
    'cold_room_dough', (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'id', d.id,
          'batch_code', d.batch_code,
          'dough_type', d.dough_type,
          'status', d.status,
          'cold_room_started_at', d.cold_room_started_at,
          'hours_in_cold', round(extract(epoch from (now() - d.cold_room_started_at)) / 3600.0, 1),
          'quantity_units', d.quantity_units
        ) order by d.cold_room_started_at
      ), '[]'::jsonb)
      from public.bakery_dough_batches d
      where d.status in ('cold_room', 'ready')
    ),
    'recent_waste', (
      select coalesce(jsonb_agg(to_jsonb(w) order by w.created_at desc), '[]'::jsonb)
      from (
        select * from public.bakery_waste_records
        order by created_at desc
        limit 10
      ) w
    ),
    'weekly_delivered', (
      select coalesce(sum(b.actual_quantity), 0)
      from public.bakery_production_batches b
      where b.status in ('delivered', 'partial')
        and b.delivered_at >= v_week_start::timestamptz
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_bakery_supervisor_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_billing_monitoring_summary"("p_legal_entity_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entity_id uuid;
  v_result jsonb;
begin
  if not public.can_view_billing_settings() then
    raise exception 'No tienes permiso para consultar monitoreo de facturacion.';
  end if;

  v_entity_id := coalesce(p_legal_entity_id, public.get_default_billing_legal_entity_id());

  select jsonb_build_object(
    'legal_entity_id', v_entity_id,
    'settings', public.get_billing_settings(),
    'document_counts', coalesce((
      select jsonb_agg(to_jsonb(c))
      from public.billing_monitoring_document_counts c
      where c.legal_entity_id = v_entity_id
    ), '[]'::jsonb),
    'providers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'provider_config_id', st.provider_config_id,
        'provider_code', st.provider_code,
        'adapter_version', st.adapter_version,
        'connection_status', st.connection_status,
        'last_test_at', st.last_test_at,
        'last_test_success', st.last_test_success,
        'last_test_duration_ms', st.last_test_duration_ms,
        'last_test_error_summary', st.last_test_error_summary,
        'last_test_error_codes', st.last_test_error_codes,
        'last_known_credits', st.last_known_credits,
        'last_successful_connection_at', st.last_successful_connection_at,
        'last_error_at', st.last_error_at,
        'last_error_summary', st.last_error_summary,
        'updated_at', st.updated_at,
        'environment', cfg.environment,
        'entity_id', cfg.entity_id
      ) order by st.provider_code)
      from public.billing_provider_status st
      join public.billing_provider_configs cfg on cfg.id = st.provider_config_id
      where st.legal_entity_id = v_entity_id
    ), '[]'::jsonb),
    'recent_attempts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id,
        'provider_code', a.provider_code,
        'adapter_version', a.adapter_version,
        'operation', a.operation,
        'status', a.status,
        'duration_ms', a.duration_ms,
        'error_codes', a.error_codes,
        'created_at', a.created_at
      ) order by a.created_at desc)
      from (
        select *
        from public.billing_certification_attempts
        where legal_entity_id = v_entity_id
        order by created_at desc
        limit 10
      ) a
    ), '[]'::jsonb),
    'last_error_by_provider', coalesce((
      select jsonb_object_agg(distinct_on.provider_code, dist_on.payload)
      from (
        select distinct on (a.provider_code)
          a.provider_code,
          jsonb_build_object(
            'error_codes', a.error_codes,
            'error_messages', a.error_messages,
            'created_at', a.created_at,
            'operation', a.operation
          ) as payload
        from public.billing_certification_attempts a
        where a.legal_entity_id = v_entity_id
          and a.status = 'failed'
        order by a.provider_code, a.created_at desc
      ) dist_on
    ), '{}'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_billing_monitoring_summary"("p_legal_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_billing_provider_config_for_service"("p_provider_code" "text", "p_environment" "text", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entity_id uuid;
  v_row record;
begin
  v_entity_id := coalesce(p_legal_entity_id, public.get_default_billing_legal_entity_id());

  select
    cfg.id,
    cfg.legal_entity_id,
    cfg.provider_code,
    cfg.environment,
    cfg.entity_id,
    cfg.secret_env_var,
    cfg.base_url,
    coalesce(cfg.adapter_version, prov.adapter_version) as adapter_version,
    prov.adapter_key,
    prov.name as provider_name
  into v_row
  from public.billing_provider_configs cfg
  join public.billing_providers prov on prov.code = cfg.provider_code
  where cfg.legal_entity_id = v_entity_id
    and cfg.provider_code = p_provider_code
    and cfg.environment = p_environment
    and cfg.is_active = true
  order by cfg.is_default desc, cfg.updated_at desc
  limit 1;

  if v_row.id is null then
    return null;
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'legal_entity_id', v_row.legal_entity_id,
    'provider_code', v_row.provider_code,
    'environment', v_row.environment,
    'entity_id', v_row.entity_id,
    'secret_env_var', v_row.secret_env_var,
    'base_url', v_row.base_url,
    'adapter_version', v_row.adapter_version,
    'adapter_key', v_row.adapter_key,
    'provider_name', v_row.provider_name
  );
end;
$$;


ALTER FUNCTION "public"."get_billing_provider_config_for_service"("p_provider_code" "text", "p_environment" "text", "p_legal_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_billing_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_value jsonb;
begin
  if not public.can_view_billing_settings() then
    raise exception 'No tienes permiso para consultar configuracion de facturacion.';
  end if;

  select value into v_value
  from public.app_settings
  where key = 'billing_settings';

  return public.billing_settings_default()
    || coalesce(v_value, '{}'::jsonb);
end;
$$;


