    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_id" "uuid" NOT NULL,
    "activity_type" "text" NOT NULL,
    "description" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "catering_activity_log_activity_type_check" CHECK (("activity_type" = ANY (ARRAY['lead_received'::"text", 'lead_assigned'::"text", 'status_changed'::"text", 'followup_recorded'::"text", 'contact_made'::"text", 'quote_created'::"text", 'quote_sent'::"text", 'quote_approved'::"text", 'quote_rejected'::"text", 'quote_expired'::"text", 'lead_created_manual'::"text", 'lead_updated'::"text"])))
);


