CREATE OR REPLACE FUNCTION "public"."get_catering_assignee_ranking"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from date := coalesce(p_date_from, date_trunc('month', current_date)::date);
  v_to date := coalesce(p_date_to, current_date);
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar ranking de catering.';
  end if;

  select coalesce(jsonb_agg(row_data order by active_leads desc, closed_leads desc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'assignee_id', profile.id,
      'assignee_name', coalesce(nullif(trim(profile.full_name), ''), profile.username, 'Sin nombre'),
      'role', profile.role,
      'active_leads', count(*) filter (
        where request.conversion_status in ('lead', 'contacted', 'quoted', 'negotiating')
      ),
      'closed_leads', count(*) filter (
        where request.conversion_status in ('approved', 'lost', 'converted')
      ),
      'approved_leads', count(*) filter (where request.conversion_status = 'approved'),
      'conversion_rate', case
        when count(*) filter (where request.conversion_status in ('approved', 'lost', 'converted')) > 0 then
          round(
            (
              count(*) filter (where request.conversion_status = 'approved')::numeric
              / count(*) filter (where request.conversion_status in ('approved', 'lost', 'converted'))::numeric
            ) * 100,
            1
          )
        else 0
      end
    ) as row_data,
    count(*) filter (
      where request.conversion_status in ('lead', 'contacted', 'quoted', 'negotiating')
    ) as active_leads,
    count(*) filter (
      where request.conversion_status in ('approved', 'lost', 'converted')
    ) as closed_leads
    from public.profiles profile
    left join public.catering_requests request
      on request.assigned_to = profile.id
      and request.created_at::date between v_from and v_to
    where profile.status = 'active'
      and public.normalize_profile_role(profile.role) in (
        'admin',
        'gerente_general',
        'gerente',
        'gerente_operaciones',
        'supervisor',
        'ventas'
      )
    group by profile.id, profile.full_name, profile.username, profile.role
    having count(request.id) > 0
  ) ranked;

  return jsonb_build_object(
    'date_from', v_from,
    'date_to', v_to,
    'rows', v_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_catering_assignee_ranking"("p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_leads_by_source"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from date := coalesce(p_date_from, date_trunc('month', current_date)::date);
  v_to date := coalesce(p_date_to, current_date);
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar el pipeline de catering.';
  end if;

  if v_to < v_from then
    raise exception 'p_date_to no puede ser menor que p_date_from.';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'lead_source', src.lead_source,
          'lead_count', coalesce(stats.lead_count, 0),
          'potential_value', coalesce(stats.potential_value, 0),
          'approved_count', coalesce(stats.approved_count, 0),
          'approved_value', coalesce(stats.approved_value, 0)
        )
        order by src.lead_source
      )
      from (
        select unnest(public.catering_lead_source_values()) as lead_source
      ) src
      left join (
        select
          request.lead_source,
          count(*) as lead_count,
          coalesce(sum(
            coalesce(request.estimated_value, 0)
            * public.catering_effective_win_probability(request.win_probability, request.conversion_status)::numeric
            / 100
          ) filter (
            where request.conversion_status in ('lead', 'contacted', 'quoted', 'negotiating')
          ), 0) as potential_value,
          count(*) filter (where request.conversion_status = 'approved') as approved_count,
          coalesce(sum(request.estimated_value) filter (
            where request.conversion_status = 'approved'
          ), 0) as approved_value
        from public.catering_requests request
        where request.created_at::date between v_from and v_to
        group by request.lead_source
      ) stats on stats.lead_source = src.lead_source
    ),
    '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."get_catering_leads_by_source"("p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_pending_followups"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar seguimientos de catering.';
  end if;

  select coalesce(jsonb_agg(row_data order by sort_key asc, follow_up_date asc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', request.id,
      'customer_name', request.customer_name,
      'follow_up_date', request.follow_up_date,
      'conversion_status', request.conversion_status,
      'assigned_to', request.assigned_to,
      'urgency', case
        when request.follow_up_date < current_date then 'overdue'
        when request.follow_up_date = current_date then 'today'
        else 'upcoming'
      end
    ) as row_data,
    case
      when request.follow_up_date < current_date then 0
      when request.follow_up_date = current_date then 1
      else 2
    end as sort_key,
    request.follow_up_date
    from public.catering_requests request
    where request.follow_up_date is not null
      and request.follow_up_date <= current_date
      and request.conversion_status not in ('approved', 'lost', 'converted')
  ) pending;

  return jsonb_build_object('rows', v_rows);
end;
$$;


ALTER FUNCTION "public"."get_catering_pending_followups"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_pipeline_summary"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from date := coalesce(p_date_from, date_trunc('month', current_date)::date);
  v_to date := coalesce(p_date_to, current_date);
  v_total_leads bigint := 0;
  v_new_leads bigint := 0;
  v_new_leads_today bigint := 0;
  v_uncontacted_leads bigint := 0;
  v_contacted_leads bigint := 0;
  v_quoted_leads bigint := 0;
  v_negotiating_leads bigint := 0;
  v_approved_leads bigint := 0;
  v_lost_leads bigint := 0;
  v_converted_leads bigint := 0;
  v_gross_pipeline_value numeric(12, 2) := 0;
  v_weighted_pipeline_value numeric(12, 2) := 0;
  v_approved_total_value numeric(12, 2) := 0;
  v_conversion_rate numeric(10, 2) := 0;
  v_avg_response_time_minutes numeric(10, 2) := 0;
  v_quotes_created bigint := 0;
  v_quotes_sent bigint := 0;
  v_quotes_approved bigint := 0;
  v_quoted_amount numeric(12, 2) := 0;
  v_approved_quote_amount numeric(12, 2) := 0;
begin
  if auth.uid() is null then
    raise exception 'Debes iniciar sesion para consultar el pipeline de catering.';
  end if;

  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar el pipeline de catering.';
  end if;

  if v_to < v_from then
    raise exception 'p_date_to no puede ser menor que p_date_from.';
  end if;

  perform public.sync_catering_quote_expired();

  select
    count(*),
    count(*) filter (where conversion_status = 'lead'),
    count(*) filter (where created_at::date = current_date),
    count(*) filter (where conversion_status = 'lead' and last_contact_at is null),
    count(*) filter (where conversion_status = 'contacted'),
    count(*) filter (where conversion_status = 'quoted'),
    count(*) filter (where conversion_status = 'negotiating'),
    count(*) filter (where conversion_status = 'approved'),
    count(*) filter (where conversion_status = 'lost'),
    count(*) filter (where conversion_status = 'converted'),
    coalesce(sum(estimated_value) filter (
      where conversion_status in ('lead', 'contacted', 'quoted', 'negotiating')
    ), 0),
    coalesce(sum(
      coalesce(estimated_value, 0)
      * public.catering_effective_win_probability(win_probability, conversion_status)::numeric
      / 100
    ) filter (
      where conversion_status in ('lead', 'contacted', 'quoted', 'negotiating')
    ), 0),
    coalesce(sum(estimated_value) filter (where conversion_status = 'approved'), 0),
    coalesce(avg(extract(epoch from (last_contact_at - created_at)) / 60.0) filter (
      where last_contact_at is not null
    ), 0)
  into
    v_total_leads,
    v_new_leads,
    v_new_leads_today,
    v_uncontacted_leads,
    v_contacted_leads,
    v_quoted_leads,
    v_negotiating_leads,
    v_approved_leads,
    v_lost_leads,
    v_converted_leads,
    v_gross_pipeline_value,
    v_weighted_pipeline_value,
    v_approved_total_value,
    v_avg_response_time_minutes
  from public.catering_requests
  where created_at::date between v_from and v_to;

  select
    count(*),
    count(*) filter (where status in ('sent', 'approved', 'rejected', 'expired')),
    count(*) filter (where status = 'approved'),
    coalesce(sum(total) filter (where status in ('sent', 'approved', 'rejected', 'expired')), 0),
    coalesce(sum(total) filter (where status = 'approved'), 0)
  into
    v_quotes_created,
    v_quotes_sent,
    v_quotes_approved,
    v_quoted_amount,
    v_approved_quote_amount
  from public.catering_quotes
  where created_at::date between v_from and v_to;

  if v_total_leads > 0 then
    v_conversion_rate := round((v_approved_leads::numeric / v_total_leads::numeric) * 100, 2);
  end if;

  return jsonb_build_object(
    'date_from', v_from,
    'date_to', v_to,
    'total_leads', v_total_leads,
    'new_leads', v_new_leads,
    'new_leads_today', v_new_leads_today,
    'uncontacted_leads', v_uncontacted_leads,
    'contacted_leads', v_contacted_leads,
    'quoted_leads', v_quoted_leads,
    'negotiating_leads', v_negotiating_leads,
    'approved_leads', v_approved_leads,
    'lost_leads', v_lost_leads,
    'converted_leads', v_converted_leads,
    'total_potential_value', v_gross_pipeline_value,
    'gross_pipeline_value', v_gross_pipeline_value,
    'weighted_pipeline_value', round(v_weighted_pipeline_value, 2),
    'approved_total_value', v_approved_total_value,
    'conversion_rate', v_conversion_rate,
    'avg_response_time_minutes', round(coalesce(v_avg_response_time_minutes, 0), 1),
    'quotes_created', v_quotes_created,
    'quotes_sent', v_quotes_sent,
    'quotes_approved', v_quotes_approved,
    'quoted_amount', round(v_quoted_amount, 2),
    'approved_quote_amount', round(v_approved_quote_amount, 2)
  );
end;
$$;


ALTER FUNCTION "public"."get_catering_pipeline_summary"("p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_quote_detail"("p_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_quote public.catering_quotes;
  v_items jsonb := '[]'::jsonb;
  v_request public.catering_requests;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar cotizaciones de catering.';
  end if;

  if p_quote_id is null then
    raise exception 'p_quote_id es obligatorio.';
  end if;

  select * into v_quote from public.catering_quotes where id = p_quote_id;
  if not found then
    raise exception 'Cotizacion no encontrada.';
  end if;

  select * into v_request from public.catering_requests where id = v_quote.request_id;

  select coalesce(jsonb_agg(to_jsonb(item) order by item.sort_order asc, item.id asc), '[]'::jsonb)
  into v_items
  from public.catering_quote_items item
  where item.quote_id = p_quote_id;

  return jsonb_build_object(
    'quote', to_jsonb(v_quote),
    'items', v_items,
    'request', to_jsonb(v_request)
  );
end;
$$;


ALTER FUNCTION "public"."get_catering_quote_detail"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_quote_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_value jsonb;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar configuracion de cotizaciones.';
  end if;

  select setting.value into v_value
  from public.app_settings setting
  where setting.key = 'catering_quote_settings';

  return public.catering_default_quote_settings() || coalesce(v_value, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_catering_quote_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_request_detail"("p_request_id" "uuid") RETURNS "public"."catering_requests"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.catering_requests;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar solicitudes de catering.';
  end if;

  if p_request_id is null then
    raise exception 'p_request_id es obligatorio.';
  end if;

  select request.*
  into v_row
  from public.catering_requests request
  where request.id = p_request_id;

  if not found then
    raise exception 'Solicitud de catering no encontrada.';
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."get_catering_request_detail"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_request_quotes"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_quotes jsonb := '[]'::jsonb;
  v_latest jsonb := null;
  v_count integer := 0;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar cotizaciones de catering.';
  end if;

  if p_request_id is null then
    raise exception 'p_request_id es obligatorio.';
  end if;

  perform public.sync_catering_quote_expired();

  select
    count(*),
    coalesce(
      (
        select to_jsonb(latest)
        from public.catering_quotes latest
        where latest.request_id = p_request_id
        order by latest.created_at desc
        limit 1
      ),
      null
    )
  into v_count, v_latest
  from public.catering_quotes quote
  where quote.request_id = p_request_id;

  select coalesce(jsonb_agg(row_data order by created_at desc), '[]'::jsonb)
  into v_quotes
  from (
    select jsonb_build_object(
      'id', quote.id,
      'quote_number', quote.quote_number,
      'status', quote.status,
      'status_label', public.catering_quote_status_label(quote.status),
      'subtotal', quote.subtotal,
      'discount_amount', quote.discount_amount,
      'tax_amount', quote.tax_amount,
      'total', quote.total,
      'valid_until', quote.valid_until,
      'notes', quote.notes,
      'created_at', quote.created_at,
      'updated_at', quote.updated_at
    ) as row_data,
    quote.created_at
    from public.catering_quotes quote
    where quote.request_id = p_request_id
  ) rows;

  return jsonb_build_object(
    'count', v_count,
    'latest', v_latest,
    'quotes', v_quotes
  );
end;
$$;


ALTER FUNCTION "public"."get_catering_request_quotes"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catering_requests"("p_status" "text" DEFAULT NULL::"text", "p_conversion_status" "text" DEFAULT NULL::"text", "p_assigned_to" "uuid" DEFAULT NULL::"uuid", "p_lead_source" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS SETOF "public"."catering_requests"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text := nullif(trim(coalesce(p_status, '')), '');
  v_conversion_status text := nullif(trim(coalesce(p_conversion_status, '')), '');
  v_lead_source text := nullif(trim(coalesce(p_lead_source, '')), '');
  v_limit integer := greatest(coalesce(p_limit, 100), 1);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar solicitudes de catering.';
  end if;

  return query
  select request.*
  from public.catering_requests request
  where (v_status is null or request.status = v_status)
    and (v_conversion_status is null or request.conversion_status = v_conversion_status)
    and (p_assigned_to is null or request.assigned_to = p_assigned_to)
    and (v_lead_source is null or request.lead_source = v_lead_source)
  order by request.created_at desc
  limit v_limit
  offset v_offset;
end;
$$;


ALTER FUNCTION "public"."get_catering_requests"("p_status" "text", "p_conversion_status" "text", "p_assigned_to" "uuid", "p_lead_source" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_checklist_coverage_for_runs"("p_run_ids" "uuid"[], "p_reference_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("run_id" "uuid", "coverage" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
