CREATE OR REPLACE FUNCTION "public"."get_checklist_templates_library"() RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "area" "text", "assigned_role" "text", "assigned_profile_id" "uuid", "supervisor_profile_id" "uuid", "backup_profile_id" "uuid", "primary_replacement_profile_id" "uuid", "secondary_replacement_profile_id" "uuid", "coverage_escalation_profile_id" "uuid", "auto_coverage_enabled" boolean, "auto_coverage_wait_minutes" integer, "frequency" "text", "shift_context" "text", "status" "text", "reminder_time" time without time zone, "due_time" time without time zone, "recurrence_days" integer[], "recurrence_month_day" integer, "recurrence_rule" "text", "skip_non_work_days" boolean, "auto_generate" boolean, "requires_approval" boolean, "created_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "creator_name" "text", "checklist_template_items" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    t.id,
    t.title,
    t.description,
    t.area,
    t.assigned_role,
    t.assigned_profile_id,
    t.supervisor_profile_id,
    t.backup_profile_id,
    t.primary_replacement_profile_id,
    t.secondary_replacement_profile_id,
    t.coverage_escalation_profile_id,
    t.auto_coverage_enabled,
    t.auto_coverage_wait_minutes,
    t.frequency,
    t.shift_context,
    t.status,
    t.reminder_time,
    t.due_time,
    t.recurrence_days,
    t.recurrence_month_day,
    t.recurrence_rule,
    t.skip_non_work_days,
    t.auto_generate,
    t.requires_approval,
    t.created_by,
    t.created_at,
    t.updated_at,
    coalesce(p.full_name, p.username, 'Colaborador') as creator_name,
    coalesce(
      (
        select jsonb_agg(to_jsonb(item) order by item.item_order)
        from public.checklist_template_items item
        where item.template_id = t.id
          and item.is_active is distinct from false
      ),
      '[]'::jsonb
    ) as checklist_template_items
  from public.checklist_templates t
  left join public.profiles p on p.id = t.created_by
  where public.can_read_checklist_template(t)
  order by t.created_at desc;
$$;


