CREATE OR REPLACE FUNCTION "public"."get_device_enrollment_status"("p_device_id" "uuid", "p_enrollment_id" "uuid", "p_claim_secret_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_tok public.operational_station_enrollment_tokens;
  v_public_status text;
begin
  begin
    v_device := public.verify_operational_device_claim_secret(
      p_device_id, p_enrollment_id, p_claim_secret_hash, true
    );
  exception
    when others then
      return jsonb_build_object('status', 'invalid');
  end;
  select * into v_tok from public.operational_station_enrollment_tokens where id = p_enrollment_id;
  if v_tok.expires_at < now() and v_tok.status not in ('completed', 'failed') then
    return jsonb_build_object('status', 'expired');
  end if;
  v_public_status := case v_tok.status
    when 'claimed' then 'waiting_authorization'
    when 'authorized' then 'authorized'
    when 'blocked' then 'blocked'
    when 'expired' then 'expired'
    when 'completed' then 'completed'
    when 'failed' then 'failed'
    else 'invalid'
  end;
  if v_device.status = 'blocked' then
    v_public_status := 'blocked';
  end if;
  return jsonb_build_object('status', v_public_status);
end;
$$;


ALTER FUNCTION "public"."get_device_enrollment_status"("p_device_id" "uuid", "p_enrollment_id" "uuid", "p_claim_secret_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_discipline_detail"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_read_employee_expedientes() then
    raise exception 'No tienes permiso para consultar disciplina.';
  end if;

  if not exists (select 1 from public.profiles where id = p_profile_id) then
    raise exception 'Colaborador no encontrado.';
  end if;

  return jsonb_build_object(
    'kpis', public.employee_discipline_profile_kpis(p_profile_id),
    'incidents', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'incident', to_jsonb(i),
          'reported_by_name', rp.full_name,
          'closed_by_name', cp.full_name,
          'parent_title', pp.title,
          'evidence', coalesce((
            select jsonb_agg(to_jsonb(e) order by e.created_at desc)
            from public.employee_incident_evidence e
            where e.incident_id = i.id
          ), '[]'::jsonb),
          'actions', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'action', to_jsonb(a),
                'issued_by_name', ip.full_name
              ) order by a.effective_date desc, a.created_at desc
            )
            from public.employee_disciplinary_actions a
            left join public.profiles ip on ip.id = a.issued_by
            where a.incident_id = i.id
          ), '[]'::jsonb)
        ) order by i.incident_date desc, i.created_at desc
      )
      from public.employee_incidents i
      left join public.profiles rp on rp.id = i.reported_by
      left join public.profiles cp on cp.id = i.closed_by
      left join public.employee_incidents pp on pp.id = i.parent_incident_id
      where i.profile_id = p_profile_id
    ), '[]'::jsonb),
    'disciplinary_actions', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'action', to_jsonb(a),
          'issued_by_name', ip.full_name,
          'incident_title', i.title,
          'incident_status', i.status,
          'incident_reference', i.reference_code
        ) order by a.effective_date desc, a.created_at desc
      )
      from public.employee_disciplinary_actions a
      left join public.profiles ip on ip.id = a.issued_by
      left join public.employee_incidents i on i.id = a.incident_id
      where a.profile_id = p_profile_id
        and a.status <> 'revoked'
    ), '[]'::jsonb),
    'can_write', public.can_write_employee_expedientes()
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_discipline_detail"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_expediente_detail"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.profiles;
  v_extra public.employee_file_profiles;
begin
  if not public.can_read_employee_expedientes() then
    raise exception 'No tienes permiso para consultar expedientes.';
  end if;

  select * into v_profile from public.profiles where id = p_profile_id;
  if not found then
    raise exception 'Colaborador no encontrado.';
  end if;

  select * into v_extra from public.employee_file_profiles where profile_id = p_profile_id;

  return jsonb_build_object(
    'profile', to_jsonb(v_profile),
    'extra', coalesce(to_jsonb(v_extra), '{}'::jsonb),
    'completeness', public.employee_expediente_completeness(p_profile_id),
    'status', public.employee_expediente_status(p_profile_id),
    'summary', jsonb_build_object(
      'valid_count', (
        select count(*)
        from public.employee_file_versions v
        where v.profile_id = p_profile_id and v.is_current = true
          and public.employee_file_expiry_status(v.expires_at, v.no_expires) in ('valid', 'none')
      ),
      'expired_count', (
        select count(*)
        from public.employee_file_versions v
        where v.profile_id = p_profile_id and v.is_current = true
          and public.employee_file_expiry_status(v.expires_at, v.no_expires) = 'expired'
      ),
      'missing_count', coalesce((public.employee_expediente_completeness(p_profile_id) ->> 'missing_count')::integer, 0)
    ),
    'discipline_kpis', public.employee_discipline_profile_kpis(p_profile_id),
    'files', coalesce((
      select jsonb_agg(jsonb_build_object(
        'file', to_jsonb(f),
        'type', to_jsonb(ft),
        'current_version', (
          select to_jsonb(v)
          from public.employee_file_versions v
          where v.id = f.current_version_id
        ),
        'versions', coalesce((
          select jsonb_agg(to_jsonb(v) order by v.version_number desc)
          from public.employee_file_versions v
          where v.employee_file_id = f.id
        ), '[]'::jsonb),
        'expiry_status', (
          select public.employee_file_expiry_status(v.expires_at, v.no_expires)
          from public.employee_file_versions v
          where v.id = f.current_version_id
        )
      ) order by ft.sort_order)
      from public.employee_files f
      join public.employee_file_types ft on ft.code = f.file_type_code
      where f.profile_id = p_profile_id
    ), '[]'::jsonb),
    'types', coalesce((
      select jsonb_agg(to_jsonb(ft) order by ft.sort_order)
      from public.employee_file_types ft
    ), '[]'::jsonb),
    'labor_history', coalesce((
      select jsonb_agg(to_jsonb(h) order by h.effective_date desc nulls last, h.created_at desc)
      from public.employee_labor_history h
      where h.profile_id = p_profile_id
    ), '[]'::jsonb),
    'alerts', coalesce((
      select jsonb_agg(to_jsonb(a) order by a.created_at desc)
      from public.employee_file_alerts a
      where a.profile_id = p_profile_id and a.resolved_at is null
    ), '[]'::jsonb),
    'can_write', public.can_write_employee_expedientes(),
    'requires_food_handling', public.is_food_handling_area(v_profile.area_name, v_profile.area_id)
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_expediente_detail"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_expedientes"("p_search" "text" DEFAULT NULL::"text", "p_area" "text" DEFAULT NULL::"text", "p_job_title" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_expired_only" boolean DEFAULT false, "p_incomplete_only" boolean DEFAULT false, "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_area text := nullif(trim(coalesce(p_area, '')), '');
  v_job_title text := nullif(trim(coalesce(p_job_title, '')), '');
  v_status text := nullif(trim(coalesce(p_status, '')), '');
  v_limit integer := greatest(coalesce(p_limit, 200), 1);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not public.can_read_employee_expedientes() then
    raise exception 'No tienes permiso para consultar expedientes.';
  end if;

  return coalesce((
    select jsonb_agg(row_data order by row_data ->> 'full_name')
    from (
      select jsonb_build_object(
        'profile_id', p.id,
        'full_name', p.full_name,
        'avatar_url', p.avatar_url,
        'area_name', p.area_name,
        'area', p.area_name,
        'job_title', coalesce(efp.job_title, p.role),
        'dpi_number', coalesce(efp.dpi_number, ''),
        'nit_number', coalesce(efp.nit_number, ''),
        'status', public.employee_expediente_status(p.id),
        'completeness', public.employee_expediente_completeness(p.id),
        'expired_count', (
          select count(*)
          from public.employee_file_versions v
          where v.profile_id = p.id
            and v.is_current = true
            and v.expires_at is not null
            and v.expires_at < current_date
        ),
        'next_expiry', (
          select min(v.expires_at)
          from public.employee_file_versions v
          where v.profile_id = p.id
            and v.is_current = true
            and v.expires_at is not null
            and v.expires_at >= current_date
        )
      ) as row_data
      from public.profiles p
      left join public.employee_file_profiles efp on efp.profile_id = p.id
      where p.status = 'active'
        and (v_area is null or coalesce(p.area_name, '') ilike '%' || v_area || '%')
        and (v_job_title is null or coalesce(efp.job_title, p.role, '') ilike '%' || v_job_title || '%')
        and (
          v_search is null
          or coalesce(p.full_name, '') ilike '%' || v_search || '%'
          or coalesce(efp.dpi_number, '') ilike '%' || v_search || '%'
          or coalesce(efp.nit_number, '') ilike '%' || v_search || '%'
        )
        and (v_status is null or public.employee_expediente_status(p.id) = v_status)
        and (
          not coalesce(p_expired_only, false)
          or exists (
            select 1 from public.employee_file_versions v
            where v.profile_id = p.id and v.is_current and v.expires_at < current_date
          )
        )
        and (
          not coalesce(p_incomplete_only, false)
          or public.employee_expediente_status(p.id) = 'incomplete'
        )
      order by p.full_name
      limit v_limit
      offset v_offset
    ) rows
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_employee_expedientes"("p_search" "text", "p_area" "text", "p_job_title" "text", "p_status" "text", "p_expired_only" boolean, "p_incomplete_only" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_expedientes_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_discipline jsonb;
begin
  if not public.can_read_employee_expedientes() then
    raise exception 'No tienes permiso para consultar expedientes.';
  end if;

  v_discipline := public.employee_discipline_global_kpis();

  return jsonb_build_object(
    'expired_documents', (
      select count(*)
      from public.employee_file_versions v
      where v.is_current = true
        and not coalesce(v.no_expires, false)
        and v.expires_at is not null
        and v.expires_at < current_date
    ),
    'expiring_soon', (
      select count(*)
      from public.employee_file_versions v
      where v.is_current = true
        and not coalesce(v.no_expires, false)
        and v.expires_at is not null
        and v.expires_at between current_date and current_date + 30
    ),
    'incomplete_files', (
      select count(*)
      from public.profiles p
      where p.status = 'active'
        and public.employee_expediente_status(p.id) = 'incomplete'
    ),
    'complete_files', (
      select count(*)
      from public.profiles p
      where p.status = 'active'
        and public.employee_expediente_status(p.id) = 'complete'
    ),
    'expired_profiles', (
      select count(*)
      from public.profiles p
      where p.status = 'active'
        and public.employee_expediente_status(p.id) = 'expired'
    ),
    'discipline', v_discipline,
    'verbal_warnings', v_discipline -> 'verbal_warnings',
    'memorandums', v_discipline -> 'memorandums',
    'suspensions', v_discipline -> 'suspensions',
    'recurrences', v_discipline -> 'recurrences',
    'open_incidents', v_discipline -> 'open_incidents'
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_expedientes_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_expedientes_report"("p_report_type" "text" DEFAULT 'summary'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_type text := lower(trim(coalesce(p_report_type, 'summary')));
begin
  if not public.can_read_employee_expedientes() then
    raise exception 'No tienes permiso para generar reportes de expedientes.';
  end if;

  if v_type = 'expired' then
    return coalesce((
      select jsonb_agg(jsonb_build_object(
        'full_name', p.full_name,
        'area_name', p.area_name,
        'document', ft.label,
        'expires_at', v.expires_at,
        'days_overdue', current_date - v.expires_at
      ) order by p.full_name)
      from public.employee_file_versions v
      join public.profiles p on p.id = v.profile_id
      join public.employee_file_types ft on ft.code = v.file_type_code
      where v.is_current = true and v.expires_at < current_date
    ), '[]'::jsonb);
  elsif v_type = 'expiring' then
    return coalesce((
      select jsonb_agg(jsonb_build_object(
        'full_name', p.full_name,
        'area_name', p.area_name,
        'document', ft.label,
        'expires_at', v.expires_at,
        'days_left', v.expires_at - current_date
      ) order by v.expires_at)
      from public.employee_file_versions v
      join public.profiles p on p.id = v.profile_id
      join public.employee_file_types ft on ft.code = v.file_type_code
      where v.is_current = true
        and v.expires_at between current_date and current_date + 30
    ), '[]'::jsonb);
  elsif v_type = 'complete' then
    return coalesce((
      select jsonb_agg(jsonb_build_object(
        'full_name', p.full_name,
        'area_name', p.area_name,
        'completeness_percent', (public.employee_expediente_completeness(p.id) ->> 'percent')::integer
      ) order by p.full_name)
      from public.profiles p
      where p.status = 'active'
        and public.employee_expediente_status(p.id) = 'complete'
    ), '[]'::jsonb);
  end if;

  return public.get_employee_expedientes_dashboard();
end;
$$;


ALTER FUNCTION "public"."get_employee_expedientes_report"("p_report_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_executive_dashboard_metrics"("p_reference_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_ref timestamptz := coalesce(p_reference_at, now());
  v_op_day_start timestamptz;
  v_op_day_end timestamptz;
  v_ranges jsonb := '{}'::jsonb;
  v_settled_current jsonb := '{}'::jsonb;
  v_settled_previous jsonb := '{}'::jsonb;
  v_grain text;
  v_seg text;
  v_start timestamptz;
  v_end timestamptz;
  v_day_cur_s timestamptz;
  v_day_cur_e timestamptz;
  v_day_prev_s timestamptz;
  v_day_prev_e timestamptz;
  v_week_cur_s timestamptz;
  v_week_cur_e timestamptz;
  v_week_prev_s timestamptz;
  v_week_prev_e timestamptz;
  v_month_cur_s timestamptz;
  v_month_cur_e timestamptz;
  v_month_prev_s timestamptz;
  v_month_prev_e timestamptz;
  v_year_cur_s timestamptz;
  v_year_cur_e timestamptz;
  v_year_prev_s timestamptz;
  v_year_prev_e timestamptz;
  v_min_settled timestamptz;
  v_sales numeric(14, 2);
  v_orders bigint;
  v_avg numeric(14, 2);
  v_in_sales numeric(14, 2);
  v_in_orders bigint;
  v_stale_orders bigint;
  v_stale_sales numeric(14, 2);
  v_paid_without_paid_at bigint;
  v_partial_open jsonb;
  v_day_cur_sales numeric(14, 2);
  v_day_cur_orders bigint;
  v_day_prev_sales numeric(14, 2);
  v_day_prev_orders bigint;
  v_week_cur_sales numeric(14, 2);
  v_week_cur_orders bigint;
  v_week_prev_sales numeric(14, 2);
  v_week_prev_orders bigint;
  v_month_cur_sales numeric(14, 2);
  v_month_cur_orders bigint;
  v_month_prev_sales numeric(14, 2);
  v_month_prev_orders bigint;
  v_year_cur_sales numeric(14, 2);
  v_year_cur_orders bigint;
  v_year_prev_sales numeric(14, 2);
  v_year_prev_orders bigint;
begin
  if auth.uid() is null then
    raise exception 'Authentication required for executive dashboard metrics.';
  end if;

  if not public.is_executive_dashboard_reader() then
    raise exception 'No tienes permiso para consultar metricas ejecutivas.';
  end if;

  v_op_day_start := public.executive_operational_day_start(v_ref);
  v_op_day_end := v_op_day_start + interval '1 day';

  foreach v_grain in array array['day', 'week', 'month', 'year'] loop
    foreach v_seg in array array['current', 'previous'] loop
      select b.start_at, b.end_at
      into v_start, v_end
      from public.executive_period_bounds(v_ref, v_grain, v_seg) b;

      v_ranges := v_ranges || jsonb_build_object(
        v_grain,
        coalesce(v_ranges -> v_grain, '{}'::jsonb) || jsonb_build_object(
          v_seg,
          jsonb_build_object(
            'start_at', to_jsonb(v_start),
            'end_at', to_jsonb(v_end)
          )
        )
      );

      case v_grain
        when 'day' then
          if v_seg = 'current' then
            v_day_cur_s := v_start;
            v_day_cur_e := v_end;
          else
            v_day_prev_s := v_start;
            v_day_prev_e := v_end;
          end if;
        when 'week' then
          if v_seg = 'current' then
            v_week_cur_s := v_start;
            v_week_cur_e := v_end;
          else
            v_week_prev_s := v_start;
            v_week_prev_e := v_end;
          end if;
        when 'month' then
          if v_seg = 'current' then
            v_month_cur_s := v_start;
            v_month_cur_e := v_end;
          else
            v_month_prev_s := v_start;
            v_month_prev_e := v_end;
          end if;
        when 'year' then
          if v_seg = 'current' then
            v_year_cur_s := v_start;
            v_year_cur_e := v_end;
          else
            v_year_prev_s := v_start;
            v_year_prev_e := v_end;
          end if;
        else
          null;
      end case;
    end loop;
  end loop;

  v_min_settled := least(
    v_day_prev_s,
    v_week_prev_s,
    v_month_prev_s,
    v_year_prev_s
  );

  select
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_day_cur_s and o.paid_at < v_day_cur_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_day_cur_s and o.paid_at < v_day_cur_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_day_prev_s and o.paid_at < v_day_prev_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_day_prev_s and o.paid_at < v_day_prev_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_week_cur_s and o.paid_at < v_week_cur_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_week_cur_s and o.paid_at < v_week_cur_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_week_prev_s and o.paid_at < v_week_prev_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_week_prev_s and o.paid_at < v_week_prev_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_month_cur_s and o.paid_at < v_month_cur_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_month_cur_s and o.paid_at < v_month_cur_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_month_prev_s and o.paid_at < v_month_prev_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_month_prev_s and o.paid_at < v_month_prev_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_year_cur_s and o.paid_at < v_year_cur_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_year_cur_s and o.paid_at < v_year_cur_e),
    round(coalesce(sum(o.total) filter (
      where o.paid_at >= v_year_prev_s and o.paid_at < v_year_prev_e
    ), 0)::numeric, 2),
    count(*) filter (where o.paid_at >= v_year_prev_s and o.paid_at < v_year_prev_e)
  into
    v_day_cur_sales, v_day_cur_orders,
    v_day_prev_sales, v_day_prev_orders,
    v_week_cur_sales, v_week_cur_orders,
    v_week_prev_sales, v_week_prev_orders,
    v_month_cur_sales, v_month_cur_orders,
    v_month_prev_sales, v_month_prev_orders,
    v_year_cur_sales, v_year_cur_orders,
    v_year_prev_sales, v_year_prev_orders
  from public.pos_orders o
  where o.status = 'paid'
    and o.paid_at is not null
    and o.paid_at >= v_min_settled
    and o.paid_at < v_ref;

  v_settled_current := jsonb_build_object(
    'day', jsonb_build_object(
      'sales', v_day_cur_sales,
      'orders', v_day_cur_orders,
      'average_ticket', case when v_day_cur_orders > 0 then round(v_day_cur_sales / v_day_cur_orders, 2) else 0 end
    ),
    'week', jsonb_build_object(
      'sales', v_week_cur_sales,
      'orders', v_week_cur_orders,
      'average_ticket', case when v_week_cur_orders > 0 then round(v_week_cur_sales / v_week_cur_orders, 2) else 0 end
    ),
    'month', jsonb_build_object(
      'sales', v_month_cur_sales,
      'orders', v_month_cur_orders,
      'average_ticket', case when v_month_cur_orders > 0 then round(v_month_cur_sales / v_month_cur_orders, 2) else 0 end
    ),
    'year', jsonb_build_object(
      'sales', v_year_cur_sales,
      'orders', v_year_cur_orders,
      'average_ticket', case when v_year_cur_orders > 0 then round(v_year_cur_sales / v_year_cur_orders, 2) else 0 end
    )
  );

  v_settled_previous := jsonb_build_object(
    'day', jsonb_build_object(
      'sales', v_day_prev_sales,
      'orders', v_day_prev_orders,
      'average_ticket', case when v_day_prev_orders > 0 then round(v_day_prev_sales / v_day_prev_orders, 2) else 0 end
    ),
    'week', jsonb_build_object(
      'sales', v_week_prev_sales,
      'orders', v_week_prev_orders,
      'average_ticket', case when v_week_prev_orders > 0 then round(v_week_prev_sales / v_week_prev_orders, 2) else 0 end
    ),
    'month', jsonb_build_object(
      'sales', v_month_prev_sales,
      'orders', v_month_prev_orders,
      'average_ticket', case when v_month_prev_orders > 0 then round(v_month_prev_sales / v_month_prev_orders, 2) else 0 end
    ),
    'year', jsonb_build_object(
      'sales', v_year_prev_sales,
      'orders', v_year_prev_orders,
      'average_ticket', case when v_year_prev_orders > 0 then round(v_year_prev_sales / v_year_prev_orders, 2) else 0 end
    )
  );

  select
    round(coalesce(sum(o.total) filter (
      where o.created_at >= v_op_day_start and o.created_at < v_op_day_end
    ), 0)::numeric, 2),
    count(*) filter (where o.created_at >= v_op_day_start and o.created_at < v_op_day_end),
    count(*) filter (where o.created_at < v_op_day_start),
    round(coalesce(sum(o.total) filter (
      where o.created_at < v_op_day_start
    ), 0)::numeric, 2)
  into v_in_sales, v_in_orders, v_stale_orders, v_stale_sales
  from public.pos_orders o
  where o.status in ('open', 'sent', 'awaiting_bill', 'sent_to_cashier');

  select count(*)::bigint
  into v_paid_without_paid_at
  from public.pos_orders o
  where o.status = 'paid'
    and o.paid_at is null;

  v_partial_open := public.executive_partial_open_snapshot(v_ref);

  return jsonb_build_object(
    'contract_version', 2,
    'generated_at', to_jsonb(v_ref),
    'timezone', 'America/Guatemala',
    'business_day_cutoff', '04:00:00',
    'comparison_mode', 'same_elapsed_previous_calendar_period',
    'metrics_non_sumable', jsonb_build_array('partial_open'),
    'ranges', v_ranges,
    'settled', jsonb_build_object(
      'current', v_settled_current,
      'previous', v_settled_previous
    ),
    'in_progress', jsonb_build_object(
      'sales', v_in_sales,
      'orders', v_in_orders,
      'as_of', to_jsonb(v_ref),
      'operational_day_start', to_jsonb(v_op_day_start),
      'operational_day_end', to_jsonb(v_op_day_end),
      'stale_outside_current_operational_day_orders', v_stale_orders,
      'stale_outside_current_operational_day_sales', v_stale_sales
    ),
    'partial_open', v_partial_open,
    'data_quality', jsonb_build_object(
      'paid_without_paid_at', v_paid_without_paid_at
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_executive_dashboard_metrics"("p_reference_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_executive_dashboard_metrics"("p_reference_at" timestamp with time zone) IS 'Aggregated executive dashboard metrics (contract v2). SECURITY INVOKER; partial_open via DEFINER snapshot; no payment row payloads.';



CREATE OR REPLACE FUNCTION "public"."get_finance_cash_flow"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_start date := coalesce(p_start_date, (now() at time zone 'America/Guatemala')::date - 30);
  v_end date := coalesce(p_end_date, (now() at time zone 'America/Guatemala')::date);
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_view_finance() then
    raise exception 'No tienes permiso para ver finanzas.';
  end if;

  with daily as (
    select d.day::date as flow_date,
      coalesce(sum(case when t.direction = 'in' then t.amount else 0 end), 0) as inflows,
      coalesce(sum(case when t.direction = 'out' then t.amount else 0 end), 0) as outflows
    from generate_series(v_start, v_end, interval '1 day') as d(day)
    left join public.finance_bank_transactions t on t.transaction_date = d.day::date
    group by d.day
    order by d.day
  ),
  with_running as (
    select
      flow_date,
      inflows,
      outflows,
      inflows - outflows as net,
      sum(inflows - outflows) over (order by flow_date) as running_balance
    from daily
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'flow_date', flow_date,
    'inflows', inflows,
    'outflows', outflows,
    'net', net,
    'running_balance', running_balance
  ) order by flow_date), '[]'::jsonb)
  into v_rows
  from with_running;

  return jsonb_build_object('start_date', v_start, 'end_date', v_end, 'rows', v_rows);
end;
$$;


ALTER FUNCTION "public"."get_finance_cash_flow"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_finance_dashboard"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_bank_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_start date := coalesce(p_start_date, date_trunc('month', (now() at time zone 'America/Guatemala'))::date);
  v_end date := coalesce(p_end_date, (now() at time zone 'America/Guatemala')::date);
  v_available numeric := 0;
  v_receivable numeric := 0;
  v_payable numeric := 0;
  v_inflows numeric := 0;
  v_outflows numeric := 0;
  v_collections numeric := 0;
  v_payments numeric := 0;
  v_overdue_payables_count int := 0;
  v_overdue_payables_amount numeric := 0;
  v_overdue_receivables_count int := 0;
  v_overdue_receivables_amount numeric := 0;
begin
  if not public.can_view_finance() then
    raise exception 'No tienes permiso para ver finanzas.';
  end if;

  select coalesce(sum(current_balance), 0) into v_available
  from public.finance_bank_accounts
  where is_active
    and (p_bank_account_id is null or id = p_bank_account_id);

  select coalesce(sum(balance), 0) into v_receivable
  from public.finance_receivables
  where status in ('pending', 'partial', 'overdue');

  select coalesce(sum(balance), 0) into v_payable
  from public.finance_payables
  where status in ('pending', 'partial', 'overdue');

  select coalesce(sum(amount), 0) into v_inflows
  from public.finance_bank_transactions
  where direction = 'in'
    and transaction_date between v_start and v_end
    and (p_bank_account_id is null or bank_account_id = p_bank_account_id);

  select coalesce(sum(amount), 0) into v_outflows
  from public.finance_bank_transactions
  where direction = 'out'
    and transaction_date between v_start and v_end
    and (p_bank_account_id is null or bank_account_id = p_bank_account_id);

  select coalesce(sum(amount), 0) into v_collections
  from public.finance_receivable_collections
  where collection_date between v_start and v_end;

  select coalesce(sum(amount), 0) into v_payments
  from public.finance_payable_payments
  where payment_date between v_start and v_end;

  select count(*), coalesce(sum(balance), 0)
  into v_overdue_payables_count, v_overdue_payables_amount
  from public.finance_payables
  where status = 'overdue';

  select count(*), coalesce(sum(balance), 0)
  into v_overdue_receivables_count, v_overdue_receivables_amount
  from public.finance_receivables
  where status = 'overdue';

  return jsonb_build_object(
    'start_date', v_start,
    'end_date', v_end,
    'available_cash', v_available,
    'receivable_balance', v_receivable,
    'payable_balance', v_payable,
    'net_flow', v_inflows - v_outflows,
    'period_collections', v_collections + v_inflows,
    'period_payments', v_payments + v_outflows,
    'overdue_payables_count', v_overdue_payables_count,
    'overdue_payables_amount', v_overdue_payables_amount,
    'overdue_receivables_count', v_overdue_receivables_count,
    'overdue_receivables_amount', v_overdue_receivables_amount
  );
end;
$$;


ALTER FUNCTION "public"."get_finance_dashboard"("p_start_date" "date", "p_end_date" "date", "p_bank_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_finance_integration_status"("p_source_module" "text", "p_source_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_module text := lower(trim(coalesce(p_source_module, '')));
  v_id text := trim(coalesce(p_source_id, ''));
  v_payable public.finance_payables;
  v_receivable public.finance_receivables;
  v_deposits int := 0;
begin
  if v_id = '' then
    raise exception 'source_id es obligatorio.';
  end if;
  if not public.can_view_finance_integration(v_module) then
    raise exception 'No tienes permiso para consultar el estado financiero.';
  end if;

  if v_module = 'purchases' then
    select * into v_payable
    from public.finance_payables
    where source_module = 'purchases' and source_id = v_id
    limit 1;

    return jsonb_build_object(
      'source_module', v_module,
      'source_id', v_id,
      'linked', v_payable.id is not null,
      'record_id', v_payable.id,
      'record_type', 'payable',
      'financial_status', coalesce(v_payable.status, 'none'),
      'financial_status_label', public.finance_integration_status_label(
        'payable', coalesce(v_payable.status, 'none'), v_payable.id is not null
      ),
      'balance', coalesce(v_payable.balance, 0),
      'total_amount', coalesce(v_payable.total_amount, 0)
    );
  elsif v_module = 'catering' then
    select * into v_receivable
    from public.finance_receivables
    where source_module = 'catering' and source_id = v_id
    limit 1;

    return jsonb_build_object(
      'source_module', v_module,
      'source_id', v_id,
      'linked', v_receivable.id is not null,
      'record_id', v_receivable.id,
      'record_type', 'receivable',
      'financial_status', coalesce(v_receivable.status, 'none'),
      'financial_status_label', public.finance_integration_status_label(
        'receivable', coalesce(v_receivable.status, 'none'), v_receivable.id is not null
      ),
      'balance', coalesce(v_receivable.balance, 0),
      'total_amount', coalesce(v_receivable.total_amount, 0)
    );
  elsif v_module = 'cash_closing' then
    select count(*) into v_deposits
    from public.finance_bank_transactions
    where source_module = 'cash_closing'
      and source_id = v_id
      and type = 'deposit';

    return jsonb_build_object(
      'source_module', v_module,
      'source_id', v_id,
      'linked', v_deposits > 0,
      'record_type', 'deposit',
      'financial_status', case when v_deposits > 0 then 'sent' else 'none' end,
      'financial_status_label', public.finance_integration_status_label(
        'deposit', case when v_deposits > 0 then 'sent' else 'none' end, v_deposits > 0
      ),
      'deposit_count', v_deposits
    );
  else
    raise exception 'Modulo de integracion no soportado: %.', v_module;
  end if;
end;
$$;


ALTER FUNCTION "public"."get_finance_integration_status"("p_source_module" "text", "p_source_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_finance_pending_integrations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_purchases jsonb := '[]'::jsonb;
  v_catering jsonb := '[]'::jsonb;
  v_cash jsonb := '[]'::jsonb;
begin
  if not public.can_view_finance() then
    raise exception 'No tienes permiso para ver integraciones pendientes.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', po.id,
    'order_number', po.order_number,
    'supplier_name', coalesce(po.data -> 'proveedor' ->> 'nombre', ''),
    'status', po.status,
    'total_amount', (select total_amount from public.finance_purchase_order_amounts(po.data) limit 1),
    'created_at', po.created_at
  ) order by po.created_at desc), '[]'::jsonb)
  into v_purchases
  from public.purchase_orders po
  where coalesce(po.is_test, false) = false
    and po.status in ('recibida_parcial', 'recibida_completa')
    and not exists (
      select 1 from public.finance_payables fp
      where fp.source_module = 'purchases' and fp.source_id = po.id
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'customer_name', r.customer_name,
    'event_date', r.event_date,
    'status', r.status,
    'estimated_value', coalesce(r.estimated_value, 0),
    'created_at', r.created_at
  ) order by r.created_at desc), '[]'::jsonb)
  into v_catering
  from public.catering_requests r
  where r.status = 'approved' or r.conversion_status = 'approved'
    and not exists (
      select 1 from public.finance_receivables fr
      where fr.source_module = 'catering' and fr.source_id = r.id::text
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'closed_at', s.closed_at,
    'counted_cash', coalesce(s.counted_cash, 0),
    'register_name', cr.name,
    'status', s.status
  ) order by s.closed_at desc nulls last), '[]'::jsonb)
  into v_cash
  from public.cash_sessions s
  left join public.cash_registers cr on cr.id = s.cash_register_id
  where s.status = 'closed'
    and not exists (
      select 1 from public.finance_bank_transactions t
      where t.source_module = 'cash_closing'
        and t.source_id = s.id::text
        and t.type = 'deposit'
    );

  return jsonb_build_object(
    'purchases', v_purchases,
    'catering', v_catering,
    'cash_closings', v_cash,
    'counts', jsonb_build_object(
      'purchases', jsonb_array_length(v_purchases),
      'catering', jsonb_array_length(v_catering),
      'cash_closings', jsonb_array_length(v_cash)
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_finance_pending_integrations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_fixed_costs_by_month"("p_month" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_month date := public.normalize_fixed_cost_month(coalesce(p_month, current_date));
  v_prev_month date := (v_month - interval '1 month')::date;
  v_costs jsonb;
  v_total numeric(12, 2) := 0;
  v_paid numeric(12, 2) := 0;
  v_pending numeric(12, 2) := 0;
  v_overdue numeric(12, 2) := 0;
  v_prev_total numeric(12, 2) := 0;
  v_by_category jsonb := '[]'::jsonb;
begin
  if not public.can_view_fixed_costs() then
    raise exception 'No tienes permiso para ver costos fijos.';
  end if;

  select coalesce(jsonb_agg(to_jsonb(fc) order by fc.category, fc.name), '[]'::jsonb)
  into v_costs
  from public.fixed_costs fc
  where fc.cost_month = v_month
    and fc.is_active = true;

  select
    coalesce(sum(amount), 0),
    coalesce(sum(amount) filter (where payment_status = 'paid'), 0),
    coalesce(sum(amount) filter (where payment_status = 'pending'), 0),
    coalesce(sum(amount) filter (where payment_status = 'overdue'), 0)
  into v_total, v_paid, v_pending, v_overdue
  from public.fixed_costs
  where cost_month = v_month
    and is_active = true;

  select coalesce(sum(amount), 0)
  into v_prev_total
  from public.fixed_costs
  where cost_month = v_prev_month
    and is_active = true;

  select coalesce(jsonb_agg(jsonb_build_object(
    'category', grouped.category,
    'amount', grouped.amount,
    'percent', case when v_total > 0 then round((grouped.amount / v_total) * 100, 1) else 0 end
  ) order by grouped.amount desc), '[]'::jsonb)
  into v_by_category
  from (
    select category, coalesce(sum(amount), 0) as amount
    from public.fixed_costs
    where cost_month = v_month
      and is_active = true
    group by category
  ) grouped;

  return jsonb_build_object(
    'cost_month', v_month,
    'costs', v_costs,
    'summary', jsonb_build_object(
      'total', v_total,
      'paid_total', v_paid,
      'pending_total', v_pending,
      'overdue_total', v_overdue,
      'by_category', v_by_category,
      'previous_month_total', v_prev_total,
      'comparison_percent', case
        when v_prev_total > 0 then round(((v_total - v_prev_total) / v_prev_total) * 100, 1)
        when v_total > 0 then 100
        else 0
      end
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_fixed_costs_by_month"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_category_product_counts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb := '{}'::jsonb;
begin
  if not public.is_inventory_manager() then
    raise exception 'No autorizado para consultar uso de categorías de inventario';
  end if;

  select coalesce(
    jsonb_object_agg(bucket.normalized_name, bucket.product_count),
    '{}'::jsonb
  )
  into result
  from (
    select
      lower(trim(translate(coalesce(ii.category, ''), 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'))) as normalized_name,
      count(*)::bigint as product_count
    from public.inventory_items ii
    where nullif(trim(ii.category), '') is not null
    group by 1
  ) bucket
  where bucket.normalized_name <> '';

  return result;
end;
$$;


ALTER FUNCTION "public"."get_inventory_category_product_counts"() OWNER TO "postgres";


