CREATE OR REPLACE FUNCTION "public"."get_inventory_item_usage"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb := '{}'::jsonb;
  v_count integer;
begin
  if p_item_id is null then
    return result;
  end if;

  select count(*) into v_count from public.requisition_items where item_id = p_item_id;
  result := result || jsonb_build_object('requisition_items', v_count);

  select count(*) into v_count from public.recipe_ingredients where inventory_item_id = p_item_id;
  result := result || jsonb_build_object('recipe_ingredients', v_count);

  select count(*) into v_count
  from public.standard_recipes
  where output_inventory_item_id = p_item_id;
  result := result || jsonb_build_object('standard_recipes_output', v_count);

  select count(*) into v_count from public.inventory_movements where item_id = p_item_id;
  result := result || jsonb_build_object('inventory_movements', v_count);

  select count(*) into v_count
  from public.purchase_orders po
  where exists (
    select 1
    from jsonb_array_elements(coalesce(po.data -> 'items', '[]'::jsonb)) elem
    where coalesce(elem ->> 'producto_id', elem ->> 'inventory_item_id', elem ->> 'id') = p_item_id::text
  );
  result := result || jsonb_build_object('purchase_orders', v_count);

  select count(*) into v_count
  from public.production_batch_inputs
  where inventory_item_id = p_item_id;
  result := result || jsonb_build_object('production_batch_inputs', v_count);

  select count(*) into v_count
  from public.production_batch_outputs
  where inventory_item_id = p_item_id;
  result := result || jsonb_build_object('production_batch_outputs', v_count);

  select count(*) into v_count
  from public.production_batches
  where output_inventory_item_id = p_item_id;
  result := result || jsonb_build_object('production_batches', v_count);

  return result;
end;
$$;


ALTER FUNCTION "public"."get_inventory_item_usage"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_migration_mode"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_value jsonb;
  v_activated_name text;
  v_deactivated_name text;
begin
  select value into v_value
  from public.app_settings
  where key = 'inventory_migration_mode';

  v_value := coalesce(v_value, public.inventory_migration_mode_default());

  select coalesce(p.full_name, p.username, 'Administrador')
  into v_activated_name
  from public.profiles p
  where p.id = nullif(v_value ->> 'activated_by', '')::uuid;

  select coalesce(p.full_name, p.username, 'Administrador')
  into v_deactivated_name
  from public.profiles p
  where p.id = nullif(v_value ->> 'deactivated_by', '')::uuid;

  return v_value
    || jsonb_build_object(
      'activated_by_name', v_activated_name,
      'deactivated_by_name', v_deactivated_name
    );
end;
$$;


ALTER FUNCTION "public"."get_inventory_migration_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_item_open_requisitions_for_unit_change"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb := '[]'::jsonb;
begin
  if p_item_id is null then
    return result;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'requisition_id', q.requisition_id,
        'requisition_number', q.requisition_number,
        'status', q.status,
        'from_area_id', q.from_area_id,
        'to_area_id', q.to_area_id,
        'requested_quantity', q.requested_quantity,
        'requested_unit', q.requested_unit,
        'inventory_base_unit_at_request', q.inventory_base_unit_at_request,
        'created_at', q.created_at
      )
      order by q.created_at desc
    ),
    '[]'::jsonb
  )
  into result
  from (
    select distinct on (r.id)
      r.id as requisition_id,
      r.requisition_number,
      r.status,
      r.from_area_id,
      r.to_area_id,
      ri.requested_quantity,
      coalesce(ri.requested_unit, ri.unit) as requested_unit,
      coalesce(ri.inventory_base_unit_at_request, ri.unit) as inventory_base_unit_at_request,
      r.created_at
    from public.requisition_items ri
    join public.requisitions r on r.id = ri.requisition_id
    where ri.item_id = p_item_id
      and coalesce(r.is_test, false) = false
      and public.is_requisition_open_for_unit_guard(r.status)
    order by r.id, r.created_at desc
  ) q;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_item_open_requisitions_for_unit_change"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_monthly_goal_report"("p_month" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("goal_month" "date", "target_amount" numeric, "actual_sales" numeric, "progress_percent" numeric, "remaining_amount" numeric, "days_elapsed" integer, "days_remaining" integer, "average_daily_sales" numeric, "required_daily_sales" numeric, "status_label" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  goal_row public.sales_goals;
  month_start date := date_trunc('month', coalesce(p_month, current_date))::date;
  month_end date := (month_start + interval '1 month - 1 day')::date;
  elapsed integer := greatest(1, least(current_date, month_end) - month_start + 1);
  remaining integer := greatest(0, month_end - current_date);
  actual numeric;
  percent numeric;
  remaining_amount_value numeric;
begin
  if not public.can_read_sales_goals() then
    raise exception 'No tienes permiso para ver reportes de metas.';
  end if;

  select * into goal_row
  from public.sales_goals
  where sales_goals.goal_month = month_start
    and sales_goals.goal_type = 'monthly_sales'
    and sales_goals.status = 'active'
  limit 1;

  if goal_row.id is null then
    return query select month_start, 0::numeric, 0::numeric, 0::numeric, 0::numeric, elapsed, remaining, 0::numeric, 0::numeric, 'Sin meta'::text;
    return;
  end if;

  actual := public.monthly_sales_for_goal(month_start);
  percent := round((actual / nullif(goal_row.target_amount, 0)) * 100, 2);
  remaining_amount_value := greatest(0, goal_row.target_amount - actual);

  return query select
    goal_row.goal_month,
    goal_row.target_amount,
    actual,
    coalesce(percent, 0),
    remaining_amount_value,
    elapsed,
    remaining,
    round(actual / elapsed, 2),
    round(case when remaining > 0 then remaining_amount_value / remaining else remaining_amount_value end, 2),
    public.goal_status_label(coalesce(percent, 0), remaining);
end;
$$;


ALTER FUNCTION "public"."get_monthly_goal_report"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_notifications"("p_limit" integer DEFAULT 100) RETURNS SETOF "public"."notifications"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select n.*
  from public.notifications n
  where auth.uid() is not null
    and (
      n.user_id = auth.uid()
      or (
        n.target_role is not null
        and public.normalize_profile_role(n.target_role) = public.normalize_profile_role(
          public.current_profile_role()
        )
      )
    )
    and (
      not public.is_catering_notification(n.type, n.entity_type)
      or public.can_receive_catering_notifications(public.current_profile_role())
    )
  order by n.is_read asc, n.created_at desc
  limit greatest(coalesce(p_limit, 100), 1);
$$;


ALTER FUNCTION "public"."get_my_notifications"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_operational_tasks"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select coalesce(jsonb_agg(
    public.operational_task_card_summary(t)
    order by t.sort_position asc, t.updated_at desc
  ), '[]'::jsonb)
  into v_rows
  from (
    select t.*
    from public.assigned_tasks t
    where t.task_source = 'operational'
      and t.deleted_at is null
      and t.archived_at is null
      and public.can_access_operational_task(t, 'view')
      and exists (
        select 1 from public.task_assignees ta
        where ta.task_id = t.id and ta.profile_id = auth.uid() and ta.status = 'active'
      )
      and (p_status is null or t.status = p_status)
    order by t.sort_position asc, t.updated_at desc
    limit v_limit
  ) t;

  return jsonb_build_object('tasks', v_rows);
end;
$$;


ALTER FUNCTION "public"."get_my_operational_tasks"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_open_attendance_shifts"() RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "area" "text", "entrada_id" "uuid", "entrada_at" timestamp with time zone, "labor_date" "date", "calendar_date" "date", "overnight_shift" boolean, "has_open_meal" boolean, "meal_started_at" timestamp with time zone, "classification" "text", "approval_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'America/Guatemala';
  v_calendar_date date := (now() at time zone v_tz)::date;
begin
  if not public.is_schedule_publisher() then
    return;
  end if;

  return query
  with open_entries as (
    select distinct on (m.employee_id)
      m.id as entrada_id,
      m.employee_id,
      m.employee_name,
      m.marked_at as entrada_at,
      coalesce(m.labor_date, (m.marked_at at time zone v_tz)::date) as labor_date,
      m.classification,
      m.approval_status
    from public.attendance_marks m
    where m.mark_type = 'entrada'
      and not exists (
        select 1
        from public.attendance_marks out_mark
        where out_mark.employee_id = m.employee_id
          and out_mark.mark_type in ('salida_final', 'salida')
          and out_mark.marked_at > m.marked_at
      )
    order by m.employee_id, m.marked_at desc
  ),
  open_meals as (
    select distinct on (oe.employee_id)
      oe.employee_id,
      m.id as meal_id,
      m.marked_at as meal_started_at
    from open_entries oe
    join public.attendance_marks m
      on m.employee_id = oe.employee_id
      and m.mark_type in ('salida_comida', 'bano_inicio')
      and m.marked_at > oe.entrada_at
      and not exists (
        select 1
        from public.attendance_marks back_mark
        where back_mark.employee_id = m.employee_id
          and back_mark.mark_type in ('regreso_comida', 'bano_regreso')
          and back_mark.marked_at > m.marked_at
      )
    order by oe.employee_id, m.marked_at desc
  )
  select
    oe.employee_id,
    coalesce(p.full_name, p.username, oe.employee_name, 'Colaborador'),
    p.area_name,
    oe.entrada_id,
    oe.entrada_at,
    oe.labor_date,
    v_calendar_date,
    oe.labor_date < v_calendar_date,
    om.meal_id is not null,
    om.meal_started_at,
    oe.classification,
    oe.approval_status
  from open_entries oe
  join public.profiles p on p.id = oe.employee_id
  left join open_meals om on om.employee_id = oe.employee_id
  order by oe.entrada_at;
end;
$$;


ALTER FUNCTION "public"."get_open_attendance_shifts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_process_run_detail"("p_process_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.operational_process_runs;
  v_template public.operational_process_templates;
  v_steps jsonb := '[]'::jsonb;
begin
  select * into v_run from public.operational_process_runs where id = p_process_run_id;
  if v_run.id is null then
    raise exception 'Ejecucion de proceso no encontrada.';
  end if;

  if not public.can_access_operational_process_run(v_run) then
    raise exception 'No tienes permiso para consultar este proceso.';
  end if;

  select * into v_template from public.operational_process_templates where id = v_run.process_template_id;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', rs.id,
      'step_order', rs.step_order,
      'step_label', rs.step_label,
      'is_required', rs.is_required,
      'depends_on_run_step_id', rs.depends_on_run_step_id,
      'checklist_run_id', rs.checklist_run_id,
      'child_template_id', rs.child_template_id,
      'checklist_run', (
        select jsonb_build_object(
          'id', cr.id,
          'status', cr.status,
          'run_date', cr.run_date,
          'area', cr.area,
          'assigned_profile_id', cr.assigned_profile_id,
          'assigned_role', cr.assigned_role,
          'started_at', cr.started_at,
          'completed_at', cr.completed_at,
          'template_title', ct.title,
          'item_count', (select count(*) from public.checklist_run_items cri where cri.run_id = cr.id),
          'completed_items', (
            select count(*) from public.checklist_run_items cri
            where cri.run_id = cr.id and cri.completed_at is not null
          )
        )
        from public.checklist_runs cr
        left join public.checklist_templates ct on ct.id = cr.template_id
        where cr.id = rs.checklist_run_id
      )
    ) order by rs.step_order asc, rs.id asc
  ), '[]'::jsonb)
  into v_steps
  from public.operational_process_run_steps rs
  where rs.process_run_id = p_process_run_id;

  return jsonb_build_object(
    'process_run', to_jsonb(v_run),
    'template', to_jsonb(v_template),
    'steps', v_steps,
    'progress', public.operational_process_run_progress(p_process_run_id)
  );
end;
$$;


ALTER FUNCTION "public"."get_operational_process_run_detail"("p_process_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_process_runs_for_date"("p_run_date" "date" DEFAULT "public"."get_checklist_operational_date"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_view_operational_process_groups() then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(
    public.get_operational_process_run_detail(r.id)
    order by (r.process_template_id), r.created_at
  ), '[]'::jsonb)
  into v_rows
  from public.operational_process_runs r
  where r.run_date = p_run_date
    and r.status <> 'cancelled'
    and public.can_access_operational_process_run(r);

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."get_operational_process_runs_for_date"("p_run_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_process_template_detail"("p_process_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_template public.operational_process_templates;
  v_steps jsonb := '[]'::jsonb;
begin
  if p_process_template_id is null then
    raise exception 'p_process_template_id es obligatorio.';
  end if;

  select * into v_template
  from public.operational_process_templates
  where id = p_process_template_id;

  if v_template.id is null then
    raise exception 'Proceso operativo no encontrado.';
  end if;

  if not public.can_read_operational_process_template(v_template) then
    raise exception 'No tienes permiso para consultar este proceso.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'process_template_id', s.process_template_id,
      'child_template_id', s.child_template_id,
      'depends_on_step_id', s.depends_on_step_id,
      'step_order', s.step_order,
      'step_label', s.step_label,
      'assigned_profile_id', s.assigned_profile_id,
      'assigned_role', s.assigned_role,
      'area', s.area,
      'supervisor_profile_id', s.supervisor_profile_id,
      'is_required', s.is_required,
      'child_template', (
        select jsonb_build_object(
          'id', ct.id,
          'title', ct.title,
          'area', ct.area,
          'assigned_role', ct.assigned_role,
          'assigned_profile_id', ct.assigned_profile_id,
          'status', ct.status
        )
        from public.checklist_templates ct
        where ct.id = s.child_template_id
      )
    ) order by s.step_order asc, s.id asc
  ), '[]'::jsonb)
  into v_steps
  from public.operational_process_template_steps s
  where s.process_template_id = p_process_template_id;

  return jsonb_build_object(
    'template', to_jsonb(v_template),
    'steps', v_steps
  );
end;
$$;


ALTER FUNCTION "public"."get_operational_process_template_detail"("p_process_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_process_templates_library"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb;
begin
  if not public.can_view_operational_process_groups() then
    raise exception 'No tienes permiso para consultar procesos operativos.';
  end if;

  select coalesce(jsonb_agg(row order by row ->> 'title'), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', t.id,
      'title', t.title,
      'description', t.description,
      'area', t.area,
      'process_type', t.process_type,
      'completion_mode', t.completion_mode,
      'allow_parallel_execution', t.allow_parallel_execution,
      'status', t.status,
      'supervisor_profile_id', t.supervisor_profile_id,
      'frequency_type', coalesce(t.frequency_type, 'manual'),
      'recurrence_days', coalesce(t.recurrence_days, '{}'::integer[]),
      'recurrence_month_day', t.recurrence_month_day,
      'step_count', (
        select count(*) from public.operational_process_template_steps s
        where s.process_template_id = t.id
      ),
      'created_at', t.created_at,
      'updated_at', t.updated_at
    ) as row
    from public.operational_process_templates t
    where public.can_read_operational_process_template(t)
    order by t.title
  ) sub;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."get_operational_process_templates_library"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_station_device_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_station public.operational_stations;
begin
  select * into v_device
  from public.operational_station_devices
  where auth_user_id = auth.uid() and status = 'active'
  limit 1;
  if v_device.id is null then
    return jsonb_build_object('active', false);
  end if;
  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.status <> 'active' or v_device.status <> 'active' then
    return jsonb_build_object('active', false, 'reason', 'station_or_device_inactive');
  end if;
  return jsonb_build_object(
    'active', true,
    'device_id', v_device.id,
    'station_id', v_station.id,
    'station_name', v_station.name,
    'station_code', v_station.station_code,
    'station_type', v_station.station_type,
    'area_id', v_station.area_id,
    'cash_register_id', v_station.cash_register_id,
    'pos_floor_zone', v_station.pos_floor_zone
  );
end;
$$;


ALTER FUNCTION "public"."get_operational_station_device_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_task_detail"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_activity jsonb;
  v_created_name text;
begin
  if p_task_id is null or trim(p_task_id) = '' then
    raise exception 'p_task_id es obligatorio.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null;

  if not found then
    raise exception 'Tarea no encontrada.';
  end if;

  if not public.can_access_operational_task(v_task, 'view') then
    raise exception 'No tienes permiso para ver esta tarea.';
  end if;

  select coalesce(p.full_name, 'Sistema') into v_created_name
  from public.profiles p where p.id = v_task.created_by;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', l.id,
      'action', l.action,
      'field_name', l.field_name,
      'old_value', l.old_value,
      'new_value', l.new_value,
      'metadata', l.metadata,
      'created_at', l.created_at,
      'actor_name', coalesce(p.full_name, 'Sistema'),
      'icon', public.task_activity_icon(l.action) ->> 'icon',
      'tone', public.task_activity_icon(l.action) ->> 'tone'
    )
    order by l.created_at desc
  ), '[]'::jsonb)
  into v_activity
  from public.task_activity_log l
  left join public.profiles p on p.id = l.actor_id
  where l.task_id = p_task_id
    and l.action not in ('moved', 'updated');

  return public.operational_task_row(v_task)
    || jsonb_build_object(
      'activity', v_activity,
      'created_by_name', v_created_name,
      'permissions', public.get_operational_task_permissions(v_task),
      'is_overdue', (
        v_task.due_at is not null
        and v_task.due_at < now()
        and v_task.status not in ('completed', 'cancelled')
      ),
      'steps_progress', public.get_task_work_plan_progress(p_task_id),
      'work_summary', public.get_task_next_work_step(p_task_id),
      'work_plan', public.task_work_plan_json(p_task_id),
      'open_days', public.task_open_duration_days(v_task),
      'blocked_days', public.task_blocked_duration_days(v_task),
      'labels', public.task_labels_for_task(p_task_id),
      'archived_at', v_task.archived_at,
      'archived_by', v_task.archived_by,
      'attachments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', a.id,
            'step_id', a.step_id,
            'attachment_type', a.attachment_type,
            'storage_path', a.storage_path,
            'external_url', a.external_url,
            'display_name', a.display_name,
            'mime_type', a.mime_type,
            'size_bytes', a.size_bytes,
            'uploaded_by', a.uploaded_by,
            'uploaded_by_name', (select p.full_name from public.profiles p where p.id = a.uploaded_by),
            'uploaded_at', a.uploaded_at
          )
          order by a.uploaded_at desc
        )
        from public.task_attachments a
        where a.task_id = p_task_id and a.deleted_at is null
      ), '[]'::jsonb),
      'comments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', c.id,
            'step_id', c.step_id,
            'body_markdown', c.body_markdown,
            'mention_profile_ids', c.mention_profile_ids,
            'created_by', c.created_by,
            'created_by_name', (select p.full_name from public.profiles p where p.id = c.created_by),
            'created_by_avatar', (select p.avatar_url from public.profiles p where p.id = c.created_by),
            'created_at', c.created_at
          )
          order by c.created_at asc
        )
        from public.task_comments c
        where c.task_id = p_task_id and c.deleted_at is null
      ), '[]'::jsonb),
      'evidence', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', e.id,
            'step_id', e.step_id,
            'evidence_type', e.evidence_type,
            'storage_path', e.storage_path,
            'external_url', e.external_url,
            'display_name', e.display_name,
            'mime_type', e.mime_type,
            'note_text', e.note_text,
            'submitted_by', e.submitted_by,
            'submitted_by_name', (select p.full_name from public.profiles p where p.id = e.submitted_by),
            'submitted_at', e.submitted_at,
            'verified_by', e.verified_by,
            'verified_at', e.verified_at
          )
          order by e.submitted_at desc
        )
        from public.task_evidence e
        where e.task_id = p_task_id and e.deleted_at is null
      ), '[]'::jsonb),
      'recurrence', (
        select jsonb_build_object(
          'id', r.id,
          'frequency', r.frequency,
          'interval_days', r.interval_days,
          'next_run_at', r.next_run_at,
          'enabled', r.enabled
        )
        from public.task_recurrence_rules r
        where r.source_task_id = p_task_id
        limit 1
      )
    );
end;
$$;


ALTER FUNCTION "public"."get_operational_task_detail"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_task_permissions"("p_task" "public"."assigned_tasks") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'can_view', public.can_access_operational_task(p_task, 'view'),
    'can_edit', public.can_mutate_operational_task(p_task),
    'can_assign', public.can_manage_operational_task_members(p_task),
    'can_move', public.can_mutate_operational_task(p_task),
    'manage_members', public.can_manage_operational_task_members(p_task),
    'manage_watchers', public.can_manage_operational_task_watchers(p_task),
    'watch_self', public.can_access_operational_task(p_task, 'view'),
    'is_watching', public.is_operational_task_watcher(p_task.id, auth.uid()),
    'manage_work_plan', public.can_manage_task_work_plan(p_task),
    'complete_steps', public.can_mutate_operational_task(p_task),
    'assign_steps', public.can_mutate_operational_task(p_task),
    'upload_attachments', public.can_upload_task_files(p_task),
    'comment', public.can_comment_on_task(p_task),
    'submit_evidence', public.can_submit_task_evidence(p_task),
    'verify_evidence', public.is_operational_task_area_manager(),
    'manage_labels', public.can_manage_task_labels(),
    'assign_labels', public.can_mutate_operational_task(p_task),
    'can_archive', (
      public.can_mutate_operational_task(p_task)
      and p_task.archived_at is null
      and p_task.deleted_at is null
    ),
    'can_restore', (
      p_task.archived_at is not null
      and p_task.deleted_at is null
      and (
        public.can_manage_task_labels()
        or p_task.created_by = auth.uid()
        or exists (
          select 1 from public.task_assignees ta
          where ta.task_id = p_task.id
            and ta.profile_id = auth.uid()
            and ta.status = 'active'
            and ta.assignment_role = 'primary'
        )
      )
    )
  );
$$;


ALTER FUNCTION "public"."get_operational_task_permissions"("p_task" "public"."assigned_tasks") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_tasks_board"("p_area_id" "text" DEFAULT NULL::"text", "p_assignee_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_include_cancelled" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := nullif(trim(lower(coalesce(p_search, ''))), '');
  v_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select coalesce(jsonb_agg(public.operational_task_row(t) order by
    case t.priority
      when 'critical' then 1
      when 'high' then 2
      when 'medium' then 3
      else 4
    end,
    t.due_at nulls last,
    t.created_at desc
  ), '[]'::jsonb)
  into v_rows
  from public.assigned_tasks t
  where t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
    and public.can_access_operational_task(t, 'view')
    and (p_include_cancelled or t.status <> 'cancelled')
    and (p_area_id is null or t.area_id = p_area_id)
    and (
      p_assignee_id is null
      or exists (
        select 1
        from public.task_assignees ta
        where ta.task_id = t.id
          and ta.profile_id = p_assignee_id
          and ta.status = 'active'
      )
    )
    and (
      v_search is null
      or lower(t.title) like '%' || v_search || '%'
      or lower(coalesce(t.description, '')) like '%' || v_search || '%'
      or lower(coalesce(t.category, '')) like '%' || v_search || '%'
    );

  return jsonb_build_object('tasks', v_rows);
end;
$$;


ALTER FUNCTION "public"."get_operational_tasks_board"("p_area_id" "text", "p_assignee_id" "uuid", "p_search" "text", "p_include_cancelled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_tasks_board"("p_area_id" "text" DEFAULT NULL::"text", "p_assignee_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_include_cancelled" boolean DEFAULT false, "p_completed_days" integer DEFAULT 7, "p_include_old_completed" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := nullif(trim(lower(coalesce(p_search, ''))), '');
  v_completed_days integer := greatest(coalesce(p_completed_days, 7), 1);
  v_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select coalesce(jsonb_agg(
    public.operational_task_card_summary(t)
    order by t.sort_position asc, t.created_at desc
  ), '[]'::jsonb)
  into v_rows
  from public.assigned_tasks t
  where t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
    and public.can_access_operational_task(t, 'view')
    and (p_include_cancelled or t.status <> 'cancelled')
    and (
      t.status <> 'completed'
      or p_include_old_completed
      or t.completed_at >= now() - make_interval(days => v_completed_days)
      or (t.completed_at is null and t.updated_at >= now() - make_interval(days => v_completed_days))
    )
    and (p_area_id is null or t.area_id = p_area_id)
    and (
      p_assignee_id is null
      or exists (
        select 1 from public.task_assignees ta
        where ta.task_id = t.id and ta.profile_id = p_assignee_id and ta.status = 'active'
      )
    )
    and (
      v_search is null
      or lower(t.title) like '%' || v_search || '%'
      or lower(coalesce(t.objective, '')) like '%' || v_search || '%'
      or lower(coalesce(t.expected_result, '')) like '%' || v_search || '%'
      or exists (
        select 1 from public.task_steps s
        where s.task_id = t.id
          and s.deleted_at is null
          and lower(s.text) like '%' || v_search || '%'
      )
    );

  return jsonb_build_object('tasks', v_rows);
end;
$$;


ALTER FUNCTION "public"."get_operational_tasks_board"("p_area_id" "text", "p_assignee_id" "uuid", "p_search" "text", "p_include_cancelled" boolean, "p_completed_days" integer, "p_include_old_completed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_tasks_board"("p_area_id" "text" DEFAULT NULL::"text", "p_assignee_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_include_cancelled" boolean DEFAULT false, "p_completed_days" integer DEFAULT 7, "p_include_old_completed" boolean DEFAULT false, "p_label_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := nullif(trim(lower(coalesce(p_search, ''))), '');
  v_completed_days integer := greatest(coalesce(p_completed_days, 7), 1);
  v_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select coalesce(jsonb_agg(
    public.operational_task_card_summary(t)
    order by t.sort_position asc, t.created_at desc
  ), '[]'::jsonb)
  into v_rows
  from public.assigned_tasks t
  where t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
    and public.can_access_operational_task(t, 'view')
    and (p_include_cancelled or t.status <> 'cancelled')
    and (
      t.status <> 'completed'
      or p_include_old_completed
      or t.completed_at >= now() - make_interval(days => v_completed_days)
      or (t.completed_at is null and t.updated_at >= now() - make_interval(days => v_completed_days))
    )
    and (p_area_id is null or t.area_id = p_area_id)
    and (
      p_assignee_id is null
      or exists (
        select 1 from public.task_assignees ta
        where ta.task_id = t.id and ta.profile_id = p_assignee_id and ta.status = 'active'
      )
    )
    and (
      v_search is null
      or lower(t.title) like '%' || v_search || '%'
      or lower(coalesce(t.objective, '')) like '%' || v_search || '%'
      or lower(coalesce(t.expected_result, '')) like '%' || v_search || '%'
      or exists (
        select 1 from public.task_steps s
        where s.task_id = t.id
          and s.deleted_at is null
          and lower(s.text) like '%' || v_search || '%'
      )
    )
    and (
      p_label_ids is null
      or cardinality(p_label_ids) = 0
      or exists (
        select 1 from public.task_label_assignments tla
        where tla.task_id = t.id
          and tla.label_id = any(p_label_ids)
      )
    );

  return jsonb_build_object('tasks', v_rows);
end;
$$;


