CREATE TABLE IF NOT EXISTS "public"."purchase_orders" (
    "id" "text" NOT NULL,
    "order_number" "text" NOT NULL,
    "status" "text" NOT NULL,
    "data" "jsonb" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_by_role" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_test" boolean DEFAULT false NOT NULL,
    CONSTRAINT "purchase_orders_status_check" CHECK (("status" = ANY (ARRAY['borrador'::"text", 'pendiente_aprobacion'::"text", 'aprobada'::"text", 'rechazada'::"text", 'enviada_proveedor'::"text", 'recibida_parcial'::"text", 'recibida_completa'::"text", 'cancelada'::"text"])))
);


ALTER TABLE "public"."purchase_orders" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_today_purchase_order_draft"() RETURNS "public"."purchase_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_role text := public.current_profile_role();
  today_date date := public.operational_today_date();
  today_text text := to_char(today_date, 'YYYY-MM-DD');
  today_suffix text := to_char(today_date, 'YYYYMMDD');
  existing_order public.purchase_orders;
  next_count int;
  order_id text;
  order_number text;
  initial_status text;
  order_payload jsonb;
  actor_name text;
begin
  if not public.can_operate_purchase_orders() then
    raise exception 'No tienes permiso para operar ordenes de compra.';
  end if;

  select po.*
  into existing_order
  from public.purchase_orders po
  where coalesce(po.is_test, false) = false
    and po.status in ('borrador', 'pendiente_aprobacion')
    and (
      nullif(trim(po.data ->> 'fechaEmision'), '') = today_text
      or (po.created_at at time zone 'America/Guatemala')::date = today_date
    )
  order by po.created_at desc
  limit 1;

  if existing_order.id is not null then
    return existing_order;
  end if;

  select coalesce(full_name, username, email, 'Usuario')
  into actor_name
  from public.profiles
  where id = auth.uid();

  select count(*) + 1
  into next_count
  from public.purchase_orders
  where order_number like '%-' || today_suffix;

  order_id := (extract(epoch from clock_timestamp()) * 1000)::bigint::text;
  order_number := 'OC-' || lpad(next_count::text, 4, '0') || '-' || today_suffix;
  initial_status := case
    when actor_role in ('gerente', 'encargado_almacen') then 'pendiente_aprobacion'
    else 'borrador'
  end;

  order_payload := jsonb_build_object(
    'id', order_id,
    'numeroOrden', order_number,
    'fechaEmision', today_text,
    'fechaEsperadaEntrega', to_char(today_date + 3, 'YYYY-MM-DD'),
    'status', initial_status,
    'creadoPorId', auth.uid()::text,
    'creadoPorRol', actor_role,
    'proveedorId', null,
    'proveedor', jsonb_build_object(
      'nombre', 'Por definir',
      'contacto', '',
      'correo', '',
      'whatsapp', '',
      'encargado', ''
    ),
    'metodoCompra', 'manual',
    'requester', actor_name,
    'approver', '',
    'prioridad', 'normal',
    'lugar', 'almacen',
    'items', '[]'::jsonb,
    'creado', to_char(now() at time zone 'America/Guatemala', 'YYYY-MM-DD HH24:MI:SS'),
    'recepcion', null,
    'is_test', false,
    'source', 'requisition_low_stock'
  );

  insert into public.purchase_orders (
    id, order_number, status, data, created_by, created_by_role, is_test
  ) values (
    order_id,
    order_number,
    initial_status,
    order_payload,
    auth.uid(),
    actor_role,
    false
  )
  returning * into existing_order;

  return existing_order;
end;
$$;


ALTER FUNCTION "public"."get_or_create_today_purchase_order_draft"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_register_attendance_device"("p_device_id" "text", "p_device_name" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_device_type" "text" DEFAULT NULL::"text", "p_client_ip" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_devices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  device_row public.attendance_devices;
  normalized_id text := nullif(trim(p_device_id), '');
begin
  if normalized_id is null then
    raise exception 'device_id es obligatorio.';
  end if;

  select * into device_row
  from public.attendance_devices
  where device_id = normalized_id;

  if device_row.id is null then
    insert into public.attendance_devices (
      device_id, device_name, device_type, user_agent, status, last_seen_at, last_ip
    )
    values (
      normalized_id,
      coalesce(nullif(trim(p_device_name), ''), 'Terminal pendiente'),
      nullif(trim(p_device_type), ''),
      nullif(trim(p_user_agent), ''),
      'pending',
      now(),
      nullif(trim(p_client_ip), '')
    )
    returning * into device_row;

    perform public.log_attendance_security_event(
      normalized_id,
      null,
      'device_pending',
      p_client_ip,
      p_user_agent,
      jsonb_build_object('device_name', device_row.device_name)
    );
  else
    update public.attendance_devices
    set
      device_name = coalesce(nullif(trim(p_device_name), ''), device_name),
      device_type = coalesce(nullif(trim(p_device_type), ''), device_type),
      user_agent = coalesce(nullif(trim(p_user_agent), ''), user_agent),
      last_seen_at = now(),
      last_ip = coalesce(nullif(trim(p_client_ip), ''), last_ip),
      updated_at = now()
    where id = device_row.id
    returning * into device_row;
  end if;

  return device_row;
end;
$$;


ALTER FUNCTION "public"."get_or_register_attendance_device"("p_device_id" "text", "p_device_name" "text", "p_user_agent" "text", "p_device_type" "text", "p_client_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_print_jobs"("p_location" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "printer_id" "uuid", "job_type" "text", "payload" "jsonb", "status" "text", "attempts" integer, "created_at" timestamp with time zone, "printer_name" "text", "windows_printer_name" "text", "location" "text", "printer_type" "text", "ip_address" "text", "port" integer, "paper_width" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    j.id,
    j.printer_id,
    j.job_type,
    j.payload,
    j.status,
    j.attempts,
    j.created_at,
    p.name as printer_name,
    p.windows_printer_name,
    p.location,
    p.printer_type,
    p.ip_address,
    p.port,
    p.paper_width
  from public.print_jobs j
  join public.pos_printers p on p.id = j.printer_id
  where j.status = 'pending'
    and p.is_active = true
    and (
      nullif(trim(coalesce(p_location, '')), '') is null
      or lower(coalesce(p.location, '')) = lower(trim(p_location))
    )
  order by j.created_at asc
  limit greatest(1, least(coalesce(p_limit, 10), 50));
$$;


ALTER FUNCTION "public"."get_pending_print_jobs"("p_location" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pos_floor_layout"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  if not public.can_read_pos_floor_plan() then
    raise exception 'No tienes permiso para consultar el plano del restaurante.';
  end if;

  select jsonb_build_object(
    'areas', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', z.id,
          'name', z.name,
          'nombre', z.name,
          'description', coalesce(z.description, ''),
          'sortOrder', z.sort_order,
          'active', z.active,
          'width', z.width,
          'height', z.height,
          'mesasTotales', (
            select count(*)
            from public.pos_floor_tables t
            where t.zone_id = z.id and t.active = true
          )
        )
        order by z.sort_order, z.name
      )
      from public.pos_floor_zones z
      where z.active = true
    ), '[]'::jsonb),
    'tables', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', t.id,
          'areaId', t.zone_id,
          'zone_id', t.zone_id,
          'name', t.name,
          'numero', regexp_replace(t.name, '^[Mm]', ''),
          'capacity', t.capacity,
          'capacidad', t.capacity,
          'shape', t.shape,
          'x', t.x,
          'y', t.y,
          'status', t.manual_status,
          'estado', t.manual_status,
          'manual_status', t.manual_status,
          'sortOrder', t.sort_order,
          'active', t.active
        )
        order by t.zone_id, t.sort_order, t.name
      )
      from public.pos_floor_tables t
      join public.pos_floor_zones z on z.id = t.zone_id
      where t.active = true and z.active = true
    ), '[]'::jsonb),
    'settings', coalesce((
      select jsonb_build_object(
        'snapToGrid', s.snap_to_grid,
        'gridSize', s.grid_size,
        'zoom', s.zoom
      )
      from public.pos_floor_settings s
      where s.id = 'default'
    ), jsonb_build_object('snapToGrid', true, 'gridSize', 24, 'zoom', 1))
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_pos_floor_layout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pos_implementation_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_total integer := 0;
  v_active_recipe integer := 0;
  v_tracking integer := 0;
  v_pending integer := 0;
  v_sold_no_recipe jsonb := '[]'::jsonb;
  v_sold_no_tracking jsonb := '[]'::jsonb;
begin
  if not public.is_profile_manager() then
    raise exception 'No tienes permiso para ver el panel de implementacion POS.';
  end if;

  select count(*) into v_total from public.pos_products where active = true;
  select count(*) into v_active_recipe from public.pos_products where active = true and recipe_status = 'active';
  select count(*) into v_tracking from public.pos_products where active = true and inventory_tracking_enabled = true;
  select count(*) into v_pending from public.pos_products where active = true and recipe_status in ('missing', 'draft');

  select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_sold_no_recipe
  from (
    select
      item.product_id,
      max(item.product_name) as product_name,
      sum(item.quantity) as units_sold,
      count(distinct item.order_id) as order_count
    from public.pos_order_items item
    join public.pos_orders ord on ord.id = item.order_id
    join public.pos_products product on product.id = item.product_id
    where ord.created_at >= now() - interval '30 days'
      and item.status not in ('draft', 'cancelled')
      and coalesce(product.recipe_status, 'missing') <> 'active'
    group by item.product_id
    order by units_sold desc
    limit 25
  ) t;

  select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_sold_no_tracking
  from (
    select
      item.product_id,
      max(item.product_name) as product_name,
      sum(item.quantity) as units_sold,
      count(distinct item.order_id) as order_count
    from public.pos_order_items item
    join public.pos_orders ord on ord.id = item.order_id
    join public.pos_products product on product.id = item.product_id
    where ord.created_at >= now() - interval '30 days'
      and item.status not in ('draft', 'cancelled')
      and coalesce(product.inventory_tracking_enabled, false) = false
    group by item.product_id
    order by units_sold desc
    limit 25
  ) t;

  return jsonb_build_object(
    'deduction_mode', public.get_inventory_deduction_mode(),
    'total_pos_products', v_total,
    'products_with_active_recipe', v_active_recipe,
    'products_with_inventory_tracking', v_tracking,
    'products_pending_recipe', v_pending,
    'implementation_percent', case when v_total = 0 then 0 else round((v_active_recipe::numeric / v_total) * 100, 1) end,
    'sold_last_30_days_without_active_recipe', v_sold_no_recipe,
    'sold_last_30_days_without_inventory_tracking', v_sold_no_tracking
  );
end;
$$;


ALTER FUNCTION "public"."get_pos_implementation_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pos_order_payment_status"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  order_row public.pos_orders;
  result jsonb;
begin
  if not public.is_cash_operator() then
    raise exception 'No tienes permiso para consultar pagos POS.';
  end if;

  select * into order_row
  from public.pos_orders
  where id = p_order_id;

  if order_row.id is null then
    raise exception 'Orden no encontrada.';
  end if;

  select jsonb_build_object(
    'order_id', order_row.id,
    'order_total', order_row.total,
    'order_status', order_row.status,
    'amount_paid', coalesce((
      select sum(p.amount)
      from public.pos_order_payments p
      where p.order_id = order_row.id and p.status = 'paid'
    ), 0),
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'order_item_id', item.id,
          'product_name', item.product_name,
          'quantity_total', item.quantity,
          'quantity_paid', item.quantity_paid,
          'quantity_remaining', greatest(0, item.quantity - item.quantity_paid),
          'unit_price', item.unit_price,
          'line_total', item.total_price,
          'line_remaining', round(greatest(0, item.quantity - item.quantity_paid) * item.unit_price, 2),
          'status', item.status,
          'is_fully_paid', item.quantity_paid >= item.quantity
        )
        order by item.created_at, item.id
      )
      from public.pos_order_items item
      where item.order_id = order_row.id
        and item.status <> 'cancelled'
    ), '[]'::jsonb)
  ) into result;

  return result || jsonb_build_object(
    'balance_due', greatest(0, order_row.total - coalesce((result ->> 'amount_paid')::numeric, 0))
  );
end;
$$;


ALTER FUNCTION "public"."get_pos_order_payment_status"("p_order_id" "uuid") OWNER TO "postgres";


