CREATE OR REPLACE FUNCTION "public"."get_profiles_task_unavailability"("p_profile_ids" "uuid"[], "p_date" "date") RETURNS TABLE("profile_id" "uuid", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  profile_id uuid;
  profile_row public.profiles;
  weekday_int integer;
  schedule_row record;
  custom_row record;
  unavailability text;
begin
  if not public.is_task_assigner() then
    raise exception 'No tienes permiso para consultar disponibilidad.';
  end if;

  weekday_int := extract(dow from coalesce(p_date, current_date))::integer;

  foreach profile_id in array coalesce(p_profile_ids, array[]::uuid[])
  loop
    unavailability := null;
    select * into profile_row from public.profiles where id = profile_id;

    if profile_row.id is null then
      profile_id := profile_id;
      reason := 'Perfil no encontrado';
      return next;
      continue;
    end if;

    if profile_row.status = 'suspended' then
      profile_id := profile_row.id;
      reason := 'Suspendido';
      return next;
      continue;
    end if;

    for schedule_row in
      select
        es.is_work_day,
        es.shift_type,
        coalesce(st.is_rest_day, false) as is_rest_day,
        coalesce(st.is_holiday, false) as is_holiday,
        st.name as shift_type_name
      from public.employee_schedules es
      left join public.shift_types st on st.id = es.shift_type_id
      where es.employee_id = profile_row.id
        and es.shift_date = coalesce(p_date, current_date)
        and es.status = 'published'
    loop
      if not schedule_row.is_work_day
        or lower(coalesce(schedule_row.shift_type, '')) = 'rest'
        or schedule_row.is_rest_day then
        unavailability := 'Dia de descanso';
        exit;
      end if;
      if schedule_row.is_holiday
        or lower(coalesce(schedule_row.shift_type_name, '')) like '%vacac%' then
        unavailability := 'Vacaciones';
        exit;
      end if;
    end loop;

    if unavailability is null then
      for custom_row in
        select
          coalesce(st.is_rest_day, false) as is_rest_day,
          coalesce(st.is_holiday, false) as is_holiday,
          st.name as shift_type_name
        from public.employee_custom_schedules ecs
        left join public.shift_types st on st.id = ecs.shift_type_id
        where ecs.profile_id = profile_row.id
          and ecs.status = 'active'
          and (
            ecs.specific_date = coalesce(p_date, current_date)
            or (
              ecs.weekday = weekday_int
              and ecs.specific_date is null
              and (ecs.start_date is null or ecs.start_date <= coalesce(p_date, current_date))
              and (ecs.end_date is null or ecs.end_date >= coalesce(p_date, current_date))
            )
            or (
              ecs.start_date is not null
              and ecs.end_date is not null
              and coalesce(p_date, current_date) between ecs.start_date and ecs.end_date
            )
          )
      loop
        if custom_row.is_rest_day then
          unavailability := 'Dia de descanso';
          exit;
        end if;
        if custom_row.is_holiday
          or lower(coalesce(custom_row.shift_type_name, '')) like '%vacac%' then
          unavailability := 'Vacaciones';
          exit;
        end if;
      end loop;
    end if;

    profile_id := profile_row.id;
    reason := unavailability;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."get_profiles_task_unavailability"("p_profile_ids" "uuid"[], "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_monthly_goal_progress"("p_month" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("goal_month" "date", "title" "text", "progress_percent" numeric, "status_label" "text", "days_remaining" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  goal_row public.sales_goals;
  month_start date := date_trunc('month', coalesce(p_month, current_date))::date;
  month_end date := (month_start + interval '1 month - 1 day')::date;
  actual_sales numeric;
  percent numeric;
  remaining_days integer;
begin
  if not public.can_read_public_goal_widgets() then
    raise exception 'No tienes permiso para ver el avance de metas.';
  end if;

  select * into goal_row
  from public.sales_goals
  where sales_goals.goal_month = month_start
    and sales_goals.goal_type = 'monthly_sales'
    and sales_goals.status = 'active'
  limit 1;

  if goal_row.id is null then
    return query select month_start, 'Meta del mes pendiente de configurar.'::text, 0::numeric, 'Sin meta'::text, greatest(0, month_end - current_date);
    return;
  end if;

  actual_sales := public.monthly_sales_for_goal(month_start);
  percent := round((actual_sales / nullif(goal_row.target_amount, 0)) * 100, 2);
  remaining_days := greatest(0, month_end - current_date);

  return query select
    goal_row.goal_month,
    goal_row.title,
    coalesce(percent, 0),
    public.goal_status_label(coalesce(percent, 0), remaining_days),
    remaining_days;
end;
$$;


ALTER FUNCTION "public"."get_public_monthly_goal_progress"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_purchase_order_receiving_progress"("p_purchase_order_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.purchase_orders;
  v_is_test boolean;
  v_po_items jsonb;
  v_po_line jsonb;
  v_item public.inventory_items;
  v_item_id uuid;
  v_factor numeric;
  v_qty_ordered numeric;
  v_qty_ordered_base numeric;
  v_qty_received_base numeric;
  v_qty_remaining_base numeric;
  v_supplier text;
  v_suppliers jsonb := '{}'::jsonb;
  v_supplier_items jsonb;
  v_item_entry jsonb;
  v_total_ordered numeric := 0;
  v_total_received numeric := 0;
  v_progress numeric := 0;
  v_line_status text;
  v_receipts jsonb := '[]'::jsonb;
begin
  if public.current_profile_role() not in ('admin', 'gerente_general', 'gerente', 'encargado_almacen') then
    raise exception 'No tienes permiso para consultar recepciones.';
  end if;

  select * into v_order
  from public.purchase_orders
  where id = trim(p_purchase_order_id);

  if v_order.id is null then
    raise exception 'Orden de compra no encontrada.';
  end if;

  v_is_test := coalesce(v_order.is_test, false);
  v_po_items := coalesce(v_order.data -> 'items', '[]'::jsonb);

  for v_po_line in select value from jsonb_array_elements(v_po_items)
  loop
    v_item_id := public.po_line_item_id(v_po_line);
    if v_item_id is null then
      continue;
    end if;

    select * into v_item from public.inventory_items where id = v_item_id;
    v_factor := public.po_line_conversion_factor(v_po_line, v_item);
    v_qty_ordered := public.po_line_qty_ordered(v_po_line);
    v_qty_ordered_base := v_qty_ordered * v_factor;
    v_qty_received_base := public.po_item_received_base(v_order.id, v_item_id, v_is_test);
    v_qty_remaining_base := greatest(v_qty_ordered_base - v_qty_received_base, 0);

    v_line_status := case
      when v_qty_ordered_base <= 0 then 'sin_pedido'
      when v_qty_received_base <= public.po_receipt_qty_tolerance() then 'pendiente'
      when v_qty_remaining_base <= public.po_receipt_qty_tolerance() then 'completo'
      else 'parcial'
    end;

    v_supplier := public.po_line_supplier_name(
      v_po_line,
      coalesce(v_order.data -> 'proveedor' ->> 'nombre', 'Sin proveedor')
    );

    v_item_entry := jsonb_build_object(
      'item_id', v_item_id,
      'item_name', coalesce(v_item.name, v_po_line ->> 'nombre', 'Producto'),
      'supplier_name', v_supplier,
      'qty_ordered', v_qty_ordered,
      'qty_ordered_base', v_qty_ordered_base,
      'qty_received', round(v_qty_received_base / v_factor, 3),
      'qty_received_base', v_qty_received_base,
      'qty_remaining', round(v_qty_remaining_base / v_factor, 3),
      'qty_remaining_base', v_qty_remaining_base,
      'purchase_unit', coalesce(v_po_line ->> 'unidadCompra', v_po_line ->> 'unidad_compra', v_item.purchase_unit),
      'base_unit', v_item.base_unit,
      'conversion_factor', v_factor,
      'status', v_line_status
    );

    v_supplier_items := coalesce(v_suppliers -> v_supplier, '[]'::jsonb) || jsonb_build_array(v_item_entry);
    v_suppliers := jsonb_set(v_suppliers, array[v_supplier], v_supplier_items, true);

    if v_qty_ordered_base > 0 then
      v_total_ordered := v_total_ordered + v_qty_ordered_base;
      v_total_received := v_total_received + least(v_qty_received_base, v_qty_ordered_base);
    end if;
  end loop;

  if v_total_ordered > 0 then
    v_progress := round((v_total_received / v_total_ordered) * 100, 2);
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'receipt_id', r.id,
      'received_at', r.received_at,
      'supplier_name', r.supplier_name,
      'invoice_number', r.invoice_number,
      'invoice_date', r.invoice_date,
      'total', (
        select coalesce(sum(rl.subtotal), 0)
        from public.purchase_order_receipt_lines rl
        where rl.receipt_id = r.id
      ),
      'received_by', r.received_by,
      'is_test', r.is_test
    )
    order by r.received_at desc
  ), '[]'::jsonb)
  into v_receipts
  from public.purchase_order_receipts r
  where r.purchase_order_id = v_order.id
    and r.status = 'received';

  return jsonb_build_object(
    'order_id', v_order.id,
    'order_number', v_order.order_number,
    'status', v_order.status,
    'progress_percent', v_progress,
    'suppliers', (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'supplier_name', s.key,
          'items', s.value,
          'status', case
            when not exists (
              select 1
              from jsonb_array_elements(s.value) elem
              where elem ->> 'status' in ('pendiente', 'parcial')
            ) then 'completo'
            when exists (
              select 1
              from jsonb_array_elements(s.value) elem
              where elem ->> 'status' = 'completo'
            ) then 'parcial'
            else 'pendiente'
          end
        )
        order by s.key
      ), '[]'::jsonb)
      from jsonb_each(v_suppliers) s
    ),
    'receipts', v_receipts,
    'is_test', v_is_test
  );
end;
$$;


ALTER FUNCTION "public"."get_purchase_order_receiving_progress"("p_purchase_order_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recruitment_candidate_detail"("p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate public.recruitment_candidates;
  v_vacancy public.recruitment_vacancies;
  v_base jsonb;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para consultar candidatos.';
  end if;

  select * into v_candidate from public.recruitment_candidates where id = p_candidate_id;
  if v_candidate.id is null then
    raise exception 'Candidato no encontrado.';
  end if;

  select * into v_vacancy from public.recruitment_vacancies where id = v_candidate.vacancy_id;

  v_base := jsonb_build_object(
    'candidate', to_jsonb(v_candidate),
    'vacancy', to_jsonb(v_vacancy),
    'contacts', coalesce((
      select jsonb_agg(to_jsonb(ct) order by ct.contacted_at desc)
      from public.recruitment_candidate_contacts ct where ct.candidate_id = p_candidate_id
    ), '[]'::jsonb),
    'interviews', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'interview', to_jsonb(i),
          'responsible_name', rp.full_name,
          'evaluation', (select to_jsonb(ev) from public.recruitment_interview_evaluations ev where ev.interview_id = i.id)
        ) order by i.scheduled_date desc, i.scheduled_time desc nulls last
      )
      from public.recruitment_interviews i
      left join public.profiles rp on rp.id = i.responsible_profile_id
      where i.candidate_id = p_candidate_id
    ), '[]'::jsonb),
    'status_history', coalesce((
      select jsonb_agg(to_jsonb(h) order by h.changed_at desc)
      from public.recruitment_candidate_status_history h where h.candidate_id = p_candidate_id
    ), '[]'::jsonb),
    'onboarding', (
      select to_jsonb(o) from public.recruitment_onboarding_checklists o where o.candidate_id = p_candidate_id
    ),
    'retention_reviews', coalesce((
      select jsonb_agg(to_jsonb(r) order by r.review_day)
      from public.recruitment_retention_reviews r where r.candidate_id = p_candidate_id
    ), '[]'::jsonb),
    'employee_profile', (
      select jsonb_build_object('id', p.id, 'full_name', p.full_name, 'username', p.username, 'role', p.role, 'area_name', p.area_name)
      from public.profiles p where p.id = v_candidate.profile_id
    )
  );

  return v_base;
end;
$$;


ALTER FUNCTION "public"."get_recruitment_candidate_detail"("p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recruitment_kpis"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_position" "text" DEFAULT NULL::"text", "p_area" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from date := coalesce(p_date_from, ((now() at time zone 'America/Guatemala')::date - interval '30 days')::date);
  v_to date := coalesce(p_date_to, (now() at time zone 'America/Guatemala')::date);
  v_open_vacancies integer := 0;
  v_critical_vacancies integer := 0;
  v_applications integer := 0;
  v_contacted integer := 0;
  v_responded integer := 0;
  v_interviews_scheduled integer := 0;
  v_interviews_done integer := 0;
  v_no_shows integer := 0;
  v_offers integer := 0;
  v_hired integer := 0;
  v_discarded integer := 0;
  v_avg_coverage numeric := null;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para consultar KPIs de reclutamiento.';
  end if;

  select count(*) into v_open_vacancies
  from public.recruitment_vacancies v
  where v.status in ('open', 'recruiting', 'interviewing')
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%')
    and (p_position is null or nullif(trim(p_position), '') is null or v.position_title ilike '%' || trim(p_position) || '%');

  select count(*) into v_critical_vacancies
  from public.recruitment_vacancies v
  where v.status in ('open', 'recruiting', 'interviewing')
    and v.priority = 'critical'
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_applications
  from public.recruitment_candidates c
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where c.applied_at between v_from and v_to
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%')
    and (p_position is null or nullif(trim(p_position), '') is null or v.position_title ilike '%' || trim(p_position) || '%');

  select count(distinct ct.candidate_id) into v_contacted
  from public.recruitment_candidate_contacts ct
  join public.recruitment_candidates c on c.id = ct.candidate_id
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where ct.contacted_at::date between v_from and v_to
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_responded
  from public.recruitment_candidate_contacts ct
  join public.recruitment_candidates c on c.id = ct.candidate_id
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where ct.contacted_at::date between v_from and v_to
    and ct.result in ('answered', 'callback_requested')
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_interviews_scheduled
  from public.recruitment_interviews i
  join public.recruitment_candidates c on c.id = i.candidate_id
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where i.scheduled_date between v_from and v_to
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_interviews_done
  from public.recruitment_interviews i
  join public.recruitment_candidates c on c.id = i.candidate_id
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where i.scheduled_date between v_from and v_to
    and i.result = 'attended'
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_no_shows
  from public.recruitment_interviews i
  join public.recruitment_candidates c on c.id = i.candidate_id
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where i.scheduled_date between v_from and v_to
    and i.result = 'no_show'
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_offers
  from public.recruitment_candidates c
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where c.pipeline_status = 'offer'
    and c.applied_at between v_from and v_to
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_hired
  from public.recruitment_candidates c
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where c.pipeline_status = 'hired'
    and coalesce(c.hired_at::date, c.applied_at) between v_from and v_to
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select count(*) into v_discarded
  from public.recruitment_candidates c
  join public.recruitment_vacancies v on v.id = c.vacancy_id
  where c.pipeline_status = 'discarded'
    and c.applied_at between v_from and v_to
    and (p_source is null or c.source = p_source)
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  select round(avg((v.filled_at::date - v.request_date)), 1)
  into v_avg_coverage
  from public.recruitment_vacancies v
  where v.status = 'filled'
    and v.filled_at is not null
    and v.filled_at::date between v_from and v_to
    and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%');

  return jsonb_build_object(
    'date_from', v_from,
    'date_to', v_to,
    'open_vacancies', coalesce(v_open_vacancies, 0),
    'critical_vacancies', coalesce(v_critical_vacancies, 0),
    'applications_received', coalesce(v_applications, 0),
    'candidates_contacted', coalesce(v_contacted, 0),
    'candidates_responded', coalesce(v_responded, 0),
    'interviews_scheduled', coalesce(v_interviews_scheduled, 0),
    'interviews_completed', coalesce(v_interviews_done, 0),
    'no_shows', coalesce(v_no_shows, 0),
    'offers_made', coalesce(v_offers, 0),
    'hired', coalesce(v_hired, 0),
    'discarded', coalesce(v_discarded, 0),
    'response_rate', case when coalesce(v_contacted, 0) = 0 then 0 else round((v_responded::numeric / v_contacted) * 100, 1) end,
    'attendance_rate', case when coalesce(v_interviews_scheduled, 0) = 0 then 0 else round((v_interviews_done::numeric / v_interviews_scheduled) * 100, 1) end,
    'no_show_rate', case when coalesce(v_interviews_scheduled, 0) = 0 then 0 else round((v_no_shows::numeric / v_interviews_scheduled) * 100, 1) end,
    'hire_rate', case when coalesce(v_applications, 0) = 0 then 0 else round((v_hired::numeric / v_applications) * 100, 1) end,
    'avg_coverage_days', v_avg_coverage
  );
end;
$$;


ALTER FUNCTION "public"."get_recruitment_kpis"("p_date_from" "date", "p_date_to" "date", "p_position" "text", "p_area" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recruitment_origin_for_profile"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_origin public.recruitment_employee_origins;
begin
  if not public.can_read_employee_expedientes() and not public.can_manage_recruitment() then
    raise exception 'No tienes permiso.';
  end if;

  select * into v_origin from public.recruitment_employee_origins where profile_id = p_profile_id;
  if v_origin.profile_id is null then
    return null;
  end if;

  return jsonb_build_object(
    'origin', to_jsonb(v_origin),
    'candidate', (
      select to_jsonb(c) from public.recruitment_candidates c where c.id = v_origin.candidate_id
    ),
    'vacancy', (
      select to_jsonb(v) from public.recruitment_vacancies v where v.id = v_origin.vacancy_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_recruitment_origin_for_profile"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recruitment_phase2_dashboard"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from date := coalesce(p_date_from, ((now() at time zone 'America/Guatemala')::date - interval '90 days')::date);
  v_to date := coalesce(p_date_to, (now() at time zone 'America/Guatemala')::date);
  v_converted integer := 0;
  v_onboarding_open integer := 0;
  v_onboarding_done integer := 0;
  v_onboarding_overdue integer := 0;
  v_hired_without_expediente integer := 0;
  v_eligible_30 integer := 0;
  v_active_30 integer := 0;
  v_eligible_60 integer := 0;
  v_active_60 integer := 0;
  v_eligible_90 integer := 0;
  v_active_90 integer := 0;
  v_early_exits integer := 0;
  v_best_source text;
  v_worst_position text;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso.';
  end if;

  select count(*) into v_converted
  from public.recruitment_candidates c
  where c.profile_id is not null
    and coalesce(c.converted_at::date, c.hire_date) between v_from and v_to;

  select count(*) into v_onboarding_open
  from public.recruitment_onboarding_checklists o
  where o.status = 'active';

  select count(*) into v_onboarding_done
  from public.recruitment_onboarding_checklists o
  where o.status = 'completed';

  select count(*) into v_onboarding_overdue
  from public.recruitment_onboarding_checklists o
  where o.status = 'overdue'
     or (o.status = 'active' and o.due_date is not null and o.due_date < current_date);

  select count(*) into v_hired_without_expediente
  from public.recruitment_candidates c
  where c.pipeline_status = 'hired'
    and c.profile_id is null;

  select count(*) into v_eligible_30
  from public.recruitment_candidates c
  where c.profile_id is not null
    and c.hire_date is not null
    and c.hire_date <= current_date - 30;

  select count(*) into v_active_30
  from public.recruitment_retention_reviews r
  join public.recruitment_candidates c on c.id = r.candidate_id
  where r.review_day = 30 and r.active_status = 'yes';

  select count(*) into v_eligible_60
  from public.recruitment_candidates c
  where c.profile_id is not null and c.hire_date <= current_date - 60;

  select count(*) into v_active_60
  from public.recruitment_retention_reviews r
  where r.review_day = 60 and r.active_status = 'yes';

  select count(*) into v_eligible_90
  from public.recruitment_candidates c
  where c.profile_id is not null and c.hire_date <= current_date - 90;

  select count(*) into v_active_90
  from public.recruitment_retention_reviews r
  where r.review_day = 90 and r.active_status = 'yes';

  select count(*) into v_early_exits
  from public.recruitment_retention_reviews r
  where r.active_status = 'no';

  select c.source into v_best_source
  from public.recruitment_candidates c
  join public.recruitment_retention_reviews r on r.candidate_id = c.id and r.review_day = 90 and r.active_status = 'yes'
  group by c.source
  order by count(*) desc
  limit 1;

  select c.final_position into v_worst_position
  from public.recruitment_candidates c
  join public.recruitment_retention_reviews r on r.candidate_id = c.id and r.active_status = 'no'
  group by c.final_position
  order by count(*) desc
  limit 1;

  return jsonb_build_object(
    'date_from', v_from,
    'date_to', v_to,
    'converted_to_employees', coalesce(v_converted, 0),
    'onboardings_open', coalesce(v_onboarding_open, 0),
    'onboardings_completed', coalesce(v_onboarding_done, 0),
    'onboardings_overdue', coalesce(v_onboarding_overdue, 0),
    'hired_pending_conversion', coalesce(v_hired_without_expediente, 0),
    'retention_30_eligible', coalesce(v_eligible_30, 0),
    'retention_30_active', coalesce(v_active_30, 0),
    'retention_30_rate', case when coalesce(v_eligible_30, 0) = 0 then 0 else round((v_active_30::numeric / v_eligible_30) * 100, 1) end,
    'retention_60_eligible', coalesce(v_eligible_60, 0),
    'retention_60_active', coalesce(v_active_60, 0),
    'retention_60_rate', case when coalesce(v_eligible_60, 0) = 0 then 0 else round((v_active_60::numeric / v_eligible_60) * 100, 1) end,
    'retention_90_eligible', coalesce(v_eligible_90, 0),
    'retention_90_active', coalesce(v_active_90, 0),
    'retention_90_rate', case when coalesce(v_eligible_90, 0) = 0 then 0 else round((v_active_90::numeric / v_eligible_90) * 100, 1) end,
    'early_exits', coalesce(v_early_exits, 0),
    'best_retention_source', v_best_source,
    'highest_early_turnover_position', v_worst_position
  );
end;
$$;


ALTER FUNCTION "public"."get_recruitment_phase2_dashboard"("p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recruitment_weekly_report"("p_weeks" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para consultar reportes de reclutamiento.';
  end if;

  select coalesce(jsonb_agg(row order by row ->> 'week_start' desc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'week_start', w.week_start,
      'week_label', to_char(w.week_start, 'DD Mon') || ' - ' || to_char(w.week_start + 6, 'DD Mon YYYY'),
      'open_vacancies', (
        select count(*) from public.recruitment_vacancies v
        where v.status in ('open', 'recruiting', 'interviewing')
          and v.request_date <= w.week_end
          and (v.filled_at is null or v.filled_at::date > w.week_end)
      ),
      'applications_received', (
        select count(*) from public.recruitment_candidates c
        where c.applied_at between w.week_start and w.week_end
      ),
      'contacted', (
        select count(distinct ct.candidate_id)
        from public.recruitment_candidate_contacts ct
        where ct.contacted_at::date between w.week_start and w.week_end
      ),
      'responded', (
        select count(*)
        from public.recruitment_candidate_contacts ct
        where ct.contacted_at::date between w.week_start and w.week_end
          and ct.result in ('answered', 'callback_requested')
      ),
      'interviews_scheduled', (
        select count(*) from public.recruitment_interviews i
        where i.scheduled_date between w.week_start and w.week_end
      ),
      'interviews_completed', (
        select count(*) from public.recruitment_interviews i
        where i.scheduled_date between w.week_start and w.week_end and i.result = 'attended'
      ),
      'no_shows', (
        select count(*) from public.recruitment_interviews i
        where i.scheduled_date between w.week_start and w.week_end and i.result = 'no_show'
      ),
      'hired', (
        select count(*) from public.recruitment_candidates c
        where c.pipeline_status = 'hired'
          and coalesce(c.hired_at::date, c.applied_at) between w.week_start and w.week_end
      ),
      'pending_positions', (
        select coalesce(sum(public.recruitment_vacancy_pending(v)), 0)
        from public.recruitment_vacancies v
        where v.status in ('open', 'recruiting', 'interviewing')
      )
    ) as row
    from (
      select
        ((now() at time zone 'America/Guatemala')::date - (n * 7)) - extract(dow from ((now() at time zone 'America/Guatemala')::date - (n * 7)))::integer + 1 as week_start,
        ((now() at time zone 'America/Guatemala')::date - (n * 7)) - extract(dow from ((now() at time zone 'America/Guatemala')::date - (n * 7)))::integer + 7 as week_end
      from generate_series(0, greatest(coalesce(p_weeks, 8), 1) - 1) as n
    ) w
  ) sub;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."get_recruitment_weekly_report"("p_weeks" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_requisition_low_stock_impacts"("p_requisition_id" "uuid", "p_record_suggested" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return public.get_requisition_purchase_suggestions(p_requisition_id, p_record_suggested);
end;
$$;


ALTER FUNCTION "public"."get_requisition_low_stock_impacts"("p_requisition_id" "uuid", "p_record_suggested" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_requisition_purchase_suggestions"("p_requisition_id" "uuid", "p_record_suggested" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requisition public.requisitions;
  suggestions jsonb := '[]'::jsonb;
  suggestion_map jsonb := '{}'::jsonb;
  impact_row record;
  shortage_row record;
  item_key text;
  existing jsonb;
  merged jsonb;
  low_stock_qty numeric;
  shortage_qty numeric;
  final_qty numeric;
  final_source text;
begin
  if not public.can_operate_purchase_orders() then
    raise exception 'No tienes permiso para consultar sugerencias de compra.';
  end if;

  select * into requisition
  from public.requisitions
  where id = p_requisition_id;

  if requisition.id is null then
    raise exception 'Requisicion no encontrada.';
  end if;

  if requisition.status not in ('completed', 'partially_fulfilled', 'pending_fulfillment') then
    raise exception 'La requisicion debe estar surtida para evaluar sugerencias de compra.';
  end if;

  if coalesce(requisition.is_test, false) then
    return '[]'::jsonb;
  end if;

  for shortage_row in
    select
      ri.id as requisition_item_id,
      ri.item_id,
      coalesce(ri.item_name, ii.name) as item_name,
      ii.sku,
      coalesce(ri.pending_quantity, 0) as pending_quantity,
      coalesce(ri.requested_unit, ri.unit, ii.base_unit) as unit,
      coalesce(ii.purchase_unit, ri.unit) as purchase_unit,
      ii.supplier,
      coalesce(ii.conversion_factor, ri.conversion_factor, 1) as conversion_factor,
      coalesce(ii.purchase_price, ii.cost_per_base_unit, 0) as purchase_price,
      coalesce(ri.shortage_reason, '') as shortage_reason
    from public.requisition_items ri
    join public.inventory_items ii on ii.id = ri.item_id
    where ri.requisition_id = p_requisition_id
      and coalesce(ri.pending_quantity, 0) > 0
  loop
    item_key := shortage_row.item_id::text;
    shortage_qty := ceil(
      greatest(shortage_row.pending_quantity, 0)
      / greatest(coalesce(nullif(shortage_row.conversion_factor, 0), 1), 0.0001)
    );
    merged := jsonb_build_object(
      'requisition_item_id', shortage_row.requisition_item_id,
      'item_id', shortage_row.item_id,
      'item_name', shortage_row.item_name,
      'sku', shortage_row.sku,
      'pending_quantity', shortage_row.pending_quantity,
      'stock_after', null,
      'minimum_stock', null,
      'unit', shortage_row.unit,
      'purchase_unit', coalesce(nullif(trim(shortage_row.purchase_unit), ''), shortage_row.unit),
      'supplier', shortage_row.supplier,
      'conversion_factor', shortage_row.conversion_factor,
      'purchase_price', shortage_row.purchase_price,
      'shortage_reason', shortage_row.shortage_reason,
      'suggested_quantity', greatest(shortage_qty, 1),
      'source', 'requisition_shortage'
    );
    suggestion_map := suggestion_map || jsonb_build_object(item_key, merged);
  end loop;

  for impact_row in
    select
      ri.id as requisition_item_id,
      ri.item_id,
      coalesce(ri.item_name, ii.name) as item_name,
      ii.sku,
      coalesce(ai.quantity, 0) as stock_after,
      coalesce(ai.minimum_quantity, 0) as minimum_stock,
      coalesce(ii.base_unit, ri.unit) as unit,
      ii.purchase_unit,
      ii.supplier,
      coalesce(ii.conversion_factor, 1) as conversion_factor,
      coalesce(ii.purchase_price, ii.cost_per_base_unit, 0) as purchase_price,
      coalesce(
        ri.converted_delivered_quantity,
        ri.converted_approved_quantity,
        ri.converted_requested_quantity,
        ri.delivered_quantity,
        ri.approved_quantity,
        ri.requested_quantity,
        0
      ) as moved_quantity
    from public.requisition_items ri
    join public.inventory_items ii on ii.id = ri.item_id
    left join public.area_inventory ai
      on ai.item_id = ri.item_id
     and ai.area_id = requisition.from_area_id
    where ri.requisition_id = p_requisition_id
      and coalesce(ri.delivered_quantity, ri.approved_quantity, 0) > 0
      and (
        coalesce(ai.quantity, 0) <= 0
        or (
          coalesce(ai.minimum_quantity, 0) > 0
          and coalesce(ai.quantity, 0) <= coalesce(ai.minimum_quantity, 0)
        )
      )
  loop
    item_key := impact_row.item_id::text;
    low_stock_qty := public.suggest_purchase_quantity(
      impact_row.stock_after,
      impact_row.minimum_stock,
      impact_row.moved_quantity,
      impact_row.conversion_factor
    );
    existing := suggestion_map -> item_key;

    if existing is not null then
      final_qty := greatest(
        coalesce((existing ->> 'suggested_quantity')::numeric, 0),
        low_stock_qty
      );
      final_source := 'both';
      merged := existing
        || jsonb_build_object(
          'stock_after', impact_row.stock_after,
          'minimum_stock', impact_row.minimum_stock,
          'moved_quantity', impact_row.moved_quantity,
          'suggested_quantity', final_qty,
          'source', final_source
        );
    else
      merged := jsonb_build_object(
        'requisition_item_id', impact_row.requisition_item_id,
        'item_id', impact_row.item_id,
        'item_name', impact_row.item_name,
        'sku', impact_row.sku,
        'pending_quantity', 0,
        'stock_after', impact_row.stock_after,
        'minimum_stock', impact_row.minimum_stock,
        'unit', impact_row.unit,
        'purchase_unit', coalesce(nullif(trim(impact_row.purchase_unit), ''), impact_row.unit),
        'supplier', impact_row.supplier,
        'conversion_factor', impact_row.conversion_factor,
        'purchase_price', impact_row.purchase_price,
        'moved_quantity', impact_row.moved_quantity,
        'suggested_quantity', low_stock_qty,
        'source', 'low_stock'
      );
    end if;

    suggestion_map := suggestion_map || jsonb_build_object(item_key, merged);
  end loop;

  select coalesce(jsonb_agg(value), '[]'::jsonb)
  into suggestions
  from jsonb_each(suggestion_map);

  if p_record_suggested then
    for impact_row in
      select key, value
      from jsonb_each(suggestion_map)
    loop
      insert into public.requisition_low_stock_suggestion_logs (
        requisition_id,
        requisition_item_id,
        item_id,
        pending_quantity,
        stock_after,
        minimum_stock,
        suggested_quantity,
        user_id,
        action,
        source
      ) values (
        p_requisition_id,
        nullif(impact_row.value ->> 'requisition_item_id', '')::uuid,
        nullif(impact_row.value ->> 'item_id', '')::uuid,
        nullif(impact_row.value ->> 'pending_quantity', '')::numeric,
        nullif(impact_row.value ->> 'stock_after', '')::numeric,
        nullif(impact_row.value ->> 'minimum_stock', '')::numeric,
        coalesce((impact_row.value ->> 'suggested_quantity')::numeric, 1),
        auth.uid(),
        'suggested',
        coalesce(nullif(impact_row.value ->> 'source', ''), 'low_stock')
      );
    end loop;
  end if;

  return coalesce(suggestions, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_requisition_purchase_suggestions"("p_requisition_id" "uuid", "p_record_suggested" boolean) OWNER TO "postgres";


