    and is_active = true
  limit 1;
$$;


ALTER FUNCTION "public"."get_role_key_from_name"("p_role_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_attendance_details"("p_week_start" "date") RETURNS TABLE("schedule_id" "uuid", "employee_id" "uuid", "employee_name" "text", "role" "text", "area" "text", "shift_date" "date", "shift_type" "text", "is_work_day" boolean, "scheduled_start" time without time zone, "actual_start" timestamp with time zone, "meal_out" timestamp with time zone, "meal_back" timestamp with time zone, "meal_minutes" integer, "scheduled_end" time without time zone, "actual_end" timestamp with time zone, "scheduled_hours" numeric, "actual_hours" numeric, "late_minutes" integer, "early_departure_minutes" integer, "overtime_hours" numeric, "attendance_status" "text", "observations" "text", "pending_extra_hours" numeric, "approved_extra_hours" numeric, "entrance_classification" "text", "entrance_approval_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with schedule_rows as (
    select distinct on (s.id)
      s.*,
      p.full_name,
      p.username,
      p.role,
      case
        when s.is_work_day and s.start_time is not null then
          ((s.shift_date + s.start_time) at time zone 'America/Guatemala')
      end as shift_start_ts,
      case
        when s.is_work_day and s.end_time is not null then
          (
            (s.shift_date + case when s.end_time <= s.start_time then 1 else 0 end) + s.end_time
          ) at time zone 'America/Guatemala'
      end as shift_end_ts
    from public.employee_schedules s
    join public.profiles p on p.id = s.employee_id
    where s.shift_date between p_week_start and p_week_start + 6
      and s.status in ('published', 'draft')
      and public.is_schedule_publisher()
    order by s.id, case s.status when 'published' then 0 else 1 end
  ),
  work_shifts as (
    select
      s.*,
      row_number() over (
        partition by s.employee_id, s.shift_date
        order by s.block_order, s.start_time nulls last, s.id
      )::integer as shift_rank,
      count(*) over (partition by s.employee_id, s.shift_date)::integer as shifts_on_day
    from schedule_rows s
    where s.is_work_day
  ),
  day_entrances as (
    select
      m.id,
      m.employee_id,
      m.marked_at,
      m.observation,
      m.classification,
      m.approval_status,
      coalesce(m.labor_date, (m.marked_at at time zone 'America/Guatemala')::date) as mark_date,
      row_number() over (
        partition by m.employee_id, coalesce(m.labor_date, (m.marked_at at time zone 'America/Guatemala')::date)
        order by m.marked_at
      )::integer as entrance_rank
    from public.attendance_marks m
    where m.mark_type = 'entrada'
  ),
  entrance_assignments as (
    select
      ws.id as schedule_id,
      coalesce(de_rank.marked_at, de_fallback.marked_at) as entrance_marked_at,
      coalesce(de_rank.observation, de_fallback.observation) as entrance_observation,
      coalesce(de_rank.classification, de_fallback.classification) as entrance_classification,
      coalesce(de_rank.approval_status, de_fallback.approval_status) as entrance_approval_status
    from work_shifts ws
    left join day_entrances de_rank
      on de_rank.employee_id = ws.employee_id
      and de_rank.mark_date = ws.shift_date
      and (
        (ws.shifts_on_day = 1 and de_rank.entrance_rank = 1)
        or (ws.shifts_on_day > 1 and de_rank.entrance_rank = ws.shift_rank)
      )
      and (
        ws.shift_start_ts is null
        or (
          de_rank.marked_at >= ws.shift_start_ts - interval '4 hours'
          and de_rank.marked_at <= coalesce(ws.shift_end_ts, ws.shift_start_ts) + interval '4 hours'
        )
      )
    left join lateral (
      select de.*
      from day_entrances de
      where de_rank.id is null
        and de.employee_id = ws.employee_id
        and de.mark_date = ws.shift_date
        and (
          ws.shift_start_ts is null
          or (
            de.marked_at >= ws.shift_start_ts - interval '4 hours'
            and de.marked_at <= coalesce(ws.shift_end_ts, ws.shift_start_ts) + interval '4 hours'
          )
        )
      order by
        abs(coalesce(extract(epoch from (de.marked_at - ws.shift_start_ts)), 0)),
        de.marked_at
      limit 1
    ) de_fallback on true
  ),
  exit_assignments as (
    select
      ws.id as schedule_id,
      exit_mark.marked_at as exit_marked_at,
      exit_mark.observation as exit_observation
    from work_shifts ws
    left join entrance_assignments ea on ea.schedule_id = ws.id
    left join lateral (
      select ea2.entrance_marked_at as next_entrance_at
      from work_shifts ws2
      join entrance_assignments ea2 on ea2.schedule_id = ws2.id
      where ws2.employee_id = ws.employee_id
        and ws2.shift_date = ws.shift_date
        and ws2.shift_rank = ws.shift_rank + 1
      limit 1
    ) next_shift on true
    left join lateral (
      select m.marked_at, m.observation
      from public.attendance_marks m
      where ea.entrance_marked_at is not null
        and m.employee_id = ws.employee_id
        and m.mark_type in ('salida_final', 'salida')
        and m.marked_at > ea.entrance_marked_at
        and (
          next_shift.next_entrance_at is null
          or m.marked_at < next_shift.next_entrance_at
        )
        and (
          ws.shift_end_ts is null
          or m.marked_at <= ws.shift_end_ts + interval '6 hours'
        )
      order by abs(extract(epoch from (m.marked_at - coalesce(ws.shift_end_ts, m.marked_at))))
      limit 1
    ) exit_mark on true
  ),
  computed as (
    select
      s.*,
      ea.entrance_marked_at,
      ea.entrance_observation,
      ea.entrance_classification,
      ea.entrance_approval_status,
      xa.exit_marked_at,
      xa.exit_observation,
      meal_out.marked_at as meal_out_marked_at,
      meal_back.marked_at as meal_back_marked_at,
      meal_back.duration_minutes as meal_back_duration_minutes,
      case when not s.is_work_day then 0 else greatest(0, coalesce(extract(epoch from (
        ea.entrance_marked_at at time zone 'America/Guatemala' - (s.shift_date + s.start_time)
      )) / 60, 0))::integer end as raw_late_minutes,
      public.get_attendance_late_grace_minutes() as grace_minutes,
      case
        when not s.is_work_day then 0
        when ea.entrance_marked_at is null or xa.exit_marked_at is null then 0
        else greatest(0, coalesce(extract(epoch from (xa.exit_marked_at - ea.entrance_marked_at)) / 3600, 0)
          - greatest(0, coalesce(extract(epoch from (meal_back.marked_at - meal_out.marked_at)) / 3600, 0)))::numeric(10,2)
      end as gross_work_hours
    from schedule_rows s
    left join entrance_assignments ea on ea.schedule_id = s.id
    left join exit_assignments xa on xa.schedule_id = s.id
    left join lateral (
      select m.*
      from public.attendance_marks m
      where s.is_work_day
        and ea.entrance_marked_at is not null
        and m.employee_id = s.employee_id
        and m.mark_type in ('salida_comida', 'bano_inicio')
        and m.marked_at > ea.entrance_marked_at
        and (xa.exit_marked_at is null or m.marked_at < xa.exit_marked_at)
      order by m.marked_at
      limit 1
    ) meal_out on true
    left join lateral (
      select m.*
      from public.attendance_marks m
      where s.is_work_day
        and meal_out.marked_at is not null
        and m.employee_id = s.employee_id
        and m.mark_type in ('regreso_comida', 'bano_regreso')
        and m.marked_at > meal_out.marked_at
        and (xa.exit_marked_at is null or m.marked_at < xa.exit_marked_at)
      order by m.marked_at
      limit 1
    ) meal_back on true
  )
  select
    c.id,
    c.employee_id,
    coalesce(c.full_name, c.username, 'Colaborador'),
    c.role,
    c.area,
    c.shift_date,
    coalesce(c.shift_type_id::text, c.shift_type),
    c.is_work_day,
    c.start_time,
    c.entrance_marked_at,
    c.meal_out_marked_at,
    c.meal_back_marked_at,
    greatest(0, coalesce(extract(epoch from (c.meal_back_marked_at - c.meal_out_marked_at)) / 60, c.meal_back_duration_minutes, 0))::integer,
    c.end_time,
    c.exit_marked_at,
    case when not c.is_work_day then 0 else greatest(0, extract(epoch from (
      (c.shift_date + c.end_time + case when c.end_time <= c.start_time then interval '1 day' else interval '0 day' end)
      - (c.shift_date + c.start_time)
    )) / 3600 - c.break_minutes / 60.0)::numeric(10,2) end,
    case
      when not c.is_work_day then 0
      when c.entrance_marked_at is null or c.exit_marked_at is null then 0
      when c.entrance_classification in ('no_schedule', 'rest_day_worked', 'out_of_schedule', 'pending_overtime')
        and coalesce(c.entrance_approval_status, 'pending') = 'pending' then 0
      when coalesce(c.entrance_approval_status, 'not_required') = 'rejected' then 0
      when c.entrance_classification in ('no_schedule', 'rest_day_worked', 'out_of_schedule', 'pending_overtime', 'authorized_overtime')
        and coalesce(c.entrance_approval_status, 'pending') = 'approved' then 0
      else c.gross_work_hours
    end,
    case
      when not c.is_work_day then 0
      when c.entrance_marked_at is null then 0
      when c.raw_late_minutes <= c.grace_minutes then 0
      else c.raw_late_minutes
    end,
    case when not c.is_work_day then 0 else greatest(0, coalesce(extract(epoch from (
      (c.shift_date + c.end_time + case when c.end_time <= c.start_time then interval '1 day' else interval '0 day' end)
      - (c.exit_marked_at at time zone 'America/Guatemala')
    )) / 60, 0))::integer end,
    case
      when not c.is_work_day then 0
      when c.exit_marked_at is null then 0
      when c.entrance_classification in ('no_schedule', 'rest_day_worked', 'out_of_schedule', 'pending_overtime', 'authorized_overtime') then 0
      else (
        greatest(0, extract(epoch from (
          (c.exit_marked_at at time zone 'America/Guatemala') -
          ((c.shift_date + c.end_time + case when c.end_time <= c.start_time then interval '1 day' else interval '0 day' end)
            + case when c.start_time < time '12:00' then interval '20 minutes' else interval '30 minutes' end)
        )) / 3600)
      )::numeric(10,2)
    end,
    case
      when c.shift_type = 'asueto' then 'asueto'
      when not c.is_work_day or c.shift_type = 'rest' then 'descanso'
      when c.entrance_classification in ('no_schedule', 'rest_day_worked', 'out_of_schedule', 'pending_overtime')
        and coalesce(c.entrance_approval_status, 'pending') = 'pending' then 'extra_pendiente'
      when c.entrance_classification = 'authorized_overtime'
        and coalesce(c.entrance_approval_status, 'approved') = 'approved' then 'horas_extra'
      when c.entrance_approval_status = 'rejected' then 'extra_rechazada'
      when c.shift_date > (now() at time zone 'America/Guatemala')::date then 'pendiente'
      when c.shift_date < (now() at time zone 'America/Guatemala')::date and c.entrance_marked_at is null then 'falta'
      when c.entrance_marked_at is not null and c.raw_late_minutes > c.grace_minutes then 'tarde'
      when c.entrance_marked_at is null or c.exit_marked_at is null then 'incompleto'
      when greatest(0, coalesce(extract(epoch from (
        (c.exit_marked_at at time zone 'America/Guatemala') -
        ((c.shift_date + c.end_time + case when c.end_time <= c.start_time then interval '1 day' else interval '0 day' end)
          + case when c.start_time < time '12:00' then interval '20 minutes' else interval '30 minutes' end)
      )) / 60, 0)) > 0 then 'horas_extra'
      else 'completo'
    end,
    nullif(
      concat_ws(
        ' / ',
        public.sanitize_attendance_observation(c.day_notes),
        public.sanitize_attendance_observation(c.notes),
        public.sanitize_attendance_observation(c.entrance_observation),
        public.sanitize_attendance_observation(c.exit_observation)
      ),
      ''
    ),
    case
      when c.entrance_classification in ('no_schedule', 'rest_day_worked', 'out_of_schedule', 'pending_overtime')
        and coalesce(c.entrance_approval_status, 'pending') = 'pending' then c.gross_work_hours
      else 0
    end,
    case
      when c.entrance_classification in ('no_schedule', 'rest_day_worked', 'out_of_schedule', 'pending_overtime', 'authorized_overtime')
        and coalesce(c.entrance_approval_status, 'pending') = 'approved' then c.gross_work_hours
      else 0
    end,
    c.entrance_classification,
    c.entrance_approval_status
  from computed c
  order by c.shift_date, c.block_order, c.start_time nulls last, c.full_name;
$$;


ALTER FUNCTION "public"."get_schedule_attendance_details"("p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_attendance_summary"("p_week_start" "date") RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "area" "text", "scheduled_hours" numeric, "actual_hours" numeric, "regular_hours" numeric, "overtime_hours" numeric, "late_minutes" integer, "absences" integer, "estimated_pay" numeric, "payroll_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with details as (
    select * from public.get_schedule_attendance_details(p_week_start)
  )
  select
    p.id,
    coalesce(p.full_name, p.username, 'Colaborador'),
    max(d.area),
    coalesce(sum(d.scheduled_hours), 0)::numeric(10,2),
    coalesce(sum(d.actual_hours), 0)::numeric(10,2),
    least(coalesce(sum(d.actual_hours), 0), coalesce(sum(d.scheduled_hours), 0))::numeric(10,2),
    coalesce(sum(d.overtime_hours), 0)::numeric(10,2),
    coalesce(sum(d.late_minutes), 0)::integer,
    coalesce(sum(case when d.attendance_status = 'falta' then 1 else 0 end), 0)::integer,
    (coalesce(sum(d.actual_hours), 0) * coalesce(p.hourly_rate, 0))::numeric(12,2),
    coalesce(ps.status, 'pending')
  from details d
  join public.profiles p on p.id = d.employee_id
  left join public.payroll_summaries ps on ps.employee_id = p.id and ps.week_start = p_week_start
  group by p.id, p.full_name, p.username, p.hourly_rate, ps.status;
$$;


ALTER FUNCTION "public"."get_schedule_attendance_summary"("p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_security_login_attempts"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_email" "text" DEFAULT NULL::"text", "p_success" boolean DEFAULT NULL::boolean) RETURNS TABLE("id" "uuid", "email_attempted" "text", "user_id" "uuid", "ip_address" "text", "user_agent" "text", "success" boolean, "failure_reason" "text", "captcha_required" boolean, "captcha_passed" boolean, "profile_role" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.is_login_security_admin() then
    raise exception 'No tienes permiso para ver intentos de login.';
  end if;

  return query
  select
    attempt.id,
    attempt.email_attempted,
    attempt.user_id,
    attempt.ip_address,
    attempt.user_agent,
    attempt.success,
    attempt.failure_reason,
    attempt.captcha_required,
    attempt.captcha_passed,
    coalesce(attempt.metadata ->> 'profile_role', profile.role) as profile_role,
    attempt.created_at
  from public.security_login_attempts attempt
  left join public.profiles profile on profile.id = attempt.user_id
  where (p_email is null or lower(attempt.email_attempted) like '%' || lower(trim(p_email)) || '%')
    and (p_success is null or attempt.success = p_success)
  order by attempt.created_at desc
  limit greatest(coalesce(p_limit, 100), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."get_security_login_attempts"("p_limit" integer, "p_offset" integer, "p_email" "text", "p_success" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_station_cash_context"("p_operator_session_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_register public.cash_registers;
  v_session public.cash_sessions;
  v_movements jsonb := '[]'::jsonb;
  v_recent jsonb := '[]'::jsonb;
  v_cash_register_id uuid;
  v_operator_id uuid;
begin
  v_ctx := public.resolve_station_cash_operator_context(p_operator_session_token, false);
  v_cash_register_id := (v_ctx ->> 'cash_register_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;

  select * into v_register from public.cash_registers where id = v_cash_register_id;

  select * into v_session
  from public.cash_sessions
  where cash_register_id = v_cash_register_id and status = 'open'
  order by opened_at desc
  limit 1;

  if v_session.id is not null then
    select coalesce(jsonb_agg(row_to_json(m)::jsonb order by m.created_at desc), '[]'::jsonb)
    into v_movements
    from (
      select cm.*,
        jsonb_build_object(
          'full_name', pr.full_name,
          'username', pr.username
        ) as creator
      from public.cash_movements cm
      left join public.profiles pr on pr.id = cm.created_by
      where cm.cash_session_id = v_session.id
      order by cm.created_at desc
      limit 200
    ) m;
  end if;

  select coalesce(jsonb_agg(row_to_json(s)::jsonb order by s.opened_at desc), '[]'::jsonb)
  into v_recent
  from (
    select cs.*,
      jsonb_build_object('name', cr.name) as register,
      jsonb_build_object('full_name', op.full_name, 'username', op.username) as opener
    from public.cash_sessions cs
    join public.cash_registers cr on cr.id = cs.cash_register_id
    left join public.profiles op on op.id = cs.opened_by
    where cs.cash_register_id = v_cash_register_id and cs.status <> 'open'
    order by cs.opened_at desc
    limit 6
  ) s;

  return v_ctx || jsonb_build_object(
    'register', jsonb_build_object('id', v_register.id, 'name', v_register.name, 'location', v_register.location),
    'open_session', case
      when v_session.id is null then null
      else to_jsonb(v_session) || jsonb_build_object(
        'opener', (
          select jsonb_build_object('full_name', p.full_name, 'username', p.username)
          from public.profiles p where p.id = v_session.opened_by
        )
      )
    end,
    'can_close_session', case
      when v_session.id is null then false
      when public.station_cash_is_supervisor(v_operator_id) then true
      else v_session.opened_by = v_operator_id
    end,
    'movements', v_movements,
    'recent_closed_sessions', v_recent
  );
end;
$$;


ALTER FUNCTION "public"."get_station_cash_context"("p_operator_session_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_station_pos_catalog"("p_operator_session_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_products jsonb;
begin
  if auth.uid() is null then
    raise exception 'Operacion no permitida.';
  end if;

  perform public.resolve_station_pos_operator_context(p_operator_session_token, false);

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', p.id,
      'name', p.name,
      'description', coalesce(p.description, ''),
      'price', p.price,
      'category_id', p.category_id,
      'category_name', p.category_name,
      'recipe_id', p.recipe_id,
      'production_area_id', p.production_area_id,
      'production_area_name', coalesce(a.name, p.production_area_id),
      'production_ready', p.production_ready,
      'product_type', p.product_type,
      'is_test_item', p.is_test_item,
      'allow_kitchen_notes', p.allow_kitchen_notes,
      'sort_order', p.sort_order,
      'image_url', case
        when p.image_url is not null
          and btrim(p.image_url) <> ''
          and p.image_url not like 'data:%'
        then p.image_url
        else null
      end,
      'variants', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'id', v.id,
            'name', v.name,
            'size', v.size,
            'price', v.price,
            'recipe_id', v.recipe_id,
            'production_area_id', v.production_area_id,
            'is_active', v.is_active,
            'sort_order', v.sort_order
          )
          order by v.sort_order, v.name
        ), '[]'::jsonb)
        from public.pos_product_variants v
        where v.product_id = p.id and v.is_active = true
      ),
      'modifiers', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'id', m.id,
            'name', m.name,
            'modifier_type', m.modifier_type,
            'price_delta', m.price_delta,
            'sort_order', m.sort_order
          )
          order by m.sort_order, m.name
        ), '[]'::jsonb)
        from public.pos_product_modifiers m
        where m.product_id = p.id and m.is_active = true
      ),
      'option_groups', (
        select coalesce(jsonb_agg(
          jsonb_build_object(
            'id', g.id,
            'name', g.name,
            'required', g.required,
            'selection_mode', g.selection_mode,
            'min_selections', g.min_selections,
            'max_selections', g.max_selections,
            'sort_order', g.sort_order,
            'choices', (
              select coalesce(jsonb_agg(
                jsonb_build_object(
                  'id', c.id,
                  'name', c.name,
                  'price_mode', c.price_mode,
                  'price', c.price,
                  'recipe_id', c.recipe_id,
                  'sort_order', c.sort_order
                )
                order by c.sort_order, c.name
              ), '[]'::jsonb)
              from public.pos_option_choices c
              where c.group_id = g.id and c.is_active = true and trim(c.name) <> ''
            )
          )
          order by g.sort_order, g.name
        ), '[]'::jsonb)
        from public.pos_option_groups g
        where g.product_id = p.id and g.is_active = true
      )
    )
    order by p.sort_order, p.name
  ), '[]'::jsonb)
  into v_products
  from public.pos_products p
  left join public.areas a on a.id = p.production_area_id
  where p.active = true;

  return jsonb_build_object('products', v_products);
end;
$$;


