CREATE OR REPLACE FUNCTION "public"."get_station_pos_order_events"("p_operator_session_token" "text", "p_order_id" "uuid", "p_limit" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_lim integer := least(greatest(coalesce(p_limit, 40), 1), 100);
  v_events jsonb;
  v_order public.pos_orders;
begin
  if auth.uid() is null then
    raise exception 'Operacion no permitida.';
  end if;

  perform public.resolve_station_pos_operator_context(p_operator_session_token, false);

  select * into v_order from public.pos_orders where id = p_order_id;
  if v_order.id is null then
    raise exception 'La orden POS no existe.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', e.id,
      'order_id', e.order_id,
      'event_type', e.event_type,
      'description', e.description,
      'created_at', e.created_at,
      'created_by', e.created_by
    )
    order by e.created_at desc
  ), '[]'::jsonb)
  into v_events
  from (
    select e.*
    from public.pos_order_events e
    where e.order_id = p_order_id
    order by e.created_at desc
    limit v_lim
  ) e;

  return jsonb_build_object('order_id', p_order_id, 'events', v_events);
end;
$$;


ALTER FUNCTION "public"."get_station_pos_order_events"("p_operator_session_token" "text", "p_order_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_station_pos_table_events"("p_operator_session_token" "text", "p_table_id" "text", "p_limit" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_table_id text;
  v_events jsonb;
  v_lim integer := least(greatest(coalesce(p_limit, 40), 1), 100);
begin
  if auth.uid() is null then
    raise exception 'Operacion no permitida.';
  end if;

  perform public.resolve_station_pos_operator_context(p_operator_session_token, false);

  v_table_id := nullif(trim(p_table_id), '');
  if v_table_id is null then
    raise exception 'Table id is required.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', e.id,
      'order_id', e.order_id,
      'event_type', e.event_type,
      'description', e.description,
      'created_at', e.created_at,
      'created_by', e.created_by
    )
    order by e.created_at desc
  ), '[]'::jsonb)
  into v_events
  from (
    select e.*
    from public.pos_order_events e
    join public.pos_orders o on o.id = e.order_id
    where o.table_id = v_table_id
    order by e.created_at desc
    limit v_lim
  ) e;

  return jsonb_build_object('table_id', v_table_id, 'events', v_events);
end;
$$;


