CREATE OR REPLACE FUNCTION "public"."get_task_labels_catalog"("p_area_id" "text" DEFAULT NULL::"text", "p_include_archived" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', l.id,
      'name', l.name,
      'color_key', l.color_key,
      'description', l.description,
      'scope', l.scope,
      'area_id', l.area_id,
      'area_name', (select a.name from public.areas a where a.id = l.area_id)
    )
    order by l.scope, l.name
  ), '[]'::jsonb)
  into v_rows
  from public.task_labels l
  where l.deleted_at is null
    and (p_include_archived or l.archived_at is null)
    and (
      l.scope = 'global'
      or (l.scope = 'area' and (p_area_id is null or l.area_id = p_area_id))
    );

  return jsonb_build_object(
    'labels', v_rows,
    'can_administer', public.can_administer_task_labels()
  );
end;
$$;


ALTER FUNCTION "public"."get_task_labels_catalog"("p_area_id" "text", "p_include_archived" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_task_next_work_step"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'step_id', s.id,
    'text', s.text,
    'list_title', sl.title,
    'list_id', sl.id
  )
  from public.task_steps s
  join public.task_step_lists sl on sl.id = s.step_list_id and sl.deleted_at is null
  where s.task_id = p_task_id
    and s.deleted_at is null
    and not s.completed
    and (
      s.depends_on_step_id is null
      or exists (
        select 1 from public.task_steps dep
        where dep.id = s.depends_on_step_id
          and dep.deleted_at is null
          and dep.completed
      )
    )
  order by sl.sort_position asc, s.sort_position asc
  limit 1;
$$;


ALTER FUNCTION "public"."get_task_next_work_step"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_task_work_card_summary"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with stats as (
    select
      count(*) filter (where s.deleted_at is null)::int as total,
      count(*) filter (where s.deleted_at is null and s.completed)::int as done
    from public.task_steps s
    where s.task_id = p_task_id
  ),
  next_step as (
    select jsonb_build_object(
      'step_id', s.id,
      'text', s.text,
      'list_title', sl.title,
      'list_id', sl.id
    ) as payload
    from public.task_steps s
    join public.task_step_lists sl on sl.id = s.step_list_id and sl.deleted_at is null
    where s.task_id = p_task_id
      and s.deleted_at is null
      and not s.completed
      and (
        s.depends_on_step_id is null
        or exists (
          select 1 from public.task_steps dep
          where dep.id = s.depends_on_step_id
            and dep.deleted_at is null
            and dep.completed
        )
      )
    order by sl.sort_position asc, s.sort_position asc
    limit 1
  )
  select jsonb_build_object(
    'steps_progress', case when stats.total > 0 then jsonb_build_object(
      'total', stats.total,
      'done', stats.done
    ) else null end,
    'work_summary', (select payload from next_step)
  )
  from stats;
$$;


ALTER FUNCTION "public"."get_task_work_card_summary"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_task_work_plan_progress"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when count(*) filter (where s.deleted_at is null) = 0 then null
    else jsonb_build_object(
      'total', count(*) filter (where s.deleted_at is null)::int,
      'done', count(*) filter (where s.deleted_at is null and s.completed)::int
    )
  end
  from public.task_steps s
  where s.task_id = p_task_id;
$$;


ALTER FUNCTION "public"."get_task_work_plan_progress"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_waiter_sales_ranking"("p_month" "date" DEFAULT CURRENT_DATE, "p_public" boolean DEFAULT false) RETURNS TABLE("profile_id" "uuid", "full_name" "text", "display_name" "text", "total_sales" numeric, "order_count" integer, "average_ticket" numeric, "rank_position" integer, "relative_percent" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  month_start date := date_trunc('month', coalesce(p_month, current_date))::date;
  month_end timestamptz := (month_start + interval '1 month')::timestamptz;
  can_money boolean;
begin
  can_money := public.can_read_sales_goals();
  if p_public then
    if not public.can_read_public_goal_widgets() then
      raise exception 'No tienes permiso para ver ranking.';
    end if;
  elsif not can_money then
    raise exception 'No tienes permiso para ver ranking gerencial.';
  end if;

  return query
  with sales as (
    select
      coalesce(o.owner_profile_id, o.waiter_id) as seller_id,
      coalesce(max(p.full_name), max(o.waiter_name), 'Sin nombre') as seller_name,
      sum(o.total)::numeric(12,2) as seller_sales,
      count(*)::integer as seller_orders
    from public.pos_orders o
    left join public.profiles p on p.id = coalesce(o.owner_profile_id, o.waiter_id)
    where o.status = 'paid'
      and coalesce(o.paid_at, o.created_at) >= month_start::timestamptz
      and coalesce(o.paid_at, o.created_at) < month_end
      and coalesce(o.owner_profile_id, o.waiter_id) is not null
    group by coalesce(o.owner_profile_id, o.waiter_id)
  ),
  ranked as (
    select
      sales.*,
      dense_rank() over (order by sales.seller_sales desc) as seller_rank,
      max(sales.seller_sales) over () as top_sales
    from sales
  )
  select
    ranked.seller_id,
    case when p_public then null::text else ranked.seller_name end,
    ranked.seller_name,
    case when p_public then null::numeric else ranked.seller_sales end,
    ranked.seller_orders,
    case when p_public then null::numeric else round(ranked.seller_sales / nullif(ranked.seller_orders, 0), 2) end,
    ranked.seller_rank::integer,
    round((ranked.seller_sales / nullif(ranked.top_sales, 0)) * 100, 2)
  from ranked
  order by ranked.seller_rank, ranked.seller_name;
end;
$$;


ALTER FUNCTION "public"."get_waiter_sales_ranking"("p_month" "date", "p_public" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_warehouse_area_id"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select a.id
      from public.areas a
      where a.active = true
        and (
          a.id = 'almacen'
          or lower(trim(a.name)) in ('almacen', 'almacén')
        )
      order by case when a.id = 'almacen' then 0 else 1 end
      limit 1
    ),
    (
      select a.id
      from public.areas a
      where a.active = true
        and a.type = 'principal'
        and coalesce(a.can_request_inventory, false) = false
      order by a.sort_order, a.name
      limit 1
    )
  );
$$;


ALTER FUNCTION "public"."get_warehouse_area_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."goal_status_label"("p_progress" numeric, "p_days_remaining" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_progress >= 100 then 'Meta superada'
    when p_days_remaining <= 0 and p_progress < 100 then 'Atrasada'
    when p_progress >= 75 then 'En camino'
    when p_progress >= 45 then 'Riesgo'
    else 'Atrasada'
  end;
$$;


