CREATE OR REPLACE FUNCTION "public"."guard_pos_order_owner_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO '', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.owner_profile_id is distinct from old.owner_profile_id
       or new.waiter_id is distinct from old.waiter_id then
      raise exception 'POS_ORDER_OWNER_IMMUTABLE'
        using hint = 'Owner changes require authorized RPC (F0B).';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_pos_order_owner_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requested_role text := coalesce(nullif(new.raw_user_meta_data ->> 'role', ''), 'colaborador');
  initial_role text;
begin
  -- Privileged roles are never trusted from user-supplied signup metadata.
  -- Assign admin/gerente_general/rrhh/supervisor in Table Editor or a future server-only flow.
  initial_role := case
    when requested_role in (
      'cajero', 'mesero', 'cocinero', 'pizzero', 'barista', 'bartender',
      'repostero', 'panadero', 'colaborador'
    ) then requested_role
    else 'colaborador'
  end;

  insert into public.profiles (id, email, full_name, username, role)
  values (
    new.id,
    new.email,
    nullif(new.raw_user_meta_data ->> 'full_name', ''),
    nullif(new.raw_user_meta_data ->> 'username', ''),
    initial_role
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


