CREATE OR REPLACE FUNCTION "public"."hire_recruitment_candidate"("p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate public.recruitment_candidates;
  v_vacancy public.recruitment_vacancies;
  v_pending integer;
  v_suggest_close boolean := false;
  v_was_hired boolean := false;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para contratar candidatos.';
  end if;

  select * into v_candidate from public.recruitment_candidates where id = p_candidate_id for update;
  if v_candidate.id is null then
    raise exception 'Candidato no encontrado.';
  end if;

  if v_candidate.profile_id is not null then
    raise exception 'Este candidato ya fue convertido a colaborador.';
  end if;

  v_was_hired := v_candidate.pipeline_status = 'hired';

  if not v_was_hired then
    update public.recruitment_candidates
    set
      pipeline_status = 'hired',
      hired_at = coalesce(hired_at, now()),
      hired_by = coalesce(hired_by, auth.uid()),
      onboarding_status = case when onboarding_status = 'none' then 'pending_conversion' else onboarding_status end,
      updated_by = auth.uid()
    where id = p_candidate_id
    returning * into v_candidate;

    select * into v_vacancy from public.recruitment_vacancies where id = v_candidate.vacancy_id for update;
    update public.recruitment_vacancies
    set
      quantity_filled = least(quantity_filled + 1, quantity_required),
      updated_at = now(),
      filled_at = case when quantity_filled + 1 >= quantity_required then coalesce(filled_at, now()) else filled_at end,
      status = case when quantity_filled + 1 >= quantity_required then 'filled' else status end
    where id = v_vacancy.id
    returning * into v_vacancy;

    v_pending := public.recruitment_vacancy_pending(v_vacancy);
    v_suggest_close := v_pending = 0;

    if v_suggest_close then
      perform public.recruitment_notify(
        null, 'recursos_humanos', 'recruitment',
        'Vacante cubierta',
        'La vacante ' || coalesce(v_vacancy.position_title, '') || ' quedó cubierta.',
        'recruitment_vacancy', v_vacancy.id::text,
        '/hr?section=reclutamiento&tab=vacancies'
      );
    end if;

    perform public.recruitment_notify(
      null, 'recursos_humanos', 'recruitment',
      'Nueva contratación',
      'Candidato ' || v_candidate.full_name || ' marcado como contratado.',
      'recruitment_candidate', v_candidate.id::text,
      '/hr?section=reclutamiento&tab=pipeline&candidateId=' || v_candidate.id::text
    );
  end if;

  return jsonb_build_object(
    'candidate_id', v_candidate.id,
    'vacancy_id', v_candidate.vacancy_id,
    'onboarding_status', v_candidate.onboarding_status,
    'suggest_close_vacancy', v_suggest_close,
    'pending_conversion', v_candidate.onboarding_status = 'pending_conversion',
    'already_hired', v_was_hired
  );
end;
$$;


ALTER FUNCTION "public"."hire_recruitment_candidate"("p_candidate_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."inventory_duplicate_ignore" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "item_a_id" "uuid" NOT NULL,
    "item_b_id" "uuid" NOT NULL,
    "ignored_by" "uuid",
    "ignored_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reason" "text",
    CONSTRAINT "inventory_duplicate_ignore_check" CHECK (("item_a_id" <> "item_b_id"))
);


ALTER TABLE "public"."inventory_duplicate_ignore" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ignore_inventory_duplicate_pair"("p_item_a_id" "uuid", "p_item_b_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."inventory_duplicate_ignore"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  pair record;
  inserted public.inventory_duplicate_ignore;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para ignorar pares de duplicados.';
  end if;

  if p_item_a_id is null or p_item_b_id is null or p_item_a_id = p_item_b_id then
    raise exception 'Par de productos inválido.';
  end if;

  select * into pair from public.canonical_duplicate_pair(p_item_a_id, p_item_b_id);

  insert into public.inventory_duplicate_ignore (item_a_id, item_b_id, ignored_by, reason)
  values (pair.item_a_id, pair.item_b_id, auth.uid(), nullif(trim(p_reason), ''))
  on conflict (item_a_id, item_b_id) do update
    set ignored_by = auth.uid(),
        ignored_at = now(),
        reason = coalesce(excluded.reason, public.inventory_duplicate_ignore.reason)
  returning * into inserted;

  return inserted;
end;
$$;


ALTER FUNCTION "public"."ignore_inventory_duplicate_pair"("p_item_a_id" "uuid", "p_item_b_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ignore_low_stock_purchase_suggestion"("p_requisition_id" "uuid", "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  line jsonb;
begin
  if not public.can_operate_purchase_orders() then
    raise exception 'No tienes permiso para registrar sugerencias omitidas.';
  end if;

  if p_requisition_id is null then
    raise exception 'Requisicion invalida.';
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Debes indicar los productos omitidos.';
  end if;

  for line in select * from jsonb_array_elements(p_items)
  loop
    insert into public.requisition_low_stock_suggestion_logs (
      requisition_id,
      requisition_item_id,
      item_id,
      pending_quantity,
      stock_after,
      minimum_stock,
      suggested_quantity,
      user_id,
      action,
      notes,
      source
    ) values (
      p_requisition_id,
      nullif(line ->> 'requisition_item_id', '')::uuid,
      nullif(line ->> 'item_id', '')::uuid,
      nullif(line ->> 'pending_quantity', '')::numeric,
      nullif(line ->> 'stock_after', '')::numeric,
      nullif(line ->> 'minimum_stock', '')::numeric,
      coalesce((line ->> 'suggested_quantity')::numeric, (line ->> 'quantity')::numeric),
      auth.uid(),
      'ignored',
      p_notes,
      coalesce(nullif(line ->> 'source', ''), 'low_stock')
    );
  end loop;
end;
$$;


ALTER FUNCTION "public"."ignore_low_stock_purchase_suggestion"("p_requisition_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_area_inventory_stock"("p_item_id" "uuid", "p_area_id" "text", "p_quantity" numeric, "p_minimum_quantity" numeric, "p_unit" "text") RETURNS "public"."area_inventory"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  previous_value numeric;
  imported public.area_inventory;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para importar inventario.';
  end if;
  if p_quantity < 0 or p_minimum_quantity < 0 then
    raise exception 'Las cantidades no pueden ser negativas.';
  end if;

  insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
  values (p_item_id, p_area_id, 0, 0)
  on conflict (item_id, area_id) do nothing;

  select quantity into previous_value
  from public.area_inventory
  where item_id = p_item_id and area_id = p_area_id
  for update;

  update public.area_inventory
  set quantity = p_quantity, minimum_quantity = p_minimum_quantity
  where item_id = p_item_id and area_id = p_area_id
  returning * into imported;

  insert into public.inventory_movements (
    item_id, movement_type, to_area_id, quantity, unit, previous_quantity,
    new_quantity, source_type, notes, performed_by
  )
  values (
    p_item_id, 'adjustment', p_area_id, abs(p_quantity - previous_value),
    p_unit, previous_value, p_quantity, 'file_import',
    'Importación Excel/CSV', auth.uid()
  );

  return imported;
end;
$$;


ALTER FUNCTION "public"."import_area_inventory_stock"("p_item_id" "uuid", "p_area_id" "text", "p_quantity" numeric, "p_minimum_quantity" numeric, "p_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_inventory_rows"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  row_data jsonb;
  inventory_item public.inventory_items;
  previous_value numeric;
  was_existing boolean;
  created_count integer := 0;
  updated_count integer := 0;
  stock_count integer := 0;
  movement_count integer := 0;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para importar inventario.';
  end if;

  for row_data in select value from jsonb_array_elements(p_rows)
  loop
    if nullif(trim(row_data ->> 'name'), '') is null or nullif(trim(row_data ->> 'base_unit'), '') is null then
      raise exception 'La importacion contiene una fila sin nombre o unidad base.';
    end if;

    inventory_item := null;
    if nullif(trim(row_data ->> 'matched_item_id'), '') is not null then
      select * into inventory_item
      from public.inventory_items
      where id = (row_data ->> 'matched_item_id')::uuid;
    elsif nullif(trim(row_data ->> 'sku'), '') is not null then
      select * into inventory_item
      from public.inventory_items
      where sku = nullif(trim(row_data ->> 'sku'), '');
    end if;

    was_existing := inventory_item.id is not null;
    if was_existing then
      update public.inventory_items
      set
        name = trim(row_data ->> 'name'),
        sku = nullif(trim(row_data ->> 'sku'), ''),
        category = nullif(trim(row_data ->> 'category'), ''),
        purchase_unit = nullif(trim(row_data ->> 'purchase_unit'), ''),
        base_unit = trim(row_data ->> 'base_unit'),
        conversion_factor = (row_data ->> 'conversion_factor')::numeric,
        cost_per_base_unit = case
          when inventory_item.purchase_price is not null
            then inventory_item.purchase_price / (row_data ->> 'conversion_factor')::numeric
          else (row_data ->> 'cost_per_base_unit')::numeric
        end,
        supplier = nullif(trim(row_data ->> 'supplier'), ''),
        image_url = coalesce(nullif(trim(row_data ->> 'image_url'), ''), image_url),
        notes = 'Importado desde Excel/CSV',
        active = true
      where id = inventory_item.id
      returning * into inventory_item;
      updated_count := updated_count + 1;
    else
      insert into public.inventory_items (
        name, sku, category, purchase_unit, base_unit, conversion_factor,
        cost_per_base_unit, supplier, image_url, notes, active
      )
      values (
        trim(row_data ->> 'name'),
        nullif(trim(row_data ->> 'sku'), ''),
        nullif(trim(row_data ->> 'category'), ''),
        nullif(trim(row_data ->> 'purchase_unit'), ''),
        trim(row_data ->> 'base_unit'),
        (row_data ->> 'conversion_factor')::numeric,
        (row_data ->> 'cost_per_base_unit')::numeric,
        nullif(trim(row_data ->> 'supplier'), ''),
        nullif(trim(row_data ->> 'image_url'), ''),
        'Importado desde Excel/CSV',
        true
      )
      returning * into inventory_item;
      created_count := created_count + 1;
    end if;

    insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
    values (inventory_item.id, 'almacen', 0, 0)
    on conflict (item_id, area_id) do nothing;

    select quantity into previous_value
    from public.area_inventory
    where item_id = inventory_item.id
      and area_id = 'almacen'
    for update;

    update public.area_inventory
    set
      quantity = (row_data ->> 'quantity')::numeric,
      minimum_quantity = (row_data ->> 'minimum_quantity')::numeric
    where item_id = inventory_item.id
      and area_id = 'almacen';

    insert into public.inventory_movements (
      item_id, movement_type, to_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, notes, performed_by
    )
    values (
      inventory_item.id, 'adjustment', 'almacen',
      abs((row_data ->> 'quantity')::numeric - previous_value),
      row_data ->> 'base_unit', previous_value, (row_data ->> 'quantity')::numeric,
      'file_import', 'Importacion Excel/CSV', auth.uid()
    );

    stock_count := stock_count + 1;
    movement_count := movement_count + 1;
  end loop;

  return jsonb_build_object(
    'created', created_count,
    'updated', updated_count,
    'stocks', stock_count,
    'movements', movement_count
  );
end;
$$;


