CREATE OR REPLACE FUNCTION "public"."list_billing_documents"("p_filter" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce((p_filter ->> 'limit')::integer, 50), 200));
begin
  if not public.can_view_billing_documents() then
    raise exception 'No tienes permiso para consultar documentos de facturacion.';
  end if;

  return coalesce((
    select jsonb_agg(to_jsonb(d) order by d.created_at desc)
    from (
      select
        doc.id,
        doc.legal_entity_id,
        doc.document_type,
        doc.status,
        doc.currency,
        doc.external_id,
        doc.certification_authorization,
        doc.certified_at,
        doc.created_at
      from public.billing_documents doc
      order by doc.created_at desc
      limit v_limit
    ) d
  ), '[]'::jsonb);
end;
$$;


