CREATE OR REPLACE FUNCTION "public"."list_billing_provider_configs"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb;
begin
  if not public.can_view_billing_settings() then
    raise exception 'No tienes permiso para consultar configuracion de proveedores.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', cfg.id,
      'legal_entity_id', cfg.legal_entity_id,
      'legal_entity_code', ent.code,
      'legal_entity_name', ent.legal_name,
      'provider_code', cfg.provider_code,
      'provider_name', prov.name,
      'environment', cfg.environment,
      'entity_id', cfg.entity_id,
      'secret_env_var', cfg.secret_env_var,
      'base_url', cfg.base_url,
      'adapter_version', coalesce(cfg.adapter_version, prov.adapter_version),
      'is_default', cfg.is_default,
      'is_active', cfg.is_active,
      'issuer_settings', cfg.issuer_settings,
      'updated_at', cfg.updated_at
    )
    order by ent.code, cfg.provider_code, cfg.environment
  ), '[]'::jsonb) into v_rows
  from public.billing_provider_configs cfg
  join public.billing_legal_entities ent on ent.id = cfg.legal_entity_id
  join public.billing_providers prov on prov.code = cfg.provider_code;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."list_billing_provider_configs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_catering_quote_templates"("p_include_inactive" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para consultar plantillas.';
  end if;

  select coalesce(jsonb_agg(row_data order by name asc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', template.id,
      'name', template.name,
      'description', template.description,
      'category', template.category,
      'is_active', template.is_active,
      'item_count', (
        select count(*) from public.catering_quote_template_items item where item.template_id = template.id
      ),
      'created_at', template.created_at,
      'updated_at', template.updated_at
    ) as row_data,
    template.name
    from public.catering_quote_templates template
    where p_include_inactive or template.is_active
  ) listed;

  return jsonb_build_object('rows', v_rows);
end;
$$;


