CREATE OR REPLACE FUNCTION "public"."list_pos_catalog_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_category_id" "text" DEFAULT NULL::"text", "p_active" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_total integer;
  v_items jsonb;
begin
  select count(*)::integer into v_total
  from public.pos_products p
  where (v_search is null or p.name ilike '%' || v_search || '%' or coalesce(p.category_name, '') ilike '%' || v_search || '%')
    and (p_category_id is null or p.category_id = p_category_id)
    and (p_active is null or p.active = p_active);

  select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.sort_order asc, row_data.name asc), '[]'::jsonb)
  into v_items
  from (
    select
      p.id,
      p.name,
      p.price,
      p.category_id,
      p.category_name,
      p.recipe_id,
      p.production_area_id,
      p.active,
      p.production_ready,
      p.sort_order,
      p.product_type,
      p.is_test_item,
      p.inventory_tracking_enabled,
      p.recipe_required_for_sale,
      p.recipe_status,
      p.allow_kitchen_notes,
      p.prep_time_minutes,
      p.created_at,
      p.updated_at,
      (p.image_url is not null) as has_image,
      (
        select count(*)::integer
        from public.pos_option_groups g
        where g.product_id = p.id
          and g.is_active = true
      ) as active_option_groups_count
    from public.pos_products p
    where (v_search is null or p.name ilike '%' || v_search || '%' or coalesce(p.category_name, '') ilike '%' || v_search || '%')
      and (p_category_id is null or p.category_id = p_category_id)
      and (p_active is null or p.active = p_active)
    order by p.sort_order asc, p.name asc
    limit v_limit offset v_offset
  ) row_data;

  return jsonb_build_object(
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'items', v_items
  );
end;
$$;


ALTER FUNCTION "public"."list_pos_catalog_page"("p_limit" integer, "p_offset" integer, "p_search" "text", "p_category_id" "text", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_recruitment_candidates"("p_vacancy_id" "uuid" DEFAULT NULL::"uuid", "p_pipeline_status" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text", "p_area" "text" DEFAULT NULL::"text", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para consultar candidatos.';
  end if;

  select coalesce(jsonb_agg(row order by row ->> 'applied_at' desc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', c.id,
      'full_name', c.full_name,
      'phone', c.phone,
      'whatsapp', c.whatsapp,
      'vacancy_id', c.vacancy_id,
      'vacancy_title', v.position_title,
      'vacancy_area', v.area,
      'position_applied', c.position_applied,
      'source', c.source,
      'pipeline_status', c.pipeline_status,
      'applied_at', c.applied_at,
      'salary_expectation', c.salary_expectation,
      'schedule_availability', c.schedule_availability,
      'profile_id', c.profile_id,
      'onboarding_status', c.onboarding_status,
      'hire_date', c.hire_date,
      'converted_at', c.converted_at
    ) as row
    from public.recruitment_candidates c
    join public.recruitment_vacancies v on v.id = c.vacancy_id
    where (p_vacancy_id is null or c.vacancy_id = p_vacancy_id)
      and (p_pipeline_status is null or c.pipeline_status = p_pipeline_status)
      and (p_source is null or c.source = p_source)
      and (p_area is null or nullif(trim(p_area), '') is null or v.area ilike '%' || trim(p_area) || '%')
      and (p_date_from is null or c.applied_at >= p_date_from)
      and (p_date_to is null or c.applied_at <= p_date_to)
  ) sub;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."list_recruitment_candidates"("p_vacancy_id" "uuid", "p_pipeline_status" "text", "p_source" "text", "p_area" "text", "p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_recruitment_onboardings"("p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_view_recruitment_onboarding() then
    raise exception 'No tienes permiso.';
  end if;

  return coalesce((
    select jsonb_agg(row order by row ->> 'created_at' desc)
    from (
      select jsonb_build_object(
        'id', o.id,
        'candidate_id', o.candidate_id,
        'profile_id', o.profile_id,
        'status', o.status,
        'due_date', o.due_date,
        'completed_at', o.completed_at,
        'created_at', o.created_at,
        'employee_name', p.full_name,
        'position', c.final_position,
        'area', c.final_area,
        'pending_tasks', (
          select count(*) from public.recruitment_onboarding_tasks t
          where t.onboarding_id = o.id and t.status in ('pending', 'overdue')
        ),
        'total_tasks', (
          select count(*) from public.recruitment_onboarding_tasks t where t.onboarding_id = o.id
        ),
        'tasks', coalesce((
          select jsonb_agg(to_jsonb(t) order by t.sort_order)
          from public.recruitment_onboarding_tasks t
          where t.onboarding_id = o.id
            and (public.can_manage_recruitment() or t.assigned_profile_id = auth.uid())
        ), '[]'::jsonb)
      ) as row
      from public.recruitment_onboarding_checklists o
      join public.recruitment_candidates c on c.id = o.candidate_id
      join public.profiles p on p.id = o.profile_id
      where (p_status is null or o.status = p_status)
        and (
          public.can_manage_recruitment()
          or exists (
            select 1 from public.recruitment_onboarding_tasks t
            where t.onboarding_id = o.id and t.assigned_profile_id = auth.uid()
          )
        )
    ) sub
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."list_recruitment_onboardings"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_recruitment_profiles"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso.';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id,
      'full_name', p.full_name,
      'username', p.username,
      'role', p.role
    ) order by p.full_name)
    from public.profiles p
    where p.status = 'active'
      and public.normalize_profile_role(p.role) in (
        'admin', 'gerente_general', 'gerente', 'recursos_humanos', 'rrhh', 'supervisor'
      )
  ), '[]'::jsonb);
end;
