CREATE OR REPLACE FUNCTION "public"."login_security_is_unusual_hour"("p_moment" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
