CREATE OR REPLACE FUNCTION "public"."maybe_notify_login_security"("p_attempt_id" "uuid", "p_email" "text", "p_ip" "text", "p_email_failures" integer, "p_ip_failures" integer, "p_success" boolean, "p_profile_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sensitive boolean := p_profile_role = any(public.login_security_sensitive_roles());
begin
  if p_email_failures >= 5 then
    perform public.create_login_security_notification(
      'login_bruteforce_email',
      'Intentos fallidos de login',
      format('El correo %s acumulo %s intentos fallidos en %s minutos.', p_email, p_email_failures, public.login_security_window_minutes()),
      lower(trim(p_email))
    );
  end if;

  if p_ip_failures > 10 then
    perform public.create_login_security_notification(
      'login_bruteforce_ip',
      'IP con intentos fallidos de login',
      format('La IP %s acumulo %s intentos fallidos en %s minutos.', coalesce(p_ip, 'desconocida'), p_ip_failures, public.login_security_window_minutes()),
      coalesce(p_ip, 'unknown')
    );
  end if;

  if not p_success and v_sensitive then
    perform public.create_login_security_notification(
      'login_sensitive_account',
      'Intento fallido en cuenta sensible',
      format('Se intento acceder a la cuenta %s (rol %s).', p_email, coalesce(p_profile_role, 'desconocido')),
      p_attempt_id::text
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."maybe_notify_login_security"("p_attempt_id" "uuid", "p_email" "text", "p_ip" "text", "p_email_failures" integer, "p_ip_failures" integer, "p_success" boolean, "p_profile_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maybe_notify_suspicious_successful_login"("p_attempt_id" "uuid", "p_user_id" "uuid", "p_email" "text", "p_ip" "text", "p_user_agent" "text", "p_profile_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := p_user_id;
  v_email text := lower(trim(coalesce(p_email, '')));
  v_ip text := nullif(trim(coalesce(p_ip, '')), '');
  v_role text := coalesce(nullif(trim(p_profile_role), ''), '');
  v_fingerprint text := public.login_security_user_agent_fingerprint(p_user_agent);
  v_prior_successes integer := 0;
  v_dedup integer := public.login_security_suspicious_dedup_minutes();
  v_day_key text := to_char(now() at time zone 'America/Guatemala', 'YYYY-MM-DD');
begin
  if v_role = '' or not (v_role = any(public.login_security_sensitive_roles())) then
    return;
  end if;

  if v_user_id is null then
    select profile.profile_id into v_user_id
    from public.resolve_login_profile(v_email) profile;
  end if;

  select count(*)::integer
  into v_prior_successes
  from public.security_login_attempts attempt
  where attempt.success = true
    and attempt.id <> p_attempt_id
    and attempt.created_at >= now() - make_interval(days => public.login_security_retention_days())
    and (
      (v_user_id is not null and attempt.user_id = v_user_id)
      or lower(attempt.email_attempted) = v_email
    );

  if v_ip is not null and v_prior_successes > 0 then
    if not exists (
      select 1
      from public.security_login_attempts attempt
      where attempt.success = true
        and attempt.id <> p_attempt_id
        and attempt.ip_address = v_ip
        and attempt.created_at >= now() - make_interval(days => public.login_security_retention_days())
        and (
          (v_user_id is not null and attempt.user_id = v_user_id)
          or lower(attempt.email_attempted) = v_email
        )
    ) then
      perform public.create_login_security_notification(
        'login_suspicious_new_ip',
        'Login sensible desde IP nueva',
        format(
          'El usuario %s (rol %s) inicio sesion desde una IP no vista antes: %s.',
          v_email,
          v_role,
          v_ip
        ),
        coalesce(v_user_id::text, v_email) || ':new_ip:' || v_day_key,
        v_dedup
      );
    end if;
  end if;

  if v_prior_successes > 0 and coalesce(p_user_agent, '') <> '' then
    if not exists (
      select 1
      from public.security_login_attempts attempt
      where attempt.success = true
        and attempt.id <> p_attempt_id
        and attempt.created_at >= now() - make_interval(days => public.login_security_retention_days())
        and public.login_security_user_agent_fingerprint(attempt.user_agent) = v_fingerprint
        and (
          (v_user_id is not null and attempt.user_id = v_user_id)
          or lower(attempt.email_attempted) = v_email
        )
    ) then
      perform public.create_login_security_notification(
        'login_suspicious_new_device',
        'Login sensible desde dispositivo nuevo',
        format(
          'El usuario %s (rol %s) inicio sesion desde un navegador/dispositivo no visto antes.',
          v_email,
          v_role
        ),
        coalesce(v_user_id::text, v_email) || ':new_device:' || v_day_key,
        v_dedup
      );
    end if;
  end if;

  if public.login_security_is_unusual_hour(now()) then
    perform public.create_login_security_notification(
      'login_suspicious_unusual_hour',
      'Login sensible en horario inusual',
      format(
        'El usuario %s (rol %s) inicio sesion fuera del horario habitual (06:00–22:00 GT). IP: %s.',
        v_email,
        v_role,
        coalesce(v_ip, 'desconocida')
      ),
      coalesce(v_user_id::text, v_email) || ':unusual_hour:' || v_day_key,
      v_dedup
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."maybe_notify_suspicious_successful_login"("p_attempt_id" "uuid", "p_user_id" "uuid", "p_email" "text", "p_ip" "text", "p_user_agent" "text", "p_profile_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_inventory_items"("p_master_item_id" "uuid", "p_duplicate_item_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  master_row public.inventory_items;
  duplicate_row public.inventory_items;
  affected jsonb := '{}'::jsonb;
  v_count integer;
  v_area record;
  v_master_qty numeric;
  v_master_min numeric;
begin
  if not public.is_inventory_manager() then
    raise exception 'No tienes permiso para fusionar productos de inventario.';
  end if;

  if p_master_item_id is null or p_duplicate_item_id is null then
    raise exception 'Debes indicar producto maestro y duplicado.';
  end if;

  if p_master_item_id = p_duplicate_item_id then
    raise exception 'No puedes fusionar un producto consigo mismo.';
  end if;

  select * into master_row
  from public.inventory_items
  where id = p_master_item_id
  for update;

  select * into duplicate_row
  from public.inventory_items
  where id = p_duplicate_item_id
  for update;

  if master_row.id is null then
    raise exception 'El producto maestro no existe.';
  end if;

  if duplicate_row.id is null then
    raise exception 'El producto duplicado no existe.';
  end if;

  if duplicate_row.merged_into_item_id is not null then
    raise exception 'El producto duplicado ya fue fusionado anteriormente.';
  end if;

  if master_row.merged_into_item_id is not null then
    raise exception 'El producto maestro ya fue fusionado en otro producto.';
  end if;

  -- area_inventory: sum stock per area, then remove duplicate rows
  for v_area in
    select area_id, quantity, minimum_quantity
    from public.area_inventory
    where item_id = p_duplicate_item_id
  loop
    select quantity, minimum_quantity
    into v_master_qty, v_master_min
    from public.area_inventory
    where item_id = p_master_item_id and area_id = v_area.area_id;

    if found then
      update public.area_inventory
      set quantity = coalesce(v_master_qty, 0) + coalesce(v_area.quantity, 0),
          minimum_quantity = greatest(coalesce(v_master_min, 0), coalesce(v_area.minimum_quantity, 0)),
          updated_at = now()
      where item_id = p_master_item_id and area_id = v_area.area_id;
    else
      update public.area_inventory
      set item_id = p_master_item_id,
          updated_at = now()
      where item_id = p_duplicate_item_id and area_id = v_area.area_id;
    end if;
  end loop;

  delete from public.area_inventory where item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('area_inventory_deleted', v_count);

  update public.inventory_movements set item_id = p_master_item_id where item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('inventory_movements', v_count);

  update public.requisition_items set item_id = p_master_item_id where item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('requisition_items', v_count);

  -- recipe_ingredients: merge quantities when both appear in the same recipe
  update public.recipe_ingredients ri_master
  set quantity = ri_master.quantity + ri_dup.quantity
  from public.recipe_ingredients ri_dup
  where ri_master.inventory_item_id = p_master_item_id
    and ri_dup.inventory_item_id = p_duplicate_item_id
    and ri_master.recipe_id = ri_dup.recipe_id;

  delete from public.recipe_ingredients ri_dup
  using public.recipe_ingredients ri_master
  where ri_dup.inventory_item_id = p_duplicate_item_id
    and ri_master.inventory_item_id = p_master_item_id
    and ri_dup.recipe_id = ri_master.recipe_id;

  update public.recipe_ingredients
  set inventory_item_id = p_master_item_id
  where inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('recipe_ingredients', v_count);

  update public.standard_recipes
  set output_inventory_item_id = p_master_item_id
  where output_inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('standard_recipes_output', v_count);

  update public.production_batches
  set output_inventory_item_id = p_master_item_id
  where output_inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('production_batches', v_count);

  update public.production_batch_inputs
  set inventory_item_id = p_master_item_id
  where inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('production_batch_inputs', v_count);

  update public.production_batch_outputs
  set inventory_item_id = p_master_item_id
  where inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('production_batch_outputs', v_count);

  update public.yield_audits
  set inventory_item_id = p_master_item_id
  where inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('yield_audits', v_count);

  delete from public.yield_audit_campaign_items yaci_dup
  using public.yield_audit_campaign_items yaci_master
  where yaci_dup.inventory_item_id = p_duplicate_item_id
    and yaci_master.inventory_item_id = p_master_item_id
    and yaci_dup.campaign_id = yaci_master.campaign_id;

  update public.yield_audit_campaign_items
  set inventory_item_id = p_master_item_id
  where inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('yield_audit_campaign_items', v_count);

  if exists (select 1 from public.inventory_yield_profiles where inventory_item_id = p_duplicate_item_id) then
    if exists (select 1 from public.inventory_yield_profiles where inventory_item_id = p_master_item_id) then
      delete from public.inventory_yield_profiles where inventory_item_id = p_duplicate_item_id;
      affected := affected || jsonb_build_object('inventory_yield_profiles', jsonb_build_object('action', 'deleted_duplicate'));
    else
      update public.inventory_yield_profiles
      set inventory_item_id = p_master_item_id
      where inventory_item_id = p_duplicate_item_id;
      affected := affected || jsonb_build_object('inventory_yield_profiles', jsonb_build_object('action', 'repointed'));
    end if;
  end if;

  delete from public.inventory_item_unit_conversions conv_dup
  using public.inventory_item_unit_conversions conv_master
  where conv_dup.inventory_item_id = p_duplicate_item_id
    and conv_master.inventory_item_id = p_master_item_id
    and lower(trim(conv_dup.from_unit)) = lower(trim(conv_master.from_unit))
    and lower(trim(conv_dup.to_unit)) = lower(trim(conv_master.to_unit));

  update public.inventory_item_unit_conversions
  set inventory_item_id = p_master_item_id
  where inventory_item_id = p_duplicate_item_id;
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('inventory_item_unit_conversions', v_count);

  update public.purchase_orders po
  set data = jsonb_set(
    coalesce(po.data, '{}'::jsonb),
    '{items}',
    (
      select coalesce(jsonb_agg(
        case
          when coalesce(elem ->> 'producto_id', elem ->> 'inventory_item_id', elem ->> 'id') = p_duplicate_item_id::text
            then elem
              || jsonb_build_object(
                'producto_id', p_master_item_id,
                'inventory_item_id', p_master_item_id,
                'id', p_master_item_id
              )
          else elem
        end
      ), '[]'::jsonb)
      from jsonb_array_elements(coalesce(po.data -> 'items', '[]'::jsonb)) elem
    ),
    true
  ),
  updated_at = now()
  where exists (
    select 1
    from jsonb_array_elements(coalesce(po.data -> 'items', '[]'::jsonb)) elem
    where coalesce(elem ->> 'producto_id', elem ->> 'inventory_item_id', elem ->> 'id') = p_duplicate_item_id::text
  );
  get diagnostics v_count = row_count;
  affected := affected || jsonb_build_object('purchase_orders', v_count);

  -- Barcodes: move or alias, never lose
  if duplicate_row.barcode is not null and trim(duplicate_row.barcode) <> '' then
    if master_row.barcode is null or trim(master_row.barcode) = '' then
      update public.inventory_items
      set barcode = duplicate_row.barcode,
          barcode_type = coalesce(master_row.barcode_type, duplicate_row.barcode_type),
          barcode_source = coalesce(master_row.barcode_source, duplicate_row.barcode_source),
          barcode_created_at = coalesce(master_row.barcode_created_at, duplicate_row.barcode_created_at)
      where id = p_master_item_id;
      select * into master_row from public.inventory_items where id = p_master_item_id;
    elsif lower(trim(master_row.barcode)) <> lower(trim(duplicate_row.barcode)) then
      insert into public.inventory_item_barcode_aliases (item_id, barcode, barcode_type, source_item_id, created_by)
      values (
        p_master_item_id,
        duplicate_row.barcode,
        duplicate_row.barcode_type,
        p_duplicate_item_id,
        auth.uid()
      )
      on conflict do nothing;
      affected := affected || jsonb_build_object('barcode_alias_created', duplicate_row.barcode);
    end if;
  end if;

  -- Photo: use duplicate if master lacks one
  if (master_row.image_url is null or trim(master_row.image_url) = '')
     and duplicate_row.image_url is not null
     and trim(duplicate_row.image_url) <> '' then
    update public.inventory_items set image_url = duplicate_row.image_url where id = p_master_item_id;
    select * into master_row from public.inventory_items where id = p_master_item_id;
    affected := affected || jsonb_build_object('image_moved_from_duplicate', true);
  end if;

  -- SKU: keep master; store duplicate SKU in notes if different and master empty
  if (master_row.sku is null or trim(master_row.sku) = '')
     and duplicate_row.sku is not null
     and trim(duplicate_row.sku) <> '' then
    update public.inventory_items set sku = duplicate_row.sku where id = p_master_item_id;
    select * into master_row from public.inventory_items where id = p_master_item_id;
  elsif duplicate_row.sku is not null
    and trim(duplicate_row.sku) <> ''
    and coalesce(lower(trim(master_row.sku)), '') <> lower(trim(duplicate_row.sku)) then
    update public.inventory_items
    set notes = trim(both from coalesce(master_row.notes, '') || E'\nSKU fusionado: ' || duplicate_row.sku)
    where id = p_master_item_id;
  end if;

  update public.inventory_items
  set active = false,
      merged_into_item_id = p_master_item_id,
      merged_at = now(),
      merged_by = auth.uid(),
      barcode = null,
      sku = null,
      updated_at = now()
  where id = p_duplicate_item_id;

  insert into public.inventory_item_merge_audit (
    master_item_id,
    duplicate_item_id,
    merged_by,
    snapshot_master_before,
    snapshot_duplicate_before,
    affected_tables,
    notes
  )
  values (
    p_master_item_id,
    p_duplicate_item_id,
    auth.uid(),
    to_jsonb(master_row),
    to_jsonb(duplicate_row),
    affected,
    nullif(trim(p_notes), '')
  );

  perform public.refresh_inventory_item_costing(p_master_item_id);

  return jsonb_build_object(
    'ok', true,
    'master_item_id', p_master_item_id,
    'duplicate_item_id', p_duplicate_item_id,
    'affected_tables', affected
  );
exception
  when others then
    raise exception 'Merge fallido: %', sqlerrm;
end;
$$;


ALTER FUNCTION "public"."merge_inventory_items"("p_master_item_id" "uuid", "p_duplicate_item_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_purchase_order_items"("p_existing" "jsonb", "p_incoming" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  merged jsonb := coalesce(p_existing, '[]'::jsonb);
  incoming_line jsonb;
  existing_line jsonb;
  product_key text;
  updated_qty numeric;
  idx int;
  found boolean;
begin
  for incoming_line in select * from jsonb_array_elements(coalesce(p_incoming, '[]'::jsonb))
  loop
    product_key := coalesce(
      nullif(incoming_line ->> 'producto_id', ''),
      nullif(incoming_line ->> 'inventory_item_id', ''),
      nullif(incoming_line ->> 'id', '')
    );
    found := false;

    for idx in 0 .. jsonb_array_length(merged) - 1
    loop
      existing_line := merged -> idx;
      if coalesce(
        nullif(existing_line ->> 'producto_id', ''),
        nullif(existing_line ->> 'inventory_item_id', ''),
        nullif(existing_line ->> 'id', '')
      ) = product_key then
        updated_qty := coalesce((existing_line ->> 'cantidadComprar')::numeric, 0)
          + coalesce((incoming_line ->> 'cantidadComprar')::numeric, 0);
        merged := jsonb_set(
          merged,
          array[idx::text],
          existing_line
            || jsonb_build_object(
              'cantidad_compra', updated_qty,
              'cantidadComprar', updated_qty,
              'subtotal', updated_qty * coalesce((existing_line ->> 'costoUnitario')::numeric, 0),
              'cantidad_base_total', updated_qty * coalesce((existing_line ->> 'factor_conversion')::numeric, 1)
            ),
          true
        );
        found := true;
        exit;
      end if;
    end loop;

    if not found then
      merged := merged || jsonb_build_array(incoming_line);
    end if;
  end loop;

  return merged;
end;
$$;


ALTER FUNCTION "public"."merge_purchase_order_items"("p_existing" "jsonb", "p_incoming" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_local_floor_layout"("p_layout" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.can_manage_pos_floor_plan() then
    raise exception 'No tienes permiso para migrar el plano del restaurante.';
  end if;

  return public.save_pos_floor_layout(p_layout);
end;
$$;


ALTER FUNCTION "public"."migrate_local_floor_layout"("p_layout" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."monthly_sales_for_goal"("p_month" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(sum(o.total), 0)::numeric(12,2)
  from public.pos_orders o
  where o.status = 'paid'
    and coalesce(o.paid_at, o.created_at) >= date_trunc('month', p_month)::timestamptz
    and coalesce(o.paid_at, o.created_at) < (date_trunc('month', p_month)::date + interval '1 month')::timestamptz;
$$;


ALTER FUNCTION "public"."monthly_sales_for_goal"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_operational_task"("p_task_id" "text", "p_status" "text", "p_sort_position" numeric DEFAULT NULL::numeric, "p_waiting_reason" "text" DEFAULT NULL::"text", "p_next_action" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_status text := trim(coalesce(p_status, ''));
  v_old_status text;
  v_old_sort numeric;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if v_status = '' then
    raise exception 'El estado es obligatorio.';
  end if;

  if v_status not in ('pending', 'in_progress', 'waiting', 'in_review', 'completed', 'cancelled') then
    raise exception 'Estado inválido.';
  end if;

  select *
  into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
  for update;

  if not found then
    raise exception 'Tarea no encontrada.';
  end if;

  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para mover esta tarea.';
  end if;

  if v_status = 'waiting' and coalesce(trim(p_waiting_reason), '') = '' then
    raise exception 'Indica el motivo de espera.';
  end if;

  v_old_status := v_task.status;
  v_old_sort := v_task.sort_position;

  update public.assigned_tasks
  set
    status = v_status,
    sort_position = coalesce(p_sort_position, sort_position),
    waiting_reason = case when v_status = 'waiting' then p_waiting_reason else null end,
    next_action = case
      when v_status = 'waiting' then nullif(trim(coalesce(p_next_action, '')), '')
      else next_action
    end,
    started_at = case
      when v_status = 'in_progress' and started_at is null then now()
      else started_at
    end,
    completed_at = case
      when v_status = 'completed' then now()
      when v_status in ('pending', 'in_progress', 'waiting', 'in_review') then null
      else completed_at
    end,
    updated_at = now()
  where id = p_task_id
  returning * into v_task;

  if v_old_status is distinct from v_status then
    perform public.log_task_activity(
      p_task_id, 'status_changed', 'status',
      to_jsonb(v_old_status), to_jsonb(v_status),
      jsonb_build_object('waiting_reason', p_waiting_reason, 'next_action', p_next_action)
    );
  end if;

  if p_sort_position is not null and v_old_sort is distinct from p_sort_position then
    perform public.log_task_activity(
      p_task_id, 'moved', 'sort_position',
      to_jsonb(v_old_sort), to_jsonb(p_sort_position),
      jsonb_build_object('status', v_status)
    );
  end if;

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."move_operational_task"("p_task_id" "text", "p_status" "text", "p_sort_position" numeric, "p_waiting_reason" "text", "p_next_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_operational_task"("p_task_id" "text", "p_status" "text", "p_sort_position" numeric DEFAULT NULL::numeric, "p_waiting_reason" "text" DEFAULT NULL::"text", "p_next_action" "text" DEFAULT NULL::"text", "p_waiting_unblock_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_status text := trim(coalesce(p_status, ''));
  v_old_status text;
  v_old_sort numeric;
  v_unblock text;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;
  if v_status = '' then raise exception 'El estado es obligatorio.'; end if;
  if v_status not in ('pending', 'in_progress', 'waiting', 'blocked', 'in_review', 'completed', 'cancelled') then
    raise exception 'Estado inválido.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id and t.task_source = 'operational'
    and t.deleted_at is null and t.archived_at is null
  for update;

  if not found then raise exception 'Tarea no encontrada.'; end if;
  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para mover esta tarea.';
  end if;

  v_unblock := coalesce(nullif(trim(p_waiting_unblock_note), ''), nullif(trim(p_next_action), ''));

  if v_status in ('waiting', 'blocked') and coalesce(trim(p_waiting_reason), '') = '' then
    raise exception 'Indica qué estamos esperando.';
  end if;

  v_old_status := v_task.status;
  v_old_sort := v_task.sort_position;

  update public.assigned_tasks
  set status = v_status,
      sort_position = coalesce(p_sort_position, sort_position),
      waiting_reason = case when v_status in ('waiting', 'blocked') then p_waiting_reason else null end,
      waiting_unblock_note = case when v_status in ('waiting', 'blocked') then v_unblock else waiting_unblock_note end,
      waiting_since = case
        when v_status in ('waiting', 'blocked') and v_old_status not in ('waiting', 'blocked') then now()
        when v_status not in ('waiting', 'blocked') then null
        else waiting_since
      end,
      started_at = case when v_status = 'in_progress' and started_at is null then now() else started_at end,
      completed_at = case
        when v_status = 'completed' then now()
        when v_status in ('pending', 'in_progress', 'waiting', 'blocked', 'in_review') then null
        else completed_at
      end,
      updated_at = now()
  where id = p_task_id returning * into v_task;

  if v_old_status is distinct from v_status then
    perform public.log_task_activity(
      p_task_id, 'status_changed', 'status',
      to_jsonb(v_old_status), to_jsonb(v_status),
      jsonb_build_object('waiting_reason', p_waiting_reason, 'waiting_unblock_note', v_unblock)
    );
  end if;

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."move_operational_task"("p_task_id" "text", "p_status" "text", "p_sort_position" numeric, "p_waiting_reason" "text", "p_next_action" "text", "p_waiting_unblock_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_task_step"("p_step_id" "uuid", "p_target_list_id" "uuid", "p_sort_position" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_step public.task_steps;
  v_target public.task_step_lists;
  v_pos numeric;
begin
  select * into v_step
  from public.task_steps s
  where s.id = p_step_id and s.deleted_at is null
  for update;

  if not found then raise exception 'Paso no encontrado.'; end if;

  select * into v_target
  from public.task_step_lists sl
  where sl.id = p_target_list_id and sl.deleted_at is null;

  if not found then raise exception 'Lista destino no encontrada.'; end if;
  if v_target.task_id <> v_step.task_id then
    raise exception 'No puedes mover pasos entre tareas distintas.';
  end if;

  perform public.assert_operational_task_mutable(v_step.task_id);

  if p_sort_position is not null then
    v_pos := p_sort_position;
  else
    select coalesce(max(s.sort_position), -1024) + 1024 into v_pos
    from public.task_steps s
    where s.step_list_id = p_target_list_id and s.deleted_at is null;
  end if;

  update public.task_steps
  set step_list_id = p_target_list_id,
      sort_position = v_pos,
      updated_at = now()
  where id = p_step_id;

  return public.get_operational_task_detail(v_step.task_id);
end;
$$;


ALTER FUNCTION "public"."move_task_step"("p_step_id" "uuid", "p_target_list_id" "uuid", "p_sort_position" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_bakery_dough_batch_code"("p_dough_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_slug text := 'MASA-' || public.bakery_slugify(p_dough_type);
  v_day text := to_char(now() at time zone 'America/Guatemala', 'YYYYMMDD');
  v_prefix text := v_slug || '-' || v_day || '-';
  v_next integer;
begin
  select coalesce(max((substring(batch_code from '([0-9]+)$'))::integer), 0) + 1
  into v_next
  from public.bakery_dough_batches
  where batch_code like v_prefix || '%';

  return v_prefix || lpad(v_next::text, 3, '0');
end;
$_$;


