CREATE OR REPLACE FUNCTION "public"."next_catering_quote_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_year integer := extract(year from current_date)::integer;
  v_next integer;
begin
  insert into public.catering_quote_counters as counters (quote_year, last_number)
  values (v_year, 1)
  on conflict (quote_year) do update
    set last_number = counters.last_number + 1
  returning last_number into v_next;

  return format('CAT-%s-%s', v_year, lpad(v_next::text, 4, '0'));
end;
$$;


ALTER FUNCTION "public"."next_catering_quote_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_production_batch_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  day_prefix text := 'PROD-' || to_char(now(), 'YYYYMMDD') || '-';
  next_number integer;
begin
  select coalesce(max((right(batch_number, 4))::integer), 0) + 1
  into next_number
  from public.production_batches
  where batch_number like day_prefix || '%';

  return day_prefix || lpad(next_number::text, 4, '0');
end;
$$;


