CREATE OR REPLACE FUNCTION "public"."normalize_attendance_mark_type"("p_mark_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_mark_type text := lower(trim(coalesce(p_mark_type, 'entrada')));
begin
  if v_mark_type = 'salida' then return 'salida_final'; end if;
  if v_mark_type = 'bano_inicio' then return 'salida_comida'; end if;
  if v_mark_type = 'bano_regreso' then return 'regreso_comida'; end if;
  return v_mark_type;
end;
$$;


ALTER FUNCTION "public"."normalize_attendance_mark_type"("p_mark_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_catering_lead_source"("p_lead_source" "text", "p_source" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when public.is_valid_catering_lead_source(p_lead_source) then lower(trim(p_lead_source))
    when coalesce(nullif(trim(coalesce(p_source, '')), ''), '') in ('wix_form', 'wix_webhook', 'wix_automation') then 'website'
    when coalesce(nullif(trim(coalesce(p_source, '')), ''), '') = 'manual' then 'other'
    else 'website'
  end;
$$;


ALTER FUNCTION "public"."normalize_catering_lead_source"("p_lead_source" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_employee_schedule_fields"("p_shift_type_id" "uuid", "p_shift_type" "text", "p_is_work_day" boolean, "p_area" "text", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_break_minutes" integer, "p_position" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  selected_shift public.shift_types;
  v_is_work_day boolean := coalesce(p_is_work_day, true);
  v_shift_type text := coalesce(nullif(trim(p_shift_type), ''), 'full');
  v_shift_type_id uuid := p_shift_type_id;
  v_non_work_area text;
  v_area text;
begin
  if v_shift_type_id is not null then
    select * into selected_shift from public.shift_types where id = v_shift_type_id;
    if selected_shift.id is null or selected_shift.status <> 'active' then
      raise exception 'Tipo de turno invalido.';
    end if;
    v_is_work_day := selected_shift.counts_as_workday
      and not selected_shift.is_rest_day
      and not selected_shift.is_holiday;
    v_shift_type := selected_shift.id::text;
  elsif v_shift_type in ('rest', 'asueto') then
    v_is_work_day := false;
  end if;

  v_non_work_area := case
    when not v_is_work_day and selected_shift.id is not null then trim(selected_shift.name)
    when selected_shift.is_holiday or v_shift_type = 'asueto' then 'Asueto'
    when selected_shift.is_rest_day or v_shift_type = 'rest' then 'Descanso'
    else coalesce(nullif(trim(p_area), ''), 'Descanso')
  end;

  if v_is_work_day and (
    nullif(trim(p_area), '') is null
    or p_start_time is null
    or p_end_time is null
  ) then
    raise exception 'Area, entrada y salida son obligatorios para dias laborales.';
  end if;

  v_area := case when v_is_work_day then trim(p_area) else v_non_work_area end;

  return jsonb_build_object(
    'is_work_day', v_is_work_day,
    'shift_type', v_shift_type,
    'shift_type_id', v_shift_type_id,
    'area', v_area,
    'position', case when v_is_work_day then nullif(trim(p_position), '') else null end,
    'start_time', case when v_is_work_day then p_start_time else null end,
    'end_time', case when v_is_work_day then p_end_time else null end,
    'break_minutes', case when v_is_work_day then greatest(0, coalesce(p_break_minutes, 0)) else 0 end
  );
end;
$$;


ALTER FUNCTION "public"."normalize_employee_schedule_fields"("p_shift_type_id" "uuid", "p_shift_type" "text", "p_is_work_day" boolean, "p_area" "text", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_break_minutes" integer, "p_position" "text") OWNER TO "postgres";


