    LANGUAGE "sql" IMMUTABLE
    AS $$
  select date_trunc('month', coalesce(p_month, current_date))::date;
$$;


ALTER FUNCTION "public"."normalize_fixed_cost_month"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_inventory_unit"("p_unit" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with normalized as (
    select replace(
      translate(
        lower(trim(coalesce(p_unit, ''))),
        'áéíóúÁÉÍÓÚäëïöüÄËÏÖÜ',
        'aeiouAEIOUaeiouAEIOU'
      ),
      ' ',
      '_'
    ) as unit_key
  )
  select case
    when unit_key in ('', '_') then ''
    when unit_key in ('unidad', 'unidades', 'u', 'unit', 'units', 'pieza', 'piezas', 'piece', 'pieces') then 'unidad'
    when unit_key in ('unidad_pieza', 'unidad/pieza', 'unidad-pieza') then 'unidad'
    when unit_key in ('libra', 'libras', 'lb', 'lbs') then 'libra'
    when unit_key in ('onza', 'onzas', 'oz') then 'onza'
    when unit_key in ('kilogramo', 'kilogramos', 'kg', 'kilo', 'kilos') then 'kilogramo'
    when unit_key in ('gramo', 'gramos', 'g', 'gr') then 'gramo'
    when unit_key in ('mililitro', 'mililitros', 'ml', 'cc') then 'mililitro'
    when unit_key in ('litro', 'litros', 'l') then 'litro'
    when unit_key in ('galon', 'galones', 'gal') then 'galon'
    when unit_key in ('onza_liquida', 'onza_liq', 'fl_oz', 'floz') then 'onza_liquida'
    when unit_key in ('caja', 'cajas', 'box', 'boxes') then 'caja'
    when unit_key in ('paquete', 'paquetes', 'pack', 'packs') then 'paquete'
    when unit_key in ('bolsa', 'bolsas', 'bag', 'bags') then 'bolsa'
    when unit_key in ('lata', 'latas', 'can', 'cans') then 'lata'
    when unit_key in ('botella', 'botellas', 'bottle', 'bottles') then 'botella'
    when unit_key in ('quintal', 'quintales') then 'quintal'
    when unit_key in ('manojo', 'manojos') then 'manojo'
    else unit_key
  end
  from normalized;
$$;


ALTER FUNCTION "public"."normalize_inventory_unit"("p_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_profile_role"("p_role" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('rrhh', 'rr.hh.', 'recursos humanos', 'recursos_humanos') then 'recursos_humanos'
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('gerente general', 'gerente_general') then 'gerente_general'
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('administrador', 'admin') then 'admin'
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('encargado almacen', 'encargado de almacen', 'encargado_almacen') then 'encargado_almacen'
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('cajero', 'caja') then 'caja'
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('cocinero', 'cocina') then 'cocina'
    when translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou') in ('pizzero', 'pizzeria') then 'pizzeria'
    else replace(translate(lower(coalesce(p_role, '')), 'áéíóúÁÉÍÓÚ', 'aeiouaeiou'), ' ', '_')
  end;
$$;


ALTER FUNCTION "public"."normalize_profile_role"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_role_name"("p_role_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_role_name is null or p_role_name = '' then ''
    else lower(
      replace(
        replace(
          replace(
            translate(p_role_name, 'ÁÉÍÓÚÄËÏÖÜ', 'aeiouaeiou'),
            '-',
            '_'
          ),
          ' ',
          '_'
        ),
        '.',
        '_'
      )
    )
  end;
$$;


ALTER FUNCTION "public"."normalize_role_name"("p_role_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_catering_lead_assigned"("p_request_id" "uuid", "p_assigned_to" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.catering_requests;
  v_action_url text;
  v_inserted integer := 0;
begin
  if p_request_id is null or p_assigned_to is null then
    return 0;
  end if;

  select * into v_request from public.catering_requests where id = p_request_id;
  if not found then
    return 0;
  end if;

  v_action_url := '/catering?id=' || v_request.id::text;

  insert into public.notifications (
    user_id,
    target_role,
    type,
    title,
    message,
    entity_type,
    entity_id,
    action_url
  )
  select
    assignee.id,
    null,
    'catering_lead_assigned',
    'Lead de catering asignado',
    coalesce(nullif(trim(v_request.customer_name), ''), 'Cliente')
      || ' te fue asignado para seguimiento comercial.',
    'catering_request',
    v_request.id::text,
    v_action_url
  from public.profiles assignee
  where assignee.id = p_assigned_to
    and assignee.status = 'active'
    and public.can_receive_catering_notifications(assignee.role)
    and not exists (
      select 1
      from public.notifications n
      where n.user_id = p_assigned_to
        and n.type = 'catering_lead_assigned'
        and n.entity_type = 'catering_request'
        and n.entity_id = v_request.id::text
        and n.created_at > now() - interval '1 hour'
    );

  get diagnostics v_inserted = row_count;
  return v_inserted;
exception
  when others then
    raise warning 'notify_catering_lead_assigned failed for %: %', p_request_id, sqlerrm;
    return 0;
end;
$$;


ALTER FUNCTION "public"."notify_catering_lead_assigned"("p_request_id" "uuid", "p_assigned_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_catering_quote_status"("p_quote_id" "uuid", "p_status" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_quote public.catering_quotes;
  v_request public.catering_requests;
  v_status text := lower(trim(coalesce(p_status, '')));
  v_title text;
  v_message text;
  v_action_url text;
  v_inserted integer := 0;
begin
  if p_quote_id is null then
    return 0;
  end if;

  if v_status not in ('sent', 'approved', 'rejected') then
    return 0;
  end if;

  select quote.*
  into v_quote
  from public.catering_quotes quote
  where quote.id = p_quote_id;

  if not found then
    return 0;
  end if;

  select *
  into v_request
  from public.catering_requests
  where id = v_quote.request_id;

  v_action_url := '/catering?id=' || v_quote.request_id::text;

  v_title := case v_status
    when 'sent' then 'Cotizacion enviada'
    when 'approved' then 'Cotizacion aprobada'
    when 'rejected' then 'Cotizacion rechazada'
    else 'Cotizacion actualizada'
  end;

  v_message := case v_status
    when 'sent' then
      'Cotizacion enviada: '
      || v_quote.quote_number
      || ' para '
      || coalesce(nullif(trim(v_request.customer_name), ''), 'Cliente')
    when 'approved' then
      'Cotizacion aprobada: '
      || v_quote.quote_number
      || ' por Q'
      || to_char(v_quote.total, 'FM999999990.00')
    when 'rejected' then
      'Cotizacion rechazada: ' || v_quote.quote_number
    else v_quote.quote_number
  end;

  with recipients as (
    select distinct profile.id as profile_id
    from public.profiles profile
    where profile.status = 'active'
      and public.normalize_profile_role(profile.role) = any(public.catering_request_notification_roles())
  ),
  inserted as (
    insert into public.notifications (
      user_id,
      target_role,
      type,
      title,
      message,
      entity_type,
      entity_id,
      action_url
    )
    select
      recipients.profile_id,
      null,
      'catering_quote',
      v_title,
      v_message,
      'catering_request',
      v_quote.request_id::text,
      v_action_url
    from recipients
    where not exists (
      select 1
      from public.notifications notification
      where notification.user_id = recipients.profile_id
        and notification.type = 'catering_quote'
        and notification.entity_type = 'catering_request'
        and notification.entity_id = v_quote.request_id::text
        and notification.title = v_title
        and notification.message = v_message
    )
    returning 1
  )
  select count(*) into v_inserted from inserted;

  return v_inserted;
exception
  when others then
    raise warning 'notify_catering_quote_status failed for quote % status %: %',
      p_quote_id, p_status, sqlerrm;
    return 0;
end;
$$;


ALTER FUNCTION "public"."notify_catering_quote_status"("p_quote_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_checklist_run_reopened"("p_run_id" "uuid", "p_reason" "text" DEFAULT 'Se actualizo la checklist y faltan items por completar.'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_record public.checklist_runs;
  template_title text;
begin
  select * into run_record
  from public.checklist_runs
  where id = p_run_id;

  if run_record.id is null or run_record.assigned_profile_id is null then
    return;
  end if;

  select title into template_title
  from public.checklist_templates
  where id = run_record.template_id;

  insert into public.notifications (
    user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
  )
  values (
    run_record.assigned_profile_id,
    null,
    'checklist',
    'Checklist pendiente de terminar',
    coalesce(template_title, 'Checklist') || ': ' || coalesce(p_reason, 'Faltan items por completar.'),
    'checklist_run',
    run_record.id::text,
    '/tasks?tab=checklists&view=run&id=' || run_record.id::text,
    auth.uid()
  )
  on conflict do nothing;
end;
$$;


ALTER FUNCTION "public"."notify_checklist_run_reopened"("p_run_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_new_catering_request"("p_request_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.catering_requests;
  v_title text;
  v_message text;
  v_action_url text;
  v_inserted integer := 0;
begin
  if p_request_id is null then
    return 0;
  end if;

  select *
  into v_request
  from public.catering_requests
  where id = p_request_id;

  if not found then
    return 0;
  end if;

  if v_request.source = 'manual' then
    v_title := 'Nuevo lead manual de catering';
    v_message := coalesce(nullif(trim(v_request.customer_name), ''), 'Cliente')
      || ' — lead manual ('
      || v_request.lead_source
      || ').';
  else
    v_title := 'Nueva solicitud de catering';
    v_message := public.build_catering_request_notification_message(
      v_request.customer_name,
      v_request.guest_count
    );
  end if;

  v_action_url := '/catering?id=' || v_request.id::text;

  with recipients as (
    select distinct p.id as profile_id
    from public.profiles p
    where p.status = 'active'
      and public.normalize_profile_role(p.role) = any(public.catering_request_notification_roles())
  ),
  inserted as (
    insert into public.notifications (
      user_id,
      target_role,
      type,
      title,
      message,
      entity_type,
      entity_id,
      action_url
    )
    select
      recipients.profile_id,
      null,
      'catering_request',
      v_title,
      v_message,
      'catering_request',
      v_request.id::text,
      v_action_url
    from recipients
    where not exists (
      select 1
      from public.notifications n
      where n.user_id = recipients.profile_id
        and n.type = 'catering_request'
        and n.entity_type = 'catering_request'
        and n.entity_id = v_request.id::text
    )
    returning 1
  )
  select count(*) into v_inserted from inserted;

  return v_inserted;
exception
  when others then
    raise warning 'notify_new_catering_request failed for %: %', p_request_id, sqlerrm;
    return 0;
end;
$$;


ALTER FUNCTION "public"."notify_new_catering_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_new_recruitment_application"("p_candidate_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate public.recruitment_candidates;
  v_message text;
  v_action_url text;
  v_inserted integer := 0;
begin
  if p_candidate_id is null then
    return 0;
  end if;

  select *
  into v_candidate
  from public.recruitment_candidates
  where id = p_candidate_id;

  if not found then
    return 0;
  end if;

  v_message := coalesce(v_candidate.full_name, 'Un candidato')
    || ' aplicó para '
    || coalesce(nullif(trim(v_candidate.position_applied), ''), 'un puesto')
    || ' desde el sitio web.';
  v_action_url := '/hr?section=reclutamiento&tab=pipeline&candidateId=' || v_candidate.id::text;

  with recipients as (
    select distinct p.id as profile_id
    from public.profiles p
    where p.status = 'active'
      and public.normalize_profile_role(p.role) = any(public.recruitment_application_notification_roles())
  ),
  inserted as (
    insert into public.notifications (
      user_id,
      target_role,
      type,
      title,
      message,
      entity_type,
      entity_id,
      action_url
    )
    select
      recipients.profile_id,
      null,
      'recruitment',
      'Nuevo candidato recibido',
      v_message,
      'recruitment_candidate',
      v_candidate.id::text,
      v_action_url
    from recipients
    where not exists (
      select 1
      from public.notifications n
      where n.user_id = recipients.profile_id
        and n.type = 'recruitment'
        and n.entity_type = 'recruitment_candidate'
        and n.entity_id = v_candidate.id::text
        and n.title = 'Nuevo candidato recibido'
        and n.created_at > now() - interval '1 hour'
    )
    returning 1
  )
  select count(*) into v_inserted from inserted;

  return v_inserted;
exception
  when others then
    raise warning 'notify_new_recruitment_application failed for %: %', p_candidate_id, sqlerrm;
    return 0;
end;
$$;


ALTER FUNCTION "public"."notify_new_recruitment_application"("p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_operational_task_event"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_task_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action_url text;
begin
  if p_user_id is null or p_user_id = auth.uid() then
    return;
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = p_user_id and p.status = 'active'
  ) then
    return;
  end if;

  v_action_url := '/tasks/trabajo/mi-trabajo?task=' || p_task_id;

  begin
    perform public.create_notification(
      p_user_id,
      null,
      p_type,
      p_title,
      p_message,
      'task',
      p_task_id,
      v_action_url
    );
  exception when others then
    null;
  end;
end;
$$;


ALTER FUNCTION "public"."notify_operational_task_event"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_overdue_checklist_runs"("p_reference" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  template_row public.checklist_templates;
  assignee_name text;
  notified_count integer := 0;
  role_value text;
  current_ts timestamptz := coalesce(p_reference, now());
begin
  for run_row in
    select r.*
    from public.checklist_runs r
    where r.status in ('pending', 'in_progress', 'rejected')
      and r.overdue_notified_at is null
      and not public.is_checklist_operational_window_open(r.run_date, current_ts)
  loop
    select * into template_row
    from public.checklist_templates
    where id = run_row.template_id;

    select coalesce(p.full_name, p.username, 'Colaborador') into assignee_name
    from public.profiles p
    where p.id = run_row.assigned_profile_id;

    update public.checklist_runs
    set status = 'overdue',
        overdue_notified_at = now()
    where id = run_row.id;

    foreach role_value in array array['admin', 'gerente_general']
    loop
      insert into public.notifications (
        user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
      )
      values (
        null,
        role_value,
        'checklist_overdue',
        'Checklist vencida',
        coalesce(nullif(trim(template_row.title), ''), 'Checklist')
          || ' asignada a '
          || coalesce(assignee_name, 'colaborador')
          || ' no fue completada al cierre operativo.',
        'checklist_run',
        run_row.id::text,
        '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
        null
      );
    end loop;

    notified_count := notified_count + 1;
  end loop;

  return jsonb_build_object('notified_count', notified_count);
end;
$$;


ALTER FUNCTION "public"."notify_overdue_checklist_runs"("p_reference" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_cash_session"("p_cash_register_id" "uuid", "p_opening_amount" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."cash_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  register_row public.cash_registers;
  saved public.cash_sessions;
begin
  if not public.is_cash_operator() then
    raise exception 'No tienes permiso para abrir caja.';
  end if;
  select * into register_row
  from public.cash_registers
  where id = p_cash_register_id and status = 'active';
  if register_row.id is null then
    raise exception 'La caja no existe o esta inactiva.';
  end if;
  if exists (
    select 1 from public.cash_sessions
    where cash_register_id = p_cash_register_id and status = 'open'
  ) then
    raise exception 'Ya existe una caja abierta.';
  end if;

  insert into public.cash_sessions (
    cash_register_id, opened_by, opening_amount, expected_cash, notes
  ) values (
    p_cash_register_id, auth.uid(), greatest(0, coalesce(p_opening_amount, 0))::numeric(12,2),
    greatest(0, coalesce(p_opening_amount, 0))::numeric(12,2), nullif(trim(coalesce(p_notes, '')), '')
  ) returning * into saved;

  insert into public.cash_movements (
    cash_session_id, cash_register_id, created_by, movement_type, amount, reason
  ) values (
    saved.id, saved.cash_register_id, auth.uid(), 'shift_open', 0, 'Apertura de caja'
  );

  return saved;
end;
$$;


ALTER FUNCTION "public"."open_cash_session"("p_cash_register_id" "uuid", "p_opening_amount" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_pos_table_service"("p_table_id" "text", "p_table_name" "text", "p_area_id" "text", "p_area_name" "text", "p_sales_channel" "text" DEFAULT 'dine_in'::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_customer_address_id" "uuid" DEFAULT NULL::"uuid", "p_delivery_notes" "text" DEFAULT NULL::"text", "p_external_source" "text" DEFAULT NULL::"text", "p_external_order_id" "text" DEFAULT NULL::"text", "p_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_table_id text;
  v_fingerprint text;
  v_cached jsonb;
  v_reuse_id uuid;
  v_order public.pos_orders;
  v_waiter_name text;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para abrir servicio POS.';
  end if;

  if coalesce(nullif(trim(p_sales_channel), ''), 'dine_in') <> 'dine_in' then
    raise exception 'open_pos_table_service supports dine_in table service only.'
      using hint = 'Use legacy channel flow for delivery, takeout, or online.';
  end if;

  v_table_id := nullif(trim(p_table_id), '');
  if v_table_id is null then
    raise exception 'Table id is required.';
  end if;
  if p_idempotency_key is null then
    raise exception 'POS_IDEMPOTENCY_KEY_REQUIRED';
  end if;

  v_fingerprint := public.pos_rpc_fingerprint(array[
    'open',
    v_table_id,
    coalesce(trim(p_table_name), ''),
    coalesce(trim(p_area_id), ''),
    coalesce(trim(p_area_name), ''),
    coalesce(trim(p_sales_channel), 'dine_in'),
    coalesce(p_customer_id::text, ''),
    coalesce(p_customer_address_id::text, ''),
    coalesce(trim(p_delivery_notes), ''),
    coalesce(trim(p_external_source), ''),
    coalesce(trim(p_external_order_id), '')
  ]);

  v_cached := public.pos_load_rpc_idempotency(p_idempotency_key, v_fingerprint);
  if v_cached is not null then
    return v_cached;
  end if;

  perform pg_advisory_xact_lock(hashtext('pos_table_service:' || v_table_id));

  v_reuse_id := public.pos_table_has_reusable_active_order(v_table_id);
  if v_reuse_id is not null then
    select * into v_order from public.pos_orders where id = v_reuse_id;
    v_result := jsonb_build_object(
      'created', false,
      'reused', true,
      'order_id', v_order.id,
      'owner_profile_id', v_order.owner_profile_id,
      'status', v_order.status,
      'table_id', v_order.table_id
    );
    perform public.pos_store_rpc_idempotency(
      p_idempotency_key, 'open_pos_table_service', 'table:' || v_table_id, v_fingerprint, v_result
    );
    return v_result;
  end if;

  if public.pos_table_is_zombie_open(v_table_id) then
    raise exception 'POS_TABLE_PENDING_RELEASE'
      using hint = 'Release the pending service before opening a new one.';
  end if;

  if public.pos_table_has_billing_block(v_table_id) then
    raise exception 'POS_TABLE_IN_BILLING'
      using hint = 'Table has an order in billing flow.';
  end if;

  select coalesce(nullif(trim(p.full_name), ''), nullif(trim(p.username), ''), 'POS')
    into v_waiter_name
  from public.profiles p
  where p.id = auth.uid();

  begin
    insert into public.pos_orders (
      table_id, table_name, area_id, area_name,
      sales_channel, customer_id, customer_address_id, delivery_notes,
      external_source, external_order_id,
      waiter_id, waiter_name, owner_profile_id, status
    ) values (
      v_table_id,
      coalesce(nullif(trim(p_table_name), ''), 'Mesa'),
      nullif(trim(p_area_id), ''),
      nullif(trim(p_area_name), ''),
      coalesce(nullif(trim(p_sales_channel), ''), 'dine_in'),
      p_customer_id,
      p_customer_address_id,
      nullif(trim(p_delivery_notes), ''),
      nullif(trim(p_external_source), ''),
      nullif(trim(p_external_order_id), ''),
      auth.uid(),
      v_waiter_name,
      auth.uid(),
      'open'
    )
    returning * into v_order;
  exception
    when unique_violation then
      v_reuse_id := public.pos_table_has_reusable_active_order(v_table_id);
      if v_reuse_id is null then
        raise;
      end if;
      select * into v_order from public.pos_orders where id = v_reuse_id;
      v_result := jsonb_build_object(
        'created', false,
        'reused', true,
        'order_id', v_order.id,
        'owner_profile_id', v_order.owner_profile_id,
        'status', v_order.status,
        'table_id', v_order.table_id
      );
      perform public.pos_store_rpc_idempotency(
        p_idempotency_key, 'open_pos_table_service', 'table:' || v_table_id, v_fingerprint, v_result
      );
      return v_result;
  end;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    v_order.id,
    'service_opened',
    'Servicio abierto en ' || coalesce(v_order.table_name, v_table_id) || '.',
    auth.uid()
  );

  v_result := jsonb_build_object(
    'created', true,
    'reused', false,
    'order_id', v_order.id,
    'owner_profile_id', v_order.owner_profile_id,
    'status', v_order.status,
    'table_id', v_order.table_id
  );

  perform public.pos_store_rpc_idempotency(
    p_idempotency_key, 'open_pos_table_service', 'table:' || v_table_id, v_fingerprint, v_result
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."open_pos_table_service"("p_table_id" "text", "p_table_name" "text", "p_area_id" "text", "p_area_name" "text", "p_sales_channel" "text", "p_customer_id" "uuid", "p_customer_address_id" "uuid", "p_delivery_notes" "text", "p_external_source" "text", "p_external_order_id" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_station_cash_session"("p_operator_session_token" "text", "p_opening_amount" numeric, "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_register_id uuid;
  v_saved public.cash_sessions;
  v_cached jsonb;
  v_fingerprint text;
  v_generic constant text := 'No se pudo abrir caja.';
begin
  v_fingerprint := public.station_cash_request_fingerprint(
    'open',
    jsonb_build_object(
      'opening_amount', round(greatest(0, coalesce(p_opening_amount, 0))::numeric, 2),
      'notes', coalesce(nullif(trim(coalesce(p_notes, '')), ''), '')
    )
  );

  v_cached := public.station_cash_idempotency_replay_if_completed(
    p_operator_session_token, 'open', p_idempotency_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_cash_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_register_id := (v_ctx ->> 'cash_register_id')::uuid;

  v_cached := public.station_cash_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, p_idempotency_key, 'open', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_cash_extend_operator_idle(v_op_session_id);

  if exists (
    select 1 from public.cash_sessions
    where cash_register_id = v_register_id and status = 'open'
  ) then
    raise exception 'Ya existe una caja abierta.';
  end if;

  insert into public.cash_sessions (
    cash_register_id, opened_by, opening_amount, expected_cash, notes
  ) values (
    v_register_id,
    v_operator_id,
    greatest(0, coalesce(p_opening_amount, 0))::numeric(12,2),
    greatest(0, coalesce(p_opening_amount, 0))::numeric(12,2),
    nullif(trim(coalesce(p_notes, '')), '')
  ) returning * into v_saved;

  insert into public.cash_movements (
    cash_session_id, cash_register_id, created_by, movement_type, amount, reason, metadata
  ) values (
    v_saved.id, v_saved.cash_register_id, v_operator_id, 'shift_open', 0, 'Apertura de caja',
    jsonb_build_object(
      'operational_station_id', v_station_id,
      'operational_station_device_id', v_device_id,
      'operator_profile_id', v_operator_id
    )
  );

  perform public.log_operational_station_event(
    v_station_id, v_device_id, 'station_cash_session_opened', v_operator_id,
    jsonb_build_object('cash_session_id', v_saved.id), nullif(trim(p_idempotency_key), '')
  );

  v_cached := jsonb_build_object('ok', true, 'session', to_jsonb(v_saved));
  perform public.station_cash_idempotency_complete(v_device_id, p_idempotency_key, v_cached);
  return v_cached;
exception
  when others then
    if sqlerrm = 'Ya existe una caja abierta.' then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."open_station_cash_session"("p_operator_session_token" "text", "p_opening_amount" numeric, "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_station_pos_table_service"("p_operator_session_token" "text", "p_table_id" "text", "p_table_name" "text", "p_area_id" "text", "p_area_name" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_table_id text;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_reuse_id uuid;
  v_order public.pos_orders;
  v_waiter_name text;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_table_id := nullif(trim(p_table_id), '');
  if v_table_id is null then
    raise exception 'Table id is required.';
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'open_table_service',
    jsonb_build_object(
      'table_id', v_table_id,
      'table_name', coalesce(nullif(trim(p_table_name), ''), 'Mesa'),
      'area_id', coalesce(nullif(trim(p_area_id), ''), ''),
      'area_name', coalesce(nullif(trim(p_area_name), ''), ''),
      'sales_channel', 'dine_in'
    )
  );

  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'open_table_service', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'open_table_service', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);

  if not public.station_pos_can_operate_orders(v_operator_id) then
    raise exception '%', v_generic;
  end if;

  perform pg_advisory_xact_lock(hashtext('pos_table_service:' || v_table_id));

  v_reuse_id := public.pos_table_has_reusable_active_order(v_table_id);
  if v_reuse_id is not null then
    select * into v_order from public.pos_orders where id = v_reuse_id;
    if v_order.owner_profile_id is distinct from v_operator_id then
      raise exception 'STATION_POS_ORDER_OWNER_MISMATCH'
        using hint = 'Table service owned by another operator.';
    end if;
    v_result := jsonb_build_object(
      'created', false,
      'reused', true,
      'order_id', v_order.id,
      'owner_profile_id', v_order.owner_profile_id,
      'status', v_order.status,
      'table_id', v_order.table_id
    );
    perform public.station_pos_record_audit(
      v_order.id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
      'open_table_service', v_fingerprint, v_result
    );
    perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
    return v_result;
  end if;

  if public.pos_table_is_zombie_open(v_table_id) then
    raise exception 'POS_TABLE_PENDING_RELEASE'
      using hint = 'Release the pending service before opening a new one.';
  end if;

  if public.pos_table_has_billing_block(v_table_id) then
    raise exception 'POS_TABLE_IN_BILLING'
      using hint = 'Table has an order in billing flow.';
  end if;

  select coalesce(nullif(trim(p.full_name), ''), nullif(trim(p.username), ''), 'POS')
    into v_waiter_name
  from public.profiles p
  where p.id = v_operator_id;

  begin
    insert into public.pos_orders (
      table_id, table_name, area_id, area_name,
      sales_channel,
      waiter_id, waiter_name, owner_profile_id, status
    ) values (
      v_table_id,
      coalesce(nullif(trim(p_table_name), ''), 'Mesa'),
      nullif(trim(p_area_id), ''),
      nullif(trim(p_area_name), ''),
      'dine_in',
      v_operator_id,
      v_waiter_name,
      v_operator_id,
      'open'
    )
    returning * into v_order;
  exception
    when unique_violation then
      v_reuse_id := public.pos_table_has_reusable_active_order(v_table_id);
      if v_reuse_id is null then
        raise;
      end if;
      select * into v_order from public.pos_orders where id = v_reuse_id;
      if v_order.owner_profile_id is distinct from v_operator_id then
        raise exception 'STATION_POS_ORDER_OWNER_MISMATCH'
          using hint = 'Table service owned by another operator.';
      end if;
      v_result := jsonb_build_object(
        'created', false,
        'reused', true,
        'order_id', v_order.id,
        'owner_profile_id', v_order.owner_profile_id,
        'status', v_order.status,
        'table_id', v_order.table_id
      );
      perform public.station_pos_record_audit(
        v_order.id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
        'open_table_service', v_fingerprint, v_result
      );
      perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
      return v_result;
  end;

  insert into public.pos_order_events (
    order_id,
    event_type,
    description,
    created_by
  )
  values (
    v_order.id,
    'service_opened',
    'Servicio abierto en ' || coalesce(v_order.table_name, v_table_id) || '.',
    v_operator_id
  );

  v_result := jsonb_build_object(
    'created', true,
    'reused', false,
    'order_id', v_order.id,
    'owner_profile_id', v_order.owner_profile_id,
    'status', v_order.status,
    'table_id', v_order.table_id
  );
  perform public.station_pos_record_audit(
    v_order.id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'open_table_service', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm like 'STATION_POS_%' or sqlerrm like 'POS_TABLE_%' or sqlerrm like 'POS_IDEMPOTENCY_%' then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


