CREATE OR REPLACE FUNCTION "public"."operational_process_run_progress"("p_process_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_required integer := 0;
  v_completed integer := 0;
  v_in_progress integer := 0;
  v_pending integer := 0;
  v_cancelled integer := 0;
begin
  select
    count(*) filter (where rs.is_required),
    count(*) filter (where rs.is_required and cr.status = 'completed'),
    count(*) filter (where cr.status = 'in_progress'),
    count(*) filter (where cr.status in ('pending', 'rejected')),
    count(*) filter (where cr.status = 'cancelled')
  into v_required, v_completed, v_in_progress, v_pending, v_cancelled
  from public.operational_process_run_steps rs
  join public.checklist_runs cr on cr.id = rs.checklist_run_id
  where rs.process_run_id = p_process_run_id;

  return jsonb_build_object(
    'required_steps', coalesce(v_required, 0),
    'completed_steps', coalesce(v_completed, 0),
    'in_progress_steps', coalesce(v_in_progress, 0),
    'pending_steps', coalesce(v_pending, 0),
    'cancelled_steps', coalesce(v_cancelled, 0),
    'percent', case
      when coalesce(v_required, 0) = 0 then 100
      else round((coalesce(v_completed, 0)::numeric / v_required::numeric) * 100, 1)
    end
  );
end;
$$;


ALTER FUNCTION "public"."operational_process_run_progress"("p_process_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."operational_process_template_due_on_date"("p_template" "public"."operational_process_templates", "p_date" "date") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_template.status <> 'active' then false
    when not public.operational_process_template_should_auto_generate(p_template) then false
    when p_template.frequency_type = 'daily' then true
    when p_template.frequency_type = 'weekly' then
      coalesce(array_length(p_template.recurrence_days, 1), 0) > 0
      and extract(isodow from p_date)::integer = any(p_template.recurrence_days)
    when p_template.frequency_type = 'monthly' then
      coalesce(p_template.recurrence_month_day, 1) = extract(day from p_date)::integer
    else false
  end;
$$;


ALTER FUNCTION "public"."operational_process_template_due_on_date"("p_template" "public"."operational_process_templates", "p_date" "date") OWNER TO "postgres";


