  select coalesce(current_setting('pos.suppress_catalog_refresh', true), '') = 'true';
$$;


ALTER FUNCTION "public"."pos_catalog_refresh_is_suppressed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_classify_release_scenario"("p_order_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.pos_orders;
  v_item_count integer;
  v_draft_only boolean;
begin
  select * into v_order from public.pos_orders where id = p_order_id;
  if v_order.id is null then
    raise exception 'POS order not found.';
  end if;

  if v_order.status = 'paid' then
    return 'L6_paid';
  end if;
  if v_order.status = 'cancelled' then
    return 'L6_cancelled';
  end if;
  if v_order.status = 'partially_paid' or public.pos_order_has_payments(p_order_id) then
    return 'L5_payments';
  end if;
  if v_order.status in ('awaiting_bill', 'sent_to_cashier') then
    return 'L4_billing';
  end if;
  if public.pos_order_ever_sent_to_kds(p_order_id) then
    return 'L3_kds_history';
  end if;

  select count(*) into v_item_count
  from public.pos_order_items i
  where i.order_id = p_order_id;

  if v_item_count = 0 then
    return 'L1_empty';
  end if;

  select not exists (
    select 1 from public.pos_order_items i
    where i.order_id = p_order_id and i.status <> 'draft'
  ) into v_draft_only;

  if v_draft_only then
    return 'L2_drafts_only';
  end if;

  return 'L3_kds_history';
end;
$$;


ALTER FUNCTION "public"."pos_classify_release_scenario"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_configurable_catalog_is_valid"("p_product_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  grp record;
  active_choice_count integer;
begin
  if not exists (
    select 1
    from public.pos_option_groups
    where product_id = p_product_id
      and is_active = true
  ) then
    return false;
  end if;

  for grp in
    select *
    from public.pos_option_groups
    where product_id = p_product_id
      and is_active = true
  loop
    select count(*) into active_choice_count
    from public.pos_option_choices
    where group_id = grp.id
      and is_active = true;

    if grp.required and active_choice_count = 0 then
      return false;
    end if;

    if grp.selection_mode = 'single'
       and grp.max_selections is not null
       and grp.max_selections <> 1 then
      return false;
    end if;

    if exists (
      select 1
      from public.pos_option_choices choice
      where choice.group_id = grp.id
        and choice.is_active = true
        and choice.price_mode = 'absolute'
        and coalesce(choice.price, 0) <= 0
    ) then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."pos_configurable_catalog_is_valid"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_configurable_min_absolute_price"("p_product_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(min(choice.price), 0)
  from public.pos_option_groups grp
  join public.pos_option_choices choice on choice.group_id = grp.id
  where grp.product_id = p_product_id
    and grp.is_active = true
    and choice.is_active = true
    and choice.price_mode = 'absolute'
    and choice.price > 0;
$$;


