CREATE OR REPLACE FUNCTION "public"."pos_load_rpc_idempotency"("p_key" "uuid", "p_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.pos_rpc_idempotency;
begin
  if p_key is null then
    raise exception 'POS_IDEMPOTENCY_KEY_REQUIRED';
  end if;

  select * into v_row
  from public.pos_rpc_idempotency
  where idempotency_key = p_key;

  if v_row.idempotency_key is null then
    return null;
  end if;

  if v_row.request_fingerprint is distinct from p_fingerprint then
    raise exception 'POS_IDEMPOTENCY_FINGERPRINT_MISMATCH'
      using hint = 'Same idempotency key was used with different parameters.';
  end if;

  return v_row.result;
end;
$$;


ALTER FUNCTION "public"."pos_load_rpc_idempotency"("p_key" "uuid", "p_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_order_event_actor_profile"("p_order_id" "uuid" DEFAULT NULL::"uuid", "p_order_owner_profile_id" "uuid" DEFAULT NULL::"uuid", "p_order_waiter_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_actor uuid;
begin
  if v_uid is not null and exists (
    select 1
    from public.profiles p
    where p.id = v_uid
      and p.status = 'active'
  ) then
    return v_uid;
  end if;

  v_actor := coalesce(p_order_owner_profile_id, p_order_waiter_id);

  if v_actor is null and p_order_id is not null then
    select coalesce(o.owner_profile_id, o.waiter_id)
      into v_actor
    from public.pos_orders o
    where o.id = p_order_id;
  end if;

  if v_actor is not null and exists (
    select 1
    from public.profiles p
    where p.id = v_actor
      and p.status = 'active'
  ) then
    return v_actor;
  end if;

  raise exception 'STATION_POS_AUDIT_ACTOR_INVALID'
    using hint = 'No valid operator profile for POS audit event attribution.';
end;
$$;


ALTER FUNCTION "public"."pos_order_event_actor_profile"("p_order_id" "uuid", "p_order_owner_profile_id" "uuid", "p_order_waiter_id" "uuid") OWNER TO "postgres";


