CREATE OR REPLACE FUNCTION "public"."probe_attendance_late_arrival"("p_date" "date", "p_employee_name" "text" DEFAULT NULL::"text") RETURNS TABLE("step" "text", "ok" boolean, "detail" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_employee_id uuid;
  v_schedule_count integer;
  v_mark_count integer;
  v_grace integer;
begin
  if not public.can_view_attendance_reports() then
    return query select
      'permission'::text,
      false,
      format('auth.uid=%s no tiene permiso de reportes (admin/gerente_general/recursos_humanos)', coalesce(auth.uid()::text, 'null'));
    return;
  end if;

  return query select 'migration_071'::text, exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'get_attendance_daily_late_arrivals'
  ), 'Función get_attendance_daily_late_arrivals en catálogo';

  v_grace := public.get_attendance_late_grace_minutes();
  return query select 'grace_minutes'::text, true, v_grace::text;

  if p_employee_name is not null then
    select p.id into v_employee_id
    from public.profiles p
    where lower(coalesce(p.full_name, p.username, '')) like '%' || lower(trim(p_employee_name)) || '%'
    order by p.full_name
    limit 1;

    return query select
      'employee_match'::text,
      v_employee_id is not null,
      coalesce(v_employee_id::text, 'Sin coincidencia para "' || p_employee_name || '"');
  end if;

  select count(*)::integer into v_schedule_count
  from public.employee_schedules s
  join public.profiles p on p.id = s.employee_id
  where s.shift_date = p_date
    and s.status in ('published', 'draft')
    and s.is_work_day
    and s.start_time is not null
    and (v_employee_id is null or s.employee_id = v_employee_id)
    and (p_employee_name is null or lower(coalesce(p.full_name, p.username, '')) like '%' || lower(trim(p_employee_name)) || '%');

  return query select
    'schedules_for_date'::text,
    v_schedule_count > 0,
    format('%s horario(s) laborales draft/published', v_schedule_count);

  select count(*)::integer into v_mark_count
  from public.attendance_marks m
  join public.profiles p on p.id = m.employee_id
  where m.mark_type = 'entrada'
    and (m.marked_at at time zone 'America/Guatemala')::date = p_date
    and (v_employee_id is null or m.employee_id = v_employee_id)
    and (p_employee_name is null or lower(coalesce(p.full_name, p.username, '')) like '%' || lower(trim(p_employee_name)) || '%');

  return query select
    'entrada_marks_for_date'::text,
    v_mark_count > 0,
    format('%s marcaje(s) de entrada en fecha local GT', v_mark_count);

  return query
  select
    'schedule_mark_join'::text,
    count(*) filter (where x.raw_late > v_grace) > 0,
    coalesce(string_agg(
      format('%s | prog=%s entrada=%s raw_late=%s min grace=%s status=%s',
        x.full_name,
        to_char(x.start_time, 'HH24:MI'),
        coalesce(to_char(x.check_in_local, 'HH24:MI'), 'sin entrada'),
        x.raw_late,
        v_grace,
        x.schedule_status
      ), E'\n' order by x.full_name
    ), 'Sin filas horario+entrada')
  from (
    select
      coalesce(p.full_name, p.username, 'Colaborador') as full_name,
      s.start_time,
      s.status as schedule_status,
      (m.marked_at at time zone 'America/Guatemala')::time as check_in_local,
      greatest(0, coalesce(extract(epoch from (
        m.marked_at at time zone 'America/Guatemala' - (s.shift_date + s.start_time)
      )) / 60, 0))::integer as raw_late
    from public.employee_schedules s
    join public.profiles p on p.id = s.employee_id
    left join lateral (
      select am.marked_at
      from public.attendance_marks am
      where am.employee_id = s.employee_id
        and am.mark_type = 'entrada'
        and (am.marked_at at time zone 'America/Guatemala')::date = s.shift_date
      order by am.marked_at asc
      limit 1
    ) m on true
    where s.shift_date = p_date
      and s.status in ('published', 'draft')
      and s.is_work_day
      and s.start_time is not null
      and (v_employee_id is null or s.employee_id = v_employee_id)
      and (p_employee_name is null or lower(coalesce(p.full_name, p.username, '')) like '%' || lower(trim(p_employee_name)) || '%')
  ) x;

  return query
  select
    'rpc_result'::text,
    count(*) > 0,
    coalesce(string_agg(
      format('%s late=%s min entrada=%s prog=%s',
        employee_name, late_minutes, check_in_local, scheduled_start
      ), E'\n'
    ), 'RPC get_attendance_daily_late_arrivals devolvió 0 filas')
  from public.get_attendance_daily_late_arrivals(p_date, v_employee_id);
end;
$$;


ALTER FUNCTION "public"."probe_attendance_late_arrival"("p_date" "date", "p_employee_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_checklist_coverage"("p_reference_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  coverage jsonb;
  alerts_sent integer := 0;
  auto_applied integer := 0;
  escalated integer := 0;
  availability_state text;
  availability_label text;
  suggested_id uuid;
  template_title text;
  original_name text;
  suggested_name text;
  role_value text;
begin
  if not public.can_assign_checklist_run_replacement() then
    raise exception 'No tienes permiso para procesar cobertura de checklists.';
  end if;

  for run_row in
    select r.*
    from public.checklist_runs r
    where r.status in ('pending', 'in_progress', 'rejected', 'overdue')
      and public.is_checklist_operational_window_open(r.run_date, p_reference_at)
  loop
    coverage := public.get_checklist_run_coverage_context(run_row.id, p_reference_at);
    availability_state := coalesce(coverage -> 'responsible_availability' ->> 'availability_state', 'unknown');
    availability_label := coalesce(coverage -> 'responsible_availability' ->> 'availability_label', 'No determinado');
    suggested_id := nullif(coverage ->> 'suggested_replacement_profile_id', '')::uuid;

    update public.checklist_runs
    set last_coverage_availability_state = availability_state
    where id = run_row.id;

    if coalesce((coverage ->> 'needs_coverage_alert')::boolean, false)
      and run_row.coverage_alert_notified_at is null then
      select title into template_title
      from public.checklist_templates
      where id = run_row.template_id;

      select coalesce(full_name, username, 'Colaborador') into original_name
      from public.profiles
      where id = coalesce(run_row.original_assigned_profile_id, run_row.assigned_profile_id);

      select coalesce(full_name, username, 'Colaborador') into suggested_name
      from public.profiles
      where id = suggested_id;

      foreach role_value in array array['admin', 'gerente_general', 'gerente']
      loop
        insert into public.notifications (
          user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
        )
        select
          null,
          role_value,
          'checklist_coverage',
          'Responsable no disponible',
          coalesce(template_title, 'Checklist')
            || ': '
            || coalesce(original_name, 'responsable')
            || ' no disponible ('
            || availability_label
            || ').'
            || case
              when suggested_name is not null then ' Reemplazo sugerido: ' || suggested_name || '.'
              else ' Escalar cobertura manualmente.'
            end,
          'checklist_run',
          run_row.id::text,
          '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
          null
        where not exists (
          select 1
          from public.notifications n
          where n.type = 'checklist_coverage'
            and n.entity_type = 'checklist_run'
            and n.entity_id = run_row.id::text
            and n.target_role = role_value
        );
      end loop;

      if run_row.supervisor_profile_id is not null then
        insert into public.notifications (
          user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
        )
        select
          run_row.supervisor_profile_id,
          null,
          'checklist_coverage',
          'Responsable no disponible',
          coalesce(template_title, 'Checklist')
            || ': '
            || coalesce(original_name, 'responsable')
            || ' no disponible ('
            || availability_label
            || ').',
          'checklist_run',
          run_row.id::text,
          '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
          null
        where not exists (
          select 1
          from public.notifications n
          where n.type = 'checklist_coverage'
            and n.entity_type = 'checklist_run'
            and n.entity_id = run_row.id::text
            and n.user_id = run_row.supervisor_profile_id
        );
      end if;

      if suggested_id is not null then
        insert into public.notifications (
          user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
        )
        select
          suggested_id,
          null,
          'checklist_coverage',
          'Posible cobertura de checklist',
          'Se sugiere cubrir '
            || coalesce(template_title, 'checklist')
            || ' porque '
            || coalesce(original_name, 'el responsable')
            || ' no esta disponible.',
          'checklist_run',
          run_row.id::text,
          '/tasks?tab=checklists&view=run&id=' || run_row.id::text,
          null
        where not exists (
          select 1
          from public.notifications n
          where n.type = 'checklist_coverage'
            and n.entity_type = 'checklist_run'
            and n.entity_id = run_row.id::text
            and n.user_id = suggested_id
        );
      else
        update public.checklist_runs
        set coverage_escalated_at = coalesce(coverage_escalated_at, now())
        where id = run_row.id;
        escalated := escalated + 1;
      end if;

      update public.checklist_runs
      set coverage_alert_notified_at = now()
      where id = run_row.id;

      alerts_sent := alerts_sent + 1;
    end if;

    if public._apply_checklist_auto_coverage(run_row.id, p_reference_at) is not null then
      auto_applied := auto_applied + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'alerts_sent', alerts_sent,
    'auto_applied', auto_applied,
    'escalated', escalated
  );
end;
$$;


ALTER FUNCTION "public"."process_checklist_coverage"("p_reference_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pending_task_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row record;
  v_count int := 0;
begin
  for v_row in
    select r.*
    from public.task_reminder_deliveries r
    where r.delivery_status = 'pending'
      and r.reminder_at <= now()
    order by r.reminder_at asc
    limit 200
  loop
    perform public.notify_operational_task_event(
      v_row.profile_id,
      'task_reminder',
      'Recordatorio de tarea',
      'Tienes un recordatorio pendiente.',
      v_row.task_id
    );
    update public.task_reminder_deliveries
    set delivery_status = 'sent', delivered_at = now()
    where id = v_row.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."process_pending_task_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_test_purchase_order_receipt"("p_order" "public"."purchase_orders") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item_data jsonb;
  catalog_item public.inventory_items;
  qty numeric;
  sku_text text;
begin
  if not coalesce(p_order.is_test, false) then
    return;
  end if;

  for item_data in
    select value
    from jsonb_array_elements(coalesce(p_order.data -> 'items', '[]'::jsonb))
  loop
    qty := coalesce(
      nullif(item_data ->> 'cantidadRecibidaReal', '')::numeric,
      nullif(item_data ->> 'cantidadComprar', '')::numeric,
      nullif(item_data ->> 'quantity', '')::numeric,
      0
    );
    if qty <= 0 then
      continue;
    end if;

    sku_text := nullif(trim(coalesce(item_data ->> 'sku', item_data ->> 'codigo', item_data ->> 'codigoBarras', '')), '');
    select * into catalog_item
    from public.inventory_items
    where active = true
      and (
        (sku_text is not null and sku = sku_text)
        or lower(name) = lower(coalesce(item_data ->> 'nombre', item_data ->> 'name', ''))
      )
    order by created_at
    limit 1;

    if catalog_item.id is null then
      continue;
    end if;

    insert into public.inventory_movements (
      item_id, movement_type, to_area_id, quantity, unit,
      previous_quantity, new_quantity, source_type, source_id, notes, performed_by, is_test
    ) values (
      catalog_item.id,
      'purchase',
      'almacen',
      qty,
      coalesce(catalog_item.base_unit, 'unidad'),
      null,
      null,
      'purchase_order_test',
      p_order.id,
      'PRUEBA: recepcion simulada de ' || coalesce(p_order.order_number, p_order.id),
      auth.uid(),
      true
    );
  end loop;
end;
$$;


ALTER FUNCTION "public"."process_test_purchase_order_receipt"("p_order" "public"."purchase_orders") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profile_has_operational_history"("p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    exists (select 1 from public.attendance_marks where employee_id = p_profile_id)
    or exists (select 1 from public.pos_orders where waiter_id = p_profile_id)
    or exists (select 1 from public.cash_sessions where opened_by = p_profile_id)
    or exists (select 1 from public.cash_movements where created_by = p_profile_id)
    or exists (
      select 1 from public.requisitions
      where requested_by = p_profile_id
         or approved_by = p_profile_id
         or completed_by = p_profile_id
    )
    or exists (
      select 1 from public.checklist_runs
      where assigned_profile_id = p_profile_id
         or completed_by = p_profile_id
    )
    or exists (select 1 from public.employee_file_profiles where profile_id = p_profile_id)
    or exists (select 1 from public.employee_incidents where profile_id = p_profile_id)
    or exists (select 1 from public.checklist_management_alerts where sender_profile_id = p_profile_id)
    or exists (
      select 1 from public.catering_requests
      where created_by = p_profile_id
         or updated_by = p_profile_id
    )
    or exists (select 1 from public.inventory_movements where performed_by = p_profile_id)
    or exists (
      select 1 from public.production_batches
      where produced_by = p_profile_id
         or approved_by = p_profile_id
    )
    or exists (select 1 from public.checklist_session_audit where profile_id = p_profile_id)
    or exists (select 1 from public.yield_audits where employee_id = p_profile_id);
$$;


ALTER FUNCTION "public"."profile_has_operational_history"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_inventory_migration_mode_setting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.key <> 'inventory_migration_mode' then
    return new;
  end if;

  if auth.uid() is null then
    return new;
  end if;

  if public.normalize_profile_role(public.current_profile_role()) <> 'admin' then
    raise exception 'No tiene permisos para modificar el Modo Migración. Solo un Administrador del sistema puede realizar esta acción.';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."protect_inventory_migration_mode_setting"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_profile_managed_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_role text;
  old_role text := public.normalize_profile_role(old.role);
  new_role text := public.normalize_profile_role(new.role);
begin
  select public.normalize_profile_role(role) into actor_role
  from public.profiles
  where id = auth.uid();

  if actor_role = 'admin' then
    new.updated_at := now();
    return new;
  end if;

  if actor_role = 'gerente_general' then
    if old_role = 'admin' or new_role = 'admin' then
      raise exception 'No tienes permisos para editar este usuario.';
    end if;
    new.updated_at := now();
    return new;
  end if;

  if actor_role = 'recursos_humanos' then
    if old_role in ('admin', 'gerente_general') then
      raise exception 'No tienes permisos para editar este usuario.';
    end if;
    if new_role in ('admin', 'gerente_general') then
      raise exception 'No tienes permisos para asignar este rol.';
    end if;
    if row(new.id, new.created_at) is distinct from row(old.id, old.created_at) then
      raise exception 'No tienes permisos para editar este usuario.';
    end if;
    new.updated_at := now();
    return new;
  end if;

  if auth.uid() = old.id then
    if row(
      new.id, new.full_name, new.username, new.role, new.area_id, new.area_name,
      new.employee_id, new.status, new.created_at
    ) is distinct from row(
      old.id, old.full_name, old.username, old.role, old.area_id, old.area_name,
      old.employee_id, old.status, old.created_at
    ) then
      raise exception 'Solo Administracion puede modificar datos laborales o de acceso.';
    end if;
    new.updated_at := now();
    return new;
  end if;

  raise exception 'No tienes permiso para modificar este perfil.';
end;
$$;


ALTER FUNCTION "public"."protect_profile_managed_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_operational_station"("p_station_code" "text", "p_name" "text", "p_station_type" "text", "p_area_id" "text" DEFAULT NULL::"text", "p_cash_register_id" "uuid" DEFAULT NULL::"uuid", "p_pos_floor_zone" "text" DEFAULT NULL::"text") RETURNS "public"."operational_stations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.operational_stations;
  v_mode text := case when p_station_type in ('kds', 'production') then 'team' else 'individual' end;
begin
  if not public.is_operational_stations_admin() then
    raise exception 'No autorizado.';
  end if;
  insert into public.operational_stations (
    station_code, name, station_type, status, area_id, cash_register_id,
    pos_floor_zone, identity_mode, created_by
  )
  values (
    lower(trim(p_station_code)),
    trim(p_name),
    lower(trim(p_station_type)),
    'draft',
    nullif(trim(p_area_id), ''),
    p_cash_register_id,
    nullif(trim(p_pos_floor_zone), ''),
    v_mode,
    auth.uid()
  )
  returning * into v_row;
  perform public.log_operational_station_event(
    v_row.id, null, 'station_created', auth.uid(),
    jsonb_build_object('station_code', v_row.station_code), null
  );
  return v_row;
end;
$$;


ALTER FUNCTION "public"."provision_operational_station"("p_station_code" "text", "p_name" "text", "p_station_type" "text", "p_area_id" "text", "p_cash_register_id" "uuid", "p_pos_floor_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_schedule_week"("p_week_start" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  affected integer;
  employee_record record;
begin
  if not public.is_schedule_publisher() then
    raise exception 'No tienes permiso para publicar horarios.';
  end if;
  insert into public.schedule_change_logs (schedule_id, changed_by, change_type, old_value, new_value)
  select id, auth.uid(), 'published', to_jsonb(s), to_jsonb(s) || jsonb_build_object('status', 'published', 'published_at', now())
  from public.employee_schedules s
  where shift_date between p_week_start and p_week_start + 6
    and status = 'draft';
  update public.employee_schedules set
    status = 'published', published_at = now(), updated_by = auth.uid(), updated_at = now()
  where shift_date between p_week_start and p_week_start + 6
    and status = 'draft';
  get diagnostics affected = row_count;
  for employee_record in
    select distinct employee_id from public.employee_schedules
    where shift_date between p_week_start and p_week_start + 6 and status = 'published'
  loop
    insert into public.notifications (user_id, type, title, message, entity_type, entity_id)
    values (employee_record.employee_id, 'schedule_published', 'Horario semanal publicado', 'Tu horario semanal ha sido publicado.', 'schedule_week', p_week_start::text);
  end loop;
  return affected;
end;
$$;


ALTER FUNCTION "public"."publish_schedule_week"("p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_old_security_login_logs"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempts_deleted integer := 0;
  v_captcha_deleted integer := 0;
  v_cutoff timestamptz := now() - make_interval(days => public.login_security_retention_days());
begin
  delete from public.security_login_attempts attempt
  where attempt.created_at < v_cutoff;
  get diagnostics v_attempts_deleted = row_count;

  delete from public.login_captcha_sessions session
  where session.expires_at < now() - interval '7 days';
  get diagnostics v_captcha_deleted = row_count;

  return jsonb_build_object(
    'attempts_deleted', v_attempts_deleted,
    'captcha_sessions_deleted', v_captcha_deleted,
    'retention_days', public.login_security_retention_days(),
    'cutoff', v_cutoff
  );
end;
$$;


ALTER FUNCTION "public"."purge_old_security_login_logs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_old_security_login_logs"() IS 'Deletes security_login_attempts older than 90 days and expired CAPTCHA sessions older than 7 days.';



CREATE OR REPLACE FUNCTION "public"."purge_stale_discarded_recruitment_candidates"("p_retention_days" integer DEFAULT 60) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_deleted integer := 0;
begin
  if p_retention_days is null or p_retention_days < 1 then
    raise exception 'p_retention_days debe ser mayor o igual a 1.';
  end if;

  delete from public.recruitment_candidates c
  where c.pipeline_status = 'discarded'
    and not exists (
      select 1
      from public.recruitment_employee_origins o
      where o.candidate_id = c.id
    )
    and exists (
      select 1
      from public.recruitment_candidate_status_history h
      where h.candidate_id = c.id
        and h.to_status = 'discarded'
        and h.changed_at < now() - make_interval(days => p_retention_days)
    );

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


ALTER FUNCTION "public"."purge_stale_discarded_recruitment_candidates"("p_retention_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_checklist_run_points"("p_run_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.checklist_runs run
  set
    total_points = coalesce(points.total_points, 0),
    earned_points = coalesce(points.earned_points, 0),
    updated_at = now()
  from (
    select
      run_id,
      sum(score_points)::integer as total_points,
      sum(earned_points)::integer as earned_points
    from public.checklist_run_items
    where run_id = p_run_id
    group by run_id
  ) points
  where run.id = p_run_id;
end;
$$;


ALTER FUNCTION "public"."recalculate_checklist_run_points"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_operational_process_run_status"("p_process_run_id" "uuid") RETURNS "public"."operational_process_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.operational_process_runs;
  v_required integer := 0;
  v_completed integer := 0;
  v_any_active boolean := false;
  v_any_cancelled_required boolean := false;
begin
  if p_process_run_id is null then
    raise exception 'p_process_run_id es obligatorio.';
  end if;

  select * into v_run from public.operational_process_runs where id = p_process_run_id for update;
  if v_run.id is null then
    raise exception 'Proceso operativo no encontrado.';
  end if;

  if v_run.status = 'cancelled' then
    return v_run;
  end if;

  select
    count(*) filter (where rs.is_required),
    count(*) filter (where rs.is_required and cr.status = 'completed'),
    bool_or(cr.status in ('in_progress', 'completed', 'pending_review')),
    bool_or(rs.is_required and cr.status = 'cancelled')
  into v_required, v_completed, v_any_active, v_any_cancelled_required
  from public.operational_process_run_steps rs
  join public.checklist_runs cr on cr.id = rs.checklist_run_id
  where rs.process_run_id = p_process_run_id;

  if coalesce(v_required, 0) > 0 and v_completed = v_required then
    update public.operational_process_runs
    set status = 'completed',
        completed_at = coalesce(completed_at, now()),
        started_at = coalesce(started_at, now()),
        updated_at = now()
    where id = p_process_run_id
    returning * into v_run;
  elsif v_any_active or v_completed > 0 then
    update public.operational_process_runs
    set status = 'in_progress',
        started_at = coalesce(started_at, now()),
        completed_at = null,
        updated_at = now()
    where id = p_process_run_id
    returning * into v_run;
  else
    update public.operational_process_runs
    set status = 'pending',
        completed_at = null,
        updated_at = now()
    where id = p_process_run_id
    returning * into v_run;
  end if;

  return v_run;
end;
$$;


ALTER FUNCTION "public"."recalculate_operational_process_run_status"("p_process_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_recipes_for_inventory_item"("p_item_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recipe_row record;
  ingredient_row record;
  total_cost numeric;
  unit_cost numeric;
  updated_count integer := 0;
  ingredient_cost numeric;
  usable numeric;
begin
  for recipe_row in
    select distinct sr.*
    from public.standard_recipes sr
    join public.recipe_ingredients ri on ri.recipe_id = sr.id
    where ri.inventory_item_id = p_item_id
      and sr.active = true
  loop
    total_cost := 0;
    for ingredient_row in
      select ri.*, ii.usable_cost, ii.cost_per_base_unit, ii.weighted_average_cost
      from public.recipe_ingredients ri
      join public.inventory_items ii on ii.id = ri.inventory_item_id
      where ri.recipe_id = recipe_row.id
    loop
      usable := coalesce(nullif(ingredient_row.usable_cost, 0), ingredient_row.cost_per_base_unit, 0);
      ingredient_cost := coalesce(ingredient_row.inventory_quantity, ingredient_row.quantity, 0) * usable;
      total_cost := total_cost + ingredient_cost;
    end loop;

    unit_cost := case
      when coalesce(recipe_row.yield_quantity, 0) > 0 then total_cost / recipe_row.yield_quantity
      else total_cost
    end;

    update public.standard_recipes
    set
      estimated_cost = total_cost,
      recipe_current_cost = total_cost,
      recipe_food_cost_percent = recipe_row.target_food_cost_percent,
      last_cost_update = now(),
      updated_at = now()
    where id = recipe_row.id;

    insert into public.recipe_cost_history (recipe_id, cost, food_cost_percent, gross_margin, notes)
    values (
      recipe_row.id,
      total_cost,
      recipe_row.target_food_cost_percent,
      null,
      'Recalculado por cambio de costo utilizable'
    );

    updated_count := updated_count + 1;
  end loop;

  return updated_count;
end;
$$;


ALTER FUNCTION "public"."recalculate_recipes_for_inventory_item"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_purchase_order_lines"("p_purchase_order_id" "text", "p_supplier_name" "text", "p_lines" "jsonb", "p_invoice" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.purchase_orders;
  v_line jsonb;
  v_po_line jsonb;
  v_item public.inventory_items;
  v_item_id uuid;
  v_receipt public.purchase_order_receipts;
  v_receipt_line public.purchase_order_receipt_lines;
  v_supplier_name text := coalesce(nullif(trim(p_supplier_name), ''), 'Sin proveedor');
  v_supplier_id uuid;
  v_target_area text;
  v_is_test boolean;
  v_stock_before numeric;
  v_stock_total_before numeric;
  v_current_cost numeric;
  v_new_cost numeric;
  v_qty_ordered numeric;
  v_qty_ordered_base numeric;
  v_qty_received numeric;
  v_qty_received_base numeric;
  v_cumulative_base numeric;
  v_factor numeric;
  v_unit_cost_purchase numeric;
  v_unit_cost_base numeric;
  v_subtotal numeric;
  v_stock_after numeric;
  v_yield_pct numeric;
  v_usable_cost numeric;
  v_invoice_number text;
  v_invoice_date date;
  v_invoice_image_url text;
  v_invoice_notes text;
  v_all_complete boolean := true;
  v_any_received boolean := false;
  v_new_status text;
  v_progress numeric;
  v_recepcion_summary jsonb;
  v_result_lines jsonb := '[]'::jsonb;
  v_po_items jsonb;
  v_found boolean;
  v_profile public.inventory_yield_profiles;
  v_client_request_id uuid;
  v_touched_item_ids uuid[] := array[]::uuid[];
  v_recipe_item_id uuid;
begin
  if not public.can_receive_purchase_orders() then
    raise exception 'No tienes permiso para recibir ordenes de compra.';
  end if;

  if nullif(trim(p_purchase_order_id), '') is null then
    raise exception 'La orden de compra es obligatoria.';
  end if;

  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Debes indicar al menos una linea para recibir.';
  end if;

  select * into v_order
  from public.purchase_orders
  where id = trim(p_purchase_order_id)
  for update;

  if v_order.id is null then
    raise exception 'Orden de compra no encontrada.';
  end if;

  if v_order.status in ('borrador', 'pendiente_aprobacion', 'rechazada', 'cancelada') then
    raise exception 'La orden no esta lista para recepcion (estado: %).', v_order.status;
  end if;

  if v_order.status not in ('aprobada', 'enviada_proveedor', 'recibida_parcial', 'recibida_completa') then
    raise exception 'La orden no puede recibirse en estado %.', v_order.status;
  end if;

  v_is_test := coalesce(v_order.is_test, false);
  v_target_area := public.po_receiving_target_area(v_order.data);
  v_po_items := coalesce(v_order.data -> 'items', '[]'::jsonb);

  v_client_request_id := nullif(trim(p_invoice ->> 'client_request_id'), '')::uuid;

  if v_client_request_id is not null then
    select * into v_receipt
    from public.purchase_order_receipts
    where purchase_order_id = v_order.id
      and client_request_id = v_client_request_id
    limit 1;

    if v_receipt.id is not null then
      return public.po_build_receipt_rpc_result(v_receipt.id, v_order, true);
    end if;
  end if;

  if public.po_order_receiving_is_complete(v_order.id, v_is_test) then
    raise exception
      'La orden % ya esta completamente recibida. No quedan productos pendientes.',
      coalesce(v_order.order_number, v_order.id);
  end if;

  v_invoice_number := nullif(trim(p_invoice ->> 'invoice_number'), '');
  v_invoice_date := nullif(trim(p_invoice ->> 'invoice_date'), '')::date;
  v_invoice_image_url := coalesce(
    nullif(trim(p_invoice ->> 'invoice_image_url'), ''),
    nullif(trim(p_invoice ->> 'invoice_image_base64'), '')
  );
  v_invoice_notes := nullif(trim(p_invoice ->> 'notes'), '');

  select s.id into v_supplier_id
  from public.suppliers s
  where lower(trim(s.name)) = lower(v_supplier_name)
  limit 1;

  insert into public.purchase_order_receipts (
    purchase_order_id,
    supplier_id,
    supplier_name,
    invoice_number,
    invoice_date,
    invoice_image_url,
    received_by,
    notes,
    is_test,
    client_request_id
  ) values (
    v_order.id,
    v_supplier_id,
    v_supplier_name,
    v_invoice_number,
    v_invoice_date,
    v_invoice_image_url,
    auth.uid(),
    v_invoice_notes,
    v_is_test,
    v_client_request_id
  )
  returning * into v_receipt;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_item_id := nullif(trim(v_line ->> 'item_id'), '')::uuid;
    if v_item_id is null then
      raise exception 'Cada linea debe incluir item_id valido.';
    end if;

    v_qty_received := coalesce(
      nullif(trim(v_line ->> 'qty_received'), '')::numeric,
      nullif(trim(v_line ->> 'cantidadRecibida'), '')::numeric,
      0
    );
    if v_qty_received <= 0 then
      raise exception 'La cantidad recibida debe ser mayor que cero.';
    end if;

    select * into v_item from public.inventory_items where id = v_item_id;
    if v_item.id is null then
      raise exception 'Producto % no encontrado en inventario.', v_item_id;
    end if;

    v_po_line := null;
    v_found := false;
    for v_po_line in select value from jsonb_array_elements(v_po_items)
    loop
      if public.po_line_item_id(v_po_line) = v_item_id then
        v_found := true;
        exit;
      end if;
    end loop;

    if not v_found then
      raise exception 'El producto % no pertenece a la orden %.', v_item.name, v_order.order_number;
    end if;

    v_factor := public.po_line_conversion_factor(v_po_line, v_item);
    v_qty_ordered := public.po_line_qty_ordered(v_po_line);
    v_qty_ordered_base := v_qty_ordered * v_factor;
    v_qty_received_base := v_qty_received * v_factor;
    v_cumulative_base := public.po_item_received_base(v_order.id, v_item_id, v_is_test);

    if v_cumulative_base + v_qty_received_base > v_qty_ordered_base + public.po_receipt_qty_tolerance() then
      raise exception
        'Sobre-recepcion para %: pedido % base, ya recibido % base, intento % base.',
        v_item.name,
        round(v_qty_ordered_base, 3),
        round(v_cumulative_base, 3),
        round(v_qty_received_base, 3);
    end if;

    v_unit_cost_purchase := coalesce(
      nullif(trim(v_line ->> 'unit_cost_purchase'), '')::numeric,
      nullif(trim(v_line ->> 'costoUnitario'), '')::numeric,
      nullif(trim(v_po_line ->> 'costoUnitario'), '')::numeric,
      nullif(trim(v_po_line ->> 'precio_unitario_compra'), '')::numeric,
      v_item.purchase_price,
      v_item.cost_per_base_unit,
      0
    );
    v_unit_cost_base := case
      when v_unit_cost_purchase > 0 then v_unit_cost_purchase / v_factor
      else coalesce(v_item.cost_per_base_unit, 0)
    end;
    v_subtotal := v_qty_received * v_unit_cost_purchase;

    insert into public.purchase_order_receipt_lines (
      receipt_id,
      purchase_order_id,
      item_id,
      item_name,
      supplier_name,
      qty_ordered,
      qty_received,
      qty_received_base,
      purchase_unit,
      base_unit,
      conversion_factor,
      unit_cost_purchase,
      unit_cost_base,
      subtotal,
      notes
    ) values (
      v_receipt.id,
      v_order.id,
      v_item_id,
      coalesce(v_item.name, nullif(trim(v_po_line ->> 'nombre'), ''), 'Producto'),
      coalesce(
        nullif(trim(v_line ->> 'supplier_name'), ''),
        public.po_line_supplier_name(v_po_line, v_supplier_name)
      ),
      v_qty_ordered,
      v_qty_received,
      v_qty_received_base,
      coalesce(nullif(trim(v_po_line ->> 'unidadCompra'), ''), nullif(trim(v_po_line ->> 'unidad_compra'), ''), v_item.purchase_unit),
      v_item.base_unit,
      v_factor,
      v_unit_cost_purchase,
      v_unit_cost_base,
      v_subtotal,
      nullif(trim(v_line ->> 'notes'), '')
    )
    returning * into v_receipt_line;

    v_result_lines := v_result_lines || jsonb_build_array(to_jsonb(v_receipt_line));
    v_any_received := true;

    if not v_is_test then
      insert into public.area_inventory (item_id, area_id, quantity, minimum_quantity)
      values (v_item_id, v_target_area, 0, 0)
      on conflict (item_id, area_id) do nothing;

      select coalesce(quantity, 0) into v_stock_before
      from public.area_inventory
      where item_id = v_item_id and area_id = v_target_area
      for update;

      select * into v_item
      from public.inventory_items
      where id = v_item_id
      for update;

      select coalesce(sum(quantity), 0) into v_stock_total_before
      from public.area_inventory
      where item_id = v_item_id;

      v_current_cost := coalesce(v_item.cost_per_base_unit, 0);

      if v_stock_total_before + v_qty_received_base > 0 and v_unit_cost_base >= 0 then
        v_new_cost := case
          when v_stock_total_before <= 0 then v_unit_cost_base
          else ((v_stock_total_before * v_current_cost) + (v_qty_received_base * v_unit_cost_base))
            / (v_stock_total_before + v_qty_received_base)
        end;
      else
        v_new_cost := v_unit_cost_base;
      end if;

      v_stock_after := v_stock_before + v_qty_received_base;

      update public.area_inventory
      set quantity = v_stock_after, updated_at = now()
      where item_id = v_item_id and area_id = v_target_area;

      insert into public.inventory_movements (
        item_id,
        movement_type,
        to_area_id,
        quantity,
        unit,
        previous_quantity,
        new_quantity,
        source_type,
        source_id,
        notes,
        performed_by,
        is_test,
        unit_cost_base,
        unit_cost_purchase,
        receipt_id,
        receipt_line_id,
        purchase_order_id,
        invoice_number
      ) values (
        v_item_id,
        'purchase',
        v_target_area,
        v_qty_received_base,
        coalesce(v_item.base_unit, 'unidad'),
        v_stock_before,
        v_stock_after,
        'purchase_order_receipt',
        v_receipt.id::text,
        'Recepcion OC ' || coalesce(v_order.order_number, v_order.id)
          || ' proveedor ' || v_supplier_name
          || case when v_invoice_number is not null then ' factura ' || v_invoice_number else '' end,
        auth.uid(),
        false,
        v_unit_cost_base,
        v_unit_cost_purchase,
        v_receipt.id,
        v_receipt_line.id,
        v_order.id,
        v_invoice_number
      );

      select * into v_profile
      from public.inventory_yield_profiles
      where inventory_item_id = v_item_id and active = true;

      v_yield_pct := coalesce(v_profile.expected_yield_percent, 100);
      if v_yield_pct <= 0 then
        v_yield_pct := 100;
      end if;
      v_usable_cost := case when v_new_cost > 0 then v_new_cost / (v_yield_pct / 100.0) else 0 end;

      update public.inventory_items
      set
        cost_per_base_unit = v_new_cost,
        purchase_price = v_unit_cost_purchase,
        weighted_average_cost = v_new_cost,
        usable_cost = v_usable_cost,
        updated_at = now()
      where id = v_item_id;

      if not v_item_id = any(v_touched_item_ids) then
        v_touched_item_ids := array_append(v_touched_item_ids, v_item_id);
      end if;
    else
      insert into public.inventory_movements (
        item_id,
        movement_type,
        to_area_id,
        quantity,
        unit,
        source_type,
        source_id,
        notes,
        performed_by,
        is_test,
        unit_cost_base,
        unit_cost_purchase,
        receipt_id,
        receipt_line_id,
        purchase_order_id,
        invoice_number
      ) values (
        v_item_id,
        'purchase',
        v_target_area,
        v_qty_received_base,
        coalesce(v_item.base_unit, 'unidad'),
        'purchase_order_receipt_test',
        v_receipt.id::text,
        'PRUEBA: recepcion OC ' || coalesce(v_order.order_number, v_order.id),
        auth.uid(),
        true,
        v_unit_cost_base,
        v_unit_cost_purchase,
        v_receipt.id,
        v_receipt_line.id,
        v_order.id,
        v_invoice_number
      );
    end if;
  end loop;

  if not v_is_test then
    foreach v_recipe_item_id in array v_touched_item_ids
    loop
      perform public.recalculate_recipes_for_inventory_item(v_recipe_item_id);
    end loop;
  end if;

  -- Determine order completion across all PO items
  for v_po_line in select value from jsonb_array_elements(v_po_items)
  loop
    v_item_id := public.po_line_item_id(v_po_line);
    if v_item_id is null then
      continue;
    end if;
    select * into v_item from public.inventory_items where id = v_item_id;
    v_factor := public.po_line_conversion_factor(v_po_line, v_item);
    v_qty_ordered_base := public.po_line_qty_ordered(v_po_line) * v_factor;
    if v_qty_ordered_base <= 0 then
      continue;
    end if;
    v_cumulative_base := public.po_item_received_base(v_order.id, v_item_id, v_is_test);
    if v_cumulative_base + public.po_receipt_qty_tolerance() < v_qty_ordered_base then
      v_all_complete := false;
    end if;
  end loop;

  if v_all_complete then
    v_new_status := 'recibida_completa';
  elsif v_any_received then
    v_new_status := 'recibida_parcial';
  else
    v_new_status := v_order.status;
  end if;

  v_progress := (select (payload ->> 'progress_percent')::numeric
    from (
      select public.get_purchase_order_receiving_progress(v_order.id) as payload
    ) q);

  v_recepcion_summary := jsonb_build_object(
    'last_receipt_id', v_receipt.id,
    'last_supplier_name', v_supplier_name,
    'last_invoice_number', v_invoice_number,
    'last_received_at', v_receipt.received_at,
    'progress_percent', v_progress,
    'status', v_new_status,
    'legacy_note', 'Resumen; historial completo en purchase_order_receipts'
  );

  update public.purchase_orders
  set
    status = v_new_status,
    data = coalesce(v_order.data, '{}'::jsonb)
      || jsonb_build_object(
        'status', v_new_status,
        'recepcion_status', v_new_status,
        'receiving_progress_percent', v_progress,
        'recepcion', v_recepcion_summary
      ),
    updated_at = now()
  where id = v_order.id
  returning * into v_order;

  return jsonb_build_object(
    'receipt_id', v_receipt.id,
    'purchase_order_id', v_order.id,
    'order_number', v_order.order_number,
    'status', v_order.status,
    'progress_percent', v_progress,
    'lines', v_result_lines,
    'is_test', v_is_test,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."receive_purchase_order_lines"("p_purchase_order_id" "text", "p_supplier_name" "text", "p_lines" "jsonb", "p_invoice" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_billing_certification_attempt"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt_id uuid;
  v_provider_config_id uuid;
  v_operation text;
  v_status text;
begin
  v_provider_config_id := nullif(p_payload ->> 'provider_config_id', '')::uuid;
  v_operation := coalesce(p_payload ->> 'operation', 'test_connection');
  v_status := coalesce(p_payload ->> 'status', 'failed');

  insert into public.billing_certification_attempts (
    document_id,
    provider_config_id,
    legal_entity_id,
    provider_code,
    adapter_version,
    attempt_number,
    operation,
    status,
    request_payload,
    response_payload,
    error_codes,
    error_messages,
    http_status,
    duration_ms,
    created_by
  ) values (
    nullif(p_payload ->> 'document_id', '')::uuid,
    v_provider_config_id,
    nullif(p_payload ->> 'legal_entity_id', '')::uuid,
    coalesce(p_payload ->> 'provider_code', 'unknown'),
    coalesce(p_payload ->> 'adapter_version', '0.0.0'),
    coalesce((p_payload ->> 'attempt_number')::integer, 1),
    v_operation,
    v_status,
    coalesce(p_payload -> 'request_payload', '{}'::jsonb),
    coalesce(p_payload -> 'response_payload', '{}'::jsonb),
    coalesce(
      (select array_agg(value) from jsonb_array_elements_text(coalesce(p_payload -> 'error_codes', '[]'::jsonb)) as value),
      '{}'::text[]
    ),
    coalesce(p_payload -> 'error_messages', '[]'::jsonb),
    nullif(p_payload ->> 'http_status', '')::integer,
    nullif(p_payload ->> 'duration_ms', '')::integer,
    nullif(p_payload ->> 'created_by', '')::uuid
  ) returning id into v_attempt_id;

  if v_provider_config_id is not null and v_operation in ('test_connection', 'credits_check') then
    update public.billing_provider_status st
    set
      adapter_version = coalesce(p_payload ->> 'adapter_version', st.adapter_version),
      connection_status = case
        when v_status = 'success' then 'healthy'
        else 'error'
      end,
      last_test_at = now(),
      last_test_success = (v_status = 'success'),
      last_test_duration_ms = nullif(p_payload ->> 'duration_ms', '')::integer,
      last_test_error_summary = nullif(p_payload ->> 'error_summary', ''),
      last_test_error_codes = coalesce(
        (select array_agg(value) from jsonb_array_elements_text(coalesce(p_payload -> 'error_codes', '[]'::jsonb)) as value),
        '{}'::text[]
      ),
      last_known_credits = nullif(p_payload ->> 'credits', '')::integer,
      last_successful_connection_at = case when v_status = 'success' then now() else st.last_successful_connection_at end,
      last_error_at = case when v_status = 'success' then st.last_error_at else now() end,
      last_error_summary = case when v_status = 'success' then st.last_error_summary else nullif(p_payload ->> 'error_summary', '') end,
      updated_at = now()
    where st.provider_config_id = v_provider_config_id;
  end if;

  return v_attempt_id;
end;
$$;


ALTER FUNCTION "public"."record_billing_certification_attempt"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_cash_sale"("p_order_id" "uuid", "p_amount" numeric) RETURNS "public"."cash_movements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.cash_sessions;
begin
  if not public.is_cash_operator() then
    raise exception 'No tienes permiso para registrar ventas en efectivo.';
  end if;
  select * into session_row
  from public.cash_sessions
  where status = 'open'
  order by opened_at desc
  limit 1;
  if session_row.id is null then
    raise exception 'No hay caja abierta. Abre caja antes de cobrar en efectivo.';
  end if;
  return public.create_cash_movement(
    session_row.id,
    'sale_cash',
    p_amount,
    'Venta en efectivo POS',
    p_order_id::text,
    p_order_id
  );
end;
$$;


ALTER FUNCTION "public"."record_cash_sale"("p_order_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_finance_payable_payment"("p_payable_id" "uuid", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payable public.finance_payables;
  v_payment public.finance_payable_payments;
  v_amount numeric := (p_data ->> 'amount')::numeric;
  v_bank_id uuid := nullif(p_data ->> 'bank_account_id', '')::uuid;
begin
  if not public.can_view_finance() then
    raise exception 'No tienes permiso para registrar pagos.';
  end if;

  if v_amount is null or v_amount <= 0 then
    raise exception 'El monto debe ser mayor a cero.';
  end if;

  select * into v_payable from public.finance_payables where id = p_payable_id for update;
  if not found then raise exception 'Cuenta por pagar no encontrada.'; end if;
  if v_payable.status = 'cancelled' then raise exception 'La cuenta por pagar está cancelada.'; end if;

  insert into public.finance_payable_payments (
    payable_id, bank_account_id, payment_date, amount, method, reference, notes, created_by
  )
  values (
    p_payable_id,
    v_bank_id,
    coalesce((p_data ->> 'payment_date')::date, (now() at time zone 'America/Guatemala')::date),
    v_amount,
    coalesce(p_data ->> 'method', 'bank_transfer'),
    nullif(trim(p_data ->> 'reference'), ''),
    nullif(trim(p_data ->> 'notes'), ''),
    auth.uid()
  )
  returning * into v_payment;

  update public.finance_payables
  set paid_amount = paid_amount + v_amount
  where id = p_payable_id;

  if v_bank_id is not null then
    perform public.create_finance_bank_transaction(jsonb_build_object(
      'bank_account_id', v_bank_id,
      'transaction_date', v_payment.payment_date,
      'type', 'withdrawal',
      'description', 'Pago a ' || v_payable.supplier_name,
      'reference', v_payment.reference,
      'amount', v_amount,
      'direction', 'out',
      'source_module', 'finance',
      'source_id', v_payment.id
    ));
  end if;

  perform public.finance_refresh_payable_status(p_payable_id);
  select * into v_payable from public.finance_payables where id = p_payable_id;

  return jsonb_build_object('payment', to_jsonb(v_payment), 'payable', to_jsonb(v_payable));
end;
$$;


ALTER FUNCTION "public"."record_finance_payable_payment"("p_payable_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_finance_receivable_collection"("p_receivable_id" "uuid", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_receivable public.finance_receivables;
  v_collection public.finance_receivable_collections;
  v_amount numeric := (p_data ->> 'amount')::numeric;
  v_bank_id uuid := nullif(p_data ->> 'bank_account_id', '')::uuid;
begin
  if not public.can_view_finance() then
    raise exception 'No tienes permiso para registrar cobros.';
  end if;

  if v_amount is null or v_amount <= 0 then
    raise exception 'El monto debe ser mayor a cero.';
  end if;

  select * into v_receivable from public.finance_receivables where id = p_receivable_id for update;
  if not found then raise exception 'Cuenta por cobrar no encontrada.'; end if;
  if v_receivable.status = 'cancelled' then raise exception 'La cuenta por cobrar está cancelada.'; end if;

  insert into public.finance_receivable_collections (
    receivable_id, bank_account_id, collection_date, amount, method, reference, notes, created_by
  )
  values (
    p_receivable_id,
    v_bank_id,
    coalesce((p_data ->> 'collection_date')::date, (now() at time zone 'America/Guatemala')::date),
    v_amount,
    coalesce(p_data ->> 'method', 'bank_transfer'),
    nullif(trim(p_data ->> 'reference'), ''),
    nullif(trim(p_data ->> 'notes'), ''),
    auth.uid()
  )
  returning * into v_collection;

  update public.finance_receivables
  set collected_amount = collected_amount + v_amount
  where id = p_receivable_id;

  if v_bank_id is not null then
    perform public.create_finance_bank_transaction(jsonb_build_object(
      'bank_account_id', v_bank_id,
      'transaction_date', v_collection.collection_date,
      'type', 'deposit',
      'description', 'Cobro de ' || v_receivable.customer_name,
      'reference', v_collection.reference,
      'amount', v_amount,
      'direction', 'in',
      'source_module', 'finance',
      'source_id', v_collection.id
    ));
  end if;

  perform public.finance_refresh_receivable_status(p_receivable_id);
  select * into v_receivable from public.finance_receivables where id = p_receivable_id;

  return jsonb_build_object('collection', to_jsonb(v_collection), 'receivable', to_jsonb(v_receivable));
end;
$$;


ALTER FUNCTION "public"."record_finance_receivable_collection"("p_receivable_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_login_attempt"("p_email" "text", "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_success" boolean DEFAULT false, "p_failure_reason" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_captcha_session_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text := lower(trim(coalesce(p_email, '')));
  v_ip text := nullif(trim(coalesce(p_ip, '')), '');
  v_email_failures integer := 0;
  v_ip_failures integer := 0;
  v_captcha_required boolean := false;
  v_captcha_passed boolean := null;
  v_attempt public.security_login_attempts;
  v_profile record;
  v_status jsonb;
begin
  v_status := public.check_login_security(v_email, v_ip);
  v_captcha_required := coalesce((v_status ->> 'captcha_required')::boolean, false);

  if not p_success and coalesce((v_status ->> 'blocked')::boolean, false) then
    return jsonb_build_object(
      'recorded', false,
      'blocked', true,
      'message', 'Demasiados intentos. Intenta de nuevo en 15 minutos.'
    );
  end if;

  if not p_success and v_captcha_required then
    if p_captcha_session_id is null then
      return jsonb_build_object(
        'recorded', false,
        'blocked', false,
        'captcha_required', true,
        'message', 'Completa la verificacion de seguridad para continuar.'
      );
    end if;

    select exists (
      select 1
      from public.login_captcha_sessions session
      where session.id = p_captcha_session_id
        and lower(session.email_attempted) = v_email
        and session.consumed_at is null
        and session.expires_at > now()
        and (session.ip_address is null or v_ip is null or session.ip_address = v_ip)
    ) into v_captcha_passed;

    if not coalesce(v_captcha_passed, false) then
      return jsonb_build_object(
        'recorded', false,
        'blocked', false,
        'captcha_required', true,
        'message', 'La verificacion CAPTCHA expiro o no es valida.'
      );
    end if;

    update public.login_captcha_sessions
    set consumed_at = now()
    where id = p_captcha_session_id;
  end if;

  select * into v_profile
  from public.resolve_login_profile(v_email);

  insert into public.security_login_attempts (
    email_attempted,
    user_id,
    ip_address,
    user_agent,
    success,
    failure_reason,
    captcha_required,
    captcha_passed,
    metadata
  )
  values (
    v_email,
    coalesce(p_user_id, v_profile.profile_id),
    v_ip,
    nullif(trim(coalesce(p_user_agent, '')), ''),
    p_success,
    nullif(trim(coalesce(p_failure_reason, '')), ''),
    v_captcha_required,
    v_captcha_passed,
    jsonb_build_object(
      'profile_role', v_profile.profile_role,
      'user_agent_fingerprint', public.login_security_user_agent_fingerprint(p_user_agent)
    )
  )
  returning * into v_attempt;

  if p_success then
    perform public.maybe_notify_suspicious_successful_login(
      v_attempt.id,
      v_attempt.user_id,
      v_email,
      v_ip,
      v_attempt.user_agent,
      v_profile.profile_role
    );
  else
    select count(*)::integer
    into v_email_failures
    from public.security_login_attempts attempt
    where attempt.success = false
      and lower(attempt.email_attempted) = v_email
      and attempt.created_at >= now() - make_interval(mins => public.login_security_window_minutes());

    if v_ip is not null then
      select count(*)::integer
      into v_ip_failures
      from public.security_login_attempts attempt
      where attempt.success = false
        and attempt.ip_address = v_ip
        and attempt.created_at >= now() - make_interval(mins => public.login_security_window_minutes());
    end if;

    perform public.maybe_notify_login_security(
      v_attempt.id,
      v_email,
      v_ip,
      v_email_failures,
      v_ip_failures,
      false,
      v_profile.profile_role
    );
  end if;

  v_status := public.check_login_security(v_email, v_ip);

  return jsonb_build_object(
    'recorded', true,
    'attempt_id', v_attempt.id,
    'blocked', coalesce((v_status ->> 'blocked')::boolean, false),
    'captcha_required', coalesce((v_status ->> 'captcha_required')::boolean, false),
    'message', v_status ->> 'message',
    'email_failures', v_status -> 'email_failures',
    'ip_failures', v_status -> 'ip_failures'
  );
end;
$$;


ALTER FUNCTION "public"."record_login_attempt"("p_email" "text", "p_ip" "text", "p_user_agent" "text", "p_success" boolean, "p_failure_reason" "text", "p_user_id" "uuid", "p_captcha_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_operational_enrollment_secret_attempt"("p_enrollment_id" "uuid", "p_success" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count int;
begin
  if p_success then
    update public.operational_station_enrollment_tokens
    set device_claim_attempt_count = 0, device_claim_locked_until = null, updated_at = now()
    where id = p_enrollment_id;
    return;
  end if;
  update public.operational_station_enrollment_tokens
  set device_claim_attempt_count = device_claim_attempt_count + 1,
      device_claim_locked_until = case
        when device_claim_attempt_count + 1 >= 10 then now() + interval '15 minutes'
        else device_claim_locked_until
      end,
      updated_at = now()
  where id = p_enrollment_id
  returning device_claim_attempt_count into v_count;
end;
$$;


ALTER FUNCTION "public"."record_operational_enrollment_secret_attempt"("p_enrollment_id" "uuid", "p_success" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_operational_pin_attempt"("p_bucket_key" "text", "p_max" integer, "p_lock_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.operational_pin_attempt_buckets;
  v_now timestamptz := now();
begin
  insert into public.operational_pin_attempt_buckets (bucket_key, attempt_count, locked_until)
  values (p_bucket_key, 0, null)
  on conflict (bucket_key) do nothing;

  select * into v_row
  from public.operational_pin_attempt_buckets
  where bucket_key = p_bucket_key
  for update;

  if v_row.locked_until is not null and v_row.locked_until > v_now then
    return false;
  end if;

  update public.operational_pin_attempt_buckets
  set attempt_count = case
        when locked_until is not null and locked_until <= v_now then 1
        else attempt_count + 1
      end,
      locked_until = case
        when (case when locked_until is not null and locked_until <= v_now then 1 else attempt_count + 1 end) >= p_max
          then v_now + make_interval(secs => p_lock_seconds)
        else null
      end,
      updated_at = v_now
  where bucket_key = p_bucket_key;

  select * into v_row from public.operational_pin_attempt_buckets where bucket_key = p_bucket_key;
  return v_row.locked_until is null or v_row.locked_until <= v_now;
end;
$$;


ALTER FUNCTION "public"."record_operational_pin_attempt"("p_bucket_key" "text", "p_max" integer, "p_lock_seconds" integer) OWNER TO "postgres";


