CREATE OR REPLACE FUNCTION "public"."refresh_historical_yield_average"("p_item_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  avg_yield numeric;
begin
  select round(avg(ya.yield_percent)::numeric, 2) into avg_yield
  from public.yield_audits ya
  where ya.inventory_item_id = p_item_id;

  if avg_yield is null then
    return null;
  end if;

  update public.inventory_yield_profiles
  set
    historical_average_yield_percent = avg_yield,
    updated_at = now()
  where inventory_item_id = p_item_id;

  if not found then
    insert into public.inventory_yield_profiles (
      inventory_item_id,
      expected_yield_percent,
      minimum_acceptable_yield_percent,
      historical_average_yield_percent
    )
    select p_item_id, 100, 90, avg_yield
    from public.inventory_items
    where id = p_item_id;
  end if;

  perform public.refresh_inventory_item_costing(p_item_id);
  return avg_yield;
end;
$$;


ALTER FUNCTION "public"."refresh_historical_yield_average"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_inventory_item_costing"("p_item_id" "uuid") RETURNS "public"."inventory_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item public.inventory_items;
  profile public.inventory_yield_profiles;
  cpp numeric;
  yield_pct numeric;
  cur numeric;
begin
  select * into item from public.inventory_items where id = p_item_id;
  if item.id is null then
    raise exception 'Ingrediente no encontrado.';
  end if;

  cpp := public.compute_inventory_weighted_average_cost(p_item_id);

  select * into profile
  from public.inventory_yield_profiles
  where inventory_item_id = p_item_id and active = true;

  yield_pct := coalesce(profile.expected_yield_percent, 100);
  if yield_pct <= 0 then
    yield_pct := 100;
  end if;

  cur := case when cpp > 0 then cpp / (yield_pct / 100.0) else 0 end;

  update public.inventory_items
  set
    weighted_average_cost = cpp,
    usable_cost = cur,
    updated_at = now()
  where id = p_item_id
  returning * into item;

  perform public.recalculate_recipes_for_inventory_item(p_item_id);
  return item;
end;
$$;


ALTER FUNCTION "public"."refresh_inventory_item_costing"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_pos_order_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_order_id uuid;
begin
  if tg_op = 'DELETE' then
    target_order_id := old.order_id;
  else
    target_order_id := new.order_id;
  end if;
  update public.pos_orders
  set subtotal = coalesce((
        select sum(total_price) from public.pos_order_items
        where order_id = target_order_id and status <> 'cancelled'
      ), 0),
      total = coalesce((
        select sum(total_price) from public.pos_order_items
        where order_id = target_order_id and status <> 'cancelled'
      ), 0)
  where id = target_order_id;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."refresh_pos_order_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_pos_product_catalog_state"("p_product_id" "uuid") RETURNS "public"."pos_products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.pos_products;
  has_valid_variant boolean := false;
  has_valid_config boolean := false;
  v_mode text := public.get_inventory_deduction_mode();
  v_implementation boolean := v_mode <> 'strict';
  v_min_price numeric := 0;
begin
  select * into saved
  from public.pos_products
  where id = p_product_id
  for update;

  if saved.id is null then
    raise exception 'El producto POS no existe.';
  end if;

  saved.recipe_status := public.compute_pos_product_recipe_status(saved.id);

  if not saved.active then
    update public.pos_products
    set production_ready = false,
        recipe_status = saved.recipe_status
    where id = saved.id
    returning * into saved;
    return saved;
  end if;

  if saved.is_test_item then
    update public.pos_products
    set recipe_id = null,
        production_ready = true,
        recipe_status = 'missing'
    where id = saved.id
    returning * into saved;
    return saved;
  end if;

  if saved.product_type = 'pizza' then
    if coalesce(saved.inventory_tracking_enabled, false) then
      select exists (
        select 1
        from public.pos_product_variants variant
        join public.standard_recipes recipe on recipe.id = variant.recipe_id
        where variant.product_id = saved.id
          and variant.is_active = true
          and variant.price > 0
          and recipe.active = true
          and recipe.recipe_type = 'final_product'
          and recipe.production_area_id = saved.production_area_id
      ) into has_valid_variant;
    else
      select exists (
        select 1
        from public.pos_product_variants variant
        where variant.product_id = saved.id
          and variant.is_active = true
          and variant.price > 0
      ) into has_valid_variant;
    end if;

    update public.pos_products
    set recipe_id = null,
        production_ready = has_valid_variant
          and saved.production_area_id is not null,
        recipe_status = saved.recipe_status
    where id = saved.id
    returning * into saved;
    return saved;
  end if;

  if saved.product_type = 'configurable' then
    has_valid_config := public.pos_configurable_catalog_is_valid(saved.id);
    v_min_price := public.pos_configurable_min_absolute_price(saved.id);

    update public.pos_products
    set recipe_id = null,
        price = case when v_min_price > 0 then v_min_price else price end,
        production_ready = has_valid_config
          and saved.production_area_id is not null,
        recipe_status = saved.recipe_status
    where id = saved.id
    returning * into saved;
    return saved;
  end if;

  if v_implementation and not saved.recipe_required_for_sale then
    update public.pos_products
    set production_ready = saved.production_area_id is not null,
        recipe_status = saved.recipe_status
    where id = saved.id
    returning * into saved;
    return saved;
  end if;

  update public.pos_products
  set production_ready = (
    recipe_id is not null
    and production_area_id is not null
    and price >= 0
    and saved.recipe_status = 'active'
  ),
  recipe_status = saved.recipe_status
  where id = saved.id
  returning * into saved;

  return saved;
end;
$$;


ALTER FUNCTION "public"."refresh_pos_product_catalog_state"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_pos_product_catalog_state_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if public.pos_catalog_refresh_is_suppressed() then
    return coalesce(new, old);
  end if;
  perform public.refresh_pos_product_catalog_state(coalesce(new.product_id, old.product_id));
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."refresh_pos_product_catalog_state_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_pos_product_catalog_state_trigger_option_choices"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product_id uuid;
begin
  if public.pos_catalog_refresh_is_suppressed() then
    return coalesce(new, old);
  end if;
  select grp.product_id into v_product_id
  from public.pos_option_groups grp
  where grp.id = coalesce(new.group_id, old.group_id);

  if v_product_id is not null
     and exists (select 1 from public.pos_products where id = v_product_id) then
    perform public.refresh_pos_product_catalog_state(v_product_id);
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."refresh_pos_product_catalog_state_trigger_option_choices"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_pos_product_catalog_state_trigger_option_groups"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product_id uuid := coalesce(new.product_id, old.product_id);
begin
  if public.pos_catalog_refresh_is_suppressed() then
    return coalesce(new, old);
  end if;
  if v_product_id is null then
    return coalesce(new, old);
  end if;
  if not exists (select 1 from public.pos_products where id = v_product_id) then
    return coalesce(new, old);
  end if;
  perform public.refresh_pos_product_catalog_state(v_product_id);
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."refresh_pos_product_catalog_state_trigger_option_groups"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_attendance_mark"("p_employee_id" "uuid", "p_pin" "text", "p_mark_type" "text", "p_photo_path" "text", "p_device_id" "text", "p_device_name" "text", "p_observation" "text" DEFAULT NULL::"text", "p_client_ip" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_marks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO '', 'extensions', 'public'
    AS $$
declare
  employee public.profiles;
  credential public.attendance_credentials;
  mark public.attendance_marks;
  open_entry public.attendance_marks;
  open_meal public.attendance_marks;
  meal_minutes integer;
  unrecognized_device boolean;
  observation_text text := nullif(trim(p_observation), '');
  user_agent text;
  v_mark_type text;
  v_perm public.attendance_mark_permission;
  v_class jsonb;
begin
  perform public.assert_attendance_device_can_mark(
    p_device_id,
    p_employee_id,
    p_client_ip,
    null
  );

  if nullif(trim(p_photo_path), '') is null then
    raise exception 'Se requiere foto para registrar asistencia.';
  end if;

  v_mark_type := public.normalize_attendance_mark_type(p_mark_type);
  if v_mark_type not in ('entrada', 'salida_comida', 'regreso_comida', 'salida_final') then
    raise exception 'Tipo de marcaje no valido.';
  end if;

  select * into employee from public.profiles where id = p_employee_id and status = 'active';
  select * into credential from public.attendance_credentials where employee_id = p_employee_id;
  if employee.id is null or credential.employee_id is null
    or crypt(p_pin, credential.pin_hash) <> credential.pin_hash then
    raise exception 'PIN incorrecto o colaborador sin PIN configurado.';
  end if;

  v_perm := public.resolve_attendance_mark_permission(p_employee_id, v_mark_type, now());

  if not v_perm.allowed then
    raise exception '%', coalesce(
      v_perm.reason,
      'No se puede registrar esta marcación en el estado actual del turno.'
    );
  end if;

  v_class := public.classify_attendance_mark(
    p_employee_id,
    v_perm.labor_date,
    v_mark_type,
    now()
  );

  if v_perm.open_entry_id is not null then
    select m.* into open_entry
    from public.attendance_marks m
    where m.id = v_perm.open_entry_id;
  else
    open_entry := null;
  end if;

  if v_perm.open_meal_id is not null then
    select m.* into open_meal
    from public.attendance_marks m
    where m.id = v_perm.open_meal_id;
  else
    open_meal := null;
  end if;

  if v_mark_type = 'regreso_comida' then
    meal_minutes := greatest(
      0,
      floor(extract(epoch from (now() - open_meal.marked_at)) / 60)::integer
    );
  end if;

  unrecognized_device := employee.authorized_attendance_device is not null
    and employee.authorized_attendance_device <> p_device_id;

  insert into public.attendance_marks (
    employee_id, employee_name, mark_type, photo_path, device_id, device_name, device_alert,
    related_mark_id, duration_minutes, observation,
    labor_date, classification, approval_status, schedule_exception_id, system_reason
  )
  values (
    employee.id, coalesce(employee.full_name, employee.username, 'Colaborador'),
    v_mark_type, trim(p_photo_path), trim(p_device_id), trim(p_device_name), unrecognized_device,
    case when v_mark_type = 'regreso_comida' then open_meal.id else open_entry.id end,
    meal_minutes,
    observation_text,
    v_perm.labor_date,
    v_class ->> 'classification',
    coalesce(v_class ->> 'approval_status', 'not_required'),
    nullif(v_class ->> 'schedule_exception_id', '')::uuid,
    v_class ->> 'system_reason'
  )
  returning * into mark;

  perform public.log_attendance_security_event(
    trim(p_device_id),
    employee.id,
    'authorized_mark_attempt',
    p_client_ip,
    user_agent,
    jsonb_build_object(
      'mark_type', v_mark_type,
      'mark_id', mark.id,
      'labor_date', v_perm.labor_date,
      'calendar_date', (now() at time zone 'America/Guatemala')::date,
      'classification', mark.classification,
      'approval_status', mark.approval_status,
      'permission_reason_code', v_perm.reason_code,
      'next_expected_mark', v_perm.next_expected_mark
    )
  );

  return mark;
end;
$$;


ALTER FUNCTION "public"."register_attendance_mark"("p_employee_id" "uuid", "p_pin" "text", "p_mark_type" "text", "p_photo_path" "text", "p_device_id" "text", "p_device_name" "text", "p_observation" "text", "p_client_ip" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bakery_waste_records" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "related_batch_id" "uuid",
    "related_dough_batch_id" "uuid",
    "inventory_item_id" "uuid",
    "product_name" "text" NOT NULL,
    "quantity" numeric NOT NULL,
    "unit" "text" DEFAULT 'Unidad'::"text" NOT NULL,
    "waste_reason" "text" NOT NULL,
    "notes" "text",
    "photo_url" "text" NOT NULL,
    "reported_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bakery_waste_records_quantity_check" CHECK (("quantity" > (0)::numeric)),
    CONSTRAINT "bakery_waste_records_waste_reason_check" CHECK (("waste_reason" = ANY (ARRAY['burned'::"text", 'overfermented'::"text", 'expired'::"text", 'dropped'::"text", 'recipe_error'::"text", 'poor_quality'::"text", 'overproduction'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."bakery_waste_records" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_bakery_waste"("p_payload" "jsonb") RETURNS "public"."bakery_waste_records"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.bakery_waste_records;
  v_reason text := lower(trim(coalesce(p_payload ->> 'waste_reason', '')));
  v_photo text := nullif(trim(p_payload ->> 'photo_url'), '');
  v_qty numeric := nullif(p_payload ->> 'quantity', '')::numeric;
  v_name text := nullif(trim(p_payload ->> 'product_name'), '');
begin
  if not public.can_operate_bakery_production() then
    raise exception 'PERMISSION_DENIED';
  end if;
  if v_photo is null then
    raise exception 'Se requiere foto para registrar merma.';
  end if;
  if v_reason not in (
    'burned', 'overfermented', 'expired', 'dropped', 'recipe_error',
    'poor_quality', 'overproduction', 'other'
  ) then
    raise exception 'Indica un motivo de merma válido.';
  end if;
  if coalesce(v_qty, 0) <= 0 then
    raise exception 'La cantidad de merma debe ser mayor que cero.';
  end if;
  if v_name is null then
    raise exception 'Indica el producto o masa afectada.';
  end if;

  insert into public.bakery_waste_records (
    related_batch_id, related_dough_batch_id, inventory_item_id,
    product_name, quantity, unit, waste_reason, notes, photo_url, reported_by
  )
  values (
    nullif(p_payload ->> 'related_batch_id', '')::uuid,
    nullif(p_payload ->> 'related_dough_batch_id', '')::uuid,
    nullif(p_payload ->> 'inventory_item_id', '')::uuid,
    v_name,
    v_qty,
    coalesce(nullif(trim(p_payload ->> 'unit'), ''), 'Unidad'),
    v_reason,
    nullif(trim(p_payload ->> 'notes'), ''),
    v_photo,
    auth.uid()
  )
  returning * into v_row;

  if v_row.related_batch_id is not null then
    insert into public.bakery_production_batch_photos (
      batch_id, photo_url, photo_type, uploaded_by
    )
    values (v_row.related_batch_id, v_photo, 'waste', auth.uid());
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."register_bakery_waste"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_employee_file_version"("p_profile_id" "uuid", "p_file_type_code" "text", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text" DEFAULT NULL::"text", "p_file_size" bigint DEFAULT NULL::bigint, "p_issued_at" "date" DEFAULT NULL::"date", "p_expires_at" "date" DEFAULT NULL::"date", "p_no_expires" boolean DEFAULT false, "p_signature_status" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_type public.employee_file_types;
  v_file public.employee_files;
  v_version public.employee_file_versions;
  v_next_version integer := 1;
  v_no_expires boolean := coalesce(p_no_expires, false);
  v_expires_at date := case when v_no_expires then null else p_expires_at end;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para cargar documentos.';
  end if;

  select * into v_type
  from public.employee_file_types
  where code = p_file_type_code;

  if not found then
    raise exception 'Tipo de documento invalido: %.', p_file_type_code;
  end if;

  insert into public.employee_files (profile_id, file_type_code, signature_status, metadata)
  values (
    p_profile_id,
    p_file_type_code,
    case when v_type.requires_signature then coalesce(p_signature_status, 'pending') else null end,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (profile_id, file_type_code) do update set
    signature_status = case
      when v_type.requires_signature then coalesce(excluded.signature_status, employee_files.signature_status)
      else employee_files.signature_status
    end,
    metadata = employee_files.metadata || excluded.metadata,
    updated_at = now()
  returning * into v_file;

  select coalesce(max(version_number), 0) + 1
  into v_next_version
  from public.employee_file_versions
  where employee_file_id = v_file.id;

  if not v_type.allows_multiple then
    update public.employee_file_versions
    set is_current = false
    where employee_file_id = v_file.id and is_current = true;
  end if;

  insert into public.employee_file_versions (
    employee_file_id, profile_id, file_type_code, version_number,
    storage_path, file_name, mime_type, file_size,
    issued_at, expires_at, no_expires, uploaded_by, notes, is_current
  )
  values (
    v_file.id, p_profile_id, p_file_type_code, v_next_version,
    p_storage_path, p_file_name, p_mime_type, p_file_size,
    p_issued_at, v_expires_at, v_no_expires, auth.uid(), p_notes, true
  )
  returning * into v_version;

  update public.employee_files
  set current_version_id = v_version.id, updated_at = now()
  where id = v_file.id;

  begin
    perform public.sync_employee_expediente_alerts(p_profile_id);
  exception
    when others then
      raise warning 'sync_employee_expediente_alerts failed for %: %', p_profile_id, sqlerrm;
  end;

  return jsonb_build_object('file', to_jsonb(v_file), 'version', to_jsonb(v_version));
end;
$$;


ALTER FUNCTION "public"."register_employee_file_version"("p_profile_id" "uuid", "p_file_type_code" "text", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_file_size" bigint, "p_issued_at" "date", "p_expires_at" "date", "p_no_expires" boolean, "p_signature_status" "text", "p_notes" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_incident_evidence"("p_incident_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text" DEFAULT NULL::"text", "p_file_size" bigint DEFAULT NULL::bigint, "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_incident public.employee_incidents;
  v_evidence public.employee_incident_evidence;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para cargar evidencia.';
  end if;

  select * into v_incident
  from public.employee_incidents
  where id = p_incident_id;

  if not found then
    raise exception 'Incidente no encontrado.';
  end if;

  insert into public.employee_incident_evidence (
    incident_id, profile_id, storage_path, file_name, mime_type, file_size,
    description, uploaded_by
  )
  values (
    p_incident_id,
    v_incident.profile_id,
    p_storage_path,
    p_file_name,
    p_mime_type,
    p_file_size,
    nullif(trim(coalesce(p_description, '')), ''),
    auth.uid()
  )
  returning * into v_evidence;

  return to_jsonb(v_evidence);
end;
$$;


ALTER FUNCTION "public"."register_incident_evidence"("p_incident_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_file_size" bigint, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_recruitment_contact"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_contact public.recruitment_candidate_contacts;
  v_candidate_id uuid;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para registrar contactos.';
  end if;

  v_candidate_id := nullif(trim(p_payload ->> 'candidate_id'), '')::uuid;

  insert into public.recruitment_candidate_contacts (
    candidate_id, contacted_at, contact_type, result, notes, created_by
  )
  values (
    v_candidate_id,
    coalesce(nullif(trim(coalesce(p_payload ->> 'contacted_at', '')), '')::timestamptz, now()),
    coalesce(nullif(trim(p_payload ->> 'contact_type'), ''), 'call'),
    coalesce(nullif(trim(p_payload ->> 'result'), ''), 'no_answer'),
    nullif(trim(coalesce(p_payload ->> 'notes', '')), ''),
    auth.uid()
  )
  returning * into v_contact;

  update public.recruitment_candidates
  set pipeline_status = case
        when pipeline_status = 'applied' then 'contacted'
        else pipeline_status
      end,
      updated_by = auth.uid()
  where id = v_candidate_id
    and pipeline_status = 'applied';

  return to_jsonb(v_contact);
end;
$$;


ALTER FUNCTION "public"."register_recruitment_contact"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_task_attachment"("p_task_id" "text", "p_step_id" "uuid" DEFAULT NULL::"uuid", "p_storage_path" "text" DEFAULT NULL::"text", "p_display_name" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint, "p_external_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_type text;
  v_id uuid;
begin
  v_task := public.assert_operational_task_mutable(p_task_id);
  if not public.can_upload_task_files(v_task) then
    raise exception 'No tienes permiso para subir archivos.';
  end if;

  if coalesce(trim(p_external_url), '') <> '' then
    v_type := 'external_link';
  else
    v_type := 'file';
    if coalesce(trim(p_storage_path), '') = '' then
      raise exception 'Ruta de archivo obligatoria.';
    end if;
  end if;

  insert into public.task_attachments (
    task_id, step_id, attachment_type, storage_path, external_url,
    display_name, mime_type, size_bytes, uploaded_by
  ) values (
    p_task_id,
    p_step_id,
    v_type,
    nullif(trim(p_storage_path), ''),
    nullif(trim(p_external_url), ''),
    coalesce(nullif(trim(p_display_name), ''), 'Archivo'),
    nullif(trim(p_mime_type), ''),
    p_size_bytes,
    auth.uid()
  ) returning id into v_id;

  perform public.log_task_activity(
    p_task_id, 'attachment_added', 'attachments',
    null, to_jsonb(coalesce(nullif(trim(p_display_name), ''), 'Archivo')),
    jsonb_build_object('attachment_id', v_id, 'step_id', p_step_id)
  );

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."register_task_attachment"("p_task_id" "text", "p_step_id" "uuid", "p_storage_path" "text", "p_display_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_external_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_and_block_station_device"("p_device_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."operational_station_devices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
begin
  if not public.is_operational_stations_admin() then
    raise exception 'No autorizado.';
  end if;
  select * into v_device from public.operational_station_devices where id = p_device_id for update;
  if v_device.id is null then
    raise exception 'Dispositivo no encontrado.';
  end if;
  update public.operational_station_devices
  set status = 'blocked', blocked_reason = nullif(trim(p_reason), ''),
      blocked_by = auth.uid(), blocked_at = now(), updated_at = now()
  where id = p_device_id
  returning * into v_device;
  update public.operational_station_enrollment_tokens
  set status = 'blocked', updated_at = now()
  where id = v_device.enrollment_id;
  perform public.log_operational_station_event(
    v_device.station_id, v_device.id, 'device_rejected', auth.uid(),
    jsonb_build_object('reason', v_device.blocked_reason), null
  );
  return v_device;
end;
$$;


ALTER FUNCTION "public"."reject_and_block_station_device"("p_device_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_checklist_change_request"("p_request_id" "uuid", "p_review_notes" "text") RETURNS "public"."checklist_template_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request_row public.checklist_template_change_requests;
begin
  if not public.is_checklist_change_approver() then
    raise exception 'No tienes permiso para rechazar cambios de checklist.';
  end if;
  if nullif(trim(coalesce(p_review_notes, '')), '') is null then
    raise exception 'La nota de rechazo es obligatoria.';
  end if;

  update public.checklist_template_change_requests
  set status = 'rejected',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = trim(p_review_notes)
  where id = p_request_id
    and status = 'pending_review'
  returning * into request_row;

  if request_row.id is null then
    raise exception 'Solicitud pendiente no encontrada.';
  end if;

  insert into public.notifications (
    user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
  )
  values (
    request_row.submitted_by,
    null,
    'checklist_approval_result',
    'Checklist rechazada',
    'Tu checklist "' || request_row.title || '" fue rechazada. Revisa las notas y vuelve a enviarla: ' || trim(p_review_notes),
    'checklist_template_change_request',
    request_row.id::text,
    '/tasks?tab=checklists&view=approvals&id=' || request_row.id::text,
    auth.uid()
  );

  return request_row;
end;
$$;


ALTER FUNCTION "public"."reject_checklist_change_request"("p_request_id" "uuid", "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_checklist_run"("p_run_id" "uuid", "p_review_notes" "text") RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
begin
  if nullif(trim(coalesce(p_review_notes, '')), '') is null then
    raise exception 'La nota de rechazo es obligatoria.';
  end if;
  select * into run_row from public.checklist_runs where id = p_run_id for update;
  if run_row.id is null then raise exception 'Checklist no encontrada.'; end if;
  if not public.is_checklist_change_approver() and coalesce(run_row.supervisor_profile_id <> auth.uid(), true) then
    raise exception 'No tienes permiso para rechazar esta checklist.';
  end if;
  if run_row.status <> 'pending_review' then raise exception 'Solo se pueden rechazar checklists en revision.'; end if;

  update public.checklist_runs
  set status = 'rejected',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_notes = trim(p_review_notes)
  where id = p_run_id
  returning * into run_row;

  return run_row;
end;
$$;


ALTER FUNCTION "public"."reject_checklist_run"("p_run_id" "uuid", "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_requisition"("p_requisition_id" "uuid", "p_reason" "text") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rejected public.requisitions;
begin
  if not public.is_profile_manager() then
    raise exception 'No tienes permiso para rechazar requisiciones.';
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception 'El motivo de rechazo es obligatorio.';
  end if;
  update public.requisitions
    set status = 'rejected', rejection_reason = trim(p_reason)
    where id = p_requisition_id and status in ('pending', 'approved')
    returning * into rejected;
  if rejected.id is null then raise exception 'No se puede rechazar esta requisición.'; end if;
  return rejected;
end;
$$;


ALTER FUNCTION "public"."reject_requisition"("p_requisition_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_pos_table_service"("p_order_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid" DEFAULT NULL::"uuid", "p_force_supervisor" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.pos_orders;
  v_scenario text;
  v_fingerprint text;
  v_cached jsonb;
  v_result jsonb;
  v_authorized_by uuid;
  v_removed integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para liberar servicio POS.';
  end if;
  if p_idempotency_key is null then
    raise exception 'POS_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 10 then
    raise exception 'POS_RELEASE_REASON_REQUIRED';
  end if;

  v_fingerprint := public.pos_rpc_fingerprint(array[
    'release',
    p_order_id::text,
    trim(p_reason)
  ]);

  v_cached := public.pos_load_rpc_idempotency(p_idempotency_key, v_fingerprint);
  if v_cached is not null then
    return v_cached;
  end if;

  select * into v_order
  from public.pos_orders
  where id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'La orden POS no existe.';
  end if;

  perform pg_advisory_xact_lock(hashtext('pos_table_service:' || coalesce(v_order.table_id, p_order_id::text)));

  if v_order.status = 'cancelled' then
    v_result := jsonb_build_object(
      'released', true,
      'already', true,
      'order_id', v_order.id,
      'status', v_order.status
    );
    perform public.pos_store_rpc_idempotency(
      p_idempotency_key, 'release_pos_table_service', 'order:' || p_order_id::text, v_fingerprint, v_result
    );
    return v_result;
  end if;

  if v_order.status = 'paid' then
    v_result := jsonb_build_object(
      'released', false,
      'reason', 'already_paid',
      'order_id', v_order.id,
      'status', v_order.status
    );
    perform public.pos_store_rpc_idempotency(
      p_idempotency_key, 'release_pos_table_service', 'order:' || p_order_id::text, v_fingerprint, v_result
    );
    return v_result;
  end if;

  v_scenario := public.pos_classify_release_scenario(p_order_id);
  perform public.pos_assert_release_authorized(p_order_id, v_scenario);

  if v_scenario = 'L2_drafts_only' then
    v_removed := public.clear_pos_order_draft_items(p_order_id);
  end if;

  v_authorized_by := case
    when public.is_pos_elevated_supervisor()
         and (not public.is_order_owner(p_order_id) or v_scenario in ('L3_kds_history', 'L4_billing'))
      then auth.uid()
    else null
  end;

  update public.pos_orders
  set status = 'cancelled',
      updated_at = now()
  where id = p_order_id;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    p_order_id,
    'table_released',
    'Mesa liberada. Motivo: ' || left(trim(p_reason), 500),
    auth.uid()
  );

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    p_order_id,
    'service_cancelled',
    'Servicio cancelado (' || v_scenario || ').',
    auth.uid()
  );

  v_result := jsonb_build_object(
    'released', true,
    'order_id', p_order_id,
    'previous_status', v_order.status,
    'scenario', v_scenario,
    'authorized_by', v_authorized_by,
    'owner_profile_id', v_order.owner_profile_id,
    'drafts_cleared', coalesce(v_removed, 0)
  );

  perform public.pos_store_rpc_idempotency(
    p_idempotency_key, 'release_pos_table_service', 'order:' || p_order_id::text, v_fingerprint, v_result
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."release_pos_table_service"("p_order_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid", "p_force_supervisor" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_pos_table_service_for_operator"("p_order_id" "uuid", "p_reason" "text", "p_operator_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.pos_orders;
  v_scenario text;
  v_result jsonb;
  v_removed integer;
begin
  if not public.station_pos_can_operate_orders(p_operator_profile_id) then
    raise exception 'No tienes permiso para liberar servicio POS.';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 10 then
    raise exception 'POS_RELEASE_REASON_REQUIRED';
  end if;

  select * into v_order
  from public.pos_orders
  where id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'La orden POS no existe.';
  end if;

  perform pg_advisory_xact_lock(hashtext('pos_table_service:' || coalesce(v_order.table_id, p_order_id::text)));

  if v_order.status = 'cancelled' then
    return jsonb_build_object(
      'released', true,
      'already', true,
      'order_id', v_order.id,
      'status', v_order.status
    );
  end if;

  if v_order.status = 'paid' then
    return jsonb_build_object(
      'released', false,
      'reason', 'already_paid',
      'order_id', v_order.id,
      'status', v_order.status
    );
  end if;

  v_scenario := public.pos_classify_release_scenario(p_order_id);
  perform public.station_pos_assert_release_authorized(p_order_id, v_scenario, p_operator_profile_id);

  if v_scenario = 'L2_drafts_only' then
    v_removed := public.station_pos_clear_draft_items_impl(p_order_id, p_operator_profile_id);
  end if;

  update public.pos_orders
  set status = 'cancelled',
      updated_at = now()
  where id = p_order_id;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    p_order_id,
    'table_released',
    'Mesa liberada. Motivo: ' || left(trim(p_reason), 500),
    p_operator_profile_id
  );

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    p_order_id,
    'service_cancelled',
    'Servicio cancelado (' || v_scenario || ').',
    p_operator_profile_id
  );

  return jsonb_build_object(
    'released', true,
    'order_id', p_order_id,
    'previous_status', v_order.status,
    'scenario', v_scenario,
    'owner_profile_id', v_order.owner_profile_id,
    'drafts_cleared', coalesce(v_removed, 0)
  );
end;
$$;


ALTER FUNCTION "public"."release_pos_table_service_for_operator"("p_order_id" "uuid", "p_reason" "text", "p_operator_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_station_pos_table_service"("p_operator_session_token" "text", "p_order_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'release_table_service',
    jsonb_build_object('order_id', p_order_id, 'reason', trim(coalesce(p_reason, '')))
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'release_table_service', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'release_table_service', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);

  v_result := public.release_pos_table_service_for_operator(p_order_id, p_reason, v_operator_id);

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'release_table_service', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  perform public.station_pos_revoke_operator_session(v_op_session_id, 'release_table_service');
  return v_result;
exception
  when others then
    if sqlerrm in (
      'POS_RELEASE_REASON_REQUIRED', 'POS_RELEASE_NOT_OWNER', 'POS_RELEASE_BLOCKED_PAYMENTS',
      'POS_RELEASE_REQUIRES_SUPERVISOR', 'La orden POS no existe.'
    ) or sqlerrm like 'POS_RELEASE%' then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."release_station_pos_table_service"("p_operator_session_token" "text", "p_order_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_employee_file_current"("p_profile_id" "uuid", "p_file_type_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_file public.employee_files;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para eliminar documentos.';
  end if;

  select * into v_file
  from public.employee_files
  where profile_id = p_profile_id and file_type_code = p_file_type_code
  for update;

  if not found or v_file.current_version_id is null then
    raise exception 'No hay documento activo para eliminar.';
  end if;

  update public.employee_file_versions
  set is_current = false
  where id = v_file.current_version_id;

  update public.employee_files
  set current_version_id = null, updated_at = now()
  where id = v_file.id;

  begin
    perform public.sync_employee_expediente_alerts(p_profile_id);
  exception
    when others then
      raise warning 'sync_employee_expediente_alerts failed for %: %', p_profile_id, sqlerrm;
  end;

  return true;
end;
$$;


ALTER FUNCTION "public"."remove_employee_file_current"("p_profile_id" "uuid", "p_file_type_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_station_pos_draft_item"("p_operator_session_token" "text", "p_order_id" "uuid", "p_item_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_item public.pos_order_items;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'remove_draft_item',
    jsonb_build_object('order_id', p_order_id, 'item_id', p_item_id)
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'remove_draft_item', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'remove_draft_item', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);
  perform public.station_pos_assert_order_open_for_drafts(p_order_id, v_operator_id);

  delete from public.pos_order_items i
  where i.id = p_item_id
    and i.order_id = p_order_id
    and i.status = 'draft'
  returning * into v_item;

  if v_item.id is null then
    raise exception '%', v_generic;
  end if;

  v_result := jsonb_build_object('removed', true, 'item_id', p_item_id, 'order_id', p_order_id);

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'remove_draft_item', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."remove_station_pos_draft_item"("p_operator_session_token" "text", "p_order_id" "uuid", "p_item_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_task_steps"("p_list_id" "uuid", "p_step_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_list public.task_step_lists;
  v_idx int;
  v_step_id uuid;
begin
  select * into v_list
  from public.task_step_lists sl
  where sl.id = p_list_id and sl.deleted_at is null
  for update;

  if not found then raise exception 'Lista no encontrada.'; end if;
  perform public.assert_operational_task_mutable(v_list.task_id);

  v_idx := 0;
  foreach v_step_id in array coalesce(p_step_ids, '{}'::uuid[]) loop
    update public.task_steps
    set sort_position = v_idx::numeric * 1024, updated_at = now()
    where id = v_step_id and step_list_id = p_list_id and deleted_at is null;
    v_idx := v_idx + 1;
  end loop;

  return public.get_operational_task_detail(v_list.task_id);
end;
$$;


ALTER FUNCTION "public"."reorder_task_steps"("p_list_id" "uuid", "p_step_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_station_device"("p_device_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.operational_station_devices;
begin
  if not public.is_operational_stations_admin() then
    raise exception 'No autorizado.';
  end if;
  select * into v_old from public.operational_station_devices where id = p_device_id for update;
  if v_old.status <> 'active' then
    raise exception 'Solo se reemplaza un dispositivo activo.';
  end if;
  update public.operational_station_devices
  set status = 'replaced', updated_at = now(),
      metadata = metadata || jsonb_build_object('replace_reason', nullif(trim(p_reason), ''))
  where id = p_device_id;
  perform public.log_operational_station_event(
    v_old.station_id, v_old.id, 'device_replaced', auth.uid(), '{}'::jsonb, null
  );
  return jsonb_build_object('station_id', v_old.station_id, 'replaced_device_id', v_old.id);
end;
$$;


ALTER FUNCTION "public"."replace_station_device"("p_device_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pos_orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "table_id" "text",
    "table_name" "text",
    "area_id" "text",
    "area_name" "text",
    "waiter_id" "uuid",
    "waiter_name" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "subtotal" numeric DEFAULT 0 NOT NULL,
    "total" numeric DEFAULT 0 NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "sales_channel" "text" DEFAULT 'dine_in'::"text" NOT NULL,
    "customer_id" "uuid",
    "customer_address_id" "uuid",
    "delivery_notes" "text",
    "delivery_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "assigned_driver_id" "uuid",
    "external_source" "text",
    "external_order_id" "text",
    "owner_profile_id" "uuid",
    CONSTRAINT "pos_orders_delivery_status_check" CHECK (("delivery_status" = ANY (ARRAY['pending'::"text", 'preparing'::"text", 'ready'::"text", 'out_for_delivery'::"text", 'delivered'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "pos_orders_sales_channel_check" CHECK (("sales_channel" = ANY (ARRAY['dine_in'::"text", 'takeout'::"text", 'delivery'::"text", 'online'::"text"]))),
    CONSTRAINT "pos_orders_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'sent'::"text", 'awaiting_bill'::"text", 'sent_to_cashier'::"text", 'partially_paid'::"text", 'paid'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "pos_orders_subtotal_check" CHECK (("subtotal" >= (0)::numeric)),
    CONSTRAINT "pos_orders_total_check" CHECK (("total" >= (0)::numeric))
);


ALTER TABLE "public"."pos_orders" OWNER TO "postgres";


COMMENT ON COLUMN "public"."pos_orders"."owner_profile_id" IS 'Canonical order owner (mesero acreditado venta/ranking). Legacy alias: waiter_id.';



CREATE OR REPLACE FUNCTION "public"."request_pos_order_bill"("p_order_id" "uuid") RETURNS "public"."pos_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  updated_order public.pos_orders;
begin
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para solicitar cuenta.';
  end if;
  if exists (
    select 1 from public.pos_order_items
    where order_id = p_order_id and status = 'draft'
  ) then
    raise exception 'Envía o quita los productos nuevos antes de solicitar cuenta.';
  end if;
  update public.pos_orders
  set status = 'awaiting_bill'
  where id = p_order_id
    and status = 'open'
    and exists (
      select 1 from public.pos_order_items
      where order_id = p_order_id and status <> 'cancelled'
    )
  returning * into updated_order;
  if updated_order.id is null then
    raise exception 'La orden no está disponible para solicitar cuenta.';
  end if;
  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (p_order_id, 'bill_requested', 'Cuenta solicitada por el mesero.', auth.uid());
  return updated_order;
end;
$$;


ALTER FUNCTION "public"."request_pos_order_bill"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_station_pos_order_bill"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_order public.pos_orders;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'request_bill',
    jsonb_build_object('order_id', p_order_id)
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'request_bill', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'request_bill', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);

  if not public.station_pos_is_order_owner(p_order_id, v_operator_id) then
    raise exception '%', v_generic;
  end if;

  if exists (
    select 1 from public.pos_order_items
    where order_id = p_order_id and status = 'draft'
  ) then
    raise exception 'EnvÃ­a o quita los productos nuevos antes de solicitar cuenta.';
  end if;

  update public.pos_orders
  set status = 'awaiting_bill'
  where id = p_order_id
    and status = 'open'
    and exists (
      select 1 from public.pos_order_items
      where order_id = p_order_id and status <> 'cancelled'
    )
  returning * into v_order;

  if v_order.id is null then
    raise exception 'La orden no estÃ¡ disponible para solicitar cuenta.';
  end if;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (p_order_id, 'bill_requested', 'Cuenta solicitada por el mesero.', v_operator_id);

  v_result := jsonb_build_object('order_id', p_order_id, 'status', v_order.status);

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'request_bill', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    if sqlerrm like 'EnvÃ­a o quita%' or sqlerrm like 'La orden no%' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."request_station_pos_order_bill"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requisition_header_fulfillment_status"("p_all_fulfilled" boolean, "p_any_delivered" boolean, "p_any_pending" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_all_fulfilled then 'completed'
    when not p_any_delivered and p_any_pending then 'pending_fulfillment'
    else 'partially_fulfilled'
  end;
$$;


ALTER FUNCTION "public"."requisition_header_fulfillment_status"("p_all_fulfilled" boolean, "p_any_delivered" boolean, "p_any_pending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requisition_line_fulfillment_status"("p_requested" numeric, "p_delivered" numeric) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when coalesce(p_requested, 0) <= 0 then 'fulfilled'
    when coalesce(p_delivered, 0) <= 0 then 'out_of_stock'
    when coalesce(p_delivered, 0) >= coalesce(p_requested, 0) then 'fulfilled'
    else 'partial'
  end;
$$;


ALTER FUNCTION "public"."requisition_line_fulfillment_status"("p_requested" numeric, "p_delivered" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requisition_shortage_reason_required"("p_requested" numeric, "p_quantity" numeric) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(p_quantity, 0) < coalesce(p_requested, 0);
$$;


ALTER FUNCTION "public"."requisition_shortage_reason_required"("p_requested" numeric, "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_attendance_context"("p_employee_id" "uuid", "p_mark_type" "text" DEFAULT 'entrada'::"text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'America/Guatemala';
  v_mark_type text;
  v_calendar_date date;
  v_labor_date date;
  v_open_entry public.attendance_marks;
  v_open_meal public.attendance_marks;
  v_overnight record;
  v_shift_end_ts timestamptz;
  v_schedule_check jsonb;
  v_overnight_active boolean := false;
begin
  v_mark_type := lower(trim(coalesce(p_mark_type, 'entrada')));
  if v_mark_type = 'salida' then v_mark_type := 'salida_final'; end if;
  if v_mark_type = 'bano_inicio' then v_mark_type := 'salida_comida'; end if;
  if v_mark_type = 'bano_regreso' then v_mark_type := 'regreso_comida'; end if;

  v_calendar_date := (p_at at time zone v_tz)::date;

  select m.* into v_open_entry
  from public.attendance_marks m
  where m.employee_id = p_employee_id
    and m.mark_type = 'entrada'
    and not exists (
      select 1
      from public.attendance_marks out_mark
      where out_mark.employee_id = m.employee_id
        and out_mark.mark_type in ('salida_final', 'salida')
        and out_mark.marked_at > m.marked_at
    )
  order by m.marked_at desc
  limit 1;

  if v_open_entry.id is not null then
    v_labor_date := (v_open_entry.marked_at at time zone v_tz)::date;

    select m.* into v_open_meal
    from public.attendance_marks m
    where m.employee_id = p_employee_id
      and m.mark_type in ('salida_comida', 'bano_inicio')
      and m.marked_at > v_open_entry.marked_at
      and not exists (
        select 1
        from public.attendance_marks back_mark
        where back_mark.employee_id = m.employee_id
          and back_mark.mark_type in ('regreso_comida', 'bano_regreso')
          and back_mark.marked_at > m.marked_at
      )
    order by m.marked_at desc
    limit 1;

    return jsonb_build_object(
      'labor_date', v_labor_date,
      'calendar_date', v_calendar_date,
      'has_open_entry', true,
      'open_entry_id', v_open_entry.id,
      'open_entry_marked_at', v_open_entry.marked_at,
      'has_open_meal', v_open_meal.id is not null,
      'open_meal_id', v_open_meal.id,
      'schedule_check_required', v_mark_type = 'entrada',
      'overnight_shift', v_labor_date < v_calendar_date,
      'mark_type', v_mark_type
    );
  end if;

  v_labor_date := v_calendar_date;
  v_schedule_check := public.can_employee_mark_attendance(p_employee_id, v_labor_date);

  if coalesce((v_schedule_check ->> 'allowed')::boolean, false) = false
     and v_mark_type = 'entrada' then
    select
      s.id,
      s.shift_date,
      s.start_time,
      s.end_time
    into v_overnight
    from public.employee_schedules s
    left join public.shift_types st on st.id = s.shift_type_id
    where s.employee_id = p_employee_id
      and s.shift_date = v_calendar_date - 1
      and s.status in ('draft', 'published')
      and s.is_work_day = true
      and s.start_time is not null
      and s.end_time is not null
      and s.end_time <= s.start_time
      and coalesce(st.is_rest_day, false) = false
      and coalesce(st.is_holiday, false) = false
      and coalesce(s.shift_type, '') not in ('rest', 'asueto')
    order by case s.status when 'published' then 0 else 1 end, s.block_order, s.start_time
    limit 1;

    if v_overnight.id is not null then
      v_shift_end_ts := (
        (v_overnight.shift_date + interval '1 day') + v_overnight.end_time
      ) at time zone v_tz;

      if p_at <= v_shift_end_ts + interval '4 hours' then
        v_labor_date := v_overnight.shift_date;
        v_overnight_active := true;
        v_schedule_check := public.can_employee_mark_attendance(p_employee_id, v_labor_date);
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'labor_date', v_labor_date,
    'calendar_date', v_calendar_date,
    'has_open_entry', false,
    'open_entry_id', null,
    'open_entry_marked_at', null,
    'has_open_meal', false,
    'open_meal_id', null,
    'schedule_check_required', true,
    'overnight_shift', v_overnight_active,
    'mark_type', v_mark_type,
    'schedule_allowed', coalesce((v_schedule_check ->> 'allowed')::boolean, false),
    'schedule_id', v_schedule_check -> 'schedule_id',
    'schedule_status', v_schedule_check -> 'schedule_status',
    'schedule_reason_code', v_schedule_check -> 'reason_code'
  );
end;
$$;


ALTER FUNCTION "public"."resolve_attendance_context"("p_employee_id" "uuid", "p_mark_type" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_attendance_mark_permission"("p_employee_id" "uuid", "p_mark_type" "text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "public"."attendance_mark_permission"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_mark_type text := public.normalize_attendance_mark_type(p_mark_type);
  v_ctx jsonb;
  v_class jsonb;
  v_chain record;
  v_labor_date date;
  v_has_open_entry boolean;
  v_has_open_meal boolean;
  v_open_entry_id uuid;
  v_open_entry_at timestamptz;
  v_open_meal_id uuid;
  v_next_expected_mark text;
  v_reason_code text;
  v_reason text;
  v_result public.attendance_mark_permission;
begin
  if v_mark_type not in ('entrada', 'salida_comida', 'regreso_comida', 'salida_final') then
    v_result.allowed := false;
    v_result.reason_code := 'invalid_mark_type';
    v_result.reason := 'Tipo de marcaje no valido.';
    v_result.has_open_entry := false;
    v_result.has_open_meal := false;
    v_result.open_entry_id := null;
    v_result.open_entry_at := null;
    v_result.open_meal_id := null;
    v_result.next_expected_mark := null;
    v_result.labor_date := (p_at at time zone 'America/Guatemala')::date;
    v_result.classification := null;
    v_result.approval_status := null;
    return v_result;
  end if;

  v_ctx := public.resolve_attendance_context(p_employee_id, v_mark_type, p_at);
  v_labor_date := (v_ctx ->> 'labor_date')::date;
  v_has_open_entry := coalesce((v_ctx ->> 'has_open_entry')::boolean, false);
  v_has_open_meal := coalesce((v_ctx ->> 'has_open_meal')::boolean, false);
  v_open_entry_id := nullif(v_ctx ->> 'open_entry_id', '')::uuid;
  v_open_entry_at := nullif(v_ctx ->> 'open_entry_marked_at', '')::timestamptz;
  v_open_meal_id := nullif(v_ctx ->> 'open_meal_id', '')::uuid;

  v_class := public.classify_attendance_mark(p_employee_id, v_labor_date, v_mark_type, p_at);

  select *
  into v_chain
  from public.evaluate_attendance_mark_chain(v_mark_type, v_has_open_entry, v_has_open_meal);

  v_reason_code := v_chain.reason_code;
  v_reason := v_chain.reason;

  if v_mark_type = 'entrada'
     and v_chain.allowed
     and v_class ->> 'reason_code' is not null
     and v_class ->> 'reason_code' <> 'allowed' then
    v_reason_code := v_class ->> 'reason_code';
  end if;

  if not v_has_open_entry then
    v_next_expected_mark := 'entrada';
  elsif v_has_open_meal then
    v_next_expected_mark := 'regreso_comida';
  else
    v_next_expected_mark := 'salida_comida';
  end if;

  v_result.allowed := v_chain.allowed;
  v_result.reason_code := v_reason_code;
  v_result.reason := v_reason;
  v_result.has_open_entry := v_has_open_entry;
  v_result.has_open_meal := v_has_open_meal;
  v_result.open_entry_id := v_open_entry_id;
  v_result.open_entry_at := v_open_entry_at;
  v_result.open_meal_id := v_open_meal_id;
  v_result.next_expected_mark := v_next_expected_mark;
  v_result.labor_date := v_labor_date;
  v_result.classification := v_class ->> 'classification';
  v_result.approval_status := coalesce(v_class ->> 'approval_status', 'not_required');

  return v_result;
end;
$$;


ALTER FUNCTION "public"."resolve_attendance_mark_permission"("p_employee_id" "uuid", "p_mark_type" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_inventory_unit_factor"("p_from_unit" "text", "p_to_unit" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.try_global_unit_factor(p_from_unit, p_to_unit);
$$;


ALTER FUNCTION "public"."resolve_inventory_unit_factor"("p_from_unit" "text", "p_to_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_item_requisition_unit_factor"("p_item_id" "uuid", "p_requested_unit" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item_row public.inventory_items;
  requested text := nullif(trim(p_requested_unit), '');
  factor numeric;
begin
  if p_item_id is null then
    raise exception 'Producto invalido en la requisicion.';
  end if;
  if requested is null then
    raise exception 'Debes indicar la unidad solicitada.';
  end if;

  select * into item_row from public.inventory_items where id = p_item_id;
  if item_row.id is null then
    raise exception 'Producto no encontrado.';
  end if;

  if public.normalize_inventory_unit(requested) = public.normalize_inventory_unit(item_row.base_unit) then
    return 1;
  end if;

  if item_row.purchase_unit is not null
     and public.normalize_inventory_unit(requested) = public.normalize_inventory_unit(item_row.purchase_unit) then
    return greatest(coalesce(item_row.conversion_factor, 1), 0.0000001);
  end if;

  factor := public.try_global_unit_factor(requested, item_row.base_unit);
  if factor is not null then
    return factor;
  end if;

  raise exception
    'La unidad % no esta configurada para el producto %. Corrige la unidad o configura la conversion antes de enviar.',
    requested,
    item_row.name;
end;
$$;


ALTER FUNCTION "public"."resolve_item_requisition_unit_factor"("p_item_id" "uuid", "p_requested_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_login_profile"("p_email" "text") RETURNS TABLE("profile_id" "uuid", "profile_role" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select profile.id, public.normalize_profile_role(profile.role)
  from public.profiles profile
  where lower(trim(coalesce(profile.email, ''))) = lower(trim(coalesce(p_email, '')))
  limit 1;
$$;


ALTER FUNCTION "public"."resolve_login_profile"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_operational_device_for_auth_user"() RETURNS "public"."operational_station_devices"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_station public.operational_stations;
begin
  select * into v_device
  from public.operational_station_devices
  where auth_user_id = auth.uid() and status = 'active'
  limit 1;
  if v_device.id is null then
    return null;
  end if;
  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.id is null
    or v_station.status <> 'active'
    or v_device.status <> 'active' then
    return null;
  end if;
  return v_device;
end;
$$;


ALTER FUNCTION "public"."resolve_operational_device_for_auth_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_station_cash_operator_context"("p_operator_session_token" "text", "p_extend_idle" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_station public.operational_stations;
  v_hash text;
  v_op_session public.operational_operator_sessions;
  v_operator public.profiles;
  v_role text;
  v_idle_expires timestamptz;
  v_generic constant text := 'Operacion no permitida.';
begin
  if nullif(trim(coalesce(p_operator_session_token, '')), '') is null then
    raise exception '%', v_generic;
  end if;

  v_device := public.resolve_operational_device_for_auth_user();
  if v_device.id is null then
    raise exception '%', v_generic;
  end if;

  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.id is null
    or v_station.status <> 'active'
    or v_station.station_type <> 'cash'
    or v_station.cash_register_id is null then
    raise exception '%', v_generic;
  end if;

  v_hash := encode(extensions.digest(trim(p_operator_session_token), 'sha256'), 'hex');
  select * into v_op_session
  from public.operational_operator_sessions
  where session_token_hash = v_hash
    and operational_station_device_id = v_device.id
    and revoked_at is null
  for update;

  if v_op_session.id is null or v_op_session.idle_expires_at <= now() then
    if v_op_session.id is not null then
      update public.operational_operator_sessions
      set revoked_at = now(), revoke_reason = 'expired'
      where id = v_op_session.id;
    end if;
    raise exception '%', v_generic;
  end if;

  if v_op_session.module <> 'cash'
    or v_op_session.operational_station_id <> v_station.id then
    raise exception '%', v_generic;
  end if;

  select * into v_operator from public.profiles where id = v_op_session.operator_profile_id;
  if v_operator.id is null or v_operator.status <> 'active' then
    raise exception '%', v_generic;
  end if;

  if not exists (
    select 1 from public.operational_station_assignments a
    where a.profile_id = v_operator.id
      and a.station_id = v_station.id
      and a.active
  ) then
    raise exception '%', v_generic;
  end if;

  v_role := public.station_cash_operator_role(v_operator.id);
  if not public.station_cash_is_operator_role(v_operator.id) then
    raise exception '%', v_generic;
  end if;

  if coalesce(p_extend_idle, true) then
    update public.operational_operator_sessions
    set last_activity_at = now(),
        idle_expires_at = now() + interval '90 seconds'
    where id = v_op_session.id;
    v_idle_expires := now() + interval '90 seconds';
  else
    v_idle_expires := v_op_session.idle_expires_at;
  end if;

  return jsonb_build_object(
    'device_id', v_device.id,
    'station_id', v_station.id,
    'station_name', v_station.name,
    'station_code', v_station.station_code,
    'cash_register_id', v_station.cash_register_id,
    'operator_profile_id', v_operator.id,
    'operator_name', coalesce(v_operator.full_name, v_operator.username),
    'operator_role', v_role,
    'operator_session_id', v_op_session.id,
    'can_supervise', public.station_cash_is_supervisor(v_operator.id),
    'idle_expires_at', v_idle_expires
  );
end;
$$;


ALTER FUNCTION "public"."resolve_station_cash_operator_context"("p_operator_session_token" "text", "p_extend_idle" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_station_pos_operator_context"("p_operator_session_token" "text", "p_extend_idle" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_station public.operational_stations;
  v_hash text;
  v_op_session public.operational_operator_sessions;
  v_operator public.profiles;
  v_idle_expires timestamptz;
  v_absolute_expires timestamptz;
  v_generic constant text := 'Operacion no permitida.';
  v_pin_generic constant text := 'PIN o acceso no valido.';
begin
  if not public.operational_stations_enabled() or not public.operational_station_pos_enabled() then
    raise exception '%', v_generic;
  end if;

  if nullif(trim(coalesce(p_operator_session_token, '')), '') is null then
    raise exception '%', v_pin_generic;
  end if;

  v_device := public.resolve_operational_device_for_auth_user();
  if v_device.id is null or v_device.status <> 'active' then
    raise exception '%', v_generic;
  end if;

  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.id is null
    or v_station.status <> 'active'
    or v_station.station_type <> 'pos' then
    raise exception '%', v_generic;
  end if;

  v_hash := encode(extensions.digest(trim(p_operator_session_token), 'sha256'), 'hex');
  select * into v_op_session
  from public.operational_operator_sessions
  where session_token_hash = v_hash
    and operational_station_device_id = v_device.id
    and revoked_at is null
  for update;

  if v_op_session.id is null
    or v_op_session.idle_expires_at <= now()
    or (v_op_session.absolute_expires_at is not null and v_op_session.absolute_expires_at <= now()) then
    if v_op_session.id is not null then
      update public.operational_operator_sessions
      set revoked_at = now(), revoke_reason = 'expired'
      where id = v_op_session.id;
    end if;
    raise exception '%', v_pin_generic;
  end if;

  if v_op_session.module <> 'pos'
    or v_op_session.operational_station_id <> v_station.id then
    raise exception '%', v_generic;
  end if;

  select * into v_operator from public.profiles where id = v_op_session.operator_profile_id;
  if v_operator.id is null or v_operator.status <> 'active' then
    raise exception '%', v_generic;
  end if;

  if not exists (
    select 1 from public.operational_station_assignments a
    where a.profile_id = v_operator.id
      and a.station_id = v_station.id
      and a.active
  ) then
    raise exception '%', v_generic;
  end if;

  if not public.station_pos_can_operate_orders(v_operator.id) then
    raise exception '%', v_generic;
  end if;

  v_absolute_expires := v_op_session.absolute_expires_at;

  if coalesce(p_extend_idle, true) then
    perform public.station_pos_extend_operator_idle(v_op_session.id);
    select idle_expires_at into v_idle_expires
    from public.operational_operator_sessions
    where id = v_op_session.id;
  else
    v_idle_expires := v_op_session.idle_expires_at;
  end if;

  return jsonb_build_object(
    'device_id', v_device.id,
    'station_id', v_station.id,
    'station_name', v_station.name,
    'station_code', v_station.station_code,
    'pos_floor_zone', v_station.pos_floor_zone,
    'operator_profile_id', v_operator.id,
    'operator_name', coalesce(v_operator.full_name, v_operator.username),
    'operator_session_id', v_op_session.id,
    'idle_expires_at', v_idle_expires,
    'absolute_expires_at', v_absolute_expires
  );
end;
$$;


ALTER FUNCTION "public"."resolve_station_pos_operator_context"("p_operator_session_token" "text", "p_extend_idle" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_operational_task"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_perms jsonb;
  v_old_archived timestamptz;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is not null
  for update;

  if not found then raise exception 'Tarea archivada no encontrada.'; end if;

  v_perms := public.get_operational_task_permissions(v_task);
  if not coalesce((v_perms ->> 'can_restore')::boolean, false) then
    raise exception 'No tienes permiso para restaurar esta tarea.';
  end if;

  v_old_archived := v_task.archived_at;

  update public.assigned_tasks
  set archived_at = null,
      archived_by = null,
      updated_at = now()
  where id = p_task_id
  returning * into v_task;

  perform public.log_task_activity(
    p_task_id, 'restored', 'archived_at', to_jsonb(v_old_archived), null, '{}'::jsonb
  );

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."restore_operational_task"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_attendance_mark"("p_mark_id" "uuid", "p_action" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_marks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.attendance_marks;
  next_status text;
  entry_mark public.attendance_marks;
begin
  if not public.is_attendance_manager() then
    raise exception 'No tienes permiso para revisar marcaciones.';
  end if;

  next_status := case lower(trim(coalesce(p_action, '')))
    when 'approve' then 'approved'
    when 'reject' then 'rejected'
    else null
  end;
  if next_status is null then
    raise exception 'Acción de revisión no válida.';
  end if;

  select * into target from public.attendance_marks where id = p_mark_id;
  if target.id is null then
    raise exception 'Marcación no encontrada.';
  end if;

  update public.attendance_marks
  set
    approval_status = next_status,
    approved_by = auth.uid(),
    approved_at = now(),
    approval_notes = nullif(trim(p_notes), '')
  where id = p_mark_id
  returning * into target;

  if target.mark_type = 'entrada' then
    update public.attendance_marks m
    set
      approval_status = next_status,
      approved_by = auth.uid(),
      approved_at = now(),
      approval_notes = coalesce(nullif(trim(p_notes), ''), m.approval_notes)
    where m.employee_id = target.employee_id
      and m.marked_at >= target.marked_at
      and m.approval_status = 'pending'
      and m.id <> target.id
      and not exists (
        select 1
        from public.attendance_marks out_mark
        where out_mark.employee_id = target.employee_id
          and out_mark.mark_type in ('salida_final', 'salida')
          and out_mark.marked_at > target.marked_at
          and out_mark.marked_at < m.marked_at
      );
  end if;

  return target;
end;
$$;


ALTER FUNCTION "public"."review_attendance_mark"("p_mark_id" "uuid", "p_action" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_payroll_summary"("p_employee_id" "uuid", "p_week_start" "date", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  row_data record;
begin
  if not public.is_schedule_publisher() then raise exception 'No tienes permiso para revisar planilla.'; end if;
  if p_status not in ('pending', 'reviewed', 'approved') then raise exception 'Estado invalido.'; end if;
  select * into row_data from public.get_schedule_attendance_summary(p_week_start) where employee_id = p_employee_id;
  if row_data.employee_id is null then raise exception 'No existe resumen para este colaborador.'; end if;
  insert into public.payroll_summaries (
    employee_id, week_start, week_end, scheduled_hours, actual_hours, regular_hours,
    overtime_hours, late_minutes, absences, estimated_pay, status, reviewed_by, approved_by
  ) values (
    p_employee_id, p_week_start, p_week_start + 6, row_data.scheduled_hours, row_data.actual_hours,
    row_data.regular_hours, row_data.overtime_hours, row_data.late_minutes, row_data.absences,
    row_data.estimated_pay, p_status,
    case when p_status in ('reviewed', 'approved') then auth.uid() else null end,
    case when p_status = 'approved' then auth.uid() else null end
  )
  on conflict (employee_id, week_start) do update set
    scheduled_hours = excluded.scheduled_hours, actual_hours = excluded.actual_hours,
    regular_hours = excluded.regular_hours, overtime_hours = excluded.overtime_hours,
    late_minutes = excluded.late_minutes, absences = excluded.absences,
    estimated_pay = excluded.estimated_pay, status = excluded.status,
    reviewed_by = excluded.reviewed_by, approved_by = excluded.approved_by, updated_at = now();
end;
$$;


ALTER FUNCTION "public"."review_payroll_summary"("p_employee_id" "uuid", "p_week_start" "date", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_station_device"("p_device_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."operational_station_devices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
begin
  if not public.is_operational_stations_admin() then
    raise exception 'No autorizado.';
  end if;
  update public.operational_station_devices
  set status = 'revoked', revoked_at = now(), updated_at = now(),
      metadata = metadata || jsonb_build_object('revoke_reason', nullif(trim(p_reason), ''))
  where id = p_device_id and status = 'active'
  returning * into v_device;
  if v_device.id is null then
    raise exception 'Dispositivo activo no encontrado.';
  end if;
  perform public.log_operational_station_event(
    v_device.station_id, v_device.id, 'device_revoked', auth.uid(), '{}'::jsonb, null
  );
  return v_device;
end;
$$;


ALTER FUNCTION "public"."revoke_station_device"("p_device_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_user_auth_sessions"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_user_id is null then
    raise exception 'user_id requerido';
  end if;

  delete from auth.refresh_tokens where user_id = p_user_id;
  delete from auth.sessions where user_id = p_user_id;
end;
$$;


ALTER FUNCTION "public"."revoke_user_auth_sessions"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sanitize_attendance_observation"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(trim(
    regexp_replace(
      regexp_replace(
        coalesce(p_text, ''),
        '(\n|\r\n)?__device_ua__:[^\n]*',
        '',
        'gi'
      ),
      '(^|\s)(device_ua|user_agent|session_id|raw_metadata|ip_address)\s*[:=][^\n]*',
      '',
      'gi'
    )
  ), '');
$$;


ALTER FUNCTION "public"."sanitize_attendance_observation"("p_text" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bakery_production_diary_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_id" "uuid" NOT NULL,
    "start_time" timestamp with time zone,
    "end_time" timestamp with time zone,
    "ambient_temperature" numeric,
    "planned_quantity" numeric,
    "actual_quantity" numeric,
    "recipe_id" "uuid",
    "process_notes" "text",
    "quality_result" "text",
    "issues_detected" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bakery_production_diary_entries_actual_quantity_check" CHECK ((("actual_quantity" IS NULL) OR ("actual_quantity" >= (0)::numeric))),
    CONSTRAINT "bakery_production_diary_entries_quality_result_check" CHECK ((("quality_result" IS NULL) OR ("quality_result" = ANY (ARRAY['good'::"text", 'acceptable'::"text", 'failed'::"text"]))))
);


ALTER TABLE "public"."bakery_production_diary_entries" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_bakery_diary_entry"("p_payload" "jsonb") RETURNS "public"."bakery_production_diary_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_batch public.bakery_production_batches;
  v_entry public.bakery_production_diary_entries;
  v_actual numeric := nullif(p_payload ->> 'actual_quantity', '')::numeric;
begin
  if not public.can_operate_bakery_production() then
    raise exception 'PERMISSION_DENIED';
  end if;

  select * into v_batch
  from public.bakery_production_batches
  where id = (p_payload ->> 'batch_id')::uuid
  for update;

  if v_batch.id is null then
    raise exception 'Lote de producción no encontrado.';
  end if;
  if v_batch.status not in ('created', 'in_progress') then
    raise exception 'El lote no está en producción.';
  end if;
  if v_actual is null then
    raise exception 'Indica la cantidad real producida.';
  end if;

  insert into public.bakery_production_diary_entries (
    batch_id, start_time, end_time, ambient_temperature,
    planned_quantity, actual_quantity, recipe_id,
    process_notes, quality_result, issues_detected, created_by
  )
  values (
    v_batch.id,
    nullif(p_payload ->> 'start_time', '')::timestamptz,
    nullif(p_payload ->> 'end_time', '')::timestamptz,
    nullif(p_payload ->> 'ambient_temperature', '')::numeric,
    coalesce(nullif(p_payload ->> 'planned_quantity', '')::numeric, v_batch.planned_quantity),
    v_actual,
    coalesce(nullif(p_payload ->> 'recipe_id', '')::uuid, v_batch.recipe_id),
    nullif(trim(p_payload ->> 'process_notes'), ''),
    nullif(trim(p_payload ->> 'quality_result'), ''),
    nullif(trim(p_payload ->> 'issues_detected'), ''),
    auth.uid()
  )
  on conflict (batch_id) do update
  set
    start_time = excluded.start_time,
    end_time = excluded.end_time,
    ambient_temperature = excluded.ambient_temperature,
    planned_quantity = excluded.planned_quantity,
    actual_quantity = excluded.actual_quantity,
    recipe_id = excluded.recipe_id,
    process_notes = excluded.process_notes,
    quality_result = excluded.quality_result,
    issues_detected = excluded.issues_detected,
    updated_at = now()
  returning * into v_entry;

  update public.bakery_production_batches
  set
    actual_quantity = v_actual,
    status = 'in_progress',
    started_at = coalesce(started_at, now()),
    updated_at = now()
  where id = v_batch.id;

  return v_entry;
end;
$$;


ALTER FUNCTION "public"."save_bakery_diary_entry"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_catering_quote_as_template"("p_quote_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT 'general'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_items jsonb := '[]'::jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'item_type', item.item_type,
    'description', item.description,
    'quantity', item.quantity,
    'quantity_unit', item.quantity_unit,
    'unit_price', item.unit_price,
    'sort_order', item.sort_order
  ) order by item.sort_order asc), '[]'::jsonb)
  into v_items
  from public.catering_quote_items item
  where item.quote_id = p_quote_id;

  if v_items = '[]'::jsonb then
    raise exception 'La cotizacion no tiene lineas para guardar como plantilla.';
  end if;

  return public.upsert_catering_quote_template(null, p_name, p_description, p_category, true, v_items);
end;
$$;


ALTER FUNCTION "public"."save_catering_quote_as_template"("p_quote_id" "uuid", "p_name" "text", "p_description" "text", "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_catering_quote_settings"("p_settings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current jsonb := public.get_catering_quote_settings();
  v_next jsonb;
begin
  if not public.can_edit_catering_quote_settings() then
    raise exception 'No tienes permiso para editar configuracion de cotizaciones.';
  end if;

  v_next := v_current || coalesce(p_settings, '{}'::jsonb);

  insert into public.app_settings (key, value)
  values ('catering_quote_settings', v_next)
  on conflict (key) do update set value = excluded.value, updated_at = now();

  return public.get_catering_quote_settings();
end;
$$;


ALTER FUNCTION "public"."save_catering_quote_settings"("p_settings" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_custom_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "shift_type_id" "uuid",
    "weekday" integer,
    "specific_date" "date",
    "start_date" "date",
    "end_date" "date",
    "start_time" time without time zone,
    "end_time" time without time zone,
    "notes" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "employee_custom_schedules_check" CHECK ((("end_date" IS NULL) OR ("start_date" IS NULL) OR ("end_date" >= "start_date"))),
    CONSTRAINT "employee_custom_schedules_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text"]))),
    CONSTRAINT "employee_custom_schedules_weekday_check" CHECK ((("weekday" IS NULL) OR (("weekday" >= 0) AND ("weekday" <= 6))))
);


ALTER TABLE "public"."employee_custom_schedules" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_custom_schedule"("p_data" "jsonb") RETURNS "public"."employee_custom_schedules"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.employee_custom_schedules;
  custom_id uuid := nullif(p_data ->> 'id', '')::uuid;
  target_profile_id uuid := nullif(p_data ->> 'profile_id', '')::uuid;
begin
  if not public.is_shift_type_manager() then
    raise exception 'No tienes permiso para gestionar turnos especiales.';
  end if;
  if target_profile_id is null then
    raise exception 'El colaborador es obligatorio.';
  end if;

  if custom_id is null then
    insert into public.employee_custom_schedules (
      profile_id, shift_type_id, weekday, specific_date, start_date, end_date,
      start_time, end_time, notes, status
    ) values (
      target_profile_id,
      nullif(p_data ->> 'shift_type_id', '')::uuid,
      nullif(p_data ->> 'weekday', '')::integer,
      nullif(p_data ->> 'specific_date', '')::date,
      nullif(p_data ->> 'start_date', '')::date,
      nullif(p_data ->> 'end_date', '')::date,
      nullif(p_data ->> 'start_time', '')::time,
      nullif(p_data ->> 'end_time', '')::time,
      nullif(trim(p_data ->> 'notes'), ''),
      coalesce(nullif(p_data ->> 'status', ''), 'active')
    ) returning * into saved;
  else
    update public.employee_custom_schedules set
      profile_id = target_profile_id,
      shift_type_id = nullif(p_data ->> 'shift_type_id', '')::uuid,
      weekday = nullif(p_data ->> 'weekday', '')::integer,
      specific_date = nullif(p_data ->> 'specific_date', '')::date,
      start_date = nullif(p_data ->> 'start_date', '')::date,
      end_date = nullif(p_data ->> 'end_date', '')::date,
      start_time = nullif(p_data ->> 'start_time', '')::time,
      end_time = nullif(p_data ->> 'end_time', '')::time,
      notes = nullif(trim(p_data ->> 'notes'), ''),
      status = coalesce(nullif(p_data ->> 'status', ''), 'active'),
      updated_at = now()
    where id = custom_id
    returning * into saved;
    if saved.id is null then raise exception 'El turno especial no existe.'; end if;
  end if;

  return saved;
end;
$$;


ALTER FUNCTION "public"."save_employee_custom_schedule"("p_data" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "area" "text",
    "position" "text",
    "shift_date" "date" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "break_minutes" integer DEFAULT 0 NOT NULL,
    "notes" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "published_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_work_day" boolean DEFAULT true NOT NULL,
    "shift_type" "text" DEFAULT 'full'::"text" NOT NULL,
    "block_order" integer DEFAULT 1 NOT NULL,
    "day_notes" "text",
    "shift_type_id" "uuid",
    CONSTRAINT "employee_schedules_break_minutes_check" CHECK (("break_minutes" >= 0)),
    CONSTRAINT "employee_schedules_shift_type_check" CHECK ((NULLIF(TRIM(BOTH FROM "shift_type"), ''::"text") IS NOT NULL)),
    CONSTRAINT "employee_schedules_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text"]))),
    CONSTRAINT "employee_schedules_work_day_time_check" CHECK ((("is_work_day" = false) OR (("is_work_day" = true) AND ("start_time" IS NOT NULL) AND ("end_time" IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE("area", ''::"text")), ''::"text") IS NOT NULL))))
);


ALTER TABLE "public"."employee_schedules" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_schedule"("p_data" "jsonb") RETURNS "public"."employee_schedules"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing public.employee_schedules;
  saved public.employee_schedules;
  schedule_id uuid;
  v_employee_id uuid := (p_data ->> 'employee_id')::uuid;
  v_shift_type_id uuid := nullif(p_data ->> 'shift_type_id', '')::uuid;
  v_is_work_day boolean := coalesce((p_data ->> 'is_work_day')::boolean, true);
  v_shift_type text := coalesce(nullif(p_data ->> 'shift_type', ''), 'full');
  normalized jsonb;
begin
  if not public.is_schedule_editor() then
    raise exception 'No tienes permiso para editar horarios.';
  end if;
  if v_employee_id is null then
    raise exception 'Colaborador es obligatorio.';
  end if;

  normalized := public.normalize_employee_schedule_fields(
    v_shift_type_id,
    v_shift_type,
    v_is_work_day,
    p_data ->> 'area',
    nullif(p_data ->> 'start_time', '')::time,
    nullif(p_data ->> 'end_time', '')::time,
    coalesce((p_data ->> 'break_minutes')::integer, 0),
    p_data ->> 'position'
  );

  schedule_id := nullif(p_data ->> 'id', '')::uuid;
  if schedule_id is not null then
    select * into existing from public.employee_schedules where id = schedule_id;
    if existing.id is null then raise exception 'Turno no encontrado.'; end if;
    if existing.status = 'published' and not public.is_schedule_publisher() then
      raise exception 'Solo Admin, Gerente General o RRHH pueden editar un horario publicado.';
    end if;
    update public.employee_schedules set
      employee_id = v_employee_id,
      area = normalized ->> 'area',
      position = nullif(normalized ->> 'position', ''),
      shift_date = (p_data ->> 'shift_date')::date,
      start_time = nullif(normalized ->> 'start_time', '')::time,
      end_time = nullif(normalized ->> 'end_time', '')::time,
      break_minutes = (normalized ->> 'break_minutes')::integer,
      notes = nullif(trim(p_data ->> 'notes'), ''),
      day_notes = nullif(trim(coalesce(p_data ->> 'day_notes', p_data ->> 'notes')), ''),
      is_work_day = (normalized ->> 'is_work_day')::boolean,
      shift_type = normalized ->> 'shift_type',
      shift_type_id = nullif(normalized ->> 'shift_type_id', '')::uuid,
      block_order = greatest(1, coalesce((p_data ->> 'block_order')::integer, 1)),
      updated_by = auth.uid(),
      updated_at = now()
    where id = schedule_id returning * into saved;
    insert into public.schedule_change_logs (schedule_id, changed_by, change_type, old_value, new_value)
    values (saved.id, auth.uid(), 'updated', to_jsonb(existing), to_jsonb(saved));
  else
    insert into public.employee_schedules (
      employee_id, area, position, shift_date, start_time, end_time, break_minutes, notes,
      status, created_by, updated_by, is_work_day, shift_type, shift_type_id, block_order, day_notes
    ) values (
      v_employee_id,
      normalized ->> 'area',
      nullif(normalized ->> 'position', ''),
      (p_data ->> 'shift_date')::date,
      nullif(normalized ->> 'start_time', '')::time,
      nullif(normalized ->> 'end_time', '')::time,
      (normalized ->> 'break_minutes')::integer,
      nullif(trim(p_data ->> 'notes'), ''),
      'draft', auth.uid(), auth.uid(),
      (normalized ->> 'is_work_day')::boolean,
      normalized ->> 'shift_type',
      nullif(normalized ->> 'shift_type_id', '')::uuid,
      greatest(1, coalesce((p_data ->> 'block_order')::integer, 1)),
      nullif(trim(coalesce(p_data ->> 'day_notes', p_data ->> 'notes')), '')
    ) returning * into saved;
    insert into public.schedule_change_logs (schedule_id, changed_by, change_type, new_value)
    values (saved.id, auth.uid(), 'created', to_jsonb(saved));
  end if;
  return saved;
end;
$$;


ALTER FUNCTION "public"."save_employee_schedule"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_pos_catalog_product"("p_product_id" "uuid", "p_product" "jsonb", "p_variants" "jsonb" DEFAULT '[]'::"jsonb", "p_modifiers" "jsonb" DEFAULT '[]'::"jsonb", "p_option_groups" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."pos_products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.pos_products;
  recipe public.standard_recipes;
  variant_row jsonb;
  modifier_row jsonb;
  group_row jsonb;
  choice_row jsonb;
  variant_ids uuid[] := '{}'::uuid[];
  modifier_ids uuid[] := '{}'::uuid[];
  group_ids uuid[] := '{}'::uuid[];
  choice_ids uuid[] := '{}'::uuid[];
  saved_variant_id uuid;
  saved_modifier_id uuid;
  saved_group_id uuid;
  saved_choice_id uuid;
  v_product_type text := coalesce(nullif(trim(p_product ->> 'product_type'), ''), 'simple');
  v_active boolean := coalesce((p_product ->> 'active')::boolean, true);
  v_is_test boolean := coalesce((p_product ->> 'is_test_item')::boolean, false) or v_product_type = 'manual_test';
  v_recipe_id uuid := nullif(p_product ->> 'recipe_id', '')::uuid;
  v_area_id text := nullif(trim(p_product ->> 'production_area_id'), '');
  v_mode text := public.get_inventory_deduction_mode();
  v_recipe_required boolean := coalesce((p_product ->> 'recipe_required_for_sale')::boolean, false);
  v_tracking boolean := coalesce((p_product ->> 'inventory_tracking_enabled')::boolean, false);
  v_selection_mode text;
  v_active_choice_count integer;
begin
  perform set_config('pos.suppress_catalog_refresh', 'true', true);

  if not public.is_profile_manager() then
    raise exception 'No tienes permiso para guardar productos POS.';
  end if;

  if nullif(trim(p_product ->> 'name'), '') is null then
    raise exception 'El nombre del producto POS es obligatorio.';
  end if;

  if v_area_id is null and v_active then
    raise exception 'Selecciona el area de preparacion del producto.';
  end if;

  if v_product_type not in ('pizza', 'simple', 'beverage', 'dessert', 'manual_test', 'configurable') then
    raise exception 'Tipo de producto invalido.';
  end if;

  if v_product_type not in ('pizza', 'configurable') and not v_is_test then
    if v_recipe_id is null and (v_mode = 'strict' or v_recipe_required) then
      raise exception 'El producto necesita una receta conectada.';
    end if;

    if v_recipe_id is not null then
      select * into recipe
      from public.standard_recipes
      where id = v_recipe_id
        and active = true
        and recipe_type = 'final_product';
      if recipe.id is null then
        raise exception 'La receta conectada no es valida.';
      end if;
      if recipe.production_area_id is distinct from v_area_id then
        raise exception 'El area del producto debe coincidir con el area de la receta conectada.';
      end if;
    end if;
  end if;

  if v_product_type = 'configurable' and v_active then
    if jsonb_array_length(coalesce(p_option_groups, '[]'::jsonb)) = 0 then
      raise exception 'Un producto configurable activo requiere al menos un grupo de opciones.';
    end if;

    for group_row in select value from jsonb_array_elements(coalesce(p_option_groups, '[]'::jsonb))
    loop
      if coalesce((group_row ->> 'is_active')::boolean, true) = false then
        continue;
      end if;

      if nullif(trim(group_row ->> 'name'), '') is null then
        raise exception 'Cada grupo activo debe tener nombre.';
      end if;

      v_selection_mode := coalesce(nullif(trim(group_row ->> 'selection_mode'), ''), 'single');
      if v_selection_mode not in ('single', 'multiple') then
        raise exception 'Modo de seleccion invalido en grupo %. ', group_row ->> 'name';
      end if;

      if v_selection_mode = 'single'
         and nullif(group_row ->> 'max_selections', '') is not null
         and (group_row ->> 'max_selections')::integer <> 1 then
        raise exception 'El grupo % con seleccion unica debe tener max_selections = 1.', group_row ->> 'name';
      end if;

      select count(*) into v_active_choice_count
      from jsonb_array_elements(coalesce(group_row -> 'choices', '[]'::jsonb)) choice(value)
      where coalesce((choice.value ->> 'is_active')::boolean, true)
        and nullif(trim(choice.value ->> 'name'), '') is not null;

      if coalesce((group_row ->> 'required')::boolean, false) and v_active_choice_count = 0 then
        raise exception 'El grupo requerido % debe tener al menos una opcion activa.', group_row ->> 'name';
      end if;
    end loop;
  end if;

  if p_product_id is null then
    insert into public.pos_products (
      name, description, price, image_url, category_id, category_name,
      recipe_id, production_area_id, active, is_test_item, product_type,
      allow_kitchen_notes, prep_time_minutes, sort_order,
      inventory_tracking_enabled, recipe_required_for_sale, created_by
    ) values (
      trim(p_product ->> 'name'),
      nullif(trim(p_product ->> 'description'), ''),
      coalesce((p_product ->> 'price')::numeric, 0),
      nullif(trim(p_product ->> 'image_url'), ''),
      nullif(trim(p_product ->> 'category_id'), ''),
      nullif(trim(p_product ->> 'category_name'), ''),
      case when v_product_type in ('pizza', 'configurable') or v_is_test then null else v_recipe_id end,
      v_area_id,
      v_active,
      v_is_test,
      v_product_type,
      coalesce((p_product ->> 'allow_kitchen_notes')::boolean, false),
      coalesce((p_product ->> 'prep_time_minutes')::integer, 15),
      coalesce((p_product ->> 'sort_order')::integer, 0),
      v_tracking,
      v_recipe_required,
      auth.uid()
    )
    returning * into saved;
  else
    update public.pos_products
    set
      name = trim(p_product ->> 'name'),
      description = nullif(trim(p_product ->> 'description'), ''),
      price = coalesce((p_product ->> 'price')::numeric, 0),
      image_url = nullif(trim(p_product ->> 'image_url'), ''),
      category_id = nullif(trim(p_product ->> 'category_id'), ''),
      category_name = nullif(trim(p_product ->> 'category_name'), ''),
      recipe_id = case when v_product_type in ('pizza', 'configurable') or v_is_test then null else v_recipe_id end,
      production_area_id = v_area_id,
      active = v_active,
      is_test_item = v_is_test,
      product_type = v_product_type,
      allow_kitchen_notes = coalesce((p_product ->> 'allow_kitchen_notes')::boolean, false),
      prep_time_minutes = coalesce((p_product ->> 'prep_time_minutes')::integer, 15),
      sort_order = coalesce((p_product ->> 'sort_order')::integer, 0),
      inventory_tracking_enabled = v_tracking,
      recipe_required_for_sale = v_recipe_required
    where id = p_product_id
    returning * into saved;

    if saved.id is null then
      raise exception 'El producto POS seleccionado no existe.';
    end if;
  end if;

  if v_product_type = 'pizza' then
    for variant_row in select value from jsonb_array_elements(coalesce(p_variants, '[]'::jsonb))
    loop
      if nullif(trim(variant_row ->> 'size'), '') is null then
        continue;
      end if;

      saved_variant_id := null;

      if nullif(variant_row ->> 'id', '') is null then
        insert into public.pos_product_variants (
          product_id, name, size, price, recipe_id, prep_time_minutes, is_active, sort_order
        ) values (
          saved.id,
          coalesce(nullif(trim(variant_row ->> 'name'), ''), saved.name),
          trim(variant_row ->> 'size'),
          coalesce((variant_row ->> 'price')::numeric, 0),
          nullif(variant_row ->> 'recipe_id', '')::uuid,
          coalesce((variant_row ->> 'prep_time_minutes')::integer, 0),
          coalesce((variant_row ->> 'is_active')::boolean, false),
          coalesce((variant_row ->> 'sort_order')::integer, 0)
        )
        returning id into saved_variant_id;
      else
        update public.pos_product_variants
        set
          name = coalesce(nullif(trim(variant_row ->> 'name'), ''), saved.name),
          size = trim(variant_row ->> 'size'),
          price = coalesce((variant_row ->> 'price')::numeric, 0),
          recipe_id = nullif(variant_row ->> 'recipe_id', '')::uuid,
          prep_time_minutes = coalesce((variant_row ->> 'prep_time_minutes')::integer, 0),
          is_active = coalesce((variant_row ->> 'is_active')::boolean, false),
          sort_order = coalesce((variant_row ->> 'sort_order')::integer, 0)
        where id = (variant_row ->> 'id')::uuid
          and product_id = saved.id
        returning id into saved_variant_id;

        if saved_variant_id is null then
          insert into public.pos_product_variants (
            product_id, name, size, price, recipe_id, prep_time_minutes, is_active, sort_order
          ) values (
            saved.id,
            coalesce(nullif(trim(variant_row ->> 'name'), ''), saved.name),
            trim(variant_row ->> 'size'),
            coalesce((variant_row ->> 'price')::numeric, 0),
            nullif(variant_row ->> 'recipe_id', '')::uuid,
            coalesce((variant_row ->> 'prep_time_minutes')::integer, 0),
            coalesce((variant_row ->> 'is_active')::boolean, false),
            coalesce((variant_row ->> 'sort_order')::integer, 0)
          )
          returning id into saved_variant_id;
        end if;
      end if;

      if saved_variant_id is not null then
        variant_ids := array_append(variant_ids, saved_variant_id);
      end if;
    end loop;

    delete from public.pos_product_variants
    where product_id = saved.id
      and (cardinality(variant_ids) = 0 or id <> all(variant_ids));

    update public.pos_products
    set price = coalesce((
      select min(variant.price)
      from public.pos_product_variants variant
      where variant.product_id = saved.id
        and variant.is_active = true
    ), 0)
    where id = saved.id
    returning * into saved;
  else
    delete from public.pos_product_variants
    where product_id = saved.id;
  end if;

  if v_product_type = 'configurable' then
    for group_row in select value from jsonb_array_elements(coalesce(p_option_groups, '[]'::jsonb))
    loop
      if nullif(trim(group_row ->> 'name'), '') is null then
        continue;
      end if;

      saved_group_id := null;
      v_selection_mode := coalesce(nullif(trim(group_row ->> 'selection_mode'), ''), 'single');

      if nullif(group_row ->> 'id', '') is null then
        insert into public.pos_option_groups (
          product_id, name, sort_order, required, selection_mode,
          min_selections, max_selections, is_active
        ) values (
          saved.id,
          trim(group_row ->> 'name'),
          coalesce((group_row ->> 'sort_order')::integer, 0),
          coalesce((group_row ->> 'required')::boolean, false),
          v_selection_mode,
          coalesce((group_row ->> 'min_selections')::integer, case when v_selection_mode = 'single' then 1 else 0 end),
          case
            when v_selection_mode = 'single' then 1
            else nullif(group_row ->> 'max_selections', '')::integer
          end,
          coalesce((group_row ->> 'is_active')::boolean, true)
        )
        returning id into saved_group_id;
      else
        update public.pos_option_groups
        set
          name = trim(group_row ->> 'name'),
          sort_order = coalesce((group_row ->> 'sort_order')::integer, 0),
          required = coalesce((group_row ->> 'required')::boolean, false),
          selection_mode = v_selection_mode,
          min_selections = coalesce((group_row ->> 'min_selections')::integer, case when v_selection_mode = 'single' then 1 else 0 end),
          max_selections = case
            when v_selection_mode = 'single' then 1
            else nullif(group_row ->> 'max_selections', '')::integer
          end,
          is_active = coalesce((group_row ->> 'is_active')::boolean, true)
        where id = (group_row ->> 'id')::uuid
          and product_id = saved.id
        returning id into saved_group_id;

        if saved_group_id is null then
          insert into public.pos_option_groups (
            product_id, name, sort_order, required, selection_mode,
            min_selections, max_selections, is_active
          ) values (
            saved.id,
            trim(group_row ->> 'name'),
            coalesce((group_row ->> 'sort_order')::integer, 0),
            coalesce((group_row ->> 'required')::boolean, false),
            v_selection_mode,
            coalesce((group_row ->> 'min_selections')::integer, case when v_selection_mode = 'single' then 1 else 0 end),
            case
              when v_selection_mode = 'single' then 1
              else nullif(group_row ->> 'max_selections', '')::integer
            end,
            coalesce((group_row ->> 'is_active')::boolean, true)
          )
          returning id into saved_group_id;
        end if;
      end if;

      if saved_group_id is null then
        continue;
      end if;

      group_ids := array_append(group_ids, saved_group_id);

      for choice_row in select value from jsonb_array_elements(coalesce(group_row -> 'choices', '[]'::jsonb))
      loop
        if nullif(trim(choice_row ->> 'name'), '') is null then
          continue;
        end if;

        if coalesce(nullif(trim(choice_row ->> 'price_mode'), ''), 'none') = 'absolute'
           and coalesce((choice_row ->> 'price')::numeric, 0) <= 0
           and coalesce((choice_row ->> 'is_active')::boolean, true) then
          raise exception 'La opcion % del grupo % requiere precio mayor que cero.', choice_row ->> 'name', group_row ->> 'name';
        end if;

        saved_choice_id := null;

        if nullif(choice_row ->> 'id', '') is null then
          insert into public.pos_option_choices (
            group_id, name, sort_order, price_mode, price, recipe_id, is_active
          ) values (
            saved_group_id,
            trim(choice_row ->> 'name'),
            coalesce((choice_row ->> 'sort_order')::integer, 0),
            coalesce(nullif(trim(choice_row ->> 'price_mode'), ''), 'none'),
            coalesce((choice_row ->> 'price')::numeric, 0),
            nullif(choice_row ->> 'recipe_id', '')::uuid,
            coalesce((choice_row ->> 'is_active')::boolean, true)
          )
          returning id into saved_choice_id;
        else
          update public.pos_option_choices
          set
            group_id = saved_group_id,
            name = trim(choice_row ->> 'name'),
            sort_order = coalesce((choice_row ->> 'sort_order')::integer, 0),
            price_mode = coalesce(nullif(trim(choice_row ->> 'price_mode'), ''), 'none'),
            price = coalesce((choice_row ->> 'price')::numeric, 0),
            recipe_id = nullif(choice_row ->> 'recipe_id', '')::uuid,
            is_active = coalesce((choice_row ->> 'is_active')::boolean, true)
          where id = (choice_row ->> 'id')::uuid
          returning id into saved_choice_id;

          if saved_choice_id is null then
            insert into public.pos_option_choices (
              group_id, name, sort_order, price_mode, price, recipe_id, is_active
            ) values (
              saved_group_id,
              trim(choice_row ->> 'name'),
              coalesce((choice_row ->> 'sort_order')::integer, 0),
              coalesce(nullif(trim(choice_row ->> 'price_mode'), ''), 'none'),
              coalesce((choice_row ->> 'price')::numeric, 0),
              nullif(choice_row ->> 'recipe_id', '')::uuid,
              coalesce((choice_row ->> 'is_active')::boolean, true)
            )
            returning id into saved_choice_id;
          end if;
        end if;

        if saved_choice_id is not null then
          choice_ids := array_append(choice_ids, saved_choice_id);
        end if;
      end loop;
    end loop;

    delete from public.pos_option_choices
    where group_id in (
      select id from public.pos_option_groups where product_id = saved.id
    )
    and (cardinality(choice_ids) = 0 or id <> all(choice_ids));

    delete from public.pos_option_groups
    where product_id = saved.id
      and (cardinality(group_ids) = 0 or id <> all(group_ids));

    delete from public.pos_product_modifiers
    where product_id = saved.id;

    update public.pos_products
    set price = public.pos_configurable_min_absolute_price(saved.id)
    where id = saved.id
    returning * into saved;
  else
    delete from public.pos_option_choices
    where group_id in (
      select id from public.pos_option_groups where product_id = saved.id
    );

    delete from public.pos_option_groups
    where product_id = saved.id;
  end if;

  for modifier_row in select value from jsonb_array_elements(coalesce(p_modifiers, '[]'::jsonb))
  loop
    if nullif(trim(modifier_row ->> 'name'), '') is null then
      continue;
    end if;

    saved_modifier_id := null;

    if nullif(modifier_row ->> 'id', '') is null then
      insert into public.pos_product_modifiers (
        product_id, name, modifier_type, price_delta, is_active, sort_order
      ) values (
        saved.id,
        trim(modifier_row ->> 'name'),
        coalesce(nullif(trim(modifier_row ->> 'modifier_type'), ''), 'remove'),
        coalesce((modifier_row ->> 'price_delta')::numeric, 0),
        coalesce((modifier_row ->> 'is_active')::boolean, true),
        coalesce((modifier_row ->> 'sort_order')::integer, 0)
      )
      returning id into saved_modifier_id;
    else
      update public.pos_product_modifiers
      set
        name = trim(modifier_row ->> 'name'),
        modifier_type = coalesce(nullif(trim(modifier_row ->> 'modifier_type'), ''), 'remove'),
        price_delta = coalesce((modifier_row ->> 'price_delta')::numeric, 0),
        is_active = coalesce((modifier_row ->> 'is_active')::boolean, true),
        sort_order = coalesce((modifier_row ->> 'sort_order')::integer, 0)
      where id = (modifier_row ->> 'id')::uuid
        and product_id = saved.id
      returning id into saved_modifier_id;

      if saved_modifier_id is null then
        insert into public.pos_product_modifiers (
          product_id, name, modifier_type, price_delta, is_active, sort_order
        ) values (
          saved.id,
          trim(modifier_row ->> 'name'),
          coalesce(nullif(trim(modifier_row ->> 'modifier_type'), ''), 'remove'),
          coalesce((modifier_row ->> 'price_delta')::numeric, 0),
          coalesce((modifier_row ->> 'is_active')::boolean, true),
          coalesce((modifier_row ->> 'sort_order')::integer, 0)
        )
        returning id into saved_modifier_id;
      end if;
    end if;

    if saved_modifier_id is not null then
      modifier_ids := array_append(modifier_ids, saved_modifier_id);
    end if;
  end loop;

  if v_product_type <> 'configurable' then
    delete from public.pos_product_modifiers
    where product_id = saved.id
      and (cardinality(modifier_ids) = 0 or id <> all(modifier_ids));
  end if;

  delete from public.pos_recipe_links
  where pos_product_id = saved.id::text;

  if saved.recipe_id is not null then
    insert into public.pos_recipe_links (pos_product_id, recipe_id, auto_consume)
    values (saved.id::text, saved.recipe_id, true)
    on conflict (pos_product_id) do update
      set recipe_id = excluded.recipe_id,
          auto_consume = true;
  end if;

  perform set_config('pos.suppress_catalog_refresh', 'false', true);

  select * into saved
  from public.refresh_pos_product_catalog_state(saved.id);

  return saved;
end;
$$;


ALTER FUNCTION "public"."save_pos_catalog_product"("p_product_id" "uuid", "p_product" "jsonb", "p_variants" "jsonb", "p_modifiers" "jsonb", "p_option_groups" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_pos_floor_layout"("p_layout" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  zone_row jsonb;
  table_row jsonb;
  settings_row jsonb;
  zone_ids text[] := '{}';
  table_ids text[] := '{}';
begin
  if not public.can_manage_pos_floor_plan() then
    raise exception 'No tienes permiso para editar el plano del restaurante.';
  end if;

  if p_layout is null or jsonb_typeof(p_layout) <> 'object' then
    raise exception 'Layout invalido.';
  end if;

  for zone_row in
    select value
    from jsonb_array_elements(coalesce(p_layout -> 'areas', '[]'::jsonb))
  loop
    perform public.upsert_pos_floor_zone(
      zone_row ->> 'id',
      coalesce(zone_row ->> 'name', zone_row ->> 'nombre'),
      coalesce(zone_row ->> 'description', ''),
      coalesce((zone_row ->> 'sortOrder')::integer, (zone_row ->> 'sort_order')::integer, 0),
      coalesce((zone_row ->> 'active')::boolean, true),
      coalesce((zone_row ->> 'width')::integer, 900),
      coalesce((zone_row ->> 'height')::integer, 520)
    );
    zone_ids := array_append(zone_ids, zone_row ->> 'id');
  end loop;

  for table_row in
    select value
    from jsonb_array_elements(coalesce(p_layout -> 'tables', '[]'::jsonb))
  loop
    perform public.upsert_pos_floor_table(
      table_row ->> 'id',
      coalesce(table_row ->> 'areaId', table_row ->> 'zone_id'),
      table_row ->> 'name',
      coalesce((table_row ->> 'capacity')::integer, (table_row ->> 'capacidad')::integer, 4),
      coalesce(table_row ->> 'shape', 'square'),
      coalesce((table_row ->> 'x')::numeric, 50),
      coalesce((table_row ->> 'y')::numeric, 50),
      coalesce(table_row ->> 'manual_status', table_row ->> 'status', 'disponible'),
      coalesce((table_row ->> 'sortOrder')::integer, (table_row ->> 'sort_order')::integer, 0),
      coalesce((table_row ->> 'active')::boolean, true)
    );
    table_ids := array_append(table_ids, table_row ->> 'id');
  end loop;

  settings_row := coalesce(p_layout -> 'settings', '{}'::jsonb);
  insert into public.pos_floor_settings (id, snap_to_grid, grid_size, zoom, updated_by)
  values (
    'default',
    coalesce((settings_row ->> 'snapToGrid')::boolean, true),
    greatest(8, coalesce((settings_row ->> 'gridSize')::integer, 24)),
    least(2, greatest(0.5, coalesce((settings_row ->> 'zoom')::numeric, 1))),
    auth.uid()
  )
  on conflict (id) do update set
    snap_to_grid = excluded.snap_to_grid,
    grid_size = excluded.grid_size,
    zoom = excluded.zoom,
    updated_by = auth.uid(),
    updated_at = now();

  update public.pos_floor_zones
  set active = false, updated_by = auth.uid(), updated_at = now()
  where active = true
    and (cardinality(zone_ids) = 0 or id <> all(zone_ids));

  update public.pos_floor_tables
  set active = false, updated_by = auth.uid(), updated_at = now()
  where active = true
    and (cardinality(table_ids) = 0 or id <> all(table_ids));

  return public.get_pos_floor_layout();
end;
$$;


ALTER FUNCTION "public"."save_pos_floor_layout"("p_layout" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_pos_product_from_recipe"("p_product_id" "uuid", "p_recipe_id" "uuid", "p_product" "jsonb") RETURNS "public"."pos_products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recipe public.standard_recipes;
  saved public.pos_products;
  category_id text := nullif(trim(p_product ->> 'category_id'), '');
begin
  select * into recipe
  from public.standard_recipes
  where id = p_recipe_id and active = true and recipe_type = 'final_product';
  if recipe.id is null then raise exception 'Solo una receta final activa puede publicarse en POS.'; end if;
  if not public.can_manage_recipe_area(recipe.production_area_id) then
    raise exception 'No tienes permiso para publicar productos de esta area.';
  end if;
  if nullif(trim(p_product ->> 'name'), '') is null then
    raise exception 'El nombre del producto POS es obligatorio.';
  end if;
  if coalesce((p_product ->> 'price')::numeric, 0) <= 0 then
    raise exception 'El precio de venta del producto POS debe ser mayor que cero.';
  end if;

  if p_product_id is null then
    insert into public.pos_products (
      name, description, price, image_url, category_id, category_name,
      recipe_id, production_area_id, active, is_test_item, sort_order, created_by
    ) values (
      trim(p_product ->> 'name'), nullif(trim(p_product ->> 'description'), ''),
      (p_product ->> 'price')::numeric, nullif(trim(p_product ->> 'image_url'), ''),
      category_id, nullif(trim(p_product ->> 'category_name'), ''),
      recipe.id, recipe.production_area_id, true, false,
      coalesce((p_product ->> 'sort_order')::integer, 0), auth.uid()
    ) returning * into saved;
  else
    update public.pos_products set
      name = trim(p_product ->> 'name'),
      description = nullif(trim(p_product ->> 'description'), ''),
      price = (p_product ->> 'price')::numeric,
      image_url = nullif(trim(p_product ->> 'image_url'), ''),
      category_id = category_id,
      category_name = nullif(trim(p_product ->> 'category_name'), ''),
      recipe_id = recipe.id,
      production_area_id = recipe.production_area_id,
      active = true,
      is_test_item = false,
      sort_order = coalesce((p_product ->> 'sort_order')::integer, 0)
    where id = p_product_id
    returning * into saved;
    if saved.id is null then raise exception 'El producto POS seleccionado no existe.'; end if;
  end if;

  insert into public.pos_recipe_links (pos_product_id, recipe_id, auto_consume)
  values (saved.id::text, recipe.id, true)
  on conflict (pos_product_id) do update
    set recipe_id = excluded.recipe_id, auto_consume = true;
  return saved;
end;
$$;


ALTER FUNCTION "public"."save_pos_product_from_recipe"("p_product_id" "uuid", "p_recipe_id" "uuid", "p_product" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_purchase_order"("p_data" "jsonb") RETURNS "public"."purchase_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_role text := public.current_profile_role();
  order_id text := nullif(trim(p_data ->> 'id'), '');
  next_status text := nullif(trim(p_data ->> 'status'), '');
  current_order public.purchase_orders;
  saved_order public.purchase_orders;
  is_test_flow boolean := coalesce((p_data ->> 'is_test')::boolean, false);
  previous_status text;
begin
  if actor_role not in ('admin', 'gerente_general', 'gerente', 'encargado_almacen') then
    raise exception 'No tienes permiso para operar ordenes de compra.';
  end if;
  if order_id is null or nullif(trim(p_data ->> 'numeroOrden'), '') is null then
    raise exception 'La orden no contiene identificador o numero.';
  end if;
  if is_test_flow and not public.can_create_test_flow() then
    raise exception 'Solo Administracion puede crear pruebas de flujo.';
  end if;

  select * into current_order from public.purchase_orders where id = order_id;

  if current_order.id is null then
    if actor_role in ('gerente', 'encargado_almacen') then
      next_status := 'pendiente_aprobacion';
      p_data := jsonb_set(p_data, '{status}', to_jsonb(next_status));
    end if;
    insert into public.purchase_orders (
      id, order_number, status, data, created_by, created_by_role, is_test
    )
    values (
      order_id, p_data ->> 'numeroOrden', next_status, p_data, auth.uid(), actor_role, is_test_flow
    )
    returning * into saved_order;
    return saved_order;
  end if;

  is_test_flow := coalesce(current_order.is_test, is_test_flow, false);
  previous_status := current_order.status;

  if current_order.status <> next_status then
    if next_status in ('aprobada', 'rechazada') and actor_role not in ('admin', 'gerente_general') then
      raise exception 'Solo Admin o Gerente General pueden aprobar o rechazar ordenes.';
    elsif next_status = 'enviada_proveedor' and current_order.status <> 'aprobada' then
      raise exception 'Solo una orden aprobada puede enviarse al proveedor.';
    elsif next_status in ('recibida_parcial', 'recibida_completa')
      and (actor_role not in ('admin', 'gerente_general', 'encargado_almacen')
        or current_order.status not in ('aprobada', 'enviada_proveedor')) then
      raise exception 'La orden no esta lista para recepcion.';
    end if;
  end if;

  p_data := jsonb_set(p_data, '{is_test}', to_jsonb(is_test_flow));

  update public.purchase_orders
  set
    order_number = p_data ->> 'numeroOrden',
    status = next_status,
    data = p_data,
    is_test = is_test_flow,
    updated_at = now()
  where id = order_id
  returning * into saved_order;

  if is_test_flow
    and previous_status not in ('recibida_parcial', 'recibida_completa')
    and next_status in ('recibida_parcial', 'recibida_completa') then
    perform public.process_test_purchase_order_receipt(saved_order);
  end if;

  return saved_order;
end;
$$;


ALTER FUNCTION "public"."save_purchase_order"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_recruitment_interview_evaluation"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_eval public.recruitment_interview_evaluations;
  v_interview_id uuid;
  v_recommendation text;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para guardar evaluaciones.';
  end if;

  v_interview_id := nullif(trim(p_payload ->> 'interview_id'), '')::uuid;
  v_recommendation := coalesce(nullif(trim(p_payload ->> 'recommendation'), ''), 'second_interview');

  insert into public.recruitment_interview_evaluations (
    interview_id, presentation_score, communication_score, experience_score,
    attitude_score, availability_score, comments, recommendation, created_by
  )
  values (
    v_interview_id,
    (p_payload ->> 'presentation_score')::smallint,
    (p_payload ->> 'communication_score')::smallint,
    (p_payload ->> 'experience_score')::smallint,
    (p_payload ->> 'attitude_score')::smallint,
    (p_payload ->> 'availability_score')::smallint,
    nullif(trim(coalesce(p_payload ->> 'comments', '')), ''),
    v_recommendation,
    auth.uid()
  )
  on conflict (interview_id) do update set
    presentation_score = excluded.presentation_score,
    communication_score = excluded.communication_score,
    experience_score = excluded.experience_score,
    attitude_score = excluded.attitude_score,
    availability_score = excluded.availability_score,
    comments = excluded.comments,
    recommendation = excluded.recommendation
  returning * into v_eval;

  if v_recommendation = 'hire' then
    update public.recruitment_candidates c
    set pipeline_status = 'offer', updated_by = auth.uid()
    from public.recruitment_interviews i
    where i.id = v_interview_id and c.id = i.candidate_id;
  elsif v_recommendation = 'discard' then
    update public.recruitment_candidates c
    set pipeline_status = 'discarded', discard_reason = 'profile_mismatch', updated_by = auth.uid()
    from public.recruitment_interviews i
    where i.id = v_interview_id and c.id = i.candidate_id;
  end if;

  return to_jsonb(v_eval);
end;
$$;


ALTER FUNCTION "public"."save_recruitment_interview_evaluation"("p_payload" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sales_goals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "goal_month" "date" NOT NULL,
    "goal_type" "text" DEFAULT 'monthly_sales'::"text" NOT NULL,
    "target_amount" numeric(12,2) NOT NULL,
    "title" "text" DEFAULT 'Meta mensual'::"text" NOT NULL,
    "description" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sales_goals_goal_month_check" CHECK (("goal_month" = ("date_trunc"('month'::"text", ("goal_month")::timestamp with time zone))::"date")),
    CONSTRAINT "sales_goals_goal_type_check" CHECK (("goal_type" = 'monthly_sales'::"text")),
    CONSTRAINT "sales_goals_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text"]))),
    CONSTRAINT "sales_goals_target_amount_check" CHECK (("target_amount" > (0)::numeric))
);


ALTER TABLE "public"."sales_goals" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_sales_goal"("p_data" "jsonb") RETURNS "public"."sales_goals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.sales_goals;
  goal_id uuid := nullif(p_data ->> 'id', '')::uuid;
  v_goal_month date := date_trunc('month', coalesce(nullif(p_data ->> 'goal_month', '')::date, current_date))::date;
  v_goal_type text := coalesce(nullif(p_data ->> 'goal_type', ''), 'monthly_sales');
  v_target numeric := coalesce(nullif(p_data ->> 'target_amount', '')::numeric, 0);
  v_status text := coalesce(nullif(p_data ->> 'status', ''), 'active');
begin
  if not public.can_manage_sales_goals() then
    raise exception 'No tienes permiso para configurar metas de venta.';
  end if;
  if v_target <= 0 then
    raise exception 'La meta debe ser mayor que cero.';
  end if;
  if v_goal_type <> 'monthly_sales' then
    raise exception 'Tipo de meta invalido.';
  end if;

  if v_status = 'active' then
    update public.sales_goals
    set status = 'inactive'
    where goal_month = v_goal_month
      and goal_type = v_goal_type
      and status = 'active'
      and (goal_id is null or id <> goal_id);
  end if;

  if goal_id is null then
    insert into public.sales_goals (
      goal_month, goal_type, target_amount, title, description, status, created_by, updated_by
    ) values (
      v_goal_month,
      v_goal_type,
      v_target,
      coalesce(nullif(trim(p_data ->> 'title'), ''), 'Meta mensual'),
      nullif(trim(p_data ->> 'description'), ''),
      v_status,
      auth.uid(),
      auth.uid()
    ) returning * into saved;
  else
    update public.sales_goals set
      goal_month = v_goal_month,
      goal_type = v_goal_type,
      target_amount = v_target,
      title = coalesce(nullif(trim(p_data ->> 'title'), ''), 'Meta mensual'),
      description = nullif(trim(p_data ->> 'description'), ''),
      status = v_status
    where id = goal_id
    returning * into saved;
    if saved.id is null then
      raise exception 'La meta seleccionada no existe.';
    end if;
  end if;

  return saved;
end;
$$;


ALTER FUNCTION "public"."save_sales_goal"("p_data" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shift_types" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "estimated_hours" numeric,
    "counts_as_workday" boolean DEFAULT true NOT NULL,
    "is_rest_day" boolean DEFAULT false NOT NULL,
    "is_holiday" boolean DEFAULT false NOT NULL,
    "color" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "shift_types_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text"])))
);


ALTER TABLE "public"."shift_types" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_shift_type"("p_data" "jsonb") RETURNS "public"."shift_types"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.shift_types;
  shift_id uuid := nullif(p_data ->> 'id', '')::uuid;
begin
  if not public.is_shift_type_manager() then
    raise exception 'No tienes permiso para gestionar tipos de turno.';
  end if;
  if nullif(trim(p_data ->> 'name'), '') is null then
    raise exception 'El nombre del turno es obligatorio.';
  end if;

  if shift_id is null then
    insert into public.shift_types (
      name, start_time, end_time, estimated_hours, counts_as_workday, is_rest_day,
      is_holiday, color, status
    ) values (
      trim(p_data ->> 'name'),
      nullif(p_data ->> 'start_time', '')::time,
      nullif(p_data ->> 'end_time', '')::time,
      nullif(p_data ->> 'estimated_hours', '')::numeric,
      coalesce((p_data ->> 'counts_as_workday')::boolean, true),
      coalesce((p_data ->> 'is_rest_day')::boolean, false),
      coalesce((p_data ->> 'is_holiday')::boolean, false),
      nullif(trim(p_data ->> 'color'), ''),
      coalesce(nullif(p_data ->> 'status', ''), 'active')
    ) returning * into saved;
  else
    update public.shift_types set
      name = trim(p_data ->> 'name'),
      start_time = nullif(p_data ->> 'start_time', '')::time,
      end_time = nullif(p_data ->> 'end_time', '')::time,
      estimated_hours = nullif(p_data ->> 'estimated_hours', '')::numeric,
      counts_as_workday = coalesce((p_data ->> 'counts_as_workday')::boolean, true),
      is_rest_day = coalesce((p_data ->> 'is_rest_day')::boolean, false),
      is_holiday = coalesce((p_data ->> 'is_holiday')::boolean, false),
      color = nullif(trim(p_data ->> 'color'), ''),
      status = coalesce(nullif(p_data ->> 'status', ''), 'active'),
      updated_at = now()
    where id = shift_id
    returning * into saved;
    if saved.id is null then raise exception 'El tipo de turno no existe.'; end if;
  end if;

  return saved;
end;
$$;


ALTER FUNCTION "public"."save_shift_type"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_standard_recipe"("p_recipe_id" "uuid", "p_recipe" "jsonb", "p_ingredients" "jsonb") RETURNS "public"."standard_recipes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.standard_recipes;
  existing public.standard_recipes;
  ingredient jsonb;
  inventory_item public.inventory_items;
  total_cost numeric := 0;
  area_id text := nullif(trim(p_recipe ->> 'production_area_id'), '');
  recipe_kind text := coalesce(nullif(trim(p_recipe ->> 'recipe_type'), ''), 'subrecipe');
  recipe_qty numeric;
  inventory_qty numeric;
  conversion numeric;
  recipe_unit_value text;
  usable numeric;
begin
  if not public.can_manage_recipe_area(area_id) then
    raise exception 'No tienes permiso para administrar recetas de esta area.';
  end if;
  if nullif(trim(p_recipe ->> 'name'), '') is null then
    raise exception 'El nombre de la receta es obligatorio.';
  end if;
  if recipe_kind not in ('subrecipe', 'final_product') then
    raise exception 'El tipo de receta no es valido.';
  end if;
  if coalesce((p_recipe ->> 'yield_quantity')::numeric, 0) <= 0 then
    raise exception 'El rendimiento debe ser mayor que cero.';
  end if;
  if jsonb_array_length(coalesce(p_ingredients, '[]'::jsonb)) = 0 then
    raise exception 'Agrega al menos un ingrediente.';
  end if;

  for ingredient in select value from jsonb_array_elements(p_ingredients)
  loop
    select * into inventory_item from public.inventory_items
    where id = (ingredient ->> 'inventory_item_id')::uuid and active = true;
    if inventory_item.id is null then
      raise exception 'La receta contiene un ingrediente inactivo o inexistente.';
    end if;

    recipe_qty := coalesce((ingredient ->> 'recipe_quantity')::numeric, (ingredient ->> 'quantity')::numeric, 0);
    inventory_qty := coalesce((ingredient ->> 'inventory_quantity')::numeric, (ingredient ->> 'quantity')::numeric, 0);
    if recipe_qty <= 0 or inventory_qty <= 0 then
      raise exception 'La cantidad de % debe ser mayor que cero.', inventory_item.name;
    end if;

    usable := coalesce(nullif(inventory_item.usable_cost, 0), inventory_item.cost_per_base_unit, 0);
    total_cost := total_cost + (inventory_qty * usable);
  end loop;

  if p_recipe_id is not null then
    select * into existing from public.standard_recipes where id = p_recipe_id;
    if existing.id is null then raise exception 'La receta no existe.'; end if;
    if not public.can_manage_recipe_area(existing.production_area_id) then
      raise exception 'No tienes permiso para editar esta receta.';
    end if;
    update public.standard_recipes set
      name = trim(p_recipe ->> 'name'),
      recipe_type = recipe_kind,
      pos_category_id = nullif(trim(p_recipe ->> 'pos_category_id'), ''),
      production_area_id = area_id,
      yield_quantity = coalesce((p_recipe ->> 'yield_quantity')::numeric, 1),
      yield_unit = nullif(trim(p_recipe ->> 'yield_unit'), ''),
      estimated_cost = total_cost,
      recipe_current_cost = total_cost,
      last_cost_update = now(),
      active = coalesce((p_recipe ->> 'active')::boolean, true),
      image_url = nullif(trim(p_recipe ->> 'image_url'), ''),
      preparation_steps = coalesce(p_recipe -> 'preparation_steps', '[]'::jsonb),
      notes = nullif(trim(p_recipe ->> 'notes'), '')
    where id = p_recipe_id returning * into saved;
    delete from public.recipe_ingredients where recipe_id = p_recipe_id;
  else
    insert into public.standard_recipes (
      name, recipe_type, pos_category_id, production_area_id, yield_quantity,
      yield_unit, estimated_cost, recipe_current_cost, last_cost_update,
      active, image_url, preparation_steps, notes, created_by
    ) values (
      trim(p_recipe ->> 'name'), recipe_kind, nullif(trim(p_recipe ->> 'pos_category_id'), ''),
      area_id, coalesce((p_recipe ->> 'yield_quantity')::numeric, 1),
      nullif(trim(p_recipe ->> 'yield_unit'), ''), total_cost, total_cost, now(),
      coalesce((p_recipe ->> 'active')::boolean, true), nullif(trim(p_recipe ->> 'image_url'), ''),
      coalesce(p_recipe -> 'preparation_steps', '[]'::jsonb),
      nullif(trim(p_recipe ->> 'notes'), ''), auth.uid()
    ) returning * into saved;
  end if;

  for ingredient in select value from jsonb_array_elements(p_ingredients)
  loop
    select * into inventory_item from public.inventory_items where id = (ingredient ->> 'inventory_item_id')::uuid;
    recipe_qty := coalesce((ingredient ->> 'recipe_quantity')::numeric, (ingredient ->> 'quantity')::numeric, 0);
    inventory_qty := coalesce((ingredient ->> 'inventory_quantity')::numeric, (ingredient ->> 'quantity')::numeric, 0);
    conversion := coalesce((ingredient ->> 'conversion_factor')::numeric, inventory_qty / recipe_qty, 1);
    recipe_unit_value := coalesce(nullif(trim(ingredient ->> 'recipe_unit'), ''), inventory_item.base_unit);

    insert into public.recipe_ingredients (
      recipe_id, inventory_item_id, ingredient_name, quantity, unit,
      recipe_quantity, recipe_unit, inventory_quantity, inventory_unit, conversion_factor,
      conversion_warning, waste_percentage, notes
    ) values (
      saved.id, inventory_item.id, inventory_item.name, inventory_qty, inventory_item.base_unit,
      recipe_qty, recipe_unit_value, inventory_qty, inventory_item.base_unit, conversion,
      coalesce((ingredient ->> 'conversion_warning')::boolean, false),
      coalesce((ingredient ->> 'waste_percentage')::numeric, 0),
      nullif(trim(ingredient ->> 'notes'), '')
    );
  end loop;

  insert into public.recipe_cost_history (recipe_id, cost, notes)
  values (saved.id, total_cost, 'Guardado de receta');

  return saved;
end;
$$;


ALTER FUNCTION "public"."save_standard_recipe"("p_recipe_id" "uuid", "p_recipe" "jsonb", "p_ingredients" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."ticket_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "template_key" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "paper_width" "text" DEFAULT '80mm'::"text" NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "settings" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ticket_templates_paper_width_check" CHECK (("paper_width" = ANY (ARRAY['58mm'::"text", '80mm'::"text", 'letter'::"text"]))),
    CONSTRAINT "ticket_templates_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text"]))),
    CONSTRAINT "ticket_templates_template_key_check" CHECK (("template_key" = ANY (ARRAY['prebill'::"text", 'final_bill'::"text", 'delivery'::"text", 'takeout'::"text", 'kitchen'::"text"])))
);


ALTER TABLE "public"."ticket_templates" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_ticket_template"("p_data" "jsonb") RETURNS "public"."ticket_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.ticket_templates;
  template_id uuid := nullif(p_data ->> 'id', '')::uuid;
  v_template_key text := nullif(trim(p_data ->> 'template_key'), '');
  template_status text := coalesce(nullif(p_data ->> 'status', ''), 'active');
  template_is_default boolean := coalesce((p_data ->> 'is_default')::boolean, true);
begin
  if not public.can_manage_ticket_templates() then
    raise exception 'No tienes permiso para editar disenos de tickets.';
  end if;
  if v_template_key is null then
    raise exception 'La clave de plantilla es obligatoria.';
  end if;
  if v_template_key not in ('prebill', 'final_bill', 'delivery', 'takeout', 'kitchen') then
    raise exception 'Clave de plantilla invalida.';
  end if;
  if coalesce(p_data -> 'qr' ->> 'enabled', p_data -> 'settings' -> 'qr' ->> 'enabled', 'false')::boolean
    and nullif(trim(coalesce(p_data -> 'qr' ->> 'url', p_data -> 'settings' -> 'qr' ->> 'url', '')), '') is not null
    and coalesce(p_data -> 'qr' ->> 'url', p_data -> 'settings' -> 'qr' ->> 'url', '') !~* '^https?://'
  then
    raise exception 'La URL del QR debe iniciar con http:// o https://.';
  end if;

  if template_is_default and template_status = 'active' then
    update public.ticket_templates
    set is_default = false
    where ticket_templates.template_key = v_template_key
      and (template_id is null or id <> template_id)
      and is_default = true
      and status = 'active';
  end if;

  if template_id is null then
    insert into public.ticket_templates (
      template_key, name, description, paper_width, is_default, status, settings, created_by, updated_by
    ) values (
      v_template_key,
      trim(p_data ->> 'name'),
      nullif(trim(p_data ->> 'description'), ''),
      coalesce(nullif(p_data ->> 'paper_width', ''), '80mm'),
      template_is_default,
      template_status,
      coalesce(p_data -> 'settings', '{}'::jsonb),
      auth.uid(),
      auth.uid()
    ) returning * into saved;
  else
    update public.ticket_templates set
      template_key = v_template_key,
      name = trim(p_data ->> 'name'),
      description = nullif(trim(p_data ->> 'description'), ''),
      paper_width = coalesce(nullif(p_data ->> 'paper_width', ''), '80mm'),
      is_default = template_is_default,
      status = template_status,
      settings = coalesce(p_data -> 'settings', '{}'::jsonb)
    where id = template_id
    returning * into saved;
    if saved.id is null then
      raise exception 'La plantilla de ticket no existe.';
    end if;
  end if;

  return saved;
end;
$$;


ALTER FUNCTION "public"."save_ticket_template"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_recruitment_interview"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_interview public.recruitment_interviews;
  v_candidate_id uuid;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para programar entrevistas.';
  end if;

  v_candidate_id := nullif(trim(p_payload ->> 'candidate_id'), '')::uuid;

  insert into public.recruitment_interviews (
    candidate_id, scheduled_date, scheduled_time, responsible_profile_id,
    location_modality, notes, created_by, updated_by
  )
  values (
    v_candidate_id,
    nullif(trim(p_payload ->> 'scheduled_date'), '')::date,
    nullif(trim(coalesce(p_payload ->> 'scheduled_time', '')), '')::time,
    nullif(trim(coalesce(p_payload ->> 'responsible_profile_id', '')), '')::uuid,
    nullif(trim(coalesce(p_payload ->> 'location_modality', '')), ''),
    nullif(trim(coalesce(p_payload ->> 'notes', '')), ''),
    auth.uid(),
    auth.uid()
  )
  returning * into v_interview;

  update public.recruitment_candidates
  set pipeline_status = 'interview_scheduled',
      updated_by = auth.uid()
  where id = v_candidate_id
    and pipeline_status in ('applied', 'contacted', 'interview_scheduled');

  return to_jsonb(v_interview);
end;
$$;


ALTER FUNCTION "public"."schedule_recruitment_interview"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_task_reminder"("p_task_id" "text", "p_reminder_at" timestamp with time zone, "p_step_id" "uuid" DEFAULT NULL::"uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_profile uuid := coalesce(p_profile_id, auth.uid());
begin
  v_task := public.assert_operational_task_mutable(p_task_id);
  if p_reminder_at is null or p_reminder_at <= now() then
    raise exception 'La fecha del recordatorio debe ser futura.';
  end if;

  insert into public.task_reminder_deliveries (
    task_id, step_id, profile_id, reminder_at
  ) values (
    p_task_id, p_step_id, v_profile, p_reminder_at
  );

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."schedule_task_reminder"("p_task_id" "text", "p_reminder_at" timestamp with time zone, "p_step_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_pos_order_to_cashier"("p_order_id" "uuid") RETURNS "public"."pos_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  updated_order public.pos_orders;
begin
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para enviar cuentas a caja.';
  end if;
  update public.pos_orders
  set status = 'sent_to_cashier'
  where id = p_order_id
    and status = 'awaiting_bill'
  returning * into updated_order;
  if updated_order.id is null then
    raise exception 'Solicita la cuenta antes de enviarla a caja.';
  end if;
  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (p_order_id, 'sent_to_cashier', 'Cuenta enviada a caja.', auth.uid());
  return updated_order;
end;
$$;


ALTER FUNCTION "public"."send_pos_order_to_cashier"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_pos_order_to_production"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_pos_order public.pos_orders;
  v_item public.pos_order_items;
  v_product public.pos_products;
  v_recipe public.standard_recipes;
  v_variant public.pos_product_variants;
  v_required record;
  v_area_row record;
  v_ticket public.production_tickets;
  v_stock_before numeric;
  v_ticket_ids uuid[] := '{}'::uuid[];
  v_draft_count integer;
  v_mode text := public.get_inventory_deduction_mode();
  v_strict boolean := v_mode = 'strict';
  v_eval jsonb;
  v_skip_reason text;
  v_skipped_count integer := 0;
  v_deducted_count integer := 0;
begin
  if not public.can_operate_pos_orders() then
    raise exception 'No tienes permiso para enviar ordenes POS.';
  end if;

  select po.*
  into v_pos_order
  from public.pos_orders po
  where po.id = p_order_id
  for update;

  if v_pos_order.id is null then
    raise exception 'La orden POS no existe.';
  end if;

  if v_pos_order.status <> 'open' then
    raise exception 'Solo una orden abierta puede enviarse a produccion.';
  end if;

  select count(*)
  into v_draft_count
  from public.pos_order_items poi
  where poi.order_id = p_order_id
    and poi.status = 'draft';

  if v_draft_count = 0 then
    raise exception 'No hay productos nuevos para enviar.';
  end if;

  for v_item in
    select poi.*
    from public.pos_order_items poi
    where poi.order_id = p_order_id
      and poi.status = 'draft'
  loop
    if v_strict then
      select pop.*
      into v_product
      from public.pos_products pop
      where pop.id = v_item.product_id
        and pop.active = true
        and pop.production_ready = true;

      if v_product.id is null then
        raise exception 'Producto % no esta listo para produccion.', v_item.product_name;
      end if;

      if v_product.is_test_item then
        continue;
      end if;

      if v_item.recipe_id is null
        or v_item.production_area_id is null
        or not v_item.production_ready then
        raise exception 'Producto % no esta listo para produccion.', v_item.product_name;
      end if;

      if v_item.product_variant_id is not null then
        select ppv.*
        into v_variant
        from public.pos_product_variants ppv
        where ppv.id = v_item.product_variant_id
          and ppv.product_id = v_item.product_id
          and ppv.is_active = true;

        if v_variant.id is null then
          raise exception 'La variante seleccionada para % no esta activa.', v_item.product_name;
        end if;

        select sr.*
        into v_recipe
        from public.standard_recipes sr
        where sr.id = v_variant.recipe_id
          and sr.active = true
          and sr.recipe_type = 'final_product';

        if v_recipe.id is null
          or v_variant.recipe_id is distinct from v_item.recipe_id
          or v_variant.production_area_id is distinct from v_item.production_area_id
          or v_recipe.production_area_id is distinct from v_item.production_area_id then
          raise exception 'Producto % tiene variante, receta o area de produccion invalida.', v_item.product_name;
        end if;
      else
        select sr.*
        into v_recipe
        from public.standard_recipes sr
        where sr.id = v_item.recipe_id
          and sr.active = true
          and sr.recipe_type = 'final_product';

        if v_recipe.id is null
          or v_product.recipe_id is distinct from v_item.recipe_id
          or v_product.production_area_id is distinct from v_item.production_area_id
          or v_recipe.production_area_id is distinct from v_item.production_area_id then
          raise exception 'Producto % tiene receta o area de produccion invalida.', v_item.product_name;
        end if;
      end if;
    else
      select pop.*
      into v_product
      from public.pos_products pop
      where pop.id = v_item.product_id
        and pop.active = true;

      if v_product.id is null then
        raise exception 'Producto % no esta activo.', v_item.product_name;
      end if;

      if v_item.production_area_id is null then
        raise exception 'Producto % no tiene area KDS configurada.', v_item.product_name;
      end if;

      if not exists (
        select 1
        from public.areas ar
        where ar.id = v_item.production_area_id
          and ar.active = true
          and ar.is_production_area = true
      ) then
        raise exception 'El area KDS de % no esta activa.', v_item.product_name;
      end if;
    end if;
  end loop;

  for v_required in
    select
      ri.inventory_item_id as item_id,
      max(ri.ingredient_name) as ingredient_name,
      max(ri.unit) as unit,
      poi.production_area_id as area_id,
      max(ar.name) as area_name,
      sum(ri.quantity * poi.quantity) as quantity
    from public.pos_order_items poi
    join public.pos_products pop on pop.id = poi.product_id
    join public.standard_recipes sr on sr.id = poi.recipe_id
    join public.recipe_ingredients ri on ri.recipe_id = sr.id
    join public.areas ar on ar.id = poi.production_area_id
    where poi.order_id = p_order_id
      and poi.status = 'draft'
      and not poi.is_test_item
      and poi.recipe_id is not null
      and (public.evaluate_pos_inventory_deduction(pop, poi) ->> 'deduct')::boolean = true
    group by ri.inventory_item_id, poi.production_area_id
  loop
    select ai.quantity
    into v_stock_before
    from public.area_inventory ai
    where ai.item_id = v_required.item_id
      and ai.area_id = v_required.area_id
    for update;

    v_stock_before := coalesce(v_stock_before, 0);

    if v_stock_before < v_required.quantity then
      raise exception 'No hay suficiente % en %. Disponible %, requerido %.',
        v_required.ingredient_name, v_required.area_name, v_stock_before, v_required.quantity;
    end if;
  end loop;

  for v_area_row in
    select distinct poi.production_area_id as area_id
    from public.pos_order_items poi
    where poi.order_id = p_order_id
      and poi.status = 'draft'
  loop
    insert into public.production_tickets (
      order_id, table_id, table_name, area_id, area_name, waiter_id, waiter_name, status, priority, notes
    )
    select
      v_pos_order.id::text,
      v_pos_order.table_id,
      coalesce(v_pos_order.table_name, 'Orden POS'),
      ar.id,
      ar.name,
      v_pos_order.waiter_id,
      v_pos_order.waiter_name,
      'pending',
      'normal',
      v_pos_order.notes
    from public.areas ar
    where ar.id = v_area_row.area_id
      and ar.active = true
      and ar.is_production_area = true
    returning * into v_ticket;

    if v_ticket.id is null then
      raise exception 'El area de produccion % no esta activa.', v_area_row.area_id;
    end if;

    v_ticket_ids := array_append(v_ticket_ids, v_ticket.id);

    insert into public.production_ticket_items (
      ticket_id, order_item_id, product_id, product_name, quantity, notes, modifiers, status
    )
    select
      v_ticket.id,
      poi.id::text,
      poi.product_id,
      poi.product_name,
      poi.quantity,
      poi.notes,
      poi.modifiers,
      'pending'
    from public.pos_order_items poi
    where poi.order_id = p_order_id
      and poi.status = 'draft'
      and poi.production_area_id = v_area_row.area_id;

    for v_item in
      select poi.*
      from public.pos_order_items poi
      where poi.order_id = p_order_id
        and poi.status = 'draft'
        and poi.production_area_id = v_area_row.area_id
    loop
      select pop.*
      into v_product
      from public.pos_products pop
      where pop.id = v_item.product_id;

      v_eval := public.evaluate_pos_inventory_deduction(v_product, v_item);
      v_skip_reason := nullif(v_eval ->> 'reason', '');

      update public.pos_order_items poi
      set status = 'sent_to_production',
          inventory_consumed = coalesce((v_eval ->> 'deduct')::boolean, false),
          production_ticket_id = v_ticket.id
      where poi.id = v_item.id;

      if coalesce((v_eval ->> 'deduct')::boolean, false) then
        v_deducted_count := v_deducted_count + 1;
      else
        v_skipped_count := v_skipped_count + 1;
        if v_skip_reason is not null and v_skip_reason <> 'test_item' then
          perform public.log_pos_inventory_deduction_skip(
            v_pos_order.id,
            v_item.id,
            v_item.product_id,
            v_item.product_name,
            v_skip_reason
          );
        end if;
      end if;
    end loop;

    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (
      v_pos_order.id,
      'ticket_created',
      'Ticket creado en KDS para ' || v_ticket.area_name || '.',
      auth.uid()
    );
  end loop;

  for v_required in
    select
      ri.inventory_item_id as item_id,
      max(ri.ingredient_name) as ingredient_name,
      max(ri.unit) as unit,
      poi.production_area_id as area_id,
      sum(ri.quantity * poi.quantity) as quantity
    from public.pos_order_items poi
    join public.pos_products pop on pop.id = poi.product_id
    join public.standard_recipes sr on sr.id = poi.recipe_id
    join public.recipe_ingredients ri on ri.recipe_id = sr.id
    where poi.order_id = p_order_id
      and poi.production_ticket_id = any(v_ticket_ids)
      and not poi.is_test_item
      and poi.recipe_id is not null
      and (public.evaluate_pos_inventory_deduction(pop, poi) ->> 'deduct')::boolean = true
    group by ri.inventory_item_id, poi.production_area_id
  loop
    select ai.quantity
    into v_stock_before
    from public.area_inventory ai
    where ai.item_id = v_required.item_id
      and ai.area_id = v_required.area_id
    for update;

    update public.area_inventory ai
    set quantity = v_stock_before - v_required.quantity
    where ai.item_id = v_required.item_id
      and ai.area_id = v_required.area_id;

    insert into public.inventory_movements (
      item_id, movement_type, from_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, source_id, notes, performed_by
    ) values (
      v_required.item_id,
      'consumption',
      v_required.area_id,
      v_required.quantity,
      v_required.unit,
      v_stock_before,
      v_stock_before - v_required.quantity,
      'pos_order',
      v_pos_order.id::text,
      'Consumo por comanda POS',
      auth.uid()
    );
  end loop;

  if v_skipped_count > 0 then
    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (
      v_pos_order.id,
      'inventory_deduction_skipped',
      v_skipped_count::text || ' linea(s) omitieron descarga de inventario (modo implementacion).',
      auth.uid()
    );
  end if;

  update public.pos_orders po
  set sent_at = now()
  where po.id = p_order_id;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    v_pos_order.id,
    'sent_to_production',
    v_draft_count::text || ' producto(s) enviado(s) a produccion.'
      || case
        when v_deducted_count > 0 and v_skipped_count > 0 then
          ' Inventario descontado en ' || v_deducted_count::text || ' linea(s); omitido en ' || v_skipped_count::text || '.'
        when v_deducted_count > 0 then ' Inventario descontado.'
        else ' Sin descarga de inventario (modo implementacion).'
      end,
    auth.uid()
  );

  return jsonb_build_object(
    'order_id', v_pos_order.id,
    'ticket_ids', to_jsonb(v_ticket_ids),
    'items_sent', v_draft_count,
    'inventory_deducted_count', v_deducted_count,
    'inventory_skipped_count', v_skipped_count,
    'deduction_mode', v_mode,
    'inventory_consumed', v_deducted_count > 0
  );
end;
$$;


ALTER FUNCTION "public"."send_pos_order_to_production"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_pos_order_to_production_for_operator"("p_order_id" "uuid", "p_operator_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$declare
  v_pos_order public.pos_orders;
  v_item public.pos_order_items;
  v_product public.pos_products;
  v_recipe public.standard_recipes;
  v_variant public.pos_product_variants;
  v_required record;
  v_area_row record;
  v_ticket public.production_tickets;
  v_stock_before numeric;
  v_ticket_ids uuid[] := '{}'::uuid[];
  v_draft_count integer;
  v_mode text := public.get_inventory_deduction_mode();
  v_strict boolean := v_mode = 'strict';
  v_eval jsonb;
  v_skip_reason text;
  v_skipped_count integer := 0;
  v_deducted_count integer := 0;
begin
  if not public.station_pos_can_operate_orders(p_operator_profile_id) then
    raise exception 'No tienes permiso para enviar ordenes POS.';
  end if;

  select po.*
  into v_pos_order
  from public.pos_orders po
  where po.id = p_order_id
  for update;

  if v_pos_order.id is null then
    raise exception 'La orden POS no existe.';
  end if;

  if v_pos_order.status <> 'open' then
    raise exception 'Solo una orden abierta puede enviarse a produccion.';
  end if;

  select count(*)
  into v_draft_count
  from public.pos_order_items poi
  where poi.order_id = p_order_id
    and poi.status = 'draft';

  if v_draft_count = 0 then
    raise exception 'No hay productos nuevos para enviar.';
  end if;

  for v_item in
    select poi.*
    from public.pos_order_items poi
    where poi.order_id = p_order_id
      and poi.status = 'draft'
  loop
    if v_strict then
      select pop.*
      into v_product
      from public.pos_products pop
      where pop.id = v_item.product_id
        and pop.active = true
        and pop.production_ready = true;

      if v_product.id is null then
        raise exception 'Producto % no esta listo para produccion.', v_item.product_name;
      end if;

      if v_product.is_test_item then
        continue;
      end if;

      if v_item.recipe_id is null
        or v_item.production_area_id is null
        or not v_item.production_ready then
        raise exception 'Producto % no esta listo para produccion.', v_item.product_name;
      end if;

      if v_item.product_variant_id is not null then
        select ppv.*
        into v_variant
        from public.pos_product_variants ppv
        where ppv.id = v_item.product_variant_id
          and ppv.product_id = v_item.product_id
          and ppv.is_active = true;

        if v_variant.id is null then
          raise exception 'La variante seleccionada para % no esta activa.', v_item.product_name;
        end if;

        select sr.*
        into v_recipe
        from public.standard_recipes sr
        where sr.id = v_variant.recipe_id
          and sr.active = true
          and sr.recipe_type = 'final_product';

        if v_recipe.id is null
          or v_variant.recipe_id is distinct from v_item.recipe_id
          or v_variant.production_area_id is distinct from v_item.production_area_id
          or v_recipe.production_area_id is distinct from v_item.production_area_id then
          raise exception 'Producto % tiene variante, receta o area de produccion invalida.', v_item.product_name;
        end if;
      else
        select sr.*
        into v_recipe
        from public.standard_recipes sr
        where sr.id = v_item.recipe_id
          and sr.active = true
          and sr.recipe_type = 'final_product';

        if v_recipe.id is null
          or v_product.recipe_id is distinct from v_item.recipe_id
          or v_product.production_area_id is distinct from v_item.production_area_id
          or v_recipe.production_area_id is distinct from v_item.production_area_id then
          raise exception 'Producto % tiene receta o area de produccion invalida.', v_item.product_name;
        end if;
      end if;
    else
      select pop.*
      into v_product
      from public.pos_products pop
      where pop.id = v_item.product_id
        and pop.active = true;

      if v_product.id is null then
        raise exception 'Producto % no esta activo.', v_item.product_name;
      end if;

      if v_item.production_area_id is null then
        raise exception 'Producto % no tiene area KDS configurada.', v_item.product_name;
      end if;

      if not exists (
        select 1
        from public.areas ar
        where ar.id = v_item.production_area_id
          and ar.active = true
          and ar.is_production_area = true
      ) then
        raise exception 'El area KDS de % no esta activa.', v_item.product_name;
      end if;
    end if;
  end loop;

  for v_required in
    select
      ri.inventory_item_id as item_id,
      max(ri.ingredient_name) as ingredient_name,
      max(ri.unit) as unit,
      poi.production_area_id as area_id,
      max(ar.name) as area_name,
      sum(ri.quantity * poi.quantity) as quantity
    from public.pos_order_items poi
    join public.pos_products pop on pop.id = poi.product_id
    join public.standard_recipes sr on sr.id = poi.recipe_id
    join public.recipe_ingredients ri on ri.recipe_id = sr.id
    join public.areas ar on ar.id = poi.production_area_id
    where poi.order_id = p_order_id
      and poi.status = 'draft'
      and not poi.is_test_item
      and poi.recipe_id is not null
      and (public.evaluate_pos_inventory_deduction(pop, poi) ->> 'deduct')::boolean = true
    group by ri.inventory_item_id, poi.production_area_id
  loop
    select ai.quantity
    into v_stock_before
    from public.area_inventory ai
    where ai.item_id = v_required.item_id
      and ai.area_id = v_required.area_id
    for update;

    v_stock_before := coalesce(v_stock_before, 0);

    if v_stock_before < v_required.quantity then
      raise exception 'No hay suficiente % en %. Disponible %, requerido %.',
        v_required.ingredient_name, v_required.area_name, v_stock_before, v_required.quantity;
    end if;
  end loop;

  for v_area_row in
    select distinct poi.production_area_id as area_id
    from public.pos_order_items poi
    where poi.order_id = p_order_id
      and poi.status = 'draft'
  loop
    insert into public.production_tickets (
      order_id, table_id, table_name, area_id, area_name, waiter_id, waiter_name, status, priority, notes
    )
    select
      v_pos_order.id::text,
      v_pos_order.table_id,
      coalesce(v_pos_order.table_name, 'Orden POS'),
      ar.id,
      ar.name,
      v_pos_order.waiter_id,
      v_pos_order.waiter_name,
      'pending',
      'normal',
      v_pos_order.notes
    from public.areas ar
    where ar.id = v_area_row.area_id
      and ar.active = true
      and ar.is_production_area = true
    returning * into v_ticket;

    if v_ticket.id is null then
      raise exception 'El area de produccion % no esta activa.', v_area_row.area_id;
    end if;

    v_ticket_ids := array_append(v_ticket_ids, v_ticket.id);

    insert into public.production_ticket_items (
      ticket_id, order_item_id, product_id, product_name, quantity, notes, modifiers, status
    )
    select
      v_ticket.id,
      poi.id::text,
      poi.product_id,
      poi.product_name,
      poi.quantity,
      poi.notes,
      poi.modifiers,
      'pending'
    from public.pos_order_items poi
    where poi.order_id = p_order_id
      and poi.status = 'draft'
      and poi.production_area_id = v_area_row.area_id;

    for v_item in
      select poi.*
      from public.pos_order_items poi
      where poi.order_id = p_order_id
        and poi.status = 'draft'
        and poi.production_area_id = v_area_row.area_id
    loop
      select pop.*
      into v_product
      from public.pos_products pop
      where pop.id = v_item.product_id;

      v_eval := public.evaluate_pos_inventory_deduction(v_product, v_item);
      v_skip_reason := nullif(v_eval ->> 'reason', '');

      update public.pos_order_items poi
      set status = 'sent_to_production',
          inventory_consumed = coalesce((v_eval ->> 'deduct')::boolean, false),
          production_ticket_id = v_ticket.id
      where poi.id = v_item.id;

      if coalesce((v_eval ->> 'deduct')::boolean, false) then
        v_deducted_count := v_deducted_count + 1;
      else
        v_skipped_count := v_skipped_count + 1;
        if v_skip_reason is not null and v_skip_reason <> 'test_item' then
          perform public.log_pos_inventory_deduction_skip(
            v_pos_order.id,
            v_item.id,
            v_item.product_id,
            v_item.product_name,
            v_skip_reason
          );
        end if;
      end if;
    end loop;

    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (
      v_pos_order.id,
      'ticket_created',
      'Ticket creado en KDS para ' || v_ticket.area_name || '.',
      p_operator_profile_id
    );
  end loop;

  for v_required in
    select
      ri.inventory_item_id as item_id,
      max(ri.ingredient_name) as ingredient_name,
      max(ri.unit) as unit,
      poi.production_area_id as area_id,
      sum(ri.quantity * poi.quantity) as quantity
    from public.pos_order_items poi
    join public.pos_products pop on pop.id = poi.product_id
    join public.standard_recipes sr on sr.id = poi.recipe_id
    join public.recipe_ingredients ri on ri.recipe_id = sr.id
    where poi.order_id = p_order_id
      and poi.production_ticket_id = any(v_ticket_ids)
      and not poi.is_test_item
      and poi.recipe_id is not null
      and (public.evaluate_pos_inventory_deduction(pop, poi) ->> 'deduct')::boolean = true
    group by ri.inventory_item_id, poi.production_area_id
  loop
    select ai.quantity
    into v_stock_before
    from public.area_inventory ai
    where ai.item_id = v_required.item_id
      and ai.area_id = v_required.area_id
    for update;

    update public.area_inventory ai
    set quantity = v_stock_before - v_required.quantity
    where ai.item_id = v_required.item_id
      and ai.area_id = v_required.area_id;

    insert into public.inventory_movements (
      item_id, movement_type, from_area_id, quantity, unit, previous_quantity,
      new_quantity, source_type, source_id, notes, performed_by
    ) values (
      v_required.item_id,
      'consumption',
      v_required.area_id,
      v_required.quantity,
      v_required.unit,
      v_stock_before,
      v_stock_before - v_required.quantity,
      'pos_order',
      v_pos_order.id::text,
      'Consumo por comanda POS',
      p_operator_profile_id
    );
  end loop;

  if v_skipped_count > 0 then
    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (
      v_pos_order.id,
      'inventory_deduction_skipped',
      v_skipped_count::text || ' linea(s) omitieron descarga de inventario (modo implementacion).',
      p_operator_profile_id
    );
  end if;

  update public.pos_orders po
  set sent_at = now()
  where po.id = p_order_id;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (
    v_pos_order.id,
    'sent_to_production',
    v_draft_count::text || ' producto(s) enviado(s) a produccion.'
      || case
        when v_deducted_count > 0 and v_skipped_count > 0 then
          ' Inventario descontado en ' || v_deducted_count::text || ' linea(s); omitido en ' || v_skipped_count::text || '.'
        when v_deducted_count > 0 then ' Inventario descontado.'
        else ' Sin descarga de inventario (modo implementacion).'
      end,
    p_operator_profile_id
  );

  return jsonb_build_object(
    'order_id', v_pos_order.id,
    'ticket_ids', to_jsonb(v_ticket_ids),
    'items_sent', v_draft_count,
    'inventory_deducted_count', v_deducted_count,
    'inventory_skipped_count', v_skipped_count,
    'deduction_mode', v_mode,
    'inventory_consumed', v_deducted_count > 0
  );
end;
$$;


ALTER FUNCTION "public"."send_pos_order_to_production_for_operator"("p_order_id" "uuid", "p_operator_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_station_pos_order_to_cashier"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_order public.pos_orders;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'send_to_cashier',
    jsonb_build_object('order_id', p_order_id)
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'send_to_cashier', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'send_to_cashier', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);

  if not public.station_pos_is_order_owner(p_order_id, v_operator_id) then
    raise exception '%', v_generic;
  end if;

  update public.pos_orders
  set status = 'sent_to_cashier'
  where id = p_order_id
    and status = 'awaiting_bill'
  returning * into v_order;

  if v_order.id is null then
    raise exception 'Solicita la cuenta antes de enviarla a caja.';
  end if;

  insert into public.pos_order_events (order_id, event_type, description, created_by)
  values (p_order_id, 'sent_to_cashier', 'Cuenta enviada a caja.', v_operator_id);

  v_result := jsonb_build_object('order_id', p_order_id, 'status', v_order.status);

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'send_to_cashier', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  perform public.station_pos_revoke_operator_session(v_op_session_id, 'send_to_cashier');
  return v_result;
exception
  when others then
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    if sqlerrm like 'Solicita la cuenta%' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."send_station_pos_order_to_cashier"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_station_pos_order_to_production"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_payload jsonb;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'send_to_production',
    jsonb_build_object('order_id', p_order_id)
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'send_to_production', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'send_to_production', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);
  perform public.station_pos_assert_order_open_for_drafts(p_order_id, v_operator_id);

  v_payload := public.send_pos_order_to_production_for_operator(p_order_id, v_operator_id);
  v_result := v_payload;

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'send_to_production', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  perform public.station_pos_revoke_operator_session(v_op_session_id, 'send_to_production');
  return v_result;
exception
  when others then
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    if sqlerrm like 'No hay productos%' or sqlerrm like 'Solo una orden%' or sqlerrm like 'No tienes permiso%' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."send_station_pos_order_to_production"("p_operator_session_token" "text", "p_order_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


