CREATE OR REPLACE FUNCTION "public"."set_attendance_pin"("p_employee_id" "uuid", "p_pin" "text", "p_authorized_device" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO '', 'extensions', 'public'
    AS $_$
begin
  if not public.is_attendance_manager() then
    raise exception 'No tienes permiso para configurar PIN de marcaje.';
  end if;
  if p_pin !~ '^[0-9]{4,6}$' then
    raise exception 'El PIN debe contener entre 4 y 6 digitos.';
  end if;
  if exists (
    select 1
    from public.attendance_credentials c
    join public.profiles p on p.id = c.employee_id
    where c.employee_id <> p_employee_id
      and p.status = 'active'
      and crypt(p_pin, c.pin_hash) = c.pin_hash
  ) then
    raise exception 'El PIN ya esta asignado a otro colaborador activo.';
  end if;

  insert into public.attendance_credentials (employee_id, pin_hash, updated_by)
  values (p_employee_id, crypt(p_pin, gen_salt('bf')), auth.uid())
  on conflict (employee_id) do update
  set pin_hash = excluded.pin_hash,
      updated_by = excluded.updated_by,
      updated_at = now();

  update public.profiles
  set authorized_attendance_device = nullif(trim(p_authorized_device), ''),
      updated_at = now()
  where id = p_employee_id;
end;
$_$;


ALTER FUNCTION "public"."set_attendance_pin"("p_employee_id" "uuid", "p_pin" "text", "p_authorized_device" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_billing_settings"("p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current jsonb;
  v_next jsonb;
  v_key text;
  v_old jsonb;
  v_new jsonb;
begin
  if not public.can_manage_billing_settings() then
    raise exception 'No tienes permiso para modificar configuracion de facturacion.';
  end if;

  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'Patch invalido para billing_settings.';
  end if;

  v_current := public.get_billing_settings();
  v_next := v_current || p_patch;

  if coalesce(v_next ->> 'emission_enabled', 'false')::boolean then
    raise exception 'La emision FEL no esta habilitada en Fase 0.';
  end if;

  for v_key in
    select jsonb_object_keys(p_patch)
  loop
    v_old := to_jsonb(v_current -> v_key);
    v_new := to_jsonb(v_next -> v_key);
    if v_old is distinct from v_new then
      perform public.billing_log_config_change(
        'app_settings', 'billing_settings', v_key, v_old, v_new, 'update',
        jsonb_build_object('source', 'set_billing_settings')
      );
    end if;
  end loop;

  v_next := v_next || jsonb_build_object(
    'updated_at', to_jsonb(now()),
    'updated_by', to_jsonb(auth.uid())
  );

  insert into public.app_settings (key, value, updated_by)
  values ('billing_settings', v_next, auth.uid())
  on conflict (key) do update
    set value = excluded.value,
        updated_by = excluded.updated_by,
        updated_at = now();

  return public.get_billing_settings();
end;
$$;


ALTER FUNCTION "public"."set_billing_settings"("p_patch" "jsonb") OWNER TO "postgres";


