CREATE OR REPLACE FUNCTION "public"."set_inventory_deduction_mode"("p_mode" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_mode text := lower(trim(coalesce(p_mode, '')));
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  if public.normalize_profile_role(public.current_profile_role()) <> 'admin' then
    raise exception 'No tiene permisos para modificar el modo de descarga de inventario.';
  end if;

  if v_mode not in ('disabled', 'active_recipes_only', 'strict') then
    raise exception 'Modo de descarga invalido: %. Valores: disabled, active_recipes_only, strict.', v_mode;
  end if;

  insert into public.app_settings (key, value, updated_by)
  values (
    'inventory_deduction_mode',
    jsonb_build_object(
      'mode', v_mode,
      'updated_by', auth.uid(),
      'updated_at', now(),
      'notes', v_notes
    ),
    auth.uid()
  )
  on conflict (key) do update
  set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();

  return public.get_inventory_deduction_mode_setting();
end;
$$;


ALTER FUNCTION "public"."set_inventory_deduction_mode"("p_mode" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_inventory_migration_mode"("p_enabled" boolean, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current jsonb := public.get_inventory_migration_mode();
  v_was_enabled boolean := coalesce((v_current ->> 'enabled')::boolean, false);
  v_next jsonb;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  if public.normalize_profile_role(public.current_profile_role()) <> 'admin' then
    raise exception 'No tiene permisos para modificar el Modo Migración. Solo un Administrador del sistema puede realizar esta acción.';
  end if;

  if v_was_enabled = coalesce(p_enabled, false) then
    return public.get_inventory_migration_mode();
  end if;

  if coalesce(p_enabled, false) then
    v_next := jsonb_build_object(
      'enabled', true,
      'activated_by', auth.uid(),
      'activated_at', now(),
      'deactivated_by', null,
      'deactivated_at', null,
      'notes', v_notes
    );
  else
    v_next := jsonb_build_object(
      'enabled', false,
      'activated_by', v_current -> 'activated_by',
      'activated_at', v_current -> 'activated_at',
      'deactivated_by', auth.uid(),
      'deactivated_at', now(),
      'notes', v_notes
    );
  end if;

  insert into public.app_settings (key, value, updated_by)
  values ('inventory_migration_mode', v_next, auth.uid())
  on conflict (key) do update
  set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();

  insert into public.inventory_migration_mode_audit (
    action, previous_enabled, new_enabled, notes, changed_by
  )
  values (
    case when coalesce(p_enabled, false) then 'activated' else 'deactivated' end,
    v_was_enabled,
    coalesce(p_enabled, false),
    v_notes,
    auth.uid()
  );

  return public.get_inventory_migration_mode();
end;
$$;


ALTER FUNCTION "public"."set_inventory_migration_mode"("p_enabled" boolean, "p_notes" "text") OWNER TO "postgres";


