CREATE OR REPLACE FUNCTION "public"."set_standard_recipe_output_inventory_item"("p_recipe_id" "uuid", "p_output_inventory_item_id" "uuid") RETURNS "public"."standard_recipes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recipe public.standard_recipes;
  output_item public.inventory_items;
begin
  select * into recipe
  from public.standard_recipes
  where id = p_recipe_id;

  if recipe.id is null then
    raise exception 'La receta no existe.';
  end if;
  if not public.can_manage_recipe_area(recipe.production_area_id) then
    raise exception 'No tienes permiso para configurar esta receta.';
  end if;

  if p_output_inventory_item_id is not null then
    select * into output_item
    from public.inventory_items
    where id = p_output_inventory_item_id and active = true;
    if output_item.id is null then
      raise exception 'El producto terminado no existe o esta inactivo.';
    end if;
  end if;

  update public.standard_recipes
  set output_inventory_item_id = p_output_inventory_item_id
  where id = recipe.id
  returning * into recipe;

  return recipe;
end;
$$;


ALTER FUNCTION "public"."set_standard_recipe_output_inventory_item"("p_recipe_id" "uuid", "p_output_inventory_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."slugify_inventory_category_code"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select trim(both '_' from regexp_replace(
    lower(translate(coalesce(trim(p_name), ''), 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun')),
    '[^a-z0-9]+',
    '_',
    'g'
  ));
$$;


ALTER FUNCTION "public"."slugify_inventory_category_code"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_bakery_production_from_plan"("p_plan_item_id" "uuid") RETURNS "public"."bakery_production_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_plan public.bakery_production_plan_items;
  v_batch public.bakery_production_batches;
  v_recipe_id uuid;
begin
  if not public.can_operate_bakery_production() then
    raise exception 'PERMISSION_DENIED: no autorizado para operar producción de panadería.';
  end if;

  select * into v_plan
  from public.bakery_production_plan_items
  where id = p_plan_item_id
  for update;

  if v_plan.id is null then
    raise exception 'El ítem del plan no existe.';
  end if;
  if v_plan.status not in ('planned', 'in_progress', 'partial') then
    raise exception 'Este ítem del plan no puede iniciar producción (estado: %).', v_plan.status;
  end if;
  if nullif(trim(v_plan.product_name), '') is null then
    raise exception 'No se puede crear lote sin producto.';
  end if;

  if exists (
    select 1 from public.bakery_production_batches b
    where b.plan_item_id = v_plan.id
      and b.status in ('created', 'in_progress')
  ) then
    raise exception 'Ya existe un lote activo para este ítem del plan.';
  end if;

  select sr.id into v_recipe_id
  from public.standard_recipes sr
  where sr.active = true
    and sr.production_area_id in ('panaderia', 'reposteria')
    and lower(trim(sr.name)) = lower(trim(v_plan.product_name))
  order by sr.updated_at desc
  limit 1;

  insert into public.bakery_production_batches (
    batch_code, plan_item_id, inventory_item_id, product_name,
    planned_quantity, unit, responsible_user_id, destination_area_id,
    recipe_id, status, started_at
  )
  values (
    public.next_bakery_production_batch_code(v_plan.product_name),
    v_plan.id,
    v_plan.inventory_item_id,
    v_plan.product_name,
    v_plan.planned_quantity,
    v_plan.unit,
    coalesce(v_plan.assigned_to, auth.uid()),
    v_plan.destination_area_id,
    v_recipe_id,
    'in_progress',
    now()
  )
  returning * into v_batch;

  update public.bakery_production_plan_items
  set status = 'in_progress', updated_at = now()
  where id = v_plan.id;

  return v_batch;
end;
$$;


ALTER FUNCTION "public"."start_bakery_production_from_plan"("p_plan_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_cash_bind_operator_session_by_token"("p_operator_session_token" "text", OUT "p_device_id" "uuid", OUT "p_station_id" "uuid", OUT "p_operator_session_id" "uuid", OUT "p_operator_profile_id" "uuid", OUT "p_session_revoked" boolean, OUT "p_revoke_reason" "text") RETURNS "record"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_station public.operational_stations;
  v_hash text;
  v_op public.operational_operator_sessions;
  v_generic constant text := 'Operacion no permitida.';
begin
  if nullif(trim(coalesce(p_operator_session_token, '')), '') is null then
    raise exception '%', v_generic;
  end if;

  v_device := public.resolve_operational_device_for_auth_user();
  if v_device.id is null then
    raise exception '%', v_generic;
  end if;

  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.id is null
    or v_station.status <> 'active'
    or v_station.station_type <> 'cash'
    or v_station.cash_register_id is null then
    raise exception '%', v_generic;
  end if;

  v_hash := encode(extensions.digest(trim(p_operator_session_token), 'sha256'), 'hex');
  select * into v_op
  from public.operational_operator_sessions
  where session_token_hash = v_hash
    and operational_station_device_id = v_device.id
  order by created_at desc
  limit 1;

  if v_op.id is null
    or v_op.module <> 'cash'
    or v_op.operational_station_id <> v_station.id then
    raise exception '%', v_generic;
  end if;

  p_device_id := v_device.id;
  p_station_id := v_station.id;
  p_operator_session_id := v_op.id;
  p_operator_profile_id := v_op.operator_profile_id;
  p_session_revoked := v_op.revoked_at is not null;
  p_revoke_reason := v_op.revoke_reason;
end;
$$;


ALTER FUNCTION "public"."station_cash_bind_operator_session_by_token"("p_operator_session_token" "text", OUT "p_device_id" "uuid", OUT "p_station_id" "uuid", OUT "p_operator_session_id" "uuid", OUT "p_operator_profile_id" "uuid", OUT "p_session_revoked" boolean, OUT "p_revoke_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."station_cash_bind_operator_session_by_token"("p_operator_session_token" "text", OUT "p_device_id" "uuid", OUT "p_station_id" "uuid", OUT "p_operator_session_id" "uuid", OUT "p_operator_profile_id" "uuid", OUT "p_session_revoked" boolean, OUT "p_revoke_reason" "text") IS 'Replay terminal: sale_complete, shift_close, manual_lock, expired. Solo lectura de filas idempotency completed; nunca muta ni extiende idle.';



CREATE OR REPLACE FUNCTION "public"."station_cash_create_movement_impl"("p_operator_session_token" "text", "p_movement_type" "text", "p_amount" numeric, "p_reason" "text", "p_reference" "text" DEFAULT NULL::"text", "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_skip_idempotency" boolean DEFAULT false, "p_skip_idle_extend" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_register_id uuid;
  v_role text;
  v_session_row public.cash_sessions;
  v_saved public.cash_movements;
  v_cached jsonb;
  v_fingerprint text;
  v_allowed_cashier text[] := array['deposit', 'sale_cash', 'refund'];
  v_generic constant text := 'No se pudo registrar el movimiento.';
begin
  v_fingerprint := public.station_cash_request_fingerprint(
    'movement',
    jsonb_build_object(
      'movement_type', coalesce(p_movement_type, ''),
      'amount', round(coalesce(p_amount, 0)::numeric, 2),
      'reason', coalesce(nullif(trim(coalesce(p_reason, '')), ''), ''),
      'reference', coalesce(nullif(trim(coalesce(p_reference, '')), ''), ''),
      'order_id', p_order_id
    )
  );

  if not coalesce(p_skip_idempotency, false) then
    v_cached := public.station_cash_idempotency_replay_if_completed(
      p_operator_session_token, 'movement', p_idempotency_key, v_fingerprint
    );
    if v_cached is not null then
      return v_cached;
    end if;
  end if;

  v_ctx := public.resolve_station_cash_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_register_id := (v_ctx ->> 'cash_register_id')::uuid;
  v_role := v_ctx ->> 'operator_role';

  if not coalesce(p_skip_idempotency, false) then
    v_cached := public.station_cash_idempotency_begin(
      v_device_id, v_station_id, v_op_session_id, p_idempotency_key, 'movement', v_fingerprint
    );
    if v_cached is not null then
      return v_cached;
    end if;
  end if;

  if not coalesce(p_skip_idle_extend, false) then
    perform public.station_cash_extend_operator_idle(v_op_session_id);
  end if;

  select * into v_session_row
  from public.cash_sessions
  where cash_register_id = v_register_id and status = 'open'
  order by opened_at desc
  limit 1
  for update;

  if v_session_row.id is null then
    raise exception 'No hay caja abierta.';
  end if;

  if p_movement_type not in ('sale_cash', 'withdrawal', 'deposit', 'refund', 'adjustment', 'manual_open') then
    raise exception 'Tipo de movimiento invalido.';
  end if;

  if v_role in ('cajero', 'caja') and not (p_movement_type = any(v_allowed_cashier)) then
    raise exception 'Este movimiento requiere supervisor, Admin o Gerente General.';
  end if;
  if p_movement_type in ('withdrawal', 'manual_open', 'adjustment')
    and not public.station_cash_is_supervisor(v_operator_id) then
    raise exception 'Este movimiento requiere supervisor, Admin o Gerente General.';
  end if;
  if p_movement_type in ('withdrawal', 'deposit', 'refund', 'adjustment', 'manual_open')
    and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'El motivo es obligatorio.';
  end if;

  insert into public.cash_movements (
    cash_session_id, cash_register_id, created_by, authorized_by, movement_type,
    amount, reason, reference, order_id, metadata
  ) values (
    v_session_row.id, v_session_row.cash_register_id, v_operator_id,
    case when public.station_cash_is_supervisor(v_operator_id) then v_operator_id else null end,
    p_movement_type,
    coalesce(p_amount, 0)::numeric(12,2),
    nullif(trim(coalesce(p_reason, '')), ''),
    nullif(trim(coalesce(p_reference, '')), ''),
    p_order_id,
    jsonb_build_object(
      'operational_station_id', v_station_id,
      'operational_station_device_id', v_device_id,
      'operator_profile_id', v_operator_id
    )
  ) returning * into v_saved;

  update public.cash_sessions
  set expected_cash = public.calculate_cash_expected(v_session_row.id),
      updated_at = now()
  where id = v_session_row.id;

  v_cached := jsonb_build_object('ok', true, 'movement', to_jsonb(v_saved));

  if p_movement_type = 'sale_cash' then
    update public.operational_operator_sessions
    set revoked_at = now(), revoke_reason = 'sale_complete'
    where id = v_op_session_id and revoked_at is null;
    perform public.log_operational_station_event(
      v_station_id, v_device_id, 'operator_session_locked', v_operator_id,
      jsonb_build_object('reason', 'sale_complete'), null
    );
    v_cached := v_cached || jsonb_build_object('operator_locked', true);
  end if;

  if not coalesce(p_skip_idempotency, false) then
    perform public.station_cash_idempotency_complete(v_device_id, p_idempotency_key, v_cached);
  end if;
  return v_cached;
exception
  when others then
    if sqlerrm in (
      'No hay caja abierta.', 'Tipo de movimiento invalido.',
      'Este movimiento requiere supervisor, Admin o Gerente General.',
      'El motivo es obligatorio.'
    ) then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."station_cash_create_movement_impl"("p_operator_session_token" "text", "p_movement_type" "text", "p_amount" numeric, "p_reason" "text", "p_reference" "text", "p_order_id" "uuid", "p_idempotency_key" "text", "p_skip_idempotency" boolean, "p_skip_idle_extend" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_cash_extend_operator_idle"("p_operator_session_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.operational_operator_sessions
  set last_activity_at = now(),
      idle_expires_at = now() + interval '90 seconds'
  where id = p_operator_session_id
    and revoked_at is null
    and idle_expires_at > now();
end;
$$;


ALTER FUNCTION "public"."station_cash_extend_operator_idle"("p_operator_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_cash_idempotency_begin"("p_device_id" "uuid", "p_station_id" "uuid", "p_operator_session_id" "uuid", "p_key" "text", "p_operation" "text", "p_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.operational_station_cash_idempotency;
  v_key text := nullif(trim(coalesce(p_key, '')), '');
begin
  if v_key is null then
    raise exception 'Se requiere clave de idempotencia.';
  end if;

  insert into public.operational_station_cash_idempotency (
    device_id, idempotency_key, operation, request_fingerprint,
    operator_session_id, station_id, result
  ) values (
    p_device_id, v_key, p_operation, p_fingerprint,
    p_operator_session_id, p_station_id,
    jsonb_build_object('idempotency_status', 'pending')
  )
  on conflict (device_id, idempotency_key) do nothing;

  select * into v_row
  from public.operational_station_cash_idempotency
  where device_id = p_device_id and idempotency_key = v_key
  for update;

  if not found then
    raise exception 'No se pudo reservar idempotencia.';
  end if;

  if v_row.request_fingerprint is distinct from p_fingerprint then
    raise exception 'Conflicto de idempotencia: la clave ya se usÃ³ con otra operaciÃ³n.';
  end if;

  if v_row.operation is distinct from p_operation then
    raise exception 'Conflicto de idempotencia: tipo de operaciÃ³n distinto.';
  end if;

  if v_row.operator_session_id is distinct from p_operator_session_id then
    raise exception 'Operacion no permitida.';
  end if;

  if coalesce(v_row.result ->> 'idempotency_status', '') = 'completed' then
    return v_row.result;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."station_cash_idempotency_begin"("p_device_id" "uuid", "p_station_id" "uuid", "p_operator_session_id" "uuid", "p_key" "text", "p_operation" "text", "p_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_cash_idempotency_complete"("p_device_id" "uuid", "p_key" "text", "p_result" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.operational_station_cash_idempotency
  set result = coalesce(p_result, '{}'::jsonb) || jsonb_build_object('idempotency_status', 'completed')
  where device_id = p_device_id
    and idempotency_key = nullif(trim(coalesce(p_key, '')), '');
end;
$$;


ALTER FUNCTION "public"."station_cash_idempotency_complete"("p_device_id" "uuid", "p_key" "text", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_cash_idempotency_replay_if_completed"("p_operator_session_token" "text", "p_operation" "text", "p_key" "text", "p_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device_id uuid;
  v_station_id uuid;
  v_op_session_id uuid;
  v_operator_profile_id uuid;
  v_revoked boolean;
  v_revoke_reason text;
  v_row public.operational_station_cash_idempotency;
  v_key text := nullif(trim(coalesce(p_key, '')), '');
begin
  if v_key is null then
    raise exception 'Se requiere clave de idempotencia.';
  end if;

  select
    b.p_device_id, b.p_station_id, b.p_operator_session_id, b.p_operator_profile_id,
    b.p_session_revoked, b.p_revoke_reason
  into
    v_device_id, v_station_id, v_op_session_id, v_operator_profile_id, v_revoked, v_revoke_reason
  from public.station_cash_bind_operator_session_by_token(p_operator_session_token) b;

  select * into v_row
  from public.operational_station_cash_idempotency
  where device_id = v_device_id
    and idempotency_key = v_key;

  if not found then
    return null;
  end if;

  if v_row.operator_session_id is distinct from v_op_session_id then
    raise exception 'Operacion no permitida.';
  end if;

  if v_row.station_id is distinct from v_station_id then
    raise exception 'Operacion no permitida.';
  end if;

  if v_row.operation is distinct from p_operation then
    raise exception 'Conflicto de idempotencia: tipo de operaciÃ³n distinto.';
  end if;

  if v_row.request_fingerprint is distinct from p_fingerprint then
    raise exception 'Conflicto de idempotencia: la clave ya se usÃ³ con otra operaciÃ³n.';
  end if;

  if coalesce(v_row.result ->> 'idempotency_status', '') = 'completed' then
    return v_row.result;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."station_cash_idempotency_replay_if_completed"("p_operator_session_token" "text", "p_operation" "text", "p_key" "text", "p_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_cash_is_operator_role"("p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    public.station_cash_operator_role(p_profile_id) in (
      'admin', 'gerente_general', 'supervisor', 'cajero', 'caja'
    ),
    false
  );
$$;


