CREATE OR REPLACE FUNCTION "public"."station_pos_assert_order_open_for_drafts"("p_order_id" "uuid", "p_operator_id" "uuid") RETURNS "public"."pos_orders"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_order public.pos_orders;
begin
  select * into v_order
  from public.pos_orders
  where id = p_order_id;

  if v_order.id is null then
    raise exception 'La orden POS no existe.';
  end if;

  if v_order.status <> 'open' then
    raise exception 'STATION_POS_ORDER_NOT_OPEN'
      using hint = 'Order is not open for draft items.';
  end if;

  if not public.station_pos_is_order_owner(p_order_id, p_operator_id) then
    raise exception 'STATION_POS_ORDER_OWNER_MISMATCH'
      using hint = 'Only the order owner can modify draft items on this table.';
  end if;

  return v_order;
end;
$$;


ALTER FUNCTION "public"."station_pos_assert_order_open_for_drafts"("p_order_id" "uuid", "p_operator_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_pos_assert_release_authorized"("p_order_id" "uuid", "p_scenario" "text", "p_operator_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_scenario = 'L5_payments' then
    raise exception 'POS_RELEASE_BLOCKED_PAYMENTS'
      using hint = 'Orders with payments require flow 189.';
  end if;

  if p_scenario in ('L1_empty', 'L2_drafts_only') then
    if not public.station_pos_is_order_owner(p_order_id, p_operator_id) then
      raise exception 'POS_RELEASE_NOT_OWNER'
        using hint = 'Only the order owner can release this service scenario.';
    end if;
    return;
  end if;

  if p_scenario in ('L3_kds_history', 'L4_billing') then
    raise exception 'POS_RELEASE_REQUIRES_SUPERVISOR'
      using hint = 'Supervisor release not available on station POS yet.';
  end if;
end;
$$;


ALTER FUNCTION "public"."station_pos_assert_release_authorized"("p_order_id" "uuid", "p_scenario" "text", "p_operator_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."station_pos_bind_operator_session_by_token"("p_operator_session_token" "text", OUT "p_device_id" "uuid", OUT "p_station_id" "uuid", OUT "p_operator_session_id" "uuid", OUT "p_operator_profile_id" "uuid", OUT "p_session_revoked" boolean, OUT "p_revoke_reason" "text") RETURNS "record"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_device public.operational_station_devices;
  v_station public.operational_stations;
  v_hash text;
  v_op public.operational_operator_sessions;
  v_generic constant text := 'Operacion no permitida.';
begin
  if nullif(trim(coalesce(p_operator_session_token, '')), '') is null then
    raise exception '%', v_generic;
  end if;

  v_device := public.resolve_operational_device_for_auth_user();
  if v_device.id is null then
    raise exception '%', v_generic;
  end if;

  select * into v_station from public.operational_stations where id = v_device.station_id;
  if v_station.id is null
    or v_station.status <> 'active'
    or v_station.station_type <> 'pos' then
    raise exception '%', v_generic;
  end if;

  v_hash := encode(extensions.digest(trim(p_operator_session_token), 'sha256'), 'hex');
  select * into v_op
  from public.operational_operator_sessions
  where session_token_hash = v_hash
    and operational_station_device_id = v_device.id
  order by created_at desc
  limit 1;

  if v_op.id is null
    or v_op.module <> 'pos'
    or v_op.operational_station_id <> v_station.id then
    raise exception '%', v_generic;
  end if;

  p_device_id := v_device.id;
  p_station_id := v_station.id;
  p_operator_session_id := v_op.id;
  p_operator_profile_id := v_op.operator_profile_id;
  p_session_revoked := v_op.revoked_at is not null;
  p_revoke_reason := v_op.revoke_reason;
end;
$$;


ALTER FUNCTION "public"."station_pos_bind_operator_session_by_token"("p_operator_session_token" "text", OUT "p_device_id" "uuid", OUT "p_station_id" "uuid", OUT "p_operator_session_id" "uuid", OUT "p_operator_profile_id" "uuid", OUT "p_session_revoked" boolean, OUT "p_revoke_reason" "text") OWNER TO "postgres";


