    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.status = 'active'
      and public.normalize_profile_role(p.role) in (
        'admin', 'gerente_general', 'cajero', 'caja', 'mesero', 'servicio', 'supervisor'
      )
  );
$$;


