CREATE OR REPLACE FUNCTION "public"."station_pos_clear_draft_items_impl"("p_order_id" "uuid", "p_operator_profile_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_removed integer;
begin
  delete from public.pos_order_items
  where order_id = p_order_id
    and status = 'draft';

  get diagnostics v_removed = row_count;

  if v_removed > 0 then
    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (
      p_order_id,
      'draft_cleared',
      'Se limpiaron los productos nuevos de la orden.',
      p_operator_profile_id
    );
  end if;

  return v_removed;
end;
$$;


