CREATE OR REPLACE FUNCTION "public"."submit_checklist_change_request"("p_request_id" "uuid") RETURNS "public"."checklist_template_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_role text := public.normalize_profile_role(public.current_profile_role());
  request_row public.checklist_template_change_requests;
  actor_name text;
  notification_title text;
  notification_message text;
begin
  if actor_role not in ('admin', 'gerente_general', 'gerente', 'supervisor', 'recursos_humanos', 'rrhh') then
    raise exception 'No tienes permiso para enviar cambios de checklist.';
  end if;

  select * into request_row
  from public.checklist_template_change_requests
  where id = p_request_id
  for update;

  if request_row.id is null then
    raise exception 'Solicitud no encontrada.';
  end if;
  if request_row.submitted_by <> auth.uid() and not public.is_checklist_change_approver() then
    raise exception 'No tienes permiso para enviar esta solicitud.';
  end if;
  if request_row.status not in ('draft', 'rejected') then
    raise exception 'Solo se pueden enviar borradores o solicitudes rechazadas.';
  end if;
  if request_row.template_id is not null and exists (
    select 1
    from public.checklist_template_change_requests other
    where other.template_id = request_row.template_id
      and other.status = 'pending_review'
      and other.id <> request_row.id
  ) then
    raise exception 'Ya existe una solicitud pendiente para esta checklist.';
  end if;

  update public.checklist_template_change_requests
  set status = 'pending_review',
      submitted_by = coalesce(submitted_by, auth.uid()),
      submitted_at = now(),
      reviewed_by = null,
      reviewed_at = null,
      review_notes = null
  where id = p_request_id
  returning * into request_row;

  select coalesce(full_name, username, 'Colaborador') into actor_name
  from public.profiles
  where id = auth.uid();

  notification_title := case
    when request_row.request_type = 'create' then 'Nueva checklist pendiente de aprobacion'
    else 'Cambio de checklist pendiente de aprobacion'
  end;
  notification_message := coalesce(actor_name, 'Colaborador') || ' envio a verificacion: ' || request_row.title;

  insert into public.notifications (
    user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
  )
  select
    p.id,
    null,
    'checklist_approval',
    notification_title,
    notification_message,
    'checklist_template_change_request',
    request_row.id::text,
    '/tasks?tab=checklists&view=approvals&id=' || request_row.id::text,
    auth.uid()
  from public.profiles p
  where p.status = 'active'
    and public.normalize_profile_role(p.role) in ('admin', 'gerente_general', 'gerente', 'recursos_humanos', 'rrhh')
    and not exists (
      select 1
      from public.notifications n
      where n.user_id = p.id
        and n.type = 'checklist_approval'
        and n.entity_type = 'checklist_template_change_request'
        and n.entity_id = request_row.id::text
    );

  if actor_role = 'supervisor' and request_row.submitted_by is not null then
    insert into public.notifications (
      user_id, target_role, type, title, message, entity_type, entity_id, action_url, created_by
    )
    values (
      request_row.submitted_by,
      null,
      'checklist_approval_pending',
      'Checklist pendiente de aprobacion',
      'Tu checklist "' || request_row.title || '" esta pendiente de aprobacion. Podras asignarla y utilizarla cuando gerencia, RRHH o admin la autoricen.',
      'checklist_template_change_request',
      request_row.id::text,
      '/tasks?tab=checklists&view=approvals&id=' || request_row.id::text,
      auth.uid()
    );
  end if;

  return request_row;
end;
$$;


ALTER FUNCTION "public"."submit_checklist_change_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_checklist_run_for_review"("p_run_id" "uuid") RETURNS "public"."checklist_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  missing_count integer;
  due_at timestamptz;
  completed_ts timestamptz := now();
  timing text := 'on_time';
begin
  select * into run_row from public.checklist_runs where id = p_run_id for update;
  if run_row.id is null then raise exception 'Checklist no encontrada.'; end if;
  if not public.can_access_checklist_run(run_row) then raise exception 'No tienes permiso para completar esta checklist.'; end if;

  select count(*) into missing_count
  from public.checklist_run_items item
  where item.run_id = p_run_id
    and (
      (item.is_required and not (
        item.checked
        or nullif(trim(coalesce(item.response_text, '')), '') is not null
        or item.response_number is not null
        or item.response_date is not null
        or item.response_time is not null
        or coalesce(item.response_json, '{}'::jsonb) <> '{}'::jsonb
        or nullif(trim(coalesce(item.photo_url, '')), '') is not null
      ))
      or ((item.requires_photo or (item.require_photo_on_no and lower(coalesce(item.response_text, '')) = 'no')) and nullif(trim(coalesce(item.photo_url, '')), '') is null)
      or ((item.requires_comment or (item.require_comment_on_no and lower(coalesce(item.response_text, '')) = 'no')) and nullif(trim(coalesce(item.comment, '')), '') is null)
    );

  if missing_count > 0 then
    raise exception 'Completa las preguntas obligatorias antes de enviar.';
  end if;

  perform public.recalculate_checklist_run_points(p_run_id);

  due_at := public.get_checklist_expected_due_at(run_row);
  if due_at is not null and completed_ts > due_at then
    timing := 'late';
  end if;

  update public.checklist_runs
  set status = 'completed',
      submitted_at = completed_ts,
      completed_at = completed_ts,
      completed_by = auth.uid(),
      completion_timing = timing,
      reviewed_by = null,
      reviewed_at = null,
      review_notes = null
  where id = p_run_id
  returning * into run_row;

  return run_row;
end;
$$;


ALTER FUNCTION "public"."submit_checklist_run_for_review"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_requisition"("p_requisition_id" "uuid") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_row public.requisitions;
  submitted public.requisitions;
  detail public.requisition_items;
  catalog_item public.inventory_items;
  resolved_factor numeric;
  requested_unit text;
begin
  select * into current_row from public.requisitions where id = p_requisition_id;
  if current_row.id is null then
    raise exception 'No se pudo enviar la requisicion.';
  end if;
  if current_row.status <> 'draft' then
    raise exception 'Solo se pueden enviar requisiciones en borrador.';
  end if;
  if current_row.requested_by <> auth.uid() and not public.is_profile_manager() then
    raise exception 'No tienes permiso para enviar esta requisicion.';
  end if;

  perform public.assert_requisition_request_permissions(
    current_row.from_area_id,
    current_row.to_area_id,
    current_row.requested_by_profile_id
  );

  if not exists (
    select 1 from public.requisition_items where requisition_id = p_requisition_id
  ) then
    raise exception 'Agrega al menos un producto a la requisicion.';
  end if;

  for detail in
    select * from public.requisition_items where requisition_id = p_requisition_id
  loop
    requested_unit := coalesce(nullif(trim(detail.requested_unit), ''), detail.unit);

    if coalesce(detail.requested_quantity, 0) <= 0 then
      raise exception
        'La linea % tiene cantidad solicitada invalida. Corrige el borrador antes de enviar.',
        detail.item_name;
    end if;

    if requested_unit is null then
      raise exception
        'La linea % no tiene unidad solicitada. Corrige el borrador antes de enviar.',
        detail.item_name;
    end if;

    if coalesce(detail.conversion_warning, false) then
      continue;
    end if;

    if detail.conversion_factor is not null
       and detail.conversion_factor > 0
       and detail.converted_requested_quantity is not null
       and detail.converted_requested_quantity > 0 then
      continue;
    end if;

    select * into catalog_item from public.inventory_items where id = detail.item_id;
    if catalog_item.id is null then
      raise exception 'La requisicion contiene un producto inexistente: %.', detail.item_name;
    end if;
    if coalesce(catalog_item.active, false) = false then
      raise exception 'La requisicion contiene un producto inactivo: %.', detail.item_name;
    end if;

    resolved_factor := public.resolve_item_requisition_unit_factor(
      catalog_item.id,
      coalesce(requested_unit, catalog_item.default_requisition_unit, catalog_item.base_unit)
    );
    if resolved_factor is null or resolved_factor <= 0 then
      raise exception
        'La unidad % no esta configurada para el producto %. Corrige la unidad o configura la conversion antes de enviar.',
        requested_unit,
        detail.item_name;
    end if;
  end loop;

  update public.requisitions
  set status = 'pending', submitted_at = now()
  where id = p_requisition_id
    and status = 'draft'
    and (requested_by = auth.uid() or public.is_profile_manager())
  returning * into submitted;

  if submitted.id is null then
    raise exception 'No se pudo enviar la requisicion.';
  end if;
  return submitted;
end;
$$;


ALTER FUNCTION "public"."submit_requisition"("p_requisition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_task_evidence"("p_task_id" "text", "p_evidence_type" "text" DEFAULT 'photo'::"text", "p_step_id" "uuid" DEFAULT NULL::"uuid", "p_storage_path" "text" DEFAULT NULL::"text", "p_external_url" "text" DEFAULT NULL::"text", "p_display_name" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint, "p_note_text" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_id uuid;
begin
  v_task := public.assert_operational_task_mutable(p_task_id);
  if not public.can_submit_task_evidence(v_task) then
    raise exception 'No tienes permiso para enviar evidencia.';
  end if;

  insert into public.task_evidence (
    task_id, step_id, evidence_type, storage_path, external_url,
    display_name, mime_type, size_bytes, note_text, submitted_by
  ) values (
    p_task_id,
    p_step_id,
    coalesce(nullif(trim(p_evidence_type), ''), 'photo'),
    nullif(trim(p_storage_path), ''),
    nullif(trim(p_external_url), ''),
    coalesce(nullif(trim(p_display_name), ''), 'Evidencia'),
    nullif(trim(p_mime_type), ''),
    p_size_bytes,
    nullif(trim(p_note_text), ''),
    auth.uid()
  ) returning id into v_id;

  perform public.log_task_activity(
    p_task_id, 'evidence_submitted', 'evidence',
    null, to_jsonb(coalesce(nullif(trim(p_display_name), ''), 'Evidencia')),
    jsonb_build_object('evidence_id', v_id, 'step_id', p_step_id)
  );

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."submit_task_evidence"("p_task_id" "text", "p_evidence_type" "text", "p_step_id" "uuid", "p_storage_path" "text", "p_external_url" "text", "p_display_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_note_text" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."yield_audits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_id" "uuid",
    "inventory_item_id" "uuid" NOT NULL,
    "task_id" "text",
    "production_area_id" "text",
    "employee_id" "uuid",
    "supervisor_id" "uuid",
    "audit_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "initial_weight" numeric NOT NULL,
    "usable_weight" numeric NOT NULL,
    "waste_weight" numeric DEFAULT 0 NOT NULL,
    "yield_percent" numeric NOT NULL,
    "variance_percent" numeric,
    "waste_reason_id" "uuid",
    "notes" "text",
    "photo_urls" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "yield_audits_initial_weight_check" CHECK (("initial_weight" > (0)::numeric)),
    CONSTRAINT "yield_audits_usable_weight_check" CHECK (("usable_weight" >= (0)::numeric)),
    CONSTRAINT "yield_audits_waste_weight_check" CHECK (("waste_weight" >= (0)::numeric)),
    CONSTRAINT "yield_audits_yield_percent_check" CHECK ((("yield_percent" > (0)::numeric) AND ("yield_percent" <= (100)::numeric)))
);


ALTER TABLE "public"."yield_audits" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_yield_audit"("p_campaign_id" "uuid", "p_inventory_item_id" "uuid", "p_task_id" "text", "p_production_area_id" "text", "p_employee_id" "uuid", "p_supervisor_id" "uuid", "p_audit_date" "date", "p_initial_weight" numeric, "p_usable_weight" numeric, "p_waste_reason_id" "uuid", "p_notes" "text", "p_photo_urls" "text"[]) RETURNS "public"."yield_audits"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  profile public.inventory_yield_profiles;
  waste numeric;
  yield_pct numeric;
  variance numeric;
  saved public.yield_audits;
begin
  if p_initial_weight <= 0 then
    raise exception 'El peso inicial debe ser mayor que cero.';
  end if;
  if p_usable_weight < 0 or p_usable_weight > p_initial_weight then
    raise exception 'El peso utilizable debe estar entre 0 y el peso inicial.';
  end if;

  waste := greatest(p_initial_weight - p_usable_weight, 0);
  yield_pct := round((p_usable_weight / p_initial_weight) * 100.0, 2);

  select * into profile
  from public.inventory_yield_profiles
  where inventory_item_id = p_inventory_item_id and active = true;

  variance := case
    when profile.id is not null then round(yield_pct - profile.expected_yield_percent, 2)
    else null
  end;

  insert into public.yield_audits (
    campaign_id, inventory_item_id, task_id, production_area_id,
    employee_id, supervisor_id, audit_date,
    initial_weight, usable_weight, waste_weight,
    yield_percent, variance_percent, waste_reason_id, notes, photo_urls
  ) values (
    p_campaign_id, p_inventory_item_id, nullif(trim(p_task_id), ''), nullif(trim(p_production_area_id), ''),
    coalesce(p_employee_id, auth.uid()), p_supervisor_id, coalesce(p_audit_date, current_date),
    p_initial_weight, p_usable_weight, waste,
    yield_pct, variance, p_waste_reason_id, nullif(trim(p_notes), ''), coalesce(p_photo_urls, '{}')
  ) returning * into saved;

  perform public.refresh_historical_yield_average(p_inventory_item_id);
  return saved;
end;
$$;


ALTER FUNCTION "public"."submit_yield_audit"("p_campaign_id" "uuid", "p_inventory_item_id" "uuid", "p_task_id" "text", "p_production_area_id" "text", "p_employee_id" "uuid", "p_supervisor_id" "uuid", "p_audit_date" "date", "p_initial_weight" numeric, "p_usable_weight" numeric, "p_waste_reason_id" "uuid", "p_notes" "text", "p_photo_urls" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_purchase_quantity"("p_stock_after" numeric, "p_minimum_stock" numeric, "p_moved_quantity" numeric, "p_conversion_factor" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  target_base numeric;
  needed_base numeric;
  factor numeric;
begin
  target_base := case
    when coalesce(p_minimum_stock, 0) > 0 then p_minimum_stock * 2
    else greatest(coalesce(p_moved_quantity, 0), 1)
  end;
  needed_base := greatest(
    target_base - coalesce(p_stock_after, 0),
    coalesce(p_moved_quantity, 0),
    1
  );
  factor := greatest(coalesce(nullif(p_conversion_factor, 0), 1), 0.0001);
  return ceil(needed_base / factor);
end;
$$;


ALTER FUNCTION "public"."suggest_purchase_quantity"("p_stock_after" numeric, "p_minimum_stock" numeric, "p_moved_quantity" numeric, "p_conversion_factor" numeric) OWNER TO "postgres";


