CREATE OR REPLACE FUNCTION "public"."sync_catering_followup_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_inserted integer := 0;
begin
  if auth.uid() is null then
    return 0;
  end if;

  with due_requests as (
    select
      request.id,
      request.customer_name,
      request.follow_up_date,
      request.assigned_to,
      case
        when request.follow_up_date < current_date then 'overdue'
        when request.follow_up_date = current_date then 'today'
        else 'upcoming'
      end as urgency
    from public.catering_requests request
    where request.follow_up_date is not null
      and request.follow_up_date <= current_date
      and request.conversion_status not in ('approved', 'lost', 'converted')
  ),
  recipients as (
    select
      due.id as request_id,
      due.customer_name,
      due.follow_up_date,
      due.urgency,
      coalesce(due.assigned_to, profile.id) as user_id
    from due_requests due
    cross join lateral (
      select p.id
      from public.profiles p
      where p.status = 'active'
        and (
          p.id = due.assigned_to
          or (
            due.assigned_to is null
            and public.normalize_profile_role(p.role) = any(public.catering_request_notification_roles())
          )
        )
    ) profile
  ),
  inserted as (
    insert into public.notifications (
      user_id,
      target_role,
      type,
      title,
      message,
      entity_type,
      entity_id,
      action_url
    )
    select
      recipients.user_id,
      null,
      'catering_followup_due',
      case recipients.urgency
        when 'overdue' then 'Seguimiento de catering vencido'
        else 'Seguimiento de catering hoy'
      end,
      coalesce(nullif(trim(recipients.customer_name), ''), 'Cliente')
        || case recipients.urgency
          when 'overdue' then ' — seguimiento vencido desde '
          else ' — seguimiento programado para hoy ('
        end
        || to_char(recipients.follow_up_date, 'DD/MM/YYYY')
        || case when recipients.urgency = 'today' then ')' else '' end,
      'catering_request',
      recipients.request_id::text,
      '/catering?id=' || recipients.request_id::text
    from recipients
    where not exists (
      select 1
      from public.notifications n
      where n.user_id = recipients.user_id
        and n.type = 'catering_followup_due'
        and n.entity_type = 'catering_request'
        and n.entity_id = recipients.request_id::text
        and n.created_at::date = current_date
    )
    returning 1
  )
  select count(*) into v_inserted from inserted;

  return v_inserted;
exception
  when others then
    raise warning 'sync_catering_followup_reminders failed: %', sqlerrm;
    return 0;
end;
$$;


ALTER FUNCTION "public"."sync_catering_followup_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_catering_quote_expired"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_quote public.catering_quotes;
  v_count integer := 0;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para sincronizar cotizaciones vencidas.';
  end if;

  for v_quote in
    select quote.*
    from public.catering_quotes quote
    where quote.status = 'sent'
      and quote.valid_until is not null
      and quote.valid_until < current_date
  loop
    update public.catering_quotes
    set status = 'expired', updated_at = now()
    where id = v_quote.id;

    perform public.log_catering_activity(
      v_quote.request_id,
      'quote_expired',
      'Cotizacion ' || v_quote.quote_number || ' vencida',
      jsonb_build_object('quote_id', v_quote.id, 'quote_number', v_quote.quote_number)
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."sync_catering_quote_expired"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_checklist_runs_from_template"("p_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_row public.checklist_runs;
  synced_runs integer := 0;
  reopened_runs integer := 0;
  inserted_count integer := 0;
  was_completed boolean := false;
  template_title text;
  today_gt date := (now() at time zone 'America/Guatemala')::date;
begin
  if not exists (
    select 1
    from public.checklist_templates
    where id = p_template_id
  ) then
    raise exception 'Plantilla no encontrada.';
  end if;

  if not (
    public.is_checklist_library_admin()
    or public.is_checklist_change_approver()
  ) then
    raise exception 'No tienes permiso para sincronizar ejecuciones de checklist.';
  end if;

  select title into template_title
  from public.checklist_templates
  where id = p_template_id;

  for run_row in
    select *
    from public.checklist_runs
    where template_id = p_template_id
      and status <> 'cancelled'
      and (
        status in ('pending', 'in_progress', 'overdue', 'rejected', 'pending_review')
        or (status = 'completed' and run_date >= today_gt)
      )
  loop
    was_completed := run_row.status = 'completed';

    update public.checklist_runs r
    set
      area = t.area,
      supervisor_profile_id = coalesce(r.supervisor_profile_id, t.supervisor_profile_id),
      reminder_time = coalesce(r.reminder_time, t.reminder_time),
      due_time = coalesce(r.due_time, t.due_time)
    from public.checklist_templates t
    where r.id = run_row.id
      and t.id = p_template_id;

    delete from public.checklist_run_items ri
    where ri.run_id = run_row.id
      and not public.checklist_run_item_has_answer(ri)
      and (
        ri.template_item_id is null
        or not exists (
          select 1
          from public.checklist_template_items ti
          where ti.id = ri.template_item_id
            and ti.template_id = p_template_id
            and ti.is_active = true
        )
      );

    update public.checklist_run_items ri
    set
      item_order = ti.item_order,
      title = ti.title,
      response_type = ti.response_type,
      is_required = ti.is_required,
      requires_photo = ti.requires_photo,
      requires_comment = ti.requires_comment,
      score_points = ti.score_points,
      options = ti.options,
      require_comment_on_no = ti.require_comment_on_no,
      require_photo_on_no = ti.require_photo_on_no,
      generate_incident_on_no = ti.generate_incident_on_no,
      rule_config = ti.rule_config,
      expected_response = ti.expected_response,
      triggers_incident = ti.triggers_incident,
      incident_severity = ti.incident_severity,
      notify_roles = ti.notify_roles,
      create_task_on_fail = ti.create_task_on_fail
    from public.checklist_template_items ti
    where ri.run_id = run_row.id
      and ri.template_item_id = ti.id
      and ti.template_id = p_template_id
      and ti.is_active = true;

    insert into public.checklist_run_items (
      run_id, template_item_id, item_order, title, response_type, is_required,
      requires_photo, requires_comment, score_points, options,
      require_comment_on_no, require_photo_on_no, generate_incident_on_no, rule_config,
      expected_response, triggers_incident, incident_severity, notify_roles, create_task_on_fail
    )
    select
      run_row.id,
      ti.id,
      ti.item_order,
      ti.title,
      ti.response_type,
      ti.is_required,
      ti.requires_photo,
      ti.requires_comment,
      ti.score_points,
      ti.options,
      ti.require_comment_on_no,
      ti.require_photo_on_no,
      ti.generate_incident_on_no,
      ti.rule_config,
      ti.expected_response,
      ti.triggers_incident,
      ti.incident_severity,
      ti.notify_roles,
      ti.create_task_on_fail
    from public.checklist_template_items ti
    where ti.template_id = p_template_id
      and ti.is_active = true
      and not exists (
        select 1
        from public.checklist_run_items ri
        where ri.run_id = run_row.id
          and ri.template_item_id = ti.id
      );

    GET DIAGNOSTICS inserted_count = ROW_COUNT;

    update public.checklist_runs r
    set
      total_points = coalesce((
        select sum(ri.score_points)::integer
        from public.checklist_run_items ri
        where ri.run_id = r.id
      ), 0),
      earned_points = coalesce((
        select sum(ri.earned_points)::integer
        from public.checklist_run_items ri
        where ri.run_id = r.id
      ), 0)
    where r.id = run_row.id;

    if was_completed and (inserted_count > 0 or public.checklist_run_has_pending_required(run_row.id)) then
      update public.checklist_runs
      set
        status = 'in_progress',
        completed_at = null,
        reviewed_at = null,
        reviewed_by = null,
        review_notes = null,
        started_at = coalesce(started_at, now())
      where id = run_row.id;

      perform public.notify_checklist_run_reopened(
        run_row.id,
        coalesce(template_title, 'Checklist') || ' fue actualizada y tiene items pendientes por completar.'
      );

      reopened_runs := reopened_runs + 1;
    end if;

    synced_runs := synced_runs + 1;
  end loop;

  return jsonb_build_object(
    'synced_runs', synced_runs,
    'reopened_runs', reopened_runs
  );
end;
$$;


ALTER FUNCTION "public"."sync_checklist_runs_from_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_employee_expediente_alerts"("p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count integer := 0;
  v_hr_ids uuid[];
  rec record;
  v_task_id text;
  v_priority text;
  v_title text;
  v_alert_id uuid;
begin
  if auth.uid() is not null and not public.can_read_employee_expedientes() then
    raise exception 'No tienes permiso para sincronizar alertas.';
  end if;

  select coalesce(array_agg(p.id), '{}'::uuid[])
  into v_hr_ids
  from public.profiles p
  where p.status = 'active'
    and public.normalize_profile_role(p.role) = 'recursos_humanos';

  for rec in
    select
      p.id as profile_id,
      p.full_name,
      v.id as version_id,
      ft.code as file_type_code,
      ft.label as file_type_label,
      v.expires_at,
      public.employee_file_expiry_status(v.expires_at, v.no_expires) as expiry_status
    from public.profiles p
    join public.employee_file_versions v on v.profile_id = p.id and v.is_current = true
    join public.employee_file_types ft on ft.code = v.file_type_code
    where p.status = 'active'
      and not coalesce(v.no_expires, false)
      and v.expires_at is not null
      and (p_profile_id is null or p.id = p_profile_id)
      and public.employee_file_expiry_status(v.expires_at, v.no_expires) in ('warning', 'orange', 'expired')
  loop
    v_priority := case rec.expiry_status
      when 'expired' then 'critical'
      when 'orange' then 'high'
      else 'medium'
    end;

    v_title := case rec.expiry_status
      when 'expired' then 'Renovar ' || lower(rec.file_type_label) || ' de ' || coalesce(rec.full_name, 'colaborador') || ' (vencido)'
      else 'Renovar ' || lower(rec.file_type_label) || ' de ' || coalesce(rec.full_name, 'colaborador')
    end;

    insert into public.employee_file_alerts (
      profile_id, file_type_code, version_id, alert_level, message
    )
    values (
      rec.profile_id,
      rec.file_type_code,
      rec.version_id,
      case rec.expiry_status when 'expired' then 'critical' when 'orange' then 'orange' else 'warning' end,
      v_title
    )
    on conflict (profile_id, file_type_code, alert_level, alert_date) do update set
      message = excluded.message,
      version_id = excluded.version_id
    returning id into v_alert_id;

    v_count := v_count + 1;

    v_task_id := 'expediente-' || rec.profile_id::text || '-' || rec.file_type_code || '-' || rec.expiry_status;

    insert into public.assigned_tasks (
      id, title, status, due_date, due_at, assigned_profile_ids, assigned_by, payload
    )
    values (
      v_task_id,
      v_title,
      'pending',
      coalesce(rec.expires_at, current_date),
      coalesce(rec.expires_at, current_date)::timestamptz,
      v_hr_ids,
      auth.uid(),
      jsonb_build_object(
        'source', 'employee_expediente',
        'profile_id', rec.profile_id,
        'file_type_code', rec.file_type_code,
        'priority', v_priority,
        'category', 'Recursos Humanos'
      )
    )
    on conflict (id) do update set
      title = excluded.title,
      due_date = excluded.due_date,
      due_at = excluded.due_at,
      payload = excluded.payload,
      updated_at = now();

    update public.employee_file_alerts
    set task_id = v_task_id
    where profile_id = rec.profile_id
      and file_type_code = rec.file_type_code
      and alert_date = current_date
      and resolved_at is null;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."sync_employee_expediente_alerts"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_pos_item_from_ticket_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  order_item public.pos_order_items;
  next_status text;
begin
  if new.status is not distinct from old.status then
    return new;
  end if;
  next_status := case new.status
    when 'in_production' then 'in_production'
    when 'ready' then 'ready'
    when 'served' then 'served'
    when 'cancelled' then 'cancelled'
    when 'problem' then 'error'
    else null
  end;
  if next_status is null then
    return new;
  end if;
  update public.pos_order_items
  set status = next_status
  where id::text = new.order_item_id and production_ticket_id = new.ticket_id
  returning * into order_item;
  if order_item.id is not null then
    insert into public.pos_order_events (order_id, event_type, description, created_by)
    values (
      order_item.order_id,
      'production_' || next_status,
      order_item.product_name || ': estado de produccion actualizado a ' || next_status || '.',
      auth.uid()
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_pos_item_from_ticket_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_pos_order_owner_legacy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO '', 'public'
    AS $$
begin
  if tg_op <> 'INSERT' then
    return new;
  end if;

  if new.owner_profile_id is not null
     and new.waiter_id is not null
     and new.owner_profile_id is distinct from new.waiter_id then
    raise exception 'POS_ORDER_OWNER_WAITER_MISMATCH'
      using hint = 'owner_profile_id and waiter_id must match on insert.';
  end if;

  if new.owner_profile_id is null and new.waiter_id is not null then
    new.owner_profile_id := new.waiter_id;
  elsif new.owner_profile_id is not null and new.waiter_id is null then
    new.waiter_id := new.owner_profile_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_pos_order_owner_legacy"() OWNER TO "postgres";


