CREATE OR REPLACE FUNCTION "public"."task_step_has_dependency_cycle"("p_step_id" "uuid", "p_depends_on" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current uuid := p_depends_on;
  v_guard int := 0;
begin
  if p_step_id is null or p_depends_on is null then
    return false;
  end if;
  if p_step_id = p_depends_on then
    return true;
  end if;

  while v_current is not null and v_guard < 100 loop
    if v_current = p_step_id then
      return true;
    end if;
    select s.depends_on_step_id into v_current
    from public.task_steps s
    where s.id = v_current and s.deleted_at is null;
    v_guard := v_guard + 1;
  end loop;

  return false;
end;
$$;


ALTER FUNCTION "public"."task_step_has_dependency_cycle"("p_step_id" "uuid", "p_depends_on" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."task_work_plan_json"("p_task_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', sl.id,
      'title', sl.title,
      'sort_position', sl.sort_position,
      'steps', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', s.id,
            'text', s.text,
            'completed', s.completed,
            'completed_at', s.completed_at,
            'completed_by', s.completed_by,
            'completed_by_name', (select p.full_name from public.profiles p where p.id = s.completed_by),
            'assigned_profile_id', s.assigned_profile_id,
            'assigned_name', (select p.full_name from public.profiles p where p.id = s.assigned_profile_id),
            'assigned_avatar', (select p.avatar_url from public.profiles p where p.id = s.assigned_profile_id),
            'due_at', s.due_at,
            'sort_position', s.sort_position,
            'depends_on_step_id', s.depends_on_step_id,
            'depends_on_text', (
              select dep.text from public.task_steps dep
              where dep.id = s.depends_on_step_id and dep.deleted_at is null
            ),
            'is_blocked', (
              s.depends_on_step_id is not null
              and not exists (
                select 1 from public.task_steps dep
                where dep.id = s.depends_on_step_id
                  and dep.deleted_at is null
                  and dep.completed
              )
            ),
            'converted_task_id', s.converted_task_id,
            'attachment_count', (
              select count(*)::int from public.task_attachments a
              where a.step_id = s.id and a.deleted_at is null
            ),
            'comment_count', (
              select count(*)::int from public.task_comments c
              where c.step_id = s.id and c.deleted_at is null
            )
          )
          order by s.sort_position asc
        )
        from public.task_steps s
        where s.step_list_id = sl.id and s.deleted_at is null
      ), '[]'::jsonb)
    )
    order by sl.sort_position asc
  ), '[]'::jsonb)
  from public.task_step_lists sl
  where sl.task_id = p_task_id
    and sl.deleted_at is null;
$$;


ALTER FUNCTION "public"."task_work_plan_json"("p_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."test_attendance_mark_chain_rules"() RETURNS TABLE("scenario" "text", "mark_type" "text", "has_open_entry" boolean, "has_open_meal" boolean, "expected_allowed" boolean, "expected_reason_code" "text", "passed" boolean, "detail" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v record;
  v_allowed boolean;
  v_reason_code text;
begin
  for v in
    select *
    from (
      values
        ('entrada normal', 'entrada', false, false, true, 'allowed'),
        ('entrada bloqueada por turno abierto', 'entrada', true, false, false, 'open_entry'),
        ('salida_comida permitida con entrada abierta', 'salida_comida', true, false, true, 'open_shift'),
        ('salida_comida bloqueada sin entrada', 'salida_comida', false, false, false, 'no_open_entry'),
        ('salida_comida bloqueada con comida abierta', 'salida_comida', true, true, false, 'open_meal'),
        ('regreso_comida permitido con comida abierta', 'regreso_comida', true, true, true, 'open_shift'),
        ('regreso_comida bloqueado sin comida', 'regreso_comida', true, false, false, 'no_open_meal'),
        ('salida_final permitida con entrada abierta', 'salida_final', true, false, true, 'open_shift'),
        ('salida_final bloqueada sin entrada', 'salida_final', false, false, false, 'no_open_entry'),
        ('salida_final bloqueada con comida abierta', 'salida_final', true, true, false, 'open_meal')
    ) as t(scenario, mark_type, has_open_entry, has_open_meal, expected_allowed, expected_reason_code)
  loop
    select c.allowed, c.reason_code
    into v_allowed, v_reason_code
    from public.evaluate_attendance_mark_chain(
      v.mark_type,
      v.has_open_entry,
      v.has_open_meal
    ) c;

    scenario := v.scenario;
    mark_type := v.mark_type;
    has_open_entry := v.has_open_entry;
    has_open_meal := v.has_open_meal;
    expected_allowed := v.expected_allowed;
    expected_reason_code := v.expected_reason_code;
    passed := v_allowed = v.expected_allowed and v_reason_code = v.expected_reason_code;
    detail := format(
      'got allowed=%s reason_code=%s',
      v_allowed,
      v_reason_code
    );
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."test_attendance_mark_chain_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."test_pos_order_owner_f0a_rules"() RETURNS TABLE("scenario" "text", "passed" boolean, "detail" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO '', 'public'
    AS $$
declare
  v_order uuid;
  v_blocked boolean := false;
  v_err text;
begin
  return query select 'migration_owner_column_exists'::text,
    exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'pos_orders'
        and column_name = 'owner_profile_id'
    ), 'column owner_profile_id'::text;

  return query select 'migration_owner_fk_exists'::text,
    exists (
      select 1 from pg_constraint where conname = 'pos_orders_owner_profile_id_fkey'
    ), 'FK owner_profile_id'::text;

  return query select 'migration_sync_trigger_exists'::text,
    exists (
      select 1 from pg_trigger
      where tgname = 'sync_pos_order_owner_legacy'
        and tgrelid = 'public.pos_orders'::regclass
        and not tgisinternal
    ),
    'sync_pos_order_owner_legacy present'::text;

  return query select 'internal_owner_rpc_absent'::text,
    to_regprocedure('public.set_pos_order_owner_internal(uuid, uuid, text)') is null,
    'set_pos_order_owner_internal removed from F0A'::text;

  return query select 'diagnose_integrity_not_authenticated'::text,
    not has_function_privilege('authenticated', 'public.diagnose_pos_order_owner_integrity()', 'EXECUTE'),
    'diagnose_pos_order_owner_integrity'::text;

  return query select 'diagnose_orphans_not_authenticated'::text,
    not has_function_privilege('authenticated', 'public.diagnose_pos_order_owner_orphans()', 'EXECUTE'),
    'diagnose_pos_order_owner_orphans'::text;

  return query select 'diagnose_orphans_service_role'::text,
    has_function_privilege('service_role', 'public.diagnose_pos_order_owner_orphans()', 'EXECUTE'),
    'orphans diagnostic for service_role'::text;

  return query select 'backfill_no_mismatch_when_both_set'::text,
    not exists (
      select 1 from public.pos_orders o
      where o.owner_profile_id is not null and o.waiter_id is not null
        and o.owner_profile_id <> o.waiter_id
    ), 'owner/waiter aligned after backfill'::text;

  return query select 'ranking_function_uses_owner_coalesce'::text,
    pg_get_functiondef('public.get_waiter_sales_ranking(date, boolean)'::regprocedure)
      ilike '%coalesce(o.owner_profile_id, o.waiter_id)%',
    'ranking coalesce'::text;

  select o.id into v_order from public.pos_orders o order by o.created_at desc limit 1;

  if v_order is null then
    return query select 'guard_blocks_owner_update'::text, true, 'skipped — no orders'::text;
    return query select 'guard_blocks_waiter_update'::text, true, 'skipped — no orders'::text;
    return query select 'guard_blocks_both_update'::text, true, 'skipped — no orders'::text;
    return query select 'status_update_allowed'::text, true, 'skipped — no orders'::text;
    return query select 'insert_mismatch_rejected'::text, true, 'skipped — no fixture'::text;
    return;
  end if;

  begin
    update public.pos_orders set owner_profile_id = gen_random_uuid() where id = v_order;
    v_blocked := false;
  exception when others then
    v_blocked := sqlerrm ilike '%POS_ORDER_OWNER_IMMUTABLE%';
  end;
  return query select 'guard_blocks_owner_update'::text, v_blocked, 'UPDATE owner only'::text;

  begin
    update public.pos_orders set waiter_id = gen_random_uuid() where id = v_order;
    v_blocked := false;
  exception when others then
    v_blocked := sqlerrm ilike '%POS_ORDER_OWNER_IMMUTABLE%';
  end;
  return query select 'guard_blocks_waiter_update'::text, v_blocked, 'UPDATE waiter only'::text;

  begin
    update public.pos_orders
    set owner_profile_id = gen_random_uuid(), waiter_id = gen_random_uuid()
    where id = v_order;
    v_blocked := false;
  exception when others then
    v_blocked := sqlerrm ilike '%POS_ORDER_OWNER_IMMUTABLE%';
  end;
  return query select 'guard_blocks_both_update'::text, v_blocked, 'UPDATE both'::text;

  begin
    update public.pos_orders
    set status = status
    where id = v_order;
    return query select 'status_update_allowed'::text, true, 'status-only UPDATE'::text;
  exception when others then
    return query select 'status_update_allowed'::text, false, sqlerrm;
  end;

  begin
    insert into public.pos_orders (
      table_id, table_name, waiter_id, owner_profile_id, status, subtotal, total
    ) values (
      'f0a-test', 'Mesa test', gen_random_uuid(), gen_random_uuid(), 'open', 0, 0
    );
    return query select 'insert_mismatch_rejected'::text, false, 'mismatch insert succeeded'::text;
  exception when others then
    v_err := sqlerrm;
    return query select 'insert_mismatch_rejected'::text,
      v_err ilike '%POS_ORDER_OWNER_WAITER_MISMATCH%',
      'INSERT owner<>waiter rejected'::text;
  end;
end;
$$;


ALTER FUNCTION "public"."test_pos_order_owner_f0a_rules"() OWNER TO "postgres";


