CREATE OR REPLACE FUNCTION "public"."try_global_unit_factor"("p_from_unit" "text", "p_to_unit" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when public.normalize_inventory_unit(p_from_unit) = public.normalize_inventory_unit(p_to_unit) then 1::numeric
    else coalesce(
      (
        select c.factor
        from public.inventory_unit_conversions c
        where public.normalize_inventory_unit(c.from_unit) = public.normalize_inventory_unit(p_from_unit)
          and public.normalize_inventory_unit(c.to_unit) = public.normalize_inventory_unit(p_to_unit)
        limit 1
      ),
      (
        select 1 / c.factor
        from public.inventory_unit_conversions c
        where public.normalize_inventory_unit(c.from_unit) = public.normalize_inventory_unit(p_to_unit)
          and public.normalize_inventory_unit(c.to_unit) = public.normalize_inventory_unit(p_from_unit)
          and c.factor > 0
        limit 1
      )
    )
  end;
$$;


ALTER FUNCTION "public"."try_global_unit_factor"("p_from_unit" "text", "p_to_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_attendance_device"("p_device_id" "text", "p_device_name" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."attendance_devices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  device_row public.attendance_devices;
begin
  if not public.is_attendance_security_admin() then
    raise exception 'Solo Administracion puede editar dispositivos de marcaje.';
  end if;

  update public.attendance_devices
  set
    device_name = coalesce(nullif(trim(p_device_name), ''), device_name),
    notes = coalesce(nullif(trim(p_notes), ''), notes),
    updated_at = now()
  where device_id = nullif(trim(p_device_id), '')
  returning * into device_row;

  if device_row.id is null then
    raise exception 'Dispositivo no encontrado.';
  end if;

  return device_row;
end;
$$;


