CREATE OR REPLACE FUNCTION "public"."update_bakery_dough_batch_status"("p_dough_batch_id" "uuid", "p_status" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."bakery_dough_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.bakery_dough_batches;
  v_status text := lower(trim(coalesce(p_status, '')));
begin
  if not public.can_operate_bakery_production() then
    raise exception 'PERMISSION_DENIED';
  end if;
  if v_status not in ('mixed', 'resting', 'balled', 'cold_room', 'ready', 'used', 'discarded') then
    raise exception 'Estado de masa no válido.';
  end if;

  select * into v_row from public.bakery_dough_batches where id = p_dough_batch_id for update;
  if v_row.id is null then raise exception 'Lote de masa no encontrado.'; end if;

  update public.bakery_dough_batches
  set
    status = v_status,
    cold_room_started_at = case
      when v_status = 'cold_room' and cold_room_started_at is null then now()
      else cold_room_started_at
    end,
    notes = coalesce(nullif(trim(p_notes), ''), notes),
    updated_at = now()
  where id = p_dough_batch_id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_bakery_dough_batch_status"("p_dough_batch_id" "uuid", "p_status" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_catering_followup"("p_request_id" "uuid", "p_follow_up_date" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text", "p_conversion_status" "text" DEFAULT NULL::"text", "p_estimated_value" numeric DEFAULT NULL::numeric, "p_win_probability" integer DEFAULT NULL::integer) RETURNS "public"."catering_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_conversion_status text := nullif(trim(coalesce(p_conversion_status, '')), '');
  v_previous_conversion text;
  v_row public.catering_requests;
  v_description text := 'Seguimiento registrado';
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para registrar seguimiento de catering.';
  end if;

  if p_request_id is null then
    raise exception 'p_request_id es obligatorio.';
  end if;

  if v_conversion_status is not null and not public.is_valid_catering_conversion_status(v_conversion_status) then
    raise exception 'conversion_status invalido: %', v_conversion_status;
  end if;

  if p_estimated_value is not null and p_estimated_value < 0 then
    raise exception 'estimated_value no puede ser negativo.';
  end if;

  if p_win_probability is not null and (p_win_probability < 0 or p_win_probability > 100) then
    raise exception 'win_probability debe estar entre 0 y 100.';
  end if;

  select request.conversion_status
  into v_previous_conversion
  from public.catering_requests request
  where request.id = p_request_id;

  update public.catering_requests request
  set
    follow_up_date = coalesce(p_follow_up_date, request.follow_up_date),
    last_contact_at = now(),
    conversion_status = coalesce(v_conversion_status, request.conversion_status),
    estimated_value = coalesce(p_estimated_value, request.estimated_value),
    win_probability = coalesce(p_win_probability, request.win_probability),
    notes = case
      when p_notes is null then request.notes
      when nullif(trim(p_notes), '') is null then request.notes
      when nullif(trim(coalesce(request.notes, '')), '') is null then trim(p_notes)
      else request.notes || E'\n' || trim(p_notes)
    end,
    updated_by = auth.uid()
  where request.id = p_request_id
  returning * into v_row;

  if not found then
    raise exception 'Solicitud de catering no encontrada.';
  end if;

  if v_previous_conversion is distinct from v_row.conversion_status then
    perform public.log_catering_activity(
      v_row.id,
      'status_changed',
      'Estado comercial: ' || coalesce(v_previous_conversion, '—') || ' → ' || v_row.conversion_status,
      jsonb_build_object(
        'previous_conversion_status', v_previous_conversion,
        'new_conversion_status', v_row.conversion_status
      )
    );
    v_description := 'Cliente contactado';
    perform public.log_catering_activity(
      v_row.id,
      'contact_made',
      v_description,
      jsonb_build_object('conversion_status', v_row.conversion_status)
    );
  else
    perform public.log_catering_activity(
      v_row.id,
      'followup_recorded',
      v_description,
      jsonb_build_object(
        'follow_up_date', v_row.follow_up_date,
        'notes', nullif(trim(coalesce(p_notes, '')), '')
      )
    );
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_catering_followup"("p_request_id" "uuid", "p_follow_up_date" "date", "p_notes" "text", "p_conversion_status" "text", "p_estimated_value" numeric, "p_win_probability" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_catering_quote"("p_quote_id" "uuid", "p_items" "jsonb", "p_discount_amount" numeric DEFAULT 0, "p_valid_until" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text", "p_terms" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_quote public.catering_quotes;
  v_totals jsonb;
  v_item jsonb;
  v_sort integer := 0;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para actualizar cotizaciones de catering.';
  end if;

  if p_quote_id is null then
    raise exception 'p_quote_id es obligatorio.';
  end if;

  select * into v_quote from public.catering_quotes where id = p_quote_id for update;
  if not found then
    raise exception 'Cotizacion no encontrada.';
  end if;

  if v_quote.status <> 'draft' then
    raise exception 'Solo se pueden editar cotizaciones en borrador.';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Debes incluir al menos una linea en la cotizacion.';
  end if;

  v_totals := public.catering_quote_totals(p_items, p_discount_amount);

  update public.catering_quotes
  set
    subtotal = (v_totals ->> 'subtotal')::numeric,
    discount_amount = (v_totals ->> 'discount_amount')::numeric,
    tax_amount = 0,
    total = (v_totals ->> 'total')::numeric,
    valid_until = p_valid_until,
    notes = nullif(trim(coalesce(p_notes, '')), ''),
    terms = nullif(trim(coalesce(p_terms, '')), ''),
    updated_at = now()
  where id = p_quote_id;

  delete from public.catering_quote_items where quote_id = p_quote_id;

  for v_item in select value from jsonb_array_elements(p_items) as value loop
    v_sort := v_sort + 1;
    insert into public.catering_quote_items (
      quote_id, item_type, description, quantity, quantity_unit, unit_price, total_price, sort_order,
      line_kind, option_group_name, option_label, is_selected_option
    )
    values (
      p_quote_id,
      coalesce(nullif(trim(v_item ->> 'item_type'), ''), 'other'),
      trim(v_item ->> 'description'),
      coalesce(nullif(v_item ->> 'quantity', '')::numeric, 1),
      coalesce(nullif(trim(v_item ->> 'quantity_unit'), ''), 'unidades'),
      coalesce(nullif(v_item ->> 'unit_price', '')::numeric, 0),
      round(coalesce(nullif(v_item ->> 'quantity', '')::numeric, 1) * coalesce(nullif(v_item ->> 'unit_price', '')::numeric, 0), 2),
      coalesce(nullif(v_item ->> 'sort_order', '')::integer, v_sort),
      coalesce(nullif(trim(v_item ->> 'line_kind'), ''), 'normal'),
      nullif(trim(coalesce(v_item ->> 'option_group_name', '')), ''),
      nullif(trim(coalesce(v_item ->> 'option_label', '')), ''),
      coalesce((v_item ->> 'is_selected_option')::boolean, false)
    );
  end loop;

  return public.get_catering_quote_detail(p_quote_id);
end;
$$;


ALTER FUNCTION "public"."update_catering_quote"("p_quote_id" "uuid", "p_items" "jsonb", "p_discount_amount" numeric, "p_valid_until" "date", "p_notes" "text", "p_terms" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_catering_quote_status"("p_quote_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_quote public.catering_quotes;
  v_request public.catering_requests;
  v_status text := lower(trim(coalesce(p_status, '')));
  v_activity_type text;
  v_activity_description text;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para actualizar cotizaciones de catering.';
  end if;

  if p_quote_id is null then
    raise exception 'p_quote_id es obligatorio.';
  end if;

  if v_status not in ('draft', 'sent', 'approved', 'rejected', 'expired') then
    raise exception 'Estado de cotizacion invalido: %.', v_status;
  end if;

  select * into v_quote from public.catering_quotes where id = p_quote_id for update;
  if not found then
    raise exception 'Cotizacion no encontrada.';
  end if;

  if v_quote.status = v_status then
    return public.get_catering_quote_detail(p_quote_id);
  end if;

  if v_status = 'draft' then
    raise exception 'No se puede regresar una cotizacion a borrador.';
  end if;

  if v_status = 'sent' and v_quote.status not in ('draft') then
    raise exception 'Solo borradores pueden marcarse como enviados.';
  end if;

  if v_status in ('approved', 'rejected') and v_quote.status not in ('sent') then
    raise exception 'Solo cotizaciones enviadas pueden aprobarse o rechazarse.';
  end if;

  if v_status = 'expired' and v_quote.status not in ('sent') then
    raise exception 'Solo cotizaciones enviadas pueden vencer.';
  end if;

  update public.catering_quotes
  set status = v_status, updated_at = now()
  where id = p_quote_id
  returning * into v_quote;

  v_activity_type := case v_status
    when 'sent' then 'quote_sent'
    when 'approved' then 'quote_approved'
    when 'rejected' then 'quote_rejected'
    when 'expired' then 'quote_expired'
    else 'status_changed'
  end;

  v_activity_description := case v_status
    when 'sent' then 'Cotizacion ' || v_quote.quote_number || ' enviada al cliente'
    when 'approved' then 'Cotizacion ' || v_quote.quote_number || ' aprobada'
    when 'rejected' then 'Cotizacion ' || v_quote.quote_number || ' rechazada'
    when 'expired' then 'Cotizacion ' || v_quote.quote_number || ' vencida'
    else 'Estado de cotizacion actualizado'
  end;

  perform public.log_catering_activity(
    v_quote.request_id,
    v_activity_type,
    v_activity_description,
    jsonb_build_object(
      'quote_id', v_quote.id,
      'quote_number', v_quote.quote_number,
      'status', v_quote.status,
      'total', v_quote.total
    )
  );

  select * into v_request from public.catering_requests where id = v_quote.request_id for update;

  if v_status = 'sent' then
    update public.catering_requests
    set
      conversion_status = case
        when conversion_status in ('lead', 'contacted') then 'quoted'
        else conversion_status
      end,
      status = case when status = 'new' then 'quoted' else status end,
      estimated_value = coalesce(estimated_value, v_quote.total),
      updated_by = auth.uid()
    where id = v_quote.request_id;
  elsif v_status = 'approved' then
    update public.catering_requests
    set
      conversion_status = 'approved',
      status = 'approved',
      estimated_value = v_quote.total,
      win_probability = 100,
      updated_by = auth.uid()
    where id = v_quote.request_id;

    perform public.create_finance_receivable_from_catering(v_quote.request_id, true);
  end if;

  perform public.notify_catering_quote_status(p_quote_id, v_status);

  return public.get_catering_quote_detail(p_quote_id);
end;
$$;


ALTER FUNCTION "public"."update_catering_quote_status"("p_quote_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_catering_request"("p_request_id" "uuid", "p_data" "jsonb") RETURNS "public"."catering_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.catering_requests;
  v_customer_name text := nullif(trim(coalesce(p_data ->> 'customer_name', '')), '');
  v_phone text := nullif(trim(coalesce(p_data ->> 'customer_phone', '')), '');
  v_email text := nullif(trim(coalesce(p_data ->> 'customer_email', '')), '');
  v_lead_source text;
  v_guest_count integer;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para editar solicitudes de catering.';
  end if;

  select * into v_row
  from public.catering_requests
  where id = p_request_id;

  if not found then
    raise exception 'Solicitud de catering no encontrada.';
  end if;

  if v_customer_name is null then
    raise exception 'customer_name es obligatorio.';
  end if;

  if v_phone is null and v_email is null then
    raise exception 'Debes indicar telefono o correo del cliente.';
  end if;

  v_lead_source := public.normalize_catering_lead_source(
    coalesce(p_data ->> 'lead_source', v_row.lead_source),
    v_row.source
  );

  if nullif(p_data ->> 'guest_count', '') is not null then
    v_guest_count := nullif(p_data ->> 'guest_count', '')::integer;
    if v_guest_count is not null and v_guest_count <= 0 then
      raise exception 'guest_count debe ser mayor a 0.';
    end if;
  end if;

  update public.catering_requests request
  set
    customer_name = v_customer_name,
    customer_phone = v_phone,
    customer_email = v_email,
    event_date = nullif(p_data ->> 'event_date', '')::date,
    event_time = nullif(p_data ->> 'event_time', '')::time,
    event_location = nullif(trim(coalesce(p_data ->> 'event_location', '')), ''),
    event_type = nullif(trim(coalesce(p_data ->> 'event_type', '')), ''),
    guest_count = coalesce(
      v_guest_count,
      nullif(p_data ->> 'guest_count', '')::integer
    ),
    products_requested = coalesce(
      (
        select array_agg(value)
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(p_data -> 'products_requested') = 'array' then p_data -> 'products_requested'
            else '[]'::jsonb
          end
        ) as value
        where nullif(trim(value), '') is not null
      ),
      '{}'::text[]
    ),
    notes = nullif(trim(coalesce(p_data ->> 'notes', '')), ''),
    lead_source = v_lead_source,
    assigned_to = case
      when p_data ? 'assigned_to' then nullif(p_data ->> 'assigned_to', '')::uuid
      else request.assigned_to
    end,
    follow_up_date = case
      when p_data ? 'follow_up_date' then nullif(p_data ->> 'follow_up_date', '')::date
      else request.follow_up_date
    end,
    estimated_value = case
      when p_data ? 'estimated_value' then nullif(p_data ->> 'estimated_value', '')::numeric(12, 2)
      else request.estimated_value
    end,
    updated_at = now(),
    updated_by = auth.uid()
  where request.id = p_request_id
  returning * into v_row;

  perform public.log_catering_activity(
    p_request_id,
    'lead_updated',
    'Datos del lead actualizados',
    jsonb_build_object(
      'customer_name', v_row.customer_name,
      'event_type', v_row.event_type,
      'event_date', v_row.event_date
    ),
    auth.uid(),
    now()
  );

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_catering_request"("p_request_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_catering_request_status"("p_request_id" "uuid", "p_status" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."catering_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text := nullif(trim(coalesce(p_status, '')), '');
  v_mapped_conversion text;
  v_previous_status text;
  v_row public.catering_requests;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para actualizar solicitudes de catering.';
  end if;

  if p_request_id is null or v_status is null then
    raise exception 'p_request_id y p_status son obligatorios.';
  end if;

  if not public.is_valid_catering_operational_status(v_status) then
    raise exception 'status operativo invalido: %', v_status;
  end if;

  select request.status
  into v_previous_status
  from public.catering_requests request
  where request.id = p_request_id;

  v_mapped_conversion := public.map_catering_status_to_conversion(v_status);

  update public.catering_requests request
  set
    status = v_status,
    conversion_status = coalesce(v_mapped_conversion, request.conversion_status),
    notes = case
      when p_notes is null then request.notes
      when nullif(trim(p_notes), '') is null then request.notes
      when nullif(trim(coalesce(request.notes, '')), '') is null then trim(p_notes)
      else request.notes || E'\n' || trim(p_notes)
    end,
    updated_by = auth.uid()
  where request.id = p_request_id
  returning * into v_row;

  if not found then
    raise exception 'Solicitud de catering no encontrada.';
  end if;

  if v_previous_status is distinct from v_status then
    perform public.log_catering_activity(
      v_row.id,
      'status_changed',
      'Estado operativo: ' || coalesce(v_previous_status, '—') || ' → ' || v_status,
      jsonb_build_object(
        'previous_status', v_previous_status,
        'new_status', v_status,
        'conversion_status', v_row.conversion_status
      )
    );
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_catering_request_status"("p_request_id" "uuid", "p_status" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_checklist_incident_status"("p_incident_id" "uuid", "p_status" "text", "p_resolution_notes" "text" DEFAULT NULL::"text") RETURNS "public"."checklist_incidents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  incident_record public.checklist_incidents;
begin
  if p_status not in ('open', 'acknowledged', 'in_progress', 'resolved', 'dismissed') then
    raise exception 'Estado de incidencia no valido.';
  end if;

  select * into incident_record
  from public.checklist_incidents
  where id = p_incident_id
  for update;

  if incident_record.id is null then
    raise exception 'La incidencia no existe.';
  end if;

  if not public.can_access_checklist_incident(incident_record) or not public.can_manage_checklist_incident_status(p_status) then
    raise exception 'No tienes permiso para actualizar esta incidencia.';
  end if;

  update public.checklist_incidents
  set
    status = p_status,
    resolution_notes = coalesce(nullif(trim(p_resolution_notes), ''), resolution_notes),
    resolved_by = case when p_status in ('resolved', 'dismissed') then auth.uid() else resolved_by end,
    resolved_at = case when p_status in ('resolved', 'dismissed') then now() else null end,
    updated_at = now()
  where id = p_incident_id
  returning * into incident_record;

  return incident_record;
end;
$$;


ALTER FUNCTION "public"."update_checklist_incident_status"("p_incident_id" "uuid", "p_status" "text", "p_resolution_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_checklist_management_alert_status"("p_alert_id" "uuid", "p_status" "text", "p_resolution_notes" "text" DEFAULT NULL::"text") RETURNS "public"."checklist_management_alerts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  alert_record public.checklist_management_alerts;
  normalized_status text;
begin
  if not public.can_manage_checklist_management_alert() then
    raise exception 'No tienes permiso para actualizar avisos a gerencia.';
  end if;

  normalized_status := lower(trim(coalesce(p_status, '')));
  if normalized_status not in ('open', 'reviewed', 'resolved', 'dismissed') then
    raise exception 'Estado de aviso no valido.';
  end if;

  select * into alert_record
  from public.checklist_management_alerts
  where id = p_alert_id
  for update;

  if alert_record.id is null then
    raise exception 'El aviso no existe.';
  end if;

  update public.checklist_management_alerts
  set
    status = normalized_status,
    resolution_notes = coalesce(nullif(trim(p_resolution_notes), ''), resolution_notes),
    resolved_by = case when normalized_status in ('resolved', 'dismissed') then auth.uid() else resolved_by end,
    resolved_at = case when normalized_status in ('resolved', 'dismissed') then now() else null end,
    updated_at = now()
  where id = p_alert_id
  returning * into alert_record;

  return alert_record;
end;
$$;


ALTER FUNCTION "public"."update_checklist_management_alert_status"("p_alert_id" "uuid", "p_status" "text", "p_resolution_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_requisition"("p_requisition_id" "uuid", "p_data" "jsonb", "p_items" "jsonb") RETURNS "public"."requisitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_row public.requisitions;
  updated public.requisitions;
  row_data jsonb;
  catalog_item public.inventory_items;
  requester public.profiles;
  from_id text := nullif(trim(p_data ->> 'from_area_id'), '');
  to_id text := nullif(trim(p_data ->> 'to_area_id'), '');
  requester_id uuid := nullif(p_data ->> 'requested_by_profile_id', '')::uuid;
  requested_qty numeric;
  requested_unit text;
  conversion_factor numeric;
  converted_qty numeric;
  source_stock numeric;
  source_minimum numeric;
  availability text;
begin
  select * into current_row from public.requisitions where id = p_requisition_id;
  if current_row.id is null or current_row.status <> 'draft' then
    raise exception 'Solo se pueden editar requisiciones en borrador.';
  end if;
  if current_row.requested_by <> auth.uid() and not public.is_profile_manager() then
    raise exception 'No tienes permiso para editar esta requisicion.';
  end if;

  perform public.assert_requisition_request_permissions(from_id, to_id, requester_id);

  select * into requester from public.profiles where id = requester_id and status = 'active';
  if requester.id is null then
    raise exception 'Selecciona quien esta haciendo la requisicion.';
  end if;

  if jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'Agrega al menos un producto a la requisicion.';
  end if;

  update public.requisitions
    set from_area_id = from_id,
        to_area_id = to_id,
        priority = coalesce(nullif(trim(p_data ->> 'priority'), ''), 'normal'),
        notes = nullif(trim(p_data ->> 'notes'), ''),
        requested_by_profile_id = requester.id,
        requested_by_name = coalesce(requester.full_name, requester.username),
        requested_by_role = requester.role
  where id = p_requisition_id
  returning * into updated;

  delete from public.requisition_items where requisition_id = p_requisition_id;
  for row_data in select value from jsonb_array_elements(p_items)
  loop
    select * into catalog_item from public.inventory_items where id = (row_data ->> 'item_id')::uuid and active = true;
    requested_qty := coalesce((row_data ->> 'requested_quantity')::numeric, 0);
    if catalog_item.id is null or requested_qty <= 0 then raise exception 'Producto o cantidad invalida en la requisicion.'; end if;

    requested_unit := coalesce(
      nullif(trim(row_data ->> 'requested_unit'), ''),
      nullif(trim(catalog_item.default_requisition_unit), ''),
      catalog_item.base_unit
    );
    conversion_factor := public.resolve_item_requisition_unit_factor(catalog_item.id, requested_unit);
    converted_qty := requested_qty * conversion_factor;

    select quantity, minimum_quantity into source_stock, source_minimum
    from public.area_inventory
    where item_id = catalog_item.id and area_id = from_id;
    source_stock := coalesce(source_stock, 0);
    source_minimum := coalesce(source_minimum, 0);
    availability := case when source_stock <= 0 then 'Sin stock' when source_stock < converted_qty then 'Parcial' else 'Disponible' end;

    insert into public.requisition_items (
      requisition_id, item_id, item_name, unit, requested_quantity, approved_quantity,
      requested_unit, conversion_factor, converted_requested_quantity, availability_status,
      stock_available_at_request, stock_minimum_at_request, conversion_warning, notes, is_test,
      inventory_base_unit_at_request
    ) values (
      updated.id, catalog_item.id, catalog_item.name, requested_unit, requested_qty, null,
      requested_unit, conversion_factor, converted_qty, availability,
      source_stock, source_minimum, false, nullif(trim(row_data ->> 'notes'), ''),
      coalesce(current_row.is_test, false), catalog_item.base_unit
    );
  end loop;
  return updated;
end;
$$;


ALTER FUNCTION "public"."update_draft_requisition"("p_requisition_id" "uuid", "p_data" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_employee_file_current"("p_profile_id" "uuid", "p_file_type_code" "text", "p_issued_at" "date" DEFAULT NULL::"date", "p_expires_at" "date" DEFAULT NULL::"date", "p_no_expires" boolean DEFAULT false, "p_signature_status" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_type public.employee_file_types;
  v_file public.employee_files;
  v_version public.employee_file_versions;
  v_no_expires boolean := coalesce(p_no_expires, false);
  v_expires_at date := case when v_no_expires then null else p_expires_at end;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para editar documentos.';
  end if;

  select * into v_type from public.employee_file_types where code = p_file_type_code;
  if not found then
    raise exception 'Tipo de documento invalido: %.', p_file_type_code;
  end if;

  select * into v_file
  from public.employee_files
  where profile_id = p_profile_id and file_type_code = p_file_type_code;

  if not found or v_file.current_version_id is null then
    raise exception 'No hay documento cargado para actualizar.';
  end if;

  select * into v_version
  from public.employee_file_versions
  where id = v_file.current_version_id
  for update;

  if not found then
    raise exception 'Version actual no encontrada.';
  end if;

  update public.employee_file_versions
  set
    issued_at = p_issued_at,
    expires_at = v_expires_at,
    no_expires = v_no_expires,
    notes = nullif(trim(coalesce(p_notes, '')), '')
  where id = v_version.id;

  if v_type.requires_signature then
    update public.employee_files
    set
      signature_status = coalesce(nullif(trim(coalesce(p_signature_status, '')), ''), signature_status),
      updated_at = now()
    where id = v_file.id
    returning * into v_file;
  else
    update public.employee_files set updated_at = now() where id = v_file.id returning * into v_file;
  end if;

  select * into v_version from public.employee_file_versions where id = v_version.id;

  begin
    perform public.sync_employee_expediente_alerts(p_profile_id);
  exception
    when others then
      raise warning 'sync_employee_expediente_alerts failed for %: %', p_profile_id, sqlerrm;
  end;

  return jsonb_build_object('file', to_jsonb(v_file), 'version', to_jsonb(v_version));
end;
$$;


ALTER FUNCTION "public"."update_employee_file_current"("p_profile_id" "uuid", "p_file_type_code" "text", "p_issued_at" "date", "p_expires_at" "date", "p_no_expires" boolean, "p_signature_status" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_finance_reconciliation_item"("p_item_id" "uuid", "p_is_checked" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item public.finance_reconciliation_items;
  v_rec public.finance_reconciliations;
  v_checked_in numeric := 0;
  v_checked_out numeric := 0;
  v_difference numeric;
begin
  if not public.can_reconcile_finance() then
    raise exception 'No tienes permiso para conciliar.';
  end if;

  update public.finance_reconciliation_items
  set is_checked = p_is_checked,
      checked_at = case when p_is_checked then now() else null end
  where id = p_item_id
  returning * into v_item;

  if not found then raise exception 'Item de conciliación no encontrado.'; end if;

  select * into v_rec from public.finance_reconciliations where id = v_item.reconciliation_id for update;
  if v_rec.status = 'closed' then raise exception 'La conciliación ya está cerrada.'; end if;

  select
    coalesce(sum(case when t.direction = 'in' then t.amount else 0 end), 0),
    coalesce(sum(case when t.direction = 'out' then t.amount else 0 end), 0)
  into v_checked_in, v_checked_out
  from public.finance_reconciliation_items i
  join public.finance_bank_transactions t on t.id = i.bank_transaction_id
  where i.reconciliation_id = v_rec.id and i.is_checked;

  v_difference := v_rec.statement_end_balance - (v_rec.statement_start_balance + v_checked_in - v_checked_out);

  update public.finance_reconciliations
  set system_end_balance = v_rec.statement_start_balance + v_checked_in - v_checked_out,
      difference = v_difference
  where id = v_rec.id
  returning * into v_rec;

  return jsonb_build_object('item', to_jsonb(v_item), 'reconciliation', to_jsonb(v_rec));
end;
$$;


ALTER FUNCTION "public"."update_finance_reconciliation_item"("p_item_id" "uuid", "p_is_checked" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_finance_reconciliation_statement"("p_reconciliation_id" "uuid", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rec public.finance_reconciliations;
begin
  if not public.can_reconcile_finance() then
    raise exception 'No tienes permiso para conciliar.';
  end if;

  update public.finance_reconciliations
  set
    statement_start_balance = coalesce((p_data ->> 'statement_start_balance')::numeric, statement_start_balance),
    statement_end_balance = coalesce((p_data ->> 'statement_end_balance')::numeric, statement_end_balance)
  where id = p_reconciliation_id and status = 'draft'
  returning * into v_rec;

  if not found then raise exception 'Conciliación no encontrada o cerrada.'; end if;

  return to_jsonb(v_rec);
end;
$$;


ALTER FUNCTION "public"."update_finance_reconciliation_statement"("p_reconciliation_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_station"("p_station_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_area_id" "text" DEFAULT NULL::"text", "p_pos_floor_zone" "text" DEFAULT NULL::"text") RETURNS "public"."operational_stations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.operational_stations;
begin
  if not public.is_operational_stations_admin() then
    raise exception 'No autorizado.';
  end if;
  update public.operational_stations
  set
    name = coalesce(nullif(trim(p_name), ''), name),
    status = coalesce(nullif(trim(p_status), ''), status),
    area_id = coalesce(nullif(trim(p_area_id), ''), area_id),
    pos_floor_zone = coalesce(nullif(trim(p_pos_floor_zone), ''), pos_floor_zone),
    updated_at = now(),
    disabled_at = case when coalesce(p_status, status) in ('inactive', 'revoked') then now() else disabled_at end,
    disabled_by = case when coalesce(p_status, status) in ('inactive', 'revoked') then auth.uid() else disabled_by end
  where id = p_station_id
  returning * into v_row;
  if v_row.id is null then
    raise exception 'Estacion no encontrada.';
  end if;
  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_operational_station"("p_station_id" "uuid", "p_name" "text", "p_status" "text", "p_area_id" "text", "p_pos_floor_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_task"("p_task_id" "text", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_title text;
  v_description text;
  v_objective text;
  v_expected_result text;
  v_priority text;
  v_area_id text;
  v_category text;
  v_due_at timestamptz;
  v_planned_start timestamptz;
  v_waiting_unblock text;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id and t.task_source = 'operational'
    and t.deleted_at is null and t.archived_at is null
  for update;

  if not found then raise exception 'Tarea no encontrada.'; end if;
  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para editar esta tarea.';
  end if;
  if v_task.status in ('completed', 'cancelled') then
    raise exception 'No puedes editar una tarea cerrada.';
  end if;

  v_title := coalesce(nullif(trim(p_data ->> 'title'), ''), v_task.title);
  v_description := coalesce(p_data ->> 'description', v_task.description);
  v_objective := coalesce(p_data ->> 'objective', v_task.objective);
  v_expected_result := coalesce(p_data ->> 'expected_result', v_task.expected_result);
  v_priority := coalesce(nullif(trim(p_data ->> 'priority'), ''), v_task.priority);
  v_area_id := case when p_data ? 'area_id' then nullif(trim(p_data ->> 'area_id'), '') else v_task.area_id end;
  v_category := case when p_data ? 'category' then nullif(trim(p_data ->> 'category'), '') else v_task.category end;
  v_due_at := case when p_data ? 'due_at' then nullif(p_data ->> 'due_at', '')::timestamptz else v_task.due_at end;
  v_planned_start := case when p_data ? 'planned_start_at' then nullif(p_data ->> 'planned_start_at', '')::timestamptz else v_task.planned_start_at end;
  v_waiting_unblock := case when p_data ? 'waiting_unblock_note' then nullif(trim(p_data ->> 'waiting_unblock_note'), '') else v_task.waiting_unblock_note end;

  if v_priority not in ('low', 'medium', 'high', 'critical') then
    raise exception 'Prioridad inválida.';
  end if;

  update public.assigned_tasks
  set title = v_title,
      description = coalesce(v_description, ''),
      objective = coalesce(v_objective, ''),
      expected_result = coalesce(v_expected_result, ''),
      priority = v_priority,
      area_id = v_area_id,
      category = v_category,
      due_at = v_due_at,
      due_date = case when v_due_at is null then null else v_due_at::date end,
      planned_start_at = v_planned_start,
      waiting_unblock_note = v_waiting_unblock,
      updated_at = now()
  where id = p_task_id returning * into v_task;

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."update_operational_task"("p_task_id" "text", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_task_assignees"("p_task_id" "text", "p_assignee_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[];
  v_primary uuid;
begin
  select coalesce(array_agg(distinct value order by value), '{}'::uuid[])
  into v_ids
  from unnest(coalesce(p_assignee_ids, '{}'::uuid[])) as value
  where value is not null;

  if coalesce(array_length(v_ids, 1), 0) = 0 then
    raise exception 'Debes asignar al menos un colaborador.';
  end if;

  v_primary := v_ids[1];

  return public.update_operational_task_members(
    p_task_id,
    v_primary,
    v_ids[2:array_length(v_ids, 1)],
    null
  );
end;
$$;


ALTER FUNCTION "public"."update_operational_task_assignees"("p_task_id" "text", "p_assignee_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_task_labels"("p_task_id" "text", "p_label_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_old_ids uuid[];
  v_new_ids uuid[];
  v_label uuid;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null
  for update;

  if not found then raise exception 'Tarea no encontrada.'; end if;
  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para editar etiquetas.';
  end if;

  select coalesce(array_agg(tla.label_id order by tla.label_id), '{}'::uuid[])
  into v_old_ids
  from public.task_label_assignments tla
  where tla.task_id = p_task_id;

  select coalesce(array_agg(distinct value order by value), '{}'::uuid[])
  into v_new_ids
  from unnest(coalesce(p_label_ids, '{}'::uuid[])) as value
  where value is not null;

  foreach v_label in array v_new_ids loop
    if not exists (
      select 1 from public.task_labels l
      where l.id = v_label
        and l.deleted_at is null
        and l.archived_at is null
    ) then
      raise exception 'Etiqueta inválida.';
    end if;
  end loop;

  delete from public.task_label_assignments tla
  where tla.task_id = p_task_id
    and not (tla.label_id = any(v_new_ids));

  insert into public.task_label_assignments (task_id, label_id, assigned_by)
  select p_task_id, label_id, auth.uid()
  from unnest(v_new_ids) as label_id
  on conflict (task_id, label_id) do nothing;

  if v_old_ids is distinct from v_new_ids then
    perform public.log_task_activity(
      p_task_id,
      'labels_updated',
      'labels',
      to_jsonb(v_old_ids),
      to_jsonb(v_new_ids),
      '{}'::jsonb
    );
  end if;

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."update_operational_task_labels"("p_task_id" "text", "p_label_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_task_members"("p_task_id" "text", "p_primary_profile_id" "uuid", "p_participant_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_watcher_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_assignee uuid;
  v_primary uuid;
  v_participants uuid[];
  v_all_assignees uuid[];
  v_old_assignees uuid[];
  v_old_watchers uuid[];
  v_final_watchers uuid[];
  v_actor_name text;
  v_title text;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if p_task_id is null or trim(p_task_id) = '' then
    raise exception 'p_task_id es obligatorio.';
  end if;

  if p_primary_profile_id is null then
    raise exception 'Debes asignar un responsable principal.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
  for update;

  if not found then
    raise exception 'Tarea no encontrada.';
  end if;

  if v_task.status in ('completed', 'cancelled') then
    raise exception 'No puedes cambiar miembros en una tarea cerrada.';
  end if;

  if not public.can_access_operational_task(v_task, 'view') then
    raise exception 'No tienes permiso para ver esta tarea.';
  end if;

  select coalesce(array_agg(ta.profile_id order by ta.profile_id), '{}'::uuid[])
  into v_old_assignees
  from public.task_assignees ta
  where ta.task_id = p_task_id and ta.status = 'active';

  select coalesce(array_agg(tw.profile_id order by tw.profile_id), '{}'::uuid[])
  into v_old_watchers
  from public.task_watchers tw
  where tw.task_id = p_task_id;

  if public.can_manage_operational_task_members(v_task) then
    select coalesce(array_agg(distinct value order by value), '{}'::uuid[])
    into v_participants
    from unnest(coalesce(p_participant_ids, '{}'::uuid[])) as value
    where value is not null
      and value <> p_primary_profile_id;

    v_all_assignees := array[p_primary_profile_id] || v_participants;

    foreach v_assignee in array v_all_assignees loop
      if not public.can_assign_profile_to_operational_task(v_assignee) then
        raise exception 'No tienes permiso para asignar a uno de los colaboradores.';
      end if;
    end loop;

    v_primary := p_primary_profile_id;

    update public.task_assignees
    set status = 'transferred',
        unassigned_at = now(),
        unassigned_by = auth.uid(),
        unassign_reason = 'reassigned'
    where task_id = p_task_id
      and status = 'active'
      and not (profile_id = any(v_all_assignees));

    foreach v_assignee in array v_all_assignees loop
      if exists (
        select 1 from public.task_assignees ta
        where ta.task_id = p_task_id and ta.profile_id = v_assignee and ta.status = 'active'
      ) then
        update public.task_assignees
        set assignment_role = case when v_assignee = v_primary then 'primary' else 'participant' end,
            assigned_by = auth.uid()
        where task_id = p_task_id and profile_id = v_assignee and status = 'active';
      elsif exists (
        select 1 from public.task_assignees ta
        where ta.task_id = p_task_id and ta.profile_id = v_assignee
      ) then
        update public.task_assignees
        set status = 'active',
            assignment_role = case when v_assignee = v_primary then 'primary' else 'participant' end,
            assigned_by = auth.uid(),
            assigned_at = now(),
            unassigned_at = null,
            unassigned_by = null,
            unassign_reason = null
        where task_id = p_task_id and profile_id = v_assignee;
      else
        insert into public.task_assignees (task_id, profile_id, assignment_role, assigned_by)
        values (
          p_task_id,
          v_assignee,
          case when v_assignee = v_primary then 'primary' else 'participant' end,
          auth.uid()
        );
      end if;
    end loop;

    update public.task_assignees
    set assignment_role = 'participant'
    where task_id = p_task_id
      and status = 'active'
      and profile_id <> v_primary
      and assignment_role = 'primary';

    perform public.sync_assigned_tasks_profile_ids(p_task_id);
    perform public.log_task_activity(
      p_task_id, 'assignees_updated', 'assignees', to_jsonb(v_old_assignees), to_jsonb(v_all_assignees), '{}'::jsonb
    );
  else
    v_all_assignees := v_old_assignees;
  end if;

  perform public.ensure_operational_task_assignee_watchers(p_task_id);

  if p_watcher_ids is null then
    select coalesce(array_agg(tw.profile_id order by tw.profile_id), '{}'::uuid[])
    into v_final_watchers
    from public.task_watchers tw
    where tw.task_id = p_task_id;
  else
    select coalesce(array_agg(distinct value order by value), '{}'::uuid[])
    into v_final_watchers
    from (
      select unnest(v_all_assignees) as value
      union
      select unnest(p_watcher_ids) as value
    ) s
    where value is not null;

    if public.can_manage_operational_task_watchers(v_task) then
      insert into public.task_watchers (task_id, profile_id, created_by)
      select p_task_id, w, auth.uid()
      from unnest(v_final_watchers) as w
      on conflict (task_id, profile_id) do nothing;

      delete from public.task_watchers tw
      where tw.task_id = p_task_id
        and not (tw.profile_id = any(v_final_watchers))
        and not exists (
          select 1 from public.task_assignees ta
          where ta.task_id = p_task_id
            and ta.profile_id = tw.profile_id
            and ta.status = 'active'
        );
    else
      if auth.uid() = any(p_watcher_ids) and not public.is_operational_task_watcher(p_task_id, auth.uid()) then
        insert into public.task_watchers (task_id, profile_id, created_by)
        values (p_task_id, auth.uid(), auth.uid())
        on conflict (task_id, profile_id) do nothing;
        perform public.log_task_activity(p_task_id, 'watcher_added', 'watchers', null, to_jsonb(auth.uid()), '{}'::jsonb);
      elsif not (auth.uid() = any(p_watcher_ids)) and public.is_operational_task_watcher(p_task_id, auth.uid()) then
        delete from public.task_watchers tw
        where tw.task_id = p_task_id
          and tw.profile_id = auth.uid()
          and not exists (
            select 1 from public.task_assignees ta
            where ta.task_id = p_task_id
              and ta.profile_id = tw.profile_id
              and ta.status = 'active'
          );
        perform public.log_task_activity(p_task_id, 'watcher_removed', 'watchers', to_jsonb(auth.uid()), null, '{}'::jsonb);
      elsif p_watcher_ids <> v_old_watchers then
        raise exception 'No tienes permiso para cambiar seguidores.';
      end if;

      select coalesce(array_agg(tw.profile_id order by tw.profile_id), '{}'::uuid[])
      into v_final_watchers
      from public.task_watchers tw
      where tw.task_id = p_task_id;
    end if;
  end if;

  if public.can_manage_operational_task_watchers(v_task)
    and p_watcher_ids is not null
    and v_final_watchers <> v_old_watchers then
    perform public.log_task_activity(
      p_task_id, 'watchers_updated', 'watchers', to_jsonb(v_old_watchers), to_jsonb(v_final_watchers), '{}'::jsonb
    );
  end if;

  select coalesce(p.full_name, 'Sistema'), v_task.title
  into v_actor_name, v_title
  from public.profiles p
  where p.id = auth.uid();

  foreach v_assignee in array v_all_assignees loop
    if not (v_assignee = any(v_old_assignees)) then
      perform public.notify_operational_task_event(
        v_assignee,
        'task_assigned',
        'Nueva tarea asignada: ' || v_title,
        v_actor_name || ' te asignó la tarea «' || v_title || '».',
        p_task_id
      );
    end if;
  end loop;

  foreach v_assignee in array v_old_assignees loop
    if not (v_assignee = any(v_all_assignees)) then
      perform public.notify_operational_task_event(
        v_assignee,
        'task_member_removed',
        'Cambio en tarea: ' || v_title,
        v_actor_name || ' te retiró de la tarea «' || v_title || '».',
        p_task_id
      );
    end if;
  end loop;

  foreach v_assignee in array v_final_watchers loop
    if not (v_assignee = any(v_old_watchers))
      and not (v_assignee = any(v_all_assignees)) then
      perform public.notify_operational_task_event(
        v_assignee,
        'task_watcher_added',
        'Seguimiento de tarea: ' || v_title,
        v_actor_name || ' te añadió como seguidor de «' || v_title || '».',
        p_task_id
      );
    end if;
  end loop;

  select * into v_task from public.assigned_tasks where id = p_task_id;

  return public.operational_task_row(v_task)
    || jsonb_build_object('permissions', public.get_operational_task_permissions(v_task));
end;
$$;


ALTER FUNCTION "public"."update_operational_task_members"("p_task_id" "text", "p_primary_profile_id" "uuid", "p_participant_ids" "uuid"[], "p_watcher_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_task_status"("p_task_id" "text", "p_status" "text", "p_waiting_reason" "text" DEFAULT NULL::"text", "p_next_action" "text" DEFAULT NULL::"text", "p_cancel_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_status text := trim(coalesce(p_status, ''));
  v_old_status text;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if v_status = '' then
    raise exception 'El estado es obligatorio.';
  end if;

  if v_status not in ('pending', 'in_progress', 'waiting', 'in_review', 'completed', 'cancelled') then
    raise exception 'Estado inválido.';
  end if;

  select *
  into v_task
  from public.assigned_tasks t
  where t.id = p_task_id
    and t.task_source = 'operational'
    and t.deleted_at is null
    and t.archived_at is null
  for update;

  if not found then
    raise exception 'Tarea no encontrada.';
  end if;

  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para actualizar esta tarea.';
  end if;

  v_old_status := v_task.status;

  if v_status = 'waiting' and coalesce(trim(p_waiting_reason), '') = '' then
    raise exception 'Indica el motivo de espera.';
  end if;

  if v_status = 'cancelled' and coalesce(trim(p_cancel_reason), '') = '' then
    if not public.is_operational_task_area_manager() then
      raise exception 'Indica el motivo de cancelación.';
    end if;
  end if;

  update public.assigned_tasks
  set
    status = v_status,
    waiting_reason = case when v_status = 'waiting' then p_waiting_reason else null end,
    next_action = case when v_status = 'waiting' then nullif(trim(coalesce(p_next_action, '')), '') else next_action end,
    started_at = case
      when v_status = 'in_progress' and started_at is null then now()
      else started_at
    end,
    completed_at = case
      when v_status = 'completed' then now()
      when v_status in ('pending', 'in_progress', 'waiting', 'in_review') then null
      else completed_at
    end,
    cancelled_at = case when v_status = 'cancelled' then now() else cancelled_at end,
    cancelled_by = case when v_status = 'cancelled' then auth.uid() else cancelled_by end,
    cancel_reason = case when v_status = 'cancelled' then nullif(trim(coalesce(p_cancel_reason, '')), '') else cancel_reason end,
    updated_at = now()
  where id = p_task_id
  returning * into v_task;

  perform public.log_task_activity(
    p_task_id,
    'status_changed',
    'status',
    to_jsonb(v_old_status),
    to_jsonb(v_status),
    jsonb_build_object(
      'waiting_reason', p_waiting_reason,
      'next_action', p_next_action,
      'cancel_reason', p_cancel_reason
    )
  );

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."update_operational_task_status"("p_task_id" "text", "p_status" "text", "p_waiting_reason" "text", "p_next_action" "text", "p_cancel_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_operational_task_status"("p_task_id" "text", "p_status" "text", "p_waiting_reason" "text" DEFAULT NULL::"text", "p_next_action" "text" DEFAULT NULL::"text", "p_cancel_reason" "text" DEFAULT NULL::"text", "p_waiting_unblock_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
  v_status text := trim(coalesce(p_status, ''));
  v_old_status text;
  v_unblock text;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;
  if v_status = '' then raise exception 'El estado es obligatorio.'; end if;
  if v_status not in ('pending', 'in_progress', 'waiting', 'blocked', 'in_review', 'completed', 'cancelled') then
    raise exception 'Estado inválido.';
  end if;

  select * into v_task
  from public.assigned_tasks t
  where t.id = p_task_id and t.task_source = 'operational'
    and t.deleted_at is null and t.archived_at is null
  for update;

  if not found then raise exception 'Tarea no encontrada.'; end if;
  if not public.can_mutate_operational_task(v_task) then
    raise exception 'No tienes permiso para actualizar esta tarea.';
  end if;

  v_old_status := v_task.status;
  v_unblock := coalesce(nullif(trim(p_waiting_unblock_note), ''), nullif(trim(p_next_action), ''));

  if v_status in ('waiting', 'blocked') and coalesce(trim(p_waiting_reason), '') = '' then
    raise exception 'Indica qué estamos esperando.';
  end if;

  if v_status = 'cancelled' and coalesce(trim(p_cancel_reason), '') = '' then
    if not public.is_operational_task_area_manager() then
      raise exception 'Indica el motivo de cancelación.';
    end if;
  end if;

  update public.assigned_tasks
  set status = v_status,
      waiting_reason = case when v_status in ('waiting', 'blocked') then p_waiting_reason else null end,
      waiting_unblock_note = case when v_status in ('waiting', 'blocked') then v_unblock else waiting_unblock_note end,
      waiting_since = case
        when v_status in ('waiting', 'blocked') and v_old_status not in ('waiting', 'blocked') then now()
        when v_status not in ('waiting', 'blocked') then null
        else waiting_since
      end,
      started_at = case when v_status = 'in_progress' and started_at is null then now() else started_at end,
      completed_at = case
        when v_status = 'completed' then now()
        when v_status in ('pending', 'in_progress', 'waiting', 'blocked', 'in_review') then null
        else completed_at
      end,
      cancelled_at = case when v_status = 'cancelled' then now() else cancelled_at end,
      cancelled_by = case when v_status = 'cancelled' then auth.uid() else cancelled_by end,
      cancel_reason = case when v_status = 'cancelled' then nullif(trim(coalesce(p_cancel_reason, '')), '') else cancel_reason end,
      updated_at = now()
  where id = p_task_id returning * into v_task;

  if v_old_status is distinct from v_status then
    perform public.log_task_activity(
      p_task_id, 'status_changed', 'status',
      to_jsonb(v_old_status), to_jsonb(v_status),
      jsonb_build_object('waiting_reason', p_waiting_reason, 'waiting_unblock_note', v_unblock)
    );
  end if;

  return public.operational_task_card_summary(v_task);
end;
$$;


ALTER FUNCTION "public"."update_operational_task_status"("p_task_id" "text", "p_status" "text", "p_waiting_reason" "text", "p_next_action" "text", "p_cancel_reason" "text", "p_waiting_unblock_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_recruitment_candidate_pipeline"("p_candidate_id" "uuid", "p_pipeline_status" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.recruitment_candidates;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para actualizar candidatos.';
  end if;

  update public.recruitment_candidates
  set
    pipeline_status = p_pipeline_status,
    internal_notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), internal_notes),
    updated_by = auth.uid()
  where id = p_candidate_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Candidato no encontrado.';
  end if;

  return jsonb_build_object('id', v_row.id, 'pipeline_status', v_row.pipeline_status);
end;
$$;


ALTER FUNCTION "public"."update_recruitment_candidate_pipeline"("p_candidate_id" "uuid", "p_pipeline_status" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_recruitment_interview_result"("p_interview_id" "uuid", "p_result" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_interview public.recruitment_interviews;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para actualizar entrevistas.';
  end if;

  update public.recruitment_interviews
  set
    result = p_result,
    notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
    updated_by = auth.uid()
  where id = p_interview_id
  returning * into v_interview;

  if v_interview.id is null then
    raise exception 'Entrevista no encontrada.';
  end if;

  if p_result = 'attended' then
    update public.recruitment_candidates
    set pipeline_status = 'interviewed', updated_by = auth.uid()
    where id = v_interview.candidate_id;
  elsif p_result = 'no_show' then
    update public.recruitment_candidates
    set
      discard_reason = 'no_show',
      discard_notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), discard_notes),
      pipeline_status = 'discarded',
      updated_by = auth.uid()
    where id = v_interview.candidate_id;
  end if;

  return to_jsonb(v_interview);
end;
$$;


ALTER FUNCTION "public"."update_recruitment_interview_result"("p_interview_id" "uuid", "p_result" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_recruitment_onboarding_task_status"("p_task_id" "uuid", "p_status" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.recruitment_onboarding_tasks;
  v_onboarding public.recruitment_onboarding_checklists;
  v_pending integer;
begin
  select * into v_task from public.recruitment_onboarding_tasks where id = p_task_id for update;
  if v_task.id is null then
    raise exception 'Tarea no encontrada.';
  end if;

  if not public.can_access_recruitment_onboarding_task(v_task) then
    raise exception 'No tienes permiso para actualizar esta tarea.';
  end if;

  update public.recruitment_onboarding_tasks
  set
    status = p_status,
    description = coalesce(nullif(trim(coalesce(p_notes, '')), ''), description),
    completed_at = case when p_status = 'completed' then now() else completed_at end,
    completed_by = case when p_status = 'completed' then auth.uid() else completed_by end,
    updated_at = now()
  where id = p_task_id
  returning * into v_task;

  select count(*) into v_pending
  from public.recruitment_onboarding_tasks t
  where t.onboarding_id = v_task.onboarding_id
    and t.status in ('pending', 'overdue');

  if v_pending = 0 then
    update public.recruitment_onboarding_checklists
    set status = 'completed', completed_at = now(), updated_at = now()
    where id = v_task.onboarding_id
    returning * into v_onboarding;

    update public.recruitment_candidates
    set onboarding_status = 'onboarding_completed', updated_at = now()
    where id = v_onboarding.candidate_id;
  end if;

  return to_jsonb(v_task);
end;
$$;


ALTER FUNCTION "public"."update_recruitment_onboarding_task_status"("p_task_id" "uuid", "p_status" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_station_pos_order"("p_operator_session_token" "text", "p_order_id" "uuid", "p_notes" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_order public.pos_orders;
  v_result jsonb;
  v_notes text;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_notes := nullif(left(trim(coalesce(p_notes, '')), 2000), '');

  v_fingerprint := public.station_pos_request_fingerprint(
    'update_order',
    jsonb_build_object('order_id', p_order_id, 'notes', coalesce(v_notes, ''))
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'update_order', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'update_order', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);
  v_order := public.station_pos_assert_order_open_for_drafts(p_order_id, v_operator_id);

  update public.pos_orders
  set notes = v_notes,
      updated_at = now()
  where id = p_order_id
  returning * into v_order;

  v_result := jsonb_build_object('order_id', p_order_id, 'notes', v_order.notes);

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'update_order', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."update_station_pos_order"("p_operator_session_token" "text", "p_order_id" "uuid", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_station_pos_order_item"("p_operator_session_token" "text", "p_order_id" "uuid", "p_item_id" "uuid", "p_quantity" numeric, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ctx jsonb;
  v_device_id uuid;
  v_station_id uuid;
  v_operator_id uuid;
  v_op_session_id uuid;
  v_actor_id uuid;
  v_fingerprint text;
  v_idem_key text;
  v_cached jsonb;
  v_item public.pos_order_items;
  v_qty numeric;
  v_result jsonb;
  v_generic constant text := 'Operacion no permitida.';
begin
  if auth.uid() is null then
    raise exception '%', v_generic;
  end if;

  v_qty := coalesce(p_quantity, 0);
  if v_qty <= 0 then
    raise exception 'Cantidad invalida.';
  end if;

  v_fingerprint := public.station_pos_request_fingerprint(
    'update_order_item',
    jsonb_build_object('order_id', p_order_id, 'item_id', p_item_id, 'quantity', v_qty)
  );
  v_idem_key := public.station_pos_resolve_idempotency_key(p_idempotency_key, v_fingerprint);

  v_cached := public.station_pos_idempotency_replay_if_completed(
    p_operator_session_token, 'update_order_item', v_idem_key, v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  v_ctx := public.resolve_station_pos_operator_context(p_operator_session_token, false);
  v_device_id := (v_ctx ->> 'device_id')::uuid;
  v_station_id := (v_ctx ->> 'station_id')::uuid;
  v_operator_id := (v_ctx ->> 'operator_profile_id')::uuid;
  v_op_session_id := (v_ctx ->> 'operator_session_id')::uuid;
  v_actor_id := v_operator_id;

  v_cached := public.station_pos_idempotency_begin(
    v_device_id, v_station_id, v_op_session_id, v_idem_key, 'update_order_item', v_fingerprint
  );
  if v_cached is not null then
    return v_cached;
  end if;

  perform public.station_pos_extend_operator_idle(v_op_session_id);
  perform public.station_pos_assert_order_open_for_drafts(p_order_id, v_operator_id);

  update public.pos_order_items i
  set quantity = v_qty,
      total_price = v_qty * i.unit_price
  where i.id = p_item_id
    and i.order_id = p_order_id
    and i.status = 'draft'
  returning * into v_item;

  if v_item.id is null then
    raise exception '%', v_generic;
  end if;

  v_result := jsonb_build_object(
    'item_id', v_item.id,
    'order_id', p_order_id,
    'quantity', v_item.quantity,
    'total_price', v_item.total_price
  );

  perform public.station_pos_record_audit(
    p_order_id, v_operator_id, v_actor_id, v_station_id, v_device_id, v_op_session_id,
    'update_order_item', v_fingerprint, v_result
  );
  perform public.station_pos_idempotency_complete(v_device_id, v_idem_key, v_result);
  return v_result;
exception
  when others then
    if sqlerrm in ('Cantidad invalida.', 'La orden POS no existe.') then
      raise;
    end if;
    if sqlerrm like 'Conflicto de idempotencia:%' or sqlerrm = 'Se requiere clave de idempotencia.' then
      raise;
    end if;
    raise exception '%', v_generic;
end;
$$;


ALTER FUNCTION "public"."update_station_pos_order_item"("p_operator_session_token" "text", "p_order_id" "uuid", "p_item_id" "uuid", "p_quantity" numeric, "p_idempotency_key" "text") OWNER TO "postgres";


