$$;


ALTER FUNCTION "public"."update_station_pos_order_item_notes"("p_operator_session_token" "text", "p_order_id" "uuid", "p_item_id" "uuid", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_task_label"("p_label_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_color_key" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.task_labels;
  v_name text;
begin
  if auth.uid() is null or not public.is_current_profile_active() then
    raise exception 'Sesión inválida o perfil inactivo.';
  end if;

  if not public.can_administer_task_labels() then
    raise exception 'No tienes permiso para editar etiquetas.';
  end if;

  select * into v_row
  from public.task_labels l
  where l.id = p_label_id
    and l.deleted_at is null
  for update;

  if not found then
    raise exception 'Etiqueta no encontrada.';
  end if;

  v_name := coalesce(nullif(trim(p_name), ''), v_row.name);

  if p_color_key is not null
    and p_color_key not in ('teal', 'blue', 'green', 'yellow', 'orange', 'red', 'purple', 'pink', 'slate') then
    raise exception 'Color de etiqueta inválido.';
  end if;

  if exists (
    select 1
    from public.task_labels l
    where l.deleted_at is null
      and l.id <> p_label_id
      and lower(l.name) = lower(v_name)
      and l.scope = v_row.scope
      and coalesce(l.area_id, '') = coalesce(v_row.area_id, '')
  ) then
    raise exception 'Ya existe una etiqueta con ese nombre.';
  end if;

  update public.task_labels l
  set
    name = v_name,
    color_key = coalesce(p_color_key, l.color_key),
    description = case
      when p_description is null then l.description
      else nullif(trim(p_description), '')
    end,
    updated_at = now()
  where l.id = p_label_id
  returning * into v_row;

  return jsonb_build_object(
    'label',
    jsonb_build_object(
      'id', v_row.id,
      'name', v_row.name,
      'color_key', v_row.color_key,
      'description', v_row.description,
      'scope', v_row.scope,
      'area_id', v_row.area_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."update_task_label"("p_label_id" "uuid", "p_name" "text", "p_color_key" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_task_step"("p_step_id" "uuid", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_step public.task_steps;
  v_dep uuid;
begin
  select * into v_step
  from public.task_steps s
  where s.id = p_step_id and s.deleted_at is null
  for update;

  if not found then raise exception 'Paso no encontrado.'; end if;
  perform public.assert_operational_task_mutable(v_step.task_id);

  if p_data ? 'depends_on_step_id' then
    v_dep := nullif(p_data ->> 'depends_on_step_id', '')::uuid;
    if v_dep is not null and public.task_step_has_dependency_cycle(p_step_id, v_dep) then
      raise exception 'La dependencia crearía un ciclo.';
    end if;
  end if;

  update public.task_steps
  set text = coalesce(nullif(trim(p_data ->> 'text'), ''), text),
      assigned_profile_id = case
        when p_data ? 'assigned_profile_id' then nullif(p_data ->> 'assigned_profile_id', '')::uuid
        else assigned_profile_id
      end,
      due_at = case
        when p_data ? 'due_at' then nullif(p_data ->> 'due_at', '')::timestamptz
        else due_at
      end,
      depends_on_step_id = case
        when p_data ? 'depends_on_step_id' then nullif(p_data ->> 'depends_on_step_id', '')::uuid
        else depends_on_step_id
      end,
      sort_position = case
        when p_data ? 'sort_position' then (p_data ->> 'sort_position')::numeric
        else sort_position
      end,
      updated_at = now()
  where id = p_step_id;

  if p_data ? 'assigned_profile_id' and nullif(p_data ->> 'assigned_profile_id', '')::uuid is not null then
    perform public.notify_operational_task_event(
      nullif(p_data ->> 'assigned_profile_id', '')::uuid,
      'task_step_assigned',
      'Paso asignado',
      'Te asignaron un paso en la tarea.',
      v_step.task_id
    );
  end if;

  return public.get_operational_task_detail(v_step.task_id);
end;
$$;


ALTER FUNCTION "public"."update_task_step"("p_step_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_role"("p_role_id" "uuid", "p_role_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_hr_assignable" boolean DEFAULT NULL::boolean) RETURNS "public"."user_roles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_role public.user_roles;
  updated_role public.user_roles;
  profile_count integer;
begin
  if not public.is_profile_manager() then
    raise exception 'Solo Administración puede editar roles del catálogo.';
  end if;

  select * into existing_role
  from public.user_roles
  where id = p_role_id;

  if existing_role.id is null then
    raise exception 'Rol no encontrado.';
  end if;

  if public.is_protected_role_key(existing_role.role_key) then
    raise exception 'Los roles admin y gerente_general no se pueden modificar.';
  end if;

  if p_is_active is not null and p_is_active = false and existing_role.is_active = true then
    select public.count_profiles_with_role(existing_role.role_key) into profile_count;
    if profile_count > 0 then
      raise exception 'Este rol está asignado a % colaboradores. Reasigna esos colaboradores antes de desactivarlo.', profile_count;
    end if;
  end if;

  update public.user_roles
  set
    role_name = coalesce(nullif(trim(p_role_name), ''), role_name),
    description = coalesce(p_description, description),
    is_active = coalesce(p_is_active, is_active),
    hr_assignable = case
      when public.is_protected_role_key(existing_role.role_key) then hr_assignable
      else coalesce(p_hr_assignable, hr_assignable)
    end,
    updated_at = now()
  where id = p_role_id
  returning * into updated_role;

  return updated_role;
end;
$$;


ALTER FUNCTION "public"."update_user_role"("p_role_id" "uuid", "p_role_name" "text", "p_description" "text", "p_is_active" boolean, "p_hr_assignable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_billing_provider_config"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_existing public.billing_provider_configs;
  v_row public.billing_provider_configs;
  v_legal_entity_id uuid;
  v_secret_env_var text;
begin
  if not public.can_manage_billing_settings() then
    raise exception 'No tienes permiso para modificar configuracion de proveedores.';
  end if;

  v_id := nullif(p_data ->> 'id', '')::uuid;

  v_legal_entity_id := coalesce(
    nullif(p_data ->> 'legal_entity_id', '')::uuid,
    public.get_default_billing_legal_entity_id()
  );

  if v_legal_entity_id is null then
    raise exception 'No existe entidad legal predeterminada.';
  end if;

  v_secret_env_var := coalesce(
    nullif(p_data ->> 'secret_env_var', ''),
    nullif(p_data ->> 'vault_secret_name', ''),
    case coalesce(p_data ->> 'environment', 'stage')
      when 'production' then 'FELPLEX_GT_PRODUCTION_API_KEY'
      else 'FELPLEX_GT_STAGE_API_KEY'
    end
  );

  if v_id is not null then
    select * into v_existing from public.billing_provider_configs where id = v_id;
    if v_existing.id is null then
      raise exception 'Configuracion de proveedor no encontrada.';
    end if;
  end if;

  if v_id is null then
    insert into public.billing_provider_configs (
      legal_entity_id, provider_code, environment, entity_id,
      secret_env_var, base_url, adapter_version,
      is_default, is_active, issuer_settings, updated_by
    ) values (
      v_legal_entity_id,
      coalesce(p_data ->> 'provider_code', 'felplex_gt'),
      coalesce(p_data ->> 'environment', 'stage'),
      coalesce(p_data ->> 'entity_id', ''),
      v_secret_env_var,
      nullif(p_data ->> 'base_url', ''),
      nullif(p_data ->> 'adapter_version', ''),
      coalesce((p_data ->> 'is_default')::boolean, false),
      coalesce((p_data ->> 'is_active')::boolean, true),
      coalesce(p_data -> 'issuer_settings', '{}'::jsonb),
      auth.uid()
    ) returning * into v_row;

    perform public.billing_log_config_change(
      'billing_provider_configs', v_row.id::text, '_record',
      null, to_jsonb(v_row), 'insert'
    );
  else
    update public.billing_provider_configs cfg
    set
      entity_id = coalesce(nullif(p_data ->> 'entity_id', ''), cfg.entity_id),
      secret_env_var = coalesce(nullif(p_data ->> 'secret_env_var', ''), nullif(p_data ->> 'vault_secret_name', ''), cfg.secret_env_var),
      base_url = coalesce(nullif(p_data ->> 'base_url', ''), cfg.base_url),
      adapter_version = coalesce(nullif(p_data ->> 'adapter_version', ''), cfg.adapter_version),
      is_default = coalesce((p_data ->> 'is_default')::boolean, cfg.is_default),
      is_active = coalesce((p_data ->> 'is_active')::boolean, cfg.is_active),
      issuer_settings = coalesce(p_data -> 'issuer_settings', cfg.issuer_settings),
      updated_by = auth.uid()
    where cfg.id = v_id
    returning * into v_row;

    if v_existing.entity_id is distinct from v_row.entity_id then
      perform public.billing_log_config_change(
        'billing_provider_configs', v_row.id::text, 'entity_id',
        to_jsonb(v_existing.entity_id), to_jsonb(v_row.entity_id), 'update'
      );
    end if;
    if v_existing.secret_env_var is distinct from v_row.secret_env_var then
      perform public.billing_log_config_change(
        'billing_provider_configs', v_row.id::text, 'secret_env_var',
        to_jsonb(v_existing.secret_env_var), to_jsonb(v_row.secret_env_var), 'update'
      );
    end if;
  end if;

  insert into public.billing_provider_status (
    provider_config_id, legal_entity_id, provider_code, adapter_version
  ) values (
    v_row.id, v_row.legal_entity_id, v_row.provider_code,
    coalesce(v_row.adapter_version, (select adapter_version from public.billing_providers where code = v_row.provider_code))
  )
  on conflict (provider_config_id) do nothing;

  return (
    select elem from jsonb_array_elements(public.list_billing_provider_configs()) elem
    where elem ->> 'id' = v_row.id::text
    limit 1
  );
end;
$$;


ALTER FUNCTION "public"."upsert_billing_provider_config"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_catering_quote_template"("p_template_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT 'general'::"text", "p_is_active" boolean DEFAULT true, "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_template public.catering_quote_templates;
  v_item jsonb;
  v_sort integer := 0;
begin
  if not public.can_manage_catering_requests() then
    raise exception 'No tienes permiso para guardar plantillas.';
  end if;

  if nullif(trim(coalesce(p_name, '')), '') is null then
    raise exception 'El nombre de la plantilla es obligatorio.';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'La plantilla debe incluir al menos una linea.';
  end if;

  if p_template_id is null then
    insert into public.catering_quote_templates (name, description, category, is_active, created_by)
    values (trim(p_name), nullif(trim(coalesce(p_description, '')), ''), coalesce(nullif(trim(p_category), ''), 'general'), coalesce(p_is_active, true), auth.uid())
    returning * into v_template;
  else
    update public.catering_quote_templates
    set
      name = trim(p_name),
      description = nullif(trim(coalesce(p_description, '')), ''),
      category = coalesce(nullif(trim(p_category), ''), 'general'),
      is_active = coalesce(p_is_active, true),
      updated_at = now()
    where id = p_template_id
    returning * into v_template;

    if not found then
      raise exception 'Plantilla no encontrada.';
    end if;

    delete from public.catering_quote_template_items where template_id = p_template_id;
  end if;

  for v_item in select value from jsonb_array_elements(p_items) as value loop
    v_sort := v_sort + 1;
    insert into public.catering_quote_template_items (
      template_id, item_type, description, quantity, quantity_unit, unit_price, sort_order
    )
    values (
      v_template.id,
      coalesce(nullif(trim(v_item ->> 'item_type'), ''), 'other'),
      trim(v_item ->> 'description'),
      coalesce(nullif(v_item ->> 'quantity', '')::numeric, 1),
      coalesce(nullif(trim(v_item ->> 'quantity_unit'), ''), 'unidades'),
      coalesce(nullif(v_item ->> 'unit_price', '')::numeric, 0),
      coalesce(nullif(v_item ->> 'sort_order', '')::integer, v_sort)
    );
  end loop;

  return public.catering_quote_template_detail(v_template.id);
end;
$$;


ALTER FUNCTION "public"."upsert_catering_quote_template"("p_template_id" "uuid", "p_name" "text", "p_description" "text", "p_category" "text", "p_is_active" boolean, "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_disciplinary_action"("p_profile_id" "uuid", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(trim(coalesce(p_data ->> 'id', '')), '')::uuid;
  v_incident_id uuid := nullif(trim(coalesce(p_data ->> 'incident_id', '')), '')::uuid;
  v_action_type text := lower(trim(coalesce(p_data ->> 'action_type', 'verbal_warning')));
  v_action public.employee_disciplinary_actions;
  v_duration integer;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para registrar acciones disciplinarias.';
  end if;

  if v_incident_id is not null then
    if not exists (
      select 1 from public.employee_incidents
      where id = v_incident_id and profile_id = p_profile_id
    ) then
      raise exception 'Incidente invalido para este colaborador.';
    end if;
  end if;

  v_duration := nullif(trim(coalesce(p_data ->> 'duration_days', '')), '')::integer;

  if v_id is not null then
    select * into v_action
    from public.employee_disciplinary_actions
    where id = v_id and profile_id = p_profile_id;

    if not found then
      raise exception 'Accion disciplinaria no encontrada.';
    end if;

    update public.employee_disciplinary_actions
    set
      title = coalesce(nullif(trim(p_data ->> 'title'), ''), title),
      description = coalesce(p_data ->> 'description', description),
      action_type = coalesce(nullif(v_action_type, ''), action_type),
      effective_date = coalesce((p_data ->> 'effective_date')::date, effective_date),
      end_date = coalesce((p_data ->> 'end_date')::date, end_date),
      duration_days = coalesce(v_duration, duration_days),
      status = coalesce(nullif(trim(p_data ->> 'status'), ''), status),
      document_storage_path = coalesce(p_data ->> 'document_storage_path', document_storage_path),
      document_file_name = coalesce(p_data ->> 'document_file_name', document_file_name),
      updated_at = now()
    where id = v_id
    returning * into v_action;

    return to_jsonb(v_action);
  end if;

  insert into public.employee_disciplinary_actions (
    profile_id, incident_id, action_type, title, description,
    effective_date, end_date, duration_days, status, issued_by,
    document_storage_path, document_file_name, is_permanent_record
  )
  values (
    p_profile_id,
    v_incident_id,
    v_action_type,
    coalesce(nullif(trim(p_data ->> 'title'), ''), 'Accion disciplinaria'),
    nullif(trim(coalesce(p_data ->> 'description', '')), ''),
    coalesce((p_data ->> 'effective_date')::date, current_date),
    (p_data ->> 'end_date')::date,
    v_duration,
    coalesce(nullif(trim(p_data ->> 'status'), ''), 'active'),
    auth.uid(),
    nullif(trim(coalesce(p_data ->> 'document_storage_path', '')), ''),
    nullif(trim(coalesce(p_data ->> 'document_file_name', '')), ''),
    true
  )
  returning * into v_action;

  return to_jsonb(v_action);
end;
$$;


ALTER FUNCTION "public"."upsert_disciplinary_action"("p_profile_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_file_profiles" (
    "profile_id" "uuid" NOT NULL,
    "dpi_number" "text",
    "nit_number" "text",
    "birth_date" "date",
    "address" "text",
    "personal_email" "text",
    "emergency_contact_name" "text",
    "emergency_contact_phone" "text",
    "job_title" "text",
    "hire_date" "date",
    "labor_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "employee_file_profiles_labor_status_check" CHECK (("labor_status" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'suspended'::"text", 'terminated'::"text"])))
);


ALTER TABLE "public"."employee_file_profiles" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_employee_expediente_profile"("p_profile_id" "uuid", "p_data" "jsonb") RETURNS "public"."employee_file_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.employee_file_profiles;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para editar expedientes.';
  end if;

  insert into public.employee_file_profiles (
    profile_id, dpi_number, nit_number, birth_date, address, personal_email,
    emergency_contact_name, emergency_contact_phone, job_title, hire_date,
    labor_status, notes, updated_by, updated_at
  )
  values (
    p_profile_id,
    nullif(trim(coalesce(p_data ->> 'dpi_number', '')), ''),
    nullif(trim(coalesce(p_data ->> 'nit_number', '')), ''),
    nullif(p_data ->> 'birth_date', '')::date,
    nullif(trim(coalesce(p_data ->> 'address', '')), ''),
    nullif(trim(coalesce(p_data ->> 'personal_email', '')), ''),
    nullif(trim(coalesce(p_data ->> 'emergency_contact_name', '')), ''),
    nullif(trim(coalesce(p_data ->> 'emergency_contact_phone', '')), ''),
    nullif(trim(coalesce(p_data ->> 'job_title', '')), ''),
    nullif(p_data ->> 'hire_date', '')::date,
    coalesce(nullif(trim(coalesce(p_data ->> 'labor_status', '')), ''), 'active'),
    nullif(trim(coalesce(p_data ->> 'notes', '')), ''),
    auth.uid(),
    now()
  )
  on conflict (profile_id) do update set
    dpi_number = excluded.dpi_number,
    nit_number = excluded.nit_number,
    birth_date = excluded.birth_date,
    address = excluded.address,
    personal_email = excluded.personal_email,
    emergency_contact_name = excluded.emergency_contact_name,
    emergency_contact_phone = excluded.emergency_contact_phone,
    job_title = excluded.job_title,
    hire_date = excluded.hire_date,
    labor_status = excluded.labor_status,
    notes = excluded.notes,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_employee_expediente_profile"("p_profile_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_employee_incident"("p_profile_id" "uuid", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(trim(coalesce(p_data ->> 'id', '')), '')::uuid;
  v_category text := lower(trim(coalesce(p_data ->> 'category', 'other')));
  v_incident public.employee_incidents;
  v_parent_id uuid;
  v_ref text;
begin
  if not public.can_write_employee_expedientes() then
    raise exception 'No tienes permiso para registrar incidentes.';
  end if;

  if not exists (select 1 from public.profiles where id = p_profile_id and status = 'active') then
    raise exception 'Colaborador no encontrado o inactivo.';
  end if;

  if v_id is not null then
    select * into v_incident
    from public.employee_incidents
    where id = v_id and profile_id = p_profile_id;

    if not found then
      raise exception 'Incidente no encontrado.';
    end if;

    if v_incident.status = 'closed' then
      raise exception 'No se puede editar un incidente cerrado.';
    end if;

    update public.employee_incidents
    set
      title = coalesce(nullif(trim(p_data ->> 'title'), ''), title),
      description = coalesce(p_data ->> 'description', description),
      category = coalesce(nullif(v_category, ''), category),
      severity = coalesce(nullif(trim(p_data ->> 'severity'), ''), severity),
      status = coalesce(nullif(trim(p_data ->> 'status'), ''), status),
      incident_date = coalesce((p_data ->> 'incident_date')::date, incident_date),
      location = coalesce(p_data ->> 'location', location),
      updated_at = now()
    where id = v_id
    returning * into v_incident;

    return to_jsonb(v_incident);
  end if;

  select i.id into v_parent_id
  from public.employee_incidents i
  where i.profile_id = p_profile_id
    and i.category = v_category
    and i.status = 'closed'
  order by i.closed_at desc nulls last, i.incident_date desc
  limit 1;

  v_ref := 'INC-' || to_char(current_date, 'YYYY') || '-'
    || lpad((
      select count(*) + 1
      from public.employee_incidents
      where profile_id = p_profile_id
        and extract(year from created_at) = extract(year from current_date)
    )::text, 4, '0');

  insert into public.employee_incidents (
    profile_id, reference_code, title, description, category, severity, status,
    incident_date, location, reported_by, parent_incident_id, is_recurrence
  )
  values (
    p_profile_id,
    v_ref,
    coalesce(nullif(trim(p_data ->> 'title'), ''), 'Incidente laboral'),
    nullif(trim(coalesce(p_data ->> 'description', '')), ''),
    v_category,
    coalesce(nullif(trim(p_data ->> 'severity'), ''), 'medium'),
    coalesce(nullif(trim(p_data ->> 'status'), ''), 'open'),
    coalesce((p_data ->> 'incident_date')::date, current_date),
    nullif(trim(coalesce(p_data ->> 'location', '')), ''),
    auth.uid(),
    v_parent_id,
    v_parent_id is not null
  )
  returning * into v_incident;

  return to_jsonb(v_incident);
end;
$$;


ALTER FUNCTION "public"."upsert_employee_incident"("p_profile_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_fixed_cost"("p_data" "jsonb") RETURNS "public"."fixed_costs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(trim(p_data ->> 'id'), '')::uuid;
  v_name text := nullif(trim(p_data ->> 'name'), '');
  v_category text := nullif(trim(p_data ->> 'category'), '');
  v_amount numeric(12, 2) := coalesce((p_data ->> 'amount')::numeric, 0);
  v_frequency text := coalesce(nullif(trim(p_data ->> 'frequency'), ''), 'monthly');
  v_cost_month date := public.normalize_fixed_cost_month((p_data ->> 'cost_month')::date);
  v_due_day integer := nullif(trim(p_data ->> 'due_day'), '')::integer;
  v_payment_status text := coalesce(nullif(trim(p_data ->> 'payment_status'), ''), 'pending');
  v_notes text := nullif(trim(p_data ->> 'notes'), '');
  v_is_active boolean := coalesce((p_data ->> 'is_active')::boolean, true);
  saved_row public.fixed_costs;
begin
  if not public.can_manage_fixed_costs() then
    raise exception 'No tienes permiso para gestionar costos fijos.';
  end if;

  if v_name is null then
    raise exception 'Falta el campo obligatorio: Nombre del costo.';
  end if;

  if v_category is null then
    raise exception 'Falta el campo obligatorio: Categoria.';
  end if;

  if v_amount < 0 then
    raise exception 'El monto no puede ser negativo.';
  end if;

  if v_due_day is not null and (v_due_day < 1 or v_due_day > 31) then
    raise exception 'El dia de pago debe estar entre 1 y 31.';
  end if;

  if v_id is null then
    insert into public.fixed_costs (
      name, category, amount, frequency, cost_month, due_day,
      payment_status, notes, is_active, created_by, updated_by
    )
    values (
      v_name, v_category, v_amount, v_frequency, v_cost_month, v_due_day,
      v_payment_status, v_notes, v_is_active, auth.uid(), auth.uid()
    )
    returning * into saved_row;
    return saved_row;
  end if;

  update public.fixed_costs
  set
    name = v_name,
    category = v_category,
    amount = v_amount,
    frequency = v_frequency,
    cost_month = v_cost_month,
    due_day = v_due_day,
    payment_status = v_payment_status,
    notes = v_notes,
    is_active = v_is_active,
    updated_by = auth.uid()
  where id = v_id
  returning * into saved_row;

  if saved_row.id is null then
    raise exception 'No se encontro el costo fijo a actualizar.';
  end if;

  return saved_row;
end;
$$;


ALTER FUNCTION "public"."upsert_fixed_cost"("p_data" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."inventory_yield_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "inventory_item_id" "uuid" NOT NULL,
    "expected_yield_percent" numeric DEFAULT 100 NOT NULL,
    "minimum_acceptable_yield_percent" numeric DEFAULT 90 NOT NULL,
    "historical_average_yield_percent" numeric,
    "notes" "text",
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "inventory_yield_profiles_expected_yield_percent_check" CHECK ((("expected_yield_percent" > (0)::numeric) AND ("expected_yield_percent" <= (100)::numeric))),
    CONSTRAINT "inventory_yield_profiles_historical_average_yield_percent_check" CHECK ((("historical_average_yield_percent" > (0)::numeric) AND ("historical_average_yield_percent" <= (100)::numeric))),
    CONSTRAINT "inventory_yield_profiles_minimum_acceptable_yield_percent_check" CHECK ((("minimum_acceptable_yield_percent" > (0)::numeric) AND ("minimum_acceptable_yield_percent" <= (100)::numeric)))
);


ALTER TABLE "public"."inventory_yield_profiles" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_inventory_yield_profile"("p_inventory_item_id" "uuid", "p_expected_yield_percent" numeric, "p_minimum_acceptable_yield_percent" numeric, "p_notes" "text", "p_active" boolean DEFAULT true) RETURNS "public"."inventory_yield_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved public.inventory_yield_profiles;
begin
  if not public.is_inventory_manager() and not public.is_profile_manager() then
    raise exception 'No tienes permiso para administrar rendimientos.';
  end if;
  if p_expected_yield_percent <= 0 or p_expected_yield_percent > 100 then
    raise exception 'El rendimiento esperado debe estar entre 0 y 100.';
  end if;
  if p_minimum_acceptable_yield_percent <= 0 or p_minimum_acceptable_yield_percent > 100 then
    raise exception 'El rendimiento minimo debe estar entre 0 y 100.';
  end if;

  insert into public.inventory_yield_profiles (
    inventory_item_id,
    expected_yield_percent,
    minimum_acceptable_yield_percent,
    notes,
    active
  ) values (
    p_inventory_item_id,
    p_expected_yield_percent,
    p_minimum_acceptable_yield_percent,
    nullif(trim(p_notes), ''),
    coalesce(p_active, true)
  )
  on conflict (inventory_item_id) do update set
    expected_yield_percent = excluded.expected_yield_percent,
    minimum_acceptable_yield_percent = excluded.minimum_acceptable_yield_percent,
    notes = excluded.notes,
    active = excluded.active,
    updated_at = now()
  returning * into saved;

  perform public.refresh_inventory_item_costing(p_inventory_item_id);
  return saved;
end;
$$;


ALTER FUNCTION "public"."upsert_inventory_yield_profile"("p_inventory_item_id" "uuid", "p_expected_yield_percent" numeric, "p_minimum_acceptable_yield_percent" numeric, "p_notes" "text", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_operational_process_template"("p_payload" "jsonb", "p_steps" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_id uuid;
  v_template public.operational_process_templates;
  v_step jsonb;
  v_sort integer := 0;
  v_step_id uuid;
  v_dep uuid;
  v_old_to_new jsonb := '{}'::jsonb;
  v_frequency text := coalesce(nullif(trim(p_payload ->> 'frequency_type'), ''), 'manual');
  v_recurrence_days integer[];
  v_recurrence_month_day integer;
begin
  if not public.is_operational_process_manager() then
    raise exception 'No tienes permiso para administrar procesos operativos.';
  end if;

  if v_frequency not in ('manual', 'daily', 'weekly', 'monthly') then
    raise exception 'frequency_type invalido.';
  end if;

  v_recurrence_days := coalesce(
    (
      select array_agg(value::integer order by value::integer)
      from jsonb_array_elements_text(coalesce(p_payload -> 'recurrence_days', '[]'::jsonb)) as value
      where value ~ '^[1-7]$'
    ),
    '{}'::integer[]
  );

  v_recurrence_month_day := nullif(trim(coalesce(p_payload ->> 'recurrence_month_day', '')), '')::integer;

  if v_frequency = 'weekly' and coalesce(array_length(v_recurrence_days, 1), 0) = 0 then
    raise exception 'Selecciona al menos un dia de la semana para frecuencia semanal.';
  end if;

  if v_frequency = 'monthly' and v_recurrence_month_day is null then
    v_recurrence_month_day := 1;
  end if;

  if v_frequency in ('manual', 'daily') then
    v_recurrence_days := '{}'::integer[];
    v_recurrence_month_day := null;
  elsif v_frequency = 'weekly' then
    v_recurrence_month_day := null;
  elsif v_frequency = 'monthly' then
    v_recurrence_days := '{}'::integer[];
  end if;

  v_id := nullif(trim(coalesce(p_payload ->> 'id', '')), '')::uuid;

  if v_id is null then
    insert into public.operational_process_templates (
      title, description, area, process_type, completion_mode,
      allow_parallel_execution, status, supervisor_profile_id,
      frequency_type, recurrence_days, recurrence_month_day,
      created_by
    )
    values (
      trim(p_payload ->> 'title'),
      nullif(trim(coalesce(p_payload ->> 'description', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'area', '')), ''),
      coalesce(nullif(trim(p_payload ->> 'process_type'), ''), 'checklist_bundle'),
      coalesce(nullif(trim(p_payload ->> 'completion_mode'), ''), 'all_required'),
      coalesce((p_payload ->> 'allow_parallel_execution')::boolean, true),
      coalesce(nullif(trim(p_payload ->> 'status'), ''), 'active'),
      nullif(trim(coalesce(p_payload ->> 'supervisor_profile_id', '')), '')::uuid,
      v_frequency,
      v_recurrence_days,
      v_recurrence_month_day,
      auth.uid()
    )
    returning * into v_template;
    v_id := v_template.id;
  else
    update public.operational_process_templates
    set
      title = trim(p_payload ->> 'title'),
      description = nullif(trim(coalesce(p_payload ->> 'description', '')), ''),
      area = nullif(trim(coalesce(p_payload ->> 'area', '')), ''),
      process_type = coalesce(nullif(trim(p_payload ->> 'process_type'), ''), 'checklist_bundle'),
      completion_mode = coalesce(nullif(trim(p_payload ->> 'completion_mode'), ''), 'all_required'),
      allow_parallel_execution = coalesce((p_payload ->> 'allow_parallel_execution')::boolean, allow_parallel_execution),
      status = coalesce(nullif(trim(p_payload ->> 'status'), ''), status),
      supervisor_profile_id = nullif(trim(coalesce(p_payload ->> 'supervisor_profile_id', '')), '')::uuid,
      frequency_type = v_frequency,
      recurrence_days = v_recurrence_days,
      recurrence_month_day = v_recurrence_month_day,
      updated_at = now()
    where id = v_id
    returning * into v_template;

    if v_template.id is null then
      raise exception 'Proceso operativo no encontrado.';
    end if;

    delete from public.operational_process_template_steps
    where process_template_id = v_id;
  end if;

  if p_steps is null or jsonb_typeof(p_steps) <> 'array' then
    raise exception 'p_steps debe ser un arreglo.';
  end if;

  for v_step in select value from jsonb_array_elements(p_steps) as value loop
    v_sort := v_sort + 1;
    insert into public.operational_process_template_steps (
      process_template_id, child_template_id, depends_on_step_id,
      step_order, step_label, assigned_profile_id, assigned_role, area,
      supervisor_profile_id, is_required
    )
    values (
      v_id,
      nullif(trim(v_step ->> 'child_template_id'), '')::uuid,
      null,
      coalesce(nullif(v_step ->> 'step_order', '')::integer, v_sort),
      trim(v_step ->> 'step_label'),
      nullif(trim(coalesce(v_step ->> 'assigned_profile_id', '')), '')::uuid,
      nullif(trim(coalesce(v_step ->> 'assigned_role', '')), ''),
      nullif(trim(coalesce(v_step ->> 'area', '')), ''),
      nullif(trim(coalesce(v_step ->> 'supervisor_profile_id', '')), '')::uuid,
      coalesce((v_step ->> 'is_required')::boolean, true)
    )
    returning id into v_step_id;

    v_old_to_new := v_old_to_new || jsonb_build_object(
      coalesce(nullif(trim(v_step ->> 'client_key'), ''), v_step_id::text),
      v_step_id
    );
  end loop;

  for v_step in select value from jsonb_array_elements(p_steps) as value loop
    v_dep := nullif(trim(coalesce(v_step ->> 'depends_on_client_key', '')), '');
    if v_dep is null then
      continue;
    end if;

    v_step_id := nullif(v_old_to_new ->> coalesce(nullif(trim(v_step ->> 'client_key'), ''), ''), '')::uuid;
    if v_step_id is null then
      continue;
    end if;

    update public.operational_process_template_steps s
    set depends_on_step_id = nullif(v_old_to_new ->> v_dep, '')::uuid,
        updated_at = now()
    where s.id = v_step_id
      and s.process_template_id = v_id;
  end loop;

  return public.get_operational_process_template_detail(v_id);
end;
$_$;


ALTER FUNCTION "public"."upsert_operational_process_template"("p_payload" "jsonb", "p_steps" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_pos_floor_table"("p_id" "text", "p_zone_id" "text", "p_name" "text", "p_capacity" integer DEFAULT 4, "p_shape" "text" DEFAULT 'square'::"text", "p_x" numeric DEFAULT 50, "p_y" numeric DEFAULT 50, "p_manual_status" "text" DEFAULT 'disponible'::"text", "p_sort_order" integer DEFAULT 0, "p_active" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  table_row public.pos_floor_tables;
begin
  if not public.can_manage_pos_floor_plan() then
    raise exception 'No tienes permiso para editar el plano del restaurante.';
  end if;

  if coalesce(trim(p_id), '') = '' or coalesce(trim(p_zone_id), '') = '' then
    raise exception 'El id de mesa y la zona son obligatorios.';
  end if;

  if coalesce(trim(p_name), '') = '' then
    raise exception 'El nombre de la mesa es obligatorio.';
  end if;

  if not exists (select 1 from public.pos_floor_zones where id = trim(p_zone_id)) then
    raise exception 'La zona fisica no existe.';
  end if;

  insert into public.pos_floor_tables (
    id, zone_id, name, capacity, shape, x, y, manual_status, sort_order, active, created_by, updated_by
  ) values (
    trim(p_id),
    trim(p_zone_id),
    trim(p_name),
    greatest(1, coalesce(p_capacity, 4)),
    coalesce(nullif(trim(p_shape), ''), 'square'),
    least(100, greatest(0, coalesce(p_x, 50))),
    least(100, greatest(0, coalesce(p_y, 50))),
    coalesce(nullif(trim(p_manual_status), ''), 'disponible'),
    coalesce(p_sort_order, 0),
    coalesce(p_active, true),
    auth.uid(),
    auth.uid()
  )
  on conflict (id) do update set
    zone_id = excluded.zone_id,
    name = excluded.name,
    capacity = excluded.capacity,
    shape = excluded.shape,
    x = excluded.x,
    y = excluded.y,
    manual_status = excluded.manual_status,
    sort_order = excluded.sort_order,
    active = excluded.active,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into table_row;

  return jsonb_build_object(
    'id', table_row.id,
    'areaId', table_row.zone_id,
    'name', table_row.name,
    'capacity', table_row.capacity,
    'shape', table_row.shape,
    'x', table_row.x,
    'y', table_row.y,
    'status', table_row.manual_status,
    'sortOrder', table_row.sort_order,
    'active', table_row.active
  );
end;
$$;


ALTER FUNCTION "public"."upsert_pos_floor_table"("p_id" "text", "p_zone_id" "text", "p_name" "text", "p_capacity" integer, "p_shape" "text", "p_x" numeric, "p_y" numeric, "p_manual_status" "text", "p_sort_order" integer, "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_pos_floor_zone"("p_id" "text", "p_name" "text", "p_description" "text" DEFAULT ''::"text", "p_sort_order" integer DEFAULT 0, "p_active" boolean DEFAULT true, "p_width" integer DEFAULT 900, "p_height" integer DEFAULT 520) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  zone_row public.pos_floor_zones;
begin
  if not public.can_manage_pos_floor_plan() then
