  end if;

  if coalesce(trim(p_id), '') = '' then
    raise exception 'El id de la zona es obligatorio.';
  end if;

  if coalesce(trim(p_name), '') = '' then
    raise exception 'El nombre de la zona es obligatorio.';
  end if;

