CREATE OR REPLACE FUNCTION "public"."upsert_recruitment_candidate"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_row public.recruitment_candidates;
begin
  if not public.can_manage_recruitment() then
    raise exception 'No tienes permiso para guardar candidatos.';
  end if;

  v_id := nullif(trim(coalesce(p_payload ->> 'id', '')), '')::uuid;

  if v_id is null then
    insert into public.recruitment_candidates (
      vacancy_id, full_name, phone, whatsapp, age, address, position_applied,
      source, prior_experience, schedule_availability, salary_expectation,
      pipeline_status, applied_at, notes, internal_notes, created_by, updated_by
    )
    values (
      nullif(trim(p_payload ->> 'vacancy_id'), '')::uuid,
      trim(p_payload ->> 'full_name'),
      nullif(trim(coalesce(p_payload ->> 'phone', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'whatsapp', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'age', '')), '')::integer,
      nullif(trim(coalesce(p_payload ->> 'address', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'position_applied', '')), ''),
      coalesce(nullif(trim(p_payload ->> 'source'), ''), 'other'),
      nullif(trim(coalesce(p_payload ->> 'prior_experience', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'schedule_availability', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'salary_expectation', '')), ''),
      coalesce(nullif(trim(p_payload ->> 'pipeline_status'), ''), 'applied'),
      coalesce(nullif(trim(coalesce(p_payload ->> 'applied_at', '')), '')::date, (now() at time zone 'America/Guatemala')::date),
      nullif(trim(coalesce(p_payload ->> 'notes', '')), ''),
      nullif(trim(coalesce(p_payload ->> 'internal_notes', '')), ''),
      auth.uid(),
      auth.uid()
    )
    returning * into v_row;
  else
    update public.recruitment_candidates
    set
      vacancy_id = coalesce(nullif(trim(p_payload ->> 'vacancy_id'), '')::uuid, vacancy_id),
      full_name = coalesce(nullif(trim(p_payload ->> 'full_name'), ''), full_name),
      phone = nullif(trim(coalesce(p_payload ->> 'phone', '')), ''),
      whatsapp = nullif(trim(coalesce(p_payload ->> 'whatsapp', '')), ''),
      age = nullif(trim(coalesce(p_payload ->> 'age', '')), '')::integer,
      address = nullif(trim(coalesce(p_payload ->> 'address', '')), ''),
      position_applied = nullif(trim(coalesce(p_payload ->> 'position_applied', '')), ''),
      source = coalesce(nullif(trim(p_payload ->> 'source'), ''), source),
      prior_experience = nullif(trim(coalesce(p_payload ->> 'prior_experience', '')), ''),
      schedule_availability = nullif(trim(coalesce(p_payload ->> 'schedule_availability', '')), ''),
      salary_expectation = nullif(trim(coalesce(p_payload ->> 'salary_expectation', '')), ''),
      notes = nullif(trim(coalesce(p_payload ->> 'notes', '')), ''),
      internal_notes = nullif(trim(coalesce(p_payload ->> 'internal_notes', '')), ''),
      updated_by = auth.uid()
    where id = v_id
    returning * into v_row;
  end if;

  return jsonb_build_object('id', v_row.id);
end;
$$;


ALTER FUNCTION "public"."upsert_recruitment_candidate"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_recruitment_vacancy"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_row public.recruitment_vacancies;
begin
  if not public.can_create_recruitment_vacancy() then
    raise exception 'No tienes permiso para guardar vacantes.';
  end if;

  v_id := nullif(trim(coalesce(p_payload ->> 'id', '')), '')::uuid;

  if v_id is null then
    insert into public.recruitment_vacancies (
      position_title, area, quantity_required, requested_by, request_date,
      target_date, priority, reason, status, notes, created_by, updated_by
    )
    values (
      trim(p_payload ->> 'position_title'),
      nullif(trim(coalesce(p_payload ->> 'area', '')), ''),
      greatest(coalesce((p_payload ->> 'quantity_required')::integer, 1), 1),
      coalesce(
        nullif(trim(coalesce(p_payload ->> 'requested_by', '')), '')::uuid,
        auth.uid()
      ),
      coalesce(nullif(trim(coalesce(p_payload ->> 'request_date', '')), '')::date, (now() at time zone 'America/Guatemala')::date),
      nullif(trim(coalesce(p_payload ->> 'target_date', '')), '')::date,
      coalesce(nullif(trim(p_payload ->> 'priority'), ''), 'medium'),
      coalesce(nullif(trim(p_payload ->> 'reason'), ''), 'replacement'),
      coalesce(nullif(trim(p_payload ->> 'status'), ''), 'open'),
      nullif(trim(coalesce(p_payload ->> 'notes', '')), ''),
      auth.uid(),
      auth.uid()
    )
    returning * into v_row;
  else
    if not public.can_manage_recruitment() then
      select * into v_row from public.recruitment_vacancies where id = v_id and requested_by = auth.uid();
      if v_row.id is null then
        raise exception 'No tienes permiso para editar esta vacante.';
      end if;
    end if;

    update public.recruitment_vacancies
    set
      position_title = trim(p_payload ->> 'position_title'),
      area = nullif(trim(coalesce(p_payload ->> 'area', '')), ''),
      quantity_required = greatest(coalesce((p_payload ->> 'quantity_required')::integer, quantity_required), 1),
      requested_by = coalesce(
        nullif(trim(coalesce(p_payload ->> 'requested_by', '')), '')::uuid,
        requested_by
      ),
      request_date = coalesce(nullif(trim(coalesce(p_payload ->> 'request_date', '')), '')::date, request_date),
      target_date = nullif(trim(coalesce(p_payload ->> 'target_date', '')), '')::date,
      priority = coalesce(nullif(trim(p_payload ->> 'priority'), ''), priority),
      reason = coalesce(nullif(trim(p_payload ->> 'reason'), ''), reason),
      status = coalesce(nullif(trim(p_payload ->> 'status'), ''), status),
      notes = nullif(trim(coalesce(p_payload ->> 'notes', '')), ''),
      updated_by = auth.uid()
    where id = v_id
    returning * into v_row;
  end if;

  return (select row from (
    select jsonb_build_object(
      'id', v_row.id,
      'position_title', v_row.position_title,
      'status', v_row.status
    ) as row
  ) q);
end;
$$;


ALTER FUNCTION "public"."upsert_recruitment_vacancy"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_task_recurrence"("p_task_id" "text", "p_frequency" "text" DEFAULT 'weekly'::"text", "p_interval_days" integer DEFAULT NULL::integer, "p_next_run_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_enabled" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_task public.assigned_tasks;
begin
  v_task := public.assert_operational_task_mutable(p_task_id);
  if not public.is_operational_task_area_manager() then
    raise exception 'Solo gerencia puede configurar recurrencia.';
  end if;

  insert into public.task_recurrence_rules (
    source_task_id, frequency, interval_days, next_run_at, enabled, created_by
  ) values (
    p_task_id,
    coalesce(nullif(trim(p_frequency), ''), 'weekly'),
    p_interval_days,
    p_next_run_at,
    coalesce(p_enabled, false),
    auth.uid()
  )
  on conflict (source_task_id) do update set
    frequency = excluded.frequency,
    interval_days = excluded.interval_days,
    next_run_at = excluded.next_run_at,
    enabled = excluded.enabled,
    updated_at = now();

  return public.get_operational_task_detail(p_task_id);
end;
$$;


ALTER FUNCTION "public"."upsert_task_recurrence"("p_task_id" "text", "p_frequency" "text", "p_interval_days" integer, "p_next_run_at" timestamp with time zone, "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_cash_movement_row"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.cash_sessions;
begin
  select * into session_row
  from public.cash_sessions
  where id = new.cash_session_id;

  if session_row.id is null then
    raise exception 'La sesion de caja no existe.';
  end if;
  if session_row.status <> 'open' and new.movement_type <> 'shift_close' then
    raise exception 'No se permiten movimientos en sesiones cerradas.';
  end if;
  if new.cash_register_id is distinct from session_row.cash_register_id then
    raise exception 'El movimiento no coincide con la caja de la sesion.';
  end if;

  if new.movement_type in ('withdrawal', 'deposit') and (new.amount <= 0 or nullif(trim(coalesce(new.reason, '')), '') is null) then
    raise exception 'Retiro e ingreso requieren monto positivo y motivo.';
  end if;
  if new.movement_type = 'manual_open' and nullif(trim(coalesce(new.reason, '')), '') is null then
    raise exception 'La apertura manual requiere motivo.';
  end if;
  if new.movement_type in ('sale_cash', 'refund') and new.amount <= 0 then
    raise exception 'El movimiento requiere monto positivo.';
  end if;
  if new.movement_type in ('shift_open', 'shift_close', 'manual_open') and new.amount < 0 then
    raise exception 'Este movimiento no puede tener monto negativo.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_cash_movement_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_operational_process_template_step_deps"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  dep_process uuid;
begin
  if new.depends_on_step_id is null then
    return new;
  end if;

  select process_template_id into dep_process
  from public.operational_process_template_steps
  where id = new.depends_on_step_id;

  if dep_process is null or dep_process <> new.process_template_id then
    raise exception 'depends_on_step_id must reference a step in the same process template.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_operational_process_template_step_deps"() OWNER TO "postgres";


