CREATE OR REPLACE FUNCTION "public"."validate_pos_product_readiness"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recipe public.standard_recipes;
  area public.areas;
  v_mode text := public.get_inventory_deduction_mode();
  v_implementation boolean := v_mode <> 'strict';
begin
  new.updated_at := now();
  new.production_ready := false;

  if not new.active then
    new.recipe_status := public.compute_pos_product_recipe_status(new.id);
    return new;
  end if;

  select * into area
  from public.areas
  where id = new.production_area_id
    and active = true
    and is_production_area = true;

  if area.id is null then
    raise exception 'El producto POS requiere un destino KDS activo.';
  end if;

  if new.is_test_item or new.product_type = 'manual_test' then
    new.recipe_id := null;
    new.production_ready := true;
    new.recipe_status := 'missing';
    return new;
  end if;

  if new.product_type = 'pizza' then
    new.recipe_id := null;
    if new.id is not null then
      new.recipe_status := coalesce(public.compute_pos_product_recipe_status(new.id), 'missing');
      new.production_ready := new.active
        and new.production_area_id is not null
        and exists (
          select 1
          from public.pos_product_variants variant
          where variant.product_id = new.id
            and variant.is_active = true
            and variant.price > 0
        );
    else
      new.recipe_status := 'missing';
      new.production_ready := false;
    end if;
    return new;
  end if;

  if new.product_type = 'configurable' then
    new.recipe_id := null;
    if new.id is not null then
      new.recipe_status := coalesce(public.compute_pos_product_recipe_status(new.id), 'missing');
      new.production_ready := new.active
        and new.production_area_id is not null
        and public.pos_configurable_catalog_is_valid(new.id);
    else
      new.recipe_status := 'missing';
      new.production_ready := false;
    end if;
    return new;
  end if;

  if v_implementation and not new.recipe_required_for_sale then
    new.production_ready := true;
    if new.id is not null then
      new.recipe_status := coalesce(public.compute_pos_product_recipe_status(new.id), 'missing');
    elsif new.recipe_id is null then
      new.recipe_status := 'missing';
    else
      select case
        when not recipe.active then 'paused'
        when not exists (select 1 from public.recipe_ingredients ri where ri.recipe_id = recipe.id) then 'draft'
        else 'active'
      end
      into new.recipe_status
      from public.standard_recipes recipe
      where recipe.id = new.recipe_id
        and recipe.recipe_type = 'final_product';
      new.recipe_status := coalesce(new.recipe_status, 'missing');
    end if;
    return new;
  end if;

  if new.recipe_id is null then
    raise exception 'Un producto POS activo debe tener receta.';
  end if;

  select * into recipe
  from public.standard_recipes
  where id = new.recipe_id
    and active = true
    and recipe_type = 'final_product';

  if recipe.id is null then
    raise exception 'El producto POS requiere una receta final activa.';
  end if;

  if recipe.production_area_id is distinct from new.production_area_id then
    raise exception 'El area del producto POS debe coincidir con el area de la receta.';
  end if;

  new.production_ready := true;
  new.recipe_status := 'active';
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_pos_product_readiness"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_pos_product_variant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  parent_product public.pos_products;
  recipe public.standard_recipes;
  v_requires_recipe boolean;
begin
  new.updated_at := now();

  select * into parent_product
  from public.pos_products
  where id = new.product_id;

  if parent_product.id is null then
    raise exception 'El producto padre de la variante no existe.';
  end if;

  if not new.is_active then
    return new;
  end if;

  if coalesce(new.price, 0) <= 0 then
    raise exception 'La variante activa debe tener precio de venta mayor que cero.';
  end if;

  v_requires_recipe := coalesce(parent_product.inventory_tracking_enabled, false)
    or coalesce(parent_product.recipe_required_for_sale, false);

  if v_requires_recipe and new.recipe_id is null then
    raise exception 'La variante activa debe tener una receta conectada porque el producto controla inventario.';
  end if;

  if new.recipe_id is null then
    new.production_area_id := parent_product.production_area_id;
    return new;
  end if;

  select * into recipe
  from public.standard_recipes
  where id = new.recipe_id
    and active = true
    and recipe_type = 'final_product';

  if recipe.id is null then
    raise exception 'La variante requiere una receta final activa.';
  end if;

  new.production_area_id := recipe.production_area_id;

  if parent_product.production_area_id is not null
     and parent_product.production_area_id is distinct from new.production_area_id then
    raise exception 'El area de la variante debe coincidir con el area configurada en el producto padre.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_pos_product_variant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_profile_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_role text;
  role_exists boolean;
begin
  -- Normalize the role for validation
  normalized_role := public.normalize_profile_role(new.role);
  
  -- Check if role exists and is active in user_roles
  select exists (
    select 1
    from public.user_roles
    where role_key = normalized_role and is_active = true
  ) into role_exists;
  
  if not role_exists then
    raise exception 'El rol "%" no existe o no está activo.', new.role;
  end if;
  
  -- Store the normalized role key
  new.role := normalized_role;
  
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_profile_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_role_exists"("p_role" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.user_roles
    where role_key = public.normalize_profile_role(p_role)
      and is_active = true
  );
$$;


