CREATE OR REPLACE VIEW "public"."billing_monitoring_document_counts" WITH ("security_invoker"='true') AS
 SELECT "legal_entity_id",
    "provider_code",
    "count"(*) FILTER (WHERE ("status" = 'pending_certification'::"text")) AS "pending_count",
    "count"(*) FILTER (WHERE ("status" = 'rejected'::"text")) AS "failed_count",
    "count"(*) FILTER (WHERE ("status" = 'certified'::"text")) AS "certified_count",
    "count"(*) FILTER (WHERE ("status" = ANY (ARRAY['void_pending'::"text", 'void_failed'::"text"]))) AS "void_issue_count",
    "round"("avg"(EXTRACT(epoch FROM ("certified_at" - "created_at"))) FILTER (WHERE ("status" = 'certified'::"text")), 2) AS "avg_certification_seconds"
   FROM "public"."billing_documents" "d"
  GROUP BY "legal_entity_id", "provider_code";


ALTER VIEW "public"."billing_monitoring_document_counts" OWNER TO "postgres";


